#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0       // No special flags

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Global variable for SPI handle
int spi_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value from MCP3008 channel 0
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            // Get current timestamp
            time_t current_time;
            struct tm *time_info;
            time(&current_time);
            time_info = localtime(&current_time);

            // Print timestamp and ADC value
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
            printf("%s ADC Value: %d\n", timestamp, adc_value);
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate
    // proper cleanup in case the loop is ever modified.
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

