#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define MLX91219_SENSITIVITY 0.1 // V/A (example value, check datasheet)
#define SLEEP_MS 500

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int ads1115_config(int handle, int config_value);
int ads1115_read_conversion(int handle, int16_t *value);
float convert_to_amperes(int16_t raw_value);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to configure the ADS1115
int ads1115_config(int handle, int config_value) {
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;        // LSB

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the conversion result from the ADS1115
int ads1115_read_conversion(int handle, int16_t *value) {
    char buf[1];
    buf[0] = CONVERSION_REG;

    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to conversion register: %d\n", result);
        return -1;
    }

    char data[2];
    result = i2cReadDevice(handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading conversion result: %d\n", result);
        return -1;
    }

    *value = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

// Function to convert the raw ADC value to amperes
float convert_to_amperes(int16_t raw_value) {
    // Assuming a single-ended input on AIN0 with a gain of ±4.096V
    // and a full-scale range of 6553.6 mA (6.5536 A)
    float voltage = (float)raw_value * 4.096 / 32768.0; // Convert to voltage
    float current = voltage / MLX91219_SENSITIVITY;      // Convert to amperes
    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115 for single-shot mode, single-ended AIN0, ±4.096V, 128 SPS
    int config_value = 0x4083; //0b0100000010000011
    if (ads1115_config(i2c_handle, config_value) != 0) {
        fprintf(stderr, "ADS1115 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        if (ads1115_read_conversion(i2c_handle, &raw_value) == 0) {
            float current = convert_to_amperes(raw_value);
            printf("Current: %.3f A\n", current);
        } else {
            fprintf(stderr, "Failed to read current\n");
        }

        gpioDelay(SLEEP_MS * 1000); // Sleep for 500 ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

