#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define ADC_CHANNEL 0
#define GPIO_PIN 18
#define CURRENT_THRESHOLD 5.0 // Amperes
#define LOG_FILE "current_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(const char *device, uint32_t speed, uint8_t mode, uint8_t bits_per_word);
int read_adc(int spi_fd, int channel);
float adc_to_current(int adc_value);
void control_fan(int gpio_pin, float current, float threshold);
void log_data(FILE *log_file, float current);
void signal_handler(int signal);

// SPI Initialization
int spi_init(const char *device, uint32_t speed, uint8_t mode, uint8_t bits_per_word) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    return fd;
}

// Read ADC value from MCP3008
int read_adc(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Convert ADC value to current (Amperes)
float adc_to_current(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // and a full-scale range of 0-10A for the MLX91219.
    // This is a simplified conversion and may need calibration.
    return (float)adc_value * (10.0 / 1023.0); // 1023 is 2^10 - 1 (10-bit ADC)
}

// Control the cooling fan based on current threshold
void control_fan(int gpio_pin, float current, float threshold) {
    if (current > threshold) {
        digitalWrite(gpio_pin, HIGH); // Turn fan ON
    } else {
        digitalWrite(gpio_pin, LOW);  // Turn fan OFF
    }
}

// Log data to file
void log_data(FILE *log_file, float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing WiringPi.\n");
        return 1;
    }

    // Set GPIO pin as output
    pinMode(GPIO_PIN, OUTPUT);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_SPEED, SPI_MODE, SPI_BITS_PER_WORD);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
            continue; // Skip to the next iteration
        }

        // Check for sensor-absent condition
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent (ADC value: %d).\n", adc_value);
            fprintf(log_file, "Sensor absent (ADC value: %d).\n", adc_value);
            fflush(log_file);
            delay(1000); // Wait before retrying
            continue;
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value);

        // Control the fan
        control_fan(GPIO_PIN, current, CURRENT_THRESHOLD);

        // Log the data
        log_data(log_file, current);

        // Wait for 1 second
        delay(1000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    digitalWrite(GPIO_PIN, LOW); // Turn fan OFF
    fclose(log_file);
    close(spi_fd);

    return 0;
}

