#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CS_PIN 8
#define SPI_SCLK_PIN 11
#define SPI_MOSI_PIN 10
#define SPI_MISO_PIN 9

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float adc_to_temperature(int adc_value);
void log_data(int flame_detected, float temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int baud;
    int flags;
} spi_config_t;

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT);

    // Initialize SPI
    spi_config_t spi_config = {SPI_CHANNEL, SPI_BAUD, 0};
    spi_handle = spiOpen(spi_config.channel, spi_config.baud, spi_config.flags);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flame_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,FlameDetected,Temperature\n");
    }
    rewind(log_file);

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS_PIN, 0); // Select MCP3008
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    gpioWrite(MCP3008_CS_PIN, 1); // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float adc_to_temperature(int adc_value) {
    // Simple linear conversion (example)
    return (float)adc_value * 0.1; // Adjust the scaling factor as needed
}

// Function to log data to CSV file
void log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Flame sensor and temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int flame_detected = read_flame_sensor();
        int adc_value = read_mcp3008(0);

        if (flame_detected == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading flame sensor\n");
        } else if (adc_value == -1) {
            fprintf(stderr, "Error reading MCP3008\n");
        } else {
            float temperature = adc_to_temperature(adc_value);
            log_data(flame_detected, temperature);
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

