#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define CO_LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"
#define CO_THRESHOLD 25.0
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
int16_t convert_to_ppm(int16_t adc_value);
int log_co_value(float co_ppm);
int check_alert(float co_ppm);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    int16_t ox;
    int16_t red;
} sensor_data_t;

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data from the I2C bus
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to convert ADC value to CO concentration in ppm
