    // Implement the conversion formula from the MICS-4514 datasheet here
    // This is a placeholder; replace with the actual formula
    return (int16_t)(adc_value * 0.1); // Example conversion
}

// Function to log CO value to a file
int log_co_value(float co_ppm) {
    FILE *fp = fopen(CO_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", CO_LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO: %.2f ppm\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

// Function to check for alert and log it
int check_alert(float co_ppm) {
    if (co_ppm >= CO_THRESHOLD) {
        FILE *fp = fopen(ALERT_LOG_FILE, "a");
        if (fp == NULL) {
            fprintf(stderr, "Failed to open alert log file: %s\n", ALERT_LOG_FILE);
            return -1;
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
