    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

