    level = gpioRead(gpio);

    if (level < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio);
        return -1; // Indicate an error
    }

    return level;
}

// Function to calculate the average sound pressure level
double calculate_average_level(int mic1_level, int mic2_level) {
    if (mic1_level == -1 || mic2_level == -1) {
        return -999.0; // Indicate an error
    }

    // Simple averaging (replace with actual dB calculation if needed)
    double average_level = (mic1_level + mic2_level) / 2.0;
    return average_level;
}

