    // Main loop
    while (program_running) {
        // Read the microphone levels
        int mic1_level = read_microphone(MIC1_GPIO);
        int mic2_level = read_microphone(MIC2_GPIO);

        // Calculate the average level
        double average_level = calculate_average_level(mic1_level, mic2_level);

        // Log the data
        log_data(average_level);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

