#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC1_CE 8
#define MIC2_CE 9
#define LED_PIN 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define RMS threshold
#define RMS_THRESHOLD 500

// Define sampling window
#define WINDOW_SIZE 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold audio data
typedef struct {
    int16_t mic1_data[WINDOW_SIZE];
    int16_t mic2_data[WINDOW_SIZE];
} AudioWindow;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
void process_audio(AudioWindow *window);
void calculate_rms(AudioWindow *window, float *mic1_rms, float *mic2_rms);
void log_data(float mic1_rms, float mic2_rms);
void control_led(float mic1_rms, float mic2_rms);
void signal_handler(int signal);

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MIC1_CE, PI_OUTPUT);
    gpioSetMode(MIC2_CE, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,mic1_rms,mic2_rms\n");
    }

    return 0;
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MIC1_CE, 0); // Select chip
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MIC1_CE, 1); // Deselect chip

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to process audio data (dummy implementation)
void process_audio(AudioWindow *window) {
    // In a real application, this function would perform more complex processing
    // such as filtering, feature extraction, or machine learning.
    // For this example, we simply store the raw ADC values.
}

// Function to calculate RMS level
void calculate_rms(AudioWindow *window, float *mic1_rms, float *mic2_rms) {
    double sum_mic1 = 0.0;
    double sum_mic2 = 0.0;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        sum_mic1 += (double)window->mic1_data[i] * window->mic1_data[i];
        sum_mic2 += (double)window->mic2_data[i] * window->mic2_data[i];
    }

    *mic1_rms = (float)sqrt(sum_mic1 / WINDOW_SIZE);
    *mic2_rms = (float)sqrt(sum_mic2 / WINDOW_SIZE);
}

// Function to log data to file
void log_data(float mic1_rms, float mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control the LED
void control_led(float mic1_rms, float mic2_rms) {
    if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
        gpioDelay(500);         // Wait for 500 ms
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    AudioWindow audio_window;

    // Main loop
    while (!terminate) {
        // Read audio data
        for (int i = 0; i < WINDOW_SIZE; i++) {
            int mic1_value = read_mcp3008(0);
            int mic2_value = read_mcp3008(1);

            if (mic1_value == -1 || mic2_value == -1) {
                fprintf(stderr, "Error reading ADC values\n");
                break; // Exit loop on error
            }

            audio_window.mic1_data[i] = (int16_t)mic1_value;
            audio_window.mic2_data[i] = (int16_t)mic2_value;
            gpioDelay(1); // 1 ms delay
        }

        // Calculate RMS levels
        float mic1_rms, mic2_rms;
        calculate_rms(&audio_window, &mic1_rms, &mic2_rms);

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Control LED
        control_led(mic1_rms, mic2_rms);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    fclose(log_file);

    return 0;
}

