#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define ADS1115_I2C_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define MLX91204_SENSITIVITY 0.1 // 100mV/A
#define LED_PIN 17
#define BUFFER_SIZE 100
#define THRESHOLD_CURRENT 50.0 // Amperes
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE_HZ)

// Global variables
int ads1115_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int ads1115_init();
int ads1115_read_raw(int *raw_value);
float raw_to_current(int raw_value);
void buffer_add(float current);
float buffer_average();
void led_on();
void led_off();
void signal_handler(int signal);

// Function to initialize the ADS1115 ADC
int ads1115_init() {
    ads1115_fd = wiringPiI2CSetup(ADS1115_I2C_ADDR);
    if (ads1115_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }

    // Configure ADS1115 for single-ended A0, 4.096V range, 1000 SPS
    // 0x4003 = 0b0100000000000011
    int config_value = 0x4003; // Single-ended A0, 4.096V, 1000 SPS
    if (wiringPiI2CWriteReg16(ads1115_fd, ADS1115_CONFIG_REG, config_value) == -1) {
        fprintf(stderr, "Error writing to config register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read a single sample from the ADS1115
int ads1115_read_raw(int *raw_value) {
    int16_t raw;

    // Read the conversion register
    raw = wiringPiI2CReadReg16(ads1115_fd, ADS1115_CONVERSION_REG);
    if (raw == -1) {
        fprintf(stderr, "Error reading conversion register: %s\n", strerror(errno));
        return -1;
    }

    // ADS1115 returns MSB first, so swap bytes
    raw = (raw >> 8) | (raw << 8);

    *raw_value = (int)raw;
    return 0;
}

// Function to convert raw ADC value to current
float raw_to_current(int raw_value) {
    // Assuming 16-bit ADC, 4.096V range
    float voltage = (float)raw_value * 4.096 / 32768.0;
    return voltage / MLX91204_SENSITIVITY;
}

// Function to add a current reading to the circular buffer
void buffer_add(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the average of the current readings in the buffer
float buffer_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to turn the LED on
void led_on() {
    digitalWrite(LED_PIN, HIGH);
}

// Function to turn the LED off
void led_off() {
    digitalWrite(LED_PIN, LOW);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the LED pin as output
    pinMode(LED_PIN, OUTPUT);
    led_off(); // Ensure LED is off at startup

    // Initialize the ADS1115 ADC
    if (ads1115_init() == -1) {
        fprintf(stderr, "ADS1115 initialization failed.\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    int raw_value;
    float current;
    float average_current;

    while (program_running) {
        // Read raw ADC value
        if (ads1115_read_raw(&raw_value) == -1) {
            fprintf(stderr, "Error reading raw value, retrying...\n");
            delay(100); // Wait before retrying
            continue;
        }

        // Convert raw value to current
        current = raw_to_current(raw_value);

        // Add current to the circular buffer
        buffer_add(current);

        // Calculate the average current
        average_current = buffer_average();

        // Check if the average current exceeds the threshold
        if (average_current > THRESHOLD_CURRENT) {
            led_on();
        } else {
            led_off();
        }

        printf("Current: %.2f A, Average: %.2f A\n", current, average_current);

        delay(SAMPLE_PERIOD_MS);
    }

    // Cleanup before exiting
    led_off();
    close(ads1115_fd);

    printf("Program finished.\n");
    return 0;
}

