#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Expected TCS34725 ID
#define TCS34725_ID 0x60

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int tcs34725_init();
int tcs34725_read_raw_data(unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue);
int tcs34725_get_clear(unsigned int *clear);
int tcs34725_get_red(unsigned int *red);
int tcs34725_get_green(unsigned int *green);
int tcs34725_get_blue(unsigned int *blue);
int log_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize the TCS34725 sensor
int tcs34725_init() {
    int retries = 3;
    int result;

    // Enable the sensor (power on and enable RGBC)
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03); // PON + AEN
        if (result == 0) break;
        fprintf(stderr, "Error writing to TCS34725_ENABLE: %d\n", result);
        retries--;
        gpioDelay(1000); // Wait 1ms
    }
    if (retries == 0) return -1;

    // Set integration time (ATIME) - 2.4ms
    retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xEB); // 2.4ms
        if (result == 0) break;
        fprintf(stderr, "Error writing to TCS34725_ATIME: %d\n", result);
        retries--;
        gpioDelay(1000); // Wait 1ms
    }
    if (retries == 0) return -1;

    // Set gain (AGAIN) - 60x
    retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x01); // 60x gain
        if (result == 0) break;
        fprintf(stderr, "Error writing to TCS34725_CONTROL: %d\n", result);
        retries--;
        gpioDelay(1000); // Wait 1ms
    }
    if (retries == 0) return -1;

    return 0;
}

// Read raw color data from the sensor
int tcs34725_read_raw_data(unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue) {
    char buffer[8];
    int result;

    // Read all color data in one go
    result = i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, buffer, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading color data: %d\n", result);
        return -1;
    }

    *clear = (buffer[1] << 8) | buffer[0];
    *red = (buffer[3] << 8) | buffer[2];
    *green = (buffer[5] << 8) | buffer[4];
    *blue = (buffer[7] << 8) | buffer[6];

    return 0;
}

// Get clear channel data
int tcs34725_get_clear(unsigned int *clear) {
    return tcs34725_read_raw_data(clear, NULL, NULL, NULL);
}

// Get red channel data
int tcs34725_get_red(unsigned int *red) {
    return tcs34725_read_raw_data(NULL, red, NULL, NULL);
}

// Get green channel data
int tcs34725_get_green(unsigned int *green) {
    return tcs34725_read_raw_data(NULL, NULL, green, NULL);
}

// Get blue channel data
int tcs34725_get_blue(unsigned int *blue) {
    return tcs34725_read_raw_data(NULL, NULL, NULL, blue);
}

// Log data to CSV file
int log_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    unsigned int clear, red, green, blue;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    char id;
    result = i2cReadI2CBlockData(i2c_handle, 0x12, &id, 1);
    if (result != 1 || id != TCS34725_ID) {
        fprintf(stderr, "Error: Invalid sensor ID (0x%02x)\n", id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (tcs34725_init() != 0) {
        fprintf(stderr, "Error initializing TCS34725 sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read color data
        if (tcs34725_read_raw_data(&clear, &red, &green, &blue) == 0) {
            // Log data
            log_data(clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading color data\n");
        }

        // Non-blocking sleep for 1 second
        struct timespec sleep_time;
        sleep_time.tv_sec = 1;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

