#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX90817_ADDR 0x60
#define PRESSURE_REG 0x00 // Example register address, check datasheet
#define LOG_FILE "pressure_log.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_pressure(int i2c_handle, float *pressure);
int log_pressure(FILE *log_file, float pressure);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int mlx90817_address;
    char *log_file_name;
} config_t;

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (kPa)\n");
    }
    rewind(log_file);

    return 0;
}

// Function to read pressure from the sensor
int read_pressure(int i2c_handle, float *pressure) {
    int retries = 0;
    int raw_pressure;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadWordData(i2c_handle, PRESSURE_REG);
        if (result >= 0) {
            raw_pressure = result; // Assuming little-endian
            // Convert raw pressure to kPa (example conversion, adjust based on datasheet)
            *pressure = (float)raw_pressure * 0.1; // Example conversion
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read pressure after %d retries\n", MAX_RETRIES);
    return 1; // Failure
}

// Function to log pressure data to a file
int log_pressure(FILE *log_file, float pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    float pressure;
    while (!terminate) {
        if (read_pressure(i2c_handle, &pressure) == 0) {
            if (log_pressure(log_file, pressure) != 0) {
                fprintf(stderr, "Failed to log pressure\n");
            }
        } else {
            fprintf(stderr, "Failed to read pressure\n");
        }

        gpioDelay(1000 * 1000); // 1 second delay
    }

    cleanup();
    return 0;
}

