#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define SHUNT_RESISTOR 0.001 // 1 mOhm
#define OVERCURRENT_THRESHOLD 10.0 // 10 A
#define GPIO_SHUTDOWN 27
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_current(int adc_value);
void log_current(float current);
void handle_overcurrent(float current);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float shunt_resistor;
    float overcurrent_threshold;
    int gpio_shutdown;
    char *log_file;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL,
    SHUNT_RESISTOR,
    OVERCURRENT_THRESHOLD,
    GPIO_SHUTDOWN,
    LOG_FILE
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        float current = adc_to_current(adc_value);
        log_current(current);

        if (current > config.overcurrent_threshold) {
            handle_overcurrent(current);
        }

        gpioDelay(100); // Sample every 100 ms
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO_SHUTDOWN as output
    gpioSetMode(config.gpio_shutdown, PI_OUTPUT);
    gpioWrite(config.gpio_shutdown, 0); // Initially LOW

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(config.gpio_shutdown, 0); // Ensure LOW
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 single-ended read)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

float adc_to_current(int adc_value) {
    // Convert ADC value to current using shunt resistor
    float voltage = (float)adc_value * (3.3 / 1023.0); // Assuming 3.3V reference
    float current = voltage / config.shunt_resistor;
    return current;
}

void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.3f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to file immediately
}

void handle_overcurrent(float current) {
    printf("OVERCURRENT: Current = %.3f A\n", current);
    fprintf(log_file, "OVERCURRENT: Current = %.3f A\n", current);
    fflush(log_file);

    gpioWrite(config.gpio_shutdown, 1); // Set GPIO_HIGH to shut down motor
    gpioDelay(1000); // Wait 1 second
    gpioWrite(config.gpio_shutdown, 0); // Set GPIO_LOW
    gpioDelay(1000); // Wait 1 second
    fprintf(log_file, "Motor restarted.\n");
    fflush(log_file);
}

