#include <string.h>
#include <unistd.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define MLX90830_CHANNEL 0
#define VREF 3.3 // ADC reference voltage
#define MAX_PRESSURE 100.0 // kPa
#define MIN_PRESSURE 0.0 // kPa
#define SAMPLE_RATE 1 // Hz
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    float vref;
    float max_pressure;
    float min_pressure;
    int sample_rate;
    char log_file[64];
} config_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_ads1115(int handle, int channel);
float convert_to_pressure(int raw_value, float vref);
int validate_pressure(float pressure, float min_pressure, float max_pressure);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read data from ADS1115 ADC
int read_ads1115(int handle, int channel) {
    // ADS1115 configuration register settings
    // Single-shot mode, AIN0, PGA = +/- 4.096V, Continuous conversion, 128 SPS
    uint16_t config = 0x4003; //0b0100000000000011

    // Write the configuration to the ADS1115
    char buf[3];
    buf[0] = 0x01; // Configuration register address
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF; // LSB

    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    char read_buf[2];
    buf[0] = 0x00; // Conversion register address
    if (i2cWriteDevice(handle, buf, 1) != 0) {
