    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];

    return raw_value;
}

// Convert raw ADC value to pressure (kPa)
float convert_to_pressure(int raw_value, float vref) {
    // Assuming a linear relationship between voltage and pressure
    // and that the sensor outputs 0V at 0 kPa and VREF at MAX_PRESSURE kPa
    float voltage = (float)raw_value / 32767.0 * vref; // Convert to voltage
    float pressure = (voltage / vref) * MAX_PRESSURE; // Convert to pressure
