#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with actual recipient

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3208(int channel);
float adc_to_humidity(int adc_value);
float adc_to_temperature(int adc_value);
int log_data(float humidity, float temperature);
int send_email_alert(float humidity);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    float humidity;
    float temperature;
} sensor_data_t;

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3208 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (12 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to humidity (HIH-4602-A datasheet)
float adc_to_humidity(int adc_value) {
    // HIH-4602-A datasheet formulas
    float humidity = (adc_value / 4095.0) * 100.0;
    return humidity;
}

// Function to convert ADC value to temperature (HIH-4602-A datasheet)
float adc_to_temperature(int adc_value) {
    // HIH-4602-A datasheet formulas
    float temperature = (adc_value / 4095.0) * 165.0 - 40.0;
    return temperature;
}

// Function to log data to a file
int log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
    return 0;
}

// Function to send an email alert
int send_email_alert(float humidity) {
    char command[256];
    snprintf(command, sizeof(command), "echo \"Subject: Humidity Alert\n\nHumidity exceeded threshold: %.2f%%\" | ssmtp %s", humidity, EMAIL_RECIPIENT);

    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Error sending email alert (exit code: %d)\n", result);
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int humidity_adc = read_mcp3208(0);
        int temperature_adc = read_mcp3208(1);

        if (humidity_adc < 0 || temperature_adc < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to humidity and temperature
        float humidity = adc_to_humidity(humidity_adc);
        float temperature = adc_to_temperature(temperature_adc);

        // Log data
        if (log_data(humidity, temperature) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Check humidity threshold and send email alert
        if (humidity > HUMIDITY_THRESHOLD) {
            if (send_email_alert(humidity) != 0) {
                fprintf(stderr, "Error sending email alert\n");
            }
        }

        // Wait for 5 seconds
        gpioDelay(5000); // pigpio's replacement for time_sleep
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

