#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define CE0 8
#define SCLK 11
#define MOSI 10
#define MISO 9

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define ADC channel
#define ADC_CHANNEL 0

// Define temperature range
#define MIN_TEMP -40.0
#define MAX_TEMP 125.0

// Define log file name
#define LOG_FILE "temperature_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float convert_to_celsius(int adc_value);
void log_temperature(float temperature);
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read ADC value from MCP3208
int read_adc(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int adc_value;

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value * 3.3) / 4096.0; // 12-bit ADC, 3.3V reference
    float temperature = (voltage - 0.5) * 100.0; // TMP36: 10mV/°C, 0.5V offset
    return temperature;
}

// Function to log temperature to file
void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write to log file
    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Setup function to initialize pigpio and SPI
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(CE0, PI_OUTPUT);
    gpioSetMode(SCLK, PI_OUTPUT);
    gpioSetMode(MOSI, PI_OUTPUT);
    gpioSetMode(MISO, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }
    rewind(log_file);

    return 0;
}

// Cleanup function to close SPI and log file
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup
    if (setup() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Validate temperature
        if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
            fprintf(stderr, "Warning: Temperature out of range (%.2f°C)\n", temperature);
