#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1172_ADDR 0x49
#define LOG_FILE "biometric_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Si1172 Register Addresses (Example - Refer to Datasheet for actual values)
#define SI1172_REG_PART_ID 0x00
#define SI1172_REG_HW_REV 0x01
#define SI1172_REG_SEQ_ID 0x02
#define SI1172_REG_INT_CFG 0x03
#define SI1172_REG_INT_EN 0x04
#define SI1172_REG_RSP0_CFG 0x07
#define SI1172_REG_RSP1_CFG 0x08
#define SI1172_REG_RSP2_CFG 0x09
#define SI1172_REG_RSP3_CFG 0x0A
#define SI1172_REG_RSP0_DATA0 0x10
#define SI1172_REG_RSP0_DATA1 0x11
#define SI1172_REG_RSP1_DATA0 0x12
#define SI1172_REG_RSP1_DATA1 0x13
#define SI1172_REG_RSP2_DATA0 0x14
#define SI1172_REG_RSP2_DATA1 0x15
#define SI1172_REG_RSP3_DATA0 0x16
#define SI1172_REG_RSP3_DATA1 0x17
#define SI1172_REG_MEAS_RATE0 0x0F
#define SI1172_REG_MEAS_RATE1 0x10

// Global Variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int initialize_sensor();
int read_sensor_data(int16_t *ir_value, int16_t *red_value);
int log_data(time_t timestamp, int16_t ir_value, int16_t red_value, int error_flag);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the Si1172 sensor
int initialize_sensor() {
    // Example initialization sequence (Refer to Si1172 datasheet)
    // This is a placeholder - replace with actual initialization sequence
    if (i2cWriteByteData(i2c_handle, SI1172_REG_INT_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to INT_CFG register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SI1172_REG_INT_EN, 0x00) < 0) {
        fprintf(stderr, "Error writing to INT_EN register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SI1172_REG_MEAS_RATE0, 0x0A) < 0) {
        fprintf(stderr, "Error writing to MEAS_RATE0 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SI1172_REG_MEAS_RATE1, 0x00) < 0) {
        fprintf(stderr, "Error writing to MEAS_RATE1 register\n");
        return -1;
    }

    // Verify sensor presence by reading Part ID
    int part_id = i2cReadByteData(i2c_handle, SI1172_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID register\n");
        return -1;
    }

    printf("Si1172 Part ID: 0x%02X\n", part_id);

    return 0;
}

// Read raw IR and RED ADC values from the sensor
int read_sensor_data(int16_t *ir_value, int16_t *red_value) {
    // Read IR value
    int ir_data0 = i2cReadByteData(i2c_handle, SI1172_REG_RSP0_DATA0);
    int ir_data1 = i2cReadByteData(i2c_handle, SI1172_REG_RSP0_DATA1);

    if (ir_data0 < 0 || ir_data1 < 0) {
        fprintf(stderr, "Error reading IR data\n");
        return -1;
    }

    *ir_value = (int16_t)((ir_data1 << 8) | ir_data0);

    // Read RED value
    int red_data0 = i2cReadByteData(i2c_handle, SI1172_REG_RSP1_DATA0);
    int red_data1 = i2cReadByteData(i2c_handle, SI1172_REG_RSP1_DATA1);

    if (red_data0 < 0 || red_data1 < 0) {
        fprintf(stderr, "Error reading RED data\n");
        return -1;
    }

    *red_value = (int16_t)((red_data1 << 8) | red_data0);

    return 0;
}

// Log data to the CSV file
int log_data(time_t timestamp, int16_t ir_value, int16_t red_value, int error_flag) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp_str, ir_value, red_value, error_flag);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,HR (bpm),SpO2 (%%),Error Flag\n");
    }
    fflush(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        time_t current_time = time(NULL);
        int16_t ir_value, red_value;
        int error_flag = 0;

        if (read_sensor_data(&ir_value, &red_value) != 0) {
            error_flag = 1;
            fprintf(stderr, "Error reading sensor data\n");
        }

        log_data(current_time, ir_value, red_value, error_flag);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

