    int red_data1 = i2cReadByteData(i2c_handle, SI1172_REG_RSP1_DATA1);

    if (red_data0 < 0 || red_data1 < 0) {
        fprintf(stderr, "Error reading RED data\n");
        return -1;
    }

    *red_value = (int16_t)((red_data1 << 8) | red_data0);

    return 0;
}

// Log data to the CSV file
