#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define FLOW_MIN 0.0
#define FLOW_MAX 5.0
#define LOG_FILE "flow_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi_channel();
int read_adc(int channel);
float convert_to_flow_rate(int adc_value);
void log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int adc_channel;
    float flow_min;
    float flow_max;
    char *log_file;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    ADC_CHANNEL,
    FLOW_MIN,
    FLOW_MAX,
    LOG_FILE
};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open SPI channel
    if (open_spi_channel() != 0) {
        fprintf(stderr, "Failed to open SPI channel. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Continuing.\n");
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        // Convert to flow rate
        float flow_rate = convert_to_flow_rate(adc_value);

        // Log flow rate
        log_flow_rate(flow_rate);

        // Wait 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open SPI channel
int open_spi_channel() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read ADC value
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Convert ADC value to flow rate
float convert_to_flow_rate(int adc_value) {
    // Linear conversion: 0 ADC = 0 L/min, 1023 ADC = 5 L/min
    float flow_rate = (float)adc_value / 1023.0 * config.flow_max;

    return flow_rate;
}

// Log flow rate to file
void log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long microseconds = ts.tv_nsec / 1000;

    fprintf(log_file, "%s.%06ld,%.2f\n", timestamp, microseconds, flow_rate);
    fflush(log_file);

    printf("%s.%06ld,%.2f\n", timestamp, microseconds, flow_rate);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

