// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize SPI
int initialize_spi(int channel, int speed, int mode, int cs_pin) {
    int handle = spiOpen(channel, speed, mode);
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    gpioSetMode(cs_pin, PI_OUTPUT);
    gpioWrite(cs_pin, 1); // Deactivate chip select initially
    return handle;
