            fprintf(stderr, "Error reading from MCP3008, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        // Process audio samples (apply gain)
        float processed_sample1 = process_audio_sample(raw_sample1, gain1);
        float processed_sample2 = process_audio_sample(raw_sample2, gain2);

        // Perform noise cancellation
        float cleaned_sample = noise_cancellation(processed_sample1, processed_sample2);

        // Print the cleaned audio sample to the terminal in CSV format
        printf("%.2f,%.2f\n", processed_sample1, cleaned_sample);

        // Delay to control sampling rate
        gpioDelay(1000); // 1ms delay
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

