int initialize_spi();
int read_adc(int channel);
int validate_adc_value(int value);
char* generate_iso8601_timestamp();
int log_data(const char* timestamp, int adc_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Validate ADC value
int validate_adc_value(int value) {
    if (value < 0 || value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", value);
        return -1;
    }
    return 0;
}

// Generate ISO 8601 timestamp
char* generate_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Memory allocation failed for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    if (strftime(timestamp, 25, ISO8601_FORMAT, timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        free(timestamp);
        return NULL;
    }

    return timestamp;
}

// Log data to file
int log_data(const char* timestamp, int adc_value) {
    FILE *fp = fopen("moisture_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    fprintf(fp, "%s,%d\n", timestamp, adc_value);
    if (ferror(fp)) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

