    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Continue to the next iteration
        }

        // Validate ADC value
        if (validate_adc_value(adc_value) != 0) {
            fprintf(stderr, "Invalid ADC value, skipping logging\n");
            continue; // Continue to the next iteration
        }

        // Generate timestamp
        char* timestamp = generate_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to generate timestamp\n");
            continue; // Continue to the next iteration
        }

        // Log data
        if (log_data(timestamp, adc_value) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Close SPI and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

