#define MCP3008_CHANNEL 0
#define MIN_CALIBRATION 0
#define MAX_CALIBRATION 1023

// Global variables
int spi_handle;
FILE *log_file;
char *email_address;
char *msmtp_config_file;
int running = 1;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value, int min_calibration, int max_calibration);
void log_data(float moisture_percentage);
void send_email_alert(float moisture_percentage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value, int min_calibration, int max_calibration) {
    float moisture_percentage = ((float)(adc_value - min_calibration) / (float)(max_calibration - min_calibration)) * 100.0;

    // Clamp the value between 0 and 100
    if (moisture_percentage < 0.0) {
        moisture_percentage = 0.0;
    } else if (moisture_percentage > 100.0) {
        moisture_percentage = 100.0;
    }

    return moisture_percentage;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percentage);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send email alert
void send_email_alert(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char body[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(body, sizeof(body), "Subject: Plant Moisture Alert\n\nThe moisture level for the plant is below the threshold.\nTimestamp: %s\nMoisture Percentage: %.2f%%\nRecipient: %s", timestamp, moisture_percentage, email_address);

    FILE *email_pipe = popen("/usr/bin/msmtp -f /tmp/msmtp.conf -t", "w");
    if (email_pipe == NULL) {
        fprintf(stderr, "Error: Failed to open msmtp pipe\n");
        return;
    }

    if (fprintf(email_pipe, "%s", body) < 0) {
        fprintf(stderr, "Error: Failed to write to msmtp pipe\n");
        pclose(email_pipe);
        return;
    }

    int msmtp_status = pclose(email_pipe);
    if (msmtp_status != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", msmtp_status);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

