int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("plant_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Create temporary msmtp config file
    FILE *config_file = fopen("/tmp/msmtp.conf", "w");
    if (config_file == NULL) {
        fprintf(stderr, "Error: Failed to create msmtp config file\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(config_file, "defaults\n");
    fprintf(config_file, "auth = on\n");
    fprintf(config_file, "tls = off\n");
    fprintf(config_file, "account default\n");
    fprintf(config_file, "  user = %s\n", email_address);
    fprintf(config_file, "  password = your_password_here\n"); // Replace with actual password
    fprintf(config_file, "  host = smtp.your_email_provider.com\n");
    fprintf(config_file, "  port = 587\n");
    fprintf(config_file, "  from = %s\n", email_address);
    fclose(config_file);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    remove("/tmp/msmtp.conf"); // Remove the temporary config file
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 7) {
        fprintf(stderr, "Usage: %s <SPI channel> <ADC channel> <min calibration> <max calibration> <moisture threshold> <email address> <msmtp config file>\n", argv[0]);
        return 1;
    }

    int spi_channel = atoi(argv[1]);
    int adc_channel = atoi(argv[2]);
    int min_calibration = atoi(argv[3]);
    int max_calibration = atoi(argv[4]);
    float moisture_threshold = atof(argv[5]);
    email_address = argv[6];
    msmtp_config_file = argv[7];

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Plant monitoring started...\n");

    // Main loop
    while (running) {
        int adc_value = read_mcp3008(adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", LOGGING_INTERVAL);
            sleep(LOGGING_INTERVAL);
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(adc_value, min_calibration, max_calibration);
        log_data(moisture_percentage);

        if (moisture_percentage < moisture_threshold) {
            send_email_alert(moisture_percentage);
        }

        sleep(LOGGING_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

