        printf("ADC Value: %d, Moisture Percentage: %.2f%%\n", adc_value, moisture_percentage);

        // Wait for 5 seconds
        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop.
    close(spi_fd);
    return 0;
