#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define CE0 8
#define MISO 9
#define MOSI 10
#define SCLK 11

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define ADC channel for the pressure sensor
#define ADC_CHANNEL 0

// Define pressure range (kPa)
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0

// Define voltage range (V)
#define MIN_VOLTAGE 0.0
#define MAX_VOLTAGE 3.3

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_pressure(float voltage);
void log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int ce_pin;
    int miso_pin;
    int mosi_pin;
    int sclk_pin;
    int spi_channel;
    int spi_baud;
    int adc_channel;
    float min_pressure;
    float max_pressure;
    float min_voltage;
    float max_voltage;
} Config;

Config config = {
    CE0, MISO, MOSI, SCLK, SPI_CHANNEL, SPI_BAUD, ADC_CHANNEL, MIN_PRESSURE, MAX_PRESSURE, MIN_VOLTAGE, MAX_VOLTAGE
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(config.adc_channel);

        // Check for errors during ADC read
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Validate ADC value
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);

        // Log the data
        log_data(pressure);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize SPI
int initialize_spi() {
    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * config.max_voltage;
}

// Convert voltage to pressure (kPa)
float voltage_to_pressure(float voltage) {
    // Linear relationship: pressure = (voltage - min_voltage) / (max_voltage - min_voltage) * (max_pressure - min_pressure) + min_pressure
    return (voltage - config.min_voltage) / (config.max_voltage - config.min_voltage) * (config.max_pressure - config.min_pressure) + config.min_pressure;
}

// Log data to console with ISO 8601 timestamp
void log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    // Close SPI channel
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Terminate pigpio
    gpioTerminate();
}

