#include <pigpio.h>

// Define GPIO pins
#define PUMP_GPIO 17
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define moisture thresholds
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600

// Define circular buffer size
#define BUFFER_SIZE 20

// Structure to store moisture readings and timestamps
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} Reading;

// Circular buffer
Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int moisture_level);
void add_reading(time_t timestamp, int moisture_level, int pump_state);
void print_buffer();
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int moisture_level) {
    static int pump_state = 0; // 0 = off, 1 = on

    if (moisture_level < MOISTURE_LOW_THRESHOLD && pump_state == 0) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump on
        pump_state = 1;
        printf("Pump ON\n");
    } else if (moisture_level > MOISTURE_HIGH_THRESHOLD && pump_state == 1) {
        gpioWrite(PUMP_GPIO, 0); // Turn pump off
        pump_state = 0;
        printf("Pump OFF\n");
    }
}

// Function to add a reading to the circular buffer
void add_reading(time_t timestamp, int moisture_level, int pump_state) {
    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].moisture_level = moisture_level;
    buffer[buffer_index].pump_state = pump_state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

