void print_buffer() {
    printf("\n--- Moisture Readings ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        time_t timestamp = buffer[i].timestamp;
        struct tm *timeinfo = localtime(&timestamp);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Moisture: %d, Pump: %s\n", time_str, buffer[i].moisture_level, buffer[i].pump_state ? "ON" : "OFF");
    }
    printf("-------------------------\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially off

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    // Turn off the pump
    gpioWrite(PUMP_GPIO, 0);

    // Close SPI interface
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    printf("Soil Moisture Monitoring System\n");

    while (!terminate) {
        // Read moisture level from MCP3008
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Failed to read moisture level, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Get current timestamp
        time_t current_time = time(NULL);

        // Control the pump
        control_pump(moisture_level);

        // Add reading to the circular buffer
        add_reading(current_time, moisture_level, gpioRead(PUMP_GPIO));

        // Print the buffer
        print_buffer();

        // Wait for 5 seconds
        sleep(5);
    }

    cleanup();
    return 0;
}

