#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MAX30102 I2C address
#define MAX30102_I2C_ADDR 0x57

// MAX30102 Register Addresses
#define MAX30102_PART_ID 0x00
#define MAX30102_INTSTAT1 0x00
#define MAX30102_INTENABLE1 0x01
#define MAX30102_FIFOWR 0x04
#define MAX30102_FIFORD 0x05
#define MAX30102_FIFOCONFIG 0x08
#define MAX30102_MODECONFIG 0x09
#define MAX30102_SPO2CONFIG 0x0A
#define MAX30102_LEDCONFIG 0x0C
#define MAX30102_PROXCONFIG 0x0E
#define MAX30102_MULTIPROX 0x10
#define MAX30102_FIFOREADPTR 0x07
#define MAX30102_FIFOWRPTR 0x06

// Configuration values
#define FIFO_SAMPLEAVG 64
#define FIFO_WRITING 1
#define FIFO_RDPTR_RST 0
#define FIFO_WRPTR_RST 0
#define MODE_SPO2 0x03
#define LED_PA 0x24 // 24% of maximum current
#define SPO2_ADCRANGE 0x03 // 4096
#define SPO2_SAMPLEAVG 100
#define SPO2_AVERAGING 1
#define SPO2_REPORTING 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_max30102();
int read_max30102_data(int *red, int *ir);
void log_data(int red, int ir, int spo2, int heart_rate);
void signal_handler(int signal);

// Function to write a byte to a MAX30102 register
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a MAX30102 register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read\n");
        return -1;
    }
    if (i2cReadDevice(handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to initialize the MAX30102 sensor
int init_max30102() {
    uint8_t part_id;

    // Check Part ID
    if (read_register(i2c_handle, MAX30102_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error reading Part ID\n");
        return -1;
    }

    if (part_id != 0x15) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure FIFO
    if (write_register(i2c_handle, MAX30102_FIFOCONFIG, FIFO_SAMPLEAVG) != 0) return -1;
    if (write_register(i2c_handle, MAX30102_FIFOCONFIG, FIFO_WRITING) != 0) return -1;
    if (write_register(i2c_handle, MAX30102_FIFOCONFIG, FIFO_RDPTR_RST) != 0) return -1;
    if (write_register(i2c_handle, MAX30102_FIFOCONFIG, FIFO_WRPTR_RST) != 0) return -1;

    // Configure Mode
    if (write_register(i2c_handle, MAX30102_MODECONFIG, MODE_SPO2) != 0) return -1;

    // Configure LED current
    if (write_register(i2c_handle, MAX30102_LEDCONFIG, LED_PA) != 0) return -1;

    // Configure SPO2
    if (write_register(i2c_handle, MAX30102_SPO2CONFIG, SPO2_ADCRANGE) != 0) return -1;
    if (write_register(i2c_handle, MAX30102_SPO2CONFIG, SPO2_SAMPLEAVG) != 0) return -1;
    if (write_register(i2c_handle, MAX30102_SPO2CONFIG, SPO2_AVERAGING) != 0) return -1;
    if (write_register(i2c_handle, MAX30102_SPO2CONFIG, SPO2_REPORTING) != 0) return -1;

    return 0;
}

// Function to read SpO2 and heart rate data from the MAX30102
int read_max30102_data(int *red, int *ir) {
    uint8_t fifo_data[6];
    uint8_t msb, lsb;

    // Read FIFO data
    if (i2cWriteDevice(i2c_handle, (char[]){MAX30102_FIFORD}, 1) != 1) {
        fprintf(stderr, "Error writing to FIFO read register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, (char *)fifo_data, 6) != 6) {
        fprintf(stderr, "Error reading FIFO data\n");
        return -1;
    }

    // Extract Red and IR values
    msb = fifo_data[0];
    lsb = fifo_data[1];
    *red = (msb << 8) | lsb;

    msb = fifo_data[2];
    lsb = fifo_data[3];
    *ir = (msb << 8) | lsb;

    return 0;
}

// Function to log data to a file
void log_data(int red, int ir, int spo2, int heart_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Red: %d, IR: %d, SpO2: %d, Heart Rate: %d\n", timestamp, red, ir, spo2, heart_rate);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int red, ir, spo2, heart_rate;
    int i2c_bus = 1; // I2C bus 1

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(i2c_bus, MAX30102_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MAX30102 sensor
    if (init_max30102() != 0) {
        fprintf(stderr, "MAX30102 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("health_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_max30102_data(&red, &ir) == 0) {
            // Placeholder for SpO2 and heart rate calculation
            spo2 = 90; // Replace with actual calculation
            heart_rate = 70; // Replace with actual calculation

            // Log data if SpO2 is low or heart rate is high
            if (spo2 < 95 || heart_rate > 100) {
                log_data(red, ir, spo2, heart_rate);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Close I2C device and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully\n");
    return 0;
}

