#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define GPIO_RELAY 17
#define GPIO_DOOR_SENSOR 27
#define DISTANCE_THRESHOLD 50.0 // mm
#define RELAY_PULSE_DURATION 3000 // ms
#define NUM_CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY 50      // ms

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint16_t value);
int i2c_read_reg(int fd, uint8_t reg, uint16_t *value);
int ads1115_read_adc(int fd);
float calculate_distance(int adc_value);
void control_relay(int gpio_pin, int duration_ms);
int read_reed_sensor(int gpio_pin);
void log_event(const char *message);
void signal_handler(int sig);

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;       // LSB

    if (write(fd, buf, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("I2C read (MSB) failed");
        return -1;
    }
    uint8_t msb = buf[0];

    if (read(fd, buf, 1) != 1) {
        perror("I2C read (LSB) failed");
        return -1;
    }
    uint8_t lsb = buf[0];

    *value = (msb << 8) | lsb;
    return 0;
}

// ADS1115 read ADC function
int ads1115_read_adc(int fd) {
    uint16_t config = 0x4083; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    uint16_t adc_value;

    if (i2c_write_reg(fd, 0x01, config) < 0) {
        fprintf(stderr, "Error writing config register\n");
        return -1;
    }

    delay(10); // Wait for conversion

    if (i2c_read_reg(fd, 0x00, &adc_value) < 0) {
        fprintf(stderr, "Error reading ADC value\n");
        return -1;
    }

    return (int16_t)adc_value; // Return signed 16-bit value
}

// Calculate distance from ADC value (example calibration)
float calculate_distance(int adc_value) {
    // This is a placeholder.  You'll need to calibrate the sensor.
    // The relationship between ADC value and distance is typically non-linear.
    // You'll need to determine the correct formula based on your sensor's datasheet
    // and experimental data.
    // Example (replace with your actual calibration):
    return 100.0 / (adc_value + 1.0); // Example inverse relationship
}

// Control relay function
void control_relay(int gpio_pin, int duration_ms) {
    digitalWrite(gpio_pin, HIGH); // Energize relay
    delay(duration_ms);
    digitalWrite(gpio_pin, LOW);  // De-energize relay
}

// Read reed sensor function
int read_reed_sensor(int gpio_pin) {
    return digitalRead(gpio_pin);
}

// Log event function
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        keep_running = 0;

        // De-energize relay
        digitalWrite(GPIO_RELAY, LOW);

        // Close I2C file descriptor
        if (i2c_fd != -1) {
            close(i2c_fd);
        }

        // Close log file
        if (log_file != NULL) {
            fclose(log_file);
        }

        exit(0);
    }
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins
    pinMode(GPIO_RELAY, OUTPUT);
    pinMode(GPIO_DOOR_SENSOR, INPUT);
    pullUpDnControl(GPIO_DOOR_SENSOR, PUD_UP); // Enable pull-up resistor

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
