// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;       // LSB

    if (write(fd, buf, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("I2C read (MSB) failed");
        return -1;
    }
    uint8_t msb = buf[0];

    if (read(fd, buf, 1) != 1) {
        perror("I2C read (LSB) failed");
        return -1;
    }
    uint8_t lsb = buf[0];

    *value = (msb << 8) | lsb;
    return 0;
}

