FILE *log_file;
float moisture_threshold = DEFAULT_THRESHOLD;
int pump_duration = DEFAULT_PUMP_DURATION;
int sleep_interval = DEFAULT_SLEEP_INTERVAL;
volatile sig_atomic_t terminate = 0;

