            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "Error: SPI transfer failed (attempt %d): %d", i + 1, result);
