#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define THRESHOLD 500
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define LOG_FILE "/var/log/sound_events.log"
#define SAMPLE_INTERVAL_MS 10

// Global variables
int spi_handle;
int socket_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    int threshold;
    char server_ip[20];
    int server_port;
    char log_file[50];
    int sample_interval_ms;
} Config;

// Function prototypes
int init_spi();
int read_mcp3008(int channel);
int detect_peak(int adc_value, int threshold);
int log_event(int adc_value);
int send_data(int adc_value);
void signal_handler(int signal);
void cleanup();
Config load_config(const char *filename);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Detect peak
int detect_peak(int adc_value, int threshold) {
    return adc_value > threshold;
}

// Log event to file
int log_event(int adc_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %d\n", timestamp, adc_value);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Send data to server
int send_data(int adc_value) {
    char message[50];
    snprintf(message, sizeof(message), "%d", adc_value);

    if (send(socket_fd, message, strlen(message), 0) < 0) {
        perror("Send failed");
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (socket_fd >= 0) {
        close(socket_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Load configuration from file
Config load_config(const char *filename) {
    Config config;
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file, using default values");
        // Initialize with default values if config file is not found
        config.spi_channel = SPI_CHANNEL;
        config.spi_speed = SPI_SPEED;
        config.mcp3008_channel = MCP3008_CHANNEL;
        config.threshold = THRESHOLD;
        strncpy(config.server_ip, SERVER_IP, sizeof(config.server_ip) - 1);
        config.server_ip[sizeof(config.server_ip) - 1] = '\0'; // Ensure null termination
        config.server_port = SERVER_PORT;
        strncpy(config.log_file, LOG_FILE, sizeof(config.log_file) - 1);
        config.log_file[sizeof(config.log_file) - 1] = '\0';
        config.sample_interval_ms = SAMPLE_INTERVAL_MS;
        return config;
    }

    if (fscanf(fp, "spi_channel = %d\n", &config.spi_channel) != 1) goto default_values;
    if (fscanf(fp, "spi_speed = %d\n", &config.spi_speed) != 1) goto default_values;
    if (fscanf(fp, "mcp3008_channel = %d\n", &config.mcp3008_channel) != 1) goto default_values;
    if (fscanf(fp, "threshold = %d\n", &config.threshold) != 1) goto default_values;
    if (fscanf(fp, "server_ip = %s\n", config.server_ip) != 1) goto default_values;
    if (fscanf(fp, "server_port = %d\n", &config.server_port) != 1) goto default_values;
    if (fscanf(fp, "log_file = %s\n", config.log_file) != 1) goto default_values;
    if (fscanf(fp, "sample_interval_ms = %d\n", &config.sample_interval_ms) != 1) goto default_values;

    fclose(fp);
    return config;

default_values:
    fprintf(stderr, "Error reading config file, using default values\n");
    // Initialize with default values
    config.spi_channel = SPI_CHANNEL;
    config.spi_speed = SPI_SPEED;
    config.mcp3008_channel = MCP3008_CHANNEL;
    config.threshold = THRESHOLD;
    strncpy(config.server_ip, SERVER_IP, sizeof(config.server_ip) - 1);
    config.server_ip[sizeof(config.server_ip) - 1] = '\0'; // Ensure null termination
    config.server_port = SERVER_PORT;
    strncpy(config.log_file, LOG_FILE, sizeof(config.log_file) - 1);
    config.log_file[sizeof(config.log_file) - 1] = '\0';
    config.sample_interval_ms = SAMPLE_INTERVAL_MS;
    fclose(fp);
    return config;
}

int main() {
    // Load configuration
    Config config = load_config("config.txt");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        perror("Error creating socket");
        cleanup();
        return 1;
    }

    // Connect to server
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(config.server_port);
    if (inet_pton(AF_INET, config.server_ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        cleanup();
        return 1;
    }

    if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection Failed");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Continue to the next iteration
        }

        // Detect peak
        if (detect_peak(adc_value, config.threshold)) {
            // Log event
            if (log_event(adc_value) != 0) {
                fprintf(stderr, "Error logging event\n");
            }

            // Send data to server
            if (send_data(adc_value) != 0) {
                fprintf(stderr, "Error sending data to server\n");
            }
        }

        // Wait for the next sample
        gpioDelay(config.sample_interval_ms * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

