    fprintf(stderr, "Error reading config file, using default values\n");
    // Initialize with default values
    config.spi_channel = SPI_CHANNEL;
    config.spi_speed = SPI_SPEED;
    config.mcp3008_channel = MCP3008_CHANNEL;
    config.threshold = THRESHOLD;
    strncpy(config.server_ip, SERVER_IP, sizeof(config.server_ip) - 1);
    config.server_ip[sizeof(config.server_ip) - 1] = '\0'; // Ensure null termination
    config.server_port = SERVER_PORT;
    strncpy(config.log_file, LOG_FILE, sizeof(config.log_file) - 1);
    config.log_file[sizeof(config.log_file) - 1] = '\0';
    config.sample_interval_ms = SAMPLE_INTERVAL_MS;
    fclose(fp);
    return config;
}

int main() {
    // Load configuration
    Config config = load_config("config.txt");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        perror("Error creating socket");
        cleanup();
        return 1;
    }

    // Connect to server
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(config.server_port);
    if (inet_pton(AF_INET, config.server_ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        cleanup();
        return 1;
    }

    if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection Failed");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Continue to the next iteration
        }

        // Detect peak
        if (detect_peak(adc_value, config.threshold)) {
            // Log event
            if (log_event(adc_value) != 0) {
                fprintf(stderr, "Error logging event\n");
            }

            // Send data to server
            if (send_data(adc_value) != 0) {
                fprintf(stderr, "Error sending data to server\n");
            }
        }

        // Wait for the next sample
        gpioDelay(config.sample_interval_ms * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

