// Constants
#define ADS1115_I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_REG_LO_THRESH 0x02
#define ADS1115_REG_HI_THRESH 0x03
#define ADS1115_CONFIG_DEFAULT 0x4003 // Single-ended AIN0, 128 SPS, 3.3V, Disable comparator

#define GPIO_SHUTDOWN 27
#define THRESHOLD_GAUSS 500.0
#define BUFFER_SIZE 10
#define SAMPLE_RATE_HZ 1

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer
float voltage_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_adc(int channel);
float voltage_to_gauss(float voltage);
void update_circular_buffer(float voltage);
float calculate_rolling_average();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(ADS1115_I2C_ADDR);
    if (i2c_fd == -1) {
        syslog(LOG_ERR, "Failed to initialize I2C communication.");
        return -1;
    }

    // Configure ADS1115
    if (wiringPiI2CWriteReg16(i2c_fd, ADS1115_REG_CONFIG, ADS1115_CONFIG_DEFAULT) == -1) {
        syslog(LOG_ERR, "Failed to configure ADS1115.");
        return -1;
    }

    return 0;
}

// Function to read ADC value from a channel
int read_adc(int channel) {
    int16_t adc_value;

    // Set the mux value based on the channel
    int config = ADS1115_CONFIG_DEFAULT;
    switch (channel) {
        case 0:
            config &= 0x000F; // AIN0
            break;
        case 1:
            config &= 0x00F0; // AIN1
            break;
        case 2:
            config &= 0x00F0; // AIN2
            break;
        case 3:
            config &= 0x000F; // AIN3
            break;
        default:
            syslog(LOG_ERR, "Invalid ADC channel.");
            return -1;
    }

    if (wiringPiI2CWriteReg16(i2c_fd, ADS1115_REG_CONFIG, config) == -1) {
        syslog(LOG_ERR, "Failed to write to config register.");
        return -1;
    }

    delay(10); // Wait for conversion

    adc_value = wiringPiI2CReadReg16(i2c_fd, ADS1115_REG_CONVERT);
    if (adc_value == -1) {
        syslog(LOG_ERR, "Failed to read ADC value.");
        return -1;
    }

    // ADS1115 returns a 16-bit value, but we only need the lower 15 bits for 16-bit resolution
    adc_value = (adc_value << 1) >> 1; // Sign extend

    return adc_value;
}

// Function to convert voltage to Gauss
float voltage_to_gauss(float voltage) {
    // Assuming a linear relationship between voltage and magnetic field strength
    // This is a placeholder; replace with the actual calibration data from the SS49E datasheet
    // Example: 0.1 Gauss/Volt
    float gauss_per_volt = 0.1; // Example value, replace with actual value
    return voltage * gauss_per_volt;
}

// Function to update the circular buffer
void update_circular_buffer(float voltage) {
    voltage_buffer[buffer_index] = voltage;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average
float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += voltage_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    program_running = 0;
}

// Cleanup function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");
    digitalWrite(GPIO_SHUTDOWN, LOW);
    closelog();
}

int main() {
    // Initialize syslog
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        syslog(LOG_ERR, "Failed to initialize wiringPi.");
        return 1;
    }

    // Set GPIO_SHUTDOWN as output
    pinMode(GPIO_SHUTDOWN, OUTPUT);
    digitalWrite(GPIO_SHUTDOWN, LOW);

    // Initialize I2C
    if (init_i2c() == -1) {
        syslog(LOG_ERR, "Failed to initialize I2C. Exiting.");
        cleanup();
        return 1;
    }

    syslog(LOG_INFO, "Hall sensor monitor started.");

    // Main loop
    while (program_running) {
        int adc_value = read_adc(0);
        if (adc_value != -1) {
            // Convert ADC value to voltage (assuming 16-bit ADC and 3.3V reference)
            float voltage = (float)adc_value * 3.3 / 32767.0;

            // Validate voltage
            if (voltage >= 0.0 && voltage <= 3.3) {
                // Convert voltage to Gauss
                float gauss = voltage_to_gauss(voltage);

                // Update circular buffer
                update_circular_buffer(voltage);

                // Calculate rolling average
                float rolling_average = calculate_rolling_average();

                // Log data
                syslog(LOG_INFO, "Voltage: %.2f V, Gauss: %.2f G, Rolling Average: %.2f V", voltage, gauss, rolling_average);

                // Check threshold
                if (gauss > THRESHOLD_GAUSS) {
                    syslog(LOG_WARNING, "Threshold exceeded: %.2f G", gauss);
                    digitalWrite(GPIO_SHUTDOWN, HIGH);
                } else {
                    digitalWrite(GPIO_SHUTDOWN, LOW);
                }
            } else {
                syslog(LOG_ERR, "Voltage out of range: %.2f V", voltage);
            }
        } else {
            syslog(LOG_ERR, "Failed to read ADC value.");
        }

        delay(1000 / SAMPLE_RATE_HZ); // Sample at 1 Hz
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

