#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VDD 3.3
#define ADC_MAX 1023
#define RAINFALL_LEVELS 5

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
int voltage_to_rainfall_intensity(float voltage);
void log_data(int adc_value, int rainfall_intensity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Reads the MCP3008 ADC value from the specified channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the SPI message to send to the MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer the SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Converts the ADC value to a voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / ADC_MAX) * VDD;
}

// Maps the voltage to a rainfall intensity level
int voltage_to_rainfall_intensity(float voltage) {
    if (voltage < 0.5 * VDD) {
        return 0; // No rain
    } else if (voltage < 1.0 * VDD) {
        return 1; // Light rain
    } else if (voltage < 1.5 * VDD) {
        return 2; // Moderate rain
    } else if (voltage < 2.0 * VDD) {
        return 3; // Heavy rain
    } else {
        return 4; // Storm
    }
}

// Logs the data to stdout with a timestamp
void log_data(int adc_value, int rainfall_intensity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, ADC: %d, Rainfall Intensity: %d\n", timestamp, adc_value, rainfall_intensity);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float voltage = adc_to_voltage(adc_value);
            int rainfall_intensity = voltage_to_rainfall_intensity(voltage);
            log_data(adc_value, rainfall_intensity);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Rain sensor monitoring stopped.\n");

    return 0;
}

