#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_LED 17
#define DEFAULT_THRESHOLD 100.0
#define BLINK_DURATION 1000 // milliseconds
#define BLINK_ON_TIME 50    // milliseconds
#define BLINK_OFF_TIME 50   // milliseconds

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_ads1115();
int16_t read_ads1115();
double convert_to_gauss(int16_t raw_value);
void blink_led();
void signal_handler(int signal);

// Structure for configuration (optional, but good practice)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int gpio_led;
    double default_threshold;
} Config;

Config config = {
    .i2c_bus = I2C_BUS,
    .ads1115_address = ADS1115_ADDR,
    .gpio_led = GPIO_LED,
    .default_threshold = DEFAULT_THRESHOLD
};

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        threshold = atof(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Error: Threshold must be a positive value.\n");
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle = i2cOpen(config.i2c_bus, config.ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (init_ads1115() != 0) {
        fprintf(stderr, "Error initializing ADS1115\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO for LED
    gpioSetMode(config.gpio_led, PI_OUTPUT);
    gpioWrite(config.gpio_led, 0); // Initially off

    // Main loop
    while (!terminate) {
        // Read sensor value
        int16_t raw_value = read_ads1115();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading ADS1115\n");
            continue; // Continue to the next iteration
        }

        // Convert to Gauss
        double gauss = convert_to_gauss(raw_value);

        // Print Gauss value
        printf("Magnetic Field: %.2f Gauss\n", gauss);

        // Check threshold and blink LED if necessary
        if (gauss > threshold) {
            blink_led();
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    gpioWrite(config.gpio_led, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize ADS1115
int init_ads1115() {
    // Configuration register value:
    // 0b10000000000000000000000000000000
    // Single-ended AIN0, PGA = +/-4.096V, Continuous conversion mode, 128 SPS, Disable comparator
    uint16_t config_value = 0x8383; //0b1000001110000011

    // Write configuration register
    char buf[3];
    buf[0] = CONFIG_REG;
