#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "soil_moisture"
#define MQTT_CONTROL_TOPIC "pump_control"
#define SENSOR_ABSOLUTE_MIN 0
#define SENSOR_ABSOLUTE_MAX 1023

// Global variables
static int spi_handle;
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int pump_state);
void publish_moisture(float moisture);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signum);
int mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
int mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int result);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    if (adc_value < SENSOR_ABSOLUTE_MIN || adc_value > SENSOR_ABSOLUTE_MAX) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0; // Indicate error
    }

    float moisture = 100.0 - ((float)adc_value / SENSOR_ABSOLUTE_MAX) * 100.0;
    return moisture;
}

// Function to control the pump
void control_pump(int pump_state) {
    if (gpioWrite(PUMP_GPIO, pump_state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", PUMP_GPIO);
    }
    syslog(LOG_INFO, "Pump set to %s", pump_state ? "ON" : "OFF");
}

// Function to publish moisture data to MQTT
void publish_moisture(float moisture) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%.2f", moisture);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(ret));
    } else {
        syslog(LOG_INFO, "Published moisture: %s", payload);
    }
}

// MQTT message callback function
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        if (strcmp(message->topic, MQTT_CONTROL_TOPIC) == 0) {
            if (strcmp((char *)message->payload, "pump_on") == 0) {
                syslog(LOG_INFO, "Received pump_on command");
                control_pump(1);
            } else if (strcmp((char *)message->payload, "pump_off") == 0) {
                syslog(LOG_INFO, "Received pump_off command");
                control_pump(0);
            } else {
                syslog(LOG_WARNING, "Unknown command received: %s", (char *)message->payload);
            }
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// MQTT connect callback function
int mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        int ret = mosquitto_subscribe(mosq, NULL, MQTT_CONTROL_TOPIC, 0);
        if (ret != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT subscribe failed: %s", mosquitto_strerror(ret));
            return 1; // Indicate failure
        }
        syslog(LOG_INFO, "Connected to MQTT broker");
    } else {
        syslog(LOG_ERR, "MQTT connection failed: %s", mosquitto_strerror(result));
    }
    return 0; // Indicate success
}

// MQTT disconnect callback function
int mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int result) {
    syslog(LOG_INFO, "Disconnected from MQTT broker");
    return 0;
}

int main() {
    // Initialize syslog
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially off

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT initialisation failed");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connection failed: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int pump_state = 0; // 0 = off, 1 = on
    float moisture;
    int adc_value;

    while (running) {
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
        } else {
            moisture = calculate_moisture(adc_value);
            if (moisture < 0) {
                syslog(LOG_ERR, "Failed to calculate moisture");
            } else {
                syslog(LOG_INFO, "Moisture: %.2f%%", moisture);
                publish_moisture(moisture);

                // Hysteresis control
                if (moisture < MOISTURE_THRESHOLD_LOW && !pump_state) {
                    control_pump(1);
                    pump_state = 1;
                } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state) {
                    control_pump(0);
                    pump_state = 0;
                }
            }
        }

        sleep(60); // Publish every 60 seconds
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    gpioWrite(PUMP_GPIO, 0); // Turn off pump
    gpioTerminate();
    closelog();

    return 0;
}

