#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// SPI device file
#define SPI_DEVICE "/dev/spidev0.0"

// SPI mode
#define SPI_MODE SPI_MODE_0

// SPI clock speed (Hz)
#define SPI_SPEED 1000000

// Chip Select (CS) pin (BCM GPIO 8)
#define CS_PIN 8

// MCP3008 channel to read
#define MCP3008_CHANNEL 0

// VDD and VREF voltage
#define VDD 3.3

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
