// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define PWM_FREQUENCY 100
#define NOISE_THRESHOLD 500
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_MS 10

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void set_motor_speed(int gpio, int speed);
void log_vibration_event(int gpio);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to set motor speed using hardware PWM
void set_motor_speed(int gpio, int speed) {
    if (speed < 0 || speed > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid motor speed: %d\n", speed);
        return;
    }

    gpioPWM(gpio, speed);
}

// Function to log vibration event
void log_vibration_event(int gpio) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Vibration event on GPIO %d\n", timestamp, gpio);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for motors
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Set PWM frequency for motors
    gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_GPIO, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read noise level from MCP3008
        int noise_level = read_mcp3008(MCP3008_CHANNEL);
        if (noise_level < 0) {
            fprintf(stderr, "Error: Failed to read noise level\n");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
            continue; // Skip to the next iteration
        }

        // Control motors based on noise level
        if (noise_level > NOISE_THRESHOLD) {
            set_motor_speed(MOTOR1_GPIO, PWM_RANGE / 2); // 50% speed
            set_motor_speed(MOTOR2_GPIO, PWM_RANGE / 2); // 50% speed
        } else {
            set_motor_speed(MOTOR1_GPIO, 0); // Turn off motor 1
            set_motor_speed(MOTOR2_GPIO, 0); // Turn off motor 2
        }

        // Log vibration events
        if (noise_level > NOISE_THRESHOLD) {
            log_vibration_event(MOTOR1_GPIO);
            log_vibration_event(MOTOR2_GPIO);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_motor_speed(MOTOR1_GPIO, 0); // Turn off motor 1
    set_motor_speed(MOTOR2_GPIO, 0); // Turn off motor 2
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

