int read_bh1750() {
    char buf[2];
    int lux = -1;

    // Send start measurement command
    if (i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE) != 0) {
        fprintf(stderr, "Error: I2C write failed (start measurement)\n");
        return -1;
    }

