    // distance = a * adc_value + b
    // You'll need to determine 'a' and 'b' experimentally.
    // For example, if adc_value = 0 corresponds to 80cm and adc_value = 1023 corresponds to 5cm:
    // a = (5 - 80) / (1023 - 0) = -0.0752
    // b = 80

    float distance = -0.0752 * adc_value + 80.0; // Example linear approximation

    // Ensure distance is not negative
    if (distance < 0) {
