        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    int last_detection_time = 0; // Debounce timer

    printf("Monitoring distance sensor... Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to distance
        float distance = adc_to_distance(adc_value);

        // Check if distance is below threshold
        if (distance < DISTANCE_THRESHOLD) {
            // Check debounce timer
            int current_time = gpioTick();
            if (current_time - last_detection_time > DEBOUNCE_DELAY * 1000) { // Convert ms to us
                // Activate relay
                control_relay(1);
                log_event("Door opened (distance below threshold)");
                last_detection_time = current_time;
            }
        } else {
            // Deactivate relay
            control_relay(0);
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 us
    }

    // Cleanup
    spiClose(spi_handle);
    control_relay(0); // Ensure relay is off on exit
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

