#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define VALVE_GPIO 17
#define PWM_FREQUENCY 100
#define NUM_SENSORS 3
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_average(int sensor_values[], int num_sensors);
void set_valve_position(int average_moisture);
void log_data(int sensor_values[], float average_moisture, int valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate the average of sensor readings
float calculate_average(int sensor_values[], int num_sensors) {
    int valid_count = 0;
    float sum = 0.0;

    for (int i = 0; i < num_sensors; i++) {
        if (sensor_values[i] >= 0) {
            sum += sensor_values[i];
            valid_count++;
        }
    }

    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return -1.0; // Indicate error
    }
}

// Function to set the valve position using PWM
void set_valve_position(int average_moisture) {
    // Map moisture level (0-1023) to duty cycle (0-100)
    int duty_cycle = (int)(((float)average_moisture / 1023.0) * 100.0);

    // Ensure duty cycle is within valid range
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 100) {
        duty_cycle = 100;
    }

    // Set PWM duty cycle
    gpioPWM(VALVE_GPIO, duty_cycle);
}

// Function to log data to a file
void log_data(int sensor_values[], float average_moisture, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %.2f, %d\n",
            timestamp, sensor_values[0], sensor_values[1], sensor_values[2],
            average_moisture, valve_position);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output for PWM
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int sensor_values[NUM_SENSORS];
        int valid_readings = 0;

        // Read sensor values
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
            if (sensor_values[i] >= 0) {
                valid_readings++;
            }
        }

        // Calculate average moisture level
        float average_moisture = calculate_average(sensor_values, NUM_SENSORS);

        // Set valve position
        if (average_moisture >= 0) {
            set_valve_position((int)average_moisture);
        } else {
            gpioPWM(VALVE_GPIO, 0); // Close valve on error
        }

        // Log data
        log_data(sensor_values, average_moisture, gpioGetPWMdutycycle(VALVE_GPIO));

        // Wait 5 seconds
        sleep(5);
    }

    // Graceful shutdown
    gpioPWM(VALVE_GPIO, 0); // Close valve
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

