        int retry_count = 0;
        int delay_ms = RETRY_DELAY_BASE_MS;

        // Retry mechanism for SPI read
        while (retry_count < RETRY_COUNT && adc_value < 0) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value < 0) {
                fprintf(stderr, "Error: SPI read failed, retrying (%d/%d) in %d ms\n", retry_count + 1, RETRY_COUNT, delay_ms);
                gpioDelay(delay_ms * 1000); // Delay in microseconds
                delay_ms *= 2; // Exponential backoff
                retry_count++;
            }
        }

        if (adc_value >= 0) {
            float percentage = convert_to_percentage(adc_value);
            if (percentage >= 0.0) {
                log_data(percentage);
                printf("Moisture: %.2f%%\n", percentage);
            } else {
                fprintf(stderr, "Error: Percentage conversion failed\n");
            }
        } else {
            fprintf(stderr, "Error: SPI read failed after %d retries\n", RETRY_COUNT);
            FILE *fp = fopen(LOG_FILE, "a");
            if (fp != NULL) {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[20];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                fprintf(fp, "%s, SPI read failed after %d retries\n", timestamp, RETRY_COUNT);
                fclose(fp);
            }
        }

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");

    return 0;
}

