#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define PWM parameters
#define PWM_FREQUENCY 440 // Initial frequency (A4)
#define PWM_DUTYCYCLE 500000 // 50% duty cycle (0-1000000)

// Define constants
#define MAX_DISTANCE 400 // Maximum measurable distance in cm
#define MIN_DISTANCE 2    // Minimum measurable distance in cm
#define MAX_VOLUME 1023   // Maximum ADC value
#define MIN_VOLUME 0      // Minimum ADC value
#define TIMEOUT_US 25000  // Timeout for echo pulse in microseconds

// Global variables
static volatile int running = 1;
static volatile unsigned int echo_start = 0;
static volatile unsigned int echo_end = 0;
static volatile int distance = 0; // Default distance
static volatile int volume = 0;   // Default volume
static int spi_handle;
static FILE *log_file;

// Calibration parameters
static float distance_to_frequency_slope = 1.0;
static float distance_to_frequency_intercept = 440.0;
static float volume_to_duty_cycle_slope = 0.5;
static float volume_to_duty_cycle_intercept = 500000.0;

// Function prototypes
void signal_handler(int signal);
int read_mcp3008(int channel);
float map_distance_to_frequency(int distance);
int map_volume_to_duty_cycle(int volume);
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
void log_data(int distance, int volume);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();      // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    // Transfer SPI data
    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to map distance to frequency
float map_distance_to_frequency(int distance) {
    // Linear mapping: frequency = slope * distance + intercept
    return distance_to_frequency_slope * distance + distance_to_frequency_intercept;
}

// Function to map volume to duty cycle
int map_volume_to_duty_cycle(int volume) {
    // Linear mapping: duty_cycle = slope * volume + intercept
    return (int)(volume_to_duty_cycle_slope * volume + volume_to_duty_cycle_intercept);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start = tick;
    } else if (level == 0) {
        echo_end = tick;
    }
}

// Function to log data to file
void log_data(int distance, int volume) {
    if (log_file != NULL) {
        fprintf(log_file, "%d,%d\n", distance, volume);
        fflush(log_file); // Ensure data is written to disk
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency and duty cycle
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, 1000000); // Set PWM range to 1000000 for percentage
    gpioPWM(PWM_PIN, PWM_DUTYCYCLE / 1000000.0 * 1000000); // Set initial duty cycle

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("theremin_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Load calibration parameters from file
    FILE *config_file = fopen("theremin_config.txt", "r");
    if (config_file != NULL) {
        if (fscanf(config_file, "%f,%f,%f,%f", &distance_to_frequency_slope, &distance_to_frequency_intercept, &volume_to_duty_cycle_slope, &volume_to_duty_cycle_intercept) != 4) {
            fprintf(stderr, "Error: Failed to read calibration parameters from file, using defaults\n");
        }
        fclose(config_file);
    } else {
        fprintf(stderr, "Warning: Calibration file not found, using default values\n");
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Set up echo callback
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read distance from ultrasonic sensor
        trigger_sensor();
        gpioDelay(50); // Wait for echo

        if (echo_end - echo_start > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for echo\n");
            distance = -1; // Indicate error
        } else {
            float pulse_duration = (float)(echo_end - echo_start) / 1000000.0; // in seconds
            distance = (int)(pulse_duration * 34300 / 2); // Calculate distance in cm (speed of sound: 343 m/s)
            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                fprintf(stderr, "Error: Distance out of range: %d cm\n", distance);
                distance = -1; // Indicate error
            }
        }

        // Read volume from LDR
        volume = read_mcp3008(0);
        if (volume < 0) {
            fprintf(stderr, "Error: Failed to read LDR value\n");
            volume = -1; // Indicate error
        }

        // Map distance to frequency
        float frequency = map_distance_to_frequency(distance);

        // Map volume to duty cycle
        int duty_cycle = map_volume_to_duty_cycle(volume);

        // Set PWM frequency and duty cycle
        gpioSetPWMfrequency(PWM_PIN, (int)frequency);
        gpioPWM(PWM_PIN, duty_cycle / 1000000.0 * 1000000); // Set duty cycle

        // Log data
        log_data(distance, volume);

        // Delay
        gpioDelay(50);
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

