    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, AQI: %.2f\n", timestamp, aqi);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    spiClose(spi_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retries = 0;

        // Retry SPI read if it fails
        while (adc_value < 0 && retries < MAX_RETRIES) {
            adc_value = read_mcp3008(MQ135_CHANNEL);
            if (adc_value < 0) {
                fprintf(stderr, "SPI read failed, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
                gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
                retries++;
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after multiple retries. Re-initializing SPI.\n");
            spiClose(spi_handle);
            if (initialize_spi() != 0) {
                fprintf(stderr, "Failed to re-initialize SPI. Exiting.\n");
                break; // Exit the loop if re-initialization fails
            }
            continue; // Skip to the next iteration
        }

        // Calculate AQI
        float aqi = calculate_aqi(adc_value);

        // Control fan
        control_fan(aqi);

        // Log data
        log_data(aqi);

        // Wait 5 seconds
        gpioDelay(5000); // Delay in milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

