// Define GPIO pins
#define SPI_CE 8
#define LED_PIN 17

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define debounce time
#define DEBOUNCE_TIME 10 // milliseconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
int calibrate_ambient_noise(int duration);
void control_led(int state);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int led_state;
    uint32_t last_change_time;
} ProgramState;

ProgramState state = {0, 0};

// Function to initialize the pigpio library and configure GPIO pins
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Configure SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calibrate ambient noise level
int calibrate_ambient_noise(int duration) {
    int sum = 0;
    int num_samples = 0;
    int adc_value;

    printf("Calibrating ambient noise for %d seconds...\n", duration);

    while (num_samples < duration * 100) { // Sample 100 times per second
        adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            sum += adc_value;
            num_samples++;
        } else {
            fprintf(stderr, "Error reading ADC during calibration\n");
            return -1;
        }
        gpioDelay(10); // 10 ms delay
    }

    int baseline = sum / num_samples;
    printf("Calibration complete. Baseline: %d\n", baseline);

    return baseline;
}

// Function to control the LED
void control_led(int state) {
    if (state != state.led_state) {
        gpioWrite(LED_PIN, state);
        state.led_state = state;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Calibrate ambient noise
    int baseline = calibrate_ambient_noise(5);
    if (baseline == -1) {
        gpioTerminate();
        spiClose(spi_handle);
        return 1;
    }

    // Main loop
    int adc_value;
    while (!terminate) {
        adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            if (adc_value > baseline) {
                // Check debounce
                uint32_t current_time = gpioTick();
                if ((current_time - state.last_change_time) > (DEBOUNCE_TIME * 1000)) { // Convert ms to microseconds
                    control_led(1); // Turn LED on
                    state.last_change_time = current_time;
                }
            } else {
                control_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading ADC\n");
        }

        gpioDelay(10); // 10 ms delay
    }

    // Cleanup
    control_led(0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

