#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Define GPIO pin for chip select (CE0)
#define GPIO_PIN 8

// Define SPI device
#define SPI_DEVICE "/dev/spidev0.0"

// Define log file name
#define LOG_FILE "audio_log.txt"

// Define sampling rate (Hz)
#define SAMPLING_RATE 1000

// Define sleep duration (ms)
#define SLEEP_DURATION 1

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);
int spi_open(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_mcp3008(int fd, int channel);
void log_data(FILE *fp, long long timestamp_ns, int adc_value);
void signal_handler(int sig);

// GPIO export function
int gpio_export(int pin) {
    char buffer[64];
    int fd;
    int len;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error: Unable to open /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) < 0) {
        fprintf(stderr, "Error: Unable to write to /sys/class/gpio/export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO unexport function
int gpio_unexport(int pin) {
    char buffer[64];
    int fd;
    int len;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error: Unable to open /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) < 0) {
        fprintf(stderr, "Error: Unable to write to /sys/class/gpio/unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO set direction function
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error: Unable to open %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (write(fd, direction, strlen(direction)) < 0) {
        fprintf(stderr, "Error: Unable to write to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO write function
int gpio_write(int pin, int value) {
    char path[64];
    int fd;
    char val_str[2];

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error: Unable to open %s: %s\n", path, strerror(errno));
        return -1;
    }

    snprintf(val_str, sizeof(val_str), "%d", value);
    if (write(fd, val_str, 1) < 0) {
        fprintf(stderr, "Error: Unable to write to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// SPI open function
int spi_open(const char *device) {
    int fd;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Unable to open SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode = 0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: Unable to set SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: Unable to set bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: Unable to set max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read MCP3008 function
int read_mcp3008(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    // Perform SPI transfer
    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Log data function
void log_data(FILE *fp, long long timestamp_ns, int adc_value) {
    fprintf(fp, "%lld|%d\n", timestamp_ns, adc_value);
    fflush(fp);
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    struct timespec sleep_time;
    struct timespec remaining_time;
    long long timestamp_ns;
    int adc_value;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (gpio_export(GPIO_PIN) < 0) {
        return 1;
    }

    // Set GPIO direction to output
    if (gpio_set_direction(GPIO_PIN, "out") < 0) {
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    // Open SPI device
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Unable to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(spi_fd);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    // Set sleep time
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SLEEP_DURATION * 1000000; // 1 ms

    // Main loop
    while (!terminate) {
        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC_RAW, (struct timespec *)&timestamp_ns) < 0) {
            fprintf(stderr, "Error: Unable to get timestamp: %s\n", strerror(errno));
            break;
        }

        // Read ADC value
        adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Unable to read ADC value\n");
            break;
        }

        // Log data
        log_data(log_file, timestamp_ns, adc_value);

        // Sleep
        if (nanosleep(&sleep_time, &remaining_time) < 0) {
            if (errno == EINTR) {
                fprintf(stderr, "Nanosleep interrupted\n");
            } else {
                fprintf(stderr, "Error: Nanosleep failed: %s\n", strerror(errno));
                break;
            }
        }
    }

    // Cleanup
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    gpio_unexport(GPIO_PIN);

    return 0;
}

