        }

        // Read ADC value
        adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Unable to read ADC value\n");
            break;
        }

        // Log data
        log_data(log_file, timestamp_ns, adc_value);

        // Sleep
        if (nanosleep(&sleep_time, &remaining_time) < 0) {
            if (errno == EINTR) {
                fprintf(stderr, "Nanosleep interrupted\n");
            } else {
                fprintf(stderr, "Error: Nanosleep failed: %s\n", strerror(errno));
                break;
            }
        }
    }

    // Cleanup
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    gpio_unexport(GPIO_PIN);

    return 0;
}

