#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define ADXL335 sensitivity (300mV/g)
#define SENSITIVITY 0.3

// Define voltage reference
#define VREF 3.3

// Define Kalman filter parameters
#define Q 0.001  // Process noise covariance
#define R 0.1    // Measurement noise covariance

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state variables
float x_state = 0.0;
float y_state = 0.0;
float z_state = 0.0;

float x_error = 1.0; // Initial error covariance
float y_error = 1.0;
float z_error = 1.0;

// Function prototypes
int initialize_spi();
int read_adc_channel(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_g(float voltage);
void kalman_filter(float measurement, float *state, float *error);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read ADC channel
int read_adc_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to convert voltage to g-force
float voltage_to_g(float voltage) {
    return voltage / SENSITIVITY;
}

// Kalman filter function
void kalman_filter(float measurement, float *state, float *error) {
    // Prediction step
    float predicted_state = *state;
    float predicted_error = *error + Q;

    // Update step
    float kalman_gain = predicted_error / (predicted_error + R);
    *state = predicted_state + kalman_gain * (measurement - predicted_state);
    *error = (1 - kalman_gain) * predicted_error;
}

// Function to perform cleanup
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008 initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int x_adc = read_adc_channel(0);
        int y_adc = read_adc_channel(1);
        int z_adc = read_adc_channel(2);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Convert ADC values to voltage
        float x_voltage = adc_to_voltage(x_adc);
        float y_voltage = adc_to_voltage(y_adc);
        float z_voltage = adc_to_voltage(z_adc);

        // Convert voltage to g-force
        float x_g = voltage_to_g(x_voltage);
        float y_g = voltage_to_g(y_voltage);
        float z_g = voltage_to_g(z_voltage);

        // Apply Kalman filter
        kalman_filter(x_g, &x_state, &x_error);
        kalman_filter(y_g, &y_state, &y_error);
        kalman_filter(z_g, &z_state, &z_error);

        // Print filtered values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_state, y_state, z_state);

        // Delay for 100ms (10 Hz)
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

