#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to read the digital state of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to convert a digital state to a magnetic field strength in millitesla
float convert_to_mT(int digital_state) {
    float voltage = (digital_state == 1) ? 3.3 : 0.0;
    float magnetic_field = (voltage / 3.3) * 200.0 - 100.0;
    return magnetic_field;
}

// Function to log the magnetic field values to a file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1; // Indicate an error
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Check for out-of-range values and print warnings
    if (sensor1_mT < -100.0 || sensor1_mT > 100.0) {
        fprintf(stderr, "%s - WARNING: Sensor 1 value out of range: %.2f mT\n", timestamp, sensor1_mT);
    }
    if (sensor2_mT < -100.0 || sensor2_mT > 100.0) {
        fprintf(stderr, "%s - WARNING: Sensor 2 value out of range: %.2f mT\n", timestamp, sensor2_mT);
    }
    if (sensor3_mT < -100.0 || sensor3_mT > 100.0) {
        fprintf(stderr, "%s - WARNING: Sensor 3 value out of range: %.2f mT\n", timestamp, sensor3_mT);
    }

    // Write the data to the file
    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);

    // Flush the file buffer to ensure data is written immediately
    fflush(fp);

    // Close the file
    fclose(fp);
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read the sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading sensors, skipping logging.\n");
            gpioDelay(100); // Wait 100ms before the next iteration
            continue;
        }

        // Convert the sensor values to magnetic field strengths
        float sensor1_mT = convert_to_mT(sensor1_value);
        float sensor2_mT = convert_to_mT(sensor2_value);
        float sensor3_mT = convert_to_mT(sensor3_value);

        // Log the data
        if (log_data(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

