// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define SPI_MODE 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 30
#define READ_INTERVAL 60 // seconds
#define LOG_FILE "watering.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        log_event("Error: SPI transfer failed.");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        log_event("Error: Invalid ADC value.");
        return -1.0;
    }
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the pump relay
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char message[100];
    snprintf(message, sizeof(message), "Pump turned %s", state ? "ON" : "OFF");
    log_event(message);
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

