    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    log_event("Program started.");

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        log_event("Error: SPI open failed.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int pump_state = 0; // 0 = off, 1 = on
    int last_adc_value = 0;

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Error reading ADC, retrying in 60 seconds.");
            gpioDelay(60000); // Wait 60 seconds
            continue;
        }

        float moisture_level = calculate_moisture(adc_value);
        if (moisture_level < 0) {
            log_event("Error calculating moisture, retrying in 60 seconds.");
            gpioDelay(60000); // Wait 60 seconds
            continue;
        }

        char message[100];
        snprintf(message, sizeof(message), "ADC Value: %d, Moisture Level: %.2f%%", adc_value, moisture_level);
        log_event(message);

        // Control pump based on moisture level
        if (moisture_level < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
            control_pump(1);
            pump_state = 1;
        } else if (moisture_level >= MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
            control_pump(0);
            pump_state = 0;
        }

        gpioDelay(READ_INTERVAL * 1000); // Wait for READ_INTERVAL seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_pump(0);
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

