#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

// SPI device and settings
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// MCP3008 channel definitions
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define MCP3008_CHANNEL_2 2

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int spi_fd = -1;
FILE *csv_file = NULL;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits_per_word, uint32_t speed);
int read_mcp3008(int spi_fd, int channel);
int log_data(FILE *fp, int channel0, int channel1, int channel2);
void signal_handler(int signal);

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint8_t bits_per_word, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from MCP3008 channel
int read_mcp3008(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log data to CSV file
int log_data(FILE *fp, int channel0, int channel1, int channel2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, channel0, channel1, channel2) < 0) {
        perror("Error writing to CSV file");
        return -1;
    }

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (csv_file != NULL) {
        fclose(csv_file);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        return 1;
    }

    // Open CSV file for logging
    csv_file = fopen("sensor_data.csv", "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        int channel0_value = read_mcp3008(spi_fd, MCP3008_CHANNEL_0);
        int channel1_value = read_mcp3008(spi_fd, MCP3008_CHANNEL_1);
        int channel2_value = read_mcp3008(spi_fd, MCP3008_CHANNEL_2);

        if (channel0_value == -1 || channel1_value == -1 || channel2_value == -1) {
            fprintf(stderr, "Error reading from MCP3008, exiting...\n");
            break;
        }

        if (log_data(csv_file, channel0_value, channel1_value, channel2_value) == -1) {
            fprintf(stderr, "Error logging data, exiting...\n");
            break;
        }

        fflush(csv_file); // Flush the buffer to ensure data is written to the file
        sleep(1); // Wait for 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(spi_fd);
    fclose(csv_file);

    return 0;
}

