#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60 // seconds

// Global variables
static volatile int running = 1;
static int led_state = 0; // 0 = off, 1 = on
static int reconnect_delay = 1;
static int sockfd = -1; // Socket file descriptor

// Function prototypes
void signal_handler(int signal);
int connect_mqtt();
void on_connect(int rc);
void on_message(const char *topic, const char *payload);
int parse_json(const char *payload, int *led_state);
void set_led(int state);
void log_message(const char *message);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Connect to MQTT broker
int connect_mqtt() {
    struct sockaddr_in serv_addr;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error opening socket");
        return -1;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(MQTT_PORT);

    if (inet_pton(AF_INET, MQTT_BROKER, &serv_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Error connecting to MQTT broker");
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    printf("Connected to MQTT broker\n");
    return 0;
}

// MQTT connect callback
void on_connect(int rc) {
    if (rc == 0) {
        printf("Connected to MQTT broker with return code %d\n", rc);
        // Subscribe to the topic
        char subscribe_topic[256];
        snprintf(subscribe_topic, sizeof(subscribe_topic), "%s", MQTT_TOPIC);

        // Create the subscribe message
        char subscribe_message[256];
        snprintf(subscribe_message, sizeof(subscribe_message), "SUBSCRIBE %s 1\n", subscribe_topic);

        // Send the subscribe message
        send(sockfd, subscribe_message, strlen(subscribe_message), 0);
        printf("Subscribed to topic: %s\n", subscribe_topic);
    } else {
        fprintf(stderr, "Connection failed with return code %d\n", rc);
    }
}

// MQTT message callback
void on_message(const char *topic, const char *payload) {
    printf("Received message on topic: %s, payload: %s\n", topic, payload);

    int new_led_state;
    if (parse_json(payload, &new_led_state) == 0) {
        led_state = new_led_state;
        set_led(led_state);
    } else {
        fprintf(stderr, "Error parsing JSON payload\n");
    }
}

// Parse JSON payload
int parse_json(const char *payload, int *led_state) {
    json_error_t error;
    json_t *root = json_loads(payload, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return -1;
    }

    json_t *led_state_json = json_object_get(root, "led_state");
    if (!led_state_json) {
        fprintf(stderr, "Error: 'led_state' key not found in JSON\n");
        json_decref(root);
        return -1;
    }

    if (!json_is_boolean(led_state_json)) {
        fprintf(stderr, "Error: 'led_state' value is not a boolean\n");
        json_decref(root);
        return -1;
    }

    *led_state = json_boolean_value(led_state_json);
    json_decref(root);
    return 0;
}

// Set LED state
void set_led(int state) {
    gpioWrite(GPIO_PIN, state);
    printf("LED set to %d\n", state);
}

// Log message with timestamp
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn off LED initially

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Connect to MQTT broker
    if (connect_mqtt() != 0) {
        log_message("Failed to connect to MQTT broker. Exiting.");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        char buffer[1024];
        ssize_t bytes_received = recv(sockfd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            printf("Received: %s", buffer);

            // Process MQTT messages (very basic example)
            // In a real application, you would parse the MQTT protocol
            // and call the appropriate callbacks (on_connect, on_message).
            // This is a placeholder to demonstrate the structure.

            // For example, if the received data is a CONNECT message:
            // on_connect(0); // Assuming return code 0 for success

            // If the received data is a PUBLISH message:
            // on_message("home/led_control", "true"); // Example payload

        } else if (bytes_received == 0) {
            printf("MQTT broker disconnected\n");
            running = 0; // Exit loop if broker disconnects
        } else {
            perror("Error receiving data");
            running = 0; // Exit loop on error
        }

        if (!running) {
            // Attempt to reconnect with exponential backoff
            printf("Attempting to reconnect in %d seconds...\n", reconnect_delay);
            sleep(reconnect_delay);
            reconnect_delay *= 2;
            if (reconnect_delay > MAX_RECONNECT_DELAY) {
                reconnect_delay = MAX_RECONNECT_DELAY;
            }
            if (connect_mqtt() != 0) {
                log_message("Failed to reconnect to MQTT broker.");
            } else {
                reconnect_delay = 1; // Reset delay on successful reconnection
            }
        }
    }

    // Clean up
    printf("Cleaning up...\n");
    if (sockfd != -1) {
        close(sockfd);
    }
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio

    printf("Exiting.\n");
    return 0;
}

