#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to trigger the alarm
void trigger_alarm() {
    gpioWrite(ALARM_LED_PIN, 1); // Turn LED on
    gpioDelay(1000);             // Wait for 1 second
    gpioWrite(ALARM_LED_PIN, 0); // Turn LED off
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    fprintf(stderr, "Sound sensor monitoring started. Press Ctrl-C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor();

        if (sound_level == 0) {
            trigger_alarm();
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    fprintf(stderr, "GPIO resources released. Exiting.\n");

    return 0;
}

