#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <poll.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "Signal received, terminating...\n");
}

int main() {
    int gpio_handle;
    int log_fd;
    struct timespec ts;
    char timestamp[30];
    char log_message[100];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd == -1) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Main loop
    while (!terminate) {
        // Read GPIO level
        int level = gpioRead(GPIO_PIN);

        // Check for falling edge
        if (level == 0) {
            // Get current timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                struct tm *tm_info = localtime(&ts.tv_sec);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
                snprintf(log_message, sizeof(log_message), "%s.%09ld Vibration detected! Initiating shutdown.\n", timestamp, ts.tv_nsec);

                // Log message to file
                if (write(log_fd, log_message, strlen(log_message)) == -1) {
                    perror("Error writing to log file");
                }

                // Print message to stdout
                printf("%s", log_message);

                // Initiate shutdown
                system("sudo shutdown -h now");
                break; // Exit loop after shutdown is initiated
            } else {
                perror("Error getting timestamp");
            }
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Clean up
    close(log_fd);
    gpioTerminate();

    return 0;
}

