#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_STATUS 0xF3
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP 2 // x2
#define BMP280_OVERSAMPLING_PRESS 5 // x16
#define BMP280_MODE_NORMAL 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function prototypes
int init_bmp280();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
double calculate_altitude(double pressure);
int log_data(double altitude);
void signal_handler(int signal);

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize the BMP280 sensor
int init_bmp280() {
    // Check chip ID
    char chip_id;
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CHIPID, &chip_id, 1) != 1) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%02x\n", chip_id);
        return -1;
    }

    // Read calibration data
