        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, skipping sample\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Convert ADC value to temperature
        float temperature = adc_to_temperature(adc_value);

        // Add temperature to buffer
        add_to_buffer(temperature);

        // Print temperature
        print_buffer();

        // Write buffer to file
        write_buffer_to_file("temp_log.dat");

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Close SPI interface and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

