#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define MCP3008_CHANNEL 0
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
int spi_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int init_spi();
int read_bh1750(int fd);
int read_mcp3008(int fd, int channel);
void log_data(FILE *fp, int light_level, int sound_level);
void signal_handler(int signal);
void cleanup();

// I2C initialization function
int init_i2c() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI initialization function
int init_spi() {
    int fd = open(SPI_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI bus");
        return -1;
    }

    // Configure SPI mode (CPOL=0, CPHA=0)
    unsigned char mode = 0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed (adjust as needed)
    unsigned int speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read light level from BH1750 sensor
int read_bh1750(int fd) {
    unsigned char config = 0x10; // Continuous high resolution mode
    if (write(fd, &config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(200000); // Wait for measurement (at least 180ms)

    unsigned char buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return (int)(raw_value / 1.2); // Convert to lux
}

// Function to read sound level from MCP3008 ADC
int read_mcp3008(int fd, int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;                  // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buffer,
        .rx_buf = (unsigned long)rx_buffer,
        .len = 3,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to log data to file
void log_data(FILE *fp, int light_level, int sound_level) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Light: %d lux, Sound: %d\n", timestamp, light_level, sound_level);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C and SPI
    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    spi_fd = init_spi();
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        int light_level = read_bh1750(i2c_fd);
        int sound_level = read_mcp3008(spi_fd, MCP3008_CHANNEL);

        if (light_level >= 0 && sound_level >= 0) {
            log_data(log_file, light_level, sound_level);
        } else {
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
            fprintf(log_file, "%s, Error reading sensor data\n", timestamp);
            fflush(log_file);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

