#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_PIN 17
#define LOG_FILE "flame_events.log"

static volatile int running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int pigpio_init_result;
    int gpio_mode_result;
    int gpio_read_result;
    int log_file_open_result;
    int log_file_write_result;
    int alarm_print_result;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];
    int flame_detected;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO pin 17 as an input with a pull-down resistor
    gpio_mode_result = gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    if (gpio_mode_result != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %d\n", FLAME_SENSOR_PIN, gpio_mode_result);
        gpioTerminate();
        return 1;
    }

    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_DOWN);

    // Open the log file in append mode
    log_file_open_result = fopen(LOG_FILE, "a");
    if (log_file_open_result == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }
    log_file = log_file_open_result;

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to read the sensor and log data
    while (running) {
        // Read the digital value from the GPIO pin
        flame_detected = gpioRead(FLAME_SENSOR_PIN);

        // Get current timestamp
        current_time = time(NULL);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Log the data to the CSV file
        log_file_write_result = fprintf(log_file, "%s,%d,%d\n", timestamp, FLAME_SENSOR_PIN, flame_detected);
        if (log_file_write_result < 0) {
            fprintf(stderr, "Failed to write to log file\n");
        }
        fflush(log_file); // Ensure data is written to disk immediately

        // Check if a flame is detected (HIGH signal)
        if (flame_detected == 1) {
            alarm_print_result = printf("ALARM: Flame detected at %s\n", timestamp);
            if (alarm_print_result < 0) {
                fprintf(stderr, "Failed to print alarm message\n");
            }
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function takes milliseconds
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

