int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len);
int spi_close(void);
int i2c_init(void);
int i2c_write(uint8_t reg, uint8_t *data, int len);
int i2c_read(uint8_t reg, uint8_t *data, int len);
int mcp3008_read(int channel);
float adc_to_celsius(int adc_value);
float celsius_to_voltage(float temperature);
int mcp4725_write(float voltage);
int log_data(int adc_value, float temperature, float voltage);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Configure SPI clock speed
    uint32_t speed = 500000; // 500 kHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// SPI transfer
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 500000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// SPI close
int spi_close(void) {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    return 0;
}

// I2C initialization
int i2c_init(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MCP4725_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// I2C write
int i2c_write(uint8_t reg, uint8_t *data, int len) {
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);

    if (write(i2c_fd, buf, len + 1) != len + 1) {
        perror("Error during I2C write");
        return -1;
    }

    return 0;
}

