#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SENSOR_CHANNELS {0, 1, 2}
#define NUM_SENSORS 3
#define SLEEP_DURATION 60 // seconds
#define LOG_FILE "soil_data.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_adc(int channel);
float calculate_moisture(int adc_value);
int log_data(float moisture1, float moisture2, float moisture3);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float moisture1;
    float moisture2;
    float moisture3;
} SensorData;

// Function to initialize the pigpio library and SPI interface
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read data from the MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate moisture percentage from ADC value
float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }

    // Linear relationship: 0 ADC = 0% moisture, 1023 ADC = 100% moisture
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to log data to a file
int log_data(float moisture1, float moisture2, float moisture3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, moisture1, moisture2, moisture3);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close SPI, log file, and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Goodbye!\n");
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed, exiting\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_values[NUM_SENSORS];
        float moisture_values[NUM_SENSORS];

        // Read ADC values from each sensor
        for (int i = 0; i < NUM_SENSORS; i++) {
            adc_values[i] = read_adc(SENSOR_CHANNELS[i]);
            if (adc_values[i] < 0) {
                fprintf(stderr, "Failed to read ADC value from channel %d\n", SENSOR_CHANNELS[i]);
                moisture_values[i] = -1.0; // Indicate error
            } else {
                moisture_values[i] = calculate_moisture(adc_values[i]);
                if (moisture_values[i] < 0) {
                    fprintf(stderr, "Failed to calculate moisture for channel %d\n", SENSOR_CHANNELS[i]);
                }
            }
        }

        // Log data
        if (log_data(moisture_values[0], moisture_values[1], moisture_values[2]) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Sleep for 60 seconds
        gpioSleep(PI_TIME_RELATIVE, SLEEP_DURATION, 0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

