#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define IN1 17
#define IN2 18
#define ENA 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define rain threshold
#define RAIN_THRESHOLD 5

// Define motor control duration
#define MOTOR_DURATION 3 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rain_sensor();
void control_motor(int direction);
void log_data(int rain_level);
void signal_handler(int signal);

// Function to read the rain sensor value from MCP3008
int read_rain_sensor() {
    char tx_buffer[3];
    char rx_buffer[3];

    // MCP3008 configuration: single-ended channel 0
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80; // Single-ended, channel 0
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract the 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the motor direction
void control_motor(int direction) {
    if (direction == 1) { // Forward
        gpioWrite(IN1, 1);
        gpioWrite(IN2, 0);
        gpioPWM(ENA, 150); // 150/255 duty cycle
        printf("Motor: Forward\n");
    } else if (direction == -1) { // Reverse
        gpioWrite(IN1, 0);
        gpioWrite(IN2, 1);
        gpioPWM(ENA, 150); // 150/255 duty cycle
        printf("Motor: Reverse\n");
    } else { // Stop
        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
        gpioPWM(ENA, 0); // Stop PWM
        printf("Motor: Stop\n");
    }
}

// Function to log data to a file
void log_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d\n", timestamp, rain_level);
        fflush(log_file); // Flush the buffer to ensure data is written
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initial window state
    int window_open = 1;

    // Main loop
    while (!terminate) {
        // Read rain sensor value
        int rain_level = read_rain_sensor();
        if (rain_level < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor\n");
            continue; // Skip to the next iteration
        }

        // Log the data
        log_data(rain_level);

        // Control the motor based on rain level and window state
        if (rain_level > RAIN_THRESHOLD && window_open) {
            control_motor(1); // Open the window
            window_open = 0;
            gpioDelay(MOTOR_DURATION * 1000000); // Delay for 3 seconds
            control_motor(0); // Stop the motor
        } else if (rain_level <= RAIN_THRESHOLD && !window_open) {
            control_motor(-1); // Close the window
            window_open = 1;
            gpioDelay(MOTOR_DURATION * 1000000); // Delay for 3 seconds
            control_motor(0); // Stop the motor
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_motor(0); // Stop the motor
    spiClose(spi_handle); // Close SPI
    fclose(log_file); // Close log file
    gpioTerminate(); // Terminate pigpio

    return 0;
}

