#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define PUMP_ON_TIME 5 // seconds
#define LOG_FILE "soil_moisture.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float adc_to_moisture(int adc_value);
void control_pump(int pump_state);
void log_data(float moisture_percentage, int pump_status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Convert ADC value to moisture percentage
float adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }

    // Linear conversion (adjust as needed based on sensor calibration)
    float moisture_percentage = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return moisture_percentage;
}

// Control the water pump
void control_pump(int pump_state) {
    gpioWrite(PUMP_GPIO, pump_state);
}

// Log data to file
void log_data(float moisture_percentage, int pump_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %s\n", timestamp, moisture_percentage, pump_status ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            log_data(-1.0, gpioRead(PUMP_GPIO)); // Log error
            gpioDelay(60000); // Wait 60 seconds
            continue;
        }

        float moisture_percentage = adc_to_moisture(adc_value);
        if (moisture_percentage < 0) {
            fprintf(stderr, "Failed to convert ADC value to moisture percentage\n");
            log_data(-1.0, gpioRead(PUMP_GPIO)); // Log error
            gpioDelay(60000); // Wait 60 seconds
            continue;
        }

        int pump_status = gpioRead(PUMP_GPIO);
        log_data(moisture_percentage, pump_status);

        if (moisture_percentage < MOISTURE_THRESHOLD && !pump_status) {
            printf("Moisture level below threshold. Activating pump.\n");
            control_pump(1); // Turn pump ON
            log_data(moisture_percentage, 1); // Log pump status
            gpioDelay(PUMP_ON_TIME * 1000); // Wait for pump on time
            control_pump(0); // Turn pump OFF
            log_data(moisture_percentage, 0); // Log pump status
            printf("Pump deactivated.\n");
        }

        gpioDelay(60000); // Wait 60 seconds
    }

    // Graceful shutdown
    printf("Shutting down...\n");
    control_pump(0); // Turn pump OFF
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

