int read_mcp3008(int channel);
float adc_to_magnetic_field(int adc_value);
int log_data(float magnetic_field);
void control_led(float magnetic_field);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    int led_gpio;
    float magnetic_field_threshold;
    int sample_interval_ms;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL,
    LED_GPIO,
    MAGNETIC_FIELD_THRESHOLD,
    SAMPLE_INTERVAL_MS
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        float magnetic_field = adc_to_magnetic_field(adc_value);
        log_data(magnetic_field);
        control_led(magnetic_field);

        gpioDelay(config.sample_interval_ms * 1000); // Delay in microseconds
    }

    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);
    gpioWrite(config.led_gpio, 0); // Initially off

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

float adc_to_magnetic_field(int adc_value) {
    // Linear relationship: 0 ADC = 0 mT, 1023 ADC = 20 mT
    return (float)adc_value * (20.0 / 1023.0);
}

int log_data(float magnetic_field) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f mT\n", timestamp, magnetic_field);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

void control_led(float magnetic_field) {
    if (magnetic_field > config.magnetic_field_threshold) {
        gpioWrite(config.led_gpio, 1); // Turn on LED
    } else {
        gpioWrite(config.led_gpio, 0); // Turn off LED
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(config.led_gpio, 0); // Turn off LED
    gpioTerminate();
    fclose(log_file);

    exit(0);
}

