#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 2

// Number of readings for debouncing
#define DEBOUNCE_READINGS 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read a sensor with debouncing
int read_sensor(int gpio) {
    int readings[DEBOUNCE_READINGS];
    int i;

    // Read the sensor multiple times with a small delay
    for (i = 0; i < DEBOUNCE_READINGS; i++) {
        readings[i] = gpioRead(gpio);
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
    }

    // Determine the majority value
    int low_count = 0;
    int high_count = 0;
    for (i = 0; i < DEBOUNCE_READINGS; i++) {
        if (readings[i] == 0) {
            low_count++;
        } else {
            high_count++;
        }
    }

    return (low_count > high_count) ? 0 : 1; // 0 for object present, 1 for no object
}

// Function to log sensor data
void log_sensor_data(int sensor1_state, int sensor2_state) {
    printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_state, sensor2_state);
}

// Function to check for simultaneous object detection
void check_simultaneous_detection(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 0 && sensor2_state == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for the sensors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Set pull-up resistors (internal pull-up is already enabled on the sensor)
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor states
        int sensor1_state = read_sensor(SENSOR_1_GPIO);
        int sensor2_state = read_sensor(SENSOR_2_GPIO);

        // Log sensor data
        log_sensor_data(sensor1_state, sensor2_state);

        // Check for simultaneous object detection
        check_simultaneous_detection(sensor1_state, sensor2_state);

        // Wait for 1 second
        sleep(1);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

