#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Configuration
#define PIR_GPIO 17
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define MOTION_DEBOUNCE_MS 200
#define CAPTURE_DIR "/home/pi/security_cam"
#define LOG_FILE "/var/log/security_cam.log"

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fd;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
int read_pir_sensor();
int read_light_sensor();
int capture_image();
void log_event(const char *message);
void signal_handler(int signal);
int create_directory(const char *path);

// Function to create a directory if it doesn't exist
int create_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == -1) {
        if (mkdir(path, 0777) == -1) {
            perror("mkdir");
            return -1;
        }
    }
    return 0;
}

// Function to initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    syslog(LOG_INFO, "GPIO initialisation successful");
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    syslog(LOG_INFO, "I2C initialisation successful");
    return 0;
}

// Function to read the PIR sensor state
int read_pir_sensor() {
    return gpioRead(PIR_GPIO);
}

// Function to read the light sensor value
int read_light_sensor() {
    unsigned char buffer[2];
    if (read(i2c_fd, buffer, 2) != 2) {
        syslog(LOG_ERR, "Failed to read light sensor data");
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

// Function to capture an image using libcamera-still
int capture_image() {
    char filename[256];
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), CAPTURE_DIR "/%Y%m%d_%H%M%S.jpg", timeinfo);

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        char *args[] = {"libcamera-still", "-o", filename, NULL};
        execvp(args[0], args);
        perror("execvp");
        exit(EXIT_FAILURE);
    } else if (pid < 0) {
        // Fork failed
        syslog(LOG_ERR, "Fork failed");
        return -1;
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
            syslog(LOG_ERR, "Image capture failed with exit code %d", WEXITSTATUS(status));
            return -1;
        }
        syslog(LOG_INFO, "Image captured: %s", filename);
        return 0;
    }
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    syslog(LOG_INFO, "Signal received, shutting down...");
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize syslog
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    // Create the capture directory
    if (create_directory(CAPTURE_DIR) != 0) {
        syslog(LOG_ERR, "Failed to create capture directory");
        closelog();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialisation failed, exiting");
        closelog();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        syslog(LOG_ERR, "I2C initialisation failed, exiting");
        gpioTerminate();
        closelog();
        return 1;
    }

    int last_pir_state = 0;
    int light_level = 0;
    time_t last_capture_time = 0;

    log_event("Security camera started");

    while (program_running) {
        int pir_state = read_pir_sensor();
        if (pir_state < 0) {
            syslog(LOG_ERR, "Failed to read PIR sensor");
        } else {
            if (pir_state != last_pir_state) {
                last_pir_state = pir_state;
                gpioDelay(MOTION_DEBOUNCE_MS * 1000); // Debounce

                if (read_pir_sensor() == pir_state) {
                    // Motion confirmed
                    log_event("Motion detected");

                    int current_light_level = read_light_sensor();
                    if (current_light_level < 0) {
                        syslog(LOG_ERR, "Failed to read light sensor");
                    } else {
                        light_level = current_light_level;

                        time_t now = time(NULL);
                        if (now - last_capture_time > 5) {
                            if (capture_image() == 0) {
                                last_capture_time = now;
                            } else {
                                syslog(LOG_ERR, "Image capture failed");
                            }
                        } else {
                            syslog(LOG_INFO, "Capture suppressed due to rate limiting");
                        }
                    }
                }
            }
        }

        gpioDelay(50 * 1000); // Poll every 50ms
    }

    // Cleanup
    close(i2c_fd);
    gpioTerminate();
    closelog();

    log_event("Security camera stopped");

    return 0;
}

