int init_camera(camera_device_t *camera, int fd) {
    if (ioctl(fd, VIDIOC_QUERYCAP, &camera->cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (!(camera->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(camera->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    camera->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    camera->fmt.fmt.pix.width = IMAGE_WIDTH;
    camera->fmt.fmt.pix.height = IMAGE_HEIGHT;
    camera->fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    camera->fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &camera->fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    camera->req.count = NUM_BUFFERS;
    camera->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    camera->req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &camera->req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    camera->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    camera->buf.memory = V4L2_MEMORY_MMAP;
    camera->buf.index = 0;

