        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        return -1;
    }

    camera->buffer = mmap(NULL, camera->req.size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (camera->buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        return -1;
    }

    camera->buffer_size = camera->req.size;

    return 0;
}

