int unmap_buffer(camera_device_t *camera) {
    if (munmap(camera->buffer, camera->buffer_size) < 0) {
        fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

