                    if (dequeue_buffer(&camera) < 0) {
                        fprintf(stderr, "Error dequeuing buffer after select: %s\n", strerror(errno));
                        break;
                    }
                }
            } else {
                // Other error occurred, break the loop
                break;
            }
        }

