#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define FRAME_LOG_FILE "frame_log.txt"
#define BUFFER_COUNT 4

// Structure to hold video buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

// Global variables
static int                  fd = -1;          // File descriptor for the video device
static buffer_t             buffers[BUFFER_COUNT]; // Array to store video buffers
static unsigned int          n_buffers = 0;       // Number of buffers
static FILE                *log_file = NULL;    // File pointer for the log file
static volatile sig_atomic_t terminate = 0; // Flag to signal termination

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the video device
int initialize_device() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening video device");
        return -1;
    }

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying device capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    // Set video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;  // Example width
    fmt.fmt.pix.height = 480; // Example height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // MJPEG format
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting video format");
        close(fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    n_buffers = req.count;

    // Map the buffers
    for (i = 0; i < n_buffers; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            return -1;
        }
    }

    return 0;
}

// Function to start video streaming
int start_streaming() {
    unsigned int i;
    struct v4l2_buffer buf;

    for (i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting streaming");
        return -1;
    }

    return 0;
}

// Function to stop video streaming
int stop_streaming() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping streaming");
        return -1;
    }
    return 0;
}

// Function to unmap the buffers
int unmap_buffers() {
    unsigned int i;
    for (i = 0; i < n_buffers; i++) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
    }
    return 0;
}

// Function to close the video device
int close_device() {
    if (close(fd) < 0) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

// Function to log the timestamp to a file
int log_timestamp() {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Error getting timestamp");
        return -1;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
    return 0;
}

// Function to capture a frame
int capture_frame() {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error in select()");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout occurred\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    if (log_timestamp() < 0) {
        fprintf(stderr, "Error logging timestamp\n");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the video device
    if (initialize_device() < 0) {
        fprintf(stderr, "Error initializing device\n");
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(FRAME_LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        unmap_buffers();
        close_device();
        return EXIT_FAILURE;
    }

    // Start video streaming
    if (start_streaming() < 0) {
