            break; // Exit loop on error
        }
    }

    // Stop video streaming
    if (stop_streaming() < 0) {
        fprintf(stderr, "Error stopping streaming\n");
    }

    // Unmap the buffers
    if (unmap_buffers() < 0) {
        fprintf(stderr, "Error unmapping buffers\n");
    }

    // Close the log file
    if (fclose(log_file) < 0) {
        perror("Error closing log file");
    }

    // Close the video device
    if (close_device() < 0) {
        fprintf(stderr, "Error closing device\n");
    }

    return EXIT_SUCCESS;
}

