#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <sys/time.h>

#define DEVICE_NAME "/dev/video0"
#define UDP_IP "127.0.0.1" // Replace with your target IP
#define UDP_PORT 5000        // Replace with your target port
#define MAX_DGRAM_SIZE 65000
#define NUM_BUFFERS 4

// Structure to hold frame data
typedef struct {
    void *start;
    size_t length;
} buffer_t;

// Global variables
static int fd = -1;
static buffer_t buffers[NUM_BUFFERS];
static int num_buffers = NUM_BUFFERS;
static int buffer_size = 0;
static int frame_index = 0;
static int fragment_index = 0;
static int total_fragments = 0;
static int udp_socket = -1;
static struct sockaddr_in target_addr;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int open_device(const char *device_name);
int init_device(int fd);
int start_capturing(int fd);
int stop_capturing(int fd);
int close_device(int fd);
int init_udp_socket(const char *ip_address, int port);
int send_udp_packet(int socket_fd, const void *data, size_t data_len, int frame_index, int fragment_index, int total_fragments, size_t payload_size);
void signal_handler(int sig);
int fragment_frame(const void *frame_data, size_t frame_size, const void *header, size_t header_size, int frame_index, int fragment_index, int total_fragments, int socket_fd);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Open the V4L2 device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

// Initialize the V4L2 device
int init_device(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    // Set video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Example width
    fmt.fmt.pix.height = 480; // Example height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV; // YUYV format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    // Map buffers
    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            return -1;
        }

        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            return -1;
        }

        buffers[i].length = buf.length;
        buffer_size = buf.length; // Store the buffer size
    }

    return 0;
}

// Start capturing
int start_capturing(int fd) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "Error queuing buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Stop capturing
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Close the V4L2 device
int close_device(int fd) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            fprintf(stderr, "Error unmapping buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }

    if (close(fd) == -1) {
        fprintf(stderr, "Error closing device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize UDP socket
int init_udp_socket(const char *ip_address, int port) {
    int socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd == -1) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    memset(&target_addr, 0, sizeof(target_addr));
    target_addr.sin_family = AF_INET;
    target_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip_address, &target_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        close(socket_fd);
        return -1;
    }

    return socket_fd;
}

// Send UDP packet
int send_udp_packet(int socket_fd, const void *data, size_t data_len, int frame_index, int fragment_index, int total_fragments, size_t payload_size) {
    struct {
        int frame_index;
        int fragment_index;
        int total_fragments;
        size_t payload_size;
    } header;

    header.frame_index = frame_index;
    header.fragment_index = fragment_index;
    header.total_fragments = total_fragments;
    header.payload_size = payload_size;

    size_t header_size = sizeof(header);
    size_t total_size = header_size + data_len;

    if (total_size > MAX_DGRAM_SIZE) {
        fprintf(stderr, "Error: Datagram size exceeds maximum limit (%zu > %d)\n", total_size, MAX_DGRAM_SIZE);
        return -1;
    }

    if (sendto(socket_fd, &header, header_size, 0, (struct sockaddr *)&target_addr, sizeof(target_addr)) == -1) {
        fprintf(stderr, "Error sending header: %s\n", strerror(errno));
        return -1;
    }

    if (sendto(socket_fd, data, data_len, 0, (struct sockaddr *)&target_addr, sizeof(target_addr)) == -1) {
        fprintf(stderr, "Error sending data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Fragment frame into UDP datagrams
int fragment_frame(const void *frame_data, size_t frame_size, const void *header, size_t header_size, int frame_index, int fragment_index, int total_fragments, int socket_fd) {
    size_t remaining_data = frame_size;
    size_t data_to_send = 0;
    const char *data_ptr = (const char *)frame_data;

    while (remaining_data > 0) {
        if (data_to_send == 0) {
            data_to_send = (remaining_data > MAX_DGRAM_SIZE - header_size) ? MAX_DGRAM_SIZE - header_size : remaining_data;
        }

        if (send_udp_packet(socket_fd, data_ptr, data_to_send, frame_index, fragment_index, total_fragments, data_to_send) == -1) {
            fprintf(stderr, "Error sending fragment %d of frame %d\n", fragment_index, frame_index);
            return -1;
        }

        data_ptr += data_to_send;
        remaining_data -= data_to_send;
        fragment_index++;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the V4L2 device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Initialize the V4L2 device
    if (init_device(fd) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Initialize UDP socket
    udp_socket = init_udp_socket(UDP_IP, UDP_PORT);
    if (udp_socket == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Start capturing
    if (start_capturing(fd) == -1) {
        close_device(fd);
        close(udp_socket);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            break;
        }

        // Calculate number of fragments
        total_fragments = (buffer_size > MAX_DGRAM_SIZE) ? (buffer_size / MAX_DGRAM_SIZE) + ((buffer_size % MAX_DGRAM_SIZE) ? 1 : 0) : 1;

        // Fragment the frame
        if (fragment_frame(buffers[buf.index].start, buffer_size, NULL, 0, frame_index, 0, total_fragments, udp_socket) == -1) {
            fprintf(stderr, "Error fragmenting frame %d\n", frame_index);
            break;
        }

        // Increment frame index
        frame_index++;

        // Queue the buffer back
        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            break;
        }

        // Sleep for a short time
        usleep(10000); // 10ms
    }

    // Stop capturing
    if (stop_capturing(fd) == -1) {
        fprintf(stderr, "Error stopping stream\n");
    }

    // Close the V4L2 device
    if (close_device(fd) == -1) {
        fprintf(stderr, "Error closing device\n");
    }

    // Close the UDP socket
    if (close(udp_socket) == -1) {
        fprintf(stderr, "Error closing socket: %s\n", strerror(errno));
    }

    return EXIT_SUCCESS;
}

