#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "image.jpg"
#define WIDTH 192
#define HEIGHT 144
#define NUM_BUFFERS 4

// Structure to hold buffer information
struct buffer {
    void   *start;
    size_t  length;
};

// Global variables
static int                  fd                  = -1; // File descriptor for the video device
static struct buffer       *buffers             = NULL; // Array of buffer structures
static unsigned int         n_buffers           = 0;  // Number of buffers
static FILE                *image_file          = NULL; // File pointer for the image file
static volatile sig_atomic_t terminate          = 0;  // Flag to signal termination

// Function prototypes
int  open_device(void);
int  init_device(void);
int  start_capturing(void);
int  stop_capturing(void);
int  save_image(struct buffer *buffer);
void uninit_device(void);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nSignal received, stopping...\n");
}

// Function to open the video device
int open_device(void) {
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }
    return 0;
}

// Function to initialize the video device
int init_device(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    // Query device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: Device does not support streaming\n");
        return -1;
    }

    // Set video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    n_buffers = req.count;
    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        return -1;
    }

    // Map the buffers
    for (i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }

    return 0;
}

// Function to start capturing
int start_capturing(void) {
    unsigned int i;
    struct v4l2_buffer buf;

    for (i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to stop capturing
int stop_capturing(void) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

// Function to save the image to a file
int save_image(struct buffer *buffer) {
    if (image_file == NULL) {
        fprintf(stderr, "Error: Image file is not open\n");
        return -1;
    }

    if (fwrite(buffer->start, 1, buffer->length, image_file) != buffer->length) {
        perror("Error writing to image file");
        return -1;
    }

    return 0;
}

// Function to uninitialize the device
void uninit_device(void) {
    unsigned int i;

    if (buffers != NULL) {
        for (i = 0; i < n_buffers; ++i) {
            if (buffers[i].start != NULL) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
    }

    if (fd != -1) {
        close(fd);
    }

    if (image_file != NULL) {
        fclose(image_file);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the image file
    image_file = fopen(IMAGE_FILE, "wb");
    if (image_file == NULL) {
        perror("Error opening image file");
        return EXIT_FAILURE;
    }

    // Open the video device
    if (open_device() < 0) {
        uninit_device();
        return EXIT_FAILURE;
    }

    // Initialize the video device
    if (init_device() < 0) {
        uninit_device();
        return EXIT_FAILURE;
    }

    // Start capturing
    if (start_capturing() < 0) {
        uninit_device();
        return EXIT_FAILURE;
    }

    // Dequeue a single frame
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        uninit_device();
        return EXIT_FAILURE;
    }

    // Verify bytesused
    if (buf.bytesused <= 0) {
        fprintf(stderr, "Error: bytesused is not greater than zero\n");
        uninit_device();
        return EXIT_FAILURE;
    }

    // Save the image
    if (save_image(&buffers[buf.index]) < 0) {
        uninit_device();
        return EXIT_FAILURE;
    }

    // Requeue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error requeuing buffer");
        uninit_device();
        return EXIT_FAILURE;
    }

    // Stop capturing
    if (stop_capturing() < 0) {
        uninit_device();
        return EXIT_FAILURE;
    }

    // Uninitialize the device
    uninit_device();

    printf("Image saved to %s\n", IMAGE_FILE);
    return EXIT_SUCCESS;
}

