#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_PIN 6
#define TILT_DOWN_PIN 7
#define PAN_LEFT_PIN 8
#define PAN_RIGHT_PIN 9

// Define PWM parameters
#define PWM_FREQUENCY 50
#define PWM_RANGE 1000

// Define servo limits
#define SERVO_MIN 25
#define SERVO_MAX 125

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_servo_position(int servo_pin, int position);
int read_button(int button_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set servo pins as outputs
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set button pins as inputs with pull-up resistors
    gpioSetMode(TILT_UP_PIN, PI_INPUT);
    gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP);
    gpioSetMode(TILT_DOWN_PIN, PI_INPUT);
    gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP);
    gpioSetMode(PAN_LEFT_PIN, PI_INPUT);
    gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP);
    gpioSetMode(PAN_RIGHT_PIN, PI_INPUT);
    gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    return 0;
}

// Set servo position
int set_servo_position(int servo_pin, int position) {
    if (position < SERVO_MIN || position > SERVO_MAX) {
        fprintf(stderr, "Error: Servo position out of range (%d)\n", position);
        return 1;
    }

    // Convert position to pulse width (1ms - 2ms)
    int pulse_width = (int)(((float)(position - SERVO_MIN) / (SERVO_MAX - SERVO_MIN)) * 1000 + 1000); // Corrected pulse width calculation

    gpioPWM(servo_pin, pulse_width);
    return 0;
}

// Read button state
int read_button(int button_pin) {
    return !gpioRead(button_pin); // Active-low
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize servo positions to mid-position
    set_servo_position(PAN_SERVO_PIN, 75);
    set_servo_position(TILT_SERVO_PIN, 75);

    // Main loop
    while (program_running) {
        // Read button states
        int tilt_up_pressed = read_button(TILT_UP_PIN);
        int tilt_down_pressed = read_button(TILT_DOWN_PIN);
        int pan_left_pressed = read_button(PAN_LEFT_PIN);
        int pan_right_pressed = read_button(PAN_RIGHT_PIN);

        // Adjust servo positions based on button presses
        if (tilt_up_pressed) {
            int current_tilt_position = gpioGetPWMdutycycle(TILT_SERVO_PIN) * PWM_RANGE / 1000; // Get current duty cycle and convert to position
            int new_tilt_position = current_tilt_position + 5;
            if (new_tilt_position > SERVO_MAX) {
                new_tilt_position = SERVO_MAX;
            }
            set_servo_position(TILT_SERVO_PIN, new_tilt_position);
        }
        if (tilt_down_pressed) {
            int current_tilt_position = gpioGetPWMdutycycle(TILT_SERVO_PIN) * PWM_RANGE / 1000; // Get current duty cycle and convert to position
            int new_tilt_position = current_tilt_position - 5;
            if (new_tilt_position < SERVO_MIN) {
                new_tilt_position = SERVO_MIN;
            }
            set_servo_position(TILT_SERVO_PIN, new_tilt_position);
        }
        if (pan_left_pressed) {
            int current_pan_position = gpioGetPWMdutycycle(PAN_SERVO_PIN) * PWM_RANGE / 1000; // Get current duty cycle and convert to position
            int new_pan_position = current_pan_position - 5;
            if (new_pan_position < SERVO_MIN) {
                new_pan_position = SERVO_MIN;
            }
            set_servo_position(PAN_SERVO_PIN, new_pan_position);
        }
        if (pan_right_pressed) {
            int current_pan_position = gpioGetPWMdutycycle(PAN_SERVO_PIN) * PWM_RANGE / 1000; // Get current duty cycle and convert to position
            int new_pan_position = current_pan_position + 5;
            if (new_pan_position > SERVO_MAX) {
                new_pan_position = SERVO_MAX;
            }
            set_servo_position(PAN_SERVO_PIN, new_pan_position);
        }

        // Delay
        gpioDelay(50000); // 50ms
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

