#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <time.h>
#include <jpeglib.h>
#include <setjmp.h>
#include <math.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

// Structure to hold camera parameters
typedef struct {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer;
    size_t buffer_size;
} camera_t;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the camera
int camera_init(camera_t *cam, const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cam->cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cam->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cam->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", device_name);
        close(fd);
        return -1;
    }

    CLEAR(cam->fmt);
    cam->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->fmt.fmt.pix.width = 640;  // Set desired width
    cam->fmt.fmt.pix.height = 480; // Set desired height
    cam->fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV; // Set desired format
    cam->fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &cam->fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    CLEAR(cam->req);
    cam->req.count = 1; // Single buffer
    cam->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &cam->req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    CLEAR(cam->buf);
    cam->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->buf.memory = V4L2_MEMORY_MMAP;
    cam->buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &cam->buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return -1;
    }

    cam->buffer_size = cam->buf.length;
    cam->buffer = mmap(NULL, cam->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, cam->buf.m.offset);
    if (cam->buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &cam->buf) < 0) {
        perror("Error queuing buffer");
        munmap(cam->buffer, cam->buffer_size);
        close(fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(cam->buffer, cam->buffer_size);
        close(fd);
        return -1;
    }

    cam->fd = fd;
    return 0;
}

// Function to capture a frame from the camera
int camera_capture(camera_t *cam, unsigned char **buffer) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(cam->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(cam->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    if (ioctl(cam->fd, VIDIOC_DQBUF, &cam->buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    *buffer = cam->buffer;
    return 0;
}

// Function to stop the camera stream
int camera_stop(camera_t *cam) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(cam->fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

// Function to unmap the camera buffer
int camera_unmap(camera_t *cam) {
    if (munmap(cam->buffer, cam->buffer_size) < 0) {
        perror("Error unmapping buffer");
        return -1;
    }
    return 0;
}

// Function to close the camera device
int camera_close(camera_t *cam) {
    if (close(cam->fd) < 0) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

// Function to convert YUYV to RGB24
void yuyv_to_rgb(unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int i = 0; i < width * height * 2; i += 4) {
        unsigned char Y1 = yuyv[i];
        unsigned char U = yuyv[i + 1];
        unsigned char Y2 = yuyv[i + 2];
        unsigned char V = yuyv[i + 3];

        // Convert YUV to RGB (using simplified conversion)
        int R1 = Y1 + 1.370705 * (V - 128);
        int G1 = Y1 - 0.698001 * (V - 128) - 0.336331 * (U - 128);
        int B1 = Y1 + 2.032112 * (U - 128);

        int R2 = Y2 + 1.370705 * (V - 128);
        int G2 = Y2 - 0.698001 * (V - 128) - 0.336331 * (U - 128);
        int B2 = Y2 + 2.032112 * (U - 128);

        // Clamp values to 0-255
        R1 = (R1 < 0) ? 0 : ((R1 > 255) ? 255 : R1);
        G1 = (G1 < 0) ? 0 : ((G1 > 255) ? 255 : G1);
        B1 = (B1 < 0) ? 0 : ((B1 > 255) ? 255 : B1);

        R2 = (R2 < 0) ? 0 : ((R2 > 255) ? 255 : R2);
        G2 = (G2 < 0) ? 0 : ((G2 > 255) ? 255 : G2);
        B2 = (B2 < 0) ? 0 : ((B2 > 255) ? 255 : B2);

        // Store RGB values
        rgb[i * 3] = (unsigned char)R1;
        rgb[i * 3 + 1] = (unsigned char)G1;
        rgb[i * 3 + 2] = (unsigned char)B1;

        rgb[i * 3 + 6] = (unsigned char)R2;
        rgb[i * 3 + 7] = (unsigned char)G2;
        rgb[i * 3 + 8] = (unsigned char)B2;
    }
}

// Function to apply a blur filter (simple averaging)
void apply_blur(unsigned char *rgb, int width, int height) {
    int new_width = width - 2;
    int new_height = height - 2;
    unsigned char *blurred = (unsigned char *)malloc(new_width * new_height * 3);
    if (blurred == NULL) {
        perror("Error allocating memory for blurred image");
        return;
    }

    for (int i = 1; i < width - 1; i++) {
        for (int j = 1; j < height - 1; j++) {
            int r = 0, g = 0, b = 0;
            for (int x = -1; x <= 1; x++) {
                for (int y = -1; y <= 1; y++) {
                    r += rgb[(i + x) * width * 3 + (j + y) * 3];
                    g += rgb[(i + x) * width * 3 + (j + y) * 3 + 1];
                    b += rgb[(i + x) * width * 3 + (j + y) * 3 + 2];
                }
            }
            r /= 9;
            g /= 9;
            b /= 9;

            blurred[(i - 1) * new_width * 3 + (j - 1) * 3] = (unsigned char)r;
            blurred[(i - 1) * new_width * 3 + (j - 1) * 3 + 1] = (unsigned char)g;
            blurred[(i - 1) * new_width * 3 + (j - 1) * 3 + 2] = (unsigned char)b;
        }
    }

    // Copy blurred image back to original buffer (overwriting the original)
    memcpy(rgb, blurred, new_width * new_height * 3);

    free(blurred);
}

// Function to encode RGB24 to JPEG
int encode_jpeg(unsigned char *rgb, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        perror("Error opening output file");
        jpeg_destroy_compress(&cinfo);
        return -1;
    }
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3; // RGB
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, 75, TRUE); // Set JPEG quality

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3; // RGB

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

int main() {
    camera_t camera;
    unsigned char *yuyv_buffer = NULL;
    unsigned char *rgb_buffer = NULL;
    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];

    // Install signal handler
    signal(SIGINT, sigint_handler);

    // Initialize camera
    if (camera_init(&camera, "/dev/video0") < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    // Capture frame
    if (camera_capture(&camera, &yuyv_buffer) < 0) {
        fprintf(stderr, "Frame capture failed\n");
        camera_stop(&camera);
        camera_unmap(&camera);
        camera_close(&camera);
        return 1;
    }

    // Allocate memory for RGB buffer
    rgb_buffer = (unsigned char *)malloc(camera.fmt.fmt.pix.width * camera.fmt.fmt.pix.height * 3);
    if (rgb_buffer == NULL) {
        perror("Error allocating memory for RGB buffer");
        camera_stop(&camera);
        camera_unmap(&camera);
        camera_close(&camera);
        return 1;
    }

    // Convert YUYV to RGB
    yuyv_to_rgb(yuyv_buffer, rgb_buffer, camera.fmt.fmt.pix.width, camera.fmt.fmt.pix.height);

    // Apply blur filter
    apply_blur(rgb_buffer, camera.fmt.fmt.pix.width, camera.fmt.fmt.pix.height);

    // Generate filename
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    // Encode JPEG
    if (encode_jpeg(rgb_buffer, camera.fmt.fmt.pix.width, camera.fmt.fmt.pix.height, filename) < 0) {
        fprintf(stderr, "JPEG encoding failed\n");
        free(rgb_buffer);
        camera_stop(&camera);
        camera_unmap(&camera);
        camera_close(&camera);
        return 1;
    }

    printf("Image saved as %s\n", filename);

    // Clean up
    free(rgb_buffer);
    camera_stop(&camera);
    camera_unmap(&camera);
    camera_close(&camera);

    return 0;
}

