#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <string.h>
#include <errno.h>

#define DEVICE_PATH "/dev/video0"

// Function to check if a file exists
int file_exists(const char *filename) {
    return access(filename, F_OK) == 0;
}

// Function to open the video device
int open_device(const char *device_path) {
    int fd = open(device_path, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening device %s: %s\n", device_path, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to query device capabilities
int query_device_capabilities(int fd, struct v4l2_capability *cap) {
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) == -1) {
        fprintf(stderr, "Error querying device capabilities: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to check if the device is a video capture device
int is_video_capture_device(const struct v4l2_capability *cap) {
    return (cap->capabilities & V4L2_CAP_VIDEO_CAPTURE);
}

// Function to enumerate frame sizes
int enumerate_frame_sizes(int fd, struct v4l2_frmsizeenum *frmsize) {
    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, frmsize) == -1) {
        fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to check if frame size enumeration is supported
int is_frame_size_supported(const struct v4l2_capability *cap) {
    return (cap->capabilities & V4L2_CAP_ENUM_FRAMESIZES);
}

// Function to enumerate frame intervals
int enumerate_frame_intervals(int fd, struct v4l2_frmivalenum *frmival) {
    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, frmival) == -1) {
        fprintf(stderr, "Error enumerating frame intervals: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to check if frame interval enumeration is supported
int is_frame_interval_supported(const struct v4l2_capability *cap) {
    return (cap->capabilities & V4L2_CAP_ENUM_FRAMEINTERVALS);
}

// Function to query control
int query_control(int fd, struct v4l2_queryctrl *ctrl) {
    if (ioctl(fd, VIDIOC_QUERYCTRL, ctrl) == -1) {
        fprintf(stderr, "Error querying control: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to check if autofocus is supported
int is_autofocus_supported(const struct v4l2_queryctrl *ctrl) {
    return (ctrl->flags & V4L2_CTRL_FLAG_INACTIVE) == 0;
}

// Function to print frame size
void print_frame_size(const struct v4l2_frmsizeenum *frmsize) {
    printf("  %dx%d", frmsize->type, frmsize->size.width, frmsize->size.height);
}

// Function to print frame interval
void print_frame_interval(const struct v4l2_frmivalenum *frmival) {
    printf("  %d.%02d fps", (int)(1.0 / frmival->denominator), (int)((1.0 / frmival->numerator) * 100));
}

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_queryctrl ctrl;

    // Check if the device file exists
    if (!file_exists(DEVICE_PATH)) {
        fprintf(stderr, "Error: Device %s does not exist.\n", DEVICE_PATH);
        return 1;
    }

    // Open the device
    fd = open_device(DEVICE_PATH);
    if (fd == -1) {
        return 1;
    }

    // Query device capabilities
    if (query_device_capabilities(fd, &cap) == -1) {
        close(fd);
        return 1;
    }

    // Check if it's a video capture device
    if (!is_video_capture_device(&cap)) {
        fprintf(stderr, "Error: %s is not a video capture device.\n", DEVICE_PATH);
        close(fd);
        return 1;
    }

    printf("Device: %s\n", DEVICE_PATH);
    printf("  Driver: %s\n", cap.driver);
    printf("  Card: %s\n", cap.card);
    printf("  Bus Info: %s\n", cap.bus_info);
    printf("  Version: %d.%d.%d\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("  Capabilities: ");
    if (cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) printf("V4L2_CAP_VIDEO_CAPTURE ");
    if (cap.capabilities & V4L2_CAP_STREAMING) printf("V4L2_CAP_STREAMING ");
    printf("\n");

    // Enumerate frame sizes
    frmsize.type = V4L2_FRMSIZE_TYPE_DISCRETE;
    printf("Supported Resolutions:\n");
    while (enumerate_frame_sizes(fd, &frmsize) != -1) {
        print_frame_size(&frmsize);
        printf("\n");
        frmsize.index++;
    }

    // Enumerate frame intervals
    if (is_frame_interval_supported(&cap)) {
        frmival.type = V4L2_FRMIVAL_TYPE_DISCRETE;
        printf("Supported Frame Rates:\n");
        while (enumerate_frame_intervals(fd, &frmival) != -1) {
            print_frame_interval(&frmival);
            printf("\n");
            frmival.index++;
        }
    } else {
        printf("  Frame rate enumeration not supported.\n");
    }

    // Query autofocus control
    ctrl.id = V4L2_CID_FOCUS_AUTO;
    if (query_control(fd, &ctrl) == -1) {
        printf("  Autofocus control not supported.\n");
    } else {
        if (is_autofocus_supported(&ctrl)) {
            printf("  Autofocus supported (ID: %d, Type: %d, Flags: %d, Default Value: %d, Minimum: %d, Maximum: %d, Step: %d, Value: %d)\n",
                   ctrl.id, ctrl.type, ctrl.flags, ctrl.default_value, ctrl.minimum, ctrl.maximum, ctrl.step, ctrl.value);
        } else {
            printf("  Autofocus not supported (Control is inactive).\n");
        }
    }

    // Close the device
    close(fd);

    return 0;
}

