#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <curl/curl.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2 // seconds
#define CAPTURE_INTERVAL 100 // milliseconds
#define IMAGE_QUALITY 85
#define MOTION_STATUS "detected"
#define MOTION_STATUS_FALSE "false"
#define JSON_FILENAME "motion_captures/motion_log.json"
#define IMAGE_DIR "motion_captures"

// Structure to hold program state
typedef struct {
    int running;
    char *ip_address;
    int port;
    FILE *log_file;
} ProgramState;

// Function prototypes
int initialize_gpio();
int capture_image(char *filename);
int create_json_payload(char *filename, char *timestamp, char *motion_status, char *gpio_pin, char *payload);
int post_data(const char *ip_address, int port, const char *image_path, const char *json_payload);
void signal_handler(int signal);
int create_directory(const char *path);
int check_directory_exists(const char *path);
int write_to_log(const char *message);
int read_ip_port(int argc, char *argv[], char **ip_address, int *port);

// Global program state
ProgramState state = {1, NULL, 0, NULL};

// Callback function for libcurl to handle the response
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    // You can process the response here if needed
    return real_size;
}

int main(int argc, char *argv[]) {
    char timestamp[30];
    char filename[100];
    char json_payload[200];
    time_t rawtime;
    struct tm *timeinfo;
    int motion_detected = 0;
    time_t last_motion_time = 0;

    // Read IP address and port from command-line arguments
    if (read_ip_port(argc, argv, &state.ip_address, &state.port) != 0) {
        fprintf(stderr, "Error: Could not read IP address and port from command-line arguments.\n");
        return 1;
    }

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio.\n");
        return 1;
    }

    // Create the motion_captures directory if it doesn't exist
    if (!check_directory_exists(IMAGE_DIR)) {
        if (create_directory(IMAGE_DIR) != 0) {
            fprintf(stderr, "Error: Failed to create directory '%s'.\n", IMAGE_DIR);
            gpioTerminate();
            return 1;
        }
    }

    // Open the log file
    state.log_file = fopen("motion_captures/motion_log.txt", "a");
    if (state.log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (state.running) {
        int current_value = gpioRead(GPIO_PIN);

        if (current_value == 1 && !motion_detected) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

            // Debounce the motion detection
            if (time(NULL) - last_motion_time >= DEBOUNCE_TIME) {
                motion_detected = 1;
                last_motion_time = time(NULL);

                // Capture the image
                if (capture_image(filename) == 0) {
                    // Create the JSON payload
                    if (create_json_payload(filename, timestamp, MOTION_STATUS, "17", json_payload) == 0) {
                        // Post the data to the HTTP endpoint
                        if (post_data(state.ip_address, state.port, filename, json_payload) != 0) {
                            fprintf(stderr, "Error: Failed to post data to HTTP endpoint.\n");
                        }
                    } else {
                        fprintf(stderr, "Error: Failed to create JSON payload.\n");
                    }
                } else {
                    fprintf(stderr, "Error: Failed to capture image.\n");
                }
            }
        } else if (current_value == 0 && motion_detected) {
            motion_detected = 0;
        }

        gpioDelay(CAPTURE_INTERVAL * 1000); // pigpio uses microseconds
    }

    // Clean up and exit
    fclose(state.log_file);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    return 0;
}

int capture_image(char *filename) {
    char command[200];
    snprintf(command, sizeof(command), "raspistill -o %s/%s.jpg -q %d", IMAGE_DIR, filename, IMAGE_QUALITY);
    int result = system(command);
    if (result == 0) {
        snprintf(filename, 100, "%s/%s.jpg", IMAGE_DIR, filename);
        return 0;
    } else {
        fprintf(stderr, "Error: Failed to capture image. Command returned %d\n", result);
        return 1;
    }
}

int create_json_payload(char *filename, char *timestamp, char *motion_status, char *gpio_pin, char *payload) {
    snprintf(payload, 200, "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": \"%s\", \"gpio_pin\": \"%s\"}", filename, timestamp, motion_status, gpio_pin);
    return 0;
}

int post_data(const char *ip_address, int port, const char *image_path, const char *json_payload) {
    CURL *curl;
    CURLcode res;
    char url[100];
    struct curl_slist *headers = NULL;

    snprintf(url, sizeof(url), "http://%s:%d/upload", ip_address, port);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_payload));

        // Set the Content-Type header to application/json
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        // Set the image file as a multipart/form-data attachment
        curl_easy_setopt(curl, CURLOPT_READFUNCTION, NULL); // Use default read function
        curl_easy_setopt(curl, CURLOPT_UPLOAD, 1L); // Enable upload
        curl_easy_setopt(curl, CURLOPT_INFILESIZE, (long)strlen(json_payload)); // Set the size of the data to send

        res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code != 200) {
                fprintf(stderr, "Error: HTTP request failed with status code: %ld\n", response_code);
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "Error: Failed to initialize libcurl.\n");
        curl_global_cleanup();
        return 1;
    }
    curl_global_cleanup();
    return 0;
}

void signal_handler(int signal) {
    printf("Signal received (%d).  Shutting down...\n", signal);
    state.running = 0;
}

int create_directory(const char *path) {
    if (mkdir(path, 0777) == 0) {
        return 0;
    } else {
        fprintf(stderr, "Error: Failed to create directory '%s'.\n", path);
        return 1;
    }
}

int check_directory_exists(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        return (st.st_mode & S_IFDIR);
    } else {
        return 0;
    }
}

int write_to_log(const char *message) {
    if (state.log_file != NULL) {
        fprintf(state.log_file, "%s\n", message);
        fflush(state.log_file); // Ensure the message is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

int read_ip_port(int argc, char *argv[], char **ip_address, int *port) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP address> <port>\n", argv[0]);
        return 1;
    }

    *ip_address = argv[1];
    *port = atoi(argv[2]);

    if (*port <= 0 || *port > 65535) {
        fprintf(stderr, "Error: Invalid port number.\n");
        return 1;
    }

    return 0;
}

