#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define PIXEL_FORMAT V4L2_PIX_FMT_YUYV
#define BUFFER_COUNT 1
#define TIMEOUT_SEC 2

static int fd = -1;
static void *buffer = NULL;
static FILE *output_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold the camera configuration
typedef struct {
    int width;
    int height;
    int pixel_format;
} camera_config_t;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nSignal received, stopping...\n");
}

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to query the device capabilities
int query_capabilities(int fd, struct v4l2_capability *cap) {
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }
    return 0;
}

// Function to set the image format
int set_format(int fd, int width, int height, int pixel_format) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = pixel_format;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        return -1;
    }
    return 0;
}

// Function to request buffers
int request_buffers(int fd, unsigned int count) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = count;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }
    return 0;
}

// Function to map the buffer to memory
int map_buffer(int fd, unsigned int index) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = index;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("Error querying buffer");
        return -1;
    }

    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        return -1;
    }
    return (int)(uintptr_t)buffer; // Return the address as an integer
}

// Function to start streaming
int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting streaming");
        return -1;
    }
    return 0;
}

// Function to dequeue a buffer
int dequeue_buffer(int fd, struct v4l2_buffer *buf) {
    if (ioctl(fd, VIDIOC_DQBUF, buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }
    return 0;
}

// Function to enqueue a buffer
int enqueue_buffer(int fd, struct v4l2_buffer *buf) {
    if (ioctl(fd, VIDIOC_QBUF, buf) == -1) {
        perror("Error enqueuing buffer");
        return -1;
    }
    return 0;
}

// Function to stop streaming
int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping streaming");
        return -1;
    }
    return 0;
}

// Function to unmap the buffer
int unmap_buffer(void *buffer, size_t size) {
    if (munmap(buffer, size) == -1) {
        perror("Error unmapping buffer");
        return -1;
    }
    return 0;
}

// Function to write the cropped YUYV data to a file
int write_cropped_data(const void *buffer, int width, int height, int crop_x, int crop_y, int crop_width, int crop_height, const char *filename) {
    size_t buffer_size = width * height * 2; // YUYV format
    size_t crop_size = crop_width * crop_height * 2;

    // Calculate the starting offset for the cropped region
    int start_offset = crop_y * width * 2 + crop_x * 2;

    // Allocate memory for the cropped data
    unsigned char *cropped_data = (unsigned char *)malloc(crop_size);
    if (cropped_data == NULL) {
        perror("Error allocating memory for cropped data");
        return -1;
    }

    // Copy the cropped data from the buffer
    memcpy(cropped_data, (unsigned char *)buffer + start_offset, crop_size);

    // Open the output file
    output_file = fopen(filename, "wb");
    if (output_file == NULL) {
        perror("Error opening output file");
        free(cropped_data);
        return -1;
    }

    // Write the cropped data to the file
    size_t bytes_written = fwrite(cropped_data, 1, crop_size, output_file);
    if (bytes_written != crop_size) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %zu\n", bytes_written, crop_size);
        perror("Error writing to file");
        fclose(output_file);
        free(cropped_data);
        return -1;
    }

    // Close the output file
    if (fclose(output_file) != 0) {
        perror("Error closing output file");
        free(cropped_data);
        return -1;
    }

    free(cropped_data);
    return 0;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    fd_set readfds;
    struct timeval timeout;
    int ret;
    int buffer_index = 0;
    int buffer_address = 0; // Store the mapped buffer address

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Query capabilities
    if (query_capabilities(fd, &cap) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Check if the device is a video capture device
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    // Set the image format
    if (set_format(fd, WIDTH, HEIGHT, PIXEL_FORMAT) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    if (request_buffers(fd, BUFFER_COUNT) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffer
    buffer_address = map_buffer(fd, buffer_index);
    if (buffer_address == -1) {
        close(fd);
        return EXIT_FAILURE;
    }
    buffer = (void *)(uintptr_t)buffer_address; // Cast the integer address back to a void pointer

    // Start streaming
    if (start_streaming(fd) == -1) {
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    }

    // Dequeue the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = buffer_index;

    if (dequeue_buffer(fd, &buf) == -1) {
        stop_streaming(fd);
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    }

    // Set up select() timeout
    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    // Wait for a frame with timeout
    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    ret = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (ret == -1) {
        perror("Error in select()");
        stop_streaming(fd);
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        stop_streaming(fd);
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    }

    // Enqueue the buffer
    if (enqueue_buffer(fd, &buf) == -1) {
        stop_streaming(fd);
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    }

    // Verify the captured frame
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = PIXEL_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error re-setting format for verification");
        stop_streaming(fd);
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    }

    // Write the cropped data to the file
    if (write_cropped_data(buffer, WIDTH, HEIGHT, 100, 75, 200, 150, "cropped.yuv") == -1) {
        stop_streaming(fd);
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    }

    // Stop streaming
    if (stop_streaming(fd) == -1) {
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    }

    // Unmap the buffer
    if (unmap_buffer(buffer, WIDTH * HEIGHT * 2) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Close the file descriptor
    if (close(fd) == -1) {
        return EXIT_FAILURE;
    }

    printf("Cropped YUYV data written to cropped.yuv\n");
    return EXIT_SUCCESS;
}

