    // Write the cropped data to the file
    size_t bytes_written = fwrite(cropped_data, 1, crop_size, output_file);
    if (bytes_written != crop_size) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %zu\n", bytes_written, crop_size);
        perror("Error writing to file");
        fclose(output_file);
        free(cropped_data);
        return -1;
    }

    // Close the output file
    if (fclose(output_file) != 0) {
        perror("Error closing output file");
        free(cropped_data);
        return -1;
    }

    free(cropped_data);
    return 0;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    fd_set readfds;
    struct timeval timeout;
    int ret;
    int buffer_index = 0;
    int buffer_address = 0; // Store the mapped buffer address

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Query capabilities
    if (query_capabilities(fd, &cap) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Check if the device is a video capture device
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    // Set the image format
    if (set_format(fd, WIDTH, HEIGHT, PIXEL_FORMAT) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    if (request_buffers(fd, BUFFER_COUNT) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffer
    buffer_address = map_buffer(fd, buffer_index);
    if (buffer_address == -1) {
        close(fd);
        return EXIT_FAILURE;
    }
    buffer = (void *)(uintptr_t)buffer_address; // Cast the integer address back to a void pointer

    // Start streaming
    if (start_streaming(fd) == -1) {
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    }

    // Dequeue the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = buffer_index;

    if (dequeue_buffer(fd, &buf) == -1) {
        stop_streaming(fd);
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    }

    // Set up select() timeout
    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    // Wait for a frame with timeout
    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    ret = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (ret == -1) {
        perror("Error in select()");
        stop_streaming(fd);
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        stop_streaming(fd);
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    }

    // Enqueue the buffer
    if (enqueue_buffer(fd, &buf) == -1) {
        stop_streaming(fd);
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    }

    // Verify the captured frame
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = PIXEL_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error re-setting format for verification");
        stop_streaming(fd);
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    }

    // Write the cropped data to the file
    if (write_cropped_data(buffer, WIDTH, HEIGHT, 100, 75, 200, 150, "cropped.yuv") == -1) {
        stop_streaming(fd);
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    }

    // Stop streaming
    if (stop_streaming(fd) == -1) {
        unmap_buffer(buffer, WIDTH * HEIGHT * 2);
        close(fd);
        return EXIT_FAILURE;
    }

    // Unmap the buffer
    if (unmap_buffer(buffer, WIDTH * HEIGHT * 2) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Close the file descriptor
    if (close(fd) == -1) {
        return EXIT_FAILURE;
    }

    printf("Cropped YUYV data written to cropped.yuv\n");
    return EXIT_SUCCESS;
}

