#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define angle limits
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define servo pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_servo_angle(int gpio_pin, int angle);
void handle_arrow_key(int key, int *pan_angle, int *tilt_angle);
void handle_q_key(int *pan_angle, int *tilt_angle);
void cleanup_gpio(int pan_angle, int tilt_angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Initialize GPIO and pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    return 0; // Indicate success
}

// Set servo angle using PWM
void set_servo_angle(int gpio_pin, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d). Must be between %d and %d\n", angle, MIN_ANGLE, MAX_ANGLE);
        return;
    }

    // Calculate pulse width based on angle (linear mapping)
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    // Set PWM duty cycle (pulse width)
    gpioPWM(gpio_pin, pulse_width);
}

// Handle arrow key input
void handle_arrow_key(int key, int *pan_angle, int *tilt_angle) {
    switch (key) {
        case 'w':
            *tilt_angle += 5;
            if (*tilt_angle > MAX_ANGLE) {
                *tilt_angle = MAX_ANGLE;
                fprintf(stderr, "Error: Tilt angle exceeds maximum (%d)\n", MAX_ANGLE);
            }
            break;
        case 's':
            *tilt_angle -= 5;
            if (*tilt_angle < MIN_ANGLE) {
                *tilt_angle = MIN_ANGLE;
                fprintf(stderr, "Error: Tilt angle below minimum (%d)\n", MIN_ANGLE);
            }
            break;
        case 'a':
            *pan_angle -= 5;
            if (*pan_angle < MIN_ANGLE) {
                *pan_angle = MIN_ANGLE;
                fprintf(stderr, "Error: Pan angle below minimum (%d)\n", MIN_ANGLE);
            }
            break;
        case 'd':
            *pan_angle += 5;
            if (*pan_angle > MAX_ANGLE) {
                *pan_angle = MAX_ANGLE;
                fprintf(stderr, "Error: Pan angle exceeds maximum (%d)\n", MAX_ANGLE);
            }
            break;
        default:
            fprintf(stderr, "Invalid key pressed: %c\n", key);
            return;
    }

    set_servo_angle(PAN_SERVO_PIN, *pan_angle);
    set_servo_angle(TILT_SERVO_PIN, *tilt_angle);
}

// Handle 'q' key input
void handle_q_key(int *pan_angle, int *tilt_angle) {
    *pan_angle = 90;
    *tilt_angle = 90;
    set_servo_angle(PAN_SERVO_PIN, *pan_angle);
    set_servo_angle(TILT_SERVO_PIN, *tilt_angle);
    printf("Servos reset to neutral position.\n");
}

// Cleanup GPIO and terminate pigpio library
void cleanup_gpio(int pan_angle, int tilt_angle) {
    // Set servos to neutral position before exiting
    set_servo_angle(PAN_SERVO_PIN, pan_angle);
    set_servo_angle(TILT_SERVO_PIN, tilt_angle);

    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initial servo positions
    int pan_angle = 90;
    int tilt_angle = 90;

    // Set initial servo positions
    set_servo_angle(PAN_SERVO_PIN, pan_angle);
    set_servo_angle(TILT_SERVO_PIN, tilt_angle);

    printf("Arrow key control: w (up), s (down), a (left), d (right). Press 'q' to reset. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        char input;
        if (scanf(" %c", &input) != 1) {
            // Handle potential input errors or EOF
            continue; // Or break, depending on desired behavior
        }

        switch (input) {
            case 'w':
            case 's':
            case 'a':
            case 'd':
                handle_arrow_key(input, &pan_angle, &tilt_angle);
                break;
            case 'q':
                handle_q_key(&pan_angle, &tilt_angle);
                break;
            default:
                fprintf(stderr, "Invalid input: %c\n", input);
                break;
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup_gpio(pan_angle, tilt_angle);
    return 0;
}

