    int page = y / 8;
    int bit = y % 8;
    int address = x + page * OLED_WIDTH;

    unsigned char data = i2cReadByteData(i2c_handle, 0x40 + address);
    if (data < 0) {
        fprintf(stderr, "Error reading OLED data at address 0x%02X\n", 0x40 + address);
        return;
    }

    if (color) {
        data |= (1 << bit);
    } else {
        data &= ~(1 << bit);
    }

    if (i2cWriteByteData(i2c_handle, 0x40 + address, data) < 0) {
        fprintf(stderr, "Error writing to OLED data at address 0x%02X\n", 0x40 + address);
