            }
        }
    }

    fclose(fp);

    // Calculate total CPU time
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;

    // Calculate CPU usage percentage
    unsigned long long total_diff = total - prev_total;
    unsigned long long idle_diff = idle + iowait - prev_idle_total - (prev_iowait - prev_idle_total);

    cpu_usage = (int)(((total_diff - idle_diff) / (double)total_diff) * 100);

