#include <unistd.h>
#include <pigpio.h>

// Configuration
#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_ADDR 0x27 // Example I2C address for LCD
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define PULSES_PER_LITER 450.0 // YF-S201 sensor pulses per liter
#define SAMPLE_INTERVAL_SEC 1
#define LCD_UPDATE_INTERVAL_SEC 10

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
double flow_rate = 0.0;
int i2c_handle;
int running = 1;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user);
double calculate_flow_rate(int pulse_count, double time_interval);
void update_total_volume(double flow_rate, double time_interval);
void log_data(double flow_rate, double total_volume);
void lcd_init(int i2c_handle);
void lcd_clear(int i2c_handle);
void lcd_set_cursor(int i2c_handle, int row, int col);
void lcd_print(int i2c_handle, const char *text);
void lcd_update_display(int i2c_handle, double flow_rate, double total_volume);
void signal_handler(int signal);

// LCD functions (minimal implementation - adapt to your LCD library)
void lcd_init(int i2c_handle) {
    // Initialization sequence (example - adapt to your LCD)
    char init_data[] = {0x33, 0x32, 0x28, 0x0C, 0x01, 0x06};
    for (int i = 0; i < sizeof(init_data); i++) {
        char buf[2] = {0x40, init_data[i]}; // 0x40 is the control byte for command
        if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
            fprintf(stderr, "Error initializing LCD: I2C write failed\n");
            running = 0; // Stop the program if LCD init fails
            return;
        }
        gpioDelay(2); // Delay after each command
    }
}

void lcd_clear(int i2c_handle) {
    char buf[2] = {0x40, 0x01}; // Clear display command
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error clearing LCD: I2C write failed\n");
        running = 0;
        return;
    }
    gpioDelay(2);
}

void lcd_set_cursor(int i2c_handle, int row, int col) {
    int address = (row == 0) ? (0x80 + col) : (0xC0 + col);
    char buf[2] = {0x40, address};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error setting cursor: I2C write failed\n");
        running = 0;
        return;
    }
    gpioDelay(1);
}

void lcd_print(int i2c_handle, const char *text) {
    for (int i = 0; text[i] != '\0'; i++) {
        char buf[2] = {0x41, text[i]}; // 0x41 is the control byte for data
        if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
            fprintf(stderr, "Error printing to LCD: I2C write failed\n");
            running = 0;
            return;
        }
    }
}

void lcd_update_display(int i2c_handle, double flow_rate, double total_volume) {
    char flow_str[20];
    char volume_str[20];

    snprintf(flow_str, sizeof(flow_str), "Flow: %.2f L/min", flow_rate);
    snprintf(volume_str, sizeof(volume_str), "Vol: %.2f L", total_volume);

    lcd_clear(i2c_handle);
    lcd_set_cursor(i2c_handle, 0, 0);
    lcd_print(i2c_handle, flow_str);
    lcd_set_cursor(i2c_handle, 1, 0);
    lcd_print(i2c_handle, volume_str);
}

void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

double calculate_flow_rate(int pulse_count, double time_interval) {
    return (double)pulse_count / PULSES_PER_LITER / (time_interval / 60.0); // L/min
}

void update_total_volume(double flow_rate, double time_interval) {
    total_volume += flow_rate * (time_interval / 60.0);
}

void log_data(double flow_rate, double total_volume) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Flow Rate: %.2f L/min, Total Volume: %.2f L\n", timestamp, flow_rate, total_volume);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for the flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Set up interrupt for pulse counting
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C for LCD
    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    lcd_init(i2c_handle);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_log_time = time(NULL);
    time_t last_lcd_update_time = time(NULL);

    while (running) {
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay for 1 second

        // Calculate flow rate and update total volume
        double time_interval = SAMPLE_INTERVAL_SEC;
        flow_rate = calculate_flow_rate(pulse_count, time_interval);
        update_total_volume(flow_rate, time_interval);
        pulse_count = 0; // Reset pulse count

        // Log data
        time_t current_time = time(NULL);
        if (difftime(current_time, last_log_time) >= 1.0) {
            log_data(flow_rate, total_volume);
            last_log_time = current_time;
        }

        // Update LCD display
        if (difftime(current_time, last_lcd_update_time) >= LCD_UPDATE_INTERVAL_SEC) {
            lcd_update_display(i2c_handle, flow_rate, total_volume);
            last_lcd_update_time = current_time;
        }
    }

    // Cleanup
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

