#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Configuration
#define ANEMOMETER_GPIO 17
#define MCP3008_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define PCF8574_ADDR 0x27
#define LCD_ADDR 0x27 // Assuming LCD is connected to PCF8574
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define SAMPLE_WINDOW_MS 500

// Global variables
volatile int pulse_count = 0;
int spi_fd = -1;
int i2c_fd = -1;
int lcd_fd = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(const char *device);
int spi_read_adc(int channel);
int i2c_init(const char *device);
int i2c_write_byte(int fd, int addr, int data);
int i2c_read_byte(int fd, int addr);
int lcd_init(int fd);
void lcd_send_command(int fd, int command);
void lcd_send_data(int fd, int data);
void lcd_print(int fd, const char *text);
void anemometer_interrupt_handler(int signum);
float calculate_wind_speed(int pulse_count);
const char *get_wind_direction(int adc_value);
void signal_handler(int signum);
void lcd_clear(int fd);
void lcd_set_cursor(int fd, int row, int col);

// SPI functions
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    int speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

int spi_read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // MCP3008 command to read a single channel
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error reading SPI data");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// I2C functions
int i2c_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    int addr = PCF8574_ADDR;
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int i2c_write_byte(int fd, int addr, int data) {
    int result = i2c_smbus_write_byte_data(fd, addr, data);
    if (result < 0) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read_byte(int fd, int addr) {
    int result = i2c_smbus_read_byte_data(fd, addr);
    if (result < 0) {
        perror("Error reading from I2C device");
        return -1;
    }
    return result;
}

// LCD functions
int lcd_init(int fd) {
    // Initialization sequence (adjust as needed for your LCD)
    usleep(50000); // Wait for LCD to power up
    lcd_send_command(fd, 0x33); // Initialize
    lcd_send_command(fd, 0x32); // Initialize
    lcd_send_command(fd, 0x28); // 4-bit mode, 2 lines, 5x8 font
    lcd_send_command(fd, 0x0C); // Display on, cursor off, blink off
    lcd_send_command(fd, 0x06); // Increment cursor, no shift
    lcd_clear(fd);
    return 0;
}

void lcd_send_command(int fd, int command) {
    int data_u, data_l;
    data_u = (command & 0xF0);
    data_l = ((command << 4) & 0xF0);

    i2c_write_byte(fd, 0x40, data_u | 0x04); // Enable pulse
    usleep(1); // Delay for 1us
    i2c_write_byte(fd, 0x40, data_u & ~0x04); // Disable pulse
    usleep(1); // Delay for 1us

    i2c_write_byte(fd, 0x40, data_l | 0x04); // Enable pulse
    usleep(1); // Delay for 1us
    i2c_write_byte(fd, 0x40, data_l & ~0x04); // Disable pulse
    usleep(1); // Delay for 1us
}

void lcd_send_data(int fd, int data) {
    int data_u, data_l;
    data_u = (data & 0xF0);
    data_l = ((data << 4) & 0xF0);

    i2c_write_byte(fd, 0x40, data_u | 0x05); // Enable pulse, RS=1
    usleep(1); // Delay for 1us
    i2c_write_byte(fd, 0x40, data_u & ~0x05); // Disable pulse, RS=1
    usleep(1); // Delay for 1us

    i2c_write_byte(fd, 0x40, data_l | 0x05); // Enable pulse, RS=1
    usleep(1); // Delay for 1us
    i2c_write_byte(fd, 0x40, data_l & ~0x05); // Disable pulse, RS=1
    usleep(1); // Delay for 1us
}

void lcd_print(int fd, const char *text) {
    for (int i = 0; text[i] != '\0'; i++) {
        lcd_send_data(fd, text[i]);
    }
}

void lcd_clear(int fd) {
    lcd_send_command(fd, 0x01); // Clear display
    usleep(2000); // Delay for 2ms
}

void lcd_set_cursor(int fd, int row, int col) {
    int address;
    if (row == 0) {
        address = 0x00 + col;
    } else {
        address = 0x40 + col;
    }
    lcd_send_command(fd, 0x80 + address); // Set cursor position
}

// Anemometer interrupt handler
void anemometer_interrupt_handler(int signum) {
    pulse_count++;
}

// Wind speed calculation
float calculate_wind_speed(int pulse_count) {
    // Calibration factor (pulses per second per m/s)
    float calibration_factor = 1.0; // Adjust based on your anemometer
    float wind_speed = (float)pulse_count / (float)SAMPLE_WINDOW_MS * 60.0 / calibration_factor; // pulses/second to m/s
    return wind_speed;
}

// Wind direction lookup
const char *get_wind_direction(int adc_value) {
    const char *directions[] = {
        "N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE", "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW"
    };
    int num_directions = sizeof(directions) / sizeof(directions[0]);

    // Map ADC value to direction (0-15)
    int direction_index = adc_value / 64; // Assuming 0-1023 range, 64 per direction
    if (direction_index < 0) direction_index = 0;
    if (direction_index >= num_directions) direction_index = num_directions - 1;

    return directions[direction_index];
}

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        program_running = 0;
    }
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

