            lcd_print(lcd_fd, "ADC Error");
            lcd_set_cursor(lcd_fd, 1, 0);
            lcd_print(lcd_fd, default_direction);
            usleep(SAMPLE_WINDOW_MS * 1000); // Wait for sample window
            continue;
        }

        // Validate ADC reading
        if (adc_value == 0 || adc_value == 1023) {
