            const char *default_direction = "Unknown";
            lcd_clear(lcd_fd);
            lcd_set_cursor(lcd_fd, 0, 0);
            lcd_print(lcd_fd, "ADC Out of Range");
            lcd_set_cursor(lcd_fd, 1, 0);
            lcd_print(lcd_fd, default_direction);
            usleep(SAMPLE_WINDOW_MS * 1000); // Wait for sample window
            continue;
        }

        // Get wind direction
        const char *wind_direction = get_wind_direction(adc_value);

        // Calculate wind speed (simulating interrupt)
        // In a real application, you would increment pulse_count in the interrupt handler.
        // For demonstration, we'll increment it manually.
        // pulse_count = 1; // Simulate one pulse

        // Calculate wind speed
