        // Display wind speed and direction on LCD
        lcd_clear(lcd_fd);
        lcd_set_cursor(lcd_fd, 0, 0);
        char speed_str[20];
        snprintf(speed_str, sizeof(speed_str), "Speed: %.2f m/s", wind_speed);
        lcd_print(lcd_fd, speed_str);
        lcd_set_cursor(lcd_fd, 1, 0);
        lcd_print(lcd_fd, wind_direction);

        // Wait for the sample window
        usleep(SAMPLE_WINDOW_MS * 1000); // Convert ms to us
    }

    // Cleanup
    close(spi_fd);
    close(i2c_fd);
    printf("Program terminated.\n");
