#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDR 0x27 // LCD1602 I2C address
#define FLOW_SENSOR_CALIBRATION_FACTOR 7.5 // pulses per liter
#define SENSOR_ABSENT_THRESHOLD 5 // seconds
#define SENSOR_ABSENT_CHECK_INTERVAL 1 // seconds
#define FLOW_RATE_DISPLAY_UPDATE_INTERVAL 1 // seconds

// Global variables
static volatile int pulse_count = 0;
static int i2c_handle;
static int running = 1;
static time_t last_pulse_time;
static int sensor_absent = 0;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user);
float calculate_flow_rate(int pulse_count);
int lcd_init();
int lcd_send_command(unsigned char command);
int lcd_send_data(unsigned char data);
int lcd_set_cursor(int row, int col);
int lcd_print(const char *string);
void signal_handler(int signal);
void cleanup();

// LCD1602 functions
int lcd_init() {
    // Initialization sequence
    lcd_send_command(0x33); // Initialize
    lcd_send_command(0x32); // Initialize
    lcd_send_command(0x28); // 4-bit mode, 2 lines, 5x8 font
    lcd_send_command(0x0C); // Display on, cursor off, blink off
    lcd_send_command(0x06); // Increment cursor, no shift
    lcd_send_command(0x01); // Clear display
    gpioDelay(2); // Delay for clear command
    return 0;
}

int lcd_send_command(unsigned char command) {
    char data_u, data_l;
    data_u = (command & 0xF0);
    data_l = ((command << 4) & 0xF0);

    // Send upper nibble
    char buf[2];
    buf[0] = data_u | 0x0C; // Enable pulse
    buf[1] = data_u & 0xF0; // Disable pulse
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device (command upper nibble)\n");
        return -1;
    }
    gpioDelay(1); // Enable pulse width

    // Send lower nibble
    buf[0] = data_l | 0x0C; // Enable pulse
    buf[1] = data_l & 0xF0; // Disable pulse
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device (command lower nibble)\n");
        return -1;
    }
    gpioDelay(1); // Enable pulse width
    return 0;
}

int lcd_send_data(unsigned char data) {
    char data_u, data_l;
    data_u = (data & 0xF0);
    data_l = ((data << 4) & 0xF0);

    // Send upper nibble
    char buf[2];
    buf[0] = data_u | 0x0D; // Enable pulse, RS=1
    buf[1] = data_u & 0xF0; // Disable pulse, RS=1
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device (data upper nibble)\n");
        return -1;
    }
    gpioDelay(1); // Enable pulse width

    // Send lower nibble
    buf[0] = data_l | 0x0D; // Enable pulse, RS=1
    buf[1] = data_l & 0xF0; // Disable pulse, RS=1
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device (data lower nibble)\n");
        return -1;
    }
    gpioDelay(1); // Enable pulse width
    return 0;
}

int lcd_set_cursor(int row, int col) {
    int addr;
    if (row == 0) {
        addr = 0x80 + col;
    } else {
        addr = 0xC0 + col;
    }
    lcd_send_command(addr);
    return 0;
}

int lcd_print(const char *string) {
    int i;
    for (i = 0; string[i] != '\0'; i++) {
        lcd_send_data(string[i]);
    }
    return 0;
}

// Pulse counter function
void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    time_t current_time = time(NULL);
    if (level == 1) { // Rising edge
        pulse_count++;
        last_pulse_time = current_time;
        sensor_absent = 0; // Reset sensor absent flag
    }
}

// Flow rate calculation function
float calculate_flow_rate(int pulse_count) {
    return (float)pulse_count / FLOW_SENSOR_CALIBRATION_FACTOR * 60.0; // L/min
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable pulse counter
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode and alert function
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetAlertFuncEx(GPIO_PIN, pulse_counter, NULL);

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        cleanup();
        return 1;
    }

    // Initialize LCD
    if (lcd_init() != 0) {
        fprintf(stderr, "LCD initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    last_pulse_time = time(NULL);

    // Main loop
    while (running) {
        time_t current_time = time(NULL);
        if (difftime(current_time, last_pulse_time) > SENSOR_ABSENT_CHECK_INTERVAL) {
            if (pulse_count == 0) {
                sensor_absent++;
                if (sensor_absent >= SENSOR_ABSENT_THRESHOLD) {
                    fprintf(stderr, "Sensor absent for %d seconds\n", SENSOR_ABSENT_THRESHOLD);
                    lcd_set_cursor(0, 0);
                    lcd_print("Sensor Absent");
                    lcd_set_cursor(1, 0);
                    lcd_print("Check Connection");
                    gpioDelay(5000); // Display for 5 seconds
                    sensor_absent = 0; // Reset the flag
                }
            } else {
                sensor_absent = 0; // Reset if pulses are detected
            }
        }

        float flow_rate = calculate_flow_rate(pulse_count);
        char buffer[20];
        snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);

        lcd_set_cursor(0, 0);
        lcd_print("Flow Rate:");
        lcd_set_cursor(1, 0);
        lcd_print(buffer);

        pulse_count = 0; // Reset pulse count for the next interval
        gpioDelay(FLOW_RATE_DISPLAY_UPDATE_INTERVAL * 1000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

