        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        cleanup();
        return 1;
    }

    // Initialize LCD
    if (lcd_init() != 0) {
        fprintf(stderr, "LCD initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    last_pulse_time = time(NULL);

    // Main loop
    while (running) {
        time_t current_time = time(NULL);
        if (difftime(current_time, last_pulse_time) > SENSOR_ABSENT_CHECK_INTERVAL) {
            if (pulse_count == 0) {
                sensor_absent++;
                if (sensor_absent >= SENSOR_ABSENT_THRESHOLD) {
                    fprintf(stderr, "Sensor absent for %d seconds\n", SENSOR_ABSENT_THRESHOLD);
                    lcd_set_cursor(0, 0);
                    lcd_print("Sensor Absent");
                    lcd_set_cursor(1, 0);
                    lcd_print("Check Connection");
                    gpioDelay(5000); // Display for 5 seconds
                    sensor_absent = 0; // Reset the flag
                }
            } else {
                sensor_absent = 0; // Reset if pulses are detected
            }
        }

        float flow_rate = calculate_flow_rate(pulse_count);
        char buffer[20];
        snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);

        lcd_set_cursor(0, 0);
        lcd_print("Flow Rate:");
        lcd_set_cursor(1, 0);
        lcd_print(buffer);

        pulse_count = 0; // Reset pulse count for the next interval
        gpioDelay(FLOW_RATE_DISPLAY_UPDATE_INTERVAL * 1000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

