const int delayUs = 800;

// Global variable to indicate program termination
volatile sig_atomic_t programRunning = 1;

// Function prototypes
int initializeGPIO();
void cleanupGPIO();
void setRow(int row, int state);
void setColumn(int col, int state);
void displayMatrix(int matrix[matrixSize][matrixSize]);
void generateWaveMatrix(int matrix[matrixSize][matrixSize], int direction);
void signalHandler(int signum);

// Signal handler for graceful shutdown
void signalHandler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        programRunning = 0;
        cleanupGPIO();
        exit(0);
    }
}

// Initializes the GPIO pins
int initializeGPIO() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    // Set row pins as output
    for (int i = 0; i < matrixSize; i++) {
        pinMode(rowPins[i], OUTPUT);
        digitalWrite(rowPins[i], HIGH); // Common anode, so HIGH turns off the LED
    }

    // Set column pins as output
    for (int i = 0; i < matrixSize; i++) {
        pinMode(colPins[i], OUTPUT);
        digitalWrite(colPins[i], HIGH); // Common anode, so HIGH turns off the LED
    }

    return 0;
}

// Cleans up the GPIO pins
void cleanupGPIO() {
    // Set all pins to INPUT and HIGH to turn off LEDs
    for (int i = 0; i < matrixSize; i++) {
        pinMode(rowPins[i], INPUT);
        digitalWrite(rowPins[i], HIGH);
        pinMode(colPins[i], INPUT);
        digitalWrite(colPins[i], HIGH);
    }
}

// Sets the state of a row pin
void setRow(int row, int state) {
    digitalWrite(rowPins[row], state ? HIGH : LOW);
}

// Sets the state of a column pin
void setColumn(int col, int state) {
    digitalWrite(colPins[col], state ? LOW : HIGH);
}

// Displays the LED matrix
void displayMatrix(int matrix[matrixSize][matrixSize]) {
    for (int row = 0; row < matrixSize; row++) {
        // Turn on the row
        setRow(row, HIGH);

        // Set the column states based on the matrix data
        for (int col = 0; col < matrixSize; col++) {
            setColumn(col, matrix[row][col]);
        }

        // Delay to allow the LED to light up
        delayMicroseconds(delayUs);

        // Turn off the row
        setRow(row, LOW);

        // Delay to prevent flickering
        delayMicroseconds(delayUs);
    }
}

// Generates a wave-like animation matrix
void generateWaveMatrix(int matrix[matrixSize][matrixSize], int direction) {
    // Clear the matrix
    for (int row = 0; row < matrixSize; row++) {
        for (int col = 0; col < matrixSize; col++) {
            matrix[row][col] = 0;
        }
    }

    // Generate the wave pattern
    int waveOffset = (direction == 1) ? 1 : -1; // 1 for right-to-left, -1 for left-to-right
    for (int col = 0; col < matrixSize; col++) {
        for (int row = 0; row < matrixSize; row++) {
            int wavePosition = (col + waveOffset * row) % matrixSize;
            if (wavePosition < 0) {
                wavePosition += matrixSize; // Handle negative modulo
            }
            matrix[row][wavePosition] = 1; // Turn on the LED
        }
    }
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signalHandler);

    // Initialize GPIO
    if (initializeGPIO() == -1) {
        return 1;
    }

    // Main loop
    while (programRunning) {
        // Generate wave matrices
        int waveMatrix1[matrixSize][matrixSize];
        int waveMatrix2[matrixSize][matrixSize];

        generateWaveMatrix(waveMatrix1, 1); // Right-to-left
        generateWaveMatrix(waveMatrix2, -1); // Left-to-right

        // Display the matrices
        displayMatrix(waveMatrix1);
        displayMatrix(waveMatrix2);
    }

    // Cleanup GPIO before exiting
    cleanupGPIO();

    return 0;
}

