{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio()
{
    // Set row pins as outputs
    for (int i = 0; i < num_rows; i++)
    {
        if (gpioSetMode(row_pins[i], PI_OUTPUT) != 0)
        {
            fprintf(stderr, "Error setting row pin %d as output\n", row_pins[i]);
            return 1;
        }
    }

    // Set column pins as outputs
    for (int i = 0; i < num_cols; i++)
    {
        if (gpioSetMode(col_pins[i], PI_OUTPUT) != 0)
        {
            fprintf(stderr, "Error setting column pin %d as output\n", col_pins[i]);
            return 1;
        }
    }

    return 0;
}

// Function to clear the LED matrix
void clear_matrix()
{
    // Set all column pins HIGH
    for (int i = 0; i < num_cols; i++)
    {
        if (gpioWrite(col_pins[i], 1) != 0)
        {
            fprintf(stderr, "Error setting column pin %d HIGH\n", col_pins[i]);
        }
    }

    // Set all row pins LOW
    for (int i = 0; i < num_rows; i++)
    {
        if (gpioWrite(row_pins[i], 0) != 0)
        {
            fprintf(stderr, "Error setting row pin %d LOW\n", row_pins[i]);
        }
    }
}

// Function to display a column
void display_column(int col, int delay_ms)
{
    // Set column pin LOW
    if (gpioWrite(col_pins[col], 0) != 0)
    {
        fprintf(stderr, "Error setting column pin %d LOW\n", col_pins[col]);
    }

    // Light up LEDs sequentially
    for (int i = 0; i < num_rows; i++)
    {
        if (gpioWrite(row_pins[i], 1) != 0)
        {
            fprintf(stderr, "Error setting row pin %d HIGH\n", row_pins[i]);
        }
        gpioDelay(1000); // 1ms delay
        if (gpioWrite(row_pins[i], 0) != 0)
        {
            fprintf(stderr, "Error setting row pin %d LOW\n", row_pins[i]);
        }
    }

    // Set column pin HIGH
    if (gpioWrite(col_pins[col], 1) != 0)
    {
        fprintf(stderr, "Error setting column pin %d HIGH\n", col_pins[col]);
    }

    gpioDelay(delay_ms * 1000); // Delay for the specified time
}

