    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio() != 0)
    {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate)
    {
        // Scan columns left to right
        for (int col = 0; col < num_cols; col++)
        {
            clear_matrix();
            display_column(col, 150);
        }
    }

    // Clean up GPIO pins
    for (int i = 0; i < num_rows; i++)
    {
        gpioWrite(row_pins[i], 0);
        gpioSetMode(row_pins[i], PI_INPUT); // Set to input to avoid leaving them high
    }
    for (int i = 0; i < num_cols; i++)
    {
        gpioWrite(col_pins[i], 1);
        gpioSetMode(col_pins[i], PI_INPUT); // Set to input to avoid leaving them high
    }

    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

