#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX75031_ADDR 0x4C
#define CONFIG_REG 0x00 // Example configuration register
#define CONFIG_VALUE 0x01 // Example configuration value
#define DISTANCE_REG 0x01 // Example distance register
#define DISTANCE_BYTES 2 // Number of bytes for distance data
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "depth_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance(int *distance);
int log_data(int distance);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Structure for sensor configuration (example)
typedef struct {
    uint8_t config_reg;
    uint8_t config_value;
} sensor_config_t;

// Function to initialize the sensor
int init_sensor() {
    // Configure the sensor (example)
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, CONFIG_VALUE) < 0) {
        fprintf(stderr, "Error writing to configuration register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read distance data from the sensor
int read_distance(int *distance) {
    char buf[DISTANCE_BYTES];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, DISTANCE_BYTES);

    if (bytes_read != DISTANCE_BYTES) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        return -1;
    }

    // Convert the received bytes to a distance value (example)
    *distance = (buf[0] << 8) | buf[1]; // Assuming MSB first
    return 0;
}

// Function to log data to a file
int log_data(int distance) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return -1;
    }

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        free(timestamp);
        return -1;
    }

    if (fprintf(log_file, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        free(timestamp);
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    free(timestamp);
    return 0;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int distance;
    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_data(distance);
        } else {
            // Log error and attempt to re-initialize
            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                fprintf(log_file, "%s,-1\n", timestamp);
                fflush(log_file);
                free(timestamp);
            }
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %s\n", strerror(errno));
                terminate = 1; // Exit if re-initialization fails
            } else {
                if (init_sensor() < 0) {
                    fprintf(stderr, "Sensor re-initialization failed\n");
                    terminate = 1;
                }
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

