#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PARTID 0x00
#define SI1145_REG_REVID 0x01
#define SI1145_REG_SEQID 0x02
#define SI1145_REG_INTCFG 0x03
#define SI1145_REG_IRQEN 0x04
#define SI1145_REG_IRQMODE1 0x05
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEASRATE0 0x08
#define SI1145_REG_MEASRATE1 0x09
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_ALS_IR_DATA0 0x24
#define SI1145_REG_ALS_IR_DATA1 0x25
#define SI1145_REG_PS1_DATA0 0x26
#define SI1145_REG_PS1_DATA1 0x27

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_si1145_data(int *proximity, int *ambient_light);
char *format_log_entry(int proximity, int ambient_light);
int write_to_log(const char *log_entry);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int proximity;
    int ambient_light;
} sensor_data_t;

// Function to initialize the Si1145 sensor
int init_si1145() {
    // Reset the device
    if (i2cWriteByteData(i2c_handle, SI1145_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, SI1145_REG_MEASRATE0, 0x08) < 0) { // Measurement rate
        fprintf(stderr, "Error: Failed to set measurement rate\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SI1145_REG_MEASRATE1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set measurement rate\n");
        return -1;
    }

    // Enable proximity sensor
    if (i2cWriteByteData(i2c_handle, SI1145_REG_IRQEN, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to enable proximity sensor\n");
        return -1;
    }

    return 0;
}

// Function to read data from the Si1145 sensor
int read_si1145_data(int *proximity, int *ambient_light) {
    int prox_low, prox_high, vis_low, vis_high, ir_low, ir_high;

    prox_low = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA0);
    prox_high = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA1);
    vis_low = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    vis_high = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA1);
    ir_low = i2cReadByteData(i2c_handle, SI1145_REG_ALS_IR_DATA0);
    ir_high = i2cReadByteData(i2c_handle, SI1145_REG_ALS_IR_DATA1);

    if (prox_low < 0 || prox_high < 0 || vis_low < 0 || vis_high < 0 || ir_low < 0 || ir_high < 0) {
        fprintf(stderr, "Error: Failed to read sensor data\n");
        return -1;
    }

    *proximity = (prox_high << 8) | prox_low;
    *ambient_light = (vis_high << 8) | vis_low;

    return 0;
}

// Function to format the log entry
char *format_log_entry(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    static char log_entry[256]; // Static to preserve across calls

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    snprintf(log_entry, sizeof(log_entry), "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity, ambient_light);

    return log_entry;
}

// Function to write the log entry to the file
int write_to_log(const char *log_entry) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s", log_entry) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT. Cleaning up...\n");
        terminate = 1;
    }
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1145 sensor
    if (init_si1145() != 0) {
        fprintf(stderr, "Error: Si1145 initialisation failed\n");
        cleanup();
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        cleanup();
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    int proximity, ambient_light;
    char *log_entry;

    while (!terminate) {
        // Read sensor data
        if (read_si1145_data(&proximity, &ambient_light) == 0) {
            // Format log entry
            log_entry = format_log_entry(proximity, ambient_light);

            // Write to log file
            if (write_to_log(log_entry) != 0) {
                fprintf(stderr, "Error: Failed to write log entry\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data in main loop\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup and exit
    cleanup();
    gpioTerminate();
    return 0;
}

