#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_PIN 4
#define LED_PIN 17

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor();
void control_led(int state);
void log_entry();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to log the entry with timestamp
void log_entry() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    FILE *fp;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fp = fopen("proximity.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening proximity.log for writing\n");
        return;
    }

    fprintf(fp, "%s Object detected\n", timestamp);
    fclose(fp);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int last_sensor_state = 1; // Assume sensor is initially HIGH (no object)
    int current_sensor_state;

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        current_sensor_state = read_sensor();

        if (current_sensor_state == 0 && last_sensor_state == 1) {
            // Falling edge detected
            log_entry();
            control_led(1); // Turn LED on
            gpioDelay(100);  // Wait 100ms
            control_led(0); // Turn LED off
        }

        last_sensor_state = current_sensor_state;
        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup GPIO before exiting
    gpioTerminate();
    printf("GPIO terminated. Exiting.\n");

    return 0;
}

