#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000000      // 30 seconds
#define MIN_DISTANCE 2.0        // cm
#define MAX_DISTANCE 400.0      // cm
#define LOG_FILE "distance_log.txt"
#define WATER_THRESHOLD 15.0    // cm
#define LOG_INTERVAL 60          // seconds

// Global variables
static volatile int echo_rising = 0;
static volatile int echo_falling = 0;
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold configuration data
typedef struct {
    int trigger_pin;
    int echo_pin;
    double speed_of_sound;
    int timeout_us;
    double min_distance;
    double max_distance;
    char *log_file;
    double water_threshold;
    int log_interval;
} config_t;

config_t config = {
    TRIGGER_PIN,
    ECHO_PIN,
    SPEED_OF_SOUND,
    TIMEOUT_US,
    MIN_DISTANCE,
    MAX_DISTANCE,
    LOG_FILE,
    WATER_THRESHOLD,
    LOG_INTERVAL
};

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(config.trigger_pin, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(config.trigger_pin, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_rising = 1;
        start_tick = tick;
    } else if (level == 0) {
        echo_falling = 1;
        end_tick = tick;
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width * config.speed_of_sound / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log distance to a file with ISO 8601 timestamp
void log_distance(double distance) {
    FILE *fp = fopen(config.log_file, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    if (distance >= config.min_distance && distance <= config.max_distance) {
        fprintf(fp, "%s, Distance: %.2f cm\n", timestamp, distance);
        if (distance < config.water_threshold) {
            fprintf(fp, "%s, Time to water the plant!\n", timestamp);
        }
    } else {
        fprintf(fp, "%s, Error: Distance out of range (%.2f cm)\n", timestamp, distance);
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.trigger_pin, PI_OUTPUT);
    gpioSetMode(config.echo_pin, PI_INPUT);

    gpioSetAlertFunc(config.echo_pin, echo_callback);

    return 0;
}

// Cleanup function
void cleanup() {
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    time_t last_log_time = 0;

    while (running) {
        trigger_pulse();

        // Wait for echo to rise or timeout
        int timeout_count = 0;
        while (!echo_rising && !echo_falling && timeout_count < 100) {
            gpioDelay(1000); // 1 ms delay
            timeout_count++;
        }

        if (!echo_rising) {
            time_t t = time(NULL);
            struct tm *tm = gmtime(&t);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);
            FILE *fp = fopen(config.log_file, "a");
            if (fp != NULL) {
                fprintf(fp, "%s, Error: Echo never rose\n", timestamp);
                fclose(fp);
            }
            gpioDelay(100000); // 100ms delay before next measurement
            continue;
        }

        // Wait for echo to fall or timeout
        timeout_count = 0;
        while (!echo_falling && timeout_count < 100) {
            gpioDelay(1000); // 1 ms delay
            timeout_count++;
        }

        if (!echo_falling) {
            time_t t = time(NULL);
            struct tm *tm = gmtime(&t);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);
            FILE *fp = fopen(config.log_file, "a");
            if (fp != NULL) {
                fprintf(fp, "%s, Error: Echo never fell\n", timestamp);
                fclose(fp);
            }
            gpioDelay(100000); // 100ms delay before next measurement
            continue;
        }

        uint32_t pulse_width = end_tick - start_tick;

        double distance = calculate_distance(pulse_width);

        if (distance < config.min_distance || distance > config.max_distance) {
            time_t t = time(NULL);
            struct tm *tm = gmtime(&t);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);
            FILE *fp = fopen(config.log_file, "a");
            if (fp != NULL) {
                fprintf(fp, "%s, Error: Distance out of range (%.2f cm)\n", timestamp, distance);
                fclose(fp);
            }
        } else {
            log_distance(distance);
        }

        echo_rising = 0;
        echo_falling = 0;
        start_tick = 0;
        end_tick = 0;

        time_t current_time = time(NULL);
        if (current_time - last_log_time >= config.log_interval) {
            last_log_time = current_time;
        }

        gpioDelay(100000); // 100ms delay before next measurement
    }

    cleanup();
    return 0;
}

