#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C address of the Si1182-GMR sensor
#define SI1182_I2C_ADDR 0x60

// Define the register addresses for proximity and ambient light data
#define SI1182_REG_PROX_DATA 0x24
#define SI1182_REG_ALS_DATA 0x22

// Define the retry count for I2C operations
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light);
int log_data(uint16_t proximity, uint16_t ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to initialize the I2C interface
int initialize_i2c() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(1, SI1182_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light) {
    int retries = 0;
    int result;

    // Read proximity data
    while (retries < I2C_RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, SI1182_REG_PROX_DATA);
        if (result >= 0) {
            *proximity = (uint16_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading proximity data (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }
    if (retries == I2C_RETRY_COUNT) {
        fprintf(stderr, "Failed to read proximity data after %d retries\n", I2C_RETRY_COUNT);
        return -1;
    }

    // Read ambient light data
    retries = 0;
    while (retries < I2C_RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, SI1182_REG_ALS_DATA);
        if (result >= 0) {
            *ambient_light = (uint16_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading ambient light data (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }
    if (retries == I2C_RETRY_COUNT) {
        fprintf(stderr, "Failed to read ambient light data after %d retries\n", I2C_RETRY_COUNT);
        return -1;
    }

    return 0;
}

// Function to log data to a file
int log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get the current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open the log file in append mode
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    // Write the data to the log file
    fprintf(log_file, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, proximity, ambient_light);

    // Close the log file
    fclose(log_file);

    return 0;
}

int main() {
    // Install the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C interface
    if (initialize_i2c() != 0) {
        return 1;
    }

    printf("Biometric sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        uint16_t proximity, ambient_light;

        // Read sensor data
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            // Log the data
            if (log_data(proximity, ambient_light) != 0) {
                fprintf(stderr, "Error logging data!\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data!\n");
        }

        // Wait for 500 milliseconds
        gpioDelay(500);
    }

    // Close the I2C device
    i2cClose(i2c_handle);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Biometric sensor data logging stopped.\n");

    return 0;
}

