#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define HEADER_VALUE 0x02
#define DISTANCE_THRESHOLD 1000 // mm
#define NUM_SAMPLES 10
#define SAMPLE_DELAY_MS 100
#define LOG_FILE "intrusion_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int send_command(int handle, unsigned char *command, int command_length);
int read_response(int handle, unsigned char *response, int response_length);
int verify_header(unsigned char *response, int response_length);
int extract_distance(unsigned char *response);
float calculate_average_distance(int *distances, int num_samples);
int log_intrusion(float average_distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, unsigned char *command, int command_length) {
    int result = i2cWriteDevice(handle, (char *)command, command_length);
    if (result != command_length) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read response from the sensor
int read_response(int handle, unsigned char *response, int response_length) {
    int result = i2cReadDevice(handle, (char *)response, response_length);
    if (result != response_length) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Verify the header
int verify_header(unsigned char *response, int response_length) {
    if (response_length < 1) return -1; // Ensure enough data
    if (response[0] != HEADER_VALUE) {
        fprintf(stderr, "Error: Invalid header value: 0x%02X\n", response[0]);
        return -1;
    }
    return 0;
}

// Extract distance from the response
int extract_distance(unsigned char *response) {
    if (response_length < 13) return -1; // Ensure enough data
    int distance = (response[11] << 8) | response[12];
    return distance;
}

// Calculate the average distance
float calculate_average_distance(int *distances, int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return sum / num_samples;
}

// Log intrusion event
int log_intrusion(float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s, Average Distance: %.2f mm\n", timestamp, average_distance);
    fclose(log_file);
    return 0;
}

