    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Command to request measurement (replace with actual command)
    unsigned char command[] = {0x01, 0x02, 0x03, 0x04}; // Example command
    int command_length = sizeof(command);

    // Response buffer
    unsigned char response[15];

    // Distance array
    int distances[NUM_SAMPLES];

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Send command
        if (send_command(i2c_handle, command, command_length) != 0) {
            fprintf(stderr, "Error sending command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for measurement (adjust as needed)
        gpioDelay(10); // Wait 10ms

        // Read response
        if (read_response(i2c_handle, response, sizeof(response)) != 0) {
            fprintf(stderr, "Error reading response, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Verify header
        if (verify_header(response, sizeof(response)) != 0) {
            fprintf(stderr, "Error verifying header, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Extract distance
        int distance = extract_distance(response);
        if (distance < 0) {
            fprintf(stderr, "Error extracting distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Store distance
        distances[0] = distance; // Overwrite previous value

        // Calculate average distance
        float average_distance = calculate_average_distance(distances, NUM_SAMPLES);

        // Check for intrusion
        if (average_distance < DISTANCE_THRESHOLD) {
            printf("Intrusion detected! Average distance: %.2f mm\n", average_distance);
            if (log_intrusion(average_distance) != 0) {
                fprintf(stderr, "Error logging intrusion!\n");
            }
        }

        gpioDelay(SAMPLE_DELAY_MS); // Delay between samples
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

