#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L0X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L0X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L0X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L0X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0013
#define VL53L0X_REG_RESULT_RANGE_VAL 0x001E
#define VL53L0X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L0X_REG_I2C_SLAVE_DEVICE_ADDRESS_MSB 0x008B

// Expected model ID
#define VL53L0X_MODEL_ID 0xEACC

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l0x_init();
int vl53l0x_read_distance(int *distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// VL53L0X initialization function
int vl53l0x_init() {
    int model_id;

    // Read model ID
    model_id = i2cReadByteData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }

    if (model_id != VL53L0X_MODEL_ID) {
        fprintf(stderr, "Error: Incorrect model ID (0x%02x, expected 0x%02x)\n", model_id, VL53L0X_MODEL_ID);
        return -1;
    }

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, VL53L0X_REG_I2C_SLAVE_DEVICE_ADDRESS_MSB, 0x00) < 0) {
        fprintf(stderr, "Error writing I2C slave address MSB: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L0X_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L0X_ADDR) < 0) {
        fprintf(stderr, "Error writing I2C slave address LSB: %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, VL53L0X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) < 0) {
        fprintf(stderr, "Error writing pre-range timeout: %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, VL53L0X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) < 0) {
        fprintf(stderr, "Error writing final range timeout: %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, VL53L0X_REG_SYSTEM_SEQUENCE_CONFIG, 0x06) < 0) {
        fprintf(stderr, "Error writing sequence config: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// VL53L0X distance reading function
int vl53l0x_read_distance(int *distance) {
    int range_status, interrupt_status, range_val;

    // Poll RESULT_INTERRUPT_STATUS with timeout
    int timeout_count = 0;
    do {
