#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 38000.0  // us (38ms)
#define TIMEOUT 200000.0      // us (200ms)

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
double measure_distance();
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;
    static uint32_t end_tick = 0;
    static int echo_active = 0;

    if (level == 1) {
        // Rising edge
        start_tick = tick;
        echo_active = 1;
    } else if (level == 0) {
        // Falling edge
        end_tick = tick;
        echo_active = 0;
    }
}

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance
double measure_distance() {
    uint32_t start_tick = 0;
    uint32_t end_tick = 0;
    uint32_t pulse_duration = 0;
    double distance = -1.0; // Initialize to an invalid value

    // Set up callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Trigger the sensor
    trigger_pulse();

    // Wait for echo or timeout
    int timeout_count = 0;
    while (pulse_duration == 0 && timeout_count < TIMEOUT) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (pulse_duration == 0) {
        fprintf(stderr, "Error: Echo timeout\n");
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable callback
        return -1.0; // Indicate timeout
    }

    // Calculate pulse duration
    pulse_duration = end_tick - start_tick;

    // Validate pulse duration
    if (pulse_duration <= 0 || pulse_duration > MAX_DISTANCE) {
        fprintf(stderr, "Error: Invalid pulse duration: %u us\n", pulse_duration);
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable callback
        return -1.0; // Indicate invalid duration
    }

    // Calculate distance
    distance = (double)pulse_duration * SPEED_OF_SOUND / 2000000.0; // cm

    // Disable callback
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);

    return distance;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        double distance = measure_distance();

        if (distance > 0) {
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("[%s] Distance: %.2f cm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

