#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 1.0
#define LED_ON_TIME 2 // seconds

// Global variables
int uart_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_uart_data(int handle, unsigned char *buffer, int max_length);
int validate_magic_word(const unsigned char *buffer, int length);
int decode_range_profile(const unsigned char *buffer, float *range_profile);
int detect_intrusion(const float *range_profile, int num_bins, float threshold);
int log_intrusion(const char *timestamp, float distance);
int control_led(int pin, int state, int duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize UART
int initialize_uart(const char *device, int baud_rate) {
    int handle = serOpen(device, baud_rate, 0); // 0 for default flags
    if (handle < 0) {
        fprintf(stderr, "Error opening UART: %s\n", device);
        return -1;
    }
    return handle;
}

// Read data from UART
int read_uart_data(int handle, unsigned char *buffer, int max_length) {
    int bytes_read = serRead(handle, buffer, max_length);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART.\n");
        return -1;
    }
    return bytes_read;
}

// Validate magic word
int validate_magic_word(const unsigned char *buffer, int length) {
    if (length < MAGIC_WORD_SIZE) {
        return 0; // Not enough data for magic word
    }

    // Simple check: compare first 4 bytes to 0x02B2A101 and last 4 bytes to 0x03B3A202
    if (buffer[0] == 0x02 && buffer[1] == 0xB2 && buffer[2] == 0xA1 && buffer[3] == 0x01 &&
        buffer[4] == 0x03 && buffer[5] == 0xB3 && buffer[6] == 0xA2 && buffer[7] == 0x02) {
        return 1;
    } else {
        return 0;
    }
}

// Decode range profile
int decode_range_profile(const unsigned char *buffer, float *range_profile) {
    if (buffer == NULL || range_profile == NULL) {
        fprintf(stderr, "Error: Null pointer passed to decode_range_profile.\n");
        return -1;
    }

    for (int i = 0; i < 64; i++) {
        // Extract 16-bit little-endian value from the buffer
        short raw_value = (short)((buffer[i * 2 + 1] << 8) | buffer[i * 2]);

        // Convert to float (assuming raw_value is a signed integer)
        range_profile[i] = (float)raw_value; // Or apply a scaling factor if needed
    }
    return 0;
}

// Detect intrusion
int detect_intrusion(const float *range_profile, int num_bins, float threshold) {
    for (int i = 0; i < num_bins; i++) {
        if (range_profile[i] > threshold) {
            return 1; // Intrusion detected
        }
    }
    return 0; // No intrusion detected
}

// Log intrusion
int log_intrusion(const char *timestamp, float distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Control LED
int control_led(int pin, int state, int duration) {
    gpioWrite(pin, state);
    gpioDelay(duration * 1000000); // Convert seconds to microseconds
    gpioWrite(pin, 0); // Turn off LED after duration
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize UART
    uart_handle = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (uart_handle < 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char buffer[RANGE_PROFILE_SIZE + MAGIC_WORD_SIZE];
    float range_profile[64];
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read data from UART
        int bytes_read = read_uart_data(uart_handle, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            // Validate magic word
            if (validate_magic_word(buffer, bytes_read)) {
                // Extract range profile data (after the magic word)
                const unsigned char *range_data = buffer + MAGIC_WORD_SIZE;
                if (decode_range_profile(range_data, range_profile) == 0) {
                    // Detect intrusion
                    if (detect_intrusion(range_profile, 64, DISTANCE_THRESHOLD)) {
                        // Get current timestamp
                        time(&rawtime);
                        timeinfo = localtime(&rawtime);
                        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

                        // Log intrusion
                        if (log_intrusion(timestamp, DISTANCE_THRESHOLD)) {
                            fprintf(stderr, "Error logging intrusion.\n");
                        }

                        // Activate alert LED
                        control_led(GPIO_PIN, 1, LED_ON_TIME);
                    }
                }
            }
        }
        gpioDelay(10000); // Check every 10ms
    }

    // Clean up
    serClose(uart_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Intrusion detection system stopped.\n");
    return 0;
}

