    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read distance from the sensor
int read_distance(float *distance) {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }

    // Assuming the sensor returns two bytes representing the distance in cm
    // Convert the two bytes to a float (example, adjust based on sensor datasheet)
    uint16_t raw_distance = (buf[0] << 8) | buf[1];
    *distance = (float)raw_distance / 10.0f; // Example conversion

    return 0;
}

