    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            set_gpio_alert(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpio delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

