#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses (example, adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR 0x0027
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN 0x0029
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void log_distance(int distance);
void print_guidance(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// VL53L1X initialization function
int vl53l1x_init() {
    // Example initialization sequence (adjust based on datasheet)
    char data[2];

    // Check sensor ID (example)
    data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (data[0] != 0xEACC) {
        fprintf(stderr, "Error: Incorrect sensor ID (0x%02X)\n", data[0]);
        return -1;
    }

    // Configure sensor (example)
    data[0] = VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR;
    data[1] = 0x10; // Example value
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    data[0] = VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN;
    data[1] = 0x05; // Example value
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    data[0] = VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG;
    data[1] = 0x40; // Example value
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance(int *distance) {
    char cmd[1];
    char data[2];
    int retries = 3;

    cmd[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            retries--;
            gpioDelay(1000); // Wait 1ms before retry
            continue;
        }

        if (i2cReadDevice(i2c_handle, data, 2) != 2) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            retries--;
            gpioDelay(1000); // Wait 1ms before retry
            continue;
        }

        *distance = (data[0] << 8) | data[1];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Failure
}

// Log distance to file function
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Print guidance message function
void print_guidance(int distance) {
    if (distance < 300) {
        printf("STOP\n");
    } else if (distance < 600) {
        printf("APPROACH\n");
    } else if (distance < 1200) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

int main() {
    int distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }
    rewind(log_file);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance from VL53L1X
        if (vl53l1x_read_distance(&distance) == 0) {
            // Log distance
            log_distance(distance);

            // Print guidance message
            print_guidance(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

