// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x50
#define LED_GPIO 18
#define BLINK_HALF_CYCLE_US 50000 // 50ms
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(int *distance);
void set_led_frequency(int distance);
void blink_led(int on);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ch201_address;
    int led_gpio;
    int blink_half_cycle_us;
    int max_retries;
    int retry_delay_ms;
} config_t;

config_t config = {
    I2C_BUS,
    CH201_ADDR,
    LED_GPIO,
    BLINK_HALF_CYCLE_US,
    MAX_RETRIES,
    RETRY_DELAY_MS
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

