            set_led_frequency(distance);

            // Get current timestamp
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

            // Log timestamp, distance, and LED frequency
            printf("%s, Distance: %d mm, LED Frequency: %d Hz\n", buf, distance, 1000000 / (BLINK_HALF_CYCLE_US * 2)); // Calculate frequency
        } else {
            fprintf(stderr, "Failed to read distance\n");
