int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.ch201_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read distance from CH201 sensor
int read_distance(int *distance) {
    char buf[2];
    int retries = 0;
    int bytes_read;

    while (retries < config.max_retries) {
        bytes_read = i2cReadDevice(i2c_handle, buf, 2);
        if (bytes_read == 2) {
            // Combine the two bytes to form the distance
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, bytes_read);
            retries++;
            gpioDelay(config.retry_delay_ms * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read distance after %d retries\n", config.max_retries);
    return 1; // Failure
}

// Set LED frequency based on distance
void set_led_frequency(int distance) {
    // Map distance to blink frequency (example: 100mm -> 1Hz, 50mm -> 10Hz)
    // This is a simple linear mapping.  Adjust as needed.
    int frequency = 1000000 / distance; // Example: Inverse relationship
    if (frequency > 100) frequency = 100; // Cap the frequency
    if (frequency < 1) frequency = 1; // Minimum frequency

    // Calculate the on/off time based on the desired frequency
    int on_time_us = BLINK_HALF_CYCLE_US * (100 - frequency) / 100; // Adjust on time
    int off_time_us = BLINK_HALF_CYCLE_US * frequency / 100;      // Adjust off time

    // Blink the LED
    blink_led(1); // Turn on
    gpioDelay(on_time_us);
    blink_led(0); // Turn off
    gpioDelay(off_time_us);
}

