void blink_led(int on) {
    gpioWrite(config.led_gpio, on);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    // Turn off LED
    gpioWrite(config.led_gpio, 0);

    // Close I2C
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Terminate pigpio
    gpioTerminate();
}

