#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define MEASURE_CMD 0x01
#define DISTANCE_REG 0x00
#define DISTANCE_CM_MASK 0x3FFF // Mask for distance value (14 bits)
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_distance(uint16_t *distance);
int log_data(time_t timestamp, uint16_t distance);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int mlx75030_address;
    char *log_file_name;
} config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    int result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read distance data
int read_distance(uint16_t *distance) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    *distance = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    *distance &= DISTANCE_CM_MASK; // Apply mask
    return 0;
}

// Log data to file
int log_data(time_t timestamp, uint16_t distance) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp_str, distance);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    config_t config = {
        .i2c_bus = I2C_BUS,
        .mlx75030_address = MLX75030_ADDR,
        .log_file_name = "distance_log.csv"
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Starting distance measurement...\n");

    // Main loop
    while (!terminate) {
        uint16_t distance;
        time_t timestamp;
        int retries = 0;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Measurement trigger failed, retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Wait for measurement to complete (adjust as needed)
        gpioDelay(10000); // 10ms delay

        // Read distance with retries
        while (retries < MAX_RETRIES) {
            if (read_distance(&distance) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Distance read failed, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retries++;
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached, skipping data point.\n");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay before next sample
            continue;
        }

        // Get timestamp
        timestamp = time(NULL);

        // Log data
        if (log_data(timestamp, distance) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

