#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x50
#define MEAS_STATUS_REG 0x00
#define DISTANCE_REG 0x01
#define TIMEOUT_US 50000 // 50 ms
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILE "distance_log.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_then_read(int fd, unsigned char reg, unsigned char *buf, int count);
int read_distance(int fd);
void log_distance(FILE *fp, int distance);
void signal_handler(int sig);
int setup();
void cleanup();

// I2C write-then-read transaction
int i2c_write_then_read(int fd, unsigned char reg, unsigned char *buf, int count) {
    unsigned char write_buf[1];
    write_buf[0] = reg;

    if (write(fd, write_buf, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }

    if (read(fd, buf, count) != count) {
        perror("I2C read failed");
        return -1;
    }

    return 0;
}

// Read distance from the sensor
int read_distance(int fd) {
    unsigned char status_buf[1];
    unsigned char distance_buf[2];
    int status;

    // Poll MEAS_STATUS register with timeout
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    do {
        if (i2c_write_then_read(fd, MEAS_STATUS_REG, status_buf, 1) != 0) {
            fprintf(stderr, "Error reading status register\n");
            return -1;
        }
        status = status_buf[0];
        clock_gettime(CLOCK_MONOTONIC, &now);
    } while (((now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000) < TIMEOUT_US);

    if ((status & 0x01) == 0) {
        fprintf(stderr, "Measurement not ready\n");
        return -1;
    }

    // Read distance data
    if (i2c_write_then_read(fd, DISTANCE_REG, distance_buf, 2) != 0) {
        fprintf(stderr, "Error reading distance register\n");
        return -1;
    }

    return (distance_buf[0] << 8) | distance_buf[1];
}

// Log distance to CSV file
void log_distance(FILE *fp, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(fp, "%s,%d\n", timestamp, distance);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup function
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C device
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return -1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,distance_mm\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup() != 0) {
        return 1;
    }

    fprintf(stderr, "Starting distance measurement...\n");

    while (!terminate) {
        int distance = read_distance(i2c_fd);
        if (distance >= 0) {
            log_distance(csv_file, distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 500 ms
    }

    cleanup();
    fprintf(stderr, "Exiting.\n");
    return 0;
}

