#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define VL53L5CX_ADDR 0x29

// Define register addresses (replace with actual values from datasheet)
#define VL53L5CX_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L5CX_REG_SYSTEM_START 0x0001
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L5CX_REG_RESULT_SPAD_NB 0x001E
#define VL53L5CX_REG_RESULT_SIGNAL_RATE 0x0022
#define VL53L5CX_REG_RESULT_AMBIENT_RATE 0x0024
#define VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0018
#define VL53L5CX_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L5CX_REG_I2C_SLAVE_DEVICE_ADDRESS_MSB 0x008B
#define VL53L5CX_REG_ZONE_CONFIG 0x0030
#define VL53L5CX_REG_ZONE_DATA_START 0x0040

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor configuration
typedef struct {
    uint8_t zone_config;
} sensor_config_t;

// Function prototypes
int i2c_read_register(uint16_t reg_addr, uint8_t *data, int len);
int i2c_write_register(uint16_t reg_addr, uint8_t *data, int len);
int vl53l5cx_init();
int vl53l5cx_read_zone_data(uint16_t *zone_distances);
void signal_handler(int signal);

// I2C read function
int i2c_read_register(uint16_t reg_addr, uint8_t *data, int len) {
    uint8_t buf[2];
    buf[0] = (reg_addr >> 8) & 0xFF; // MSB of register address
    buf[1] = reg_addr & 0xFF;        // LSB of register address

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(i2c_fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

// I2C write function
int i2c_write_register(uint16_t reg_addr, uint8_t *data, int len) {
    uint8_t buf[len + 2];
    buf[0] = (reg_addr >> 8) & 0xFF; // MSB of register address
    buf[1] = reg_addr & 0xFF;        // LSB of register address
    memcpy(buf + 2, data, len);

    if (write(i2c_fd, buf, len + 2) != len + 2) {
        perror("Failed to write data");
        return -1;
    }

    return 0;
}

// VL53L5CX initialization function
int vl53l5cx_init() {
    uint8_t model_id;

    // Check sensor ID
    if (i2c_read_register(VL53L5CX_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }

    if (model_id != 0xE1) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", model_id);
        return -1;
    }

    // Configure for 8x8 zone grid
    uint8_t zone_config_data[2] = {0x00, 0x00}; // Example configuration, adjust as needed
    if (i2c_write_register(VL53L5CX_REG_ZONE_CONFIG, zone_config_data, 2) != 0) {
        fprintf(stderr, "Error writing zone config\n");
        return -1;
    }

    // Start the sensor
    uint8_t start_data[1] = {0x01};
    if (i2c_write_register(VL53L5CX_REG_SYSTEM_START, start_data, 1) != 0) {
        fprintf(stderr, "Error starting sensor\n");
        return -1;
    }

    return 0;
}

// VL53L5CX read zone data function
int vl53l5cx_read_zone_data(uint16_t *zone_distances) {
    uint8_t data[128]; // 64 zones * 2 bytes each
    if (i2c_read_register(VL53L5CX_REG_ZONE_DATA_START, data, 128) != 0) {
        fprintf(stderr, "Error reading zone data\n");
        return -1;
    }

    // Convert data to distances (adjust based on sensor data format)
    for (int i = 0; i < 64; i++) {
        zone_distances[i] = (data[2 * i] << 8) | data[2 * i + 1];
    }

    return 0;
}

