        return -1;
    }

    // Wait for measurement to complete (polling interrupt status)
    int timeout = 100; // Timeout after 100ms
    while (timeout > 0) {
        if (vl53l4cx_poll_interrupt() > 0) {
            break;
        }
        gpioDelay(1); // Wait 1ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for interrupt\n");
        return -1;
