// Function to read distance from the VL53L4CX sensor
int vl53l4cx_read_distance(uint16_t *distance) {
    char cmd[1];
    char data[2];
    int status;

    // Start a single measurement
    cmd[0] = VL53L4CX_REG_SYSRANGE_START;
    data[0] = 0x01; // Start measurement
    status = i2cWriteDevice(i2c_handle, cmd, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to start measurement register: %d\n", status);
        return -1;
    }
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to start measurement value: %d\n", status);
        return -1;
    }

    // Wait for measurement to complete (polling interrupt status)
    int timeout = 100; // Timeout after 100ms
    while (timeout > 0) {
        if (vl53l4cx_poll_interrupt() > 0) {
            break;
        }
        gpioDelay(1); // Wait 1ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for interrupt\n");
        return -1;
    }

    // Read the distance
    cmd[0] = VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    status = i2cWriteDevice(i2c_handle, cmd, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to distance register: %d\n", status);
        return -1;
    }
    status = i2cReadDevice(i2c_handle, data, 2);
    if (status != 0) {
        fprintf(stderr, "Error reading distance: %d\n", status);
        return -1;
    }

    *distance = (uint16_t)((data[0] << 8) | data[1]);

    return 0;
}

// Function to poll the VL53L4CX interrupt status register
int vl53l4cx_poll_interrupt() {
    char cmd[1];
    char data[1];
    int status;

    cmd[0] = VL53L4CX_REG_INT_STATUS;
    status = i2cWriteDevice(i2c_handle, cmd, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to interrupt status register: %d\n", status);
        return -1;
    }
    status = i2cReadDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error reading interrupt status: %d\n", status);
        return -1;
    }

    if (data[0] & 0x01) { // Check if interrupt is set (bit 0)
        return 1;
    } else {
        return 0;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L4CX sensor
    if (vl53l4cx_init() != 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t distance;
        struct timespec ts;
        char timestamp[30];
        int status;

        // Read distance
        status = vl53l4cx_read_distance(&distance);
        if (status == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                // Format timestamp
                struct tm tm_info;
                localtime_r(&ts.tv_sec, &tm_info);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
                snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

                // Log distance with timestamp
                printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        // Poll interrupt status
        if (vl53l4cx_poll_interrupt() == 0) {
            // Skip cycle if interrupt is not set
            gpioDelay(500); // Wait 500ms
        } else {
            // Handle interrupt (e.g., clear interrupt, process data)
            char cmd[1];
            char data[1];
            cmd[0] = VL53L4CX_REG_INT_STATUS;
            data[0] = 0x01; // Clear interrupt
            status = i2cWriteDevice(i2c_handle, cmd, 1);
            if (status != 0) {
                fprintf(stderr, "Error writing to clear interrupt register: %d\n", status);
            }
            status = i2cWriteDevice(i2c_handle, data, 1);
            if (status != 0) {
                fprintf(stderr, "Error writing to clear interrupt value: %d\n", status);
            }
            gpioDelay(500); // Wait 500ms
        }
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

