#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_ANGLE -90.0       // degrees
#define MAX_ANGLE 90.0        // degrees
#define TIMEOUT_MS 50          // ms
#define LOOP_DELAY_MS 200      // ms

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_sensor();
long pulse_width();
float calculate_distance(long pulse_width);
float map_distance_to_angle(float distance);
void set_servo_angle(float angle);
void log_data(float distance, float angle);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the pulse width of the echo signal
long pulse_width() {
    long start_time = 0, end_time = 0;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_MS * 1000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_MS * 1000) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1; // Timeout
    }

    start_time = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_MS * 1000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_MS * 1000) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1; // Timeout
    }

    end_time = gpioTick();

    return end_time - start_time;
}

// Calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 for one-way distance
}

// Map distance to servo angle
float map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Set the servo angle
void set_servo_angle(float angle) {
    int pulse_width = 500 + (int)(angle * 2000.0 / 180.0); // Map angle to pulse width (500-2500 us)
    gpioServo(SERVO_PIN, pulse_width);
}

// Log data to file
void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %.2f degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor();
        long pulse_width = pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            if (distance > 0) {
                float angle = map_distance_to_angle(distance);
                set_servo_angle(angle);
                log_data(distance, angle);
            } else {
                fprintf(stderr, "Invalid distance reading\n");
            }
        } else {
            fprintf(stderr, "Sensor timeout\n");
        }

        gpioDelay(LOOP_DELAY_MS * 1000); // Delay for 200 ms
    }

    // Stop servo and release resources
    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate();          // Terminate pigpio

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Parking assist system stopped.\n");

    return 0;
}

