#define VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Message queue structure
typedef struct {
    long mtype; // Message type (must be > 0)
    int distance;
} message_queue_t;

// Global variables
int i2c_handle;
int message_queue_id;
volatile sig_atomic_t program_running = 1;

