void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (adjust as needed)
    char init_data[] = {0x00, 0x01}; // Example register and value
    int result = i2cWriteDevice(i2c_handle, init_data, sizeof(init_data));
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    char reg_addr = VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    char buffer[2];
    int distance;

    // Write register address to be read
    if (i2cWriteDevice(i2c_handle, &reg_addr, 1) != 0) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }

    // Read 2 bytes of distance data
    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes to form the distance
    distance = (buffer[0] << 8) | buffer[1];

    return distance;
}

// Control buzzer state
void control_buzzer(int state) {
    gpioWrite(BUZZER_GPIO, state);
}

// Send distance to message queue
int send_distance_to_queue(int distance) {
    message_queue_t message;
    message.mtype = 1; // Message type
    message.distance = distance;

