#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 200000       // 200ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define BUZZER_THRESHOLD 30.0  // cm

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick, void *user);
float calculate_distance(unsigned int pulse_width);
void control_buzzer(float distance);
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, unsigned int tick, void *user) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate echo start
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 0; // Reset echo flag
    }
}

// Function to calculate distance in centimeters
float calculate_distance(unsigned int pulse_width) {
    float time = (float)(end_tick - start_tick) / 1000000.0; // Time in seconds
    float distance = (time * SPEED_OF_SOUND) / 2.0;         // Distance in cm
    return distance;
}

// Function to control the buzzer based on distance
void control_buzzer(float distance) {
    if (distance < BUZZER_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register interrupt callback for echo pin
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        trigger_pulse(); // Send trigger pulse

        // Wait for echo or timeout
        unsigned int start_time = gpioTick();
        while (end_tick == 0 && (gpioTick() - start_time) < TIMEOUT_US) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        if (end_tick == 0) {
            // Timeout occurred
            printf("Timeout: No echo received\n");
            gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
        } else {
            // Calculate distance
            unsigned int pulse_width = end_tick - start_tick;
            float distance = calculate_distance(pulse_width);

            // Validate distance
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                printf("Distance: %.2f cm\n", distance);
                control_buzzer(distance);
            } else {
                printf("Invalid reading: %.2f cm\n", distance);
                gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
            }
        }

        gpioDelay(100); // Wait 100ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

