#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_MS 60
#define MIN_PULSE_WIDTH 100 // us
#define MAX_PULSE_WIDTH 30000 // us

// Global variables
static volatile unsigned int rising_tick = 0;
static volatile unsigned int falling_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
double calculate_distance(unsigned int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);
int initialize_gpio();
void cleanup();

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin interrupts
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        rising_tick = tick;
        echo_received = 1;
    } else if (level == 0) {
        falling_tick = tick;
        echo_received = 0;
    }
}

// Function to calculate distance in centimeters
double calculate_distance(unsigned int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        return -1.0; // Indicate invalid reading
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    printf("%s, %.2f\n", timestamp, distance);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    gpioWrite(TRIG_PIN, 0); // Ensure TRIG is low initially

    // Register callback function for ECHO pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO pin\n");
        gpioTerminate();
        return 1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to perform cleanup
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();
        echo_received = 0; // Reset echo received flag
        rising_tick = 0; // Reset rising tick
        falling_tick = 0; // Reset falling tick

        gpioDelay(TIMEOUT_MS * 1000); // Wait for timeout (60ms)

        if (!echo_received) {
            fprintf(stderr, "Timeout: No echo received within %d ms\n", TIMEOUT_MS);
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
            fprintf(log_file, "%s, Timeout\n", timestamp);
            fflush(log_file);
            printf("%s, Timeout\n", timestamp);
        } else {
            unsigned int pulse_width;
            if (rising_tick < falling_tick) {
                pulse_width = falling_tick - rising_tick;
            } else {
                pulse_width = (0xFFFFFFFF - rising_tick) + falling_tick + 1; // Handle tick wraparound
            }

            double distance = calculate_distance(pulse_width);

            if (distance > 0) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Invalid pulse width: %u us\n", pulse_width);
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[80];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
                fprintf(log_file, "%s, Invalid pulse width: %u us\n", timestamp, pulse_width);
                fflush(log_file);
                printf("%s, Invalid pulse width: %u us\n", timestamp, pulse_width);
            }
        }

        gpioDelay(200000); // Wait 200ms before next trigger
    }

    cleanup();
    return 0;
}

