    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    printf("%s, %.2f\n", timestamp, distance);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    gpioWrite(TRIG_PIN, 0); // Ensure TRIG is low initially

    // Register callback function for ECHO pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO pin\n");
        gpioTerminate();
        return 1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to perform cleanup
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();
        echo_received = 0; // Reset echo received flag
        rising_tick = 0; // Reset rising tick
        falling_tick = 0; // Reset falling tick

        gpioDelay(TIMEOUT_MS * 1000); // Wait for timeout (60ms)

        if (!echo_received) {
            fprintf(stderr, "Timeout: No echo received within %d ms\n", TIMEOUT_MS);
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
            fprintf(log_file, "%s, Timeout\n", timestamp);
            fflush(log_file);
            printf("%s, Timeout\n", timestamp);
        } else {
            unsigned int pulse_width;
            if (rising_tick < falling_tick) {
                pulse_width = falling_tick - rising_tick;
            } else {
                pulse_width = (0xFFFFFFFF - rising_tick) + falling_tick + 1; // Handle tick wraparound
            }

            double distance = calculate_distance(pulse_width);

            if (distance > 0) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Invalid pulse width: %u us\n", pulse_width);
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[80];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
                fprintf(log_file, "%s, Invalid pulse width: %u us\n", timestamp, pulse_width);
                fflush(log_file);
                printf("%s, Invalid pulse width: %u us\n", timestamp, pulse_width);
            }
        }

        gpioDelay(200000); // Wait 200ms before next trigger
    }

    cleanup();
    return 0;
}

