int vl53l1x_init() {
    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor model ID
    char buf[2];
    buf[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        i2cClose(i2c_handle);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error reading from I2C device\n");
        i2cClose(i2c_handle);
        return -1;
    }

    if (buf[0] != 0xEA) {
        fprintf(stderr, "Incorrect sensor model ID: 0x%02x\n", buf[0]);
        i2cClose(i2c_handle);
        return -1;
    }

    // Perform initialization sequence (example)
    for (int i = 0; i < sizeof(init_sequence) / 2; i++) {
        char buf[2];
        buf[0] = init_sequence[2 * i];
        buf[1] = init_sequence[2 * i + 1];
        if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
            fprintf(stderr, "Error writing to I2C device during init\n");
            i2cClose(i2c_handle);
            return -1;
        }
        gpioDelay(10); // Small delay after each write
    }

    // Set shutdown pin high to enable sensor
    gpioWrite(SHUTDOWN_GPIO, 1);

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance() {
    char buf[1];
    char read_buf[2];

    // Check if measurement is ready
    buf[0] = VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device (ready check)\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error reading from I2C device (ready check)\n");
        return -1;
    }

    if (buf[0] != 1) {
        fprintf(stderr, "Measurement not ready\n");
        return -1;
    }

    // Read range status
    buf[0] = VL53L1X_REG_RESULT_RANGE_STATUS;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device (range status)\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error reading from I2C device (range status)\n");
        return -1;
    }

    if (buf[0] != 0) {
        fprintf(stderr, "Invalid range status: 0x%02x\n", buf[0]);
        return -1;
    }

    // Read distance
    buf[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device (distance)\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 0) {
        fprintf(stderr, "Error reading from I2C device (distance)\n");
        return -1;
    }

    return (read_buf[0] << 8) | read_buf[1];
}

// Servo control functions
void servo_open() {
    gpioPWM(SERVO_GPIO, SERVO_OPEN_PULSE / 1000); // pigpio PWM range is 0-1000
}

void servo_close() {
