void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    // This function is called when the interrupt pin (INT_GPIO) changes state.
    // In this example, we simply read the distance and update the gate state.
    // More complex interrupt handling could be implemented here, such as
    // triggering an event when the gate opens or closes.
    distance = vl53l1x_read_distance();
    if (distance < 0) {
        fprintf(stderr, "Error reading distance in interrupt handler\n");
    }
}

