#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_OPEN 18
#define GPIO_CLOSE 19
#define DISTANCE_THRESHOLD 200 // mm
#define TIMING_BUDGET 50 // ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(uint16_t *distance);
int control_gate(uint16_t distance);
void log_event(const char *event);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// VL53L1X initialization function
int vl53l1x_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x00, 0x01) < 0) {
        log_event("Error: Soft reset failed");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Example configuration (adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, 0x00, 0x00) < 0) { // Example register write
        log_event("Error: Failed to write configuration");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01) < 0) {
        log_event("Error: Failed to start ranging");
        return -1;
    }

    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance(uint16_t *distance) {
    int range_status;
    uint8_t data[2];

    // Read range status
    range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        log_event("Error: Failed to read range status");
        return -1;
    }

    // Read distance data
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)data, 2) != 2) {
        log_event("Error: Failed to read distance data");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];

    return 0;
}

// Control gate function
int control_gate(uint16_t distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_OPEN, 1);
        gpioWrite(GPIO_CLOSE, 0);
        log_event("Gate OPEN");
    } else {
        gpioWrite(GPIO_OPEN, 0);
        gpioWrite(GPIO_CLOSE, 1);
        log_event("Gate CLOSED");
    }
    return 0;
}

// Log event function
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        log_event("Error: Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
