#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define DISTANCE_SENSOR_PIN 24

// Define distance thresholds
#define DISTANCE_THRESHOLD_FORWARD 100
#define DISTANCE_THRESHOLD_BACKWARD 300

// Define VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// Define VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile int distance = 0; // Distance measured by the sensor
volatile int motor_state = 0; // 0: stopped, 1: forward, 2: backward
volatile int running = 1; // Flag to control the main loop

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void motor_forward();
void motor_backward();
void motor_stop();
void distance_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
void log_message(const char *message);

// VL53L1X initialization sequence
int vl53l1x_init() {
    int retries = 0;
    int status;

    // Soft reset
    while (retries < 3) {
        status = i2cWriteByteData(i2c_handle, 0x00, 0x01); // Reset command
        if (status == 0) break; // Success
        fprintf(stderr, "VL53L1X reset failed (attempt %d): %d\n", retries + 1, status);
        gpioDelay(1000); // 1 ms delay
        retries++;
    }
    if (retries == 3) {
        fprintf(stderr, "VL53L1X reset failed after multiple retries.\n");
        return -1;
    }
    gpioDelay(1000); // Wait for reset to complete

    // Check device ID
    int device_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (device_id < 0) {
        fprintf(stderr, "Failed to read device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0xEACC) {
        fprintf(stderr, "Incorrect device ID: 0x%X\n", device_id);
        return -1;
    }

    // Start continuous ranging
    retries = 0;
    while (retries < 3) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01);
        if (status == 0) break; // Success
        fprintf(stderr, "Failed to start ranging (attempt %d): %d\n", retries + 1, status);
        gpioDelay(1000); // 1 ms delay
        retries++;
    }
    if (retries == 3) {
        fprintf(stderr, "Failed to start ranging after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int vl53l1x_read_distance() {
    int status;
    int distance = -1; // Initialize to an invalid value
    int retries = 0;

    // Poll status register until data is ready
    while (retries < 3) {
        int status_reg = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (status_reg < 0) {
            fprintf(stderr, "Failed to read status register (attempt %d): %d\n", retries + 1, status_reg);
            gpioDelay(1000); // 1 ms delay
            retries++;
            continue;
        }

        if (status_reg & 0x01) { // Data ready
            break;
        } else {
            gpioDelay(1000); // 1 ms delay
            retries++;
        }
    }

    if (retries == 3) {
        fprintf(stderr, "Timeout waiting for data ready.\n");
        return -1;
    }

    // Read distance value
    retries = 0;
    while (retries < 3) {
        distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (distance >= 0) break; // Success
        fprintf(stderr, "Failed to read distance (attempt %d): %d\n", retries + 1, distance);
        gpioDelay(1000); // 1 ms delay
        retries++;
    }

    if (retries == 3) {
        fprintf(stderr, "Failed to read distance after multiple retries.\n");
        return -1;
    }

    return distance;
}

// Motor control functions
void motor_forward() {
    if (motor_state != 1) {
        gpioWrite(MOTOR_FORWARD_PIN, 1);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        motor_state = 1;
        log_message("Motor running forward");
    }
}

void motor_backward() {
    if (motor_state != 2) {
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 1);
        motor_state = 2;
        log_message("Motor running backward");
    }
}

void motor_stop() {
    if (motor_state != 0) {
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        motor_state = 0;
        log_message("Motor stopped");
    }
}

// Distance callback function
void distance_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        distance = vl53l1x_read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance in callback.\n");
            motor_stop();
        } else {
            char message[100];
            snprintf(message, sizeof(message), "Distance: %d mm", distance);
            log_message(message);

            if (distance < DISTANCE_THRESHOLD_FORWARD) {
                motor_forward();
            } else if (distance > DISTANCE_THRESHOLD_BACKWARD) {
                motor_backward();
            } else {
                motor_stop();
            }
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message("Signal received, stopping motor and cleaning up...");
    running = 0;
    motor_stop();
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Logging function
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0); // Bus 1, address 0x29, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(DISTANCE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(DISTANCE_SENSOR_PIN, PI_PUD_DOWN); // Optional pull-down resistor

    // Set up interrupt on rising edge of distance sensor pin
    if (gpioSetISRFuncEx(DISTANCE_SENSOR_PIN, RISING_EDGE, 0, distance_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Program started");

    // Main loop
    while (running) {
        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    return 0;
}

