// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define LED_GPIO_0 17
#define LED_GPIO_1 18
#define LED_GPIO_2 27
#define LED_GPIO_3 22
#define NUM_ELECTRODES 12
#define POLL_INTERVAL_MS 50

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int init_mpr121();
int read_touch_status(uint16_t *touch_status);
void set_led_pattern(uint8_t pattern);
void log_event(int electrode);
void signal_handler(int signal);

// Structure to hold GPIO pins for LEDs
typedef struct {
    int gpio_0;
    int gpio_1;
    int gpio_2;
    int gpio_3;
} led_pins_t;

led_pins_t led_pins = {LED_GPIO_0, LED_GPIO_1, LED_GPIO_2, LED_GPIO_3};

// Function to initialize GPIO pins
int init_gpio() {
    if (gpioSetMode(led_pins.gpio_0, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(led_pins.gpio_1, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(led_pins.gpio_2, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(led_pins.gpio_3, PI_OUTPUT) < 0) return -1;
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error resetting MPR121\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

