#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTERTH_L 0x24
#define MPR121_FILTERTH_H 0x25
#define MPR121_BASELINETH_L 0x26
#define MPR121_BASELINETH_H 0x27
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_MHDT 0x33
#define MPR121_NHDT 0x34
#define MPR121_NCLT 0x35
#define MPR121_FDLT 0x36
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// GPIO pin for LED
#define LED_PIN 27

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_read_register(int handle, uint8_t reg);
int mpr121_write_register(int handle, uint8_t reg, uint8_t value);
int mpr121_init(int handle);
int proximity_detected(int handle);
void led_on(int pin);
void led_off(int pin);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read a single byte from an MPR121 register
int mpr121_read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to an MPR121 register
int mpr121_write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Function to initialize the MPR121
int mpr121_init(int handle) {
    // Soft reset
    if (mpr121_write_register(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(100); // Wait for reset to complete

    // Configure Electrode Configuration Register (ECR) to enable all electrodes
    if (mpr121_write_register(handle, MPR121_ECR, 0x3F) < 0) return -1;

    // Configure Filter Thresholds
    if (mpr121_write_register(handle, MPR121_FILTERTH_L, 0x10) < 0) return -1; // Low threshold
    if (mpr121_write_register(handle, MPR121_FILTERTH_H, 0x10) < 0) return -1; // High threshold

    // Configure Baseline Thresholds
    if (mpr121_write_register(handle, MPR121_BASELINETH_L, 0x05) < 0) return -1; // Low threshold
    if (mpr121_write_register(handle, MPR121_BASELINETH_H, 0x05) < 0) return -1; // High threshold

    // Configure Debounce
    if (mpr121_write_register(handle, MPR121_MHDR, 0x01) < 0) return -1; // Max Height
    if (mpr121_write_register(handle, MPR121_NHDR, 0x01) < 0) return -1; // Noise Height
    if (mpr121_write_register(handle, MPR121_NCLR, 0x0E) < 0) return -1; // Noise Clear
    if (mpr121_write_register(handle, MPR121_FDLR, 0x00) < 0) return -1; // Fall Distance

    if (mpr121_write_register(handle, MPR121_MHDF, 0x01) < 0) return -1; // Max Height
    if (mpr121_write_register(handle, MPR121_NHDF, 0x01) < 0) return -1; // Noise Height
    if (mpr121_write_register(handle, MPR121_NCLF, 0x0E) < 0) return -1; // Noise Clear
    if (mpr121_write_register(handle, MPR121_FDLF, 0x00) < 0) return -1; // Fall Distance

    if (mpr121_write_register(handle, MPR121_MHDT, 0x01) < 0) return -1; // Max Height
    if (mpr121_write_register(handle, MPR121_NHDT, 0x01) < 0) return -1; // Noise Height
    if (mpr121_write_register(handle, MPR121_NCLT, 0x0E) < 0) return -1; // Noise Clear
    if (mpr121_write_register(handle, MPR121_FDLT, 0x00) < 0) return -1; // Fall Distance

    // Configure AFE and Baseline Filtering
    if (mpr121_write_register(handle, MPR121_CONFIG1, 0x10) < 0) return -1; // Enable electrode 0-11
    if (mpr121_write_register(handle, MPR121_CONFIG2, 0x24) < 0) return -1; // Baseline filtering

    return 0;
}

// Function to detect proximity based on touch status
int proximity_detected(int handle) {
    int touch_status = mpr121_read_register(handle, MPR121_TOUCHSTATUS_L);
    if (touch_status < 0) return 0; // Return 0 on error

    // Check if any electrode is touched
    return (touch_status > 0);
}

// Function to turn the LED on
void led_on(int pin) {
    gpioWrite(pin, 1);
}

// Function to turn the LED off
void led_off(int pin) {
    gpioWrite(pin, 0);
}

// Function to log an event to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (proximity_detected(i2c_handle)) {
            led_on(LED_PIN);
            log_event("Proximity detected!");
            gpioDelay(1000); // LED on for 1 second
            led_off(LED_PIN);
        }
        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

