// Function to trigger the ultrasonic sensor
void trigger_sensor() {
  gpioWrite(TRIGGER_PIN, 1);
  gpioDelay(TRIGGER_PULSE_US);
  gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long measure_pulse_width() {
  long start_time = 0, end_time = 0;
  int timeout_count = 0;

  // Wait for the echo pin to go high (rising edge)
  while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_US) {
    timeout_count++;
    gpioDelay(1); // Check every 1 us
  }

  if (timeout_count >= TIMEOUT_US) {
    fprintf(stderr, "Error: Echo rising edge timeout.\n");
    return -1; // Indicate timeout error
  }

  start_time = gpioTick();

  // Wait for the echo pin to go low (falling edge)
  timeout_count = 0;
  while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT_US) {
    timeout_count++;
    gpioDelay(1); // Check every 1 us
  }

  if (timeout_count >= TIMEOUT_US) {
    fprintf(stderr, "Error: Echo falling edge timeout.\n");
    return -1; // Indicate timeout error
  }

  end_time = gpioTick();

  return end_time - start_time;
}

