#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 1.0      // Minimum measurable distance in cm
#define MAX_DISTANCE 400.0    // Maximum measurable distance in cm
#define MIN_PULSE_WIDTH 58.0  // Minimum pulse width in us (1cm)
#define MAX_PULSE_WIDTH 25000.0 // Maximum pulse width in us (4m)
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in us

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Function to handle echo pin interrupts
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1;
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 0;
    }
}

// Function to calculate distance from pulse width
double calculate_distance(uint32_t pulse_width) {
    double time_taken = (double)(end_tick - start_tick) / 1000000.0; // Time in seconds
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm
    return distance;
}

// Function to log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL); // Disable ISR
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler for ECHO pin
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(1000); // Wait 1 second

        if (end_tick > start_tick) {
            uint32_t pulse_width = end_tick - start_tick;
            double distance = calculate_distance(pulse_width);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Invalid pulse width: %u us\n", end_tick - start_tick);
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL); // Disable ISR
    fclose(log_file);
    gpioTerminate();

    return 0;
}

