#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses (example, adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// GPIO pin for XSHUT
#define XSHUT_PIN 27

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    closelog();
    exit(0);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Set XSHUT pin high to enable sensor
    gpioWrite(XSHUT_PIN, 1);
    gpioDelay(100); // Wait for sensor to power up

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }

    // Verify sensor ID (example)
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        syslog(LOG_ERR, "Failed to read model ID");
        return -1;
    }
    if (model_id != 0xEACC) {
        syslog(LOG_ERR, "Incorrect model ID: 0x%02x", model_id);
        return -1;
    }

    syslog(LOG_INFO, "VL53L1X sensor initialized successfully");
    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    char data[2];
    int status;

    // Start a single measurement
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) != 0) {
        syslog(LOG_ERR, "Failed to start measurement");
        return -1;
    }

    // Wait for measurement to complete (adjust delay as needed)
    gpioDelay(10); // Wait 10ms

    // Read range status
    char range_status;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status, 1) != 1) {
        syslog(LOG_ERR, "Failed to read range status");
        return -1;
    }

    // Read distance data
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance data");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set XSHUT pin as output
    gpioSetMode(XSHUT_PIN, PI_OUTPUT);

    // Open syslog
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        cleanup();
        return 1;
    }

    // Main loop
    int distance;
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            syslog(LOG_INFO, "Distance: %d mm, Status: 0x%02x", distance, range_status);
        } else {
            syslog(LOG_ERR, "Failed to read distance");
        }
        gpioDelay(100); // Wait 100ms
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

