    // Verify sensor ID (example)
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        syslog(LOG_ERR, "Failed to read model ID");
        return -1;
    }
    if (model_id != 0xEACC) {
        syslog(LOG_ERR, "Incorrect model ID: 0x%02x", model_id);
        return -1;
    }

    syslog(LOG_INFO, "VL53L1X sensor initialized successfully");
    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    char data[2];
    int status;

    // Start a single measurement
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) != 0) {
        syslog(LOG_ERR, "Failed to start measurement");
        return -1;
    }

    // Wait for measurement to complete (adjust delay as needed)
    gpioDelay(10); // Wait 10ms

    // Read range status
    char range_status;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status, 1) != 1) {
        syslog(LOG_ERR, "Failed to read range status");
        return -1;
    }

    // Read distance data
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance data");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];

    return 0;
}

