    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set XSHUT pin as output
    gpioSetMode(XSHUT_PIN, PI_OUTPUT);

    // Open syslog
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        cleanup();
        return 1;
    }

    // Main loop
    int distance;
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            syslog(LOG_INFO, "Distance: %d mm, Status: 0x%02x", distance, range_status);
        } else {
            syslog(LOG_ERR, "Failed to read distance");
        }
        gpioDelay(100); // Wait 100ms
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

