    } else if (level == 0) {
        end_tick = tick;

        // Calculate pulse width in microseconds
        pulse_width = end_tick - start_tick;
        if (end_tick < start_tick) {
            pulse_width = (0xFFFFFFFF - start_tick) + end_tick; // Handle wrap-around
        }

        new_pulse = 1; // Set the flag to indicate new pulse width
    }
}

// Function to calculate distance in centimeters
float calculate_distance(uint32_t pulse_width_us) {
    if (pulse_width_us == 0) {
        return -1.0; // Indicate no echo received
    }

    float distance = (float)pulse_width_us * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
    return distance;
}

// Function to apply moving average filter
float moving_average_filter(float new_distance) {
    distance_buffer[buffer_index] = new_distance;
    buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;

    float sum = 0.0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        sum += distance_buffer[i];
    }

    return sum / MOVING_AVG_SIZE;
}

// Function to set servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > SERVO_RANGE) {
        fprintf(stderr, "Error: Invalid servo angle: %d\n", angle);
        return -1;
    }

    // Convert angle to pulse width (linear mapping)
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / SERVO_RANGE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

// Function to log data to CSV file
int log_data(float distance, int servo_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, servo_angle);
        fflush(log_file); // Flush the buffer to ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM range for servo
    gpioSetPWMrange(SERVO_PIN, 20000); // Set PWM range to 20ms (50Hz)

    // Set PWM frequency for servo (optional, but recommended)
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50Hz

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return -1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Set up interrupt callback for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Stop the servo
    set_servo_angle(90); // Set to a safe position
    gpioDelay(500); // Allow time for the servo to move

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    int servo_angle = 90;
    set_servo_angle(servo_angle);

    while (!terminate) {
        trigger_pulse();
        gpioDelay(100); // Wait 100ms

        // Read pulse width and calculate distance
        while (!new_pulse) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }
        new_pulse = 0; // Clear the flag

        float distance = calculate_distance(pulse_width);

        // Validate distance
        if (distance < DISTANCE_MIN || distance > DISTANCE_MAX) {
            distance = -1.0; // Indicate invalid distance
            set_servo_angle(90);
        }

        // Apply moving average filter
        filtered_distance = moving_average_filter(distance);

        // Log data
        log_data(filtered_distance, servo_angle);

        // Adjust servo angle based on distance (example logic)
        if (filtered_distance > 0) {
            // Simple proportional control (adjust as needed)
            if (filtered_distance < 100) {
                servo_angle = 45; // Move closer
            } else if (filtered_distance > 200) {
                servo_angle = 135; // Move farther
            } else {
                servo_angle = 90; // Maintain current position
            }

            if (set_servo_angle(servo_angle) != 0) {
                fprintf(stderr, "Error: Failed to set servo angle\n");
            }
        }

        gpioDelay(100); // Delay between measurements
    }

    cleanup();
    return 0;
}

