int vl53l1x_init();
int vl53l1x_read_distance();
void update_led(int distance);
void signal_handler(int signal);

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02x: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(uint8_t reg, uint8_t *value) {
    int result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02x: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L1X register
int vl53l1x_read_word(uint8_t reg, uint16_t *value) {
    char buf[1];
    buf[0] = reg;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read: %d\n", result);
        return -1;
    }
    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02x: %d\n", reg, result);
        return -1;
    }
    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// VL53L1X initialization function
int vl53l1x_init() {
    // Example initialization sequence (refer to STMicroelectronics documentation)
    // This is a simplified example and may need adjustments based on your specific use case.

    // Check device ID
    uint8_t model_id;
    if (vl53l1x_read_byte(VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02x\n", model_id);
        return -1;
    }

    // Set signal rate check
    if (vl53l1x_write_byte(0x0024, 0x01) != 0) return -1; // Example register and value

    // Configure cross-talk compensation
    if (vl53l1x_write_byte(0x0025, 0x0A) != 0) return -1; // Example register and value

    // Start ranging
    if (vl53l1x_write_byte(0x0080, 0x01) != 0) return -1; // Example register and value

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance() {
    uint16_t distance;

    // Start a new measurement
    if (vl53l1x_write_byte(0x000, 0x01) != 0) return -1; // Example register and value

    // Wait for measurement to complete (adjust timeout as needed)
    gpioDelay(10000); // 10ms

    // Read the distance
    if (vl53l1x_read_word(VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance) != 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    return (int)distance;
}

// Function to update the warning LED based on the distance
void update_led(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

