#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define GPIO_PIN 27
#define PROXIMITY_REG 0x00 // Example register address, adjust as needed
#define INTERRUPT_REG 0x01 // Example interrupt register address, adjust as needed
#define INTERRUPT_ENABLE 0x02 // Example interrupt enable register address, adjust as needed

// Global variables
static int i2c_handle;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int threshold = DEFAULT_THRESHOLD;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int interrupt_flag = 0;

// Function prototypes
int init_i2c(int address);
int init_gpio(int pin);
int init_sensor(int handle);
int read_proximity(int handle);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void log_data(int proximity_value, const char *status);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c(int address) {
    i2c_handle = i2cOpen(I2C_BUS, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return i2c_handle;
}

// Function to initialize GPIO
int init_gpio(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting GPIO pull-up\n");
        return -1;
    }
    return 0;
}

// Function to initialize the sensor
int init_sensor(int handle) {
    // Example initialization sequence (adjust based on Si1102 datasheet)
    if (i2cWriteByteData(handle, INTERRUPT_ENABLE, 0x01) < 0) { // Enable interrupt
        fprintf(stderr, "Error enabling interrupt\n");
        return -1;
    }
    return 0;
}

// Function to read proximity value
int read_proximity(int handle) {
    int proximity_value = i2cReadWordData(handle, PROXIMITY_REG);
    if (proximity_value < 0) {
        fprintf(stderr, "Error reading proximity value\n");
        return -1;
    }
    return proximity_value;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    interrupt_flag = 1;
}

// Function to log data to file
void log_data(int proximity_value, const char *status) {
    pthread_mutex_lock(&log_mutex);
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %s\n", timestamp, proximity_value, status);
    fflush(log_file);
    pthread_mutex_unlock(&log_mutex);
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&log_mutex);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0); // Allow hex or decimal
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c(i2c_address) < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
