#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 200.0    // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define TIMEOUT_US 200000      // 200 ms in microseconds

// Global variables
static volatile int running = 1;
static volatile int echo_start = 0;
static volatile int echo_end = 0;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
long pulse_width();
double distance();
double frequency(double distance);
void set_pwm_frequency(double frequency);
void echo_callback(int gpio, int level, uint32_t tick);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();      // Terminate pigpio
    exit(0);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long pulse_width() {
    echo_start = 0;
    echo_end = 0;

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1; // Timeout
    }

    echo_start = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1; // Timeout
    }

    echo_end = gpioTick();

    return echo_end - echo_start;
}

// Function to calculate the distance from the pulse width
double distance() {
    long pulse = pulse_width();
    if (pulse < 0) {
        return -1.0; // Indicate error
    }
    return (double)pulse * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to map distance to frequency on a logarithmic scale
double frequency(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0; // Indicate error
    }

    // Logarithmic mapping
    double log_distance = log10(distance / MIN_DISTANCE);
    double log_max_distance = log10(MAX_DISTANCE / MIN_DISTANCE);
    double frequency_ratio = log_distance / log_max_distance;
    double frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * frequency_ratio;

    return frequency;
}

// Function to set the PWM frequency
void set_pwm_frequency(double frequency) {
    if (frequency > 0) {
        gpioSetPWMfrequency(PWM_PIN, (int)frequency);
    } else {
        fprintf(stderr, "Invalid frequency: %.2f Hz\n", frequency);
    }
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start = tick;
    } else if (level == 0) {
        echo_end = tick;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range (optional, defaults to 1000)
    gpioSetPWMrange(PWM_PIN, 1000);

    // Set PWM duty cycle (50%)
    gpioPWM(PWM_PIN, 500); // 50% of 1000

    // Set PWM frequency (initial value)
    set_pwm_frequency(440.0); // A4

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (running) {
        trigger_pulse();
        double dist = distance();

        if (dist > 0) {
            double freq = frequency(dist);
            if (freq > 0) {
                set_pwm_frequency(freq);
            }
        } else {
            // Error occurred, preserve previous frequency
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Clean up (should not reach here if signal handler works)
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();      // Terminate pigpio

    return 0;
}

