#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 5.0      // cm
#define MAX_DISTANCE 50.0     // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define TIMEOUT_US 100000      // 100 ms
#define TRIGGER_PULSE_US 10    // 10 us trigger pulse

// Global variables
static volatile int running = 1;
static volatile unsigned int start_tick = 0;
static volatile unsigned int end_tick = 0;
static volatile int echo_received = 0;

// Function prototypes
void signal_handler(int signal);
void trigger_sensor();
void echo_callback(int gpio, int level, unsigned int tick);
float calculate_distance(unsigned int pulse_width);
float map_distance_to_frequency(float distance);
void set_buzzer_frequency(float frequency);
void log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();         // Terminate pigpio
    printf("\nProgram terminated gracefully.\n");
    exit(0);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            start_tick = tick;
            echo_received = 1; // Indicate echo start
        } else if (level == 0 && echo_received == 1) {
            end_tick = tick;
            echo_received = 0; // Reset echo flag
        }
    }
}

// Function to calculate distance from pulse width
float calculate_distance(unsigned int pulse_width) {
    float distance = (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
    return distance;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    float frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }
    return frequency;
}

// Function to set buzzer frequency using pigpio
void set_buzzer_frequency(float frequency) {
    if (frequency > 0) {
        gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
        gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
    } else {
        gpioPWM(BUZZER_PIN, 0); // Stop PWM
    }
}

// Function to log errors
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set PWM range for buzzer
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Set PWM frequency (initial value)
    gpioSetPWMfrequency(BUZZER_PIN, 0); // Start with 0 frequency

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    float last_valid_distance = 0.0; // Store the last valid distance
    float last_valid_frequency = 0.0; // Store the last valid frequency

    // Main loop
    while (running) {
        trigger_sensor();
        gpioDelay(10); // Wait 10 ms

        unsigned int pulse_width = 0;
        if (echo_received) {
            pulse_width = end_tick - start_tick;
        } else {
            pulse_width = TIMEOUT_US; // Timeout
        }

        if (pulse_width > TIMEOUT_US) {
            log_error("Timeout waiting for echo.");
            // Use the last valid distance and frequency
            float distance = last_valid_distance;
            float frequency = last_valid_frequency;
            if (distance == 0.0 && frequency == 0.0) {
                // If no valid readings yet, use a default value
                distance = 25.0; // Default distance
                frequency = 1100.0; // Default frequency
            }
            set_buzzer_frequency(frequency);
            printf("Timeout, using last valid: Distance=%.2f cm, Frequency=%.2f Hz\n", distance, frequency);
        } else {
            float distance = calculate_distance(pulse_width);
            float frequency = map_distance_to_frequency(distance);
            set_buzzer_frequency(frequency);
            last_valid_distance = distance;
            last_valid_frequency = frequency;
            printf("Distance=%.2f cm, Frequency=%.2f Hz\n", distance, frequency);
        }
    }

    // Cleanup (should not reach here if signal handler works)
    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();

    return 0;
}

