    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set PWM range for buzzer
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Set PWM frequency (initial value)
    gpioSetPWMfrequency(BUZZER_PIN, 0); // Start with 0 frequency

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    float last_valid_distance = 0.0; // Store the last valid distance
    float last_valid_frequency = 0.0; // Store the last valid frequency

    // Main loop
    while (running) {
        trigger_sensor();
        gpioDelay(10); // Wait 10 ms

        unsigned int pulse_width = 0;
        if (echo_received) {
            pulse_width = end_tick - start_tick;
        } else {
            pulse_width = TIMEOUT_US; // Timeout
        }

        if (pulse_width > TIMEOUT_US) {
            log_error("Timeout waiting for echo.");
            // Use the last valid distance and frequency
            float distance = last_valid_distance;
            float frequency = last_valid_frequency;
            if (distance == 0.0 && frequency == 0.0) {
                // If no valid readings yet, use a default value
                distance = 25.0; // Default distance
                frequency = 1100.0; // Default frequency
            }
            set_buzzer_frequency(frequency);
            printf("Timeout, using last valid: Distance=%.2f cm, Frequency=%.2f Hz\n", distance, frequency);
        } else {
            float distance = calculate_distance(pulse_width);
            float frequency = map_distance_to_frequency(distance);
            set_buzzer_frequency(frequency);
            last_valid_distance = distance;
            last_valid_frequency = frequency;
            printf("Distance=%.2f cm, Frequency=%.2f Hz\n", distance, frequency);
        }
    }

    // Cleanup (should not reach here if signal handler works)
    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();

    return 0;
}

