#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); // 1 ms

    while (!terminate) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10 us
        gpioWrite(TRIGGER_PIN, 0);

        unsigned int start_tick = 0, end_tick = 0;

        // Wait for echo to go high with timeout
        int timeout = 50000; // 50 ms * 1000 us/ms
        while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
            timeout--;
            gpioDelay(1); // Check every 1 us
        }

        if (timeout <= 0) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            start_tick = -1;
        } else {
            start_tick = gpioTick();
        }

        // Wait for echo to go low with timeout
        timeout = 50000;
        while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
            timeout--;
            gpioDelay(1);
        }

        if (timeout <= 0) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            end_tick = -1;
        } else {
            end_tick = gpioTick();
        }

        if (start_tick == -1 || end_tick == -1) {
            printf("Invalid reading\n");
        } else {
            unsigned int pulse_duration = end_tick - start_tick;

            if (pulse_duration > 1000000) {
                fprintf(stderr, "Invalid pulse duration: %u\n", pulse_duration);
                printf("Invalid reading\n");
            } else {
                float distance = pulse_duration * 0.0343 / 2.0;

                if (distance < 2.0 || distance > 400.0) {
                    printf("Invalid reading\n");
                } else {
                    printf("Distance: %.2f cm", distance);
                    if (distance < 10.0) {
                        printf(" Too close!");
                    }
                    printf("\n");
                }
            }
        }

        gpioDelay(500000); // 500 ms
    }

    gpioTerminate();
    printf("Program terminated gracefully\n");
    return 0;
}

