#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)
#define LOG_FILE "distance_log.csv"
#define MAX_DISTANCE 5000
#define MIN_DISTANCE 200

// ICU-20201 Register Addresses (Example - Refer to datasheet for actual values)
#define ICU_REG_WHO_AM_I 0x00
#define ICU_REG_DISTANCE_HIGH 0x01
#define ICU_REG_DISTANCE_LOW 0x02
#define ICU_REG_CONFIG 0x03

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
int log_data(time_t timestamp, int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize the ICU-20201 sensor
int initialize_sensor() {
    // Example initialization sequence (Refer to datasheet for actual sequence)
    char init_data[] = {ICU_REG_CONFIG, 0x01}; // Example config value
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = init_data[0];
    tx_buf[1] = init_data[1];

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI initialization failed.\n");
        return -1;
    }

    // Verify sensor ID (Example)
    tx_buf[0] = ICU_REG_WHO_AM_I;
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed during initialization.\n");
        return -1;
    }

    // Check WHO_AM_I register (Example)
    if (rx_buf[1] != 0x42) { // Example expected value
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", rx_buf[1]);
        return -1;
    }

    printf("ICU-20201 sensor initialized successfully.\n");
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char tx_buf[2];
    char rx_buf[2];

    // Read high byte
    tx_buf[0] = ICU_REG_DISTANCE_HIGH;
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed (high byte).\n");
        return -1;
    }
    int high_byte = rx_buf[1];

    // Read low byte
    tx_buf[0] = ICU_REG_DISTANCE_LOW;
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed (low byte).\n");
        return -1;
    }
    int low_byte = rx_buf[1];

    *distance = (high_byte << 8) | low_byte;

    // Validate distance
    if (*distance < MIN_DISTANCE || *distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: Distance out of range: %d mm\n", *distance);
        return -1; // Indicate invalid distance
    }

    return 0;
}

// Log data to CSV file
int log_data(time_t timestamp, int distance) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp_str, distance);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int distance;
    time_t current_time;
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            current_time = time(NULL);
            if (log_data(current_time, distance) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

