#include <pigpio.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 Register Addresses
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_RESET 0x07
#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_PS1_DATA0 0x18

// Reset command
#define SI1120_RESET_CMD 0x01

// Part ID expected value
#define SI1120_PART_ID 0x50

// I2C bus number
#define I2C_BUS 1

// Log file name
#define LOG_FILE "si1120_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int reset_sensor();
int verify_part_id();
int read_als();
int read_proximity();
int combine_data(int als, int proximity);
char* get_timestamp();
int log_data(int als, int proximity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int als;
    int proximity;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to reset the sensor
int reset_sensor() {
    int retries = 3;
    while (retries > 0) {
        int result = i2cWriteByteData(i2c_handle, SI1120_REG_RESET, SI1120_RESET_CMD);
        if (result == 0) {
            gpioDelay(10); // Wait for reset to complete
            return 0;
        } else {
            fprintf(stderr, "Error resetting sensor: %d, retries remaining: %d\n", result, retries);
            retries--;
            gpioDelay(10);
        }
    }
    return -1;
}

// Function to verify the Part ID
int verify_part_id() {
    int retries = 3;
    while (retries > 0) {
        int part_id = i2cReadByteData(i2c_handle, SI1120_REG_PART_ID);
        if (part_id >= 0) {
            if (part_id == SI1120_PART_ID) {
                return 0;
            } else {
                fprintf(stderr, "Error: Incorrect Part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1120_PART_ID);
                return -1;
            }
        } else {
            fprintf(stderr, "Error reading Part ID: %d, retries remaining: %d\n", part_id, retries);
            retries--;
            gpioDelay(10);
        }
    }
    return -1;
}

// Function to read ALS data
int read_als() {
    int retries = 3;
    while (retries > 0) {
        int als_low = i2cReadByteData(i2c_handle, SI1120_REG_ALS_VIS_DATA0);
        int als_high = i2cReadByteData(i2c_handle, SI1120_REG_ALS_VIS_DATA0 + 1);

        if (als_low >= 0 && als_high >= 0) {
            return (als_high << 8) | als_low;
        } else {
            fprintf(stderr, "Error reading ALS data: %d, retries remaining: %d\n", als_low, retries);
            retries--;
            gpioDelay(10);
        }
    }
    return -1;
}

// Function to read proximity data
int read_proximity() {
    int retries = 3;
    while (retries > 0) {
        int prox_low = i2cReadByteData(i2c_handle, SI1120_REG_PS1_DATA0);
        int prox_high = i2cReadByteData(i2c_handle, SI1120_REG_PS1_DATA0 + 1);

        if (prox_low >= 0 && prox_high >= 0) {
            return (prox_high << 8) | prox_low;
        } else {
            fprintf(stderr, "Error reading proximity data: %d, retries remaining: %d\n", prox_low, retries);
            retries--;
            gpioDelay(10);
        }
    }
    return -1;
}

// Function to combine ALS and proximity data into 16-bit little-endian values
int combine_data(int als, int proximity) {
    return (als << 16) | proximity;
}

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log data to a file
int log_data(int als, int proximity) {
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d\n", timestamp, als, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Reset the sensor
    if (reset_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify the Part ID
    if (verify_part_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ALS and proximity data
        int als = read_als();
        int proximity = read_proximity();

        // Combine data
        int combined_data = combine_data(als, proximity);

        // Log data
        if (log_data(als, proximity) != 0) {
