#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define the I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Define the Si1182-A-GM I2C address
#define SI1182_I2C_ADDR 0x60

// Define register addresses (replace with actual values from datasheet)
#define SI1182_PART_ID_REG 0x00
#define SI1182_MEAS_RATE_REG 0x01
#define SI1182_ALS_DATA_REG 0x02
#define SI1182_PS_DATA_REG 0x04

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_file = NULL; // Log file pointer
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Function prototypes
int i2c_read_reg(int fd, unsigned char reg);
int i2c_write_reg(int fd, unsigned char reg, unsigned char value);
int read_sensor_data(int fd, float *lux, int *proximity);
void log_data(FILE *fp, float lux, int proximity);
void signal_handler(int signum);
char* get_timestamp();

// I2C read function
int i2c_read_reg(int fd, unsigned char reg) {
    int result;
    unsigned char buf[1];

    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    result = buf[0];
    return result;
}

// I2C write function
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];

    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, float *lux, int *proximity) {
    int als_data, ps_data;

    als_data = i2c_read_reg(fd, SI1182_ALS_DATA_REG);
    if (als_data < 0) {
        fprintf(stderr, "Error reading ALS data\n");
        return -1;
    }

    ps_data = i2c_read_reg(fd, SI1182_PS_DATA_REG);
    if (ps_data < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }

    // Convert raw data to lux and proximity (replace with actual conversion formulas)
    *lux = (float)als_data * 0.1; // Example conversion
    *proximity = ps_data; // Proximity is raw 16-bit value

    return 0;
}

// Function to log data to a file
void log_data(FILE *fp, float lux, int proximity) {
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return;
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, lux, proximity);
    fflush(fp); // Ensure data is written to disk immediately
    free(timestamp);

    printf("%s,%.2f,%d\n", timestamp, lux, proximity);
    free(timestamp);
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        program_running = 0;
    }
}

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify the sensor by reading the part ID register
    int part_id = i2c_read_reg(i2c_fd, SI1182_PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read part ID. Sensor might be absent.\n");
        close(i2c_fd);
        return 1;
    }

    printf("Si1182 Part ID: 0x%02X\n", part_id);

    // Configure the measurement rate register (replace with actual value from datasheet)
    if (i2c_write_reg(i2c_fd, SI1182_MEAS_RATE_REG, 0x0A) < 0) {
        fprintf(stderr, "Failed to write measurement rate register\n");
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    float lux;
    int proximity;
    while (program_running) {
        if (read_sensor_data(i2c_fd, &lux, &proximity) == 0) {
            log_data(log_file, lux, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(100000); // 100 ms delay
    }

    // Close the I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

