#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define DISTANCE_THRESHOLD 20.0 // Distance threshold in cm
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick, void *user_data);
double calculate_distance(unsigned int pulse_width);
void set_buzzer_state(double distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Interrupt handler for echo pin
void echo_callback(int gpio, int level, unsigned int tick, void *user_data) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 0; // Reset flag
    }
}

// Function to calculate distance from pulse width
double calculate_distance(unsigned int pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert microseconds to seconds
}

// Function to set buzzer state based on distance
void set_buzzer_state(double distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for echo pin\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds

        // Calculate distance
        unsigned int pulse_width = end_tick - start_tick;
        double distance = calculate_distance(pulse_width);

        // Set buzzer state
        set_buzzer_state(distance);

