void echo_callback(int gpio, int level, unsigned int tick, void *user_data);
double calculate_distance(unsigned int pulse_width);
void set_buzzer_state(double distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Interrupt handler for echo pin
void echo_callback(int gpio, int level, unsigned int tick, void *user_data) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 0; // Reset flag
    }
}

// Function to calculate distance from pulse width
double calculate_distance(unsigned int pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert microseconds to seconds
}

