#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to measure distance using HC-SR04
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0;
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0;
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
    return distance;
}

// Function to set servo angle
void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    // Map angle (0-180) to pulse width (500-2500 us)
    int pulse_width = 500 + (int)((float)angle / 180.0 * 2000.0);

    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking Assist System running. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Measure distance
        float distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Set servo angle based on distance
        int angle;
        if (distance > 200) {
            angle = 0;
        } else if (distance < 20) {
            angle = 180;
        } else {
            // Linear mapping from distance to angle
            angle = 90 - (int)((distance - 110) / (200 - 110) * 90); // Inverted mapping
            if (angle < 0) angle = 0;
            if (angle > 180) angle = 180;
        }

        set_servo_angle(angle);

        // Print distance and angle
        printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);

        // Delay for 100ms
        gpioDelay(100);
    }

    // Stop servo and terminate pigpio library
    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate();

    return 0;
}

