#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// GPIO pin for servo control
#define SERVO_PIN 18

// Distance thresholds (mm)
#define OPEN_THRESHOLD 250
#define CLOSE_THRESHOLD 200

// PWM parameters
#define PWM_FREQUENCY 50 // Hz
#define PWM_RANGE 20000  // 20ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void set_servo_pulse_width(int pulse_width);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the VL53L1X sensor
int vl53l1x_init() {
    int model_id, revision_id;

    // Read model ID
    if (i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID) < 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%X\n", model_id);
        return -1;
    }

    // Read revision ID
    revision_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_REVISION_ID);
    printf("Model ID: 0x%X, Revision ID: 0x%X\n", model_id, revision_id);

    // Set timing budget (example: 33ms)
    // This is a simplified example.  Refer to the VL53L1X datasheet for proper initialization.
    char timing_budget_config[] = {0x00, 0x01}; // Example configuration
    if (i2cWriteI2CBlockData(i2c_handle, 0x002D, timing_budget_config, 2) < 0) {
        fprintf(stderr, "Error setting timing budget\n");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int vl53l1x_read_distance(int *distance) {
    char range_status;
    char data[2];

    // Check range status
    range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance data
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) < 0) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];

    return 0;
}

// Set servo pulse width
void set_servo_pulse_width(int pulse_width) {
    gpioPWM(SERVO_PIN, pulse_width);
}

// Log event to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

int main() {
    int distance;
    int pulse_width = 1500; // Initial pulse width (center)
    int last_pulse_width = 1500;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for servo pin
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO_PIN, PWM_RANGE);

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        if (vl53l1x_read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);

            // Determine pulse width based on distance
            if (distance > OPEN_THRESHOLD) {
                pulse_width = 1000;
            } else if (distance < CLOSE_THRESHOLD) {
                pulse_width = 2000;
            } else {
                // Smooth transition
                if (distance > last_pulse_width) {
                    pulse_width = last_pulse_width + 100;
                } else {
                    pulse_width = last_pulse_width - 100;
                }
            }

            // Update last pulse width
            last_pulse_width = pulse_width;

            // Set servo pulse width
            set_servo_pulse_width(pulse_width);

            // Log event if pulse width changes
            if (pulse_width != 1500) {
                if (pulse_width == 1000) {
                    log_event("Gate opened");
                } else if (pulse_width == 2000) {
                    log_event("Gate closed");
                }
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        // Delay
        gpioDelay(50000); // 50ms
    }

    // Cleanup
    set_servo_pulse_width(0); // Stop PWM
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

