#define SERVO_RANGE 2000       // Difference between min and max pulse width
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define MIN_ANGLE 0.0          // degrees
#define MAX_ANGLE 180.0        // degrees
#define ANGLE_RANGE 180.0      // Difference between min and max angle
#define PAUSE_MS 100           // Pause between measurements

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
long long get_pulse_width();
double calculate_distance(long long pulse_width);
double map_distance_to_angle(double distance);
int set_servo_angle(double angle);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    long long start_tick;
    long long end_tick;
    int valid;
} sensor_data_t;

sensor_data_t sensor_data = {0, 0, 0};

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); // 1 ms

    return 0; // Indicate success
}

// Function to send a 10 µs trigger pulse to the HC-SR04 sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long long get_pulse_width() {
    long long start_tick, end_tick;
    int timeout_start = gpioTick();

    // Wait for rising edge with timeout
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            return -1; // Timeout
        }
    }
    start_tick = gpioTick();

    // Wait for falling edge with timeout
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            return -1; // Timeout
        }
    }
    end_tick = gpioTick();

    sensor_data.start_tick = start_tick;
    sensor_data.end_tick = end_tick;
    sensor_data.valid = 1;

    return end_tick - start_tick;
}

// Function to calculate the distance in centimeters from the pulse width
double calculate_distance(long long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate timeout
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map the distance to a servo angle
double map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) {
        return 0.0;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    }

    double angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * ANGLE_RANGE;
    return angle;
}

// Function to set the servo angle using pigpio
int set_servo_angle(double angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (0-180)\n");
        return 1; // Indicate failure
    }

    // Map angle to pulse width
    int pulse_width = SERVO_MIN_PULSE + (int)((angle / MAX_ANGLE) * SERVO_RANGE);

    gpioServo(SERVO_PIN, pulse_width);
    return 0; // Indicate success
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping servo and exiting...\n", signal);
    set_servo_angle(0.0); // Stop the servo
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

