    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Ultrasonic sensor and servo control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the pulse width
        long long pulse_width = get_pulse_width();

        // Calculate the distance
        double distance = calculate_distance(pulse_width);

        // Map the distance to an angle
        double angle = map_distance_to_angle(distance);

        // Set the servo angle
        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Error setting servo angle\n");
        }

        // Print the distance and angle
        printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);

        // Pause for 100 ms
        gpioDelay(PAUSE_MS * 1000); // Convert ms to us
    }

    return 0;
}

