#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define the I2C bus and sensor address
#define I2C_BUS 1
#define SI7005_ADDR 0x40

// Define the configuration register value
#define CONFIG_REG 0x00

// Define the humidity and temperature register addresses
#define HUMIDITY_REG 0x00
#define TEMPERATURE_REG 0x01

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int write_register(int handle, int reg, int value);
int read_register(int handle, int reg, int *value);
int read_sensor_data(int handle, float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Writes a value to a specific register
int write_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Failed to write to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Reads a value from a specific register
int read_register(int handle, int reg, int *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Failed to read from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = result;
    return 0;
}

// Reads temperature and humidity data from the sensor
int read_sensor_data(int handle, float *temperature, float *humidity) {
    int raw_temperature, raw_humidity;

    // Write the configuration register
    if (write_register(handle, CONFIG_REG, 0x00) < 0) {
        return -1;
    }
    gpioDelay(10); // Wait 10 ms

    // Read the humidity register
    if (read_register(handle, HUMIDITY_REG, &raw_humidity) < 0) {
        return -1;
    }
    gpioDelay(10); // Wait 10 ms

    // Read the temperature register
    if (read_register(handle, TEMPERATURE_REG, &raw_temperature) < 0) {
        return -1;
    }

    // Convert raw data to temperature and humidity
    *temperature = (175.72 * raw_temperature / 65536.0) - 46.85;
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

// Logs the temperature and humidity data to the console
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s - Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    if (initialize_i2c() < 0) {
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &temperature, &humidity) == 0) {
            // Log the data
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Attempting to re-initialize I2C.\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            if (initialize_i2c() < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
        }

        // Wait 2 seconds
        gpioDelay(2000);
    }

    // Close the I2C handle and terminate the pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

