#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_WHO_AM_I 0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from two I2C registers (big-endian)
int16_t read_word(int handle, uint8_t reg) {
    int high = read_register(handle, reg);
    int low = read_register(handle, reg + 1);

    if (high < 0 || low < 0) {
        return -1; // Indicate error
    }

    return (int16_t)((high << 8) | low);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = read_register(i2c_handle, MPU6050_WHO_AM_I);
    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0x68\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("MPU6050 sensor found (WHO_AM_I = 0x%02X)\n", who_am_i);

    // Wake up the sensor (clear sleep bit in PWR_MGMT_1 register)
    if (write_register(i2c_handle, MPU6050_PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error waking up sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read accelerometer and gyroscope data
        int16_t accel_x = read_word(i2c_handle, MPU6050_ACCEL_XOUT_H);
        int16_t accel_y = read_word(i2c_handle, MPU6050_ACCEL_XOUT_H + 2);
        int16_t accel_z = read_word(i2c_handle, MPU6050_ACCEL_XOUT_H + 4);
        int16_t gyro_x = read_word(i2c_handle, MPU6050_GYRO_XOUT_H);
        int16_t gyro_y = read_word(i2c_handle, MPU6050_GYRO_XOUT_H + 2);
        int16_t gyro_z = read_word(i2c_handle, MPU6050_GYRO_XOUT_H + 4);

        if (accel_x == -1 || accel_y == -1 || accel_z == -1 || gyro_x == -1 || gyro_y == -1 || gyro_z == -1) {
            fprintf(stderr, "Error reading sensor data\n");
        } else {
            // Print the data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

