int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int sts30_address;
    char log_file[64];
    char error_log_file[64];
} Config;

Config config = {I2C_BUS, STS30_ADDR, LOG_FILE, ERROR_LOG_FILE};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_temperature(&temperature) == 0) {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Log temperature
            if (log_temperature(temperature) != 0) {
                log_error("Failed to log temperature.");
            }
        } else {
            log_error("Failed to read temperature.");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.sts30_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        log_error("Failed to open I2C device.");
        return 1;
    }
    return 0;
}

// Read temperature from STS30 sensor
int read_temperature(float *temperature) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buf[6];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        log_error("Failed to write to I2C device.");
        return 1;
    }

    // Wait for measurement (at least 20ms)
    gpioDelay(20000); // 20ms

    // Read temperature data
    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        log_error("Failed to read from I2C device.");
        return 1;
    }

    // Convert data to temperature (Celsius)
    int temp_raw = (buf[0] << 8) | buf[1];
    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);

    return 0;
}

// Log temperature to file
int log_temperature(float temperature) {
    FILE *fp = fopen(config.log_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        log_error("Failed to open log file.");
        return 1;
    }

    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    time(&current_time);
    time_info = localtime(&current_time);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(fp, "%s, %.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

// Log error to file
int log_error(const char *message) {
    FILE *fp = fopen(config.error_log_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        return 1;
    }

    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    time(&current_time);
    time_info = localtime(&current_time);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(fp, "%s, %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

