// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(int16_t *pressure, int16_t *temperature, int16_t *pressure_scale, int16_t *temperature_scale);
int validate_crc(uint8_t data[], int len);
float convert_pressure(int16_t raw_pressure, int16_t pressure_scale);
float convert_temperature(int16_t raw_temperature, int16_t temperature_scale);
char* get_iso8601_timestamp();
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to initialize the sensor
int init_sensor() {
    char cmd[2] = {MEASURE_CMD_1, MEASURE_CMD_2};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for sensor to be ready
    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *pressure, int16_t *temperature, int16_t *pressure_scale, int16_t *temperature_scale) {
    char buffer[9];
    int result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    // Validate CRCs
    if (validate_crc(buffer, 3) != 0 || validate_crc(buffer + 3, 3) != 0 || validate_crc(buffer + 6, 3) != 0) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    *pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    *temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    *pressure_scale = (int16_t)((buffer[6] << 8) | buffer[7]);
    *temperature_scale = (int16_t)((buffer[8] << 8) | buffer[9]);

    return 0;
}

// Function to validate CRC-8 checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc_calculated = crc8(data, len - 1);
    return (crc_calculated == data[len - 1]);
}

