    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return -1;
    }

    char *timestamp = get_iso8601_timestamp();
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    free(timestamp); // Free the allocated memory
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if CSV file exists and create header if needed
    FILE *fp = fopen(CSV_FILE, "r");
    if (fp == NULL) {
        fp = fopen(CSV_FILE, "w");
        if (fp == NULL) {
            fprintf(stderr, "Failed to create CSV file\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
        fprintf(fp, "timestamp,pressure_Pa,temperature_C\n");
        fclose(fp);
    } else {
        fclose(fp);
    }

    int16_t raw_pressure, raw_temperature, pressure_scale, temperature_scale;
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_pressure, &raw_temperature, &pressure_scale, &temperature_scale) == 0) {
            // Convert raw data to physical units
            sensor_data.pressure = convert_pressure(raw_pressure, pressure_scale);
            sensor_data.temperature = convert_temperature(raw_temperature, temperature_scale);

            // Log data
            if (log_data(sensor_data.pressure, sensor_data.temperature) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

