#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define LOG_FILE "sht40_log.txt"
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, int command);
int read_data(int handle, char *buffer, int count);
int validate_crc(const char *data, int len);
sensor_data_t process_data(const char *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to SHT40
int send_command(int handle, int command) {
    int result = i2cWriteByteData(handle, 0, command);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from SHT40
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadI2CBlockData(handle, 0, buffer, count);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC checksum
int validate_crc(const char *data, int len) {
    unsigned char crc = crc8((unsigned char *)data, len - 1);
    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }
    return 0;
}

// Process raw data to get temperature and humidity
sensor_data_t process_data(const char *data) {
    sensor_data_t result;
    // Convert temperature
    int temperature_raw = (data[0] << 8) | data[1];
    result.temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;

    // Convert humidity
    int humidity_raw = (data[3] << 8) | data[4];
    result.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return result;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    char buffer[6];
    sensor_data_t sensor_data;
    int retry;

    // Main loop
    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            // Send measurement command
            if (send_command(i2c_handle, MEASURE_CMD) == 0) {
                // Wait for measurement (at least 10 ms)
                gpioDelay(10000); // 10 ms

                // Read data
                if (read_data(i2c_handle, buffer, 6) == 0) {
                    // Validate CRC
                    if (validate_crc(buffer, 6) == 0) {
                        // Process data
                        sensor_data = process_data(buffer);

                        // Log data
                        log_data(sensor_data);

                        break; // Exit retry loop on success
                    } else {
                        fprintf(stderr, "CRC validation failed, retrying...\n");
                    }
                } else {
                    fprintf(stderr, "Data read failed, retrying...\n");
                }
            } else {
                fprintf(stderr, "Command send failed, retrying...\n");
            }
            retry++;
            gpioDelay(100000); // Wait 100ms before retrying
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

