#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define TEMP_CMD 0xE3
#define HUM_CMD 0xE5
#define SAMPLE_INTERVAL 5 // seconds
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int command, float *temperature, float *humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int command, float *temperature, float *humidity) {
    char buf[2];
    int result;
    int retries = 0;

    // Write the measurement command
    result = i2cWriteByte(i2c_handle, command);
    if (result != 0) {
        fprintf(stderr, "Error writing command to sensor: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete (polling)
    gpioDelay(20); // Wait 20ms

    // Read the two bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading data from sensor: %s\n", strerror(errno));
        return -1;
    }

    // Convert the data to temperature and humidity
    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    uint16_t raw_humidity = (buf[0] << 8) | buf[1];

    *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

// Function to log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to file immediately

    printf("%s, %.2f, %.2f\n", timestamp, temperature, humidity);

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(TEMP_CMD, &temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Wait for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

