#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define the I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Define the SDP800-500Pa sensor I2C address
#define SDP800_ADDR 0x25

// Define the continuous measurement trigger command
#define TRIGGER_CMD 0x362F

// Define the data file name
#define DATA_FILE "airflow_data.txt"

// Define the logging interval in milliseconds
#define LOG_INTERVAL_MS 100

// Define the CRC8 polynomial
#define CRC8_POLY 0x31

// Global variables
int i2c_fd = -1;
FILE *data_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int i2c_init(const char *device, int address);
int i2c_write(int fd, int address, const unsigned char *data, int len);
int i2c_read(int fd, int address, unsigned char *data, int len);
unsigned char crc8(const unsigned char *data, int len);
int validate_crc(const unsigned char *data, int len);
sensor_data_t read_sensor_data(int fd);
void log_data(FILE *fp, sensor_data_t data);
void signal_handler(int sig);
void cleanup();

// CRC8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const unsigned char *data, int len) {
    unsigned char crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// I2C initialization function
int i2c_init(const char *device, int address) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write(int fd, int address, const unsigned char *data, int len) {
    if (write(fd, data, len) != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, int address, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Read sensor data function
sensor_data_t read_sensor_data(int fd) {
    sensor_data_t data = {0.0, 0.0};
    unsigned char raw_data[9];
    int retries = 3;

    while (retries > 0) {
        // Trigger continuous measurement
        unsigned char trigger_cmd[2] = {(TRIGGER_CMD >> 8) & 0xFF, TRIGGER_CMD & 0xFF};
        if (i2c_write(fd, SDP800_ADDR, trigger_cmd, 2) == 0) {
            usleep(45000); // Wait 45 ms

            // Read sensor data
            if (i2c_read(fd, SDP800_ADDR, raw_data, 9) == 0) {
                // Validate CRCs
                if (validate_crc(raw_data, 3) && validate_crc(raw_data + 3, 3) && validate_crc(raw_data + 6, 3)) {
                    // Convert raw data to pressure and temperature
                    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
                    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];
                    int16_t raw_scale_factor = (raw_data[6] << 8) | raw_data[7];

                    data.pressure = (float)raw_pressure / (float)raw_scale_factor;
                    data.temperature = (float)raw_temperature / 200.0f; // Temperature in degrees Celsius
                    return data;
                } else {
                    fprintf(stderr, "CRC validation failed. Retrying...\n");
                }
            } else {
                fprintf(stderr, "I2C read failed. Retrying...\n");
            }
        } else {
            fprintf(stderr, "I2C write failed. Retrying...\n");
        }
        retries--;
        usleep(10000); // Wait 10 ms before retrying
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return data; // Return default values if read fails
}

// Log data function
void log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE, SDP800_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open data file
    data_file = fopen(DATA_FILE, "a");
    if (data_file == NULL) {
        perror("Error opening data file");
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data = read_sensor_data(i2c_fd);
        log_data(data_file, sensor_data);
        usleep(LOG_INTERVAL_MS * 1000); // Sleep for LOG_INTERVAL_MS milliseconds
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

