#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define SAMPLE_INTERVAL 5 // seconds
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

// Global variables
int i2c_handle;
FILE *log_file = NULL;
FILE *error_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(int handle, unsigned short command);
int read_data(int handle, char *buffer, int count);
unsigned char calculate_crc(const char *data, int len);
int validate_crc(const char *data, int len, unsigned char crc);
int log_temperature(double temperature);
int log_error(const char *message);
void signal_handler(int signal);

// Structure for grouping sensor data
typedef struct {
    double temperature;
    time_t timestamp;
} SensorData;

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, unsigned short command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        log_error("Failed to write command to sensor");
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        log_error("Failed to read data from sensor");
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8 checksum
unsigned char calculate_crc(const char *data, int len) {
    unsigned char crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC checksum
int validate_crc(const char *data, int len, unsigned char crc) {
    unsigned char calculated_crc = calculate_crc(data, len);
    if (calculated_crc != crc) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "CRC validation failed. Expected: 0x%02X, Calculated: 0x%02X", crc, calculated_crc);
        log_error(error_message);
        return -1;
    }
    return 0;
}

// Function to log temperature to file
int log_temperature(double temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen("enclosure_temp_log.txt", "a");
        if (log_file == NULL) {
            log_error("Failed to open log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to log errors to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (error_file == NULL) {
        error_file = fopen("error_log.txt", "a");
        if (error_file == NULL) {
            perror("Failed to open error log file"); // Use perror for system errors
            return -1;
        }
    }

    fprintf(error_file, "%s, %s\n", timestamp, message);
    fflush(error_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        char data[3];
        unsigned char crc;

        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            continue; // Retry on error
        }

        // Wait for conversion (at least 15ms)
        gpioDelay(15000); // 15ms

        // Read data
        if (read_data(i2c_handle, data, 3) != 0) {
            continue; // Retry on error
        }

        // Validate CRC
        if (validate_crc(data, 2, data[2]) != 0) {
            continue; // Retry on error
        }

        // Convert data to temperature
        int temperature_raw = (data[0] << 8) | data[1];
        double temperature = -45.0 + (175.0 * temperature_raw) / 65535.0;

        // Log temperature
        if (log_temperature(temperature) != 0) {
            log_error("Failed to log temperature");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000000); // Convert seconds to microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }

    return 0;
}

