#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define DATA_FILE "airflow_data.txt"
#define LOG_FILE "error_log.txt"

// Global variables
int i2c_handle;
FILE *data_file = NULL;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len, uint8_t crc_init) {
    uint8_t crc = crc_init;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to write a command to the sensor
int write_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(uint8_t *data, int len) {
    int result = i2cReadDevice(i2c_handle, (char *)data, len);
    if (result != len) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate CRC checksums
int validate_crc(const uint8_t *data, int len) {
    uint8_t pressure_crc = crc8(data, 2, 0xFF);
    uint8_t temp_crc = crc8(data + 3, 2, 0xFF);

    if (pressure_crc != data[2] || temp_crc != data[5]) {
        fprintf(stderr, "CRC check failed!\n");
        return -1;
    }
    return 0;
}

// Function to convert raw data to pressure and temperature
void convert_data(const uint8_t *data, float *pressure, float *temperature) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    *pressure = (float)raw_pressure / 20.0; // Scale factor from datasheet
    *temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet
}

// Function to get the current timestamp
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log errors to a file
void log_error(const char *message) {
    char timestamp[20];
    get_timestamp(timestamp);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

// Function to write data to the file
int write_to_file(float pressure, float temperature) {
    char timestamp[20];
    get_timestamp(timestamp);

    if (data_file == NULL) {
        fprintf(stderr, "Data file is not open.\n");
        return -1;
    }

    fprintf(data_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(data_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        log_error("I2C initialization failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Open data file
    data_file = fopen(DATA_FILE, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Write header to data file
    fprintf(data_file, "Timestamp,Pressure(Pa),Temperature(C)\n");
    fflush(data_file);

    // Main loop
    while (!terminate) {
        // Start continuous measurement
        if (write_command(MEASURE_CMD) != 0) {
            log_error("Failed to start measurement");
            break;
        }

        // Wait for measurement to complete
        gpioDelay(1); // Wait at least 1 ms

        // Read data
        uint8_t data[6];
        if (read_data(data, 6) != 0) {
            log_error("Failed to read data");
            break;
        }

        // Validate CRC
        if (validate_crc(data, 6) != 0) {
            log_error("CRC validation failed");
            break;
        }

        // Convert data
        float pressure, temperature;
        convert_data(data, &pressure, &temperature);

        // Write to file
        if (write_to_file(pressure, temperature) != 0) {
            log_error("Failed to write data to file");
            break;
        }

        // Print data to console
        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Delay
        gpioDelay(100); // Delay 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(data_file);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

