#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xE3
#define HUM_CMD 0xE5
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 27.0
#define BUFFER_SIZE 60

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int read_temperature(int i2c_handle);
int read_humidity(int i2c_handle);
void control_fan(float temperature);
void add_to_buffer(CircularBuffer *cb, float temperature);
void print_buffer(CircularBuffer *cb);
void signal_handler(int signal);
void cleanup();

// Circular buffer functions
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

void add_to_buffer(CircularBuffer *cb, float temperature) {
    cb->buffer[cb->head] = temperature;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

void print_buffer(CircularBuffer *cb) {
    printf("Circular Buffer Contents:\n");
    for (int i = 0; i < cb->count; i++) {
        int index = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE; // Corrected index calculation
        printf("  [%d] %.2f\n", index, cb->buffer[index]);
    }
}

// Function to read temperature from Si7021
int read_temperature(int i2c_handle) {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, TEMP_CMD) == 0) {
            gpioDelay(100); // Wait for conversion
            char buf[2];
            if (i2cReadDevice(i2c_handle, buf, 2) == 2) {
                uint16_t raw_temp = (buf[0] << 8) | buf[1];
                float temperature = (175.72 * raw_temp / 65536.0) - 46.85;
                return (int)(temperature * 100); // Return temperature * 100 as integer
            } else {
                fprintf(stderr, "Error reading temperature data. Retries remaining: %d\n", retries);
            }
        } else {
            fprintf(stderr, "Error writing temperature command. Retries remaining: %d\n", retries);
        }
        retries--;
        gpioDelay(10); // Small delay before retry
    }
    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to read humidity from Si7021
int read_humidity(int i2c_handle) {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, HUM_CMD) == 0) {
            gpioDelay(100); // Wait for conversion
            char buf[2];
            if (i2cReadDevice(i2c_handle, buf, 2) == 2) {
