#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// CRC-8 parameters
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c(int addr);
int write_command(int handle, unsigned short command);
int read_data(int handle, unsigned char *data, int count);
int check_crc(unsigned char data[], int len);
int start_periodic_measurement(int handle);
int read_measurement(int handle, unsigned char *data);
int stop_periodic_measurement(int handle);
int log_data(FILE *fp, int co2_ppm, float temperature_c, float humidity_pct);
void signal_handler(int signal);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C bus
int open_i2c(int addr) {
    int handle = i2cOpen(1, addr, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to write a command to the SCD40
int write_command(int handle, unsigned short command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Function to read data from the SCD40
int read_data(int handle, unsigned char *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8 checksum
unsigned char calculate_crc(unsigned char data[], int len) {
    unsigned char crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to check CRC checksum
int check_crc(unsigned char data[], int len) {
    unsigned char crc = calculate_crc(data, len - 1);
    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC check failed: calculated 0x%02X, received 0x%02X\n", crc, data[len - 1]);
        return -1;
    }
    return 0;
}

// Function to start periodic measurement
int start_periodic_measurement(int handle) {
    return write_command(handle, CMD_START_PERIODIC_MEASUREMENT);
}

// Function to read measurement data
int read_measurement(int handle, unsigned char *data) {
    if (write_command(handle, CMD_READ_MEASUREMENT) != 0) {
        return -1;
    }
    gpioDelay(1); // Small delay after command
    return read_data(handle, data, 9);
}

// Function to stop periodic measurement
int stop_periodic_measurement(int handle) {
    return write_command(handle, CMD_STOP_PERIODIC_MEASUREMENT);
}

// Function to log data to file
int log_data(FILE *fp, int co2_ppm, float temperature_c, float humidity_pct) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%.2f,%.2f\n", timestamp, co2_ppm, temperature_c, humidity_pct);
    fflush(fp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c(SCD40_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for the first measurement
    gpioDelay(1000); // 1 second

    unsigned char data[9];
    int co2_ppm, temperature_c, humidity_pct;

    while (!terminate) {
        // Poll data-ready flag (not implemented in this example, but would be here)
        // For this example, we assume data is ready after a short delay
        gpioDelay(5000); // 5 seconds

        // Read measurement data
        if (read_measurement(i2c_handle, data) == 0) {
            // Check CRC
            if (check_crc(data, 9) == 0) {
                // Extract data
                co2_ppm = (data[0] << 8) | data[1];
                temperature_c = (data[3] << 8) | data[4];
                humidity_pct = (data[6] << 8) | data[7];

                // Log data
                if (log_data(log_file, co2_ppm, temperature_c, humidity_pct) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "CRC check failed, skipping data logging\n");
            }
        } else {
            fprintf(stderr, "Failed to read measurement data\n");
        }
    }

    // Stop periodic measurement
    if (stop_periodic_measurement(i2c_handle) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

