#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define TIMEOUT_US 50000
#define SAMPLE_INTERVAL_SEC 5
#define TEMP_MIN -40.0
#define TEMP_MAX 150.0
#define NUM_FAILURES 3

static volatile int running = 1;
static FILE *log_file = NULL;
static int failure_count = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the log file
int open_log_file(const char *filename) {
    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

// Function to close the log file
void close_log_file() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

// Function to terminate the pigpio library
void terminate_pigpio() {
    gpioTerminate();
}

// Function to read the temperature from the TMP05 sensor
float read_temperature() {
    uint32_t start_tick, end_tick, high_tick, low_tick;
    int high_state = 0; // Assume initially low
    uint32_t last_tick = 0;

    // Wait for the first rising edge
    while (gpioRead(GPIO_PIN) == 0) {
        start_tick = gpioTick();
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1.0; // Indicate timeout
        }
    }
    start_tick = gpioTick();

    // Wait for the first falling edge
    while (gpioRead(GPIO_PIN) == 1) {
        end_tick = gpioTick();
        if (gpioTick() - end_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1.0; // Indicate timeout
        }
    }
    end_tick = gpioTick();

    // Calculate high and low pulse widths
    high_tick = start_tick;
    low_tick = end_tick;

    // Calculate duty cycle
    float duty_cycle = (float)(high_tick - low_tick) / (float)(end_tick - low_tick);

    // Convert duty cycle to temperature (example formula, adjust as needed)
    float temperature = 25.0 + (duty_cycle - 0.5) * 100.0; // Example conversion

    return temperature;
}

// Function to log the temperature reading to a file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", buf, temperature);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
}

// Function to check if the temperature is within the valid range
int is_temperature_valid(float temperature) {
    return (temperature >= TEMP_MIN && temperature <= TEMP_MAX);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open the log file
    if (open_log_file("temperature_log.txt") != 0) {
        terminate_pigpio();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature = read_temperature();

        if (temperature < 0) {
            // Handle read error (timeout or other issues)
            failure_count++;
            if (failure_count >= NUM_FAILURES) {
                fprintf(log_file, "SENSOR MALFUNCTION\n");
                fflush(log_file);
                failure_count = 0; // Reset failure count after logging
            }
            printf("Error reading temperature\n");
        } else {
            // Temperature reading successful
            failure_count = 0; // Reset failure count
            if (is_temperature_valid(temperature)) {
                log_temperature(temperature);
                printf("Temperature: %.2f °C\n", temperature);
            } else {
                fprintf(stderr, "Invalid temperature reading: %.2f °C\n", temperature);
                fprintf(log_file, "Invalid temperature reading: %.2f °C\n", temperature);
                fflush(log_file);
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Clean up
    close_log_file();
    terminate_pigpio();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

