        result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result == 0) {
            break; // Success
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
        }
    }

    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command after %d retries\n", RETRY_COUNT);
        return -1;
    }

    gpioDelay(15); // Wait for measurement (at least 15ms)

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    return 0;
}

