    unsigned char bit;

    for (int i = 0; i < data_len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            bit = crc & 0x80;
            if (bit) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc = (crc << 1);
            }
        }
    }
    if (crc != data[data_len - 1]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }
    return 0;
}

