int validate_crc(const unsigned char *data, int len) {
    if (len < 2) return 0; // Not enough data for CRC

    unsigned char temp_crc = crc8(data, len - 2);
    if (temp_crc != data[len - 2]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    if (len < 4) return 0; // Not enough data for humidity CRC

    temp_crc = crc8(data + 3, len - 5);
