#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xE3
#define HUMID_CMD 0xE5
#define RESET_CMD 0xFE
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define TIMEOUT_MS 100
#define LOG_FILE "environment.log"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(int bus, int addr);
int i2c_read_bytes(int handle, int count, char *buf);
int i2c_write_byte(int handle, int data);
int request_measurement(int handle, int command);
int read_measurement(int handle, int *data);
int calculate_crc(int data);
int verify_crc(int data, int crc);
int reset_sensor(int handle);
void log_data(const char *timestamp, float temperature, float humidity);
void signal_handler(int signal);

// Function to open I2C bus
int i2c_open(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "ERROR: Could not open I2C bus %d at address 0x%02X: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Function to read bytes from I2C
int i2c_read_bytes(int handle, int count, char *buf) {
    int bytes_read = i2cReadDevice(handle, buf, count);
    if (bytes_read < 0) {
        fprintf(stderr, "ERROR: I2C read failed: %d\n", bytes_read);
        return -1;
    }
    return bytes_read;
}

// Function to write a byte to I2C
int i2c_write_byte(int handle, int data) {
    int result = i2cWriteByteData(handle, 0, data);
    if (result < 0) {
        fprintf(stderr, "ERROR: I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to request a measurement
int request_measurement(int handle, int command) {
    if (i2c_write_byte(handle, command) < 0) {
        fprintf(stderr, "ERROR: Failed to request measurement command 0x%02X\n", command);
        return -1;
    }
    return 0;
}

// Function to read a measurement with timeout
int read_measurement(int handle, int *data) {
    char buf[3];
    int bytes_read;
    int start_time = time(NULL);

    while (1) {
        bytes_read = i2c_read_bytes(handle, 3, buf);
        if (bytes_read == 3) {
            *data = (buf[0] << 8) | buf[1];
            return 0;
        } else if (bytes_read < 0) {
            fprintf(stderr, "ERROR: I2C read failed during measurement\n");
            return -1;
        } else {
            if (time(NULL) - start_time > (TIMEOUT_MS / 1000.0)) {
                fprintf(stderr, "ERROR: Timeout waiting for measurement data\n");
                return -1;
            }
            gpioDelay(1); // Small delay to avoid busy-waiting
        }
    }
}

// Function to calculate CRC-8 checksum
int calculate_crc(int data) {
    int crc = CRC_INITIAL;
    int i;
    for (i = 0; i < 8; i++) {
        if ((crc ^ data) & 0x01) {
            crc = (crc >> 1) ^ CRC_POLYNOMIAL;
        } else {
            crc >>= 1;
        }
        data >>= 1;
    }
    return crc;
}

// Function to verify CRC checksum
int verify_crc(int data, int crc) {
    int calculated_crc = calculate_crc(data);
    if (calculated_crc != crc) {
        fprintf(stderr, "ERROR: CRC checksum mismatch (calculated: 0x%02X, received: 0x%02X)\n", calculated_crc, crc);
        return -1;
    }
    return 0;
}

// Function to reset the sensor
int reset_sensor(int handle) {
    if (i2c_write_byte(handle, RESET_CMD) < 0) {
        fprintf(stderr, "ERROR: Failed to reset sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete
    return 0;
}

// Function to log data to CSV file
void log_data(const char *timestamp, float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "ERROR: Could not open log file %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "INFO: Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "ERROR: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2c_open(I2C_BUS, SI7021_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int temperature_raw, humidity_raw;
        float temperature, humidity;
        char timestamp[32];
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tstruct);

        // Request temperature measurement
        if (request_measurement(i2c_handle, TEMP_CMD) < 0) {
            fprintf(stderr, "ERROR: Failed to request temperature measurement\n");
            reset_sensor(i2c_handle);
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Read temperature measurement
        if (read_measurement(i2c_handle, &temperature_raw) < 0) {
            fprintf(stderr, "ERROR: Failed to read temperature measurement\n");
            reset_sensor(i2c_handle);
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Verify temperature CRC
        if (verify_crc(temperature_raw, ((temperature_raw >> 8) & 0xFF)) < 0) {
            fprintf(stderr, "ERROR: Temperature CRC verification failed\n");
            reset_sensor(i2c_handle);
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Convert temperature to Celsius
        temperature = (175.72 * temperature_raw / 65536.0) - 46.85;

        // Request humidity measurement
        if (request_measurement(i2c_handle, HUMID_CMD) < 0) {
            fprintf(stderr, "ERROR: Failed to request humidity measurement\n");
            reset_sensor(i2c_handle);
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Read humidity measurement
        if (read_measurement(i2c_handle, &humidity_raw) < 0) {
            fprintf(stderr, "ERROR: Failed to read humidity measurement\n");
            reset_sensor(i2c_handle);
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Verify humidity CRC
        if (verify_crc(humidity_raw, ((humidity_raw >> 8) & 0xFF)) < 0) {
            fprintf(stderr, "ERROR: Humidity CRC verification failed\n");
            reset_sensor(i2c_handle);
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Convert humidity to percentage
        humidity = (125.0 * humidity_raw / 65536.0) - 6.0;

        // Log data
        log_data(timestamp, temperature, humidity);

        printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

