int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to calculate CRC8 checksum
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
