// Function to validate CRC checksums
int validate_crc(const char *buffer) {
    uint8_t pressure_data[6];
    uint8_t temperature_data[6];

    // Extract pressure data (MSB, LSB, CRC)
    for (int i = 0; i < 3; i++) {
        pressure_data[i] = buffer[i];
