    // Extract temperature data (MSB, LSB, CRC)
    for (int i = 0; i < 3; i++) {
        temperature_data[i] = buffer[3 + i];
    }

    uint8_t calculated_pressure_crc = calculate_crc8(pressure_data, 2);
    uint8_t calculated_temperature_crc = calculate_crc8(temperature_data, 2);

    if (calculated_pressure_crc != buffer[2] || calculated_temperature_crc != buffer[5]) {
