sensor_data_t parse_data(const char *buffer);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC checksums
int validate_crc(const char *buffer) {
    uint8_t data[2];
    uint8_t crc;

    // Pressure CRC
    data[0] = buffer[0];
    data[1] = buffer[1];
    crc = calculate_crc(data, 2);
    if (crc != buffer[2]) {
        fprintf(stderr, "Pressure CRC check failed\n");
        return -1;
    }

    // Temperature CRC
    data[0] = buffer[3];
    data[1] = buffer[4];
    crc = calculate_crc(data, 2);
    if (crc != buffer[5]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

