            timestamp, data.pressure, data.temperature, data.status);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char buffer[9];
        sensor_data_t sensor_data;

        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            break;
        }

        // Wait for conversion time (45ms)
        gpioDelay(45000); // 45ms

        // Read data from sensor
        if (read_data(i2c_handle, buffer, 9) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        // Validate CRC checksums
        if (validate_crc(buffer) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            break;
        }

        // Parse sensor data
        sensor_data = parse_data(buffer);

        // Log data to file
        if (log_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
            break;
        }

        // Sleep for 5 seconds
        sleep(SLEEP_DURATION);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated\n");
    return 0;
}

