// LPS33HW I2C address
#define LPS33HW_ADDR 0x5C

// LPS33HW register addresses
#define CTRL_REG1 0x20
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lps33hw();
int read_pressure(float *pressure);
int read_temperature(float *temperature);
void log_data(float pressure, float temperature);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function to initialize the LPS33HW sensor
int init_lps33hw() {
    // Enable continuous data acquisition (ODR = 1 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x10) < 0) {
        return -1;
    }
    return 0;
}

// Function to read pressure data from the LPS33HW
int read_pressure(float *pressure) {
    char buffer[3];
    if (i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3) != 3) {
        return -1;
    }

    int32_t raw_pressure = (int32_t)buffer[0] | ((int32_t)buffer[1] << 8) | ((int32_t)buffer[2] << 16);
    *pressure = (float)raw_pressure / 4096.0; // Convert to hPa
    return 0;
}

// Function to read temperature data from the LPS33HW
int read_temperature(float *temperature) {
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2) != 2) {
        return -1;
    }

    int16_t raw_temperature = (int16_t)buffer[0] | ((int16_t)buffer[1] << 8);
    *temperature = (float)raw_temperature / 100.0; // Convert to °C
    return 0;
}

// Function to log data to a file
void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime_r(&now, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(log_file);
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0); // Bus 1, address 0x5C, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LPS33HW sensor
    if (init_lps33hw() < 0) {
        fprintf(stderr, "Failed to initialize LPS33HW sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    float pressure, temperature;
    while (!terminate) {
        // Read pressure and temperature
        if (read_pressure(&pressure) == 0 && read_temperature(&temperature) == 0) {
            // Log data
            log_data(pressure, temperature);
        } else {
            // Log error
            time_t now = time(NULL);
            struct tm *t = localtime_r(&now, NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(stderr, "%s, Error reading sensor data\n", timestamp);
            fprintf(log_file, "%s, Error reading sensor data\n", timestamp);
            fflush(log_file);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

