#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define LED_GPIO 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
float read_temperature();
void update_buffer(float temperature);
float calculate_average();
void control_led(float average_temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to read temperature from LM75 sensor
float read_temperature() {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    float temperature = raw_temp * 0.125;

    return temperature;
}

// Function to update the circular buffer
void update_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the average temperature
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the LED based on the average temperature
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

