    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize temperature buffer with 0s
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            update_buffer(temperature);
            float average_temperature = calculate_average();
            control_led(average_temperature);
