#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// SCD30 I2C address
#define SCD30_I2C_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_PERIODIC_MEASUREMENT 0x0010
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define SCD30_CMD_GET_DATA_READY 0x0202
#define SCD30_CMD_SET_MEASUREMENT_INTERVAL 0x4600

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_scd30();
int read_scd30_data(float *co2, float *temperature, float *humidity);
int log_data(float co2, float temperature, float humidity);
int control_ventilation(float co2);
void signal_handler(int signal);
int check_sensor_presence();
int stop_periodic_measurement();
int set_measurement_interval(int interval);

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize the SCD30 sensor
int init_scd30() {
    // Check sensor presence
    if (check_sensor_presence() != 0) {
        fprintf(stderr, "Error: SCD30 sensor not found or initialization failed.\n");
        return -1;
    }

    // Set measurement interval to 5 seconds
    if (set_measurement_interval(5) != 0) {
        fprintf(stderr, "Error: Failed to set measurement interval.\n");
        return -1;
    }

    // Start periodic measurement
    if (stop_periodic_measurement() != 0) {
        fprintf(stderr, "Error: Failed to stop periodic measurement before starting.\n");
        return -1;
    }
    if (i2cWriteWordData(i2c_handle, SCD30_CMD_START_PERIODIC_MEASUREMENT, 0x0000) < 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for the command to be processed

    return 0;
}

// Function to check if the SCD30 sensor is present
int check_sensor_presence() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: Failed to read from sensor: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to set the measurement interval
int set_measurement_interval(int interval) {
    int command = SCD30_CMD_SET_MEASUREMENT_INTERVAL;
    int data = interval * 1000; // Convert seconds to milliseconds
    char buf[4];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    buf[2] = (data >> 8) & 0xFF;
    buf[3] = data & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 4) < 0) {
        fprintf(stderr, "Error: Failed to set measurement interval: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for the command to be processed
    return 0;
}

// Function to stop periodic measurement
int stop_periodic_measurement() {
    if (i2cWriteWordData(i2c_handle, SCD30_CMD_STOP_PERIODIC_MEASUREMENT, 0x0000) < 0) {
        fprintf(stderr, "Error: Failed to stop periodic measurement: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for the command to be processed
    return 0;
}

// Function to read data from the SCD30 sensor
int read_scd30_data(float *co2, float *temperature, float *humidity) {
    char buf[2];
    int data_ready = 0;

    // Check if data is ready
    while (1) {
        buf[0] = (SCD30_CMD_GET_DATA_READY >> 8) & 0xFF;
        buf[1] = SCD30_CMD_GET_DATA_READY & 0xFF;
        if (i2cWriteDevice(i2c_handle, buf, 2) < 0) {
            fprintf(stderr, "Error: Failed to write GET DATA READY command: %s\n", strerror(errno));
            return -1;
        }
        gpioDelay(10); // Small delay before reading

        char read_buf[2];
        if (i2cReadDevice(i2c_handle, read_buf, 2) < 0) {
            fprintf(stderr, "Error: Failed to read data ready status: %s\n", strerror(errno));
            return -1;
        }

        data_ready = (read_buf[0] << 8) | read_buf[1];
        if (data_ready) break;
        gpioDelay(100); // Wait for data to be ready
    }

    // Read measurement data
    buf[0] = (SCD30_CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD30_CMD_READ_MEASUREMENT & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) < 0) {
        fprintf(stderr, "Error: Failed to write read measurement command: %s\n", strerror(errno));
        return -1;
    }

    char data[18];
    if (i2cReadDevice(i2c_handle, data, 18) < 0) {
        fprintf(stderr, "Error: Failed to read measurement data: %s\n", strerror(errno));
        return -1;
    }

    // CRC check (simplified, assuming data is correct)
    // In a real application, implement proper CRC calculation and comparison

    // Extract data
    int co2_raw = (data[0] << 8) | data[1];
    int temperature_raw = (data[3] << 8) | data[4];
    int humidity_raw = (data[6] << 8) | data[7];

    *co2 = (float)co2_raw;
    *temperature = -45 + 175 * ((float)temperature_raw / 65535.0);
    *humidity = 100 * ((float)humidity_raw / 65535.0);

    return 0;
}

// Function to log data to a file
int log_data(float co2, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", buf, co2, temperature, humidity);
    fflush(log_file);

    return 0;
}

// Function to control ventilation based on CO2 level
int control_ventilation(float co2) {
    if (co2 < 800) {
        printf("Ventilation: OFF\n");
    } else if (co2 >= 800 && co2 < 1200) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SCD30 sensor
    if (init_scd30() != 0) {
        fprintf(stderr, "Error: SCD30 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float co2, temperature, humidity;
    while (!terminate) {
        if (read_scd30_data(&co2, &temperature, &humidity) == 0) {
            log_data(co2, temperature, humidity);
            control_ventilation(co2);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }
        sleep(5);
    }

    // Cleanup
    stop_periodic_measurement();
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

