#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SDP32 I2C address
#define SDP32_ADDR 0x21

// CRC-8 polynomial
#define CRC8_POLY 0x31

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint16_t scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sdp32(sensor_data_t *data);
int calculate_crc(uint8_t data[], int len);
void print_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, SDP32_ADDR, 0); // Bus 1, address 0x21, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from SDP32
int read_sdp32(sensor_data_t *data) {
    uint8_t buffer[9];
    int result;

    result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // CRC Check
    if (calculate_crc(buffer, 2) != buffer[2] ||
        calculate_crc(buffer + 3, 2) != buffer[5] ||
        calculate_crc(buffer + 6, 2) != buffer[8]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert data
    data->pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    data->scale_factor = (uint16_t)((buffer[6] << 8) | buffer[7]);

    return 0;
}

// Function to calculate CRC-8
int calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to print data with timestamp
void print_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Pressure: %d Pa, Temperature: %d °C, Scale Factor: %d\n", timestamp, data.pressure, data.temperature, data.scale_factor);
}

// Function to cleanup resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int interval = 1000; // Default interval in milliseconds
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "i:")) != -1) {
        switch (opt) {
            case 'i':
                interval = atoi(optarg);
                if (interval <= 0) {
                    fprintf(stderr, "Invalid interval. Using default 1000ms.\n");
                    interval = 1000;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-i interval_ms]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sdp32(&sensor_data) == 0) {
            print_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(interval * 1000); // pigpio uses microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

