#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define TRIGGER_MEASUREMENT 0x362F
#define MEASUREMENT_INTERVAL_MS 45
#define LOGGING_INTERVAL_S 1

// CRC-8 polynomial and initial value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
int validate_crc(const uint8_t *data, int len);
sensor_data_t process_sensor_data(const uint8_t *data);
void log_sensor_data(const sensor_data_t *data);
void signal_handler(int signal);

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to trigger a measurement
int trigger_measurement() {
    uint8_t cmd[2] = {(TRIGGER_MEASUREMENT >> 8) & 0xFF, TRIGGER_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate CRC-8 checksum
int validate_crc(const uint8_t *data, int len) {
    for (int i = 0; i < len; i += 3) {
        uint8_t crc = data[i + 2];
        uint8_t data_bytes[2] = {data[i], data[i + 1]};

        for (int j = 0; j < 8; j++) {
            int bit = (crc ^ data_bytes[j]) & 0x01;
            crc >>= 1;
            if (bit) {
                crc ^= CRC8_POLYNOMIAL;
            }
        }

        if (crc != CRC8_INITIAL) {
            fprintf(stderr, "CRC validation failed at byte %d\n", i);
            return -1;
        }
    }
    return 0;
}

// Function to process sensor data
sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Apply scaling factors (from datasheet)
    sensor_data.pressure = (float)raw_pressure / 240.0; // Pa
    sensor_data.temperature = (float)raw_temperature / 200.0; // °C

    return sensor_data;
}

// Function to log sensor data
void log_sensor_data(const sensor_data_t *data) {
    printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", data->pressure, data->temperature);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete
        gpioDelay(MEASUREMENT_INTERVAL_MS);

        // Read sensor data
        uint8_t sensor_data[9];
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC
        if (validate_crc(sensor_data, 9) != 0) {
            fprintf(stderr, "CRC validation failed, skipping data.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Process sensor data
        sensor_data_t processed_data = process_sensor_data(sensor_data);

        // Log sensor data
        log_sensor_data(&processed_data);

        // Wait for the next logging interval
        gpioDelay(LOGGING_INTERVAL_S * 1000); // Convert seconds to milliseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

