#define HUMIDITY_REG 0x01
#define CONFIGURATION_REG 0x02

// I2C bus number
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the HDC1000 sensor
int init_hdc1000() {
    // Configure the sensor for temperature and humidity measurement
    // 14-bit resolution, temperature and humidity measurement mode
    char config_data[2] = {0x00, 0x00}; // Default configuration
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity data from the HDC1000
int read_hdc1000(float *temperature, float *humidity) {
    unsigned char data[4];
    int result;

    // Trigger temperature and humidity measurement
    result = i2cWriteByte(i2c_handle, TEMPERATURE_REG);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 20ms)
    gpioDelay(20000); // 20ms

    // Read temperature data
    result = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (result != 0) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    unsigned int raw_temperature = (data[0] << 8) | data[1];
    unsigned int raw_humidity = (data[2] << 8) | data[3];

    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

