#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define TEMP_ERROR -999.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
double read_temperature();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read temperature from Si7051 sensor
double read_temperature() {
    int raw_temperature;
    double temperature_celsius;

    // Send temperature measurement command
    if (i2cWriteByte(i2c_handle, MEASURE_TEMP_CMD) != 0) {
        fprintf(stderr, "Error: Failed to write temperature measurement command.\n");
        return TEMP_ERROR;
    }

    // Wait for measurement to complete (at least 20ms)
    gpioDelay(20000); // 20ms

    // Read temperature data (2 bytes)
    raw_temperature = i2cReadWordData(i2c_handle, 0);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error: Failed to read temperature data. Error code: %d\n", raw_temperature);
        return TEMP_ERROR;
    }

    // Convert raw temperature to Celsius
    temperature_celsius = (175.72 * raw_temperature / 65536.0) - 46.85;

    return temperature_celsius;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

