#define MEASUREMENT_DELAY_MS 8
#define CSV_FILE "airflow_log.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to trigger a measurement
int trigger_measurement() {
    char cmd[2] = {(TRIGGER_CMD >> 8) & 0xFF, TRIGGER_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the sensor data
int read_sensor_data(unsigned char *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to verify the CRC checksum
int verify_crc(const unsigned char *data) {
    unsigned char crc_calculated = crc8(data, 2);
    if (crc_calculated != data[2]) {
        fprintf(stderr, "CRC checksum failed\n");
        return -1;
    }
    return 0;
}

