        gpioDelay(MEASUREMENT_DELAY_MS);

        // Read sensor data
        unsigned char data[3];
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Verify CRC checksum
        if (verify_crc(data) != 0) {
            fprintf(stderr, "CRC verification failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to pressure
        float pressure = convert_to_pressure(data);

        // Log data
        if (log_data(pressure) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("Pressure: %.2f Pa\n", pressure);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Airflow monitoring stopped.\n");
    return 0;
}

