#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define MLX90821_ADDR 0x40
#define PRESSURE_REG 0x00 // Example register address, check datasheet
#define PRESSURE_MIN 200.0f
#define PRESSURE_MAX 250.0f
#define LOG_FILE "pressure_log.csv"
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_pressure(float *pressure);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int mlx90821_address;
    char *log_file_name;
    float pressure_min;
    float pressure_max;
} config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure from the sensor
int read_pressure(float *pressure) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2); // Read 2 bytes
        if (result == 2) {
            // Convert raw data to pressure (example conversion, adjust based on datasheet)
            int16_t raw_pressure = (buf[0] << 8) | buf[1];
            *pressure = (float)raw_pressure * 0.1f; // Example scaling
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(10000); // 10ms delay
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C after read failure.\n");
                return -1; // Fatal error
            }
            retries++;
        }
    }

    fprintf(stderr, "Failed to read pressure after %d retries.\n", RETRY_COUNT);
    return -1; // Failure after all retries
}

// Log pressure to file
int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

