    uint16_t humidity_raw = ((buf[0] & 0x3F) << 8) | buf[1];
    uint16_t temperature_raw = (buf[2] << 6) | (buf[3] >> 2);

    // Validate sensor data
    if (validate_sensor_data(data) != 0) {
        fprintf(stderr, "Invalid sensor data\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    data->humidity = ((float)humidity_raw / 16383) * 100;
