    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        // File doesn't exist or can't be opened, nothing to do
        return 0;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    fclose(fp);

    if (file_size > MAX_LOG_SIZE) {
