            fprintf(stderr, "Error reading sensor data\n");
        }

        // Check log file size
        if (check_log_size() != 0) {
            fprintf(stderr, "Error checking log size\n");
        }

        // Wait for the next measurement
        sleep(MEASUREMENT_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

