#include <pigpio.h>

#define GPIO_PIN 4
#define TIMEOUT_US 100000 // 100ms timeout
#define SYNC_PULSE_MIN 56
#define SYNC_PULSE_MAX 56
#define NIBBLE_MIN 12
#define NIBBLE_MAX 271
#define MAX_PULSE_WIDTH 271

// Structure to hold SENT data
typedef struct {
    unsigned char status_nibble;
    unsigned char data_nibble1;
    unsigned char data_nibble2;
    unsigned char data_nibble3;
    unsigned char checksum_nibble;
} SENT_Data;

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sent_data(SENT_Data *data);
float calculate_pressure(const SENT_Data *data);
void log_pressure_data(float pressure);
