// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize pigpio safely
int pigpio_init_safe() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Reads SENT data from the sensor
int read_sent_data(SENT_Data *data) {
    int i;
    int pulse_width;
    long start_time, end_time, diff;

    // Synchronization pulse
    start_time = gpioTick();
    while (gpioRead(GPIO_PIN) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            log_error("Timeout waiting for synchronization pulse start.");
            return -1;
        }
    }
    start_time = gpioTick();
    while (gpioRead(GPIO_PIN) == 0) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            log_error("Timeout waiting for synchronization pulse end.");
            return -1;
        }
    }
    end_time = gpioTick();
    diff = end_time - start_time;
    if (diff < SYNC_PULSE_MIN || diff > SYNC_PULSE_MAX) {
        log_error("Invalid synchronization pulse width.");
        return -1;
    }

    // Status nibble
    for (i = 0; i < 4; i++) {
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 1) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                log_error("Timeout waiting for status nibble start.");
                return -1;
            }
        }
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 0) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                log_error("Timeout waiting for status nibble end.");
                return -1;
            }
        }
        end_time = gpioTick();
        diff = end_time - start_time;
        if (diff < NIBBLE_MIN || diff > NIBBLE_MAX) {
            log_error("Invalid status nibble pulse width.");
            return -1;
        }
        data->status_nibble |= (diff > 64) << (3 - i); // Assuming 64 is the threshold for 1
    }

    // Data nibble 1
    for (i = 0; i < 4; i++) {
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 1) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                log_error("Timeout waiting for data nibble 1 start.");
                return -1;
            }
        }
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 0) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                log_error("Timeout waiting for data nibble 1 end.");
                return -1;
            }
        }
        end_time = gpioTick();
        diff = end_time - start_time;
        if (diff < NIBBLE_MIN || diff > NIBBLE_MAX) {
            log_error("Invalid data nibble 1 pulse width.");
            return -1;
        }
        data->data_nibble1 |= (diff > 64) << (3 - i); // Assuming 64 is the threshold for 1
    }

    // Data nibble 2
    for (i = 0; i < 4; i++) {
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 1) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                log_error("Timeout waiting for data nibble 2 start.");
                return -1;
            }
        }
