            if (gpioTick() - start_time > TIMEOUT_US) {
                log_error("Timeout waiting for data nibble 2 end.");
                return -1;
            }
        }
        end_time = gpioTick();
        diff = end_time - start_time;
        if (diff < NIBBLE_MIN || diff > NIBBLE_MAX) {
            log_error("Invalid data nibble 2 pulse width.");
            return -1;
        }
        data->data_nibble2 |= (diff > 64) << (3 - i); // Assuming 64 is the threshold for 1
    }

    // Data nibble 3
    for (i = 0; i < 4; i++) {
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 1) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                log_error("Timeout waiting for data nibble 3 start.");
                return -1;
            }
        }
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 0) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                log_error("Timeout waiting for data nibble 3 end.");
                return -1;
            }
        }
        end_time = gpioTick();
        diff = end_time - start_time;
        if (diff < NIBBLE_MIN || diff > NIBBLE_MAX) {
            log_error("Invalid data nibble 3 pulse width.");
            return -1;
        }
        data->data_nibble3 |= (diff > 64) << (3 - i); // Assuming 64 is the threshold for 1
    }

    // Checksum nibble
    for (i = 0; i < 4; i++) {
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 1) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                log_error("Timeout waiting for checksum nibble start.");
                return -1;
            }
        }
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 0) {
            if (gpioTick() - start_time > TIMEOUT_US) {
