#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x0F
#define DEVICE_ID 0x5441 // "TA" in hex
#define LOG_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
int write_temperature_log(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int tmp117_address;
    char *log_file_name;
    int sample_interval;
} config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Verify device ID
    char buf[2];
    buf[0] = DEVICE_ID_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to device ID register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }

    uint16_t read_id = (buf[1] << 8) | buf[0];
    if (read_id != DEVICE_ID) {
        fprintf(stderr, "Error: Incorrect device ID. Expected 0x%X, got 0x%X\n", DEVICE_ID, read_id);
        return -1;
    }

    printf("TMP117 device ID verified.\n");
    return 0;
}

// Read temperature from TMP117
int read_temperature(float *temperature) {
    char buf[1];
    char data[2];

    buf[0] = TEMP_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to temperature register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    int16_t raw_temp = (data[1] << 8) | data[0];
    *temperature = raw_temp * 0.0078125; // Resolution is 0.0078125 degrees C
    return 0;
}

// Write temperature to log file
int write_temperature_log(float temperature) {
    uint32_t temp_int = *(uint32_t *)&temperature; // Cast float to uint32_t
    uint8_t bytes[4];
    bytes[0] = temp_int & 0xFF;       // Byte 0
    bytes[1] = (temp_int >> 8) & 0xFF; // Byte 1
    bytes[2] = (temp_int >> 16) & 0xFF; // Byte 2
    bytes[3] = (temp_int >> 24) & 0xFF; // Byte 3

    if (fwrite(bytes, 1, 4, log_file) != 4) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature;
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[26];

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            if (write_temperature_log(temperature) != 0) {
                fprintf(stderr, "Error writing temperature to log, but continuing...\n");
            }
            printf("Temperature: %.2f °C\n", temperature);

            // Get current timestamp
            gettimeofday(&tv, NULL);
            tm_info = localtime(&tv.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("Timestamp: %s\n", timestamp);
        } else {
            fprintf(stderr, "Error reading temperature, but continuing...\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

