#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// CRC-8 polynomial and initial value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int crc8(const uint8_t *data, int len);
int read_sht40(int i2c_handle, float *temperature, float *humidity);
int validate_crc(const uint8_t *data, int len);
void signal_handler(int signal);

// CRC-8 calculation function
int crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t cmd = 0xFD; // High precision measurement command
    uint8_t data[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write to I2C device.\n");
        return -1;
    }

    // Wait for conversion (at least 8.5 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read from I2C device.\n");
        return -1;
    }

    // Validate CRC for temperature
    if (validate_crc(data, 3) != 0) {
        fprintf(stderr, "Error: Temperature CRC validation failed.\n");
        return -1;
    }

    // Validate CRC for humidity
    if (validate_crc(data + 3, 3) != 0) {
        fprintf(stderr, "Error: Humidity CRC validation failed.\n");
        return -1;
    }

    // Convert data to temperature and humidity
    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

// Function to validate CRC checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    if (crc != data[len - 1]) {
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

