    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C interface
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float temperature, humidity;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Main loop
    while (!terminate) {
        // Read temperature and humidity
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            // Get current timestamp
