#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHTC3_ADDR 0x70
#define MEASURE_CMD 0x7866
#define CRC8_POLY 0x31
#define MIN_TEMP -40.0
#define MAX_TEMP 125.0
#define MIN_HUMIDITY 0.0
#define MAX_HUMIDITY 100.0
#define LOG_FILE "shtc3_environment.log"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_shtc3_data(unsigned char *data);
int calculate_crc(const unsigned char *data, int len, unsigned char *crc);
int validate_data(unsigned char *data);
float convert_temperature(unsigned short raw_temp);
float convert_humidity(unsigned short raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure for grouping sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

int main() {
    unsigned char data[6];
    SensorData sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read data from SHTC3
        if (read_shtc3_data(data) == 0) {
            // Validate data
            if (validate_data(data) == 0) {
                // Convert data
                unsigned short raw_temp = (data[0] << 8) | data[1];
                unsigned short raw_humidity = (data[3] << 8) | data[4];

                sensor_data.temperature = convert_temperature(raw_temp);
                sensor_data.humidity = convert_humidity(raw_humidity);

                // Log data
                if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }

                // Print data to stdout
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
            } else {
                fprintf(stderr, "Data validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read data from SHTC3\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read data from SHTC3
int read_shtc3_data(unsigned char *data) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Failed to write command to SHTC3\n");
        return 1;
    }

    gpioDelay(12400); // Wait 12.4 ms

    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Failed to read data from SHTC3\n");
        return 1;
    }

    return 0;
}

// Calculate CRC-8 checksum
int calculate_crc(const unsigned char *data, int len, unsigned char *crc) {
    *crc = 0xFF;
    for (int i = 0; i < len; i++) {
        *crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((*crc) & 0x80) {
                *crc = (*crc << 1) ^ CRC8_POLY;
            } else {
                *crc <<= 1;
            }
        }
    }
    return 0;
}

// Validate data
int validate_data(unsigned char *data) {
    unsigned char temp_crc, humidity_crc;

    calculate_crc(data, 2, &temp_crc);
    calculate_crc(data + 3, 2, &humidity_crc);

    if (temp_crc != data[2] || humidity_crc != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return 1;
    }

    // Check temperature range
    float temperature = convert_temperature((data[0] << 8) | data[1]);
    if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
        fprintf(stderr, "Temperature out of range\n");
        return 1;
    }

    // Check humidity range
    float humidity = convert_humidity((data[3] << 8) | data[4]);
    if (humidity < MIN_HUMIDITY || humidity > MAX_HUMIDITY) {
        fprintf(stderr, "Humidity out of range\n");
        return 1;
    }

    return 0;
}

// Convert raw temperature data to Celsius
float convert_temperature(unsigned short raw_temp) {
    return 175.0 * raw_temp / 65535.0 - 45.0;
}

// Convert raw humidity data to percentage
float convert_humidity(unsigned short raw_humidity) {
    return 100.0 * raw_humidity / 65535.0;
}

// Log data to file
int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Ctrl+C pressed, exiting...\n");
}

