#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define CONFIG_REG 0x01
#define LOG_FILE "temperature_log.txt"
#define MAX_REINIT_ATTEMPTS 3

// Global variables
int i2c_handle = -1;
int reinit_attempts = 0;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
float read_temperature();
void log_temperature(float temperature);
void signal_handler(int signal);

// Structure for configuration (optional, but good practice)
typedef struct {
    int bus;
    int address;
    int reinit_attempts_max;
} sensor_config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117
float read_temperature() {
    int raw_temp;
    float temperature;

    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate error
    }

    // Convert raw temperature to Celsius
    temperature = (float)raw_temp * 0.0078125;
    return temperature;
}

// Log temperature to file
void log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Temperature: %.2f C\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        float temperature;

        // Re-initialize I2C if needed
        if (i2c_handle < 0) {
            if (init_i2c() != 0) {
                reinit_attempts++;
                fprintf(stderr, "I2C re-initialization attempt %d failed.\n", reinit_attempts);
                if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                    fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                    break; // Exit the loop if re-initialization fails too many times
                }
                sleep(1); // Wait before retrying
                continue; // Skip to the next iteration
            } else {
                reinit_attempts = 0; // Reset reinit attempts on success
            }
        }

        temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Logging error.\n");
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
            fprintf(log_file, "%s, Error: Failed to read temperature.\n", timestamp);
            fflush(log_file);
        }

        sleep(1); // Sample every 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

