#define FLOW_SCALE_FACTOR 0.01
#define TEMPERATURE_SCALE_FACTOR 0.1
#define DISCONNECTED_THRESHOLD 5 // Number of consecutive failed reads before considering sensor disconnected
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
