int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading I2C: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Extract flow and temperature from raw data
int extract_flow_temperature(const uint8_t *data, float *flow, float *temperature) {
    // Combine the first two bytes for flow (14-bit)
    int16_t raw_flow = (data[0] << 8) | data[1];
    // Combine the last two bytes for temperature (12-bit)
    int16_t raw_temperature = (data[2] << 8) | data[3];

    // Apply scaling factors
    *flow = (float)raw_flow * FLOW_SCALE_FACTOR;
    *temperature = (float)raw_temperature * TEMPERATURE_SCALE_FACTOR;

    return 0;
}

// Log data to file
int log_data(float flow, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Flow: %.2f SLPM, Temperature: %.2f °C\n", timestamp, flow, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

