#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define MAX_TIMINGS 85
#define TIMEOUT 100000 // 100ms

// Structure to hold DHT11 data
typedef struct {
    int humidity_int;
    int humidity_dec;
    int temperature_int;
    int temperature_dec;
    int checksum;
} DHT11Data;

// Global variables
static volatile int timings[MAX_TIMINGS];
static volatile int timing_index = 0;
static volatile int data_ready = 0;
static FILE *log_file = NULL;
static FILE *data_file = NULL;
static int running = 1;

// Function prototypes
void dht11_callback(int gpio, int level, uint32_t tick);
int read_dht11_data(DHT11Data *data);
int verify_checksum(DHT11Data data);
int log_error(const char *message, int status_code);
int log_data(DHT11Data data);
void signal_handler(int signal);

// Callback function for DHT11 data acquisition
void dht11_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t diff;

    if (level == PI_TIMEOUT) {
        if (timing_index < MAX_TIMINGS) {
            timings[timing_index++] = 0; // Timeout
        }
        return;
    }

    diff = tick - last_tick;
    last_tick = tick;

    if (timing_index < MAX_TIMINGS) {
        timings[timing_index++] = diff;
    }
}

// Function to read DHT11 data
int read_dht11_data(DHT11Data *data) {
    int i, j;
    int humidity = 0;
    int temperature = 0;

    // Initialize data structure
    data->humidity_int = 0;
    data->humidity_dec = 0;
    data->temperature_int = 0;
    data->temperature_dec = 0;
    data->checksum = 0;

    // Send start signal
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(18000); // 18ms
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(30); // 30us

    // Switch to input mode
    gpioSetMode(DHT11_GPIO, PI_INPUT);

    // Wait for response
    gpioDelay(80); // Wait for 80us
    if (gpioRead(DHT11_GPIO) == 1) {
        gpioDelay(80); // Wait for 80us
        if (gpioRead(DHT11_GPIO) == 0) {
            gpioDelay(50); // Wait for 50us
            if (gpioRead(DHT11_GPIO) == 1) {
                // Start reading data
                timing_index = 0;
                data_ready = 0; // Reset data ready flag

                // Wait for data to be ready
                int timeout_count = 0;
                while (!data_ready && timeout_count < 100) {
                    gpioDelay(1000); // Wait 1ms
                    timeout_count++;
                }

                if (!data_ready) {
                    log_error("DHT11 response timeout", 2);
                    return -1;
                }

                // Decode data
                for (i = 0; i < 40; i++) {
                    // Wait for low
                    while (gpioRead(DHT11_GPIO) == 0 && timing_index < MAX_TIMINGS) {
                        timings[timing_index++] = 0;
                    }

                    // Measure high time
                    while (gpioRead(DHT11_GPIO) == 1 && timing_index < MAX_TIMINGS) {
                        timings[timing_index++] = 0;
                    }

                    if (timing_index >= MAX_TIMINGS) {
                        log_error("DHT11 data timeout", 3);
                        return -1;
                    }

                    if (timings[i * 2 + 1] > 28) {
                        humidity = humidity << 1;
                        temperature = temperature << 1;
                    } else {
                        humidity = humidity << 1;
                        temperature = temperature << 1;
                        if (timings[i * 2 + 1] > 16) {
                            humidity++;
                        } else {
                            temperature++;
                        }
                    }
                }

                data->humidity_int = humidity;
                data->temperature_int = temperature;

                // Calculate checksum
                data->checksum = (data->humidity_int + data->humidity_dec + data->temperature_int + data->temperature_dec) & 0xFF;

                // Verify checksum
                if (!verify_checksum(*data)) {
                    log_error("DHT11 checksum failure", 4);
                    return -1;
                }

                return 0;
            } else {
                log_error("DHT11 data line stuck low", 5);
                return -1;
            }
        } else {
            log_error("DHT11 data line stuck high", 6);
            return -1;
        }
    } else {
        log_error("DHT11 data line stuck high", 7);
        return -1;
    }
}

// Function to verify checksum
int verify_checksum(DHT11Data data) {
    return (data.humidity_int + data.humidity_dec + data.temperature_int + data.temperature_dec) == data.checksum;
}

// Function to log errors
int log_error(const char *message, int status_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s - ERROR: %s (Status Code: %d)\n", timestamp, message, status_code);
        fflush(log_file);
    } else {
        fprintf(stderr, "%s - ERROR: %s (Status Code: %d)\n", timestamp, message, status_code);
    }
    return 0;
}

// Function to log data
int log_data(DHT11Data data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (data_file != NULL) {
        fprintf(data_file, "%s,%.1f,%.1f\n", timestamp, data.humidity_int, data.temperature_int);
        fflush(data_file);
    } else {
        fprintf(stderr, "%s - Data: Humidity=%.1f, Temperature=%.1f\n", timestamp, data.humidity_int, data.temperature_int);
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    DHT11Data dht11_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("dht11_readings.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
    }

    // Open data file
    data_file = fopen("dht11_readings.txt", "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file!\n");
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set GPIO mode and pull-up resistor
    gpioSetMode(DHT11_GPIO, PI_INPUT);
    gpioSetPullUpDown(DHT11_GPIO, PI_PUD_UP);

    // Set alert function
    gpioSetAlertFuncEx(DHT11_GPIO, dht11_callback, NULL);

    printf("DHT11 reader started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_dht11_data(&dht11_data) == 0) {
            log_data(dht11_data);
        } else {
            log_error("Failed to read DHT11 data", 1);
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup
    gpioSetAlertFuncEx(DHT11_GPIO, NULL, NULL); // Disable callback
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }

    printf("DHT11 reader stopped.\n");
    return 0;
}

