#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06 // High repeatability, clock stretching disabled
#define RETRY_COUNT 3
#define LOG_FILE "sht31d_data.log"
#define SLEEP_DURATION 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c(int bus, int addr);
int write_i2c(int handle, int count, char *data);
int read_i2c(int handle, int count, char *data);
int crc8(const unsigned char *data, int len);
int validate_crc(const unsigned char *data, int len);
int read_sensor_data(int handle, float *temperature, float *humidity);
int log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C bus
int open_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to write data to I2C
int write_i2c(int handle, int count, char *data) {
    int result = i2cWriteDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from I2C
int read_i2c(int handle, int count, char *data) {
    int result = i2cReadDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 calculation function
int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC-8
int validate_crc(const unsigned char *data, int len) {
    unsigned char crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// Function to read sensor data
int read_sensor_data(int handle, float *temperature, float *humidity) {
    char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    char data[6];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (write_i2c(handle, 2, command) == 0) {
            gpioDelay(15); // Wait for measurement (at least 15ms)
            if (read_i2c(handle, 6, data) == 0) {
