int open_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to write data to I2C
int write_i2c(int handle, int count, char *data) {
    int result = i2cWriteDevice(handle, data, count);
    if (result != count) {
