#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define ADPD105 I2C addresses
#define ADPD105_ADDR1 0x38
#define ADPD105_ADDR2 0x39

// Define ADPD105 register addresses (Example - adjust based on datasheet)
#define ADPD105_REG_LED_DRIVE 0x00
#define ADPD105_REG_INT_TIME 0x01
#define ADPD105_REG_DATA_HIGH 0x02
#define ADPD105_REG_DATA_LOW 0x03
#define ADPD105_REG_CCT_HIGH 0x04
#define ADPD105_REG_CCT_LOW 0x05

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue);
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue);
int log_cct_data(float cct1, float cct2);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int i2c_address;
    int i2c_handle;
} sensor_config_t;

// Function to initialize the ADPD105 sensor
int initialize_sensor(int i2c_handle) {
    // Example initialization sequence (adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, ADPD105_REG_LED_DRIVE, 0x0A) < 0) { // Example: Set LED drive current
        fprintf(stderr, "Error writing to LED_DRIVE register: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ADPD105_REG_INT_TIME, 0x10) < 0) { // Example: Set integration time
        fprintf(stderr, "Error writing to INT_TIME register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data (Red, Green, Blue)
int read_sensor_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buffer[6]; // 2 bytes for each color (Red, Green, Blue)

    if (i2cReadI2CBlockData(i2c_handle, ADPD105_REG_DATA_HIGH, buffer, 6) < 0) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    *red = (uint16_t)((buffer[0] << 8) | buffer[1]);
    *green = (uint16_t)((buffer[2] << 8) | buffer[3]);
    *blue = (uint16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate Correlated Color Temperature (CCT)
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    // Implement CCT calculation algorithm here (e.g., McCamy's approximation)
    // This is a placeholder - replace with a proper algorithm
    float x = (float)red / (float)(red + green + blue);
    float y = (float)green / (float)(red + green + blue);

    float n = (x - 0.3320) / (0.1858 - y);
    float cct = 449.0 * pow(n, 3) + 3525.0 * pow(n, 2) + 6823.3 * n + 5520.33;

    return cct;
}

// Function to log CCT data to a CSV file
int log_cct_data(float cct1, float cct2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, cct1, cct2);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle1 = i2cOpen(1, ADPD105_ADDR1, 0); // Bus 1, address 0x38, no flags
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(1, ADPD105_ADDR2, 0); // Bus 1, address 0x39, no flags
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (initialize_sensor(i2c_handle1) < 0) {
        fprintf(stderr, "Error initializing sensor 1.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle2) < 0) {
        fprintf(stderr, "Error initializing sensor 2.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("cct_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, add the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }
    rewind(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        uint16_t red1, green1, blue1, red2, green2, blue2;
        float cct1, cct2, avg_cct;

        // Read sensor data from sensor 1
        if (read_sensor_data(i2c_handle1, &red1, &green1, &blue1) == 0) {
            // Calculate CCT for sensor 1
            cct1 = calculate_cct(red1, green1, blue1);
        } else {
            cct1 = -1.0; // Indicate error
        }

        // Read sensor data from sensor 2
        if (read_sensor_data(i2c_handle2, &red2, &green2, &blue2) == 0) {
            // Calculate CCT for sensor 2
            cct2 = calculate_cct(red2, green2, blue2);
        } else {
            cct2 = -1.0; // Indicate error
        }

        // Calculate average CCT
        if (cct1 >= 0.0 && cct2 >= 0.0) {
            avg_cct = (cct1 + cct2) / 2.0;
        } else {
            avg_cct = -1.0; // Indicate error
        }

        // Log data
        if (log_cct_data(cct1, cct2) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Print average CCT to console
        printf("Average CCT: %.2f K\n", avg_cct);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

