        if (read_sensor_data(&sensor_data) == 0) {
            // Get timestamp
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                // Log data
                if (log_data(sensor_data, timestamp) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        } else {
            // Get timestamp for error logging
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                fprintf(log_file, "%s,ERROR,Failed to read sensor data\n", timestamp);
                fflush(log_file);
                free(timestamp);
            } else {
                fprintf(stderr, "Error getting timestamp for error logging\n");
            }
        }

        // Wait for the next read interval
        gpioDelay(READ_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

