#include <string.h>
#include <unistd.h>

// HDC1080 I2C address
#define HDC1080_ADDR 0x40

// HDC1080 register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x01
#define CONFIGURATION_REG 0x02

// Configuration register values
#define CONFIGURATION_DEFAULT 0x0000 // Temperature and Humidity, 14-bit resolution, 1 Hz

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_hdc1080(float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure HDC1080 (optional, but recommended)
    char config_data[2];
    config_data[0] = CONFIGURATION_REG;
    config_data[1] = (CONFIGURATION_DEFAULT >> 8) & 0xFF; // MSB
    if (i2cWriteI2CBlockData(i2c_handle, config_data[0], config_data + 1, 1) != 0) {
        fprintf(stderr, "Error writing to configuration register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read temperature and humidity from HDC1080
int read_hdc1080(float *temperature, float *humidity) {
    char trigger_data[1] = {0x00}; // Trigger measurement
    char read_data[4];

    // Trigger measurement
    if (i2cWriteI2CBlockData(i2c_handle, TEMPERATURE_REG, trigger_data, 0) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for conversion (at least 20ms)
    gpioDelay(20000); // 20ms

    // Read temperature and humidity data
    if (i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, read_data, 4) != 4) {
        fprintf(stderr, "Error reading data\n");
        return -1;
    }

    // Convert data
    uint16_t raw_temperature = (read_data[0] << 8) | read_data[1];
    uint16_t raw_humidity = (read_data[2] << 8) | read_data[3];

    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

// Log data to file
void log_data(float temperature, float humidity) {
    FILE *fp = fopen("enviro_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    time_t last_log_time = 0;

    // Main loop
    while (!terminate) {
        if (read_hdc1080(&temperature, &humidity) == 0) {
            time_t current_time = time(NULL);
            if (current_time - last_log_time >= 5) {
                log_data(temperature, humidity);
                last_log_time = current_time;
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping log entry\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Close I2C and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

