#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define STS40_ADDR 0x4A
#define MEASURE_HIGH_REP 0x2C06
#define LOG_FILE "temperature_log.txt"

int i2c_fd = -1;
FILE *log_file = NULL;

// CRC8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS40
float read_temperature() {
    unsigned char cmd[2] = {(MEASURE_HIGH_REP >> 8) & 0xFF, MEASURE_HIGH_REP & 0xFF};
    unsigned char data[3];
    int result;

    result = i2cWriteDevice(i2c_fd, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1000.0; // Indicate error
    }

    gpioDelay(10); // Wait for conversion

    result = i2cReadDevice(i2c_fd, (char *)data, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1000.0; // Indicate error
    }

    unsigned char crc = crc8(data, 2);
    if (crc != data[2]) {
        fprintf(stderr, "CRC check failed!\n");
        return -1000.0; // Indicate error
    }

    int temp_raw = (data[0] << 8) | data[1];
    return -45.0 + (175.0 * temp_raw) / 65535.0;
}

// Function to log temperature with timestamp
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, STS40_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }
        sleep(5);
    }

    return 0; // This line will not be reached due to the infinite loop
}

