#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

// SCD40 I2C address
#define SCD40_I2C_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// CRC-8 polynomial and initial value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Structure for circular buffer
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t running = 1;
pthread_t logging_thread;
FILE *error_log_file;

// Function prototypes
int crc8(const unsigned char *data, int len);
int read_scd40_data(sensor_data_t *data);
void buffer_init(circular_buffer_t *buffer);
int buffer_add(circular_buffer_t *buffer, sensor_data_t data);
int buffer_get(circular_buffer_t *buffer, int index, sensor_data_t *data);
void *logging_thread_func(void *arg);
void signal_handler(int signal);
int write_data_to_csv(const char *filename);
int create_log_directory();

// CRC-8 calculation function
int crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC8_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SCD40 sensor
int read_scd40_data(sensor_data_t *data) {
    unsigned char buffer[9];
    int result;

    // Send read measurement command
    unsigned char cmd[2] = {(CMD_READ_MEASUREMENT >> 8) & 0xFF, CMD_READ_MEASUREMENT & 0xFF};
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        log_error("Failed to write read measurement command");
        return -1;
    }

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        log_error("Failed to read measurement data");
        return -1;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5] || crc8(buffer + 6, 2) != buffer[8]) {
        log_error("CRC validation failed");
        return -1;
    }

    // Convert data to float values
    data->co2 = (float)((buffer[0] << 8) | buffer[1]);
    data->temperature = -45 + 175 * ((float)((buffer[3] << 8) | buffer[4])) / 65535;
    data->humidity = 100 * ((float)((buffer[6] << 8) | buffer[7])) / 65535;

    return 0;
}

// Initialize circular buffer
void buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Add data to circular buffer
int buffer_add(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Get data from circular buffer
int buffer_get(circular_buffer_t *buffer, int index, sensor_data_t *data) {
    if (index < 0 || index >= buffer->count) {
        return -1; // Invalid index
    }

    pthread_mutex_lock(&buffer->mutex);
    int actual_index = (buffer->tail + index) % BUFFER_SIZE;
    *data = buffer->data[actual_index];
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Logging thread function
void *logging_thread_func(void *arg) {
    while (running) {
        sleep(60);
        pthread_mutex_lock(&buffer.mutex);
        int count = buffer.count;
        pthread_mutex_unlock(&buffer.mutex);

        if (count > 0) {
            char filename[256];
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            sprintf(filename, "/var/log/scd40_data/scd40_data_%04d%02d%02d_%02d%02d%02d.csv", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);

            FILE *fp = fopen(filename, "w");
            if (fp == NULL) {
                log_error("Failed to open CSV file for writing");
                continue;
            }

            fprintf(fp, "CO2,Temperature,Humidity\n");
            pthread_mutex_lock(&buffer.mutex);
            for (int i = 0; i < count; i++) {
                sensor_data_t data;
                buffer_get(&buffer, i, &data);
                fprintf(fp, "%.2f,%.2f,%.2f\n", data.co2, data.temperature, data.humidity);
            }
            pthread_mutex_unlock(&buffer.mutex);
            fclose(fp);
        }
    }
    pthread_exit(NULL);
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Log error message to file
void log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(error_log_file, "%04d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(error_log_file);
}

// Write data to CSV file
int write_data_to_csv(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        log_error("Failed to open CSV file for appending");
        return -1;
    }

    pthread_mutex_lock(&buffer.mutex);
    int count = buffer.count;
    pthread_mutex_unlock(&buffer.mutex);

    for (int i = 0; i < count; i++) {
        sensor_data_t data;
        pthread_mutex_lock(&buffer.mutex);
        buffer_get(&buffer, i, &data);
        pthread_mutex_unlock(&buffer.mutex);
        fprintf(fp, "%.2f,%.2f,%.2f\n", data.co2, data.temperature, data.humidity);
    }

    fclose(fp);
    return 0;
}

// Create log directory if it doesn't exist
int create_log_directory() {
    if (mkdir("/var/log/scd40_data", 0777) == -1) {
        if (errno != EEXIST) {
            perror("Failed to create log directory");
            return -1;
        }
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create error log file
    error_log_file = fopen("/var/log/scd40_error.log", "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create log directory
    if (create_log_directory() != 0) {
        fclose(error_log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    buffer_init(&buffer);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Start periodic measurement
    unsigned char cmd_start[2] = {(CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_START_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd_start, 2);
    if (result != 0) {
        log_error("Failed to start periodic measurement");
        fclose(error_log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait 1 second

    // Create logging thread
    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        fclose(error_log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    sensor_data_t data;
    while (running) {
        if (read_scd40_data(&data) == 0) {
            buffer_add(&buffer, data);
        } else {
            log_error("Failed to read sensor data");
        }
        sleep(5);
    }

    // Stop periodic measurement
    unsigned char cmd_stop[2] = {(CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_STOP_PERIODIC_MEASUREMENT & 0xFF};
    result = i2cWriteDevice(i2c_handle, (char *)cmd_stop, 2);
    if (result != 0) {
        log_error("Failed to stop periodic measurement");
    }

    // Join logging thread
    pthread_join(logging_thread, NULL);

    // Write remaining data to CSV file
    char filename[256];
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    sprintf(filename, "/var/log/scd40_data/scd40_data_final_%04d%02d%02d_%02d%02d%02d.csv", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
    write_data_to_csv(filename);

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(error_log_file);

    return 0;
}

