#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C address of the ICP-10110 sensor
#define ICP10110_ADDR 0x69

// Define the register addresses for pressure and temperature
#define ICP10110_PRESSURE_REG 0x00
#define ICP10110_TEMPERATURE_REG 0x03

// Define the command to trigger a measurement
#define ICP10110_MEASURE_CMD 0x07

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int addr);
int trigger_measurement(int handle);
int read_sensor_data(int handle, uint8_t *data);
sensor_data_t process_sensor_data(uint8_t *data);
char *format_data(sensor_data_t data);
void write_to_file(char *data);
void signal_handler(int signal);
void cleanup();

// Initialize the pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open the I2C bus
int open_i2c_bus(int addr) {
    int handle = i2cOpen(1, addr, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Trigger a measurement on the sensor
int trigger_measurement(int handle) {
    int result = i2cWriteByteData(handle, ICP10110_MEASURE_CMD, 0x00); // Command to trigger measurement
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the I2C bus
int read_sensor_data(int handle, uint8_t *data) {
    int result = i2cReadI2CBlockData(handle, ICP10110_PRESSURE_REG, (char *)data, 6); // Read 6 bytes
    if (result < 0) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Process the raw sensor data
sensor_data_t process_sensor_data(uint8_t *data) {
    sensor_data_t sensor_data;
    // Extract raw pressure and temperature values from the data buffer
    int32_t raw_pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    int32_t raw_temperature = (data[3] << 16) | (data[4] << 8) | data[5];

    // Convert raw values to pressure (hPa) and temperature (°C) - Example conversion (replace with actual datasheet values)
    sensor_data.pressure = (float)raw_pressure / 100.0; // Example conversion
    sensor_data.temperature = (float)raw_temperature / 100.0; // Example conversion

    return sensor_data;
}

