int calculate_crc(const uint8_t *data, int len, uint8_t *crc) {
    uint8_t crc_calculated = 0;
    for (int i = 0; i < len; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ 0x31;
            } else {
                crc_calculated <<= 1;
            }
        }
    }
    *crc = crc_calculated;
    return 0;
}

