        gpioDelay(500); // 500ms on
        gpioWrite(GPIO_LED, 0);
        gpioDelay(500); // 500ms off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

