#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 30.0
#define TEMP_THRESHOLD_OFF 28.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature(int handle, int reg);
void control_fan(float object_temp);
void log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Function to read temperature from the sensor
float read_temperature(int handle, int reg) {
    int raw_temp;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        raw_temp = i2cReadWordData(handle, reg);
        if (raw_temp >= 0) {
            // Success
            return (float)raw_temp * 0.02 - 273.15;
        } else {
            // Error, retry
            fprintf(stderr, "Error reading temperature (reg 0x%02X): %d, retrying...\n", reg, raw_temp);
            gpioDelay(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
    return -273.15; // Return absolute zero as error indicator
}

// Function to control the cooling fan
void control_fan(float object_temp) {
    static int fan_on = 0;

    if (object_temp > TEMP_THRESHOLD_ON && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Object Temp: %.2f°C)\n", object_temp);
    } else if (object_temp < TEMP_THRESHOLD_OFF && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Object Temp: %.2f°C)\n", object_temp);
    }
}

// Function to log temperature data to a file
void log_temperature(float ambient_temp, float object_temp) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("temperature_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature_log.txt for writing!\n");
        return;
    }

    fprintf(fp, "%s, Ambient: %.2f°C, Object: %.2f°C\n", timestamp, ambient_temp, object_temp);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is initially off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float ambient_temp = read_temperature(i2c_handle, AMBIENT_TEMP_REG);
        float object_temp = read_temperature(i2c_handle, OBJECT_TEMP_REG);

        if (ambient_temp > -273.0 && object_temp > -273.0) {
            control_fan(object_temp);
            log_temperature(ambient_temp, object_temp);
        } else {
            fprintf(stderr, "Invalid temperature reading, skipping logging.\n");
        }

        gpioDelay(2000000); // Wait 2 seconds (2000000 microseconds)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

