#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
int server_fd;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sht40(int i2c_handle, float *temperature, float *humidity);
int clamp_humidity(float humidity);
int create_html_page(float temperature, float humidity, char *html_page);
int start_server(int port);
void handle_client(int client_socket);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Function to read data from SHT40 sensor
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    unsigned char data[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        // Send measurement command
        result = i2cWriteByte(i2c_handle, MEASURE_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d\n", result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(10000); // Wait 10ms

        // Read 6 bytes of data
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading from I2C: %d\n", result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Convert data to temperature and humidity
        unsigned short temperature_raw = (data[0] << 8) | data[1];
        unsigned short humidity_raw = (data[3] << 8) | data[4];

        *temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
        *humidity = 100.0 * (float)humidity_raw / 65535.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to clamp humidity to 0-100%
int clamp_humidity(float humidity) {
    if (humidity < 0.0) {
        humidity = 0.0;
    } else if (humidity > 100.0) {
        humidity = 100.0;
    }
    return 0; // Indicate success
}

// Function to create an HTML page
int create_html_page(float temperature, float humidity, char *html_page) {
    char temp_str[20], humidity_str[20];
    snprintf(temp_str, sizeof(temp_str), "%.2f", temperature);
    snprintf(humidity_str, sizeof(humidity_str), "%.2f", humidity);

    snprintf(html_page, 256, 
             "HTTP/1.1 200 OK\r\n" 
             "Content-Type: text/html\r\n" 
             "Connection: close\r\n" 
             "\r\n" 
             "<!DOCTYPE html><html><head><title>SHT40 Sensor</title></head><body>" 
             "<h1>SHT40 Sensor Data</h1>" 
             "<p>Temperature: %s &deg;C</p>" 
             "<p>Humidity: %s %%</p>" 
             "</body></html>", 
             temp_str, humidity_str);
    return 0;
}

// Function to start the HTTP server
int start_server(int port) {
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    // Forcefully attaching socket to the port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        return -1;
    }
    printf("Server listening on port %d\n", port);
    return 0;
}

// Function to handle client connections
void handle_client(int client_socket) {
    char html_page[256];
    float temperature, humidity;

    // Read sensor data
    if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
        // Clamp humidity
        clamp_humidity(humidity);

        // Create HTML page
        create_html_page(temperature, humidity, html_page);

        // Send response to client
        send(client_socket, html_page, strlen(html_page), 0);
    } else {
        // Error reading sensor data
        const char *error_page = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\nConnection: close\r\n\r\n<h1>Internal Server Error</h1>";
        send(client_socket, error_page, strlen(error_page), 0);
    }

    close(client_socket);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start the server
    if (start_server(PORT) != 0) {
        fprintf(stderr, "Failed to start server\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    struct sockaddr_in client_address;
    int client_socket, addrlen = sizeof(client_address);
    while (!terminate) {
        // Accept incoming connection
        client_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&addrlen);
        if (client_socket < 0) {
            perror("accept");
            continue; // Continue listening for connections
        }

        // Handle the client
        handle_client(client_socket);
    }

    // Clean up
    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return 0;
}

