#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define CSV_FILE "temperature_log.csv"
#define SLEEP_DURATION 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_temperature();
char* format_timestamp();
int write_to_csv(const char* timestamp, float temperature);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int tmp102_address;
    const char* csv_filename;
    int sleep_duration;
} Config;

Config config = {I2C_BUS, TMP102_ADDR, CSV_FILE, SLEEP_DURATION};

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.tmp102_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read temperature from TMP102
float read_temperature() {
    int raw_data = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    // Convert raw data to Celsius (see TMP102 datasheet)
    float temperature = (float)((int16_t)raw_data >> 4) * 0.0625;
    return temperature;
}

// Format timestamp
char* format_timestamp() {
    time_t now = time(NULL);
    struct tm *tstruct;
    char *buf = malloc(20 * sizeof(char)); // Allocate memory for the timestamp string
    if (buf == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }
    tstruct = localtime(&now);
    strftime(buf, 20, "%Y-%m-%d %H:%M:%S", tstruct);
    return buf;
}

// Write to CSV file
int write_to_csv(const char* timestamp, float temperature) {
    FILE *fp = fopen(config.csv_filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for read error
            // Format timestamp
            char* timestamp = format_timestamp();
            if (timestamp != NULL) {
                // Write to CSV file
                if (write_to_csv(timestamp, temperature) != 0) {
                    fprintf(stderr, "Error writing to CSV file\n");
                }
                free(timestamp); // Free allocated memory
            } else {
                fprintf(stderr, "Error formatting timestamp\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping log entry\n");
        }

        // Sleep for 5 seconds
        sleep(config.sleep_duration);
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

