            if (status_result != 1) {
                fprintf(stderr, "Error reading status from MEASUREMENT_CONFIG register: %d\n", status_result);
                retry_count++;
                gpioDelay(100); // Wait 100ms before retrying
                continue;
            }

            if ((status_data[0] & 0x01) == 0) {
                // Measurement is ready
                if (read_hdc2010(&temperature, &humidity) == 0) {
                    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
                    break; // Exit retry loop
                } else {
                    fprintf(stderr, "Error reading temperature/humidity data\n");
                    retry_count++;
                    gpioDelay(100); // Wait 100ms before retrying
                }
            } else {
                // Measurement not ready, wait 100ms
                gpioDelay(100);
            }
        }

        if (retry_count == 3) {
            fprintf(stderr, "Failed to read temperature/humidity after 3 retries\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Clean shutdown
    printf("Shutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

