#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x362F
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SLEEP_MS 500

// CRC-8 checksum calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP800 sensor
int read_sdp800(int i2c_handle, int16_t *pressure, int16_t *temperature) {
    uint8_t data[6];
    int result;

    // Send measurement command
    uint8_t command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    for (int i = 0; i < RETRY_COUNT; i++) {
        result = i2cWriteDevice(i2c_handle, (char *)command, 2);
        if (result == 0) break; // Success
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(45000); // Wait for measurement (45ms)

    // Read 6 bytes of data
    for (int i = 0; i < RETRY_COUNT; i++) {
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) break; // Success
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }
    if (result != 6) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // CRC validation
    uint8_t pressure_crc = crc8(data, 2);
    uint8_t temperature_crc = crc8(data + 3, 2);

    if (pressure_crc != data[2] || temperature_crc != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data to signed integers
    *pressure = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (int16_t)((data[3] << 8) | data[4]);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    int i2c_handle;
    int16_t pressure, temperature;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SLEEP_MS * 1000000; // 500ms

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (read_sdp800(i2c_handle, &pressure, &temperature) == 0) {
            printf("Pressure: %d Pa, Temperature: %d °C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

