#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0 // CE0
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_RELAY 17
#define TARGET_PROFILE_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define MAX_RETRIES 3

// PID Gains
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for target temperature profile
typedef struct {
    int time_seconds;
    float target_temp_celsius;
} TargetProfile;

// Function Prototypes
int initialize();
float read_temperature();
float calculate_pid(float setpoint, float actual_temp, float *integral, float *previous_error);
void set_relay_duty_cycle(float duty_cycle);
void log_data(float temperature, float setpoint, float pid_output, float duty_cycle);
void load_target_profile(TargetProfile *profile, int *profile_size);
void signal_handler(int signal);
void cleanup();

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initially off

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_celsius,setpoint_celsius,pid_output,duty_cycle\n");
    }

    return 0;
}

// Function to read temperature from MAX6675
float read_temperature() {
    unsigned char buffer[4];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        bytes_read = spiRead(spi_handle, buffer, 4);
        if (bytes_read == 4) {
            // Extract temperature data (bits 3-14 of the second byte)
            int raw_temp = ((buffer[1] << 8) | buffer[2]) >> 2;
            float temperature = raw_temp * 0.25;
            return temperature;
        } else {
            fprintf(stderr, "SPI read failed (attempt %d): %d bytes read\n", retries + 1, bytes_read);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "MAX6675 read failed after %d retries\n", MAX_RETRIES);
    return -273.15; // Return absolute zero as error value
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temp, float *integral, float *previous_error) {
    float error = setpoint - actual_temp;
    *integral += error;
    float derivative = error - *previous_error;
    float pid_output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return pid_output;
}

// Function to set the solid-state relay duty cycle
void set_relay_duty_cycle(float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;

    // Assuming a simple on/off control for demonstration
    if (duty_cycle > 0.5) {
        gpioWrite(GPIO_RELAY, 1); // Turn on
    } else {
        gpioWrite(GPIO_RELAY, 0); // Turn off
    }
}

// Function to log data to file
void log_data(float temperature, float setpoint, float pid_output, float duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, temperature, setpoint, pid_output, duty_cycle);
    fflush(log_file); // Ensure data is written to disk
}

// Function to load target temperature profile from file
void load_target_profile(TargetProfile *profile, int *profile_size) {
    FILE *fp = fopen(TARGET_PROFILE_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open target profile file\n");
        *profile_size = 0; // Indicate no profile loaded
        return;
    }

    *profile_size = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%d,%f", &profile[*profile_size].time_seconds, &profile[*profile_size].target_temp_celsius) == 2) {
            (*profile_size)++;
            if (*profile_size >= 100) { // Limit profile size to prevent excessive memory allocation
                fprintf(stderr, "Warning: Target profile size limit reached\n");
                break;
            }
        } else {
            fprintf(stderr, "Invalid line in target profile file: %s", line);
        }
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    gpioWrite(GPIO_RELAY, 0); // Turn off relay
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    TargetProfile target_profile[100]; // Array to hold the target temperature profile
    int profile_size = 0;
    load_target_profile(target_profile, &profile_size);

    if (profile_size == 0) {
        fprintf(stderr, "No target temperature profile loaded. Using default setpoint of 100.0°C\n");
    }

    float setpoint = 100.0; // Default setpoint
    int current_profile_index = 0;

    float integral = 0.0;
    float previous_error = 0.0;
    float pid_output;
    float duty_cycle;
    float temperature;

    time_t last_profile_update = time(NULL);

    while (!terminate) {
        // Update setpoint based on target profile
        time_t now = time(NULL);
        if (now - last_profile_update >= 1) { // Check every second
            if (current_profile_index < profile_size) {
                setpoint = target_profile[current_profile_index].target_temp_celsius;
                current_profile_index++;
            } else {
                setpoint = 100.0; // Reset to default setpoint if profile is complete
            }
            last_profile_update = now;
        }

        // Read temperature
        temperature = read_temperature();
        if (temperature < -200.0) { // Error reading temperature
            fprintf(stderr, "Error reading temperature, using previous value\n");
            // Consider implementing a more robust error handling strategy here
            // such as using a moving average or a last known good value.
            continue; // Skip to the next iteration
        }

        // Calculate PID output
        pid_output = calculate_pid(setpoint, temperature, &integral, &previous_error);

        // Scale PID output to duty cycle (0.0 - 1.0)
        duty_cycle = pid_output / 100.0; // Assuming PID output range of 0-100

        // Set relay duty cycle
        set_relay_duty_cycle(duty_cycle);

        // Log data
        log_data(temperature, setpoint, pid_output, duty_cycle);

        gpioDelay(1000); // 1 Hz loop
    }

    cleanup();
    return 0;
}

