    // Construct the w1_slave file path
    char w1_slave_path[128];
    snprintf(w1_slave_path, sizeof(w1_slave_path), "/sys/bus/w1/devices/%s/w1_slave", sensor_id);

    // Open the w1_slave file
    fp = fopen(w1_slave_path, "r");
    if (fp == NULL) {
        perror("Error opening w1_slave file");
        return -1000.0;
    }

    // Read the file
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Error reading w1_slave file");
        fclose(fp);
        return -1000.0;
    }
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Error reading w1_slave file");
        fclose(fp);
        return -1000.0;
    }
    fclose(fp);

    // Check for CRC error
    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "CRC check failed\n");
        return -1000.0;
    }

    // Extract temperature
    sscanf(buffer, "t=%f", &temperature);

    return temperature;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature) {
    float error = setpoint - actual_temperature;
    integral += error;
    float derivative = error - last_error;
    float output = kp * error + ki * integral + kd * derivative;
    last_error = error;

    // Clamp the output to a reasonable range
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    return output;
}

