void set_pwm_duty_cycle(int duty_cycle) {
    gpioPWM(PWM_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(float average_temperature, float setpoint, float pid_output, int pwm_duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

