void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// CRC-8 checksum calculation
int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x18;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc < 5) {
        fprintf(stderr, "Usage: %s <setpoint> <kp> <ki> <kd>\n", argv[0]);
        return 1;
    }

    setpoint = atof(argv[SETPOINT_ARG_INDEX]);
    kp = atof(argv[KP_ARG_INDEX]);
    ki = atof(argv[KI_ARG_INDEX]);
    kd = atof(argv[KD_ARG_INDEX]);

