    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        float temperature1 = read_temperature();
        float temperature2 = read_temperature();
        float temperature3 = read_temperature();

        if (temperature1 < -900 || temperature2 < -900 || temperature3 < -900) {
            fprintf(stderr, "Error reading temperature from sensor\n");
        } else {
            float average_temperature = (temperature1 + temperature2 + temperature3) / 3.0;

            float pid_output = calculate_pid(setpoint, average_temperature);

            set_pwm_duty_cycle((int)(pid_output * PWM_RANGE / 100.0));
            pwm_duty_cycle = (int)(pid_output * PWM_RANGE / 100.0);

            // Control relay based on PWM duty cycle
            if (pwm_duty_cycle > 0) {
                set_heater_state(1); // Turn on relay
            } else {
                set_heater_state(0); // Turn off relay
            }

            log_data(average_temperature, setpoint, pid_output, pwm_duty_cycle);
        }

        sleep(5);
    }

    // Cleanup
    set_heater_state(0); // Turn off heater
    set_pwm_duty_cycle(0); // Set PWM to 0
    close(i2c_fd);
    fclose(log_fp);
    gpioTerminate();

    return 0;
}

