#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define GPIO_RELAY 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define MEASUREMENT_DELAY_MS 80
#define POLLING_INTERVAL_S 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_init();
int aht20_read_humidity(float *humidity);
void control_relay(float humidity);
void log_data(float humidity);
void signal_handler(int signal);

// AHT20 Initialization Sequence
int aht20_init() {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    int result = i2cWriteDevice(i2c_handle, init_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error: AHT20 initialization failed (write): %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait for initialization to complete
    return 0;
}

// AHT20 Data Reading and Humidity Calculation
int aht20_read_humidity(float *humidity) {
    char trigger_cmd[3] = {0xAC, 0x33, 0x00};
    char data[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, trigger_cmd, 3);
        if (result != 0) {
            fprintf(stderr, "Error: AHT20 trigger failed (write): %d\n", result);
            gpioDelay(RETRY_DELAY_MS);
            retries++;
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_MS);

        result = i2cReadDevice(i2c_handle, data, 6);
        if (result != 6) {
            fprintf(stderr, "Error: AHT20 read failed (read %d bytes): %d\n", result, result);
            gpioDelay(RETRY_DELAY_MS);
            retries++;
            continue;
        }

        // Check status byte
        uint8_t status = data[0];
        if (!(status & 0x80) || (status & 0x01)) {
            fprintf(stderr, "Error: AHT20 busy or not calibrated (status: 0x%02X)\n", status);
            gpioDelay(RETRY_DELAY_MS);
            retries++;
            continue;
        }

        // Calculate humidity
        uint32_t raw_humidity = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
        *humidity = ((float)raw_humidity / 0x100000) * 100;

        return 0; // Success
    }

    fprintf(stderr, "Error: AHT20 read failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Relay Control Logic
void control_relay(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(GPIO_RELAY, 1); // Activate relay
        printf("Relay activated (Humidity: %.2f%%)\n", humidity);
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(GPIO_RELAY, 0); // Deactivate relay
        printf("Relay deactivated (Humidity: %.2f%%)\n", humidity);
    }
}

// Data Logging
void log_data(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("%s - Humidity: %.2f%%\n", timestamp, humidity);
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

