void control_relay(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(GPIO_RELAY, 1); // Activate relay
        printf("Relay activated (Humidity: %.2f%%)\n", humidity);
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(GPIO_RELAY, 0); // Deactivate relay
        printf("Relay deactivated (Humidity: %.2f%%)\n", humidity);
    }
}

// Data Logging
void log_data(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("%s - Humidity: %.2f%%\n", timestamp, humidity);
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (aht20_init() != 0) {
        fprintf(stderr, "Error: AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float humidity;

    // Main loop
    while (!terminate) {
        if (aht20_read_humidity(&humidity) == 0) {
            log_data(humidity);
            control_relay(humidity);
        } else {
            fprintf(stderr, "Error: Failed to read humidity\n");
        }

        gpioDelay(POLLING_INTERVAL_S * 1000); // Poll every 5 seconds
    }

    // Cleanup
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

