#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define HTU21D_ADDR 0x40
#define HUMIDITY_CMD 0xE5
#define API_ENDPOINT "http://api.example.com/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_humidity(int i2c_handle, float *humidity);
int post_humidity(float humidity);
void signal_handler(int signal);
int crc8(const unsigned char *data, int len);

// CRC-8 calculation function
int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read humidity from HTU21D sensor
int read_humidity(int i2c_handle, float *humidity) {
    unsigned char buf[3];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, HUMIDITY_CMD);
        if (result != 0) {
            syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        gpioDelay(50); // Wait for measurement

        result = i2cReadDevice(i2c_handle, (char *)buf, 3);
        if (result != 3) {
            syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        // CRC check
        unsigned char data[2] = {buf[0], buf[1]};
        int crc_calculated = crc8(data, 2);
        if (crc_calculated != buf[2]) {
            syslog(LOG_ERR, "CRC mismatch: calculated 0x%02X, received 0x%02X", crc_calculated, buf[2]);
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        // Convert raw data to humidity
        unsigned int raw_humidity = (buf[0] << 8) | buf[1];
        *humidity = -6.0 + 125.0 * ((float)raw_humidity / 65536.0);
        if (*humidity < 0.0) *humidity = 0.0;
        if (*humidity > 100.0) *humidity = 100.0;

        return 0; // Success
    }

    syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
    return -1; // Failure
}

// Function to post humidity data to the API endpoint
int post_humidity(float humidity) {
    int sockfd;
    struct sockaddr_in servaddr;
    char json_data[50];
    char url[256];
    char *token = NULL;
    char *rest_of_url = NULL;
    int token_len = 0;

    // Parse URL to extract host and path
    token = strtok_r(API_ENDPOINT, "/", &rest_of_url);
    if (token == NULL) {
        syslog(LOG_ERR, "Invalid API endpoint URL");
        return -1;
    }
    token_len = strlen(token);
    strncpy(url, token, sizeof(url) - 1);
    url[token_len] = '\0';
    strcat(url, "/humidity"); // Append the path

    // Create JSON data
    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80); // HTTP port

    // Resolve hostname
    if (inet_pton(AF_INET, url, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Send HTTP POST request
    char request[512];
    snprintf(request, sizeof(request), "POST /%s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %ld\r\n\r\n%s",
             rest_of_url, url, strlen(json_data), json_data);

    if (send(sockfd, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Receive response
    char response[1024];
    memset(response, 0, sizeof(response));
    ssize_t bytes_received = recv(sockfd, response, sizeof(response) - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "Receive failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    syslog(LOG_INFO, "HTTP POST response: %s", response);

    close(sockfd);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    float humidity;

    // Initialize syslog
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HTU21D_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Humidity monitor started");

    // Main loop
    while (!terminate) {
        if (read_humidity(i2c_handle, &humidity) == 0) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (post_humidity(humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        sleep(60);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    syslog(LOG_INFO, "Humidity monitor stopped");
    return 0;
}

