#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define I2C_BUS 1
#define MOTION_LOG_FILE "motion_log.csv"
#define DATA_LOG_FILE "data_log.csv"
#define RETRY_COUNT 3
#define BACKOFF_DELAY_MS 10
#define MOTION_LOG_INTERVAL_SEC 5

// Global variables
int i2c_handle_tmp117 = -1;
int i2c_handle_aht20 = -1;
FILE *data_log_fp = NULL;
FILE *motion_log_fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int read_tmp117(int handle, float *temperature);
int read_aht20(int handle, float *humidity);
int read_pir_sensor(int gpio);
int log_data(FILE *fp, float temperature, float humidity, int motion_detected);
int log_motion(FILE *fp, int motion_detected);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read temperature from TMP117
int read_tmp117(int handle, float *temperature) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(handle, buf, 2);
        if (result == 2) {
            // Convert raw data to temperature (Celsius)
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            *temperature = raw_temp * 0.0078125;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading TMP117 (attempt %d): %d\n", retries + 1, result);
            gpioDelay(BACKOFF_DELAY_MS * 1000); // Convert ms to microseconds
            retries++;
        }
    }
    return -1; // Failure after retries
}

// Function to read humidity from AHT20
int read_aht20(int handle, float *humidity) {
    char buf[6];
    int result;
    int retries = 0;

    // Trigger measurement (refer to AHT20 datasheet)
    char trigger_cmd[3] = {0xAC, 0x33, 0x00};
    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(handle, trigger_cmd, 3);
        if (result == 3) {
            gpioDelay(80); // Wait for measurement (datasheet specifies 75ms)

            while (retries < RETRY_COUNT) {
                result = i2cReadDevice(handle, buf, 6);
                if (result == 6) {
                    // Check status bit (bit 7 of byte 0)
                    if (buf[0] & 0x80) {
                        // Convert raw data to humidity
                        uint32_t raw_humidity = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | ((uint32_t)buf[3] >> 4);
                        *humidity = ((float)raw_humidity / 0x100000) * 100;
                        return 0; // Success
                    } else {
                        fprintf(stderr, "AHT20 busy (attempt %d)\n", retries + 1);
                        gpioDelay(BACKOFF_DELAY_MS * 1000); // Convert ms to microseconds
                        retries++;
                    }
                } else {
                    fprintf(stderr, "Error reading AHT20 (attempt %d): %d\n", retries + 1, result);
                    gpioDelay(BACKOFF_DELAY_MS * 1000); // Convert ms to microseconds
                    retries++;
                }
            }
            return -1; // Failure after retries
        } else {
            fprintf(stderr, "Error triggering AHT20 (attempt %d): %d\n", retries + 1, result);
            gpioDelay(BACKOFF_DELAY_MS * 1000); // Convert ms to microseconds
            retries++;
        }
    }
    return -1; // Failure after retries
}

// Function to read PIR sensor
int read_pir_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log data to CSV file
int log_data(FILE *fp, float temperature, float humidity, int motion_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected) < 0) {
        fprintf(stderr, "Error writing to data log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Function to log motion events to CSV file
int log_motion(FILE *fp, int motion_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%d\n", timestamp, motion_detected) < 0) {
        fprintf(stderr, "Error writing to motion log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle_tmp117 >= 0) {
        i2cClose(i2c_handle_tmp117);
    }
    if (i2c_handle_aht20 >= 0) {
        i2cClose(i2c_handle_aht20);
    }
    if (data_log_fp != NULL) {
        fclose(data_log_fp);
    }
    if (motion_log_fp != NULL) {
        fclose(motion_log_fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR GPIO as input
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Initialize I2C
    i2c_handle_tmp117 = init_i2c(I2C_BUS, TMP117_ADDR);
    if (i2c_handle_tmp117 < 0) {
        fprintf(stderr, "Failed to initialize TMP117 I2C. Continuing without it.\n");
    }

    i2c_handle_aht20 = init_i2c(I2C_BUS, AHT20_ADDR);
    if (i2c_handle_aht20 < 0) {
        fprintf(stderr, "Failed to initialize AHT20 I2C. Continuing without it.\n");
    }

    // Open data log file
    data_log_fp = fopen(DATA_LOG_FILE, "a");
    if (data_log_fp == NULL) {
        fprintf(stderr, "Error opening data log file\n");
        cleanup();
        return 1;
    }

    // Open motion log file
    motion_log_fp = fopen(MOTION_LOG_FILE, "a");
    if (motion_log_fp == NULL) {
        fprintf(stderr, "Error opening motion log file\n");
        cleanup();
        return 1;
    }

    // Write header to data log file
    fprintf(data_log_fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");

    // Write header to motion log file
    fprintf(motion_log_fp, "Timestamp,MotionDetected\n");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_motion_log_time = 0;

    // Main loop
    while (!terminate) {
        float temperature = 0.0;
        float humidity = 0.0;
        int motion_detected = 0;

        // Read sensor data
