            if (read_tmp117(i2c_handle_tmp117, &temperature) != 0) {
                fprintf(stderr, "Failed to read temperature from TMP117\n");
            }
        }

        if (i2c_handle_aht20 >= 0) {
            if (read_aht20(i2c_handle_aht20, &humidity) != 0) {
