#include <string.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control duration (seconds)
#define MOTOR_DURATION 5

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void close_window();
void stop_motor();
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_message("Received signal, stopping motor and exiting...");
    stop_motor();
    gpioTerminate();
    exit(0);
}

// Function to read the rain sensor
int read_rain_sensor() {
    int rain_detected = gpioRead(RAIN_SENSOR_PIN);
    if (rain_detected < 0) {
        log_message("Error reading rain sensor.");
        return -1; // Indicate error
    }
    return (rain_detected == 0) ? 1 : 0; // Active-low, so 0 means rain
}

// Function to close the window
void close_window() {
    log_message("Closing window...");
    gpioWrite(MOTOR_ENA_PIN, 1); // Enable motor
    gpioWrite(MOTOR_IN1_PIN, 1); // Set IN1 HIGH
    gpioWrite(MOTOR_IN2_PIN, 0); // Set IN2 LOW
    gpioDelay(MOTOR_DURATION * 1000000); // Delay for 5 seconds (microseconds)
    stop_motor();
    log_message("Window closed.");
}

// Function to stop the motor
void stop_motor() {
    gpioWrite(MOTOR_ENA_PIN, 0); // Disable motor
    gpioWrite(MOTOR_IN1_PIN, 0); // Set IN1 LOW
    gpioWrite(MOTOR_IN2_PIN, 0); // Set IN2 LOW
    log_message("Motor stopped.");
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Rain sensor monitoring started.");

    // Main loop
    while (program_running) {
        int rain = read_rain_sensor();
        if (rain > 0) {
            close_window();
        } else if (rain < 0) {
            log_message("Error reading rain sensor, retrying...");
        }
        gpioDelay(2000000); // Delay for 2 seconds (microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();
    return 0;
}

