#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read CPU load from /proc/stat
float read_cpu_load() {
    FILE *fp;
    unsigned long long user1, nice1, system1, idle1, iowait1, irq1, softirq1, steal1, guest1, guest_nice1;
    unsigned long long user2, nice2, system2, idle2, iowait2, irq2, softirq2, steal2, guest2, guest_nice2;
    float cpu_usage;

    // Read initial CPU stats
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1.0; // Indicate error
    }
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user1, &nice1, &system1, &idle1, &iowait1, &irq1, &softirq1, &steal1, &guest1, &guest_nice1) != 10) {
        fclose(fp);
        fprintf(stderr, "Error reading CPU stats\n");
        return -1.0;
    }
    fclose(fp);

    // Wait for 500ms
    usleep(500000); // 500ms

    // Read CPU stats again
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1.0; // Indicate error
    }
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user2, &nice2, &system2, &idle2, &iowait2, &irq2, &softirq2, &steal2, &guest2, &guest_nice2) != 10) {
        fclose(fp);
        fprintf(stderr, "Error reading CPU stats\n");
        return -1.0;
    }
    fclose(fp);

    // Calculate CPU usage
    unsigned long long idle_delta = idle2 - idle1 - (iowait2 - iowait1);
    unsigned long long non_idle_delta = (user2 - user1) + (nice2 - nice1) + (system2 - system1) + (irq2 - irq1) + (softirq2 - softirq1) + (steal2 - steal1);
    unsigned long long total_delta = non_idle_delta + idle_delta;

    if (total_delta == 0) {
        return 0.0; // Avoid division by zero
    }

    cpu_usage = (float)non_idle_delta / total_delta * 100.0;

    return cpu_usage;
}

// Function to map CPU load to RGB color values
void map_load_to_color(float cpu_load, int *red, int *green, int *blue) {
    if (cpu_load < 0.0) cpu_load = 0.0;
    if (cpu_load > 100.0) cpu_load = 100.0;

    // Linear interpolation
    float red_val = (cpu_load / 100.0) * 255.0;
    float green_val = 255.0 - (cpu_load / 100.0) * 255.0;

    *red   = (int)red_val;
    *green = (int)green_val;
    *blue  = 0; // Blue is always 0 for this gradient
}

// Function to set RGB LED color using pigpio
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);   // Common anode, so invert the value
    gpioPWM(GREEN_PIN, 255 - green); // Common anode, so invert the value
    gpioPWM(BLUE_PIN, 255 - blue);  // Common anode, so invert the value
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float cpu_load;
    int red, green, blue;

    // Main loop
    while (!terminate) {
        // Read CPU load
        cpu_load = read_cpu_load();
        if (cpu_load < 0.0) {
            fprintf(stderr, "Error reading CPU load, using 0%%\n");
            cpu_load = 0.0;
        }

        // Map CPU load to color
        map_load_to_color(cpu_load, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Wait for 500ms
        usleep(500000); // 500ms
    }

    // Turn off LED
    set_led_color(0, 0, 0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

