#include <unistd.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define FAN_PIN 18       // GPIO18 (PWM0)
#define PWM_FREQUENCY 1000 // 1 kHz
#define BUFFER_SIZE 20

// MAX31855 Fault Codes
#define MAX31855_FAULT_OPEN_CIRCUIT 1
#define MAX31855_FAULT_SHORT_GND 2
#define MAX31855_FAULT_SHORT_VCC 3
#define MAX31855_FAULT_THERMOCOUPLE 4

// Structure for circular buffer entries
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} buffer_entry_t;

// Circular buffer structure
typedef struct {
    buffer_entry_t entries[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
static volatile bool running = true;
static circular_buffer_t buffer;
static int spi_fd;

// Function prototypes
int spi_init(int channel, int speed);
int spi_transfer(int fd, unsigned char *data, int len);
int read_max31855(int fd, float *temperature);
int calculate_duty_cycle(float temperature);
void set_fan_speed(int duty_cycle);
void buffer_init(circular_buffer_t *buffer);
void buffer_add(circular_buffer_t *buffer, time_t timestamp, float temperature, int duty_cycle);
void buffer_print(circular_buffer_t *buffer);
void signal_handler(int signal);

// SPI Initialization function
int spi_init(int channel, int speed) {
    int fd = wiringPiSPISetup(channel, speed);
    if (fd == -1) {
        fprintf(stderr, "Error initializing SPI channel %d: %s\n", channel, strerror(errno));
        return -1;
    }
    return fd;
}

// SPI Transfer function
int spi_transfer(int fd, unsigned char *data, int len) {
    int result = wiringPiSPIDataRW(fd, data, len);
    if (result == -1) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature from MAX31855
int read_max31855(int fd, float *temperature) {
    unsigned char data[4] = {0, 0, 0, 0};
    int fault;

    if (spi_transfer(fd, data, 4) == -1) {
        return -1;
    }

    // Check for fault bits
    fault = data[3] & 0x07;
    if (fault != 0) {
        fprintf(stderr, "MAX31855 Fault: 0x%02X\n", fault);
        if (fault == 0x01) {
            fprintf(stderr, "  Open Circuit\n");
        } else if (fault == 0x02) {
            fprintf(stderr, "  Short to GND\n");
        } else if (fault == 0x03) {
            fprintf(stderr, "  Short to VCC\n");
        } else if (fault == 0x04) {
            fprintf(stderr, "  Thermocouple Fault\n");
        }
        return -1; // Indicate an error
    }

    // Extract temperature data
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    *temperature = raw_temp * 0.25;

    return 0;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < 25.0) {
        duty_cycle = 0;
    } else if (temperature >= 25.0 && temperature <= 40.0) {
        duty_cycle = (int)((temperature - 25.0) / 15.0 * 128.0); // Linear ramp from 0 to 128 (50%)
    } else if (temperature > 40.0 && temperature <= 60.0) {
        duty_cycle = (int)((temperature - 40.0) / 20.0 * 179.0 + 128.0); // Steeper ramp from 128 to 255 (200%)
        if (duty_cycle > 255) {
            duty_cycle = 255;
        }
    } else {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Function to set fan speed using PWM
void set_fan_speed(int duty_cycle) {
    pwmWrite(FAN_PIN, duty_cycle);
}

// Circular buffer initialization function
void buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Circular buffer add function
void buffer_add(circular_buffer_t *buffer, time_t timestamp, float temperature, int duty_cycle) {
    buffer->entries[buffer->head].timestamp = timestamp;
    buffer->entries[buffer->head].temperature = temperature;
    buffer->entries[buffer->head].duty_cycle = duty_cycle;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Circular buffer print function
void buffer_print(circular_buffer_t *buffer) {
    printf("\n--- Circular Buffer Contents ---\n");
    for (int i = 0; i < buffer->count; i++) {
        int index = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE; // Corrected index calculation
        struct tm *timeinfo = localtime(&buffer->entries[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("Timestamp: %s, Temperature: %.2f C, Duty Cycle: %d\n", timestamp_str, buffer->entries[index].temperature, buffer->entries[index].duty_cycle);
    }
    printf("--- End of Buffer ---\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = false;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        return 1;
    }

    // Initialize PWM
    pinMode(FAN_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetClock(192); // Adjust clock to achieve 1 kHz frequency (19200000 / 192 = 100000, 100000 / 255 = ~392 Hz, need to adjust for 1kHz)
    pwmSetRange(255);
    pwmSetClock(19200000 / (PWM_FREQUENCY * 255)); // Calculate clock for 1kHz

    // Initialize circular buffer
    buffer_init(&buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        int duty_cycle;

        // Read temperature from MAX31855
        if (read_max31855(spi_fd, &temperature) == 0) {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Set fan speed
            set_fan_speed(duty_cycle);

            // Get current timestamp
            time_t now = time(NULL);

            // Add data to circular buffer
            buffer_add(&buffer, now, temperature, duty_cycle);

            // Print buffer contents every 5 seconds
            if (time(NULL) % 5 == 0) {
                buffer_print(&buffer);
            }

            printf("Temperature: %.2f C, Duty Cycle: %d\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, skipping fan update.\n");
        }

        // Wait for 1 second
        delay(1000);
    }

    // Stop PWM
    pwmWrite(FAN_PIN, 0);

    // Close SPI interface
    close(spi_fd);

    // Print circular buffer contents before exiting
    buffer_print(&buffer);

    // Terminate wiringPi
    wiringPiSetup(); // Dummy call to wiringPiSetup to terminate

    return 0;
}

