int read_calibration_data()
{
    if (read_16(0xAA, &ac1) != 0) return -1;
    if (read_16(0xAC, &ac2) != 0) return -1;
    if (read_16(0xAE, &ac3) != 0) return -1;
    if (read_16(0xB0, &ac4) != 0) return -1;
    if (read_16(0xB2, &ac5) != 0) return -1;
    if (read_16(0xB4, &ac6) != 0) return -1;
    if (read_16(0xB6, &b1) != 0) return -1;
    if (read_16(0xB8, &b2) != 0) return -1;
    if (read_16(0xBA, &mb) != 0) return -1;
    if (read_16(0xBC, &mc) != 0) return -1;
    if (read_16(0xBE, &md) != 0) return -1;

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temp)
{
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    if (read_16(BMP180_REG_MSB, raw_temp) != 0) return -1;

    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[1];
    buf[0] = 0x34 + (OSS << 6); // Pressure measurement command with OSS
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }
    gpioDelay(26000); // Wait 26ms for OSS = 3

    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in Celsius
float calculate_temperature(int raw_temp)
{
    long X1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    long X2 = ((long)mc << 11) / (X1 + md);
    long B5 = X1 + X2;
    float temperature = ((B5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate pressure in Pascals
float calculate_pressure(int raw_pressure, int raw_temp)
{
    long X1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    long X2 = ((long)mc << 11) / (X1 + md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)b2 * (B6 * B6) >> 12) >> 11;
    long X4 = ((long)ac2 * B6) >> 11;
    long B3 = (((((long)ac1) * 4 + X3) << OSS) + 2) >> 2;

    unsigned long X1_pressure = (unsigned long)ac3 * B6 >> 13;
    unsigned long X2_pressure = ((unsigned long)b1 * (B6 * B6 >> 12)) >> 16;
    unsigned long X3_pressure = ((X1_pressure + X2_pressure + 2) >> 2);
    unsigned long B4 = ((unsigned long)ac4 * (X3_pressure + 32768)) >> 15;
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> OSS);

    long pressure;
    if (B7 < 0x80000000)
    {
        pressure = (B7 * 2) / B4;
    }
    else
    {
        pressure = (B7 / B4) * 2;
    }

    X1_pressure = (pressure >> 8) * (pressure >> 8);
    X1_pressure = (X1_pressure * 3038) >> 16;
    X2_pressure = (-7357 * pressure) >> 16;
    pressure = pressure + ((X1_pressure + X2_pressure + 3791) >> 4);

    return pressure;
}

// Function to log data to a CSV file
void log_data(float temperature, float pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to file immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user)
{
    logging_active = !logging_active;
    printf("Logging toggled to %s\n", logging_active ? "ON" : "OFF");
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure interrupt pin
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);
    gpioSetAlertFuncEx(INTERRUPT_PIN, interrupt_handler, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int raw_temp, raw_pressure;
    float temperature, pressure;

    // Main loop
    while (1) {
        if (logging_active) {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) != 0 || read_raw_pressure(&raw_pressure) != 0) {
                fprintf(stderr, "Error reading sensor data\n");
            } else {
                // Calculate temperature and pressure
                temperature = calculate_temperature(raw_temp);
                pressure = calculate_pressure(raw_pressure, raw_temp);

                // Log data
                log_data(temperature, pressure);
            }
        }

        // Wait for 1 second
        gpioDelay(1000000);
    }

    return 0;
}

