// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CE_PIN 8          // Chip Enable pin (GPIO8)
#define RTD_NOMINAL 100.0 // Nominal RTD resistance (100 ohms)
#define A 0.0039083       // Callendar-Van Dusen coefficient A
#define B -5.01518e-3     // Callendar-Van Dusen coefficient B
#define C 2.98616e-6      // Callendar-Van Dusen coefficient C
#define RREF 430.0        // Reference resistor value (430 ohms)
#define LOG_FILE "rtd_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_max31865(uint16_t *rtd_value, uint16_t *fault_status);
float calculate_temperature(uint16_t rtd_value);
void log_data(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int ce_pin;
    char log_file[64];
} config_t;

config_t config = {SPI_CHANNEL, SPI_SPEED, CE_PIN, LOG_FILE};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C)\n");
    }

    // Main loop
    uint16_t rtd_value, fault_status;
    float temperature;
    while (!terminate) {
        // Read RTD value and fault status
        if (read_max31865(&rtd_value, &fault_status) == 0) {
            // Check for fault conditions
            if (fault_status != 0) {
                fprintf(stderr, "Fault detected: 0x%04X\n", fault_status);
                fprintf(log_file, "Timestamp,Fault Detected: 0x%04X\n", fault_status);
                fflush(log_file);
            } else {
                // Calculate temperature
                temperature = calculate_temperature(rtd_value);

                // Log data
                log_data(temperature);
            }
        } else {
            fprintf(stderr, "Failed to read RTD value\n");
            fprintf(log_file, "Timestamp,Failed to read RTD value\n");
            fflush(log_file);
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read data from MAX31865
int read_max31865(uint16_t *rtd_value, uint16_t *fault_status) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Read RTD MSB
    tx_buffer[0] = 0x01; // Read RTD MSB command
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed (RTD MSB)\n");
        return 1;
    }

    *rtd_value = ((uint16_t)rx_buffer[0] << 8) | (uint16_t)rx_buffer[1];
    *rtd_value = *rtd_value >> 1; // Remove fault bit

    // Read Fault Status
    tx_buffer[0] = 0x07; // Read Fault Status command
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed (Fault Status)\n");
        return 1;
    }

    *fault_status = ((uint16_t)rx_buffer[0] << 8) | (uint16_t)rx_buffer[1];

    return 0;
}

// Calculate temperature using Callendar-Van Dusen equation
float calculate_temperature(uint16_t rtd_value) {
    float rtd_resistance = (float)rtd_value * RREF / 32768.0; // Convert to resistance
    float temperature = A * rtd_resistance + B * rtd_resistance * rtd_resistance + C * rtd_resistance * rtd_resistance * rtd_resistance;

    return temperature;
}

// Log data to file
void log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s,%.2f\n", timestamp, temperature);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

