#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_CHIPID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_PRESS_MSB 0xF7
#define BME280_REG_PRESS_LSB 0xF8
#define BME280_REG_PRESS_XLSB 0xF9
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_TEMP_LSB 0xFB
#define BME280_REG_TEMP_XLSB 0xFC
#define BME280_REG_HUM_MSB 0xFD
#define BME280_REG_HUM_LSB 0xFE

// Calibration data registers
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

// Chip ID
#define BME280_CHIP_ID 0x60

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data
unsigned short dig_T1;
short dig_T2, dig_T3;
unsigned short dig_P1;
short dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
unsigned char dig_H1, dig_H3;
short dig_H2, dig_H4, dig_H5, dig_H6;
unsigned char dig_H7;

// Function prototypes
int init_bme280();
int read_calibration_data();
int read_raw_data(long *temperature, long *pressure, long *humidity);
double compensate_temperature(long raw_temperature);
double compensate_pressure(long raw_pressure, double t_fine);
double compensate_humidity(long raw_humidity, double t_fine);
int log_data(double temperature, double humidity, double pressure);
void signal_handler(int signal);

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to initialize the BME280 sensor
int init_bme280() {
    // Check chip ID
    char chip_id;
    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_CHIPID, &chip_id, 1) != 1) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }

    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    // Reset the sensor
    char reset_value = 0xB6;
    if (i2cWriteI2CBlockData(i2c_handle, BME280_REG_RESET, &reset_value, 1) != 1) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for the reset to complete

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    // Set humidity oversampling to 1x
    char ctrl_hum_value = 0x01;
    if (i2cWriteI2CBlockData(i2c_handle, BME280_REG_CTRL_HUM, &ctrl_hum_value, 1) != 1) {
        fprintf(stderr, "Error setting humidity oversampling\n");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and mode to normal
    char ctrl_meas_value = (0x01 << 5) | (0x01 << 2) | 0x03; // osrs_t = 1, osrs_p = 1, normal mode
    if (i2cWriteI2CBlockData(i2c_handle, BME280_REG_CTRL_MEAS, &ctrl_meas_value, 1) != 1) {
        fprintf(stderr, "Error setting temperature/pressure oversampling and mode\n");
        return -1;
    }

    // Set inactive duration to 0.5ms
    char config_value = (0x04 << 2); // t_standby = 0.5ms
    if (i2cWriteI2CBlockData(i2c_handle, BME280_REG_CONFIG, &config_value, 1) != 1) {
        fprintf(stderr, "Error setting inactive duration\n");
        return -1;
    }

    return 0;
}

// Function to read calibration data from the BME280
int read_calibration_data() {
    unsigned char data[26];
    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_00, (char *)data, 26) != 26) {
        fprintf(stderr, "Error reading calibration data (00-25)\n");
        return -1;
    }

    dig_T1 = (data[1] << 8) | data[0];
    dig_T2 = (short)((data[3] << 8) | data[2]);
    dig_T3 = (short)((data[5] << 8) | data[4]);
    dig_P1 = (data[7] << 8) | data[6];
    dig_P2 = (short)((data[9] << 8) | data[8]);
    dig_P3 = (short)((data[11] << 8) | data[10]);
    dig_P4 = (short)((data[13] << 8) | data[12]);
    dig_P5 = (short)((data[15] << 8) | data[14]);
    dig_P6 = (short)((data[17] << 8) | data[16]);
    dig_P7 = (short)((data[19] << 8) | data[18]);
    dig_P8 = (short)((data[21] << 8) | data[20]);
    dig_P9 = (short)((data[23] << 8) | data[22]);
    dig_H1 = data[25];

    unsigned char data_h[7];
    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_26, (char *)data_h, 7) != 7) {
        fprintf(stderr, "Error reading calibration data (26-32)\n");
        return -1;
    }

    dig_H2 = (short)((data_h[1] << 8) | data_h[0]);
    dig_H3 = data_h[2];
    dig_H4 = (short)((data_h[3] << 4) | (data_h[4] & 0x0F));
    dig_H5 = (short)((data_h[5] << 4) | (data_h[4] >> 4));
    dig_H6 = data_h[6];

    return 0;
}

// Function to read raw temperature, pressure, and humidity data from the BME280
