#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// GPIO pin for alert
#define ALERT_GPIO 24

// Circular buffer size (60 seconds * 20 readings/second)
#define BUFFER_SIZE 1200

// Structure to hold calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold a pressure reading with timestamp
typedef struct {
    time_t timestamp;
    float pressure;
} pressure_reading_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
pressure_reading_t pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;
bool running = true;

// Function prototypes
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data);
int read_raw_temperature(int i2c_handle);
int read_raw_pressure(int i2c_handle, int oss);
float calculate_pressure(int raw_temperature, int raw_pressure, const bmp180_calibration_data_t *calibration_data);
void add_reading(time_t timestamp, float pressure);
float calculate_rolling_average();
void trigger_alert();
void signal_handler(int signal);
void log_error(const char *message);

// Function to read calibration data from the BMP180
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data) {
    uint8_t buffer[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buffer, 22) != 22) {
        log_error("Failed to read calibration data");
        return -1;
    }

    calibration_data->ac1 = (buffer[0] << 8) | buffer[1];
    calibration_data->ac2 = (buffer[2] << 8) | buffer[3];
    calibration_data->ac3 = (buffer[4] << 8) | buffer[5];
    calibration_data->ac4 = (buffer[6] << 8) | buffer[7];
    calibration_data->ac5 = (buffer[8] << 8) | buffer[9];
    calibration_data->ac6 = (buffer[10] << 8) | buffer[11];
    calibration_data->b1 = (buffer[12] << 8) | buffer[13];
    calibration_data->b2 = (buffer[14] << 8) | buffer[15];
    calibration_data->mb = (buffer[16] << 8) | buffer[17];
    calibration_data->mc = (buffer[18] << 8) | buffer[19];
    calibration_data->md = (buffer[20] << 8) | buffer[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int i2c_handle) {
    char write_buffer[2] = {BMP180_REG_CONTROL, 0x2E};
    if (i2cWriteDevice(i2c_handle, write_buffer, 2) != 0) {
        log_error("Failed to write temperature conversion command");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    char read_buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)read_buffer, 2) != 2) {
        log_error("Failed to read raw temperature data");
        return -1;
    }

    return (read_buffer[0] << 8) | read_buffer[1];
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int i2c_handle, int oss) {
    char write_buffer[2] = {BMP180_REG_CONTROL, 0x34 + (oss << 6)};
    if (i2cWriteDevice(i2c_handle, write_buffer, 2) != 0) {
        log_error("Failed to write pressure conversion command");
        return -1;
    }

    gpioDelay(2 + (3 << oss)) ; // Wait for conversion

    char read_buffer[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)read_buffer, 3) != 3) {
        log_error("Failed to read raw pressure data");
        return -1;
    }

    return ((read_buffer[0] << 16) | (read_buffer[1] << 8) | read_buffer[2]) >> (8 - oss);
}

// Function to calculate pressure in hPa
float calculate_pressure(int raw_temperature, int raw_pressure, const bmp180_calibration_data_t *calibration_data) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    b5 = (((long)raw_temperature - (long)calibration_data->ac6) * (long)calibration_data->ac5) >> 15;
    x1 = ((long)calibration_data->mc << 11) / (b5 + calibration_data->md);
    b6 = b5 + x1;
    x2 = ((long)calibration_data->b2 * ((b6 * b6) >> 12)) >> 11;
    x3 = ((long)calibration_data->ac2 * b6) >> 11;
    b3 = (((((long)calibration_data->ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((long)calibration_data->ac3 * b6) >> 13;
    x2 = ((long)calibration_data->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2 + 2) >> 2);
    b4 = ((unsigned long)calibration_data->ac4 * (unsigned long)(x3 + 32768)) >> 15;
    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return (float)p / 100.0f; // Convert to hPa
}

// Function to add a pressure reading to the circular buffer
void add_reading(time_t timestamp, float pressure) {
    pressure_buffer[buffer_index].timestamp = timestamp;
