#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling Setting (OSS)
#define OSS 0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int validate_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
double calculate_temperature(int raw_temp);
double calculate_pressure(int raw_pressure, int raw_temp);
void log_data(double temperature, double pressure);
void timer_callback();
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
int read_16(int handle, uint8_t reg, int16_t *value)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read an unsigned 16-bit value from the BMP180
int read_u16(int handle, uint8_t reg, uint16_t *value)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to write a byte to the BMP180
int write_byte(int handle, uint8_t reg, uint8_t value)
{
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteI2CBlockData(handle, reg, buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing byte 0x%02X to register 0x%02X\n", value, reg);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_16(i2c_handle, BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_16(i2c_handle, BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_16(i2c_handle, BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_u16(i2c_handle, BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_u16(i2c_handle, BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
    if (read_u16(i2c_handle, BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
    if (read_16(i2c_handle, BMP180_REG_CAL_B1, &b1) != 0) return -1;
    if (read_16(i2c_handle, BMP180_REG_CAL_B2, &b2) != 0) return -1;
    if (read_16(i2c_handle, BMP180_REG_CAL_MB, &mb) != 0) return -1;
    if (read_16(i2c_handle, BMP180_REG_CAL_MC, &mc) != 0) return -1;
    if (read_16(i2c_handle, BMP180_REG_CAL_MD, &md) != 0) return -1;

    return 0;
}

// Function to validate calibration data
int validate_calibration_data()
{
    if (ac1 == 0 || ac2 == 0 || ac3 == 0 || ac4 == 0 || ac5 == 0 || ac6 == 0 ||
        b1 == 0 || b2 == 0 || mb == 0 || mc == 0 || md == 0) {
        fprintf(stderr, "Error: Invalid calibration data. Check sensor connection.\n");
        return -1;
    }
    return 0;
}

// Function to read raw temperature data
int read_raw_temperature(int *raw_temp)
{
    if (write_byte(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) return -1;
    gpioDelay(5); // Wait 4.5ms
    if (read_16(i2c_handle, BMP180_REG_MSB, raw_temp) != 0) return -1;
    return 0;
}

// Function to read raw pressure data
int read_raw_pressure(int *raw_pressure)
{
    if (write_byte(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) != 0) return -1;
    gpioDelay(2 + (3 << OSS)); // Wait for conversion

    char buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp)
{
    long X1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;
    double temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in pascals
double calculate_pressure(int raw_pressure, int raw_temp)
{
    long X1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    long X4 = ((long)ac2 * B6) / pow(2, 11);
    long B3 = (((((long)ac1) * 4 + X3) << OSS) + 2) / 4;

    unsigned long X1_pressure = (unsigned long)ac3 * B6 / pow(2, 13);
    unsigned long X2_pressure = (unsigned long)b1 * (B6 * B6) / pow(2, 12);
    unsigned long B4 = X1_pressure + X2_pressure + 32768;
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> OSS);

    long pressure;
    if (B7 < 0x80000000)
    {
        pressure = (B7 * 2) / B4;
    }
    else
    {
        pressure = (B7 / B4) * 2;
    }

    X1_pressure = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    X1_pressure = (X1_pressure * 3038) / pow(2, 16);
    X2_pressure = (-7357 * pressure) / pow(2, 16);

    double calculated_pressure = pressure + (X1_pressure + X2_pressure + 3791) / pow(2, 4);
    return calculated_pressure;
}

// Function to log data to a file
void log_data(double temperature, double pressure)
{
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, pressure);
    fflush(log_file);
}

// Timer callback function
void timer_callback()
{
    int raw_temp, raw_pressure;
    double temperature, pressure;

    if (read_raw_temperature(&raw_temp) != 0) {
        fprintf(stderr, "Error reading raw temperature\n");
        return;
    }

    if (read_raw_pressure(&raw_pressure) != 0) {
        fprintf(stderr, "Error reading raw pressure\n");
        return;
    }

    temperature = calculate_temperature(raw_temp);
    pressure = calculate_pressure(raw_pressure, raw_temp);

    log_data(temperature, pressure);
}

// Signal handler function
void signal_handler(int signal)
{
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Validate calibration data
    if (validate_calibration_data() != 0) {
        fprintf(stderr, "Error validating calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer interrupt
    if (gpioSetTimerFuncEx(0, 500, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up timer interrupt\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Clean up
    gpioSetTimerFuncEx(0, 500, NULL, NULL); // Disable timer
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

