// Constants
#define GPIO_PIN 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define DUTY_MIN 0
#define DUTY_MAX 255

// Global variables
static volatile int running = 1;
FILE *log_fp = NULL;

// Function prototypes
float read_temperature();
int map_temperature_to_duty_cycle(float temperature);
int set_pwm_duty_cycle(int duty_cycle);
int log_data(float temperature, int duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioPWM(GPIO_PIN, 0); // Stop the fan
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read the CPU temperature from the thermal zone file
float read_temperature() {
    FILE *fp;
    char buffer[10];
    float temperature = -1.0;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temperature = atoi(buffer) / 1000.0;
    } else {
        perror("Error reading temperature from file");
        fclose(fp);
        return -1.0;
    }

    fclose(fp);
    return temperature;
}

// Function to map the temperature to a PWM duty cycle
int map_temperature_to_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature < TEMP_MIN) {
        duty_cycle = DUTY_MIN;
    } else if (temperature > TEMP_MAX) {
        duty_cycle = DUTY_MAX;
    } else {
        duty_cycle = (int)(((temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * (DUTY_MAX - DUTY_MIN));
    }

    return duty_cycle;
}

// Function to set the PWM duty cycle
int set_pwm_duty_cycle(int duty_cycle) {
    if (gpioPWM(GPIO_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

// Function to log the data to a file
int log_data(float temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_fp, "%s, %.2f, %d\n", timestamp, temperature, duty_cycle);
    fflush(log_fp); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    float temperature;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(GPIO_PIN, 255);

    // Set PWM duty cycle to 0 initially
    gpioPWM(GPIO_PIN, 0);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read the temperature
        temperature = read_temperature();

        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
        } else {
            // Map the temperature to a duty cycle
            duty_cycle = map_temperature_to_duty_cycle(temperature);

            // Set the PWM duty cycle
            if (set_pwm_duty_cycle(duty_cycle) != 0) {
                fprintf(stderr, "Error setting PWM duty cycle.\n");
            }

            // Log the data
            if (log_data(temperature, duty_cycle) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(GPIO_PIN, 0); // Stop the fan
    gpioTerminate(); // Terminate pigpio
    if (log_fp != NULL) {
        fclose(log_fp);
    }

    return 0;
}

