#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>
#include <pthread.h>
#include <syslog.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Configuration
#define I2C_BUS 1
#define LM75_ADDRESS 0x48
#define ALERT_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0f
#define TEMP_HYSTERESIS 27.5f
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
static int i2c_fd = -1;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static float running_average = 0.0f;
static volatile sig_atomic_t program_running = 1;
static volatile bool alert_state = false;

// Function prototypes
int init_i2c(int bus, int address);
float read_temperature(int fd);
void update_buffer(float temperature);
float calculate_average();
void control_alert_led(float temperature);
void *alert_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// I2C initialization function
int init_i2c(int bus, int address) {
    int fd = wiringPiI2CSetupInterface("/dev/i2c-1", address);
    if (fd == -1) {
        syslog(LOG_ERR, "Failed to initialize I2C: %s", strerror(errno));
        return -1;
    }
    return fd;
}

// Temperature reading function
float read_temperature(int fd) {
    int raw_temp;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        raw_temp = wiringPiI2CReadReg16(fd, 0); // Read temperature register
        if (raw_temp != -1) {
            // Convert raw temperature to Celsius (LM75 format)
            raw_temp = ((raw_temp >> 8) | (raw_temp << 8)); // Byte swap
            float temperature = (float)(raw_temp >> 5) * 0.125f;
            return temperature;
        } else {
            syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
            retries++;
            delay(RETRY_DELAY_MS);
        }
    }

    syslog(LOG_ERR, "Failed to read temperature after %d retries.", MAX_RETRIES);
    return -1000.0f; // Indicate error
}

// Circular buffer update function
void update_buffer(float temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

// Running average calculation function
float calculate_average() {
    float sum = 0.0f;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);
    return sum / BUFFER_SIZE;
}

// Alert LED control function
void control_alert_led(float temperature) {
    if (temperature > TEMP_THRESHOLD && !alert_state) {
        digitalWrite(ALERT_GPIO, HIGH);
        alert_state = true;
        syslog(LOG_INFO, "Temperature above threshold. Turning on alert LED.");
    } else if (temperature < TEMP_HYSTERESIS && alert_state) {
        digitalWrite(ALERT_GPIO, LOW);
        alert_state = false;
        syslog(LOG_INFO, "Temperature below hysteresis. Turning off alert LED.");
    }
}

// Alert thread function
void *alert_thread(void *arg) {
    while (program_running) {
        float temperature = calculate_average();
        control_alert_led(temperature);
        delay(100); // Check every 100ms
    }
    pthread_exit(NULL);
    return NULL;
}

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received: %d. Shutting down.", signal);
    program_running = 0;
}

// Cleanup function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources.");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    digitalWrite(ALERT_GPIO, LOW); // Turn off LED
    pthread_mutex_destroy(&buffer_mutex);
    closelog();
}

int main() {
    // Initialize syslog
    openlog("temperature_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        syslog(LOG_ERR, "Failed to initialize wiringPi: %s", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, LM75_ADDRESS);
    if (i2c_fd == -1) {
        syslog(LOG_ERR, "Failed to initialize I2C. Exiting.");
        cleanup();
        return 1;
    }

    // Set up alert GPIO
    pinMode(ALERT_GPIO, OUTPUT);
    digitalWrite(ALERT_GPIO, LOW); // Initially off

    // Create alert thread
    pthread_t alert_thread_id;
    if (pthread_create(&alert_thread_id, NULL, alert_thread, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create alert thread: %s", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        float temperature = read_temperature(i2c_fd);
        if (temperature > -999.0f) { // Check for valid temperature reading
            update_buffer(temperature);
            running_average = calculate_average();
            syslog(LOG_INFO, "Temperature: %.2f°C, Average: %.2f°C", temperature, running_average);
        } else {
            syslog(LOG_ERR, "Failed to read temperature. Retrying I2C initialization.");
            close(i2c_fd);
            i2c_fd = init_i2c(I2C_BUS, LM75_ADDRESS);
            if (i2c_fd == -1) {
                syslog(LOG_ERR, "Failed to re-initialize I2C. Exiting.");
                program_running = 0; // Exit the loop if re-initialization fails
            }
        }
        delay(1000); // Read every 1 second
    }

    // Cleanup and exit
    pthread_join(alert_thread_id, NULL);
    cleanup();
    return 0;
}

