    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

// Running average calculation function
float calculate_average() {
    float sum = 0.0f;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);
    return sum / BUFFER_SIZE;
}

// Alert LED control function
void control_alert_led(float temperature) {
    if (temperature > TEMP_THRESHOLD && !alert_state) {
        digitalWrite(ALERT_GPIO, HIGH);
        alert_state = true;
        syslog(LOG_INFO, "Temperature above threshold. Turning on alert LED.");
    } else if (temperature < TEMP_HYSTERESIS && alert_state) {
        digitalWrite(ALERT_GPIO, LOW);
        alert_state = false;
        syslog(LOG_INFO, "Temperature below hysteresis. Turning off alert LED.");
    }
}

// Alert thread function
void *alert_thread(void *arg) {
    while (program_running) {
        float temperature = calculate_average();
        control_alert_led(temperature);
        delay(100); // Check every 100ms
    }
    pthread_exit(NULL);
    return NULL;
}

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received: %d. Shutting down.", signal);
    program_running = 0;
}

// Cleanup function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources.");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    digitalWrite(ALERT_GPIO, LOW); // Turn off LED
    pthread_mutex_destroy(&buffer_mutex);
    closelog();
}

int main() {
    // Initialize syslog
    openlog("temperature_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        syslog(LOG_ERR, "Failed to initialize wiringPi: %s", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, LM75_ADDRESS);
    if (i2c_fd == -1) {
        syslog(LOG_ERR, "Failed to initialize I2C. Exiting.");
        cleanup();
        return 1;
    }

    // Set up alert GPIO
    pinMode(ALERT_GPIO, OUTPUT);
    digitalWrite(ALERT_GPIO, LOW); // Initially off

    // Create alert thread
    pthread_t alert_thread_id;
    if (pthread_create(&alert_thread_id, NULL, alert_thread, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create alert thread: %s", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        float temperature = read_temperature(i2c_fd);
        if (temperature > -999.0f) { // Check for valid temperature reading
            update_buffer(temperature);
            running_average = calculate_average();
            syslog(LOG_INFO, "Temperature: %.2f°C, Average: %.2f°C", temperature, running_average);
        } else {
            syslog(LOG_ERR, "Failed to read temperature. Retrying I2C initialization.");
            close(i2c_fd);
            i2c_fd = init_i2c(I2C_BUS, LM75_ADDRESS);
            if (i2c_fd == -1) {
                syslog(LOG_ERR, "Failed to re-initialize I2C. Exiting.");
                program_running = 0; // Exit the loop if re-initialization fails
            }
        }
        delay(1000); // Read every 1 second
    }

    // Cleanup and exit
    pthread_join(alert_thread_id, NULL);
    cleanup();
    return 0;
}

