#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration
#define HEATER_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define TARGET_TEMPERATURE 25.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define MAX_TEMPERATURE 80.0
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define SPI_MODE 1
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_CONFIG_VALUE 0xC2 // VBIAS, auto conversion, 50/60 Hz filter
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03
#define MAX31865_FAULT_CLEAR_REG 0x07

// Global variables
static int spi_handle;
static volatile int running = 1;
static double integral = 0.0;
static double previous_error = 0.0;
static double target_temperature = TARGET_TEMPERATURE;
static double Kp_val = Kp;
static double Ki_val = Ki;
static double Kd_val = Kd;

// Function prototypes
double read_temperature();
double calculate_pid(double current_temperature);
void set_pwm_duty(int duty_cycle);
void load_configuration(const char *filename);
void signal_handler(int signal);
void log_error(const char *message);

// Function to read temperature from MAX31865
double read_temperature() {
    unsigned char data[3];
    int rtd_raw;
    double rtd_resistance;
    double temperature;
    unsigned char fault;

    // Read RTD MSB and LSB registers
    data[0] = MAX31865_RTD_MSB_REG | 0x80; // Read command
    if (spiXfer(spi_handle, data, data, 3) != 0) {
        log_error("SPI read failed (MSB/LSB).");
        return -1000.0; // Indicate error
    }

    rtd_raw = ((data[1] << 8) | data[2]) >> 1; // Combine MSB and LSB, remove fault bit

    // Read Fault register
    data[0] = MAX31865_FAULT_REG | 0x80; // Read command
    if (spiXfer(spi_handle, data, data, 3) != 0) {
        log_error("SPI read failed (Fault).");
        return -1000.0; // Indicate error
    }

    fault = data[2];

    if (fault & 0x01) {
        log_error("MAX31865 Fault: Open circuit.");
        return -1000.0;
    } else if (fault & 0x02) {
        log_error("MAX31865 Fault: Short to GND.");
        return -1000.0;
    } else if (fault & 0x04) {
        log_error("MAX31865 Fault: Short to VCC.");
        return -1000.0;
    }

    // Convert RTD raw value to resistance (PT100, 430 ohm reference resistor)
    rtd_resistance = ((double)rtd_raw / 32768.0) * 430.0;

    // Convert resistance to temperature (PT100, linear approximation)
    temperature = (rtd_resistance - 100.0) / 0.385; // Simplified linear approximation

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double current_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = (Kp_val * error) + (Ki_val * integral) + (Kd_val * derivative);
    previous_error = error;

    // Clamp output to 0-1000 range
    if (output < 0) output = 0;
    if (output > 1000) output = 1000;

    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty(int duty_cycle) {
    gpioPWM(HEATER_GPIO, duty_cycle);
}

// Function to load configuration from JSON file
void load_configuration(const char *filename) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load configuration file: %s\n", error.text);
        return;
    }

    json_t *temp = json_object_get(root, "target_temperature");
    if (temp) {
        target_temperature = json_real_value(temp);
    }

    json_t *kp = json_object_get(root, "Kp");
    if (kp) {
        Kp_val = json_real_value(kp);
    }

    json_t *ki = json_object_get(root, "Ki");
    if (ki) {
        Ki_val = json_real_value(ki);
    }

    json_t *kd = json_object_get(root, "Kd");
    if (kd) {
        Kd_val = json_real_value(kd);
    }

    json_decref(root);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, shutting down...\n", signal);
}

// Function to log errors with timestamps
void log_error(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[256];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld: %s\n", tmbuf, tv.tv_usec, message);
    fprintf(stderr, "%s", buf);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure MAX31865
    unsigned char config_data[2];
    config_data[0] = MAX31865_CONFIG_REG;
    config_data[1] = MAX31865_CONFIG_VALUE;
    if (spiWrite(spi_handle, config_data, 2) != 0) {
        log_error("Failed to configure MAX31865.");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    // Load configuration from file
    load_configuration("config.json");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        double temperature = read_temperature();
        if (temperature < -900) {
            log_error("Failed to read temperature, exiting.");
            break;
        }

        if (temperature > MAX_TEMPERATURE) {
            log_error("Temperature exceeds maximum, shutting down heater.");
            set_pwm_duty(0);
            break;
        }

        double pid_output = calculate_pid(temperature);
        set_pwm_duty((int)pid_output);

        printf("Temperature: %.2f°C, Duty Cycle: %d\n", temperature, (int)pid_output);
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    set_pwm_duty(0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

