#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// Calibration data variables
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
double calculate_temperature(int raw_temperature);
double calculate_pressure(int raw_pressure, int raw_temperature);
bool check_breach(double temperature, double pressure);
void log_breach(double temperature, double pressure);
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
int read_16(int reg, int *value)
{
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X: %d\n", reg, result);
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_16(0xAA, &ac1) != 0) return -1;
    if (read_16(0xAC, &ac2) != 0) return -1;
    if (read_16(0xAE, &ac3) != 0) return -1;
    if (read_16(0xB0, &ac4) != 0) return -1;
    if (read_16(0xB2, &ac5) != 0) return -1;
    if (read_16(0xB4, &ac6) != 0) return -1;
    if (read_16(0xB6, &b1) != 0) return -1;
    if (read_16(0xB8, &b2) != 0) return -1;
    if (read_16(0xBA, &mb) != 0) return -1;
    if (read_16(0xBC, &mc) != 0) return -1;
    if (read_16(0xBE, &md) != 0) return -1;

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temperature)
{
    char buf[1];
    int result;

    buf[0] = 0x2E; // Temperature measurement command
    result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing temperature measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    if (read_16(BMP180_REG_MSB, raw_temperature) != 0) return -1;

    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[1];
    int result;

    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing pressure measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(2 + (3 << BMP180_OSS)) ; // Wait for conversion

    int msb, lsb, xlsb;
    if (read_16(BMP180_REG_MSB, &msb) != 0) return -1;
    if (read_16(BMP180_REG_LSB, &lsb) != 0) return -1;
    if (read_16(BMP180_REG_XLSB, &xlsb) != 0) return -1;

    *raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);

    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temperature)
{
    long x1 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in hPa
double calculate_pressure(int raw_pressure, int raw_temperature)
{
    long x1 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) >> 12) >> 11;
    long x4 = ((long)ac2 * b6) >> 11;
    long b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    unsigned long p;
    x1 = ((long)ac3 * b6) >> 13;
    x2 = ((long)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    unsigned long b4 = ((unsigned long)ac4 * (unsigned long)(x3 + 32768)) >> 15;
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);

    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return (double)p / 100.0;
}

// Function to check for temperature or pressure breaches
bool check_breach(double temperature, double pressure)
{
    return (temperature > 30.0 || pressure < 950.0);
}

// Function to log breaches to a file
void log_breach(double temperature, double pressure)
{
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s - Temperature: %.2f °C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
