#define BMP180_REG_CAL_MD 0xBE

// Oversampling Setting (OSS)
#define OSS 0

// GPIO pin for fan control
#define FAN_GPIO 18

// Circular buffer size
#define BUFFER_SIZE 60

// Structure to hold temperature and pressure readings
typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} Reading;

// Circular buffer structure
typedef struct {
    Reading buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global variables
int i2c_handle;
CircularBuffer readings;
bool running = true;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
float calculate_temperature(int raw_temperature);
