    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_16(BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_16(BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_16(BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_u16(BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_u16(BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
    if (read_u16(BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
    if (read_16(BMP180_REG_CAL_B1, &b1) != 0) return -1;
    if (read_16(BMP180_REG_CAL_B2, &b2) != 0) return -1;
    if (read_16(BMP180_REG_CAL_MB, &mb) != 0) return -1;
    if (read_16(BMP180_REG_CAL_MC, &mc) != 0) return -1;
    if (read_16(BMP180_REG_CAL_MD, &md) != 0) return -1;

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temperature)
{
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }
    gpioDelay(5); // Wait 4.5ms (minimum)

    if (read_16(BMP180_REG_MSB, raw_temperature) != 0) return -1;

    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[1];
    buf[0] = 0x34 + (OSS << 6); // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }
    gpioDelay(2 + (3 << OSS)); // Wait for conversion

    int msb, lsb, xlsb;
    if (read_16(BMP180_REG_MSB, &msb) != 0) return -1;
    if (read_16(BMP180_REG_LSB, &lsb) != 0) return -1;
    if (read_16(BMP180_REG_XLSB, &xlsb) != 0) return -1;

    *raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
float calculate_temperature(int raw_temperature)
{
    long X1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;
    float temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
float calculate_pressure(int raw_pressure, int raw_temperature)
{
    long X1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    long X4 = ((long)ac2 * B6) / pow(2, 11);
    long B3 = (((((long)ac1) * 4 + X3) << OSS) + 2) / 4;

    unsigned long X1_pressure = (unsigned long)ac3 * B6 / pow(2, 13);
    unsigned long X2_pressure = (unsigned long)b1 * (B6 * B6) / pow(2, 12);
    unsigned long X3_pressure = (X1_pressure + X2_pressure + 2) / 4;
    unsigned long B4 = (unsigned long)ac4 * (X3_pressure + 32768) / pow(2, 15);
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> OSS);

    long pressure;
    if (B7 < 0x80000000)
    {
        pressure = (B7 * 2) / B4;
    }
    else
    {
        pressure = (B7 / B4) * 2;
    }

