void add_reading(float temperature, float pressure)
{
    time(&readings.buffer[readings.head].timestamp);
    readings.buffer[readings.head].temperature = temperature;
    readings.buffer[readings.head].pressure = pressure;

    readings.head = (readings.head + 1) % BUFFER_SIZE;
    if (readings.count < BUFFER_SIZE) {
        readings.count++;
    }
}

