void timer_callback()
{
    int raw_temperature, raw_pressure;
    float temperature, pressure;

    if (read_raw_temperature(&raw_temperature) == 0) {
        if (read_raw_pressure(&raw_pressure) == 0) {
            temperature = calculate_temperature(raw_temperature);
            pressure = calculate_pressure(raw_pressure, raw_temperature);

            add_reading(temperature, pressure);
            print_reading(temperature, pressure);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Error reading raw pressure\n");
        }
    } else {
        fprintf(stderr, "Error reading raw temperature\n");
    }
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    running = false;
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    readings.head = 0;
    readings.count = 0;

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    gpioSetTimerFunc(0, 500, timer_callback); // Timer 0, every 500ms

    // Main loop
    while (running) {
        sleep(1); // Sleep for 1 second
    }

    return 0;
}

