        case 0: gpioDelay(5); break; // 4.5ms
        case 1: gpioDelay(8); break; // 7.5ms
        case 2: gpioDelay(14); break; // 13.5ms
        case 3: gpioDelay(26); break; // 25.5ms
    }

    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure: %s\n", strerror(errno));
        return -1;
    }

    *raw_pressure = ((int32_t)data[0] << 16 | (int32_t)data[1] << 8 | (int32_t)data[2]) >> (8 - oss);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp)
{
    double X1 = ((double)raw_temp - (double)ac6) * ((double)ac5 / pow(2, 15));
    double X2 = ((double)mc * pow(2, 11)) / (X1 + (double)md);
    double B5 = X1 + X2;
    double temperature = (B5 + 8) / pow(2, 4);
    return temperature / 10.0;
}

// Function to calculate pressure in pascals
double calculate_pressure(int raw_pressure, int raw_temp, int oss)
{
    double X1 = ((double)raw_temp - (double)ac6) * ((double)ac5 / pow(2, 15));
    double X2 = ((double)mc * pow(2, 11)) / (X1 + (double)md);
    double B5 = X1 + X2;

    double B6 = B5 - 4000;
    double X3 = ((double)b2 * (B6 * B6 / pow(2, 12))) / pow(2, 11);
    double X4 = ((double)ac2 * B6) / pow(2, 11);
    double B3 = (((double)ac1 * 4 + X3 + X4 + 2) / 4);

    double X1_pressure = ((double)ac3 * B6) / pow(2, 13);
    double X2_pressure = ((double)b1 * (B6 * B6 / pow(2, 12))) / pow(2, 16);
    double X3_pressure = ((X1_pressure + X2_pressure + 2) / 4);
    double B4 = ((double)ac4 * (X3_pressure + 32768)) / pow(2, 15);
    double B7 = ((double)raw_pressure - B3) * (50000 / pow(2, oss));

    double p;
    if (B7 < 0) {
        p = (B7 * 2) / B4;
    } else {
        p = (B7 / B4) * 2;
    }

    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);
    p = p + (X1 + X2 + 3791) / pow(2, 4);

    return p;
}

// Function to log data to a file
void log_data(double pressure)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user)
{
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    // Debounce the interrupt
    if (interrupt_active) {
        double time_diff = (now.tv_sec - last_interrupt_time.tv_sec) * 1000.0 +
                           (now.tv_nsec - last_interrupt_time.tv_nsec) / 1000000.0;

        if (time_diff < DEBOUNCE_TIME) {
            return; // Ignore the interrupt
        }
    }

    interrupt_active = true;
    last_interrupt_time = now;

    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");

    // Wait for the debounce time
    gpioDelay(DEBOUNCE_TIME * 1000); // Convert ms to us
    interrupt_active = false;
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup()
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

