#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define HEATER_GPIO 17
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 80.0
#define LOG_FILE "heater_log.csv"
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
float calculate_duty_cycle(float current_temperature, float target_temperature, float *integral, float *previous_error);
void set_heater_duty_cycle(float duty_cycle);
void log_data(float temperature, float duty_cycle);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char spi_data[4];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = spiRead(spi_handle, spi_data, 4);
        if (result == 4) {
            break; // Success
        } else {
            fprintf(stderr, "SPI read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "SPI read failed after %d retries.\n", MAX_RETRIES);
        return -273.15; // Return absolute zero as error indicator
    }

    // Check for fault conditions
    if (spi_data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -273.15;
    }
    if (spi_data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -273.15;
    }
    if (spi_data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -273.15;
    }

    // Extract temperature data (ignoring fault bits)
    int16_t raw_temp = ((spi_data[0] << 8) | spi_data[1]) >> 2;
    float temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate duty cycle using PI controller
float calculate_duty_cycle(float current_temperature, float target_temperature, float *integral, float *previous_error) {
    float error = target_temperature - current_temperature;
    float Kp = 10.0; // Proportional gain
    float Ki = 0.1;  // Integral gain
    float dt = 1.0;  // Time step (1 second)

    *integral += error * dt;
    float derivative = (error - *previous_error) / dt;

    float output = Kp * error + Ki * (*integral);

    // Anti-windup
    if (output > MAX_DUTY_CYCLE) {
        output = MAX_DUTY_CYCLE;
        *integral = (*integral - (output - Kp * error) / Ki);
    } else if (output < 0) {
        output = 0;
        *integral = (*integral - (output - Kp * error) / Ki);
    }

    *previous_error = error;

    return output;
}

// Function to set heater duty cycle using PWM
void set_heater_duty_cycle(float duty_cycle) {
    int pwm_value = (int)(duty_cycle * 255.0); // Convert percentage to PWM value (0-255)
    gpioPWM(HEATER_GPIO, pwm_value);
}

// Function to log data to file
void log_data(float temperature, float duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    gpioPWM(HEATER_GPIO, 0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output for PWM
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float integral = 0.0;
    float previous_error = 0.0;
    float temperature, duty_cycle;

    // Main loop
    while (!terminate) {
        temperature = read_temperature();

        if (temperature < -200) {
            fprintf(stderr, "Error reading temperature. Setting duty cycle to 0.\n");
            duty_cycle = 0.0;
        } else {
            duty_cycle = calculate_duty_cycle(temperature, TARGET_TEMPERATURE, &integral, &previous_error);
        }

        set_heater_duty_cycle(duty_cycle);
        log_data(temperature, duty_cycle);

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

