#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature file path
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp_milli_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1; // Indicate error
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error during fscanf\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp_milli_celsius;
}

// Function to set RGB LED color using PWM
int set_rgb_led(int red, int green, int blue) {
    if (gpioPWM(RED_PIN, 255 - red) < 0) {
        fprintf(stderr, "Error setting red PWM\n");
        return -1;
    }
    if (gpioPWM(GREEN_PIN, 255 - green) < 0) {
        fprintf(stderr, "Error setting green PWM\n");
        return -1;
    }
    if (gpioPWM(BLUE_PIN, 255 - blue) < 0) {
        fprintf(stderr, "Error setting blue PWM\n");
        return -1;
    }
    return 0;
}

int main() {
    int temp_milli_celsius;
    int red, green, blue;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(RED_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        temp_milli_celsius = read_cpu_temp();
        if (temp_milli_celsius == -1) {
            fprintf(stderr, "Failed to read temperature, skipping this cycle\n");
            sleep(0.5);
            continue;
        }

        // Determine RGB color based on temperature
        if (temp_milli_celsius < 40000) {
            red = 0;
            green = 0;
            blue = 255;
        } else if (temp_milli_celsius < 60000) {
            red = 0;
            green = 255;
            blue = 0;
        } else {
            red = 255;
            green = 0;
            blue = 0;
        }

        // Set RGB LED color
        if (set_rgb_led(red, green, blue) != 0) {
            fprintf(stderr, "Failed to set RGB LED color\n");
        }

        // Print temperature and PWM values
        printf("Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n", temp_milli_celsius, red, green, blue);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup before exiting
    printf("Cleaning up and exiting...\n");
    set_rgb_led(0, 0, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio

    return 0;
}

