#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define JSON_BUFFER_SIZE 128

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read DHT22 data
int read_dht22_data(DHT22Data *data) {
    int i, j;
    int data_bits[40];
    int checksum_calculated = 0;
    int checksum_received = 0;

    // 1. Send start signal
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // > 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 20-40us

    // 2. Switch to input mode
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // 3. Read response (40 bits)
    for (i = 0; i < 40; i++) {
        // Wait for the line to go low
        int timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1); // 1us delay
            timeout++;
            if (timeout > 100) {
