{
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to write a byte to the BMP180
int write_byte(int reg, int value)
{
    char buf[1];
    buf[0] = value;
    int result = i2cWriteI2CBlockData(i2c_handle, reg, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing byte 0x%02X to register 0x%02X: %d\n", value, reg, result);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_16(0xAA, &ac1) != 0) return -1;
    if (read_16(0xAC, &ac2) != 0) return -1;
    if (read_16(0xAE, &ac3) != 0) return -1;
    if (read_u16(0xB0, &ac4) != 0) return -1;
    if (read_u16(0xB2, &ac5) != 0) return -1;
    if (read_u16(0xB4, &ac6) != 0) return -1;
    if (read_16(0xB6, &b1) != 0) return -1;
    if (read_16(0xB8, &b2) != 0) return -1;
    if (read_16(0xBA, &mb) != 0) return -1;
    if (read_16(0xBC, &mc) != 0) return -1;
    if (read_16(0xBE, &md) != 0) return -1;

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int *raw_temperature)
{
    if (write_byte(BMP180_REG_CONTROL, 0x2E) != 0) return -1;
    gpioDelay(5); // Wait 4.5ms

    if (read_16(BMP180_REG_MSB, raw_temperature) != 0) return -1;
    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    if (write_byte(BMP180_REG_CONTROL, 0x34 + (OSS << 6)) != 0) return -1;
    gpioDelay(26); // Wait for conversion (26ms for OSS=3)

    char buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate the temperature in degrees Celsius
double calculate_temperature(int raw_temperature)
{
    long X1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;
    double temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate the pressure in hPa
double calculate_pressure(int raw_pressure, int raw_temperature)
{
    long X1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    long X4 = ((long)ac2 * B6) / pow(2, 11);
    long B3 = (((((long)ac1) * 4 + X3) << OSS) + 2) / 4;

    unsigned long X1_pressure = (unsigned long)ac3 * B6 / pow(2, 13);
    unsigned long X2_pressure = (unsigned long)b1 * (B6 * B6) / pow(2, 12);
    unsigned long X3_pressure = (X1_pressure + X2_pressure + 2) / 4;
    unsigned long B4 = (unsigned long)ac4 * (unsigned long)(X3_pressure + 32768) / pow(2, 15);
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> OSS);

    long p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1_pressure = (p / pow(2, 8)) * (p / pow(2, 8));
    X1_pressure = (X1_pressure * 3038) / pow(2, 16);
    X2_pressure = (-7357 * p) / pow(2, 16);

    double pressure = p + (X1_pressure + X2_pressure + 3791) / pow(2, 4);
    return pressure / 100.0; // Convert to hPa
}

// Function to log the pressure to a file
void log_pressure(double pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening pressure_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);
    fclose(fp);
}

// Interrupt handler for the button
void button_interrupt_handler(int gpio, int level, uint32_t tick)
{
    uint32_t current_time = gpioTick();
    if (current_time - last_interrupt_time > DEBOUNCE_TIME) {
        logging_enabled = !logging_enabled;
        last_interrupt_time = current_time;
        if (logging_enabled) {
            printf("Data logging enabled\n");
        } else {
            printf("Data logging disabled\n");
        }
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO 4 as input with pull-up resistor
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    // Set up interrupt handler for falling edge
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    int raw_temperature, raw_pressure;
    double temperature, pressure;

    // Main loop
    while (1) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temperature) != 0) {
                fprintf(stderr, "Error reading raw temperature\n");
                continue; // Continue to the next iteration
            }
            if (read_raw_pressure(&raw_pressure) != 0) {
                fprintf(stderr, "Error reading raw pressure\n");
                continue; // Continue to the next iteration
            }

            // Calculate temperature and pressure
            temperature = calculate_temperature(raw_temperature);
            pressure = calculate_pressure(raw_pressure, raw_temperature);

            // Log the pressure
            log_pressure(pressure);

            // Print temperature and pressure to console
            printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure);

            // Wait for the next logging interval
            gpioDelay(LOGGING_INTERVAL * 1000000); // Convert seconds to microseconds
        } else {
            // Wait for a short period before checking the button again
            gpioDelay(100000); // 0.1 seconds
        }
    }

    // Cleanup (should not reach here in normal operation due to the infinite loop)
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

