#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <curl/curl.h>
#include <pigpio.h>
#include <time.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define MAX_BACKOFF_DELAY 60 // seconds
#define JSON_BUFFER_SIZE 128

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int checksum_valid;
} DHT22Data;

// Global variables
static volatile int running = 1;
static char *api_url = "http://your-api-endpoint.com/api/humidity";

// Function prototypes
void signal_handler(int signal);
int initialize();
void cleanup();
int read_dht22(DHT22Data *data);
int validate_checksum(unsigned char *data);
int post_data(const char *json_string);
char* format_json(float temperature, float humidity);
void log_message(int priority, const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Received signal, shutting down...");
}

// Initialize pigpio and curl
int initialize() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        log_message(LOG_ERR, "curl_global_init failed");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    gpioTerminate();
    curl_global_cleanup();
    log_message(LOG_INFO, "Cleanup complete");
}

// Read data from DHT22 sensor
int read_dht22(DHT22Data *data) {
    int i, j;
    unsigned int tick;
    unsigned char raw_data[5] = {0};
    unsigned char checksum = 0;

    // Send start signal
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1000); // 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 20-40us
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read response
    for (i = 0; i < 40; i++) {
        tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 0) {
            if (gpioTick() - tick > 200) {
                log_message(LOG_ERR, "DHT22 timeout waiting for high");
                return 1;
            }
        }
        tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 1) {
            if (gpioTick() - tick > 200) {
                log_message(LOG_ERR, "DHT22 timeout waiting for low");
                return 1;
            }
        }
        if (gpioTick() - tick > 50) {
            raw_data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Validate checksum
    checksum = raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3];
    if (validate_checksum(raw_data) != 0) {
        log_message(LOG_ERR, "DHT22 checksum invalid");
        return 1;
    }

    // Convert data
    data->humidity = (float)(((raw_data[0] << 8) | raw_data[1])) / 10.0;
    data->temperature = (float)(((raw_data[2] << 8) | raw_data[3]) & 0x7FFF) / 10.0;
    if (raw_data[2] & 0x80) {
        data->temperature *= -1.0;
    }
    data->checksum_valid = 1;

    return 0;
}

// Validate checksum
int validate_checksum(unsigned char *data) {
    unsigned char checksum = data[0] + data[1] + data[2] + data[3];
    return (checksum == data[4]);
}

// Format data as JSON
char* format_json(float temperature, float humidity) {
    static char json_string[JSON_BUFFER_SIZE];
    snprintf(json_string, JSON_BUFFER_SIZE, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    return json_string;
}

// Post data to API endpoint
int post_data(const char *json_string) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, api_url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_string));

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            log_message(LOG_ERR, curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 200 && response_code < 300) {
                log_message(LOG_INFO, "Data posted successfully");
            } else {
                char error_message[100];
                snprintf(error_message, sizeof(error_message), "HTTP POST failed with code: %ld", response_code);
                log_message(LOG_ERR, error_message);
            }
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    } else {
        log_message(LOG_ERR, "curl_easy_init() failed");
        return 1;
    }

    return (res == CURLE_OK && response_code >= 200 && response_code < 300) ? 0 : 1;
}

// Log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main(int argc, char *argv[]) {
    int opt;
    DHT22Data dht22_data;
    int retries = 0;
    int backoff_delay = 2;
    int dht22_read_attempts = 0;
    int dht22_read_success = 0;
    char *json_string = NULL;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <api_url>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and curl
    if (initialize() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "DHT22 monitor started");

    while (running) {
        dht22_read_attempts = 0;
        dht22_read_success = 0;

        while (dht22_read_attempts < MAX_RETRIES && !dht22_read_success) {
            if (read_dht22(&dht22_data) == 0 && dht22_data.checksum_valid) {
                dht22_read_success = 1;
                dht22_read_attempts = MAX_RETRIES; // Exit the retry loop
            } else {
                dht22_read_attempts++;
                char error_message[100];
                snprintf(error_message, sizeof(error_message), "DHT22 read failed, attempt %d", dht22_read_attempts);
                log_message(LOG_WARNING, error_message);
                gpioDelay(backoff_delay * 1000); // Exponential backoff
                backoff_delay *= 2;
                if (backoff_delay > MAX_BACKOFF_DELAY) {
                    backoff_delay = MAX_BACKOFF_DELAY;
                }
            }
        }

        if (dht22_read_success) {
            json_string = format_json(dht22_data.temperature, dht22_data.humidity);
            retries = 0;
            backoff_delay = 2;

            while (retries < MAX_RETRIES) {
                if (post_data(json_string) == 0) {
                    break; // Exit the retry loop
                } else {
                    retries++;
                    char error_message[100];
                    snprintf(error_message, sizeof(error_message), "HTTP POST failed, attempt %d", retries);
                    log_message(LOG_WARNING, error_message);
                    gpioDelay(backoff_delay * 1000); // Exponential backoff
                    backoff_delay *= 2;
                    if (backoff_delay > MAX_BACKOFF_DELAY) {
                        backoff_delay = MAX_BACKOFF_DELAY;
                    }
                }
            }

            if (retries == MAX_RETRIES) {
                log_message(LOG_ERR, "HTTP POST failed after multiple retries");
            }
        } else {
            log_message(LOG_ERR, "DHT22 read failed after multiple retries");
        }

        gpioDelay(10000); // 10 seconds
    }

    // Cleanup resources
    cleanup();

    // Close syslog
    closelog();

    return EXIT_SUCCESS;
}

