#include <sys/types.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_STATES 4

volatile sig_atomic_t program_running = 1;

// Function to read the CPU temperature from the specified file.
int read_temperature(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    char buffer[10];
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Error reading temperature file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return atoi(buffer);
}

// Function to read the current fan state from the specified file.
int read_fan_state(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening fan state file");
        return -1;
    }

    char buffer[2];
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Error reading fan state file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return atoi(buffer);
}

// Function to write the fan state to the specified file.
int write_fan_state(const char *filename, int state) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("Error opening fan state file for writing");
        return -1;
    }

    fprintf(fp, "%d", state);
    fclose(fp);
    return 0;
}

// Function to log messages to the specified log file.
int log_message(const char *filename, const char *message) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// Function to determine the fan state based on the temperature.
int determine_fan_state(int temperature) {
    if (temperature < 45000) {
        return 0;
    } else if (temperature < 55000) {
        return 1;
    } else if (temperature < 65000) {
        return 2;
    } else {
        return 3;
    }
}

// Function to handle signals (SIGINT, SIGTERM).
void signal_handler(int signal) {
    program_running = 0;
    log_message(LOG_FILE, "Received signal, shutting down...");
}

int main() {
    // Set up signal handling for graceful shutdown.
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check if the log file exists and is writable.
    if (access(LOG_FILE, W_OK) != 0) {
        fprintf(stderr, "Error: Cannot write to log file %s. Please check permissions.\n", LOG_FILE);
        return 1;
    }

    // Main loop.
    while (program_running) {
        // Read the CPU temperature.
        int temperature = read_temperature(TEMP_FILE);
        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Read the current fan state.
        int current_fan_state = read_fan_state(FAN_FILE);
        if (current_fan_state == -1) {
            fprintf(stderr, "Error reading fan state, retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Determine the desired fan state based on the temperature.
        int desired_fan_state = determine_fan_state(temperature);

        // Check if the desired fan state is valid.
        if (desired_fan_state < 0 || desired_fan_state > MAX_STATES) {
            fprintf(stderr, "Error: Invalid fan state %d, using current state.\n", desired_fan_state);
            desired_fan_state = current_fan_state;
        }

        // If the desired fan state is different from the current state, update the fan state.
        if (desired_fan_state != current_fan_state) {
            if (write_fan_state(FAN_FILE, desired_fan_state) == 0) {
                // Log the fan state change.
                char log_message_buffer[256];
                snprintf(log_message_buffer, sizeof(log_message_buffer), "Temperature: %d, Fan state: %d", temperature, desired_fan_state);
                log_message(LOG_FILE, log_message_buffer);
            } else {
                fprintf(stderr, "Error writing fan state, retrying in 5 seconds.\n");
            }
        }

        // Wait for 5 seconds.
        sleep(5);
    }

    // Shutdown sequence: set fan to 0 and log the event.
    if (write_fan_state(FAN_FILE, 0) == 0) {
        log_message(LOG_FILE, "Fan shutdown.");
    } else {
        fprintf(stderr, "Error shutting down fan.\n");
    }

    return 0;
}

