#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define HEATER_PIN 18
#define SPI_CE0_PIN 8
#define SPI_CE1_PIN 7

// Define PWM parameters
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 100

// Define PID parameters
float Kp = 1.0;
float Ki = 0.1;
float Kd = 0.01;

// Define temperature limits
#define MIN_TEMP 0.0
#define MAX_TEMP 100.0

// Define log file name
#define LOG_FILE "heater_log.txt"

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
float read_temperature(int spi_channel);
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error);
void set_pwm_duty_cycle(int duty_cycle);
void log_data(float temperature, int duty_cycle, float pid_output);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from MAX31855
float read_temperature(int spi_channel) {
    unsigned char data[4];
    int i;
    float temperature = -1000.0; // Initialize with an invalid value
    int fault = 0;

    if (spi_channel == 0) {
        wiringPiSPIDataRW(0, data, 4);
    } else if (spi_channel == 1) {
        wiringPiSPIDataRW(1, data, 4);
    } else {
        fprintf(stderr, "Error: Invalid SPI channel: %d\n", spi_channel);
        return -1000.0; // Indicate an error
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "Error: Thermocouple open circuit\n");
        fault = 1;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "Error: Thermocouple shorted to GND\n");
        fault = 1;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "Error: Thermocouple shorted to VCC\n");
        fault = 1;
    }

    if (fault) {
        return -1000.0; // Indicate an error
    }

    // Extract temperature data
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    pwmWrite(HEATER_PIN, duty_cycle);
}

// Function to log data to file
void log_data(float temperature, int duty_cycle, float pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %d, %.2f\n", timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function to turn off heater and close SPI
void cleanup() {
    printf("Cleaning up...\n");
    set_pwm_duty_cycle(0); // Turn off heater
    if (log_file != NULL) {
        fclose(log_file);
    }
    wiringPiSPIClose(0);
    wiringPiSPIClose(1);
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Unable to initialize wiringPi\n");
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(0, 500000) == -1) { // SPI0, 500kHz
        fprintf(stderr, "Error: Unable to initialize SPI0\n");
        return 1;
    }
    if (wiringPiSPISetup(1, 500000) == -1) { // SPI1, 500kHz
        fprintf(stderr, "Error: Unable to initialize SPI1\n");
        return 1;
    }

    // Configure GPIO18 as PWM output
    pinMode(HEATER_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(192); // Adjust clock to achieve desired frequency (1000Hz)

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Unable to open log file\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float setpoint = 50.0;
    float integral = 0.0;
    float previous_error = 0.0;
    float pid_output;
    float temperature;
    int duty_cycle;

    printf("Temperature control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read temperature from both thermocouples
        temperature = read_temperature(0);
        if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
            fprintf(stderr, "Error: Invalid temperature reading from thermocouple 0\n");
            set_pwm_duty_cycle(0);
            integral = 0.0;
            previous_error = 0.0;
        } else {
            pid_output = calculate_pid(setpoint, temperature, &integral, &previous_error);
            duty_cycle = (int)pid_output;
            set_pwm_duty_cycle(duty_cycle);
            log_data(temperature, duty_cycle, pid_output);
        }

        temperature = read_temperature(1);
        if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
            fprintf(stderr, "Error: Invalid temperature reading from thermocouple 1\n");
            set_pwm_duty_cycle(0);
            integral = 0.0;
            previous_error = 0.0;
        } else {
            pid_output = calculate_pid(setpoint, temperature, &integral, &previous_error);
            duty_cycle = (int)pid_output;
            set_pwm_duty_cycle(duty_cycle);
            log_data(temperature, duty_cycle, pid_output);
        }

        delay(1000); // Wait for 1 second
    }

    cleanup();

    return 0;
}

