// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define FLOW_LOG_FILE "flow_log.txt"
#define MAX_RETRIES 3

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int i2c_handle, float *flow_rate);
int validate_crc(const unsigned char *data, int len);
int log_flow_data(float flow1, float flow2);
void signal_handler(int signal);

// CRC-8 checksum calculation (CRC8-Maxim)
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from a sensor
int read_sensor(int i2c_handle, float *flow_rate) {
    unsigned char data[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 3);
        if (bytes_read == 3) {
            // Validate CRC
            if (validate_crc(data, 3)) {
                // Convert data to flow rate (example conversion, adjust as needed)
                int raw_flow = (data[0] << 8) | data[1];
                *flow_rate = (float)raw_flow / 100.0; // Example scaling
                return 0; // Success
            } else {
                fprintf(stderr, "CRC check failed for sensor (handle %d). Retrying...\n", i2c_handle);
                retries++;
                gpioDelay(10000); // 10ms delay
            }
        } else {
            fprintf(stderr, "I2C read error (handle %d). Retrying...\n", i2c_handle);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read sensor after %d retries (handle %d).\n", MAX_RETRIES, i2c_handle);
    return -1; // Failure
}

// Function to validate CRC checksum
int validate_crc(const unsigned char *data, int len) {
    unsigned char crc_calculated = crc8(data, len - 1);
    return (crc_calculated == data[len - 1]);
}

// Function to log flow data to a file
int log_flow_data(float flow1, float flow2) {
    FILE *fp = fopen(FLOW_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow1, flow2;

    // Main loop
    while (!terminate) {
        // Read data from sensor 1
        if (read_sensor(i2c_handle1, &flow1) == 0) {
            // Read data from sensor 2
            if (read_sensor(i2c_handle2, &flow2) == 0) {
                // Log the data
                if (log_flow_data(flow1, flow2) != 0) {
                    fprintf(stderr, "Error logging data!\n");
                }
            } else {
                fprintf(stderr, "Error reading sensor 2!\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor 1!\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Close I2C handles and terminate pigpio
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

