#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
volatile int current_state = 0; // 0: 00, 1: 01, 2: 11, 3: 10
volatile int last_state = 0;
volatile double angular_position = 0.0;
volatile int running = 1; // Flag to control the main loop

// Function prototypes
int initialize_gpio();
int read_sensor_a();
int read_sensor_b();
int update_state(int a, int b);
double calculate_angle(int new_state);
void log_position(double angle);
void signal_handler(int signal);

// Structure to hold GPIO pin configurations
typedef struct {
    int sensor_a_pin;
    int sensor_b_pin;
} gpio_config_t;

// Structure to hold program state
typedef struct {
    double angular_position;
    int current_state;
    int last_state;
} program_state_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);

    gpioSetMode(SENSOR_B_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read the state of sensor A
int read_sensor_a() {
    return gpioRead(SENSOR_A_PIN);
}

// Function to read the state of sensor B
int read_sensor_b() {
    return gpioRead(SENSOR_B_PIN);
}

// Function to update the state based on sensor A and B readings
int update_state(int a, int b) {
    int new_state = current_state;

    if (a == 0 && b == 1) {
        new_state = 1;
    } else if (a == 1 && b == 1) {
        new_state = 2;
    } else if (a == 1 && b == 0) {
        new_state = 3;
    }

    return new_state;
}

// Function to calculate the angular position based on the new state
double calculate_angle(int new_state) {
    double angle = 0.0;
    double angle_increment = 360.0 / 360.0; // 360 pulses per revolution

    switch (new_state) {
        case 1:
            angle = angle_increment;
            break;
        case 2:
            angle = angle_increment * 2;
            break;
        case 3:
            angle = angle_increment * 3;
            break;
        default:
            angle = 0.0;
            break;
    }

    return angle;
}

// Function to log the angular position to a file
void log_position(double angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, angle);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0; // Stop the main loop
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int a = read_sensor_a();
        int b = read_sensor_b();
        int new_state = update_state(a, b);

        if (new_state != current_state) {
            double angle = calculate_angle(new_state);
            angular_position = angle;
            log_position(angular_position);
            current_state = new_state;
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    return 0;
}

