    } else if (a == 1 && b == 1) {
        new_state = 2;
    } else if (a == 1 && b == 0) {
        new_state = 3;
    }

    return new_state;
}

// Function to calculate the angular position based on the new state
double calculate_angle(int new_state) {
    double angle = 0.0;
    double angle_increment = 360.0 / 360.0; // 360 pulses per revolution

    switch (new_state) {
        case 1:
            angle = angle_increment;
            break;
        case 2:
            angle = angle_increment * 2;
            break;
        case 3:
            angle = angle_increment * 3;
            break;
        default:
            angle = 0.0;
            break;
    }

    return angle;
}

// Function to log the angular position to a file
void log_position(double angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, angle);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0; // Stop the main loop
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int a = read_sensor_a();
        int b = read_sensor_b();
        int new_state = update_state(a, b);

        if (new_state != current_state) {
            double angle = calculate_angle(new_state);
            angular_position = angle;
            log_position(angular_position);
            current_state = new_state;
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    return 0;
}

