    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&red_value, &ir_value) == 0) {
            // Get current timestamp
            current_time = time(NULL);

            // Log data
            log_data(current_time, red_value, ir_value);

            // Control LED
            control_led(ir_value);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

