// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x36
#define FLOW_LOG_FILE "flow_log.csv"
#define FLOW_ERROR_LOG_FILE "flow_error.log"
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 4000.0
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(unsigned char *data);
float calculate_flow_rate(unsigned char *data);
int log_flow_rate(float flow_rate);
int log_error(const char *message);
void signal_handler(int signal);
unsigned char crc8(const unsigned char *data, int len);

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(unsigned char *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Calculate flow rate
float calculate_flow_rate(unsigned char *data) {
    unsigned int raw_value = (data[0] << 8) | data[1];
    unsigned char crc = data[2];

    if (crc8(data, 2) != crc) {
        fprintf(stderr, "CRC check failed\n");
        return -1.0; // Indicate CRC error
    }

    // Convert raw value to flow rate (uL/min)
    float flow_rate = (float)raw_value / 100.0; // Example conversion, adjust as needed
    return flow_rate;
}

// Log flow rate to CSV file
int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Log errors to error log file
int log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (error_log_file == NULL) {
        fprintf(stderr, "Error log file is not open\n");
        return -1;
    }

    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", FLOW_LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(FLOW_ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Error opening error log file: %s\n", FLOW_ERROR_LOG_FILE);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        log_error("I2C initialization failed");
        fclose(log_file);
        fclose(error_log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    unsigned char sensor_data[3];
    float flow_rate;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(sensor_data) == 0) {
            flow_rate = calculate_flow_rate(sensor_data);
            if (flow_rate >= FLOW_RATE_MIN && flow_rate <= FLOW_RATE_MAX) {
                if (log_flow_rate(flow_rate) != 0) {
                    log_error("Failed to log flow rate");
                }
            } else {
                log_error("Flow rate out of range");
            }
        } else {
            log_error("Failed to read sensor data");
        }

        gpioDelay(1000); // Wait 1000 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    fclose(error_log_file);
    gpioTerminate();

    return 0;
}

