    float iaq;
} sensor_data_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(unsigned char *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 9); // Read 9 bytes
    if (bytes_read != 9) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to calculate IAQ index (example formula)
int calculate_iaq_index(unsigned char *data, float *tvoc, float *eco2) {
    // Example conversion (replace with actual sensor datasheet values)
    *tvoc = (float)((data[0] << 8) | data[1]) / 10.0; // Example: TVOC in ppb
    *eco2 = (float)((data[2] << 8) | data[3]) / 10.0; // Example: eCO2 in ppm

    // Example IAQ calculation (replace with actual formula)
    float iaq = 100.0 - (*tvoc / 500.0 * 50.0); // Example IAQ index
    if (iaq < 0) iaq = 0;
    if (iaq > 100) iaq = 100;

    return (int)iaq;
}

// Function to log data to CSV file
int log_data(float iaq, float tvoc, float eco2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, iaq, tvoc, eco2);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IAQ,TVOC (ppb),eCO2 (ppm)\n");
    }
    fflush(log_file);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    unsigned char sensor_data[9];
    float iaq, tvoc, eco2;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Calculate IAQ index
            if (calculate_iaq_index(sensor_data, &tvoc, &eco2) != -1) {
                // Log data
                if (log_data(iaq, tvoc, eco2) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Error calculating IAQ index\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for the next interval
        gpioDelay(READ_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

