#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 17
#define POLLING_INTERVAL_MS 100
#define TAMPER_DURATION_S 5

static volatile int running = 1;
static volatile int tamper_detected = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to read the sensor value
int read_sensor() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the intrusion event
void log_intrusion() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    printf("Intrusion detected at: %s\n", buf);
}

// Function to cleanup GPIO resources
void cleanup() {
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set GPIO pin as input
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Set consumer label (optional, but recommended)
    if (gpioSetConsumerLabel(GPIO_PIN, "ttp223_tamper") != 0) {
        fprintf(stderr, "Failed to set consumer label for GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tamper detection system started. Monitoring GPIO %d...\n", GPIO_PIN);

    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            cleanup();
            return EXIT_FAILURE;
        }

        if (sensor_value == 1) { // Sensor is touched (HIGH)
            if (!tamper_detected) {
                tamper_detected = 1;
                printf("Tamper detected!\n");
                log_intrusion();
            }
        } else { // Sensor is released (LOW)
            tamper_detected = 0;
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay for 100ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

