#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>
#include <errno.h>

// Configuration
#define ALSA_DEVICE "default" // Or "hw:0,0" for specific hardware
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define SAMPLE_SIZE 2 // 16-bit samples
#define GPIO_PIN 17
#define FILE_NAME "audio_capture.pcm"
#define BUFFER_SIZE 1024

// Global variables
snd_pcm_t *pcm_handle = NULL;
FILE *audio_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold ALSA configuration
typedef struct {
    snd_pcm_hw_params_t *hw_params;
} alsa_config_t;

// Function prototypes
int initialize_alsa(alsa_config_t *config);
int select_left_channel();
int write_audio_data(const short *buffer, size_t frames);
void signal_handler(int sig);
void cleanup();
int capture_audio(alsa_config_t *config);

// Signal handler for graceful termination
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize ALSA
int initialize_alsa(alsa_config_t *config) {
    int err;
    snd_pcm_hw_params_t *hw_params;

    // Open PCM device for capture
    if ((err = snd_pcm_open(&pcm_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&hw_params);

    // Initialize hardware parameters
    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set access type to interleaved
    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set sample format to 16-bit signed integer
    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting sample format: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set number of channels
    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting number of channels: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set sample rate
    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Apply hardware parameters
    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    config->hw_params = hw_params; // Store hw_params for later cleanup
    return 0;
}

// Select left channel using GPIO
int select_left_channel() {
    if (gpioWrite(GPIO_PIN, 0) != 0) { // Set GPIO low to select left channel
        fprintf(stderr, "Error writing to GPIO pin: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Write audio data to file
int write_audio_data(const short *buffer, size_t frames) {
    size_t bytes_to_write = frames * NUM_CHANNELS * SAMPLE_SIZE;
    size_t bytes_written = fwrite(buffer, 1, bytes_to_write, audio_file);

    if (bytes_written != bytes_to_write) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Capture audio data
int capture_audio(alsa_config_t *config) {
    short *buffer = (short *)malloc(BUFFER_SIZE * NUM_CHANNELS * SAMPLE_SIZE / SAMPLE_SIZE); // Allocate buffer for interleaved data
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating buffer\n");
        return -1;
    }

    int err;
    while (!terminate) {
        if ((err = snd_pcm_readi(pcm_handle, buffer, BUFFER_SIZE)) != BUFFER_SIZE) {
            fprintf(stderr, "Error reading from PCM device: %s\n", snd_strerror(err));
            free(buffer);
            return -1;
        }

        if (write_audio_data(buffer, BUFFER_SIZE) != 0) {
            free(buffer);
            return -1;
        }
    }

    free(buffer);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (pcm_handle != NULL) {
        snd_pcm_close(pcm_handle);
    }

    if (audio_file != NULL) {
        fclose(audio_file);
    }

    if (config != NULL && config->hw_params != NULL) {
        snd_pcm_hw_params_free(config->hw_params);
    }

    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Select left channel
    if (select_left_channel() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open audio file
    audio_file = fopen(FILE_NAME, "wb");
    if (audio_file == NULL) {
        fprintf(stderr, "Error opening audio file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    alsa_config_t alsa_config;

    // Initialize ALSA
    if (initialize_alsa(&alsa_config) != 0) {
        fclose(audio_file);
        gpioTerminate();
        return 1;
    }

    // Capture audio
    if (capture_audio(&alsa_config) != 0) {
        cleanup();
        return 1;
    }

    // Cleanup resources
    cleanup();

    printf("Audio capture complete.\n");
    return 0;
}

