#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define PWM_FREQUENCY 100
#define SENSOR_TIMEOUT_MS 1000 // 1 second timeout
#define LOG_FILE "flame_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static time_t program_start_time;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected);
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int flame_detected;
    time_t flame_start_time;
} ProgramState;

ProgramState state = {0, 0};

int main() {
    // Initialize program start time
    program_start_time = time(NULL);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    log_event("Program Start", "Program started successfully.");

    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == -1) {
            // Sensor timeout
            log_event("Sensor Timeout", "Sensor reading timeout. Check connection.");
            state.flame_detected = 0; // Ensure fan stops
            control_fan(0);
            sleep(1); // Wait before retrying
            continue;
        }

        if (sensor_value == 0) { // Flame detected (LOW signal)
            if (!state.flame_detected) {
                // Flame detected for the first time
                state.flame_detected = 1;
                state.flame_start_time = time(NULL);
                control_fan(1);
                log_event("Flame Detected", "Flame detected by sensor.");
            }
        } else { // No flame (HIGH signal)
            if (state.flame_detected) {
                // Flame ended
                time_t current_time = time(NULL);
                double flame_duration = difftime(current_time, state.flame_start_time);
                char message[100];
                snprintf(message, sizeof(message), "Flame ended. Duration: %.2f seconds.", flame_duration);
                log_event("Flame Ended", message);
