#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define FRAME_PERIOD_MS 100
#define FRAME_SIZE 32768 // 64 chirps * 256 samples * 2 (real/imaginary)
#define GPIO_FRAME_TRIGGER 23
#define GPIO_DATA_READY 24
#define MAGIC_NUMBER 0x41444646 // "A D F F"

// Data structure for configuration
typedef struct {
    float start_frequency;
    float end_frequency;
    int num_chirps;
    int num_samples;
} radar_config_t;

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int configure_radar(radar_config_t config);
int read_frame(uint8_t *data);
int write_data_to_file(uint8_t *data, size_t size);
int write_header(radar_config_t config);
int handle_interrupt(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and GPIO pins
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_FRAME_TRIGGER, PI_OUTPUT);
    gpioSetMode(GPIO_DATA_READY, PI_INPUT);
    gpioSetPullUpDown(GPIO_DATA_READY, PI_PUD_DOWN);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

