           config.start_frequency, config.end_frequency, config.num_chirps, config.num_samples);
    return 0;
}

// Function to read a single frame of data from the AWR1642
int read_frame(uint8_t *data) {
    // In a real application, this function would read data from the AWR1642
    // via SPI.  This is a placeholder that just fills the buffer with dummy data.
    memset(data, 0xAA, FRAME_SIZE); // Fill with a pattern for testing
    return 0;
}

// Function to write data to the log file
int write_data_to_file(uint8_t *data, size_t size) {
    if (fwrite(data, 1, size, log_file) != size) {
        fprintf(stderr, "Error writing data to file\n");
        return -1;
    }
    return 0;
}

// Function to write the header to the log file
int write_header(radar_config_t config) {
    uint32_t magic_number = MAGIC_NUMBER;
    uint64_t timestamp = time(NULL);

    if (fwrite(&magic_number, 4, 1, log_file) != 1) {
        fprintf(stderr, "Error writing magic number to file\n");
        return -1;
    }

    if (fwrite(&timestamp, 8, 1, log_file) != 1) {
        fprintf(stderr, "Error writing timestamp to file\n");
        return -1;
    }

    if (fwrite(&config, sizeof(radar_config_t), 1, log_file) != 1) {
        fprintf(stderr, "Error writing config to file\n");
        return -1;
    }

    return 0;
}

// Function to handle the data-ready interrupt
void handle_interrupt(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        uint8_t frame_data[FRAME_SIZE];
        if (read_frame(frame_data) == 0) {
            // Get timestamp
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            uint64_t timestamp = (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;

            // Write data to file
            if (write_data_to_file(frame_data, FRAME_SIZE) != 0) {
                fprintf(stderr, "Error writing frame data to file\n");
            }

            // Write timestamp and frame number to file
            uint32_t frame_number = 1; // Increment frame number
            if (fwrite(&timestamp, 8, 1, log_file) != 1) {
                fprintf(stderr, "Error writing timestamp to file\n");
            }
            if (fwrite(&frame_number, 4, 1, log_file) != 1) {
                fprintf(stderr, "Error writing frame number to file\n");
            }
        } else {
            fprintf(stderr, "Error reading frame data\n");
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Configure radar
    radar_config_t config = {77.0, 79.0, 64, 256};
    if (configure_radar(config) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("radar_data.bin", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header
    if (write_header(config) != 0) {
        cleanup();
        return 1;
    }

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_DATA_READY, RISING_EDGE, 0, handle_interrupt, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Trigger frame (optional, if the radar requires a trigger)
        gpioWrite(GPIO_FRAME_TRIGGER, 1);
        gpioDelay(10); // 10 us trigger pulse
        gpioWrite(GPIO_FRAME_TRIGGER, 0);
        gpioDelay(FRAME_PERIOD_MS * 1000); // Wait for the frame period
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

