    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        current_state = gpioRead(GPIO_PIN);

        if (current_state != previous_state) {
            if (log_flame_state(current_state) == 0) {
                printf("Flame state changed to: %d\n", current_state);
            } else {
                fprintf(stderr, "Failed to log flame state.\n");
