#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LUX_SCALE 0.01
#define LUX_OFFSET 1.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define ISO8601_BUFFER_SIZE 32

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_opt3001();
int read_opt3001_lux(float *lux);
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional, but good practice)
typedef struct {
    int i2c_bus;
    int opt3001_address;
    char *log_file_name;
} config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure OPT3001
int configure_opt3001() {
    uint16_t config_value = 0x0100; // Continuous conversion mode, auto full-scale range
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF;
    buf[2] = config_value & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to OPT3001 config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read OPT3001 lux value
int read_opt3001_lux(float *lux) {
    char buf[2];
    int result;
    uint16_t raw_result;

    // Read result register
    buf[0] = RESULT_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to OPT3001 result register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from OPT3001 result register: %d\n", result);
        return -1;
    }

    raw_result = (buf[0] << 8) | buf[1];
    *lux = (float)(raw_result & 0x0FFF) * LUX_SCALE + LUX_OFFSET;

    return 0;
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = gmtime(&timer);

    strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
    return timestamp_buffer;
}

// Log data to file
int log_data(float lux) {
    char timestamp[ISO8601_BUFFER_SIZE];
    get_iso8601_timestamp(timestamp, ISO8601_BUFFER_SIZE);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    config_t config = {
        .i2c_bus = I2C_BUS,
        .opt3001_address = OPT3001_ADDR,
        .log_file_name = "light_data.txt"
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure OPT3001
    if (configure_opt3001() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int retry;

    // Main loop
    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_opt3001_lux(&lux) == 0) {
                if (log_data(lux) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "I2C read failed. Retry %d/%d\n", retry + 1, RETRY_COUNT);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retry++;
            }
        }
        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read lux value after %d retries.\n", RETRY_COUNT);
        }
        gpioDelay(100 * 1000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

