#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_INTERVAL_SEC 1

static volatile sig_atomic_t terminate = 0;

void sigint_handler(int signal)
{
    terminate = 1;
}

int main()
{
    int pigpio_init_result;
    int gpio_mode_result;
    int gpio_read_result;
    char timestamp[20];
    struct timespec ts;
    struct tm tm_info;

    // Register signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize pigpio library
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO pin mode to input with pull-up resistor
    gpio_mode_result = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (gpio_mode_result != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode: %d\n", GPIO_PIN, gpio_mode_result);
        gpioTerminate();
        return 1;
    }

    gpio_mode_result = gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    if (gpio_mode_result != 0) {
        fprintf(stderr, "Failed to set GPIO %d pull-up: %d\n", GPIO_PIN, gpio_mode_result);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read GPIO pin value
        gpio_read_result = gpioRead(GPIO_PIN);
        if (gpio_read_result < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %d\n", GPIO_PIN, gpio_read_result);
            break; // Exit loop on read error
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break; // Exit loop on timestamp error
        }

        // Format timestamp
        tm_info = *localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

        // Log status
        if (gpio_read_result == 0) {
            printf("%s Flame Detected: YES\n", timestamp);
        } else {
            printf("%s Flame Detected: NO\n", timestamp);
        }

        // Wait for 1 second
        gpioDelay(LOG_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Cleanup
    gpioTerminate();

    return 0;
}

