#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define the GPIO pins connected to the TTP226 channels
const int gpio_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = 8;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the state of all channels
int read_channels(int gpio_pins[], int num_channels, int *channel_states) {
    for (int i = 0; i < num_channels; i++) {
        int value = gpioRead(gpio_pins[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pins[i], value);
            return -1; // Indicate an error
        }
        channel_states[i] = value;
    }
    return 0; // Indicate success
}

// Function to format the channel states into a string
void format_channel_states(int channel_states[], char *buffer, int buffer_size) {
    buffer[0] = '\0'; // Initialize the buffer
    for (int i = 0; i < num_channels; i++) {
        char temp[2];
        sprintf(temp, "%d", channel_states[i]);
        strcat(buffer, temp);
        if (i < num_channels - 1) {
            strcat(buffer, ",");
        }
    }
}

// Function to get the current timestamp as a string
void get_timestamp(char *timestamp_buffer, int buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp_buffer, buffer_size, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Configure the GPIO pins as inputs
    for (int i = 0; i < num_channels; i++) {
        gpioSetMode(gpio_pins[i], PI_INPUT);
    }

    // Allocate memory for channel states
    int *channel_states = (int *)malloc(num_channels * sizeof(int));
    if (channel_states == NULL) {
        fprintf(stderr, "Failed to allocate memory for channel states\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read the channel states
        if (read_channels(gpio_pins, num_channels, channel_states) != 0) {
            fprintf(stderr, "Error reading channels, exiting...\n");
            break; // Exit the loop if there's an error
        }

        // Format the channel states into a string
        char channel_state_str[17]; // 8 channels * 1 digit + 7 commas + null terminator
        format_channel_states(channel_states, channel_state_str, sizeof(channel_state_str));

        // Get the current timestamp
        char timestamp[20];
        get_timestamp(timestamp, sizeof(timestamp));

        // Print the timestamp and channel states to the console
        printf("%s: %s\n", timestamp, channel_state_str);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
