void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the state of a single sensor channel
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to generate an ISO 8601 timestamp string
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Configure each sensor pin as an input with pull-up disabled
    for (int i = 0; i < num_sensors; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set mode for pin %d\n", sensor_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_OFF) != 0) {
            fprintf(stderr, "Failed to set pull-up/down for pin %d\n", sensor_pins[i]);
            gpioTerminate();
            return 1;
        }
