#define TILT_SENSOR_GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int current_state = -1; // Initialize to an invalid state
    int previous_state = -1;

    // Register signal handler for SIGINT (Ctrl+C)
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO4 as an input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        current_state = gpioRead(TILT_SENSOR_GPIO);

        if (current_state == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", TILT_SENSOR_GPIO);
            gpioTerminate();
            return 1;
        }

        if (current_state != previous_state) {
            if (current_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout); // Flush the output buffer
            previous_state = current_state;
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

