#define SI1145_ADDR 0x60
#define CSV_FILE "uv_als_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_si1145(uint16_t *uv_index, uint16_t *als_visible);
int log_data(uint16_t uv_index, uint16_t als_visible);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    uint16_t uv_index;
    uint16_t als_visible;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from Si1145 sensor
int read_si1145(uint16_t *uv_index, uint16_t *als_visible) {
    char buf[4];
    int result;

    // Read UV index (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, 0x2C, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading UV index: %d\n", result);
        return -1;
    }
    *uv_index = (buf[1] << 8) | buf[0];

    // Read ALS visible (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, 0x22, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS visible: %d\n", result);
        return -1;
    }
    *als_visible = (buf[1] << 8) | buf[0];

    return 0;
}

// Function to log data to CSV file
int log_data(uint16_t uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file for appending
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }
    rewind(log_file);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_si1145(&sensor_data.uv_index, &sensor_data.als_visible) == 0) {
            printf("UV Index: %u, ALS Visible: %u\n", sensor_data.uv_index, sensor_data.als_visible);
            log_data(sensor_data.uv_index, sensor_data.als_visible);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 1 second.\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

