#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define ALARM_GPIO 17
#define FLOW_MIN 0.5 // ml/min
#define START_CMD_1 0x3060
#define START_CMD_2 0x3061
#define MEASURE_CMD 0x0000
#define CRC_POLYNOMIAL 0x31 // x^8 + x^5 + x^4 + 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int start_sensor(int i2c_handle);
int read_sensor(int i2c_handle, float *flow_rate);
int validate_crc(unsigned char data[], int len);
float calculate_average_flow(float flow1, float flow2);
void log_data(float average_flow);
void set_alarm(float average_flow);
void signal_handler(int signal);

// CRC calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to start the sensor
int start_sensor(int i2c_handle) {
    char buf[2];
    buf[0] = (START_CMD_1 >> 8) & 0xFF;
    buf[1] = START_CMD_1 & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing start command 1\n");
        return -1;
    }
    gpioDelay(100); // Wait 100ms

    buf[0] = (START_CMD_2 >> 8) & 0xFF;
    buf[1] = START_CMD_2 & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing start command 2\n");
        return -1;
    }
    gpioDelay(100); // Wait 100ms

    return 0;
}

// Function to read the sensor data
int read_sensor(int i2c_handle, float *flow_rate) {
    char buf[2];
    char data[3];

    buf[0] = (MEASURE_CMD >> 8) & 0xFF;
    buf[1] = MEASURE_CMD & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing measure command\n");
        return -1;
    }

    gpioDelay(10); // Small delay for measurement

    if (i2cReadDevice(i2c_handle, data, 3) != 3) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    // CRC validation
    if (validate_crc(data, 3) != 0) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw data to flow rate (ml/min)
    int raw_flow = (data[0] << 8) | data[1];
    *flow_rate = (float)raw_flow / 100.0; // Example conversion, adjust as needed

    return 0;
}

// Function to validate the CRC checksum
int validate_crc(unsigned char data[], int len) {
    unsigned char crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// Function to calculate the average flow rate
float calculate_average_flow(float flow1, float flow2) {
    int valid_count = 0;
    float sum = 0.0;

    if (flow1 >= 0) {
        sum += flow1;
        valid_count++;
    }
    if (flow2 >= 0) {
        sum += flow2;
        valid_count++;
    }

    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return -1.0; // Indicate no valid readings
    }
}

// Function to log the data to a file
void log_data(float average_flow) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Average Flow Rate: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, average_flow);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to set the alarm based on the average flow rate
void set_alarm(float average_flow) {
    if (average_flow < FLOW_MIN) {
        gpioWrite(ALARM_GPIO, 0); // Alarm ON (low signal)
    } else {
        gpioWrite(ALARM_GPIO, 1); // Alarm OFF (high signal)
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Start the sensors
    if (start_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Error starting sensors\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow1, flow2, average_flow;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor(i2c_handle, &flow1) != 0) {
            flow1 = -1.0; // Indicate error
        }
        if (read_sensor(i2c_handle, &flow2) != 0) {
            flow2 = -1.0; // Indicate error
        }

        // Calculate average flow rate
        average_flow = calculate_average_flow(flow1, flow2);

        // Log data
        log_data(average_flow);

        // Set alarm
        set_alarm(average_flow);

        // Wait for 1 second
        gpioDelay(1000); // 1000 ms = 1 second
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioWrite(ALARM_GPIO, 0); // Turn off alarm
    gpioTerminate();

    return 0;
}

