#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100

// Structure to hold sensor data and timestamp
typedef struct {
    int sensor_value;
    char timestamp[30];
} SensorData;

// Circular buffer
SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0; // Number of elements in the buffer

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(int sensor_value);
void dump_buffer();
void signal_handler(int signal);

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing pigpio library.\n");
        return 1;
    }

    printf("Obstacle avoidance sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_sensor();

        if (sensor_value != -1) {
            add_to_buffer(sensor_value);
            printf("Obstacle detected: %d\n", sensor_value);
        } else {
            fprintf(stderr, "Error reading sensor value.\n");
        }

        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio library and configure GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP); // Enable internal pull-up resistor

    return 0;
}

// Read sensor value
int read_sensor() {
    int sensor_value = gpioRead(SENSOR_PIN);
    if (sensor_value == PI_BAD_GPIO) {
        fprintf(stderr, "Error reading GPIO pin.\n");
        return -1;
    }
    return sensor_value;
}

// Add sensor data to the circular buffer
void add_to_buffer(int sensor_value) {
    // Get current timestamp
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer[buffer_index].timestamp, sizeof(buffer[buffer_index].timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    buffer[buffer_index].sensor_value = sensor_value;

    // Update buffer index and count
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Dump the contents of the circular buffer to stdout
void dump_buffer() {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE; // Calculate correct index
        printf("%s: %d\n", buffer[index].timestamp, buffer[index].sensor_value);
    }
    printf("--- End of Log ---\n");
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    dump_buffer();
    gpioTerminate();
    exit(0);
}

