int configure_sensor() {
    // Set to high-resolution mode (0x01)
    char buf[2];
    buf[0] = D7S_REG_MODE;
    buf[1] = 0x01; // High-resolution mode

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char reg = D7S_REG_X_LSB;
    char buf[7];
    int result;

    result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device (register select): %s\n", strerror(errno));
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buf, 7);
    if (result != 7) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

