#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define LED_PIN 25

// Function prototypes
int read_sensor(int pin);
void control_led(int pin, int state);
void cleanup(int signum);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void cleanup(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signum);
    control_led(LED_PIN, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read sensor value
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on pin %d: %d\n", pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to control LED state
void control_led(int pin, int state) {
    int result = gpioWrite(pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to LED on pin %d: %d\n", pin, result);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR2_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        if (sensor1_value < 0 || sensor2_value < 0) {
            // Error reading sensor, but continue running
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Check if either sensor detects an obstacle (LOW signal)
        if (sensor1_value == 0 || sensor2_value == 0) {
            control_led(LED_PIN, 1); // Turn on LED
        } else {
            control_led(LED_PIN, 0); // Turn off LED
        }

        gpioDelay(100000); // 100ms delay
    }

    return 0;
}

