#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_DURATION 2 // seconds
#define DEBOUNCE_DELAY 100 // milliseconds

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor value with debouncing
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay in microseconds
    return value;
}

// Function to check if both sensors are LOW
int is_stall_confirmed(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

// Function to log stall event to file
int log_stall_event() {
    FILE *fp = fopen("stall_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening stall_log.txt");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Stall confirmed\n", timestamp);
    fclose(fp);
    return 0;
}

// Function to check for duplicate stall events
int is_duplicate_stall() {
    FILE *fp = fopen("stall_log.txt", "r");
    if (fp == NULL) {
        perror("Error opening stall_log.txt for reading");
        return 0; // Assume no duplicate if file doesn't exist
    }

    char line[100];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Check if the last line is "Stall confirmed"
        if (strstr(line, "Stall confirmed") != NULL) {
            // Stall event is not a duplicate
            fclose(fp);
            return 0;
        }
    }

    fclose(fp);
    return 1; // Stall event is a duplicate
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for sensors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    time_t stall_start_time = 0;
    int stall_confirmed = 0;

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (is_stall_confirmed(sensor1_value, sensor2_value)) {
            if (!stall_confirmed) {
                stall_confirmed = 1;
                stall_start_time = time(NULL);
            } else {
                time_t current_time = time(NULL);
                if (difftime(current_time, stall_start_time) >= STALL_DURATION) {
                    if (is_duplicate_stall()) {
                        if (log_stall_event() == 0) {
                            printf("Stall event logged.\n");
                        } else {
                            fprintf(stderr, "Error logging stall event.\n");
                        }
                    } else {
                        printf("Stall event already logged.\n");
                    }
                    stall_confirmed = 0; // Reset stall confirmation
                }
            }
        } else {
            stall_confirmed = 0; // Reset stall confirmation if sensors are not LOW
        }

        gpioDelay(10000); // Check every 10 milliseconds
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

