#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define REINIT_DELAY_SEC 60

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log messages to file
void log_message(const char *message) {
    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", get_timestamp(), message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Pull-down resistor
    return 0;
}

// Function to read the sensor
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to handle flood alert
