    printf("Attempting to re-initialize GPIO...\n");
    if (initialize_gpio() == 0) {
        printf("GPIO re-initialization successful.\n");
    } else {
        log_message("GPIO re-initialization failed");
        fprintf(stderr, "GPIO re-initialization failed.\n");
    }
}

