        int sensor_value = read_sensor();

        if (sensor_value == 1) {
            handle_flood_alert();
        }

        sleep(POLL_INTERVAL_SEC);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
