#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"

volatile int pulse_count = 0;
FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to get current timestamp in YYYY-MM-DD HH:MM:SS format
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log RPM data to file and stdout
void log_rpm(float rpm) {
    char timestamp[20];
    get_timestamp(timestamp);

    if (log_file != NULL) {
        fprintf(log_file, "%s %.2f\n", timestamp, rpm);
        fflush(log_file); // Ensure data is written to disk immediately
    }

    printf("%s %.2f\n", timestamp, rpm);
}

// Interrupt handler function
void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    if (level == RISING_EDGE) {
        pulse_count++;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for one second
        sleep(1);

        // Calculate RPM
        float rpm = (float)pulse_count * 60.0;

        // Log RPM data
        log_rpm(rpm);

        // Reset pulse count
        pulse_count = 0;
    }

    return 0; // This line will never be reached due to the infinite loop, but it's good practice to include it.
}

