        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for one second
        sleep(1);

        // Calculate RPM
        float rpm = (float)pulse_count * 60.0;

        // Log RPM data
        log_rpm(rpm);

        // Reset pulse count
        pulse_count = 0;
    }

    return 0; // This line will never be reached due to the infinite loop, but it's good practice to include it.
}

