#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_led(int state);
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int touch_pin;
    int led_pin;
} gpio_config_t;

// Global GPIO configuration
gpio_config_t gpio_config = {TOUCH_SENSOR_PIN, LED_PIN};

// Function to initialize the GPIO library and configure pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set touch sensor pin as input
    if (gpioSetMode(gpio_config.touch_pin, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set touch sensor pin as input");
        gpioTerminate();
        return -1;
    }

    // Set LED pin as output
    if (gpioSetMode(gpio_config.led_pin, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set LED pin as output");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(gpio_config.touch_pin);
}

// Function to control the LED state
int control_led(int state) {
    if (gpioWrite(gpio_config.led_pin, state) != 0) {
        syslog(LOG_ERR, "Failed to write to LED pin");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
    control_led(0); // Turn off LED
    gpioTerminate(); // Release GPIO resources
    closelog(); // Close syslog
    exit(0);
}

int main() {
    // Open syslog
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Touch sensor and LED control program started");

    int last_touch_state = 0; // Store the last known touch state
    int current_touch_state;

    // Main loop
    while (program_running) {
        current_touch_state = read_touch_sensor();

        if (current_touch_state != last_touch_state) {
            // Debounce the touch sensor
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
            current_touch_state = read_touch_sensor(); // Re-read after debounce

            if (current_touch_state == last_touch_state) {
                if (current_touch_state == 1) {
                    syslog(LOG_INFO, "Touch detected");
                    if (control_led(1) != 0) {
                        syslog(LOG_ERR, "Failed to turn on LED");
                    }
                } else {
                    syslog(LOG_INFO, "Touch released");
                    if (control_led(0) != 0) {
                        syslog(LOG_ERR, "Failed to turn off LED");
                    }
                }
                last_touch_state = current_touch_state;
            }
        }
        gpioDelay(1000); // Check every 1 ms
    }

    // This point should not be reached due to the signal handler
    syslog(LOG_INFO, "Program terminated");
    closelog();
    return 0;
}

