#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 100

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Structure to store log entries
typedef struct {
    int sensor_pin;
    long timestamp;
    int state;
} LogEntry;

// Circular buffer structure
typedef struct {
    LogEntry buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    int overflow_count;
} CircularBuffer;

// Global variables
CircularBuffer log_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void update_led(int pin, int state);
void add_log_entry(int sensor_pin, int state);
void print_log_buffer();
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    cb->overflow_count = 0;
}

// Add a log entry to the circular buffer
void add_log_entry(int sensor_pin, int state) {
    long timestamp = time(NULL);
    if (timestamp == -1) {
        fprintf(stderr, "Error: Failed to get timestamp.\n");
        return;
    }

    log_buffer.buffer[log_buffer.head].sensor_pin = sensor_pin;
    log_buffer.buffer[log_buffer.head].timestamp = timestamp;
    log_buffer.buffer[log_buffer.head].state = state;

    log_buffer.head = (log_buffer.head + 1) % BUFFER_SIZE;

    if (log_buffer.count == BUFFER_SIZE) {
        log_buffer.tail = (log_buffer.tail + 1) % BUFFER_SIZE;
        log_buffer.overflow_count++;
    } else {
        log_buffer.count++;
    }
}

// Print the contents of the log buffer
void print_log_buffer() {
    printf("\n--- Log Buffer Contents ---\n");
    int i = log_buffer.tail;
    for (int j = 0; j < log_buffer.count; j++) {
        printf("Sensor: %d, Timestamp: %ld, State: %d\n",
               log_buffer.buffer[i].sensor_pin,
               log_buffer.buffer[i].timestamp,
               log_buffer.buffer[i].state);
        i = (i + 1) % BUFFER_SIZE;
    }
    printf("Overflow Count: %d\n", log_buffer.overflow_count);
    printf("--- End of Log Buffer ---\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(LED_1_PIN, PI_OUTPUT);
    gpioSetMode(LED_2_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN); // Enable pull-down resistor
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    return 0;
}

// Read sensor value with debouncing
int read_sensor(int pin) {
    int value = gpioRead(pin);
    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
    return gpioRead(pin);
}

// Update LED state
void update_led(int pin, int state) {
    gpioWrite(pin, state);
}

// Cleanup GPIO resources
void cleanup() {
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&log_buffer);

    int sensor_1_state = 0;
    int sensor_2_state = 0;

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor values
        int new_sensor_1_value = read_sensor(SENSOR_1_PIN);
        int new_sensor_2_value = read_sensor(SENSOR_2_PIN);

        // Update LED states
        if (new_sensor_1_value != sensor_1_state) {
            update_led(LED_1_PIN, new_sensor_1_value);
            sensor_1_state = new_sensor_1_value;
            add_log_entry(SENSOR_1_PIN, sensor_1_state);
        }

        if (new_sensor_2_value != sensor_2_state) {
            update_led(LED_2_PIN, new_sensor_2_value);
            sensor_2_state = new_sensor_2_value;
            add_log_entry(SENSOR_2_PIN, sensor_2_state);
        }

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    print_log_buffer();

    return 0;
}

