static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the rain sensor state
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_GPIO);
}

// Function to log the rain event with a timestamp
int log_rain_event(int rain_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (rain_detected == 0) {
        if (log_file != NULL) {
            fprintf(log_file, "%s Rain Detected\n", timestamp);
            fflush(log_file); // Ensure immediate write to file
        } else {
            fprintf(stderr, "Error: Log file is not open.\n");
            return -1;
        }
    } else {
        if (log_file != NULL) {
            fprintf(log_file, "%s No Rain\n", timestamp);
            fflush(log_file); // Ensure immediate write to file
        } else {
            fprintf(stderr, "Error: Log file is not open.\n");
            return -1;
        }
    }

    return 0;
}

// Function to open the log file
int open_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

// Function to close the log file
void close_log_file() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    int rain_state = -1; // Initialize to an invalid state

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    if (open_log_file() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = read_rain_sensor();

        if (current_state != rain_state) {
            if (log_rain_event(current_state) != 0) {
                fprintf(stderr, "Error logging rain event.\n");
            }
            rain_state = current_state;
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup before exiting
    close_log_file();
    gpioTerminate();

    printf("Rain sensor monitoring stopped.\n");

    return 0;
}

