// Define GPIO pins for the Hall-effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Define the debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Define the log file name
#define LOG_FILE "shaft_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor states and timestamps
typedef struct {
    int sensor1_state;
    int sensor2_state;
    long long timestamp;
} SensorData;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int debounce(int gpio_pin, int current_state);
void log_data(SensorData data);
double calculate_rpm(SensorData prev_data, SensorData current_data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    return 0; // Indicate success
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to debounce the sensor reading
int debounce(int gpio_pin, int current_state) {
    int prev_state = gpioRead(gpio_pin);
    long long start_time = gpioTick();
    while (gpioRead(gpio_pin) == current_state && (gpioTick() - start_time) < (DEBOUNCE_TIME * 1000)) {
        gpioDelay(1); // Small delay to avoid busy-waiting
    }
    return gpioRead(gpio_pin);
}

// Function to log the sensor data to a file
void log_data(SensorData data) {
    if (log_file != NULL) {
        fprintf(log_file, "%lld,%d,%d\n", data.timestamp, data.sensor1_state, data.sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to calculate the RPM based on the time difference between sensor transitions
double calculate_rpm(SensorData prev_data, SensorData current_data) {
    long long time_diff = current_data.timestamp - prev_data.timestamp;
    if (time_diff == 0) return 0.0; // Avoid division by zero
    return 60000000.0 / time_diff; // Convert microseconds to RPM
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        program_running = 0;
    }
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    SensorData prev_data, current_data;
    prev_data.sensor1_state = read_sensor(SENSOR1_GPIO);
    prev_data.sensor2_state = read_sensor(SENSOR2_GPIO);
    prev_data.timestamp = gpioTick();

    // Main loop
    while (program_running) {
        // Read sensor states with debouncing
        current_data.sensor1_state = debounce(SENSOR1_GPIO, read_sensor(SENSOR1_GPIO));
        current_data.sensor2_state = debounce(SENSOR2_GPIO, read_sensor(SENSOR2_GPIO));
        current_data.timestamp = gpioTick();

        // Log the data
        log_data(current_data);

        // Calculate and print RPM
        double rpm = calculate_rpm(prev_data, current_data);
        printf("RPM: %.2f\n", rpm);

        // Update previous data
        prev_data = current_data;

        gpioDelay(10); // Delay to avoid excessive CPU usage
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

