        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&heart_rate, &spo2) == 0) {
            if (log_data(heart_rate, spo2) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

