#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define constants
#define ALARM_DURATION 2 // seconds
#define DEBOUNCE_DELAY 50 // milliseconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int log_event(const char *event_type, int sensor_number);
void activate_alarm();
void deactivate_alarm();
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

SensorStates current_states = {0, 0};

int main() {
    // Register signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Log tilt start events
        if (sensor1_value == 1 && current_states.sensor1_state == 0) {
            log_event("Tilt Start", 1);
            current_states.sensor1_state = 1;
        }
        if (sensor2_value == 1 && current_states.sensor2_state == 0) {
            log_event("Tilt Start", 2);
            current_states.sensor2_state = 1;
        }

        // Check for threshold exceeded
        if (sensor1_value == 1 || sensor2_value == 1) {
            gpioDelay(ALARM_DURATION * 1000); // Delay for ALARM_DURATION seconds

            // Re-read sensors after the delay
            int sensor1_value_delayed = read_sensor(SENSOR_1_PIN);
            int sensor2_value_delayed = read_sensor(SENSOR_2_PIN);

            if (sensor1_value_delayed == 1 || sensor2_value_delayed == 1) {
                activate_alarm();
            }
        }

        // Log tilt end events
        if (sensor1_value == 0 && current_states.sensor1_state == 1) {
            log_event("Tilt End", 1);
            current_states.sensor1_state = 0;
        }
        if (sensor2_value == 0 && current_states.sensor2_state == 1) {
            log_event("Tilt End", 2);
            current_states.sensor2_state = 0;
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Ensure alarm is off initially

    return 0;
}

// Read sensor value with debouncing
int read_sensor(int pin) {
    int value = gpioRead(pin);
    gpioDelay(DEBOUNCE_DELAY);
    return gpioRead(pin);
}

// Log event to file
int log_event(const char *event_type, int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s - Sensor %d\n", timestamp, event_type, sensor_number);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return 1;
    }
}

// Activate the alarm
void activate_alarm() {
    gpioWrite(ALARM_PIN, 1);
    log_event("Threshold Exceeded", -1); // -1 indicates both sensors triggered the alarm
}

// Deactivate the alarm
void deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

