#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x1D
#define CTRL1_REG 0x20
#define DATA_REG 0x28
#define LED_GPIO 17
#define THRESHOLD 500.0
#define POLL_INTERVAL_MS 100
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    uint16_t x;
    uint16_t y;
    uint16_t z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
double calculate_magnitude(sensor_data_t data);
void log_event(double magnitude);
void control_led(int on);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Initialize the sensor
int initialize_sensor() {
    // Verify sensor presence
    char buf[1];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 1); // Read any register to check connection
    if (result < 0) {
        fprintf(stderr, "Error: Sensor not detected on I2C bus %d. Error code: %d\n", I2C_BUS, result);
        return -1;
    }

    // Clear power-down bit in CTRL1 register
    char ctrl1_value = 0x00; // Example value, check datasheet for correct value
    int status = i2cWriteByteData(i2c_handle, CTRL1_REG, ctrl1_value);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write to CTRL1 register. Error code: %d\n", status);
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, DATA_REG, buf, 6);

    if (result < 0) {
        fprintf(stderr, "Error: Failed to read sensor data. Error code: %d\n", result);
        data.x = 0; data.y = 0; data.z = 0; // Return default values
        return data;
    }

    data.x = (uint16_t)((buf[0] << 8) | buf[1]);
    data.y = (uint16_t)((buf[2] << 8) | buf[3]);
    data.z = (uint16_t)((buf[4] << 8) | buf[5]);

    return data;
}

// Calculate Euclidean magnitude
double calculate_magnitude(sensor_data_t data) {
    return sqrt(pow(data.x, 2) + pow(data.y, 2) + pow(data.z, 2));
}

// Log event to file
void log_event(double magnitude) {
    char* timestamp = get_iso8601_timestamp();
    fprintf(log_file, "%s, Magnitude: %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
