#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for sensors and LED
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LED_PIN 18

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read sensor data
int read_sensors() {
    int sensor1_value = gpioRead(SENSOR1_PIN);
    int sensor2_value = gpioRead(SENSOR2_PIN);
    int sensor3_value = gpioRead(SENSOR3_PIN);
    int sensor4_value = gpioRead(SENSOR4_PIN);

    // Check if any sensor detects an object (active-low)
    if (sensor1_value == 0 || sensor2_value == 0 || sensor3_value == 0 || sensor4_value == 0) {
        return 1; // Object detected
    } else {
        return 0; // No object detected
    }
}

// Function to control the LED
void control_led(int object_detected) {
    gpioWrite(LED_PIN, object_detected);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetMode(SENSOR4_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Read sensor data
        int object_detected = read_sensors();

        // Control the LED
        control_led(object_detected);

        // Poll every 50 milliseconds
        gpioDelay(50000); // 50 ms
    }

    // Clean up GPIO resources before exiting
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

