// Define GPIO pins for the flame sensors
#define SENSOR_1_PIN 2
#define SENSOR_2_PIN 3
#define SENSOR_3_PIN 4
#define SENSOR_4_PIN 17
#define SENSOR_5_PIN 27

// Define the log file path
#define LOG_FILE "/var/log/flame_events.log"

// Define the debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define the polling interval in seconds
#define POLLING_INTERVAL 1

// Structure to hold sensor information
typedef struct {
    int pin;
    int id;
    int line;
} sensor_t;

// Global variables
volatile sig_atomic_t terminate = 0;
sensor_t sensors[5];

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int debounce_read(int pin);
int log_event(int sensor_id, int pin);
void signal_handler(int signal);
