// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_USER, "Signal received, terminating...");
    terminate = 1;
}

// Function to initialize the pigpio library and set GPIO pins as inputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(SENSOR_3_PIN, PI_INPUT);
    gpioSetMode(SENSOR_4_PIN, PI_INPUT);
    gpioSetMode(SENSOR_5_PIN, PI_INPUT);

    return 0;
}

// Function to read the digital value from a GPIO pin
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to perform a debounce read
int debounce_read(int pin) {
    gpioDelay(DEBOUNCE_TIME * 1000); // Convert milliseconds to microseconds
    return read_sensor(pin);
}

// Function to log a flame detection event to the log file
int log_event(int sensor_id, int pin) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, pin);
    fflush(fp);
    fclose(fp);

    syslog(LOG_USER, "%s - Sensor ID: %d (GPIO %d) - Flame Detected", timestamp, sensor_id, pin);

    return 0;
}

// Function to cleanup GPIO resources
void cleanup() {
    syslog(LOG_USER, "Cleaning up GPIO resources...");
    gpioTerminate();
    closelog();
}

int main() {
    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Define sensor array
    sensors[0].pin = SENSOR_1_PIN;
    sensors[0].id = 1;
    sensors[1].pin = SENSOR_2_PIN;
    sensors[1].id = 2;
    sensors[2].pin = SENSOR_3_PIN;
    sensors[2].id = 3;
    sensors[3].pin = SENSOR_4_PIN;
    sensors[3].id = 4;
    sensors[4].pin = SENSOR_5_PIN;
    sensors[4].id = 5;

    syslog(LOG_USER, "Flame monitor started");

    // Main loop
    while (!terminate) {
        for (int i = 0; i < 5; i++) {
            int sensor_value = read_sensor(sensors[i].pin);

            if (sensor_value == 0) { // Flame detected (LOW signal)
                int debounced_value = debounce_read(sensors[i].pin);

                if (debounced_value == 0) { // Confirm flame detection
                    if (log_event(sensors[i].id, sensors[i].pin) != 0) {
                        syslog(LOG_ERR, "Failed to log event for sensor %d", sensors[i].id);
                    }
                }
            }
        }

        sleep(POLLING_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

