void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        // Release GPIO lines
        for (int i = 0; i < num_pins; i++) {
            if (lines[i] != NULL) {
                gpiod_line_release(lines[i]);
                lines[i] = NULL;
            }
        }

        // Close GPIO chip
        if (chip != NULL) {
            gpiod_chip_close(chip);
            chip = NULL;
        }

        exit(0);
    }
}

// Function to read the state of a single GPIO pin
int read_sensor_state(int pin) {
    int value = -1; // Initialize to an invalid value
    int retries = 3; // Number of retries

    while (retries > 0) {
        value = gpiod_line_get_value(lines[pin - 5]); // Get the value of the line
        if (value >= 0) {
            return value; // Return the value if successful
        } else {
            fprintf(stderr, "Error reading GPIO pin %d: %s (errno: %d)\n", pin, strerror(errno), errno);
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read GPIO pin %d after multiple retries.\n", pin);
    return -1; // Return -1 to indicate an error
}

// Function to log an event to the console
void log_event(int pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Sensor %d (GPIO %d) %s\n", timestamp, pin, gpio_pins[pin - 5], state ? "TOUCHED" : "RELEASED");
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s (errno: %d)\n", strerror(errno), errno);
        return 1;
    }

    // Request lines for each sensor pin
    for (int i = 0; i < num_pins; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error getting GPIO line for pin %d: %s (errno: %d)\n", gpio_pins[i], strerror(errno), errno);
            // Release any previously requested lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }

        // Request the line for input
        if (gpiod_line_request_input(lines[i], "touch_sensor") < 0) {
            fprintf(stderr, "Error requesting GPIO line for input on pin %d: %s (errno: %d)\n", gpio_pins[i], strerror(errno), errno);
            // Release any previously requested lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    int previous_states[8] = {0}; // Store the previous state of each pin
    while (1) {
        for (int i = 0; i < num_pins; i++) {
            int current_state = read_sensor_state(gpio_pins[i]);

            if (current_state != -1) {
                if (current_state != previous_states[i]) {
                    log_event(gpio_pins[i], current_state);
                    previous_states[i] = current_state;
                }
            }
        }

        usleep(50000); // Wait 50ms
    }

    return 0;
}

