#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x48

// VEML7700 register addresses
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_WH 0x01
#define VEML7700_ALS_WL 0x02
#define VEML7700_ALS 0x04
#define VEML7700_WHITE 0x05
#define VEML7700_POWER_SAVE 0x06

// GPIO pin for PWM control
#define PWM_PIN 18

// PWM frequency
#define PWM_FREQUENCY 1000

// Log file name
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_veml7700();
int read_lux();
int map_lux_to_duty_cycle(int lux);
int set_pwm_duty_cycle(int duty_cycle);
int log_data(int lux, int duty_cycle, int error_code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize VEML7700 sensor
int init_veml7700() {
    // Configuration: Integration time = 100ms, Gain = 1/8
    uint8_t config_data[2] = {0x02, 0x00}; // IT = 100ms, Gain = 1/8

    if (i2cWriteI2CBlockData(i2c_handle, VEML7700_ALS_CONF, config_data, 2) != 2) {
        fprintf(stderr, "Error writing to VEML7700 configuration register.\n");
        return -1;
    }

    return 0;
}

// Read lux value from VEML7700 sensor
int read_lux() {
    uint8_t data[2];
    int lux;

    if (i2cReadI2CBlockData(i2c_handle, VEML7700_ALS, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading lux data from VEML7700.\n");
        return -1;
    }

    lux = (data[1] << 8) | data[0];
    return lux;
}

// Map lux value to PWM duty cycle
int map_lux_to_duty_cycle(int lux) {
    if (lux < 100) {
        return 100;
    } else if (lux < 500) {
        return 75;
    } else if (lux < 1000) {
        return 50;
    } else {
        return 25;
    }
}

// Set PWM duty cycle
int set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid duty cycle value: %d\n", duty_cycle);
        return -1;
    }

    int pwm_value = (int)((duty_cycle / 100.0) * 255.0); // Convert percentage to PWM value (0-255)
    gpioPWM(PWM_PIN, pwm_value);
    return 0;
}

// Log data to file
int log_data(int lux, int duty_cycle, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, lux, duty_cycle, error_code);
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (init_veml7700() != 0) {
        fprintf(stderr, "VEML7700 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int lux = read_lux();
        int duty_cycle = 0;
        int error_code = 0;

        if (lux >= 0) {
            duty_cycle = map_lux_to_duty_cycle(lux);
            if (set_pwm_duty_cycle(duty_cycle) != 0) {
                error_code = 1;
            }
        } else {
            error_code = 2;
        }

        log_data(lux, duty_cycle, error_code);
        sleep(1);
    }

    // Cleanup
    gpioPWM(PWM_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

