#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for touch sensors and LED
#define TOUCH_SENSOR_1 2
#define TOUCH_SENSOR_2 3
#define TOUCH_SENSOR_3 4
#define TOUCH_SENSOR_4 5
#define TOUCH_SENSOR_5 6
#define TOUCH_SENSOR_6 7
#define TOUCH_SENSOR_7 8
#define TOUCH_SENSOR_8 9
#define ALERT_LED 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor(int gpio_pin);
int debounce(int gpio_pin);
int log_touch_event(int channel);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Structure to hold the last touch time for each channel
struct {
    unsigned long last_touch_time[8];
} debounce_data;

int main() {
    // Initialize debounce times
    for (int i = 0; i < 8; i++) {
        debounce_data.last_touch_time[i] = 0;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing pigpio library.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Read touch sensors and log events
        for (int i = 1; i <= 8; i++) {
            int gpio_pin;
            switch (i) {
                case 1: gpio_pin = TOUCH_SENSOR_1; break;
                case 2: gpio_pin = TOUCH_SENSOR_2; break;
                case 3: gpio_pin = TOUCH_SENSOR_3; break;
                case 4: gpio_pin = TOUCH_SENSOR_4; break;
                case 5: gpio_pin = TOUCH_SENSOR_5; break;
                case 6: gpio_pin = TOUCH_SENSOR_6; break;
                case 7: gpio_pin = TOUCH_SENSOR_7; break;
                case 8: gpio_pin = TOUCH_SENSOR_8; break;
                default: gpio_pin = 0; break; // Should not happen
            }

            if (read_touch_sensor(gpio_pin) == 1) {
                if (debounce(gpio_pin) == 0) {
                    log_touch_event(i);
                }
            }
        }

        // Control LED based on touch sensor state
        int any_touched = 0;
        for (int i = 1; i <= 8; i++) {
            int gpio_pin;
            switch (i) {
                case 1: gpio_pin = TOUCH_SENSOR_1; break;
                case 2: gpio_pin = TOUCH_SENSOR_2; break;
                case 3: gpio_pin = TOUCH_SENSOR_3; break;
                case 4: gpio_pin = TOUCH_SENSOR_4; break;
                case 5: gpio_pin = TOUCH_SENSOR_5; break;
                case 6: gpio_pin = TOUCH_SENSOR_6; break;
                case 7: gpio_pin = TOUCH_SENSOR_7; break;
                case 8: gpio_pin = TOUCH_SENSOR_8; break;
                default: gpio_pin = 0; break; // Should not happen
            }

            if (read_touch_sensor(gpio_pin) == 1) {
                any_touched = 1;
                break;
            }
        }

        if (any_touched) {
            control_led(1); // Turn LED on
        } else {
            control_led(0); // Turn LED off
        }

        gpioDelay(50); // Poll every 50 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins for touch sensors as inputs with pull-down resistors
    gpioSetMode(TOUCH_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_1, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_2, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_3, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_3, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_4, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_4, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_5, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_5, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_6, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_6, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_7, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_7, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_8, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_8, PI_PUD_DOWN);

    // Set GPIO pin for LED as output
    gpioSetMode(ALERT_LED, PI_OUTPUT);
    gpioWrite(ALERT_LED, 0); // Initially turn LED off

    return 0;
}

// Read the state of a touch sensor
int read_touch_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Debounce a touch sensor
int debounce(int gpio_pin) {
    int channel;
    switch (gpio_pin) {
        case TOUCH_SENSOR_1: channel = 1; break;
        case TOUCH_SENSOR_2: channel = 2; break;
        case TOUCH_SENSOR_3: channel = 3; break;
        case TOUCH_SENSOR_4: channel = 4; break;
        case TOUCH_SENSOR_5: channel = 5; break;
        case TOUCH_SENSOR_6: channel = 6; break;
        case TOUCH_SENSOR_7: channel = 7; break;
        case TOUCH_SENSOR_8: channel = 8; break;
        default: channel = 0; break; // Should not happen
    }

    unsigned long current_time = gpioTick();

    if (current_time - debounce_data.last_touch_time[channel - 1] > DEBOUNCE_TIME * 1000) {
        debounce_data.last_touch_time[channel - 1] = current_time;
        return 0; // Debounced
    } else {
        return 1; // Not debounced
    }
}

// Log a touch event to the log file
int log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s – Channel %d Touched\n", timestamp, channel);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Control the alert LED
void control_led(int state) {
    gpioWrite(ALERT_LED, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    // Turn off LED
    control_led(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();
}

