#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LUX_SCALE 0.01
#define LUX_OFFSET 1.0
#define CONFIG_CONTINUOUS 0xC200 // Continuous conversion mode, 100ms conversion time

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_opt3001();
int read_opt3001(float *lux);
char *format_data(float lux);
int write_to_log(const char *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure OPT3001
int configure_opt3001() {
    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, CONFIG_CONTINUOUS);
    if (result < 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read OPT3001 data
int read_opt3001(float *lux) {
    int raw_result = i2cReadWordData(i2c_handle, RESULT_REG);
    if (raw_result < 0) {
        fprintf(stderr, "Error reading result register: %d\n", raw_result);
        return -1;
    }

    // Byte swap for big-endian to little-endian conversion
    raw_result = ((raw_result & 0xFF00) >> 8) | ((raw_result & 0x00FF) << 8);

    *lux = (float)raw_result * LUX_SCALE + LUX_OFFSET;
    return 0;
}

// Format data as CSV string
char *format_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    static char buffer[64]; // Static buffer to hold the formatted string

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", t);
    snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), ", %.2f\n", lux);

    return buffer;
}

// Write data to log file
int write_to_log(const char *data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s", data) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure OPT3001
    if (configure_opt3001() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float lux;
    char *data;

    // Main loop
    while (!terminate) {
        if (read_opt3001(&lux) == 0) {
            data = format_data(lux);
            if (write_to_log(data) != 0) {
                fprintf(stderr, "Error writing data to log.\n");
            }
            printf("%s", data);
        } else {
            fprintf(stderr, "Error reading light data.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

