                    fprintf(stderr, "Error logging touch detected event.\n");
                }
            } else {
                if (log_event("Touch Released") != 0) {
                    fprintf(stderr, "Error logging touch released event.\n");
                }
            }
            last_state = current_state;
        }

        gpioDelay(DEBOUNCE_INTERVAL * 1000); // Debounce delay in microseconds
    }

    cleanup();
    return 0;
}

