#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define MEASURE_CMD 0x3608
#define FLOW_MIN 0.0
#define FLOW_MAX 100.0
#define LOG_FILE "cooling_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data);
int calculate_crc(uint8_t *data, int len);
float convert_flow(uint16_t raw_flow);
int validate_flow(float flow);
int log_data(float flow, uint8_t flags, const char *status);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    float flow_rate;
    uint8_t flags;
    char status[10];
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, uint8_t *data) {
    int result = i2cReadDevice(handle, (char *)data, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8
int calculate_crc(uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw flow to ml/min
float convert_flow(uint16_t raw_flow) {
    return (float)raw_flow / 10.0; // Example conversion, adjust as needed
}

// Function to validate flow rate
int validate_flow(float flow) {
    return (flow >= FLOW_MIN && flow <= FLOW_MAX) ? 0 : 1;
}

// Function to log data to CSV file
int log_data(float flow, uint8_t flags, const char *status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

