            fprintf(stderr, "Error opening log file!\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    fprintf(log_file, "%s,%.2f,%s,%u\n", timestamp, flow, status, flags);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    uint8_t data[3];
    uint16_t raw_flow;
    float flow_rate;
    int crc_valid;
    int flow_valid;
    char status[10];

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error sending command, attempting recovery...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting...\n");
                break;
            }
            continue; // Skip to the next iteration
        }

        // Wait for measurement (adjust as needed)
        gpioDelay(2000); // 2 ms

        // Read sensor data
        if (read_sensor_data(i2c_handle, data) != 0) {
            fprintf(stderr, "Error reading sensor data, attempting recovery...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting...\n");
                break;
            }
            continue; // Skip to the next iteration
        }

        // Calculate CRC
        int crc_calculated = calculate_crc(data, 2);
        int crc_received = data[2];

        // Validate CRC
        crc_valid = (crc_calculated == crc_received) ? 0 : 1;

        // Convert flow rate
        raw_flow = (data[0] << 8) | data[1];
        flow_rate = convert_flow(raw_flow);

        // Validate flow rate
        flow_valid = validate_flow(flow_rate);

        // Determine status
        if (crc_valid) {
            strcpy(status, "ERROR");
        } else if (flow_valid) {
            strcpy(status, "INVALID");
        } else {
            strcpy(status, "OK");
        }

        // Log data
        if (log_data(flow_rate, data[2], status) != 0) {
            fprintf(stderr, "Error logging data!\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

