#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

// Define GPIO pins
#define LEFT_SENSOR 17
#define MIDDLE_SENSOR 27
#define RIGHT_SENSOR 22

// Define GPIO chip path
#define GPIO_CHIP_PATH "/sys/class/gpio"

// Define log file path
#define LOG_FILE_PATH "path_log.csv"

// Global variables
static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
char *get_iso8601_timestamp();
int write_log_entry(FILE *fp, const char *timestamp, int left, int middle, int right);
void signal_handler(int signal);

// Function to export a GPIO pin
int gpio_export(int pin) {
    char export_path[64];
    snprintf(export_path, sizeof(export_path), "%s/export", GPIO_CHIP_PATH);
    int fd = open(export_path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", export_path, strerror(errno));
        return -1;
    }
    char pin_str[4];
    snprintf(pin_str, sizeof(pin_str), "%d", pin);
    if (write(fd, pin_str, strlen(pin_str)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", export_path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    char unexport_path[64];
    snprintf(unexport_path, sizeof(unexport_path), "%s/unexport", GPIO_CHIP_PATH);
    int fd = open(unexport_path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", unexport_path, strerror(errno));
        return -1;
    }
    char pin_str[4];
    snprintf(pin_str, sizeof(pin_str), "%d", pin);
    if (write(fd, pin_str, strlen(pin_str)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", unexport_path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char direction_path[64];
    snprintf(direction_path, sizeof(direction_path), "%s/gpio%d/direction", GPIO_CHIP_PATH, pin);
    int fd = open(direction_path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", direction_path, strerror(errno));
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", direction_path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to read the value of a GPIO pin
int gpio_read(int pin) {
    char value_path[64];
    snprintf(value_path, sizeof(value_path), "%s/gpio%d/value", GPIO_CHIP_PATH, pin);
    int fd = open(value_path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", value_path, strerror(errno));
        return -1;
    }
    char value_str[4];
    if (read(fd, value_str, sizeof(value_str)) < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", value_path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return atoi(value_str);
}

// Function to get the current timestamp in ISO 8601 format
char *get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to write a log entry to the CSV file
int write_log_entry(FILE *fp, const char *timestamp, int left, int middle, int right) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

int main() {
    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    // Export GPIO pins
    if (gpio_export(LEFT_SENSOR) < 0 ||
        gpio_export(MIDDLE_SENSOR) < 0 ||
        gpio_export(RIGHT_SENSOR) < 0) {
        fprintf(stderr, "Failed to export GPIO pins. Exiting.\n");
        return 1;
    }

    // Set GPIO directions to input
    if (gpio_set_direction(LEFT_SENSOR, "in") < 0 ||
        gpio_set_direction(MIDDLE_SENSOR, "in") < 0 ||
        gpio_set_direction(RIGHT_SENSOR, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO directions. Exiting.\n");
        gpio_unexport(LEFT_SENSOR);
        gpio_unexport(MIDDLE_SENSOR);
        gpio_unexport(RIGHT_SENSOR);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpio_unexport(LEFT_SENSOR);
        gpio_unexport(MIDDLE_SENSOR);
        gpio_unexport(RIGHT_SENSOR);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,left,middle,right\n");
    }
    rewind(log_file);

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_value = gpio_read(LEFT_SENSOR);
        int middle_value = gpio_read(MIDDLE_SENSOR);
        int right_value = gpio_read(RIGHT_SENSOR);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp. Skipping log entry.\n");
            continue; // Skip to the next iteration
        }

        // Write log entry
        if (write_log_entry(log_file, timestamp, left_value, middle_value, right_value) < 0) {
            fprintf(stderr, "Failed to write log entry. Continuing...\n");
        }

        // Free timestamp memory
        free(timestamp);

        // Flush log file
        fflush(log_file);

        // Wait 50ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 50000000; // 50ms
        nanosleep(&ts, NULL);
    }

    // Clean up
    printf("Cleaning up...\n");
    gpio_unexport(LEFT_SENSOR);
    gpio_unexport(MIDDLE_SENSOR);
    gpio_unexport(RIGHT_SENSOR);
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }

    return 0;
}

