    struct tm *timeinfo;
    char *timestamp = (char *)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to write a log entry to the CSV file
int write_log_entry(FILE *fp, const char *timestamp, int left, int middle, int right) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

int main() {
    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    // Export GPIO pins
    if (gpio_export(LEFT_SENSOR) < 0 ||
        gpio_export(MIDDLE_SENSOR) < 0 ||
        gpio_export(RIGHT_SENSOR) < 0) {
        fprintf(stderr, "Failed to export GPIO pins. Exiting.\n");
        return 1;
    }

    // Set GPIO directions to input
    if (gpio_set_direction(LEFT_SENSOR, "in") < 0 ||
        gpio_set_direction(MIDDLE_SENSOR, "in") < 0 ||
        gpio_set_direction(RIGHT_SENSOR, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO directions. Exiting.\n");
        gpio_unexport(LEFT_SENSOR);
        gpio_unexport(MIDDLE_SENSOR);
        gpio_unexport(RIGHT_SENSOR);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpio_unexport(LEFT_SENSOR);
        gpio_unexport(MIDDLE_SENSOR);
        gpio_unexport(RIGHT_SENSOR);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,left,middle,right\n");
    }
    rewind(log_file);

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_value = gpio_read(LEFT_SENSOR);
        int middle_value = gpio_read(MIDDLE_SENSOR);
        int right_value = gpio_read(RIGHT_SENSOR);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp. Skipping log entry.\n");
            continue; // Skip to the next iteration
        }

        // Write log entry
        if (write_log_entry(log_file, timestamp, left_value, middle_value, right_value) < 0) {
            fprintf(stderr, "Failed to write log entry. Continuing...\n");
        }

        // Free timestamp memory
        free(timestamp);

        // Flush log file
        fflush(log_file);

        // Wait 50ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 50000000; // 50ms
        nanosleep(&ts, NULL);
    }

    // Clean up
    printf("Cleaning up...\n");
    gpio_unexport(LEFT_SENSOR);
    gpio_unexport(MIDDLE_SENSOR);
    gpio_unexport(RIGHT_SENSOR);
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }

    return 0;
}

