        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Control the LED state
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Log the event to a file
int log_event(int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d\n", timestamp, led_state);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int led_state = 0; // Initial LED state (off)
    int last_touch_state = 0; // Store the last known touch state

    printf("Touch-activated lamp started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_state = read_touch_sensor();

        if (touch_state == 1 && last_touch_state == 0) {
            // Rising edge detected
            led_state = !led_state; // Toggle LED state
            control_led(led_state);
            log_event(led_state);
            printf("Touch detected! LED is now %s\n", led_state ? "ON" : "OFF");
        }

        last_touch_state = touch_state;

        gpioDelay(100); // Small delay to avoid busy-waiting
    }

    cleanup();
    return 0;
}

