int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Debounce function
int debounce() {
    gpioDelay(DEBOUNCE_TIME * 1000); // Convert ms to microseconds
    return 0;
}

// Toggle the LED state
int toggle_led() {
    led_state = !led_state;
    gpioWrite(LED_PIN, led_state);
    return 0;
}

