#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Define the log file name
#define LOG_FILE "magnet_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int log_event(int sensor_id, int state);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    int sensor3_state;
} SensorStates;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting mode for SENSOR1_PIN\n");
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up for SENSOR1_PIN\n");
        return 1;
    }

    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting mode for SENSOR2_PIN\n");
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up for SENSOR2_PIN\n");
        return 1;
    }

    if (gpioSetMode(SENSOR3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting mode for SENSOR3_PIN\n");
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up for SENSOR3_PIN\n");
        return 1;
    }

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int pin) {
    int state = gpioRead(pin);
    if (state < 0) {
        fprintf(stderr, "Error reading sensor on pin %d\n", pin);
        return -1; // Indicate an error
    }
    return state;
}

// Function to log an event to the log file
int log_event(int sensor_id, int state) {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return 1;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s Sensor %d: %s\n", timestamp, sensor_id, state ? "Magnet Removed" : "Magnet Present");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Log file is not open\n");
        free(timestamp);
        return 1;
    }
    free(timestamp);
    return 0;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (buffer == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return buffer;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read initial sensor states
    SensorStates initial_states;
    initial_states.sensor1_state = read_sensor(SENSOR1_PIN);
    initial_states.sensor2_state = read_sensor(SENSOR2_PIN);
    initial_states.sensor3_state = read_sensor(SENSOR3_PIN);

    if (initial_states.sensor1_state == -1 || initial_states.sensor2_state == -1 || initial_states.sensor3_state == -1) {
        fprintf(stderr, "Error reading initial sensor states\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor states
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);
        int sensor3_state = read_sensor(SENSOR3_PIN);

        if (sensor1_state == -1 || sensor2_state == -1 || sensor3_state == -1) {
            fprintf(stderr, "Error reading sensor states in main loop\n");
            continue; // Continue to the next iteration
        }

        // Check for state changes and log events
        if (sensor1_state != initial_states.sensor1_state) {
            log_event(1, sensor1_state);
            initial_states.sensor1_state = sensor1_state;
        }
        if (sensor2_state != initial_states.sensor2_state) {
            log_event(2, sensor2_state);
            initial_states.sensor2_state = sensor2_state;
        }
        if (sensor3_state != initial_states.sensor3_state) {
            log_event(3, sensor3_state);
            initial_states.sensor3_state = sensor3_state;
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

