        return -1;
    }

    // Validate sensor ID
    if (part_id != 0x50 || hw_rev != 0x04) {
        fprintf(stderr, "Invalid sensor ID: PART_ID=0x%02X, HW_REV=0x%02X\n", part_id, hw_rev);
        return -1;
    }

    // Configure the sensor (example configuration)
    int status = i2cWriteByteData(i2c_handle, CONFIG_REG, CONFIG_VALUE);
    if (status < 0) {
        fprintf(stderr, "Error writing configuration: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read the heart rate from the sensor with retries
int read_heart_rate() {
    int heart_rate = -1;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        heart_rate = i2cReadByteData(i2c_handle, HEART_RATE_REG);
        if (heart_rate >= 0) {
            return heart_rate;
        } else {
            fprintf(stderr, "I2C read error, retrying... (%d retries left)\n", retries - 1);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read heart rate after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to apply a moving average filter
int apply_moving_average(int *data, int size) {
    if (size <= 0) return 0; // Handle empty data

    int sum = 0;
    for (int i = 0; i < size; i++) {
        sum += data[i];
    }
    return sum / size;
}

// Function to validate the BPM value
int validate_bpm(int bpm) {
    return (bpm >= MIN_BPM && bpm <= MAX_BPM) ? bpm : -1;
}

// Function to log the data to a file
int log_data(int bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Data buffer for moving average filter
    int heart_rate_data[MOVING_AVG_SIZE];
    int data_index = 0;

    // Main loop
    while (!terminate) {
        // Read heart rate
        int raw_heart_rate = read_heart_rate();
        if (raw_heart_rate < 0) {
            fprintf(stderr, "Failed to read heart rate, skipping.\n");
            gpioDelay(1000000); // 1 second delay
            continue;
        }

        // Update data buffer
        heart_rate_data[data_index] = raw_heart_rate;
        data_index = (data_index + 1) % MOVING_AVG_SIZE;

        // Apply moving average filter
        int filtered_bpm = apply_moving_average(heart_rate_data, MOVING_AVG_SIZE);

        // Validate BPM
        int validated_bpm = validate_bpm(filtered_bpm);
        if (validated_bpm != -1) {
            // Log data
            if (log_data(validated_bpm) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Invalid BPM value: %d\n", filtered_bpm);
        }

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

