void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the flame sensor
int read_flame_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log the flame detection event
int log_flame_detection(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s FLAME DETECTED\n", timestamp);
    fflush(fp);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-up resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_flame_sensor(FLAME_SENSOR_GPIO);

        if (sensor_value == 0 && !flame_detected) {
            printf("FLAME DETECTED\n");
            if (log_flame_detection(LOG_FILE) != 0) {
                fprintf(stderr, "Error logging flame detection\n");
            }
            flame_detected = 1;
        } else if (sensor_value == 1) {
            flame_detected = 0;
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

