#include <pigpio.h>

// Define GPIO pins for touch sensor inputs
const int touch_pins[] = {5, 6, 7, 8, 9, 10, 11, 12};
// Define GPIO pins for counter outputs
const int counter_pins[] = {17, 18, 19, 20, 21, 22, 23, 24};

// Global variables
int counter_value = 0;
FILE *log_file = NULL;
int pigpio_initialized = 0;

// Function prototypes
int read_touch_sensor(int pin);
void increment_counter(int *counter);
void update_counter_output(int counter_value, const int *pins);
void log_event(int channel, int counter);
void print_event(int channel, int counter);
void signal_handler(int signal);
int setup_gpio();
void cleanup_gpio();

// Function to read the touch sensor value from a given pin
int read_touch_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to increment the counter value
void increment_counter(int *counter) {
    (*counter)++;
    if (*counter > 255) {
        *counter = 0;
    }
}

// Function to update the counter output pins based on the counter value
void update_counter_output(int counter_value, const int *pins) {
    for (int i = 0; i < 8; i++) {
        int bit = (counter_value >> i) & 1; // Extract the i-th bit
        gpioWrite(pins[i], bit);
    }
}

// Function to log the touch event to a file
void log_event(int channel, int counter) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[21]; // YYYY-MM-DDTHH:MM:SSZ\0

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to print the touch event to stdout
void print_event(int channel, int counter) {
    printf("Touch on channel %d | Counter: %d\n", channel, counter);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO pins
int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }
    pigpio_initialized = 1;

    // Set touch sensor pins as inputs
    for (int i = 0; i < 8; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as input: %s\n", touch_pins[i], strerror(errno));
            return -1;
        }
    }

    // Set counter output pins as outputs and initialize to 0
    for (int i = 0; i < 8; i++) {
        if (gpioSetMode(counter_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as output: %s\n", counter_pins[i], strerror(errno));
            return -1;
        }
        gpioWrite(counter_pins[i], 0);
    }

    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    if (pigpio_initialized) {
        // Reset all output pins to 0
        for (int i = 0; i < 8; i++) {
            gpioWrite(counter_pins[i], 0);
        }

        gpioTerminate();
        pigpio_initialized = 0;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed, exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
    }

    // Stabilization delay
    gpioDelay(200000); // 200 ms

    // Main loop
    while (1) {
        for (int i = 0; i < 8; i++) {
            int touch_value = read_touch_sensor(touch_pins[i]);
            if (touch_value == 1) {
                increment_counter(&counter_value);
                update_counter_output(counter_value, counter_pins);
                log_event(i + 1, counter_value);
                print_event(i + 1, counter_value);
            } else if (touch_value < 0) {
                // Error reading sensor, skip this channel
                continue;
            }
        }
        gpioDelay(10000); // 10 ms delay
    }

    return 0;
}

