#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22

// Define the log file name
#define LOG_FILE "tracking_log.csv"

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to format the sensor data into a comma-separated string
char* format_data(int sensor1, int sensor2, int sensor3, int sensor4) {
    static char data_string[100]; // Static buffer to hold the formatted string
    snprintf(data_string, sizeof(data_string), "%d,%d,%d,%d", sensor1, sensor2, sensor3, sensor4);
    return data_string;
}

// Function to write the timestamp and sensor data to the log file
int write_to_log(const char* data_string) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1; // Indicate an error
    }

    // Get the current timestamp
    time_t current_time = time(NULL);
    struct tm* time_info = localtime(&current_time);
    char timestamp[20]; // Buffer to hold the formatted timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    // Write the timestamp and sensor data to the log file
    fprintf(log_file, "%s,%s\n", timestamp, data_string);

    // Flush the buffer to ensure data is written to the file immediately
    fflush(log_file);

    // Close the log file
    if (fclose(log_file) != 0) {
        fprintf(stderr, "Error closing log file %s\n", LOG_FILE);
        return -1; // Indicate an error
    }

    return 0; // Indicate success
}

// Function to initialize the pigpio library and set GPIO pins as inputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1; // Indicate an error
    }

    // Set GPIO pins as inputs
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR3_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR4_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR4_PIN);
        gpioTerminate();
        return -1;
    }

    return 0; // Indicate success
}

// Function to check if the log file exists and create it with a header if it doesn't
int check_log_file() {
    FILE* log_file = fopen(LOG_FILE, "r");
    if (log_file == NULL) {
        // File doesn't exist, create it and add the header
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Error creating log file %s\n", LOG_FILE);
            return -1; // Indicate an error
        }
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
        fclose(log_file);
        return 0; // Indicate success
    } else {
        fclose(log_file);
        return 0; // Indicate success, file exists
    }
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1; // Exit with an error code
    }

    // Check if the log file exists and create it if it doesn't
    if (check_log_file() != 0) {
        gpioTerminate();
        return 1; // Exit with an error code
    }

    // Main loop to read sensor data and write to the log file
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);
        int sensor4_value = read_sensor(SENSOR4_PIN);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1 || sensor4_value == -1) {
            fprintf(stderr, "Error reading sensor data, skipping log entry.\n");
            gpioDelay(100); // Wait 100ms before the next iteration
            continue; // Skip to the next iteration of the loop
        }

        // Format the sensor data into a string
        char* data_string = format_data(sensor1_value, sensor2_value, sensor3_value, sensor4_value);

        // Write the data to the log file
        if (write_to_log(data_string) != 0) {
            fprintf(stderr, "Error writing to log file, skipping log entry.\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0; // Exit successfully
}

