#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_MS 50
#define POLL_MS 100

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);

    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log a tilt event to a file
void log_tilt_event(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("/var/log/tilt_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    int sensor1_state = 1; // Initialize to inactive state (1)
    int sensor2_state = 1;

    // Main loop
    while (running) {
        int sensor1_current_state = read_sensor(SENSOR_1_GPIO);
        int sensor2_current_state = read_sensor(SENSOR_2_GPIO);

        // Debounce and log sensor 1
        if (sensor1_current_state == 0 && sensor1_state == 1) {
            log_tilt_event(1);
            gpioDelay(DEBOUNCE_MS * 1000); // Debounce delay
            while (read_sensor(SENSOR_1_GPIO) == 0 && running) {
                gpioDelay(1000); // Wait for the sensor to return to inactive state
            }
        }
        sensor1_state = sensor1_current_state;

        // Debounce and log sensor 2
        if (sensor2_current_state == 0 && sensor2_state == 1) {
            log_tilt_event(2);
            gpioDelay(DEBOUNCE_MS * 1000); // Debounce delay
            while (read_sensor(SENSOR_2_GPIO) == 0 && running) {
                gpioDelay(1000); // Wait for the sensor to return to inactive state
            }
        }
        sensor2_state = sensor2_current_state;

        gpioDelay(POLL_MS * 1000); // Poll every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

