#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define sampling rate and LED duration
#define SAMPLING_RATE 8000 // Hz
#define LED_DURATION 100    // ms

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to get current timestamp in milliseconds
void get_timestamp(char *timestamp)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);
    sprintf(timestamp, "%ld", milliseconds);
}

// Function to read the microphone pin
int read_microphone()
{
    int value = gpioRead(MIC_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading microphone pin: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Function to control the LED
void control_led(int on)
{
    if (gpioWrite(LED_PIN, on) < 0) {
        fprintf(stderr, "Error writing to LED pin\n");
    }
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(MIC_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting microphone pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read microphone pin
        int mic_value = read_microphone();
        if (mic_value < 0) {
            // Error already printed in read_microphone function
            break; // Exit loop on error
        }

        // Check for sound peak
        if (mic_value == 1) {
            // Get timestamp
            char timestamp[20];
            get_timestamp(timestamp);

            // Print timestamp
            printf("%s\n", timestamp);

            // Turn on LED
            control_led(1);

            // Wait for LED duration
            gpioDelay(LED_DURATION * 1000); // Convert ms to microseconds

            // Turn off LED
            control_led(0);
        }

        // Delay for sampling rate
        gpioDelay(125000); // 125 us in microseconds
    }

    // Clean up
    control_led(0); // Ensure LED is off
    gpioTerminate(); // Terminate pigpio

    printf("Program terminated gracefully.\n");
    return 0;
}

