#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23

// I2C bus number
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read a 16-bit value from the Si1175
int read_si1175_als(int i2c_handle) {
    int als_lsb, als_msb;

    als_lsb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_DATA0);
    if (als_lsb < 0) {
        fprintf(stderr, "Error reading ALS LSB: %d\n", als_lsb);
        return -1;
    }

    als_msb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_DATA1);
    if (als_msb < 0) {
        fprintf(stderr, "Error reading ALS MSB: %d\n", als_msb);
        return -1;
    }

    return (als_msb << 8) | als_lsb;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int als_value = read_si1175_als(i2c_handle);

        if (als_value >= 0) {
            printf("ALS Value: %d\n", als_value);
        } else {
            fprintf(stderr, "Failed to read ALS value\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

