// Define GPIO pins for the sensors
#define LEFT_SENSOR 2
#define MIDDLE_SENSOR 3
#define RIGHT_SENSOR 4

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to format the sensor data into a string
void format_data(int left, int middle, int right, char *buffer, size_t buffer_size) {
    snprintf(buffer, buffer_size, "L:%d M:%d R:%d", left, middle, right);
}

// Function to log the sensor data with a timestamp
void log_data(const char *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, data);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to read and log sensor data
    while (program_running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR);
        int middle_value = read_sensor(MIDDLE_SENSOR);
        int right_value = read_sensor(RIGHT_SENSOR);

        // Check for errors during sensor reading
        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            // If an error occurred, skip logging this iteration
            gpioDelay(100); // Wait 100ms regardless of error
            continue;
        }

        // Format the sensor data
        char data_buffer[50];
        format_data(left_value, middle_value, right_value, data_buffer, sizeof(data_buffer));

        // Log the sensor data
        log_data(data_buffer);

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

