#include <time.h>
#include <string.h>

// Define GPIO pins for each channel
#define CH1 5
#define CH2 6
#define CH3 13
#define CH4 19
#define CH5 26
#define CH6 12
#define CH7 16
#define CH8 20

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read the state of a single channel
int read_channel(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to format the sensor data into a string
char* format_data(int ch1, int ch2, int ch3, int ch4, int ch5, int ch6, int ch7, int ch8) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    static char buffer[256]; // Static buffer to hold the formatted string
    snprintf(buffer, sizeof(buffer), "%.3f", timestamp);
    char *ptr = buffer + strlen(buffer);
    ptr -= 2; // Move pointer back to overwrite the last two characters
    ptr[0] = 's';
    ptr[1] = ']';

    snprintf(buffer, sizeof(buffer), "%s CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d",
             buffer, ch1, ch2, ch3, ch4, ch5, ch6, ch7, ch8);

    return buffer;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(CH1, PI_INPUT);
    gpioSetMode(CH2, PI_INPUT);
    gpioSetMode(CH3, PI_INPUT);
    gpioSetMode(CH4, PI_INPUT);
    gpioSetMode(CH5, PI_INPUT);
    gpioSetMode(CH6, PI_INPUT);
    gpioSetMode(CH7, PI_INPUT);
    gpioSetMode(CH8, PI_INPUT);

    // Main loop to read sensor data and print to console
    while (!terminate) {
        int ch1 = read_channel(CH1);
        int ch2 = read_channel(CH2);
        int ch3 = read_channel(CH3);
        int ch4 = read_channel(CH4);
        int ch5 = read_channel(CH5);
        int ch6 = read_channel(CH6);
        int ch7 = read_channel(CH7);
        int ch8 = read_channel(CH8);

        char* data_string = format_data(ch1, ch2, ch3, ch4, ch5, ch6, ch7, ch8);
        printf("%s\n", data_string);

        gpioDelay(200); // Delay for 200 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");
    return 0;
}
