#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency and range
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

// Define interpolation steps and duration
#define INTERPOLATION_STEPS 50
#define INTERPOLATION_DURATION 5 // seconds

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_rgb_pwm(int red, int green, int blue);
void interpolate_hue(int current_red, int current_green, int current_blue, int target_red, int target_green, int target_blue, int step);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Function to initialize GPIO and pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
