#include <time.h>
#include <errno.h>
#include <string.h>

// TCS34725 Registers
#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// GPIO Pin for LED
#define LED_PIN 17

// Threshold for Red Value
#define RED_THRESHOLD 200

// Integration Time (ms)
#define INTEGRATION_TIME 154

// I2C Bus
#define I2C_BUS 1

// Global Variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int tcs34725_init(int fd);
int tcs34725_read_raw_data(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c);
int tcs34725_calibrate_data(uint16_t r, uint16_t g, uint16_t b, uint16_t c, uint16_t *calibrated_r, uint16_t *calibrated_g, uint16_t *calibrated_b, uint16_t *calibrated_c);
void gpio_set_led(int pin, int value);
void signal_handler(int signal);

// I2C Write Function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C Write Failed");
        return -1;
    }
    return 0;
}

// I2C Read Function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C Write (register select) Failed");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("I2C Read Failed");
        return -1;
    }
    return 0;
}

// TCS34725 Initialization Function
int tcs34725_init(int fd) {
    // Enable RGBC
    if (i2c_write_byte(fd, TCS34725_ENABLE, 0x03) != 0) {
        fprintf(stderr, "Failed to enable RGBC\n");
        return -1;
    }

    // Set Integration Time
    uint8_t atime = 0xEB; // 154ms
    if (i2c_write_byte(fd, TCS34725_ATIME, atime) != 0) {
        fprintf(stderr, "Failed to set integration time\n");
        return -1;
    }

    // Set Gain (Optional, default is 1x)
    if (i2c_write_byte(fd, TCS34725_CONTROL, 0x00) != 0) {
        fprintf(stderr, "Failed to set gain\n");
        return -1;
    }

    return 0;
}

// TCS34725 Read Raw Data Function
int tcs34725_read_raw_data(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t buf[8];

    if (i2c_read_bytes(fd, TCS34725_CDATA | TCS34725_COMMAND_BIT, buf, 8) != 0) {
        fprintf(stderr, "Failed to read raw data\n");
        return -1;
    }

    *c = (buf[1] << 8) | buf[0];
    *r = (buf[3] << 8) | buf[2];
    *g = (buf[5] << 8) | buf[4];
    *b = (buf[7] << 8) | buf[6];

    return 0;
}

// TCS34725 Calibrate Data Function
int tcs34725_calibrate_data(uint16_t r, uint16_t g, uint16_t b, uint16_t c, uint16_t *calibrated_r, uint16_t *calibrated_g, uint16_t *calibrated_b, uint16_t *calibrated_c) {
    // Simple calibration (replace with actual calibration data)
