void gpio_set_led(int pin, int value) {
    gpioWrite(pin, value);
}

// Signal Handler Function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    uint16_t r, g, b, c, calibrated_r, calibrated_g, calibrated_b, calibrated_c;
    struct timespec sleep_time = {0, 200000000}; // 200ms

    // Main loop
    while (program_running) {
        // Read raw data
        if (tcs34725_read_raw_data(i2c_fd, &r, &g, &b, &c) == 0) {
            // Calibrate data
            if (tcs34725_calibrate_data(r, g, b, c, &calibrated_r, &calibrated_g, &calibrated_b, &calibrated_c) == 0) {
                // Print calibrated values
                printf("R: %u, G: %u, B: %u, C: %u\n", calibrated_r, calibrated_g, calibrated_b, calibrated_c);

                // Control LED based on red value
                if (calibrated_r > RED_THRESHOLD) {
                    gpio_set_led(LED_PIN, 1); // Turn LED on
                } else {
                    gpio_set_led(LED_PIN, 0); // Turn LED off
                }
            } else {
                fprintf(stderr, "Calibration failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Re-initializing...\n");
            // Attempt to re-initialize the sensor
            if (tcs34725_init(i2c_fd) != 0) {
                fprintf(stderr, "TCS34725 re-initialization failed\n");
                program_running = 0; // Exit loop if re-initialization fails
            }
        }

        // Sleep for 200ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

