#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define PWM_PIN 18 // BCM GPIO 18
#define NUM_LEDS 10
#define PWM_RANGE 1024
#define PWM_CLOCK 192 // Adjust for desired frequency (e.g., 800kHz)

// Global variables
static volatile int running = 1;
static int i2c_fd;
static int pwm_clock = PWM_CLOCK;

// Function prototypes
int init_i2c(int address);
int read_bh1750(int fd);
float calculate_lux(int raw_value);
float map_lux_to_brightness(float lux);
void set_led_brightness(int led_num, float brightness);
void cleanup(int signal);

// Signal handler
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    // Turn off all LEDs
    for (int i = 0; i < NUM_LEDS; i++) {
        set_led_brightness(i, 0.0);
    }
    // Disable PWM output
    pwmWrite(PWM_PIN, 0);
    // Close I2C connection
    close(i2c_fd);
    exit(0);
}

// Initialize I2C
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Read data from BH1750 sensor
int read_bh1750(int fd) {
    int retries = 3;
    int raw_value = -1;

    while (retries > 0) {
        if (wiringPiI2CWrite(fd, CONTINUOUS_HIGH_RES_MODE) == -1) {
            fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
            retries--;
            delay(10); // Small delay before retry
            continue;
        }

        delay(180); // Wait for measurement (at least 180ms)

        raw_value = wiringPiI2CReadReg16(fd, 0);
        if (raw_value == -1) {
            fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
            retries--;
            delay(10); // Small delay before retry
