#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define NUM_LEDS 10
#define SPI_CLOCK_SPEED 1000000 // 1 MHz
#define START_FRAME 0x00000000
#define END_FRAME 0xFFFFFFFF

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
int udp_socket = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int bh1750_init(int fd);
int bh1750_read_light_level(int fd);
float bh1750_calculate_lux(int raw_value);
int apa102_init(int fd);
int apa102_set_led(int fd, int led_index, uint8_t r, uint8_t g, uint8_t b, uint8_t brightness);
int apa102_send_data(int fd, uint32_t *data, int num_leds);
int send_data_to_server(const char *server_ip, int server_port, uint32_t *data, int num_leds);
void signal_handler(int sig);
void cleanup();

// BH1750 functions
int bh1750_init(int fd) {
    if (fd < 0) return -1;
    // No initialization needed for BH1750, just set the mode
    return 0;
}

int bh1750_read_light_level(int fd) {
    if (fd < 0) return -1;

    uint8_t config = 0x10; // Continuous high resolution mode
    if (write(fd, &config, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    usleep(120000); // Wait for measurement (at least 120ms)

    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

float bh1750_calculate_lux(int raw_value) {
    return (float)raw_value / 1.2;
}

// APA102 functions
int apa102_init(int fd) {
    if (fd < 0) return -1;
    // No specific initialization needed for APA102, just configure SPI
    return 0;
}

int apa102_set_led(int fd, int led_index, uint8_t r, uint8_t g, uint8_t b, uint8_t brightness) {
    if (fd < 0) return -1;
    if (led_index < 0 || led_index >= NUM_LEDS) return -1;

    uint32_t frame = 0;
    frame |= (0xE0000000 >> 8); // Global brightness (adjust as needed)
    frame |= ((uint32_t)led_index << 24); // LED index
    frame |= ((uint32_t)b << 16); // Blue
    frame |= ((uint32_t)g << 8);  // Green
    frame |= (uint32_t)r;        // Red

    uint8_t data[4];
    data[0] = (frame >> 24) & 0xFF;
    data[1] = (frame >> 16) & 0xFF;
    data[2] = (frame >> 8) & 0xFF;
    data[3] = frame & 0xFF;

    if (write(fd, data, 4) != 4) {
        perror("Failed to write to SPI device");
        return -1;
    }

    return 0;
}

int apa102_send_data(int fd, uint32_t *data, int num_leds) {
    if (fd < 0) return -1;
    if (data == NULL || num_leds <= 0) return -1;

    // Start frame
    uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    if (write(fd, start_frame, 4) != 4) {
        perror("Failed to write start frame");
        return -1;
    }

    // LED frames
    for (int i = 0; i < num_leds; i++) {
        uint8_t led_data[4];
        led_data[0] = (data[i] >> 24) & 0xFF;
        led_data[1] = (data[i] >> 16) & 0xFF;
        led_data[2] = (data[i] >> 8) & 0xFF;
        led_data[3] = data[i] & 0xFF;
        if (write(fd, led_data, 4) != 4) {
            perror("Failed to write LED frame");
            return -1;
        }
    }

    // End frame
    uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    if (write(fd, end_frame, 4) != 4) {
        perror("Failed to write end frame");
        return -1;
    }

    return 0;
}

// Network functions
int send_data_to_server(const char *server_ip, int server_port, uint32_t *data, int num_leds) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid server IP address");
        return -1;
    }

    if (sendto(udp_socket, data, num_leds * 4, 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to send data to server");
        return -1;
    }

    return 0;
}

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        terminate = 1;
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }

    printf("Cleanup complete.\n");
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize SPI
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI bus");
        cleanup();
        return 1;
    }

    uint8_t mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return 1;
    }

    uint8_t bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
        return 1;
    }

    uint32_t speed = SPI_CLOCK_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        cleanup();
        return 1;
    }

    if (apa102_init(spi_fd) < 0) {
        fprintf(stderr, "APA102 initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create UDP socket");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read light level
        int raw_light_level = bh1750_read_light_level(i2c_fd);
        if (raw_light_level < 0) {
            fprintf(stderr, "Failed to read light level\n");
            continue; // Or exit, depending on error handling strategy
        }

        float lux = bh1750_calculate_lux(raw_light_level);

        // Map lux to brightness (0-255)
        uint8_t brightness = (uint8_t)(lux / 100.0 * 255.0); // Adjust scaling as needed
        if (brightness > 255) brightness = 255;
        if (brightness < 0) brightness = 0;

        // Set LED brightness
        uint32_t led_data[NUM_LEDS];
        for (int i = 0; i < NUM_LEDS; i++) {
            led_data[i] = 0x00000000; // Start with black
            uint8_t r = (brightness > 128) ? 255 : 0;
            uint8_t g = (brightness > 192) ? 255 : 0;
            uint8_t b = (brightness > 64) ? 255 : 0;
            apa102_set_led(spi_fd, i, r, g, b, brightness);
            led_data[i] = (0xE0000000 >> 8) | ((uint32_t)i << 24) | ((uint32_t)b << 16) | ((uint32_t)g << 8) | (uint32_t)r;
        }

        // Send data to server
        if (send_data_to_server(SERVER_IP, SERVER_PORT, led_data, NUM_LEDS) < 0) {
            fprintf(stderr, "Failed to send data to server\n");
        }

        // Send data to APA102 strip
        if (apa102_send_data(spi_fd, led_data, NUM_LEDS) < 0) {
            fprintf(stderr, "Failed to send data to APA102 strip\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

