        cleanup();
        return 1;
    }

    uint32_t speed = SPI_CLOCK_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        cleanup();
        return 1;
    }

    if (apa102_init(spi_fd) < 0) {
        fprintf(stderr, "APA102 initialization failed\n");
        cleanup();
        return 1;
    }

