        if (raw_light_level < 0) {
            fprintf(stderr, "Failed to read light level\n");
            continue; // Or exit, depending on error handling strategy
        }

        float lux = bh1750_calculate_lux(raw_light_level);

        // Map lux to brightness (0-255)
        uint8_t brightness = (uint8_t)(lux / 100.0 * 255.0); // Adjust scaling as needed
        if (brightness > 255) brightness = 255;
        if (brightness < 0) brightness = 0;

        // Set LED brightness
        uint32_t led_data[NUM_LEDS];
        for (int i = 0; i < NUM_LEDS; i++) {
            led_data[i] = 0x00000000; // Start with black
            uint8_t r = (brightness > 128) ? 255 : 0;
            uint8_t g = (brightness > 192) ? 255 : 0;
            uint8_t b = (brightness > 64) ? 255 : 0;
            apa102_set_led(spi_fd, i, r, g, b, brightness);
            led_data[i] = (0xE0000000 >> 8) | ((uint32_t)i << 24) | ((uint32_t)b << 16) | ((uint32_t)g << 8) | (uint32_t)r;
        }

        // Send data to server
        if (send_data_to_server(SERVER_IP, SERVER_PORT, led_data, NUM_LEDS) < 0) {
            fprintf(stderr, "Failed to send data to server\n");
        }

        // Send data to APA102 strip
        if (apa102_send_data(spi_fd, led_data, NUM_LEDS) < 0) {
            fprintf(stderr, "Failed to send data to APA102 strip\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

