#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <wiringPiSPI.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Configuration
#define NUM_SENSORS 3
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x5C
#define BH1750_ADDR_3 0x60
#define I2C_BUS 1
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_LEDS 10
#define FADE_DURATION 500 // milliseconds
#define LOOP_DELAY 100    // milliseconds

// Global variables
int i2c_handles[NUM_SENSORS];
int spi_fd;
bool running = true;

// Function prototypes
int init_bh1750(int address);
int read_bh1750(int fd);
float average_light_level(int sensor_values[], int num_sensors);
void set_apa102_brightness(int brightness);
void fade_brightness(int current_brightness, int target_brightness);
void signal_handler(int signal);

// BH1750 Initialization
int init_bh1750(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing BH1750 at address 0x%02X: %s\n", address, strerror(errno));
        return -1;
    }
    return fd;
}

// BH1750 Reading
int read_bh1750(int fd) {
    int reading = wiringPiI2CReadReg16(fd, 0x00); // No register address needed for BH1750
    if (reading == -1) {
        fprintf(stderr, "Error reading from BH1750: %s\n", strerror(errno));
        return -1;
    }
    return reading;
}

// Light Level Averaging
float average_light_level(int sensor_values[], int num_sensors) {
    float sum = 0.0;
    int valid_count = 0;
    for (int i = 0; i < num_sensors; i++) {
        if (sensor_values[i] != -1) {
            sum += sensor_values[i];
            valid_count++;
        }
    }
    if (valid_count == 0) {
        return 0.0; // Avoid division by zero
    }
    return sum / valid_count;
}

// APA102 Brightness Control
void set_apa102_brightness(int brightness) {
    unsigned char buffer[4 + (NUM_LEDS * 4) + 4]; // Start frame + LED data + End frame
    memset(buffer, 0x00, sizeof(buffer));

    // Start frame (4 bytes of 0x00)
    for (int i = 0; i < 4; i++) {
        buffer[i] = 0x00;
    }

    // LED data (4 bytes per LED: 0xE0 + brightness + 0x00 + 0x00)
    for (int i = 0; i < NUM_LEDS; i++) {
        buffer[4 + (i * 4)] = 0xE0 | (brightness & 0x1F); // Global brightness
        buffer[4 + (i * 4) + 1] = 0x00; // Red
        buffer[4 + (i * 4) + 2] = 0x00; // Green
        buffer[4 + (i * 4) + 3] = 0x00; // Blue
    }

    // End frame (4 bytes of 0xFF)
    for (int i = 0; i < 4; i++) {
        buffer[sizeof(buffer) - 4 + i] = 0xFF;
    }

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, sizeof(buffer));
}

// Brightness Fading
void fade_brightness(int current_brightness, int target_brightness) {
    int difference = target_brightness - current_brightness;
    int steps = FADE_DURATION / LOOP_DELAY;
    int increment = (difference * 1000) / (steps * LOOP_DELAY); // Scale increment to brightness level

    for (int i = 0; i < steps; i++) {
        current_brightness += increment;
        if (current_brightness > 255) current_brightness = 255;
        if (current_brightness < 0) current_brightness = 0;
        set_apa102_brightness(current_brightness);
        delay(LOOP_DELAY);
    }
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = false;

    // Turn off LEDs
    set_apa102_brightness(0);

    // Close I2C handles
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] != -1) {
            close(i2c_handles[i]);
        }
    }

    // Close SPI handle
    if (spi_fd != -1) {
        close(spi_fd);
    }

    exit(0);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_handles[0] = init_bh1750(BH1750_ADDR_1);
    i2c_handles[1] = init_bh1750(BH1750_ADDR_2);
    i2c_handles[2] = init_bh1750(BH1750_ADDR_3);

    // Initialize SPI
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    int sensor_values[NUM_SENSORS];
    int current_brightness = 0;
    int target_brightness;

    while (running) {
        // Read sensor values
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = -1; // Initialize to invalid value
            if (i2c_handles[i] != -1) {
                delay(180); // Wait for conversion
                sensor_values[i] = read_bh1750(i2c_handles[i]);
            }
        }

        // Calculate average light level
        float average_light = average_light_level(sensor_values, NUM_SENSORS);

        // Map light level to brightness (0-255)
        target_brightness = (int)(average_light * 2.55); // Assuming 0-1000 lux range
        if (target_brightness > 255) {
            target_brightness = 255;
        }
        if (target_brightness < 0) {
            target_brightness = 0;
        }

        // Fade to target brightness
        fade_brightness(current_brightness, target_brightness);
        current_brightness = target_brightness;

        // Delay
        delay(LOOP_DELAY);
    }

    return 0;
}

