#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x48

// VEML7700 register addresses
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_WH 0x01
#define VEML7700_ALS_WL 0x02
#define VEML7700_ALS 0x04
#define VEML7700_WHITE 0x05
#define VEML7700_POWER_SAVE 0x06

// GPIO pin for WS2812B data line
#define WS2812B_GPIO 18

// Gamma correction exponent
#define GAMMA 2.2

// Number of LEDs in the strip
#define NUM_LEDS 1

// I2C retry parameters
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_veml7700();
float read_lux();
float gamma_correct(float brightness);
void set_led_color(uint8_t red, uint8_t green, uint8_t blue);
void signal_handler(int signal);

// Structure to hold LED data
typedef struct {
    uint8_t red;
    uint8_t green;
    uint8_t blue;
} led_data_t;

led_data_t led_data = {0, 0, 0}; // Initialize LED color to black

// Function to initialize the VEML7700 sensor
int init_veml7700() {
    // Configuration: Integration time = 100ms, Gain = 1/8
    uint8_t config_data[2] = {0x02, 0x00}; // IT = 100ms, Gain = 1/8
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700 configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the ambient light level from the VEML7700 sensor
float read_lux() {
    uint8_t data[2];
    int result;

    // Read ALS data (2 bytes)
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        return -1.0;
    }

    // Combine the two bytes to form the ALS value
    uint16_t als_value = (data[1] << 8) | data[0];

    // Convert ALS value to lux (example formula, adjust as needed)
    float lux = (float)als_value * 0.0576; // Example conversion factor

    return lux;
}

// Function to apply gamma correction to the brightness value
float gamma_correct(float brightness) {
    return powf(brightness, GAMMA);
}

// Function to set the color of the WS2812B LED strip
void set_led_color(uint8_t red, uint8_t green, uint8_t blue) {
    // Bit-banging implementation
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    // WS2812B timing (in nanoseconds)
    const int T0H = 350;  // 0 bit high time
    const int T0L = 800;  // 0 bit low time
    const int T1H = 700;  // 1 bit high time
    const int T1L = 450;  // 1 bit low time
    const int T_RESET = 50; // Reset pulse

    // Reset pulse
    gpioWrite(WS2812B_GPIO, 0);
    gpioDelay(T_RESET);

    // Send data (G, R, B)
    for (int i = 0; i < 24; i++) {
        uint8_t bit = (i < 8) ? (green >> (7 - i)) : ((i < 16) ? (red >> (15 - i)) : (blue >> (23 - i)));

        if (bit) {
            gpioWrite(WS2812B_GPIO, 1);
            gpioDelay(T1H);
            gpioWrite(WS2812B_GPIO, 0);
            gpioDelay(T1L);
        } else {
            gpioWrite(WS2812B_GPIO, 1);
            gpioDelay(T0H);
            gpioWrite(WS2812B_GPIO, 0);
            gpioDelay(T0L);
        }
    }

    // Reset pulse after data transmission
    gpioWrite(WS2812B_GPIO, 0);
    gpioDelay(T_RESET);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (init_veml7700() != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read lux value
        float lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value\n");
        } else {
            // Calculate brightness (example: linear mapping)
            float brightness = lux / 100.0; // Adjust scaling as needed
            if (brightness > 1.0) brightness = 1.0;

            // Apply gamma correction
            brightness = gamma_correct(brightness);

            // Set LED color (example: green)
            set_led_color(0, (uint8_t)(brightness * 255.0), 0);

            // Print lux and brightness values
            printf("Lux: %.2f, Brightness: %.2f\n", lux, brightness);
        }

        // Pause for 200ms
        gpioDelay(200000); // 200ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

