#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define BUFFER_SIZE 60

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_bh1750(int fd);
void init_circular_buffer(CircularBuffer *cb);
void add_reading(CircularBuffer *cb, float lux);
float calculate_average(CircularBuffer *cb);
void set_gpio_output(int pin, int value);
void signal_handler(int sig);

// Function to initialize the I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read the BH1750 sensor
int read_bh1750(int fd) {
    uint8_t config = CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(200000); // Wait for measurement (at least 180ms)

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    uint16_t raw_value = (data[0] << 8) | data[1];
    float lux = (float)raw_value / 1.2;
    return (int)lux;
}

// Function to initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Function to add a reading to the circular buffer
void add_reading(CircularBuffer *cb, float lux) {
    cb->buffer[cb->head] = lux;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to calculate the average of the readings in the circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Function to set the GPIO output
void set_gpio_output(int pin, int value) {
    char buffer[64];
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return;
    }

    if (write(fd, value ? "1" : "0", 1) != 1) {
        perror("Error writing to GPIO value file");
    }

    close(fd);
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize GPIO
    char buffer[64];
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d", GPIO_PIN);
    if (access(buffer, F_OK) == -1) {
        snprintf(buffer, sizeof(buffer), "/sys/class/gpio/export");
        int fd = open(buffer, O_WRONLY);
        if (fd < 0) {
            perror("Error opening GPIO export file");
            close(i2c_fd);
            return 1;
        }
        char pin_str[3];
        snprintf(pin_str, sizeof(pin_str), "%d", GPIO_PIN);
        if (write(fd, pin_str, strlen(pin_str)) != strlen(pin_str)) {
            perror("Error writing to GPIO export file");
            close(fd);
            close(i2c_fd);
            return 1;
        }
        close(fd);
        usleep(100000); // Wait for GPIO to be created
    }

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/direction", GPIO_PIN);
    int fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction file");
        close(i2c_fd);
        return 1;
    }
    if (write(fd, "out", 3) != 3) {
        perror("Error writing to GPIO direction file");
        close(fd);
        close(i2c_fd);
        return 1;
    }
    close(fd);

    // Initialize circular buffer
    CircularBuffer lux_buffer;
    init_circular_buffer(&lux_buffer);

    // Main loop
    while (program_running) {
        int lux = read_bh1750(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Error reading sensor, skipping.\n");
        } else {
            add_reading(&lux_buffer, (float)lux);
            float average_lux = calculate_average(&lux_buffer);

            // Calculate frequency based on average lux
            float frequency = 0.5 + (average_lux / 1000.0) * 4.5; // Linear mapping from 0.5Hz to 5Hz

            // Blink LED with square wave
            struct timespec on_time = {0, 500000000 / frequency}; // 50% duty cycle
            struct timespec off_time = {0, 500000000 / frequency};

            set_gpio_output(GPIO_PIN, 1);
            nanosleep(&on_time, NULL);
            set_gpio_output(GPIO_PIN, 0);
            nanosleep(&off_time, NULL);
        }

        sleep(1);
    }

    // Cleanup
    close(i2c_fd);

    // Unexport GPIO
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/unexport");
    int fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO unexport file");
    } else {
        char pin_str[3];
        snprintf(pin_str, sizeof(pin_str), "%d", GPIO_PIN);
        if (write(fd, pin_str, strlen(pin_str)) != strlen(pin_str)) {
            perror("Error writing to GPIO unexport file");
        }
        close(fd);
    }

    return 0;
}

