            // Calculate frequency based on average lux
            float frequency = 0.5 + (average_lux / 1000.0) * 4.5; // Linear mapping from 0.5Hz to 5Hz

            // Blink LED with square wave
            struct timespec on_time = {0, 500000000 / frequency}; // 50% duty cycle
            struct timespec off_time = {0, 500000000 / frequency};

            set_gpio_output(GPIO_PIN, 1);
            nanosleep(&on_time, NULL);
            set_gpio_output(GPIO_PIN, 0);
            nanosleep(&off_time, NULL);
        }

        sleep(1);
    }

    // Cleanup
    close(i2c_fd);

    // Unexport GPIO
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/unexport");
    int fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO unexport file");
    } else {
        char pin_str[3];
        snprintf(pin_str, sizeof(pin_str), "%d", GPIO_PIN);
        if (write(fd, pin_str, strlen(pin_str)) != strlen(pin_str)) {
            perror("Error writing to GPIO unexport file");
        }
        close(fd);
    }

    return 0;
}

