#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define segment mapping for digit '5'
#define SEGMENT_DATA 0b01101100

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(DATA_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting DATA_PIN as output\n");
        return -1;
    }
    if (gpioSetMode(CLOCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting CLOCK_PIN as output\n");
        return -1;
    }
    if (gpioSetMode(LATCH_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting LATCH_PIN as output\n");
        return -1;
    }
    return 0;
}

// Function to shift out data to the 74HC595
void shift_out(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        // Set data pin based on the current bit
        gpioWrite(DATA_PIN, (data >> (7 - i)) & 0x01);

        // Clock the data in
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1); // Small delay for clock high
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(1); // Small delay for clock low
    }
}

// Function to latch the data to the output
void latch_data() {
    gpioWrite(LATCH_PIN, 1);
    gpioDelay(1); // Small delay for latch high
    gpioWrite(LATCH_PIN, 0);
    gpioDelay(1); // Small delay for latch low
}

// Function to display a digit on the seven-segment display
void display_digit(unsigned char digit) {
    shift_out(digit);
    latch_data();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Seven-segment display control started. Press Ctrl+C to exit.\n");

    // Main loop to blink the digit '5'
    while (program_running) {
        display_digit(SEGMENT_DATA);
        gpioDelay(500); // On for 500ms

        // Turn off the display (all segments off)
        shift_out(0x00);
        latch_data();
        gpioDelay(500); // Off for 500ms
    }

    // Clean up GPIO pins before exiting
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    gpioTerminate();

    printf("Seven-segment display control stopped.\n");

    return 0;
}

