#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define GPIO chip
#define GPIOCHIP 0

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *button_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
int blink_led(void);
int button_pressed(void);
void cleanup(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        terminate = 1;
    }
}

// GPIO initialization function
int gpio_init(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_number(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request LED line as output
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "blink_button", 0) < 0) {
        perror("Error requesting LED line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        return -1;
    }

    // Request button line as input with pull-up
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        return -1;
    }

    if (gpiod_line_request_input(button_line, "blink_button") < 0) {
        perror("Error requesting button line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return -1;
    }

    // Set pull-up resistor
    if (gpiod_line_set_pull_up_down(button_line, GPIOD_LINE_REQUEST_FALLING_EDGE) < 0) {
        perror("Error setting pull-up resistor");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return -1;
    }

    return 0;
}

// Blink LED function
int blink_led(void) {
    struct timespec on_time = {1, 0}; // 1 second
    struct timespec off_time = {1, 0}; // 1 second

    while (!terminate) {
        // Turn LED on
        if (gpiod_line_set_value(led_line, 1) < 0) {
            perror("Error setting LED value");
            return -1;
        }

        // Wait for 1 second
        if (nanosleep(&on_time, NULL) < 0) {
            perror("nanosleep failed");
            return -1;
        }

        // Turn LED off
        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("Error setting LED value");
            return -1;
        }

        // Wait for 1 second
        if (nanosleep(&off_time, NULL) < 0) {
            perror("nanosleep failed");
            return -1;
        }
    }

    return 0;
}

// Button press detection function
int button_pressed(void) {
    struct timespec timeout = {1, 0}; // 1 second timeout
    struct timespec remaining;

    // Wait for a falling edge event with a timeout
    int ret = gpiod_line_event_wait(button_line, GPIOD_LINE_EVENT_FALLING_EDGE, &timeout, &remaining);

    if (ret < 0) {
        perror("Error waiting for falling edge event");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for falling edge event\n");
        return 0; // Timeout
    }

    // Falling edge detected
    printf("Button pressed!\n");
    return 1;
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");

    // Turn off LED
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }

    // Release button line
    if (button_line) {
        gpiod_line_release(button_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    printf("Blinking LED and waiting for button press...\n");

    // Blink LED in a separate thread (not implemented here for simplicity)
    // In a real application, you would create a separate thread to handle the blinking.
    // For this example, we'll just blink in the main thread and check for the button press.

    // Main loop
    while (!terminate) {
        // Check for button press
        if (button_pressed()) {
            // Stop blinking
            terminate = 1;
            break;
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

