    // Register signal handler for Ctrl-C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Program started. Press Ctrl-C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button state
        int button_state = gpioRead(BUTTON_PIN);

        // If button is pressed (HIGH)
        if (button_state == 1) {
            // Blink the LED
            blink_led();
        } else {
            // Turn LED off if button is not pressed
            gpioWrite(LED_PIN, 0);
        }

        // Small delay to prevent busy-waiting
        gpioDelay(10); // 10ms delay
    }

    // Clean up GPIO resources before exiting
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

