    fprintf(stderr, "Program started. Press Ctrl-C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button state
        int button_state = gpioRead(BUTTON_PIN);

        // If button is pressed (HIGH)
        if (button_state == 1) {
            // Blink the LED
            blink_led();
        } else {
            // Turn LED off if button is not pressed
            gpioWrite(LED_PIN, 0);
        }

        // Small delay to prevent busy-waiting
        gpioDelay(10); // 10ms delay
    }

