#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LSM303_ADDRESS 0x19 // Or 0x18, check your sensor
#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE_HZ)
#define PULSE_DURATION_MS 50

// Global variables
int i2c_handle;
double impact_threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_accelerometer();
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void trigger_impact_interrupt();
void log_data(int16_t x, int16_t y, int16_t z, double magnitude);
void signal_handler(int signal);
void cleanup();

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            impact_threshold = atof(argv[i + 1]);
            i++;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Configure accelerometer
    if (configure_accelerometer() != 0) {
        fprintf(stderr, "Accelerometer configuration failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    accelerometer_data_t data;
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer_data(&data.x, &data.y, &data.z) == 0) {
            // Calculate magnitude
            double magnitude = calculate_magnitude(data.x, data.y, data.z);

            // Check for impact
            if (magnitude > impact_threshold) {
                trigger_impact_interrupt();
                log_data(data.x, data.y, data.z, magnitude);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        // Delay for sample rate
        gpioDelay(SAMPLE_PERIOD_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure accelerometer
int configure_accelerometer() {
    // Enable accelerometer and set data rate (10 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) { //0x27 = 0b00100111
        fprintf(stderr, "Failed to write to CTRL_REG1_A\n");
        return 1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) != 6) { // Enable auto-increment
        fprintf(stderr, "Failed to read accelerometer data\n");
        return 1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    // Convert raw values to G (assuming +/- 2G range, 16-bit resolution)
    double x_g = (double)x / 16384.0;
    double y_g = (double)y / 16384.0;
    double z_g = (double)z / 16384.0;

    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Trigger impact interrupt
void trigger_impact_interrupt() {
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 1);
    gpioDelay(PULSE_DURATION_MS * 1000); // pigpioDelay takes microseconds
    gpioWrite(GPIO_PIN, 0);
}

// Log data
void log_data(int16_t x, int16_t y, int16_t z, double magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f G\n", s, x, y, z, magnitude);
    fclose(fp);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

