#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define ALS_LSB_REG 0x04
#define ALS_MSB_REG 0x05
#define RED_LSB_REG 0x06
#define RED_MSB_REG 0x07
#define GREEN_LSB_REG 0x08
#define GREEN_MSB_REG 0x09
#define BLUE_LSB_REG 0x0A
#define BLUE_MSB_REG 0x0B
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue);
void map_als_to_pwm(uint16_t als, int *pwm_value);
void log_data(FILE *log_file, uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }
    rewind(log_file);

    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[2];
    int retries = 0;

    // Read ALS
    buf[0] = ALS_LSB_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to ALS LSB register\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading ALS data\n");
        return -1;
    }
    *als = (uint16_t)((buf[1] << 8) | buf[0]);

    // Read Red
    buf[0] = RED_LSB_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to Red LSB register\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading Red data\n");
        return -1;
    }
    *red = (uint16_t)((buf[1] << 8) | buf[0]);

    // Read Green
    buf[0] = GREEN_LSB_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to Green LSB register\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading Green data\n");
        return -1;
    }
    *green = (uint16_t)((buf[1] << 8) | buf[0]);

    // Read Blue
    buf[0] = BLUE_LSB_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to Blue LSB register\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading Blue data\n");
        return -1;
    }
    *blue = (uint16_t)((buf[1] << 8) | buf[0]);

    return 0;
}

// Function to map ALS value to PWM duty cycle
void map_als_to_pwm(uint16_t als, int *pwm_value) {
    // Simple linear mapping
