#define FXOS8700CQ_WHO_AM_I 0x0D
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_CTRL_REG2 0x2B
#define FXOS8700CQ_OUT_X_MSB 0x01
#define FXOS8700CQ_OUT_X_LSB 0x02
#define FXOS8700CQ_OUT_Y_MSB 0x03
#define FXOS8700CQ_OUT_Y_LSB 0x04
#define FXOS8700CQ_OUT_Z_MSB 0x05
#define FXOS8700CQ_OUT_Z_LSB 0x06

// Expected WHO_AM_I value
#define FXOS8700CQ_WHO_AM_I_VALUE 0xC7

// Impact threshold (in g)
#define IMPACT_THRESHOLD 1.5

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_fxos8700cq();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_acceleration_magnitude(int16_t x, int16_t y, int16_t z);
int log_impact(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the FXOS8700CQ sensor
int init_fxos8700cq() {
    int status;

    // Verify WHO_AM_I register
    status = i2cReadByteData(i2c_handle, FXOS8700CQ_WHO_AM_I);
    if (status < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", status);
        return -1;
    }
    if ((status & 0xFF) != FXOS8700CQ_WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x%02X, got 0x%02X\n", FXOS8700CQ_WHO_AM_I_VALUE, status & 0xFF);
        return -1;
    }
    fprintf(stderr, "WHO_AM_I check passed. Value: 0x%02X\n", status & 0xFF);

    // Put the device in standby mode
    status = i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby): %d\n", status);
        return -1;
    }
    fprintf(stderr, "CTRL_REG1 (standby) written successfully.\n");

    // Configure for ±2g range and 200 Hz ODR
    status = i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG2, 0x02); // Active mode, 200 Hz, ±2g
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2: %d\n", status);
        return -1;
    }
    fprintf(stderr, "CTRL_REG2 written successfully.\n");

    return 0;
}

// Read acceleration data from the sensor
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_acceleration_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 4096.0; // Convert to g units (±2g range)
    float y_g = (float)y / 4096.0;
    float z_g = (float)z / 4096.0;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log impact data to a file
int log_impact(int16_t x, int16_t y, int16_t z, float magnitude) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for writing\n");
        return -1;
    }

    fprintf(fp, "%s,%d,%d,%d,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);

    return 0;
}

int main() {
    int16_t x, y, z;
    float magnitude;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700cq() != 0) {
        fprintf(stderr, "FXOS8700CQ initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate acceleration magnitude
            magnitude = calculate_acceleration_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                // Log the impact
                if (log_impact(x, y, z, magnitude) != 0) {
                    fprintf(stderr, "Error logging impact data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, continuing...\n");
        }

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

