#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// L3G4200D I2C address
#define L3G4200D_ADDR 0x69

// L3G4200D Registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// WHO_AM_I register value
#define WHO_AM_I_VALUE 0x33

// Calibration duration (seconds)
#define CALIBRATION_DURATION 10

// Sampling rate (Hz)
#define SAMPLING_RATE 20

// Threshold for alert (dps)
#define ALERT_THRESHOLD 50.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration offsets
float x_offset = 0.0;
float y_offset = 0.0;
float z_offset = 0.0;

// Function prototypes
int initialize_i2c();
int read_register(int reg);
int write_register(int reg, int value);
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void calibrate_gyro();
void log_data(int16_t x, int16_t y, int16_t z);
void handle_alert(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(1, L3G4200D_ADDR, 0); // Bus 1, address 0x69, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor presence by reading WHO_AM_I register
    int who_am_i = read_register(0x0F); // WHO_AM_I register
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, 100 Hz ODR)
    if (write_register(CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        i2cClose(i2c_handle);
        return -1;
    }

