// Initialize I2C
int init_i2c() {
    i2c_handle_accel = i2cOpen(1, ACCEL_ADDR, 0); // Bus 1, address 0x19, no flags
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Failed to open I2C device for accelerometer: %d\n", i2c_handle_accel);
        return 1;
    }

    i2c_handle_mag = i2cOpen(1, MAG_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Failed to open I2C device for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        return 1;
    }

    return 0;
}

// Initialize accelerometer
int init_accel() {
    // Enable accelerometer, 50 Hz data rate
    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1_A\n");
        return 1;
    }

    // Set full-scale range to +/- 2g
    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4_A\n");
        return 1;
    }

    return 0;
}

// Initialize magnetometer
int init_mag() {
    // Set continuous conversion mode
    if (i2cWriteByteData(i2c_handle_mag, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to write to MR_REG_M\n");
        return 1;
    }

    return 0;
}

// Read accelerometer data
int read_accel(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_accel, OUT_X_L_A | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return 1;
    }

    // Combine high and low bytes, convert to g
    int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)x_raw / 16384.0f; // Assuming +/- 2g range
    *y = (float)y_raw / 16384.0f;
    *z = (float)z_raw / 16384.0f;

    return 0;
}

// Read magnetometer data
int read_mag(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_mag, OUT_X_H_M, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        return 1;
    }

    // Combine high and low bytes, convert to gauss
    int16_t x_raw = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t y_raw = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t z_raw = (int16_t)((buffer[4] << 8) | buffer[5]);

    *x = (float)x_raw / 1100.0f; // Assuming typical sensitivity
    *y = (float)y_raw / 1100.0f;
    *z = (float)z_raw / 1100.0f;

    return 0;
}

// Calculate tilt-compensated heading
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float mag_x_comp = mag_x * cos(pitch) + mag_z * sin(pitch);
    float mag_y_comp = mag_y * cos(roll) - mag_z * sin(roll) * cos(pitch) + mag_x * sin(roll) * sin(pitch);

    float heading = atan2(mag_y_comp, mag_x_comp);

    // Convert to degrees
    heading = heading * 180 / M_PI;

    // Normalize to 0-360 degrees
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Log data to file
int log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

