#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define the I2C bus number
#define I2C_BUS 1

// Define the sampling interval in milliseconds
#define SAMPLING_INTERVAL_MS 10

// Define the number of samples to read from each sensor
#define NUM_SAMPLES 16

// Define the CSV file name
#define CSV_FILE "audio_log.dat"

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *fp = NULL;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_sensor_data(int handle, int16_t *data);
void get_timestamp(long *seconds, long *nanoseconds);
double calculate_tdoa(int16_t *data1, int16_t *data2, int num_samples);
int write_to_csv(long seconds, long nanoseconds, int16_t *data1, int16_t *data2, double tdoa);
void signal_handler(int signal);

// Structure to hold sensor data and configuration
typedef struct {
    int handle;
    int address;
    int16_t *data;
} sensor_t;

// Function to initialize the I2C bus
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read data from the sensor
int read_sensor_data(int handle, int16_t *data) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *data = (int16_t)((buf[0] << 8) | buf[1]);

    return 0;
}

// Function to get the current timestamp
void get_timestamp(long *seconds, long *nanoseconds) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    *seconds = ts.tv_sec;
    *nanoseconds = ts.tv_nsec;
}

// Function to calculate the TDOA
double calculate_tdoa(int16_t *data1, int16_t *data2, int num_samples) {
    // Simple cross-correlation approach
    double max_correlation = 0.0;
    int delay = 0;

    for (int d = -num_samples + 1; d < num_samples; d++) {
        double correlation = 0.0;
        for (int i = 0; i < num_samples; i++) {
            int j = i + d;
            if (j >= 0 && j < num_samples) {
                correlation += (double)data1[i] * data2[j];
            }
        }

        if (correlation > max_correlation) {
            max_correlation = correlation;
            delay = d;
        }
    }

    // Calculate the TDOA in seconds
    double tdoa = (double)delay / (double)num_samples; // Assuming 1 sample per ms
    return tdoa;
}

// Function to write data to the CSV file
int write_to_csv(long seconds, long nanoseconds, int16_t *data1, int16_t *data2, double tdoa) {
    if (fp == NULL) {
        fprintf(stderr, "Error: CSV file not opened.\n");
        return -1;
    }

    fprintf(fp, "%ld,%ld,%d,%d,%.6f\n", seconds, nanoseconds, data1[0], data2[0], tdoa);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (fp != NULL) {
        fclose(fp);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open the CSV file for writing
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILE);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Allocate memory for sensor data
    int16_t *data1 = malloc(NUM_SAMPLES * sizeof(int16_t));
    int16_t *data2 = malloc(NUM_SAMPLES * sizeof(int16_t));

    if (data1 == NULL || data2 == NULL) {
        fprintf(stderr, "Error allocating memory for sensor data\n");
        fclose(fp);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from sensor 1
        for (int i = 0; i < NUM_SAMPLES; i++) {
            if (read_sensor_data(i2c_handle1, &data1[i]) != 0) {
                fprintf(stderr, "Error reading from sensor 1, retrying...\n");
                // Attempt to re-initialize I2C
                i2cClose(i2c_handle1);
                i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
                if (i2c_handle1 < 0) {
                    fprintf(stderr, "Failed to re-initialize sensor 1, skipping sample.\n");
                    data1[i] = 0; // Set to a default value
                }
            }
        }

        // Read data from sensor 2
        for (int i = 0; i < NUM_SAMPLES; i++) {
            if (read_sensor_data(i2c_handle2, &data2[i]) != 0) {
                fprintf(stderr, "Error reading from sensor 2, retrying...\n");
                // Attempt to re-initialize I2C
                i2cClose(i2c_handle2);
                i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
                if (i2c_handle2 < 0) {
                    fprintf(stderr, "Failed to re-initialize sensor 2, skipping sample.\n");
                    data2[i] = 0; // Set to a default value
                }
            }
        }

        // Get the current timestamp
        long seconds, nanoseconds;
        get_timestamp(&seconds, &nanoseconds);

        // Calculate the TDOA
        double tdoa = calculate_tdoa(data1, data2, NUM_SAMPLES);

        // Write the data to the CSV file
        if (write_to_csv(seconds, nanoseconds, data1, data2, tdoa) != 0) {
            fprintf(stderr, "Error writing to CSV file\n");
        }

        // Wait for the next sampling interval
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup (this part will not be reached in the infinite loop, but it's good practice)
    free(data1);
    free(data2);
    fclose(fp);
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

