#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16488A Register Addresses
#define ADIS16488A_GYRO_XOUT 0x04
#define ADIS16488A_GYRO_YOUT 0x06
#define ADIS16488A_GYRO_ZOUT 0x08
#define ADIS16488A_ACCEL_XOUT 0x0A
#define ADIS16488A_ACCEL_YOUT 0x0C
#define ADIS16488A_ACCEL_ZOUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3        // CPOL = 1, CPHA = 1

// Gyroscope and Accelerometer Sensitivities
#define GYRO_SENSITIVITY 0.005  // deg/sec/LSB
#define ACCEL_SENSITIVITY 0.00025 // g/LSB

// Sampling Interval
#define SAMPLE_INTERVAL_MS 100

// Global Variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t running = 1;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data);
int16_t convert_to_gyro(int16_t raw_data);
int16_t convert_to_accel(int16_t raw_data);
void log_data(FILE *fp, int timestamp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void cleanup(int signal);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    // Construct the command word (MSB = 0, 7-bit register address)
    tx_buf[0] = 0x80 | (reg_addr & 0x7F); // Read command
    tx_buf[1] = 0x00; // Dummy byte

    gpioWrite(8, 1); // Assert CS
    gpioDelay(40);   // Stall time

    result = spiXfer(handle, tx_buf, rx_buf, 2);

    gpioWrite(8, 0); // De-assert CS

    if (result != 0) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    // Combine the received bytes to form the 16-bit data
    *data = (rx_buf[0] << 8) | rx_buf[1];

    return 0;
}

// Data Conversion Functions
int16_t convert_to_gyro(int16_t raw_data) {
    return (int16_t)(raw_data * GYRO_SENSITIVITY);
}

int16_t convert_to_accel(int16_t raw_data) {
    return (int16_t)(raw_data * ACCEL_SENSITIVITY);
}

// Data Logging Function
void log_data(FILE *fp, int timestamp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z) {
    fprintf(fp, "%d,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(fp); // Ensure data is written to file immediately
}

// Cleanup Function
void cleanup(int signal) {
    printf("Cleaning up...\n");
    running = 0; // Stop the main loop

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    if (fp != NULL) {
        fclose(fp);
    }

    gpioTerminate();
    exit(0);
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Signal received (%d).  Cleaning up...\n", signal);
    cleanup(signal);
}

int main() {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    struct timespec ts;
    int timestamp_ms;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read gyroscope data
        if (spi_read_register(spi_handle, ADIS16488A_GYRO_XOUT, &raw_gyro_x) != 0) {
            fprintf(stderr, "Error reading gyro_x\n");
            continue;
        }
        if (spi_read_register(spi_handle, ADIS16488A_GYRO_YOUT, &raw_gyro_y) != 0) {
            fprintf(stderr, "Error reading gyro_y\n");
            continue;
        }
        if (spi_read_register(spi_handle, ADIS16488A_GYRO_ZOUT, &raw_gyro_z) != 0) {
            fprintf(stderr, "Error reading gyro_z\n");
            continue;
        }

        // Read accelerometer data
        if (spi_read_register(spi_handle, ADIS16488A_ACCEL_XOUT, &raw_accel_x) != 0) {
            fprintf(stderr, "Error reading accel_x\n");
            continue;
        }
        if (spi_read_register(spi_handle, ADIS16488A_ACCEL_YOUT, &raw_accel_y) != 0) {
            fprintf(stderr, "Error reading accel_y\n");
            continue;
        }
        if (spi_read_register(spi_handle, ADIS16488A_ACCEL_ZOUT, &raw_accel_z) != 0) {
            fprintf(stderr, "Error reading accel_z\n");
            continue;
        }

        // Convert raw data to physical units
        gyro_x = convert_to_gyro(raw_gyro_x);
        gyro_y = convert_to_gyro(raw_gyro_y);
        gyro_z = convert_to_gyro(raw_gyro_z);
        accel_x = convert_to_accel(raw_accel_x);
        accel_y = convert_to_accel(raw_accel_y);
        accel_z = convert_to_accel(raw_accel_z);

        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
            timestamp_ms = (int)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
        } else {
            fprintf(stderr, "Failed to get timestamp\n");
            timestamp_ms = 0; // Use a default timestamp
        }

        // Log the data
        log_data(fp, timestamp_ms, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Delay for the sampling interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    cleanup(0);

    return 0;
}

