void log_data(FILE *fp, int timestamp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z) {
    fprintf(fp, "%d,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(fp); // Ensure data is written to file immediately
}

// Cleanup Function
void cleanup(int signal) {
    printf("Cleaning up...\n");
    running = 0; // Stop the main loop

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    if (fp != NULL) {
        fclose(fp);
    }

    gpioTerminate();
    exit(0);
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Signal received (%d).  Cleaning up...\n", signal);
    cleanup(signal);
}

int main() {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    struct timespec ts;
    int timestamp_ms;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read gyroscope data
        if (spi_read_register(spi_handle, ADIS16488A_GYRO_XOUT, &raw_gyro_x) != 0) {
            fprintf(stderr, "Error reading gyro_x\n");
            continue;
        }
        if (spi_read_register(spi_handle, ADIS16488A_GYRO_YOUT, &raw_gyro_y) != 0) {
            fprintf(stderr, "Error reading gyro_y\n");
            continue;
        }
        if (spi_read_register(spi_handle, ADIS16488A_GYRO_ZOUT, &raw_gyro_z) != 0) {
            fprintf(stderr, "Error reading gyro_z\n");
            continue;
        }

        // Read accelerometer data
        if (spi_read_register(spi_handle, ADIS16488A_ACCEL_XOUT, &raw_accel_x) != 0) {
            fprintf(stderr, "Error reading accel_x\n");
            continue;
        }
        if (spi_read_register(spi_handle, ADIS16488A_ACCEL_YOUT, &raw_accel_y) != 0) {
            fprintf(stderr, "Error reading accel_y\n");
            continue;
        }
        if (spi_read_register(spi_handle, ADIS16488A_ACCEL_ZOUT, &raw_accel_z) != 0) {
            fprintf(stderr, "Error reading accel_z\n");
            continue;
        }

        // Convert raw data to physical units
        gyro_x = convert_to_gyro(raw_gyro_x);
        gyro_y = convert_to_gyro(raw_gyro_y);
        gyro_z = convert_to_gyro(raw_gyro_z);
        accel_x = convert_to_accel(raw_accel_x);
        accel_y = convert_to_accel(raw_accel_y);
        accel_z = convert_to_accel(raw_accel_z);

        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
            timestamp_ms = (int)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
        } else {
