#define ADIS16448_ACCEL_XOUT 0x0A
#define ADIS16448_ACCEL_YOUT 0x0C
#define ADIS16448_ACCEL_ZOUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.02f  // dps/LSB
#define ACCEL_SCALE 0.00025f // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
