}

// Function to read a 16-bit register from the ADIS16448
int16_t read_register(int reg_addr) {
    char tx_buf[2];
    char rx_buf[2];
    int status;

    // Set bit 7 of the register address for read operation
    tx_buf[0] = (reg_addr << 1) | 0x80; // MSB = 1 for read
    tx_buf[1] = 0x00; // Dummy byte for reading

    status = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (status != 0) {
        fprintf(stderr, "Error during SPI transfer: %d\n", status);
        return 0; // Return 0 on error
    }

    // Combine the two bytes to form the 16-bit value
    return (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
