int init_mpu6886(int i2c_fd) {
    // Wake up the MPU-6886 (clear sleep bit)
    if (i2cWriteByteData(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6886\n");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the MPU-6886
int16_t read_mpu6886_data(int i2c_fd, uint8_t reg_addr) {
    char buf[2];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_fd, reg_addr, buf, 2) == 2) {
            return (int16_t)((buf[0] << 8) | buf[1]);
        } else {
            fprintf(stderr, "Error: I2C read failed (reg 0x%02X), retrying...\n", reg_addr);
            gpioDelay(1000); // 1 ms delay
            retries--;
        }
    }

    fprintf(stderr, "Error: I2C read failed (reg 0x%02X) after multiple retries\n", reg_addr);
    return 0; // Return 0 on failure
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, MPU6886_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6886
    if (init_mpu6886(i2c_fd) < 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl-C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        int16_t accel_x = read_mpu6886_data(i2c_fd, ACCEL_XOUT_H);
        int16_t accel_y = read_mpu6886_data(i2c_fd, ACCEL_XOUT_H + 2);
        int16_t accel_z = read_mpu6886_data(i2c_fd, ACCEL_XOUT_H + 4);

        // Read gyroscope data
        int16_t gyro_x = read_mpu6886_data(i2c_fd, GYRO_XOUT_H);
        int16_t gyro_y = read_mpu6886_data(i2c_fd, GYRO_XOUT_H + 2);
        int16_t gyro_z = read_mpu6886_data(i2c_fd, GYRO_XOUT_H + 4);

        // Print the data
        printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms
    }

    // Close I2C bus
    i2cClose(i2c_fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

