#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ICM-20602 I2C address
#define ICM20602_ADDR 0x68

// ICM-20602 register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// I2C bus
#define I2C_BUS 1

// Sampling rate (10 Hz)
#define SAMPLE_RATE_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
} imu_data_t;

// Function prototypes
int init_imu();
imu_data_t read_imu_data();
void log_data(imu_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the ICM-20602 IMU
int init_imu() {
    // Wake up the sensor (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up IMU\n");
        return -1;
    }
    return 0;
}

// Read accelerometer and gyroscope data from the IMU
imu_data_t read_imu_data() {
    imu_data_t data;
    char buffer[12];

    // Read accelerometer data (6 bytes)
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 6) < 0) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        data.accel_x = 0; data.accel_y = 0; data.accel_z = 0;
    } else {
        data.accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
        data.accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
        data.accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    }

    // Read gyroscope data (6 bytes)
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        data.gyro_x = 0; data.gyro_y = 0; data.gyro_z = 0;
    } else {
        data.gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
        data.gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
        data.gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    }

    return data;
}

// Log the IMU data to a CSV file
void log_data(imu_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize IMU
    if (init_imu() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        imu_data_t data = read_imu_data();
        log_data(data);
        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

