// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

