    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return 1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        return 1;
    }

    printf("MMA8451Q sensor verified\n");
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially
    return 0;
}

// Initialize accelerometer
int init_accelerometer() {
    // Set accelerometer to active mode, 800 Hz ODR, and +/- 2g range
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return 1;
    }
    return 0;
}

// Read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return 1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2; // Combine MSB and LSB, right-shift by 2
    *y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
    *z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

    return 0;
}

// Calculate magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = x * G_PER_COUNT;
    float y_g = y * G_PER_COUNT;
    float z_g = z * G_PER_COUNT;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.3f g\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control LED based on magnitude
void control_led(float magnitude) {
    if (magnitude > G_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
        gpioDelay(500000);      // Wait for 500ms
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

