#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// Free-fall threshold and duration
#define FREEFALL_THRESHOLD 0.3 // g
#define FREEFALL_DURATION 0.1  // seconds

// GPIO pin for interrupt
#define INTERRUPT_GPIO 17

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int adxl345_init(int fd);
int adxl345_read_acceleration(int fd, float *x, float *y, float *z);
int detect_freefall(float x, float y, float z);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);
int log_data(FILE *fp, float x, float y, float z);

// I2C read function with error handling
int i2c_read_reg(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// I2C write function with error handling
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// ADXL345 initialization function
int adxl345_init(int fd) {
    // Verify device ID
    int device_id = i2c_read_reg(fd, ADXL345_REG_DEVID);
    if (device_id != 0xE5) {
        fprintf(stderr, "Error: Invalid device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Set data format: +/- 2g range, full resolution
    if (i2c_write_reg(fd, ADXL345_REG_DATA_FORMAT, 0x0B) < 0) {
        return -1;
    }

    // Put the sensor in standby mode
    if (i2c_write_reg(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        return -1;
    }

    // Enable free-fall interrupt
    if (i2c_write_reg(fd, ADXL345_REG_INT_ENABLE, 0x40) < 0) {
        return -1;
    }

    return 0;
}

// ADXL345 read acceleration function
int adxl345_read_acceleration(int fd, float *x, float *y, float *z) {
    int16_t x_raw, y_raw, z_raw;
    int x0, x1, y0, y1, z0, z1;

    x0 = i2c_read_reg(fd, ADXL345_REG_DATAX0);
    x1 = i2c_read_reg(fd, ADXL345_REG_DATAX1);
    y0 = i2c_read_reg(fd, ADXL345_REG_DATAY0);
    y1 = i2c_read_reg(fd, ADXL345_REG_DATAY1);
    z0 = i2c_read_reg(fd, ADXL345_REG_DATAZ0);
    z1 = i2c_read_reg(fd, ADXL345_REG_DATAZ1);

    if (x0 < 0 || x1 < 0 || y0 < 0 || y1 < 0 || z0 < 0 || z1 < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    x_raw = (int16_t)((x1 << 8) | x0);
    y_raw = (int16_t)((y1 << 8) | y0);
    z_raw = (int16_t)((z1 << 8) | z0);

    // Convert to g units (assuming +/- 2g range and full resolution)
    *x = (float)x_raw / 256.0;
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

// Free-fall detection function
int detect_freefall(float x, float y, float z) {
    float magnitude = sqrt(x * x + y * y + z * z);
    return (magnitude < FREEFALL_THRESHOLD);
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_interrupt_tick = 0;
    uint32_t current_tick = gpioTick();
    float x, y, z;
    struct timespec ts;
    char timestamp[30];

    // Debounce the interrupt
    if (current_tick - last_interrupt_tick < (uint32_t)(FREEFALL_DURATION * 1000000)) {
        return;
    }
    last_interrupt_tick = current_tick;

    // Read acceleration data
    if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) < 0) {
        fprintf(stderr, "Error reading acceleration data in interrupt handler\n");
        return;
    }

    // Detect free-fall
    if (detect_freefall(x, y, z)) {
        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

        // Log data
        if (log_data(log_file, x, y, z) < 0) {
            fprintf(stderr, "Error logging data in interrupt handler\n");
        }
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;

    // Disable interrupts
    i2c_write_reg(i2c_fd, ADXL345_REG_INT_ENABLE, 0x00);

    // Close I2C file descriptor
    close(i2c_fd);

    // Release GPIO line
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT); // Set back to input

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Log data function
int log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    char timestamp[30];

    // Get timestamp
    clock_gettime(CLOCK_REALTIME, &ts);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    // Write to file
    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    // Flush the buffer
    fflush(fp);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for interrupt
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler
    gpioSetAlertFuncEx(INTERRUPT_GPIO, interrupt_handler, NULL);

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sleep(1); // Keep the program running
    }

    return 0;
}

