#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define LSM6DSR_WHO_AM_I 0x0F
#define LSM6DSR_CTRL1_XL 0x10
#define LSM6DSR_CTRL2_G 0x11
#define LSM6DSR_OUTX_L_G 0x22
#define LSM6DSR_OUTX_L_XL 0x28

// Configuration values
#define ACCEL_RANGE_2G 2.0f
#define GYRO_RANGE_250DPS 250.0f
#define ODR_104HZ 104

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define IMPACT_WINDOW 1.0f

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// State machine states
typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} State;

State current_state = IDLE;
time_t freefall_start_time = 0;

// Function prototypes
int init_i2c();
int init_lsm6dsr();
int read_accel_gyro(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z);
void log_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z);
void detect_fall(float accel_x, float accel_y, float accel_z);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0); // Bus 1, address 0x6A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize LSM6DSR
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, LSM6DSR_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I returned 0x%x, expected 0x69\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: ±2g, 104 Hz
    if (i2cWriteByteData(i2c_handle, LSM6DSR_CTRL1_XL, 0x80) < 0) { // 0x80: 104 Hz, ±2g
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: ±250 dps, 104 Hz
    if (i2cWriteByteData(i2c_handle, LSM6DSR_CTRL2_G, 0x80) < 0) { // 0x80: 104 Hz, ±250 dps
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_accel_gyro(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z) {
    char buffer[12];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Read gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_G, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }
    raw_gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g and dps
    *accel_x = (float)raw_accel_x / 16384.0f * ACCEL_RANGE_2G; // 16384 counts per g
    *accel_y = (float)raw_accel_y / 16384.0f * ACCEL_RANGE_2G;
    *accel_z = (float)raw_accel_z / 16384.0f * ACCEL_RANGE_2G;
    *gyro_x = (float)raw_gyro_x / 131.0f; // 131 counts per dps
    *gyro_y = (float)raw_gyro_y / 131.0f;
    *gyro_z = (float)raw_gyro_z / 131.0f;

    return 0;
}

// Function to log data to a CSV file
void log_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", timestamp, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to detect falls
void detect_fall(float accel_x, float accel_y, float accel_z) {
    float magnitude = sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);

    switch (current_state) {
