// ADIS16266 Register Addresses
#define ADIS16266_WHO_AM_I 0x02
#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE 8 // GPIO8 (CE0)
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3 // CPOL=1, CPHA=1

// Gyroscope Scale Factor
#define GYRO_SCALE_FACTOR 0.0305 // deg/sec/LSB

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data);
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data);
int adis16266_read_gyro(int handle, int16_t *x, int16_t *y, int16_t *z);
double convert_to_degrees_per_second(int16_t raw_data);
int log_data(FILE *fp, double x, double y, double z);
void signal_handler(int signal);

// Function to read a 16-bit register from the ADIS16266
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB to 1 for read operation
    tx_buf[0] = reg_addr | 0x80;
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Function to write a 16-bit register to the ADIS16266
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[2];

    // Set MSB to 0 for write operation
    tx_buf[0] = reg_addr & 0x7F;
    tx_buf[1] = data & 0xFF; //LSB

    if (spiWrite(handle, tx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int adis16266_read_gyro(int handle, int16_t *x, int16_t *y, int16_t *z) {
    if (spi_read_register(handle, ADIS16266_XGYRO_OUT, x) != 0) return -1;
    if (spi_read_register(handle, ADIS16266_YGYRO_OUT, y) != 0) return -1;
    if (spi_read_register(handle, ADIS16266_ZGYRO_OUT, z) != 0) return -1;
    return 0;
}

// Function to convert raw data to degrees per second
double convert_to_degrees_per_second(int16_t raw_data) {
    return (double)raw_data * GYRO_SCALE_FACTOR;
}

// Function to log data to a CSV file
int log_data(FILE *fp, double x, double y, double z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int16_t x_raw, y_raw, z_raw;
    double x_deg, y_deg, z_deg;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Verify WHO_AM_I register
    int16_t who_am_i;
    if (spi_read_register(spi_handle, ADIS16266_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: WHO_AM_I read failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != 0x4162) {
        fprintf(stderr, "Error: WHO_AM_I value incorrect (0x%04X)\n", who_am_i);
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (adis16266_read_gyro(spi_handle, &x_raw, &y_raw, &z_raw) == 0) {
            x_deg = convert_to_degrees_per_second(x_raw);
            y_deg = convert_to_degrees_per_second(y_raw);
            z_deg = convert_to_degrees_per_second(z_raw);

            if (log_data(log_file, x_deg, y_deg, z_deg) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

