#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"

static volatile int running = 1;
FILE *log_file = NULL;

// Function to handle SIGINT signal (Ctrl+C)
void sigint_handler(int signal)
{
    running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor()
{
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Function to log the flame event to a file
void log_flame_event(int flame_detected)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s – Flame detected: %s\n", timestamp, flame_detected ? "YES" : "NO");
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to print the flame event to the console
void print_flame_event(int flame_detected)
{
    printf("FLAME DETECTED!\n");
}

int main()
{
    // Install signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Initialize pigpio and GPIO pin
    if (initialize_gpio() != 0)
    {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running)
    {
        int flame_detected = (read_flame_sensor() == 0); // LOW indicates flame

        if (flame_detected)
        {
            log_flame_event(1);
            print_flame_event(1);
        } else
        {
            log_flame_event(0);
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup
    if (log_file != NULL)
    {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

