#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C address of the Omron D7S-0001 sensor
#define I2C_ADDR 0x4C

// Define the I2C bus number
#define I2C_BUS 1

// Define the register address for the X, Y, and Z axis data
#define REG_X 0x02
#define REG_Y 0x04
#define REG_Z 0x06

// Define the sampling interval in milliseconds
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
char* get_iso8601_timestamp();
int write_to_log(const char *timestamp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the I2C bus
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int result;

    // Read X axis data
    result = i2cReadI2CBlockData(i2c_handle, REG_X, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Combine the bytes to form 16-bit signed integers
    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
    data->z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Write the timestamp and sensor data to the log file
int write_to_log(const char *timestamp, int16_t x, int16_t y, int16_t z) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("vibration_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header line to the log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;
    char *timestamp;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Get the current timestamp
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                // Write the data to the log file
                if (write_to_log(timestamp, sensor_data.x, sensor_data.y, sensor_data.z) != 0) {
                    fprintf(stderr, "Error writing to log file.\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Error getting timestamp.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping sample.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Close the I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
