// Define GPIO pins for the Hall-effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Define the log file name
#define LOG_FILE "conveyor_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int log_data(int sensor1_state, int sensor2_state);
void halt_conveyor();
void signal_handler(int signal);

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int sensor_value = gpioRead(gpio_pin);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return sensor_value;
}

// Function to log sensor data to a file
int log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fclose(fp);
    return 0; // Indicate success
}

// Function to simulate halting the conveyor
void halt_conveyor() {
    printf("Conveyor Halted!\n");
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Conveyor control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor states
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        if (sensor1_state == -1 || sensor2_state == -1) {
            fprintf(stderr, "Error reading sensor data, exiting...\n");
            break; // Exit loop if sensor read fails
        }

        // Log the sensor data
        if (log_data(sensor1_state, sensor2_state) != 0) {
            fprintf(stderr, "Error logging data, exiting...\n");
            break; // Exit loop if logging fails
        }

        // Check if both sensors are HIGH
        if (sensor1_state == 1 && sensor2_state == 1) {
            halt_conveyor();
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // pigpio uses microseconds
    }

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

