#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MMA8452Q_ADDR 0x1D
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define WHO_AM_I 0x0D
#define WHO_AM_I_VALUE 0x2A
#define DATA_RATE 0x0B // 100 Hz
#define ACTIVE_MODE 0x01
#define STANDBY_MODE 0x00
#define TILT_THRESHOLD 45.0
#define LOG_FILE "fall_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt(int16_t x, int16_t y, int16_t z);
int log_fall(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Structure for sensor configuration
typedef struct {
    int data_rate;
    int active_mode;
} sensor_config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MMA8452Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the MMA8452Q sensor
int init_sensor() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }

    // Place in standby mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, STANDBY_MODE) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby): %s\n", strerror(errno));
        return -1;
    }

    // Configure data rate
    if (i2cWriteByteData(i2c_handle, DATA_RATE, 0x0A) < 0) { // 0x0A for 100Hz
        fprintf(stderr, "Error writing to DATA_RATE: %s\n", strerror(errno));
        return -1;
    }

    // Re-enable active mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, ACTIVE_MODE) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active): %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = ((int16_t)buffer[0] << 8) | buffer[1];
    *x = *x >> 4;

    *y = ((int16_t)buffer[2] << 8) | buffer[3];
    *y = *y >> 4;

    *z = ((int16_t)buffer[4] << 8) | buffer[5];
    *z = *z >> 4;

    return 0;
}

// Function to calculate tilt angle
double calculate_tilt(int16_t x, int16_t y, int16_t z) {
    double tilt = atan2(sqrt(x * x + y * y), z) * 180 / M_PI;
    if (tilt < 0) {
        tilt += 360;
    }
    return tilt;
}

// Function to log a fall event
int log_fall(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(log_file);

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    double tilt;

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer(&x, &y, &z) == 0) {
            // Calculate tilt
            tilt = calculate_tilt(x, y, z);

            // Check for tilt threshold
            if (tilt > TILT_THRESHOLD) {
                // Log fall event
                if (log_fall(x, y, z) != 0) {
                    fprintf(stderr, "Error logging fall event.\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }

        // Delay for 10 ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

