// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration constants
#define OFFSET_X 0.0
#define OFFSET_Y 0.0
#define OFFSET_Z 0.0
#define SCALE_X 1.0
#define SCALE_Y 1.0
#define SCALE_Z 1.0

// Metal detector threshold (mG)
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Function prototypes
int init_lis3mdl();
magnetometer_data_t read_magnetometer_data();
magnetometer_data_t calibrate_data(magnetometer_data_t raw_data);
void log_data(magnetometer_data_t calibrated_data);
void metal_detector_alert(magnetometer_data_t calibrated_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize LIS3MDL magnetometer
int init_lis3mdl() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Set continuous mode and 10 Hz data rate
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70); // 0x70 = 0b01110000
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG1: %d, retries remaining: %d\n", status, retries);
            gpioDelay(100); // Wait before retrying
            retries--;
            continue;
        }

        // Enable continuous conversion
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00);
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG3: %d, retries remaining: %d\n", status, retries);
            gpioDelay(100); // Wait before retrying
            retries--;
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize LIS3MDL after multiple retries.\n");
    return -1; // Failure
}

