magnetometer_data_t read_magnetometer_data() {
    char buffer[6];
    magnetometer_data_t raw_data;
    int status;

    status = i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L | 0x80, buffer, 6); // Enable auto-increment
    if (status < 0) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", status);
        raw_data.x = 0.0;
        raw_data.y = 0.0;
        raw_data.z = 0.0;
        return raw_data;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    raw_data.x = (float)x;
    raw_data.y = (float)y;
    raw_data.z = (float)z;

    return raw_data;
}

// Calibrate magnetometer data
magnetometer_data_t calibrate_data(magnetometer_data_t raw_data) {
    magnetometer_data_t calibrated_data;

    calibrated_data.x = (raw_data.x - OFFSET_X) * SCALE_X;
    calibrated_data.y = (raw_data.y - OFFSET_Y) * SCALE_Y;
    calibrated_data.z = (raw_data.z - OFFSET_Z) * SCALE_Z;

    return calibrated_data;
}

