    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        magnetometer_data_t raw_data = read_magnetometer_data();
        magnetometer_data_t calibrated_data = calibrate_data(raw_data);
        log_data(calibrated_data);
        metal_detector_alert(calibrated_data);
        gpioDelay(100); // 10 Hz sampling rate
    }

