    tx_buf[0] = ADXL354B_WRITE_REG | ADXL354B_POWER_CTL;
    tx_buf[1] = 0x00; // Clear RUN bit

    if (spi_transfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error powering down ADXL354B\n");
        return -1;
    }

    gpioDelay(10); // Wait 10 ms
    return 0;
}

// ADXL354B Power Up Function
int adxl354b_power_up(int handle) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = ADXL354B_WRITE_REG | ADXL354B_POWER_CTL;
    tx_buf[1] = 0x01; // Set RUN bit

    if (spi_transfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error powering up ADXL354B\n");
        return -1;
    }

    gpioDelay(10); // Wait 10 ms
    return 0;
}

// ADXL354B Read Register Function
int adxl354b_read_register(int handle, uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = ADXL354B_READ_REG | reg;
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spi_transfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }

    *value = rx_buf[1];
    return 0;
}

// ADXL354B Write Register Function
int adxl354b_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = ADXL354B_WRITE_REG | reg;
    tx_buf[1] = value;

    if (spi_transfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error writing register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// ADXL354B Read Acceleration Function
int adxl354b_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char tx_buf[7];
    char rx_buf[7];

    // Read X, Y, and Z acceleration data (3 bytes per axis)
    tx_buf[0] = ADXL354B_READ_REG | 0x0E; // XDATA register
    memset(tx_buf + 1, 0x00, 6); // Dummy bytes for reading

    if (spi_transfer(handle, tx_buf, rx_buf, 7) != 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine the bytes to form 20-bit signed integers
    *x = ((int32_t)rx_buf[2] << 12) | ((int32_t)rx_buf[3] << 4) | ((int32_t)rx_buf[4] >> 4);
    *y = ((int32_t)rx_buf[5] << 12) | ((int32_t)rx_buf[6] << 4) | ((int32_t)rx_buf[7] >> 4);
    *z = ((int32_t)rx_buf[8] << 12) | ((int32_t)rx_buf[9] << 4) | ((int32_t)rx_buf[10] >> 4);

    // Sign extend to 20 bits
    if (*x & 0x80000) *x |= 0xFFF00000;
    if (*y & 0x80000) *y |= 0xFFF00000;
    if (*z & 0x80000) *z |= 0xFFF00000;

    return 0;
}

// Log Data Function
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %d, Y: %d, Z: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);
    fflush(fp);
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Reset ADXL354B
    if (adxl354b_reset(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B reset failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Power down ADXL354B
    if (adxl354b_power_down(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B power down failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    uint8_t partid;
    if (adxl354b_read_register(spi_handle, ADXL354B_PARTID_REG, &partid) != 0) {
        fprintf(stderr, "Error reading PARTID register\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (partid != 0x35) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X\n", partid);
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Power up ADXL354B
    if (adxl354b_power_up(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B power up failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    while (!terminate) {
        if (adxl354b_read_acceleration(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

