#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADIS16362 Register Addresses
#define ADIS16362_XGYRO_OUT 0x04
#define ADIS16362_YGYRO_OUT 0x06
#define ADIS16362_ZGYRO_OUT 0x08
#define ADIS16362_XACCEL_OUT 0x0A
#define ADIS16362_YACCEL_OUT 0x0C
#define ADIS16362_ZACCEL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec per LSB
#define ACCEL_SCALE 0.0025 // g per LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE 8 // GPIO 8 (CE0)
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3 // Mode 3: CPOL=1, CPHA=1

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double x_gyro;
    double y_gyro;
    double z_gyro;
    double x_accel;
    double y_accel;
    double z_accel;
} imu_data_t;

// Function prototypes
int initialize_spi();
int read_register(uint8_t address, uint16_t *data);
imu_data_t process_data(uint16_t raw_data);
int log_data(imu_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit register from the ADIS16362
int read_register(uint8_t address, uint16_t *data) {
    char tx_buffer[2];
    char rx_buffer[2];

    // Set MSB to 1 for read operation
    tx_buffer[0] = address | 0x80;
    tx_buffer[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    *data = (rx_buffer[0] << 8) | rx_buffer[1];
    return 0;
}

// Function to process raw data and convert to meaningful units
imu_data_t process_data(uint16_t raw_data) {
    imu_data_t data;
    data.x_gyro = (double)((int16_t)(raw_data & 0xFFFF)) * GYRO_SCALE;
    data.y_gyro = (double)((int16_t)(raw_data & 0xFFFF)) * GYRO_SCALE;
    data.z_gyro = (double)((int16_t)(raw_data & 0xFFFF)) * GYRO_SCALE;
    data.x_accel = (double)((int16_t)(raw_data & 0xFFFF)) * ACCEL_SCALE;
    data.y_accel = (double)((int16_t)(raw_data & 0xFFFF)) * ACCEL_SCALE;
    data.z_accel = (double)((int16_t)(raw_data & 0xFFFF)) * ACCEL_SCALE;
    return data;
}

// Function to log data to a CSV file
int log_data(imu_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;

    fprintf(log_file, "%ld.%09ld,%lf,%lf,%lf,%lf,%lf,%lf\n",
            ts.tv_sec, ts.tv_nsec,
            data.x_gyro, data.y_gyro, data.z_gyro,
            data.x_accel, data.y_accel, data.z_accel);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        uint16_t raw_x_gyro, raw_y_gyro, raw_z_gyro, raw_x_accel, raw_y_accel, raw_z_accel;
        imu_data_t processed_data;

        // Read gyroscope data
        if (read_register(ADIS16362_XGYRO_OUT, &raw_x_gyro) != 0) continue;
        if (read_register(ADIS16362_YGYRO_OUT, &raw_y_gyro) != 0) continue;
        if (read_register(ADIS16362_ZGYRO_OUT, &raw_z_gyro) != 0) continue;

        // Read accelerometer data
        if (read_register(ADIS16362_XACCEL_OUT, &raw_x_accel) != 0) continue;
        if (read_register(ADIS16362_YACCEL_OUT, &raw_y_accel) != 0) continue;
        if (read_register(ADIS16362_ZACCEL_OUT, &raw_z_accel) != 0) continue;

        // Process data
        processed_data = process_data(raw_x_gyro);
        processed_data = process_data(raw_y_gyro);
        processed_data = process_data(raw_z_gyro);
        processed_data = process_data(raw_x_accel);
        processed_data = process_data(raw_y_accel);
        processed_data = process_data(raw_z_accel);

        // Log data
        if (log_data(processed_data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Delay for 10 ms (100 Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

