#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 17
#define POLLING_INTERVAL_MS 1000

static volatile int running = 1;

// Function to handle SIGINT signal (Ctrl+C)
void signal_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to read the sensor value
int read_sensor()
{
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to log a message with a timestamp
void log_message(const char *message)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main()
{
    // Register the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring obstacle sensor on GPIO %d...\n", GPIO_PIN);

    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value == 0) {
            log_message("Self-parking sequence started");
            // Simulate a self-parking routine (e.g., move forward, turn, stop)
            gpioDelay(5000); // Simulate routine duration (5 seconds)
            log_message("Self-parking sequence completed");
        } else if (sensor_value < 0) {
            // Handle error from read_sensor
            break;
        }
        gpioDelay(POLLING_INTERVAL_MS); // Poll every second
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    return 0;
}

