#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// ADIS16266 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define CS_PIN 8 // GPIO8 (CE0)

// Scale Factor
#define SCALE_FACTOR 0.02 // deg/sec per LSB

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init();
int spi_read_register(uint8_t address, int16_t *data);
void read_gyro_data(float *x_rate, float *y_rate, float *z_rate);
void log_data(float x_rate, float y_rate, float z_rate);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// SPI Initialization
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// SPI Read Register
int spi_read_register(uint8_t address, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB to 1 for read operation
    tx_buf[0] = address | 0x80;
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Read Gyro Data
void read_gyro_data(float *x_rate, float *y_rate, float *z_rate) {
    int16_t x_raw, y_raw, z_raw;

    if (spi_read_register(XGYRO_OUT, &x_raw) != 0) {
        fprintf(stderr, "Error reading X gyro data\n");
        *x_rate = 0.0;
    } else {
        *x_rate = (float)x_raw * SCALE_FACTOR;
    }

    if (spi_read_register(YGYRO_OUT, &y_raw) != 0) {
        fprintf(stderr, "Error reading Y gyro data\n");
        *y_rate = 0.0;
    } else {
        *y_rate = (float)y_raw * SCALE_FACTOR;
    }

    if (spi_read_register(ZGYRO_OUT, &z_raw) != 0) {
        fprintf(stderr, "Error reading Z gyro data\n");
        *z_rate = 0.0;
    } else {
        *z_rate = (float)z_raw * SCALE_FACTOR;
    }
}

// Log Data
void log_data(float x_rate, float y_rate, float z_rate) {
    printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_rate, y_rate, z_rate);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x_rate, y_rate, z_rate;

    // Main loop
    while (!terminate) {
        read_gyro_data(&x_rate, &y_rate, &z_rate);
        log_data(x_rate, y_rate, z_rate);
        gpioDelay(100); // 100 ms delay
    }

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

