#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6B

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the LSM6DSR
int init_lsm6dsr()
{
    // Enable accelerometer and gyroscope
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) // 104 Hz, +/- 2g
    {
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) // 104 Hz, 250 dps
    {
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Function to read IMU data
int read_imu_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z)
{
    char buffer[12];
    int result = i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12);

    if (result < 0)
    {
        fprintf(stderr, "Error reading IMU data\n");
        return -1;
    }

    *gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *accel_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    *accel_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    *accel_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0)
    {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    while (!terminate)
    {
        if (read_imu_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0)
        {
            printf("%d,%d,%d,%d,%d,%d\n", accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        }
        else
        {
            fprintf(stderr, "Failed to read IMU data. Exiting.\n");
            break;
        }
        gpioDelay(100000); // 100 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

