#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1F

// FXOS8700 registers
#define FXOS8700_WHOAMI 0x0D
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_STATUS 0x00
#define FXOS8700_OUT_X_MSB 0x01
#define FXOS8700_OUT_X_LSB 0x02
#define FXOS8700_OUT_Y_MSB 0x03
#define FXOS8700_OUT_Y_LSB 0x04
#define FXOS8700_OUT_Z_MSB 0x05
#define FXOS8700_OUT_Z_LSB 0x06
#define FXOS8700_M_OUT_X_MSB 0x33
#define FXOS8700_M_OUT_X_LSB 0x34
#define FXOS8700_M_OUT_Y_MSB 0x35
#define FXOS8700_M_OUT_Y_LSB 0x36
#define FXOS8700_M_OUT_Z_MSB 0x37
#define FXOS8700_M_OUT_Z_LSB 0x38

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read a register with retry
int read_register(int handle, uint8_t reg, uint8_t *data, int count) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, reg, (char *)data, count);
        if (result == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X, count %d): %d, retries left: %d\n", reg, count, result, retries);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X, count %d)\n", reg, count);
    return -1; // Failure
}

// Function to write a register with retry
int write_register(int handle, uint8_t reg, uint8_t data) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, data);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, data 0x%02X): %d, retries left: %d\n", reg, data, result, retries);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, data 0x%02X)\n", reg, data);
    return -1; // Failure
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Verify device ID
    uint8_t whoami;
    if (read_register(i2c_handle, FXOS8700_WHOAMI, &whoami, 1) != 0) {
        fprintf(stderr, "Failed to read WHOAMI register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (whoami != 0xC7) {
        fprintf(stderr, "Incorrect WHOAMI value: 0x%02X (expected 0xC7)\n", whoami);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("FXOS8700 WHOAMI: 0x%02X\n", whoami);

