#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5 // seconds
#define SAMPLE_INTERVAL 1 // milliseconds

static volatile int running = 1;
static int threshold = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioTerminate();
    exit(0);
}

// Function to read the GPIO pin and count high readings
int read_sensor(int gpio_pin, int threshold, int window_size) {
    int high_count = 0;
    int i;

    for (i = 0; i < window_size * 1000 / SAMPLE_INTERVAL; i++) {
        int value = gpioRead(gpio_pin);
        if (value == PI_HIGH) {
            high_count++;
        }
        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in microseconds
    }

    return high_count;
}

// Function to print the timestamped status line
void print_status(int high_count, int threshold) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (high_count > threshold) {
        printf("%s ALERT\n", timestamp);
    } else {
        printf("%s Status: %d/%d\n", timestamp, high_count, threshold);
    }
}

int main(int argc, char *argv[]) {
    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    // Parse the threshold
    char *endptr;
    threshold = strtol(argv[1], &endptr, 10);

    // Check for errors in parsing
    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int high_count = read_sensor(GPIO_PIN, threshold, WINDOW_SIZE);
        print_status(high_count, threshold);
        gpioDelay(1000 * 1000); // Pause for 1 second (1000 milliseconds)
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

