#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the door locks
#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27

// Define the duration to unlock the door (in seconds)
#define UNLOCK_DURATION 5

// Define the log file name
#define LOG_FILE "access_log.txt"

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int unlock_door(int gpio_pin);
int generate_security_code(int *code);
int read_user_input(int *entered_code);
int compare_codes(int generated_code, int entered_code);
int log_access(int generated_code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(DOOR_A_GPIO, PI_OUTPUT);
    gpioSetMode(DOOR_B_GPIO, PI_OUTPUT);

    // Ensure doors are initially locked (LOW)
    gpioWrite(DOOR_A_GPIO, 0);
    gpioWrite(DOOR_B_GPIO, 0);

    return 0;
}

// Function to unlock a door for a specified duration
int unlock_door(int gpio_pin) {
