#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define MPR121_ADDR 0x5A
#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQUENCY 440
#define TCP_PORT 12345
#define AUTH_STRING "MOTION_DETECTED:MySecretKey"
#define AUTH_STRING_LENGTH (sizeof(AUTH_STRING) - 1) // Exclude null terminator
#define LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int socket_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_data(unsigned short *touch_data);
int authenticate_command(const char *command);
void play_tone(int frequency);
void log_frequency(int frequency);
void signal_handler(int signal);

// MPR121 Initialization
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Configure electrode sensitivity (example values)
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Electrode 0 touch threshold
        fprintf(stderr, "Error: MPR121 touch threshold config failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x0C) < 0) { // Electrode 0 release threshold
        fprintf(stderr, "Error: MPR121 release threshold config failed\n");
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x0F) < 0) { // Enable electrode 0
        fprintf(stderr, "Error: MPR121 electrode enable failed\n");
        return -1;
    }

    return 0;
}

// MPR121 Data Reading
int mpr121_read_touch_data(unsigned short *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: MPR121 data read failed\n");
        return -1;
    }
    *touch_data = (buf[1] << 8) | buf[0];
    return 0;
}

// TCP Command Authentication
int authenticate_command(const char *command) {
    if (strncmp(command, AUTH_STRING, AUTH_STRING_LENGTH) == 0) {
        return 1; // Authentication successful
    } else {
        return 0; // Authentication failed
    }
}

// PWM Tone Generation
void play_tone(int frequency) {
    gpioPWM(PWM_PIN, 128); // 50% duty cycle
    gpioSetPWMfrequency(PWM_PIN, frequency);
    gpioDelay(5000000); // 5 seconds
    gpioPWM(PWM_PIN, 0); // Stop PWM
}

// Frequency Logging
void log_frequency(int frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C interface
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM pin as output
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        fprintf(stderr, "Error: Socket creation failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(TCP_PORT);

    if (bind(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error: Socket bind failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        close(socket_fd);
        return 1;
    }

    // Listen for connections
    if (listen(socket_fd, 5) < 0) {
        fprintf(stderr, "Error: Socket listen failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        close(socket_fd);
        return 1;
    }

    printf("Listening for connections on port %d...\n", TCP_PORT);

    // Accept connections and process commands
    while (!terminate) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(socket_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            fprintf(stderr, "Error: Socket accept failed\n");
            continue; // Continue listening for other connections
        }

        char buffer[256];
        ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            fprintf(stderr, "Error: Socket receive failed\n");
            close(client_fd);
            continue;
        }
        buffer[bytes_received] = '\0';

        if (authenticate_command(buffer)) {
            printf("Authentication successful, playing tone\n");
            unsigned short touch_data;
            if (mpr121_read_touch_data(&touch_data) == 0) {
                int frequency = touch_data % 1000 + 200; // Example frequency mapping
                play_tone(frequency);
                log_frequency(frequency);
            } else {
                fprintf(stderr, "Error: Failed to read touch data\n");
            }
        } else {
            printf("Authentication failed\n");
        }

        close(client_fd);
    }

    // Clean up
    printf("Cleaning up...\n");
    gpioPWM(PWM_PIN, 0); // Stop PWM
    i2cClose(i2c_handle);
    fclose(log_file);
    close(socket_fd);
    gpioTerminate();

    return 0;
}

