#include <unistd.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define LSM303_ADDR 0x1E
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_M 0x08
#define OUT_X_H_M 0x09
#define OUT_Z_L_M 0x0A
#define OUT_Z_H_M 0x0B
#define LED_GPIO 17
#define PWM_FREQUENCY 1000
#define SAMPLE_INTERVAL_MS 100
#define MAGNITUDE_SCALE_FACTOR 0.9 // Adjust as needed

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_magnetometer();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_z_magnitude(int16_t z);
void set_led_brightness(float magnitude);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize magnetometer
int init_magnetometer() {
    // Enable magnetometer and set data rate (100 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    // Set full-scale selection (+/- 1.3 Gauss)
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate Z-axis magnitude
float calculate_z_magnitude(int16_t z) {
    return fabs(z) * MAGNITUDE_SCALE_FACTOR;
}

// Set LED brightness using PWM
void set_led_brightness(float magnitude) {
    // Map magnitude to PWM duty cycle (0-255)
    int duty_cycle = (int)(magnitude * 255.0); // Assuming magnitude is a normalized value
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    gpioPWM(LED_GPIO, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (init_magnetometer() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);

    int16_t x, y, z;
    float z_magnitude;

    // Main loop
    while (!terminate) {
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            z_magnitude = calculate_z_magnitude(z);
            set_led_brightness(z_magnitude);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping sample\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    gpioPWM(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

