#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// I2C bus number
#define I2C_BUS 1

// Number of samples for running average
#define NUM_SAMPLES 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold running averages
typedef struct {
    double x;
    double y;
    double z;
} running_average_t;

// Structure to hold hard-iron offsets
typedef struct {
    double x;
    double y;
    double z;
} hard_iron_offset_t;

// Function prototypes
int initialize_magnetometer();
magnetometer_data_t read_magnetometer_data();
running_average_t calculate_running_average(running_average_t current_average, magnetometer_data_t new_data, int num_samples);
hard_iron_offset_t calculate_hard_iron_offset(running_average_t running_average);
magnetometer_data_t apply_hard_iron_offset(magnetometer_data_t raw_data, hard_iron_offset_t hard_iron_offset);
void print_magnetometer_data(magnetometer_data_t data);
void signal_handler(int signal);

// Global running averages and hard iron offsets
running_average_t running_averages = {0.0, 0.0, 0.0};
hard_iron_offset_t hard_iron_offsets = {0.0, 0.0, 0.0};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the magnetometer
    if (initialize_magnetometer() != 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t raw_data = read_magnetometer_data();

        // Calculate running average
        running_averages = calculate_running_average(running_averages, raw_data, NUM_SAMPLES);

        // Calculate hard-iron offset
        hard_iron_offsets = calculate_hard_iron_offset(running_averages);

        // Apply hard-iron offset
        magnetometer_data_t offset_data = apply_hard_iron_offset(raw_data, hard_iron_offsets);

        // Print the offset-corrected data
        print_magnetometer_data(offset_data);

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Function to initialize the magnetometer
int initialize_magnetometer() {
    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure the magnetometer
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) { // 8-average, 15 Hz, normal measurement
        fprintf(stderr, "Failed to write to config register A\n");
        i2cClose(i2c_handle);
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) { // Gain = 5
        fprintf(stderr, "Failed to write to config register B\n");
        i2cClose(i2c_handle);
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) { // Continuous measurement mode
        fprintf(stderr, "Failed to write to mode register\n");
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    // Read 6 bytes of data (X, Z, Y)
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    // Combine MSB and LSB for each axis
    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Function to calculate the running average
running_average_t calculate_running_average(running_average_t current_average, magnetometer_data_t new_data, int num_samples) {
    running_average_t new_average;

    // Update the running average
    new_average.x = current_average.x - (current_average.x / num_samples) + (new_data.x / num_samples);
    new_average.y = current_average.y - (current_average.y / num_samples) + (new_data.y / num_samples);
    new_average.z = current_average.z - (current_average.z / num_samples) + (new_data.z / num_samples);

    return new_average;
}

// Function to calculate the hard-iron offset
hard_iron_offset_t calculate_hard_iron_offset(running_average_t running_average) {
    hard_iron_offset_t offset;
    offset.x = running_average.x;
    offset.y = running_average.y;
    offset.z = running_average.z;
    return offset;
}

// Function to apply the hard-iron offset
magnetometer_data_t apply_hard_iron_offset(magnetometer_data_t raw_data, hard_iron_offset_t hard_iron_offset) {
    magnetometer_data_t offset_data;
    offset_data.x = raw_data.x - hard_iron_offset.x;
    offset_data.y = raw_data.y - hard_iron_offset.y;
    offset_data.z = raw_data.z - hard_iron_offset.z;
    return offset_data;
}

// Function to print the magnetometer data
void print_magnetometer_data(magnetometer_data_t data) {
    printf("X: %d, Y: %d, Z: %d\n", data.x, data.y, data.z);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

