// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define LSM303D_WHO_AM_I 0x0F
#define LSM303D_CTRL_REG1_A 0x20
#define LSM303D_OUT_X_L_A 0x28
#define LSM303D_INT1_CFG 0x30
#define LSM303D_INT1_SRC 0x31

// Configuration values
#define LSM303D_WHO_AM_I_VALUE 0x44
#define LSM303D_CTRL_REG1_A_VALUE 0x57 // 10 Hz, normal mode
#define LSM303D_INT1_CFG_VALUE 0x00 // No interrupt configuration
#define LSM303D_INT1_SRC_VALUE 0x00 // No interrupt source

// Sensitivity
#define SENSITIVITY 0.061 // mg/LSB

// GPIO pin for INT1
#define INT1_GPIO 23

// Circular buffer size
#define BUFFER_SIZE 64

// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} acceleration_data_t;

// Circular buffer
acceleration_data_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C file descriptor
int i2c_fd;

// Function prototypes
int init_lsm303d();
int read_acceleration(acceleration_data_t *data);
void dump_buffer();
void signal_handler(int signal);

// Function to initialize the LSM303D
int init_lsm303d() {
    // Verify device identity
    int who_am_i = i2cReadByteData(i2c_fd, LSM303D_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != LSM303D_WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0x%02X\n", who_am_i, LSM303D_WHO_AM_I_VALUE);
        return -1;
    }

    // Configure CTRL_REG1_A
    int status = i2cWriteByteData(i2c_fd, LSM303D_CTRL_REG1_A, LSM303D_CTRL_REG1_A_VALUE);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A: %d\n", status);
        return -1;
    }

    // Configure INT1_CFG
    status = i2cWriteByteData(i2c_fd, LSM303D_INT1_CFG, LSM303D_INT1_CFG_VALUE);
    if (status < 0) {
        fprintf(stderr, "Error writing to INT1_CFG: %d\n", status);
        return -1;
    }

    // Configure INT1_SRC
    status = i2cWriteByteData(i2c_fd, LSM303D_INT1_SRC, LSM303D_INT1_SRC_VALUE);
    if (status < 0) {
        fprintf(stderr, "Error writing to INT1_SRC: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int read_acceleration(acceleration_data_t *data) {
    char raw_data[6];
    int status = i2cReadI2CBlockData(i2c_fd, LSM303D_OUT_X_L_A | 0x80, raw_data, 6); // Enable auto-increment
    if (status < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", status);
        return -1;
    }

    data->x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    data->y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    data->z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    return 0;
}

// Function to dump the buffer
void dump_buffer() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s: ", timestamp);

    for (int i = 0; i < 10; i++) {
        int index = (buffer_index - 10 + BUFFER_SIZE) % BUFFER_SIZE;
        acceleration_data_t data = buffer[index];
        float x = (float)data.x * SENSITIVITY;
        float y = (float)data.y * SENSITIVITY;
        float z = (float)data.z * SENSITIVITY;
        printf("X:%.2f, Y:%.2f, Z:%.2f ", x, y, z);
    }
    printf("\n");
}

// Signal handler for Ctrl-C
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Disable accelerometer
    i2cWriteByteData(i2c_fd, LSM303D_CTRL_REG1_A, 0x00);

    // Close I2C file descriptor
    i2cClose(i2c_fd);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(1, LSM303D_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303D
    if (init_lsm303d() != 0) {
        fprintf(stderr, "LSM303D initialisation failed\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set INT1_GPIO as input
    gpioSetMode(INT1_GPIO, PI_INPUT);

    // Set up signal handler for Ctrl-C
    signal(SIGINT, signal_handler);

    acceleration_data_t data;

    // Main loop
    while (1) {
        // Read acceleration data
        if (read_acceleration(&data) == 0) {
            // Store data in circular buffer
            buffer[buffer_index] = data;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        // Check for interrupt
        if (gpioRead(INT1_GPIO) == 1) {
            dump_buffer();
            // Wait for interrupt to clear (optional)
            gpioDelay(10000); // 10ms
        }

        // Delay for 10ms
        gpioDelay(10000);
    }

    return 0;
}

