#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_GPIO 17
#define SOLENOID_2_GPIO 27

// Function prototypes
int initialize_gpio();
void activate_solenoid(int gpio);
void deactivate_solenoid(int gpio);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Activate solenoid 1
        activate_solenoid(SOLENOID_1_GPIO);
        nanosleep((const struct timespec[]){{0, 500000000L}}, NULL); // 500ms

        // Deactivate solenoid 1
        deactivate_solenoid(SOLENOID_1_GPIO);

        // Activate solenoid 2
        activate_solenoid(SOLENOID_2_GPIO);
        nanosleep((const struct timespec[]){{0, 500000000L}}, NULL); // 500ms

        // Deactivate solenoid 2
        deactivate_solenoid(SOLENOID_2_GPIO);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes to output
    if (gpioSetMode(SOLENOID_1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output\n", SOLENOID_1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output\n", SOLENOID_2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Ensure both solenoids are initially off
    deactivate_solenoid(SOLENOID_1_GPIO);
    deactivate_solenoid(SOLENOID_2_GPIO);

    return 0;
}

// Function to activate a solenoid
void activate_solenoid(int gpio) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Error writing HIGH to GPIO %d\n", gpio);
    }
}

// Function to deactivate a solenoid
void deactivate_solenoid(int gpio) {
    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Error writing LOW to GPIO %d\n", gpio);
    }
}

// Function to cleanup GPIO
void cleanup_gpio() {
    // Ensure both solenoids are off
    deactivate_solenoid(SOLENOID_1_GPIO);
    deactivate_solenoid(SOLENOID_2_GPIO);

    // Terminate pigpio
    gpioTerminate();
    printf("GPIO cleanup complete. Exiting.\n");
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d. Cleaning up...\n", signal);
    program_running = 0; // Set the flag to exit the main loop
}

