#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 27

// Define UART ports
#define UART1_DEVICE "/dev/serial0"
#define UART2_DEVICE "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define timeout in seconds
#define TIMEOUT 5

// Define expected code
#define EXPECTED_CODE "123456"

// Global variables for UART handles
int uart1_handle = -1;
int uart2_handle = -1;

// Function prototypes
int initialize_gpio();
int initialize_uart(const char *device, int baud_rate, int *handle);
int read_code(int handle, char *code, int max_length);
int compare_codes(const char *code1, const char *code2, const char *expected_code);
void activate_relay(int gpio);
void deactivate_relay(int gpio);
void cleanup();
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int running;
} ProgramState;

ProgramState state = {1}; // Initialize running to 1

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    // Initialize UART ports
    if (initialize_uart(UART1_DEVICE, BAUD_RATE, &uart1_handle) != 0) {
        fprintf(stderr, "Error initializing UART1. Exiting.\n");
        cleanup();
        return 1;
    }

    if (initialize_uart(UART2_DEVICE, BAUD_RATE, &uart2_handle) != 0) {
        fprintf(stderr, "Error initializing UART2. Exiting.\n");
        cleanup();
        return 1;
    }

    char code1[7]; // Buffer for code from UART1 (6 digits + null terminator)
    char code2[7]; // Buffer for code from UART2 (6 digits + null terminator)

    // Main loop
    while (state.running) {
        // Read code from UART1
        if (read_code(uart1_handle, code1, sizeof(code1) - 1) == 0) {
            // Code read successfully from UART1
            printf("Code from UART1: %s\n", code1);
        } else {
            // Error reading from UART1 or timeout
