#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_TIME 1 // seconds
#define PIR_TIMEOUT 10  // seconds

// Global variables
static volatile int running = 1;
static int pigpio_handle;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_relay(int state);
int log_event(const char *message);
void failsafe_handler();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set PIR pin as input");
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay pin as output");
        return -1;
    }

    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off
    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        syslog(LOG_ERR, "Failed to write to relay pin");
        return -1;
    }
    return 0;
}

// Function to log events to syslog
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);
    syslog(LOG_INFO, "%s", log_message);
    return 0;
}

// Failsafe handler function
void failsafe_handler() {
    log_event("PIR sensor HIGH for more than 10 seconds. Failsafe triggered!");
    control_relay(0); // De-energize relay
    log_event("Relay de-energized due to failsafe.");
    log_event("System shutting down.");
    running = 0; // Stop the main loop
}

// Signal handler function
void signal_handler(int signal) {
    char message[50];
    snprintf(message, sizeof(message), "Received signal %d. Shutting down...", signal);
    log_event(message);

    control_relay(0); // Ensure relay is off
    gpioTerminate();   // Terminate pigpio
    closelog();        // Close syslog
    exit(0);
}

int main() {
    // Open syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t pir_start_time = 0;
    int pir_active = 0;

    // Main loop
    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            if (!pir_active) {
                pir_active = 1;
                pir_start_time = time(NULL);
                log_event("Motion detected!");
            }

            if (time(NULL) - pir_start_time >= PIR_TIMEOUT) {
                failsafe_handler();
            }

            if (control_relay(1) == 0) {
                log_event("Relay activated.");
            }
            gpioDelay(RELAY_ON_TIME * 1000); // Delay for 1 second
            if (control_relay(0) == 0) {
                log_event("Relay deactivated.");
            }
            pir_active = 0; // Reset pir_active after relay activation
        } else {
            pir_active = 0; // Reset pir_active if no motion
        }

        gpioDelay(50); // Poll every 50 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_relay(0);
    gpioTerminate();
    closelog();
    return 0;
}

