#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the irrigation cycle parameters
#define RELAY_ON_TIME 300 // seconds
#define RELAY_OFF_TIME 60  // seconds
#define CYCLE_TIME (RELAY_ON_TIME + RELAY_OFF_TIME) * 4 // Total cycle time

// Define the timer interval (seconds)
#define TIMER_INTERVAL 60

// Define the number of relays
#define NUM_RELAYS 4

// Global variables
volatile sig_atomic_t terminate = 0;
int relay_states[NUM_RELAYS] = {0, 0, 0, 0}; // 0 = OFF, 1 = ON

// Function prototypes
void signal_handler(int signal);
void timer_callback();
void activate_relay(int relay_num);
void deactivate_relay(int relay_num);
void log_message(int priority, const char *message);

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Timer callback function
void timer_callback() {
    static int current_relay = 0;

    // Deactivate all relays before activating the next one
    for (int i = 0; i < NUM_RELAYS; i++) {
        deactivate_relay(i);
    }

    // Activate the current relay
    activate_relay(current_relay);

    // Log the state change
    char message[100];
    snprintf(message, sizeof(message), "Relay %d activated", current_relay + 1);
    log_message(LOG_INFO, message);

    // Move to the next relay
    current_relay = (current_relay + 1) % NUM_RELAYS;
}

// Function to activate a relay
void activate_relay(int relay_num) {
    int pin;
    switch (relay_num) {
        case 0:
            pin = RELAY1_PIN;
            break;
        case 1:
            pin = RELAY2_PIN;
            break;
        case 2:
            pin = RELAY3_PIN;
            break;
        case 3:
            pin = RELAY4_PIN;
            break;
        default:
            log_message(LOG_ERR, "Invalid relay number");
            return;
    }

    if (gpioWrite(pin, 0) != 0) { // Active LOW
        char message[100];
        snprintf(message, sizeof(message), "Failed to activate relay %d", relay_num + 1);
        log_message(LOG_ERR, message);
    } else {
        relay_states[relay_num] = 1; // Update relay state
    }
}

// Function to deactivate a relay
void deactivate_relay(int relay_num) {
    int pin;
    switch (relay_num) {
        case 0:
            pin = RELAY1_PIN;
            break;
        case 1:
            pin = RELAY2_PIN;
            break;
        case 2:
            pin = RELAY3_PIN;
            break;
        case 3:
            pin = RELAY4_PIN;
            break;
        default:
            log_message(LOG_ERR, "Invalid relay number");
            return;
    }

    if (gpioWrite(pin, 1) != 0) { // Active LOW
        char message[100];
        snprintf(message, sizeof(message), "Failed to deactivate relay %d", relay_num + 1);
        log_message(LOG_ERR, message);
    } else {
        relay_states[relay_num] = 0; // Update relay state
    }
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    deactivate_relay(0);
    deactivate_relay(1);
    deactivate_relay(2);
    deactivate_relay(3);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the timer
    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL) != 0) {
        log_message(LOG_ERR, "Failed to set up timer");
        gpioTerminate();
        return 1;
    }

    // Main loop (sleep until termination signal is received)
    while (!terminate) {
        sleep(1); // Sleep for 1 second
    }

    // Clean up and exit
    log_message(LOG_INFO, "Cleaning up and exiting...");

    // Deactivate all relays
    deactivate_relay(0);
    deactivate_relay(1);
    deactivate_relay(2);
    deactivate_relay(3);

    // Cancel the timer
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

