#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <pthread.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_ACCEL_YOUT_H 0x3D
#define MPU6050_ACCEL_ZOUT_H 0x3F
#define MPU6050_ACCEL_CONFIG 0x1C

// Configuration
#define SAMPLE_RATE 100 // Hz
#define BUFFER_SIZE 100
#define I2C_BUS "/dev/i2c-1"
#define DRIVER_DIR "/sys/kernel/mpu6050_accel"

// Data Structure
typedef struct {
    float x;
    float y;
    float z;
} AccelData;

// Global Variables
static int i2c_fd = -1;
static AccelData accel_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static bool running = true;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
static int i2c_read_word_data(int fd, uint8_t reg);
static int i2c_write_byte_data(int fd, uint8_t reg, uint8_t value);
static int init_mpu6050(int fd);
static AccelData read_accel_data(int fd);
static void store_data(AccelData data);
static void update_driver_interface(AccelData data);
static void timer_callback(int signo, siginfo_t *info, void *context);
static void signal_handler(int signo);
static void cleanup();

// I2C Read Function
static int i2c_read_word_data(int fd, uint8_t reg) {
    int result = i2c_smbus_read_word_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }
    return result;
}

// I2C Write Function
static int i2c_write_byte_data(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// MPU6050 Initialization Function
static int init_mpu6050(int fd) {
    // Wake up the MPU6050
    if (i2c_write_byte_data(fd, MPU6050_PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error waking up MPU6050\n");
        return -1;
    }

    // Configure accelerometer range to +/- 2g
    if (i2c_write_byte_data(fd, MPU6050_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error configuring accelerometer range\n");
        return -1;
    }

    return 0;
}

// Read Accelerometer Data Function
static AccelData read_accel_data(int fd) {
    AccelData data;
    int16_t raw_x, raw_y, raw_z;

    raw_x = i2c_read_word_data(fd, MPU6050_ACCEL_XOUT_H);
    raw_y = i2c_read_word_data(fd, MPU6050_ACCEL_YOUT_H);
    raw_z = i2c_read_word_data(fd, MPU6050_ACCEL_ZOUT_H);

    if (raw_x < 0 || raw_y < 0 || raw_z < 0) {
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Convert to g-force units (assuming +/- 2g range)
    data.x = (float)raw_x / 16384.0f;
    data.y = (float)raw_y / 16384.0f;
    data.z = (float)raw_z / 16384.0f;

    return data;
}

// Store Data in Circular Buffer
static void store_data(AccelData data) {
    pthread_mutex_lock(&buffer_mutex);
    accel_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

// Update Driver Interface
static void update_driver_interface(AccelData data) {
    char filepath[256];
    snprintf(filepath, sizeof(filepath), "%s/latest", DRIVER_DIR);

    FILE *fp = fopen(filepath, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening driver interface file: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%f,%f,%f\n", data.x, data.y, data.z);
    fclose(fp);
}

// Timer Callback Function
static void timer_callback(int signo, siginfo_t *info, void *context) {
    (void)signo; // Suppress unused parameter warning
    (void)info;  // Suppress unused parameter warning
    (void)context; // Suppress unused parameter warning

    AccelData data = read_accel_data(i2c_fd);
    store_data(data);
    update_driver_interface(data);
}

// Signal Handler Function
static void signal_handler(int signo) {
    running = false;
    printf("Received signal %d, cleaning up...\n", signo);
    cleanup();
    exit(0);
}

// Cleanup Function
static void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    pthread_mutex_destroy(&buffer_mutex);
}

int main() {
    struct sigaction sa;
    struct itimerspec timer_spec;
    struct sigevent sev;

    // Signal Handling
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // I2C Initialization
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Timer Initialization
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN; // Use a real-time signal
    sev.sigev_value.sival_ptr = NULL;
    sev.sigev_notify_function = NULL;
    sev.sigev_notify_attributes = NULL;

    if (timer_create(CLOCK_REALTIME, &sev, &timer_spec.it_value) == -1) {
        perror("timer_create");
        close(i2c_fd);
        return 1;
    }

    // Timer Interval
    timer_spec.it_interval.tv_sec = 0;
    timer_spec.it_interval.tv_nsec = 10000000; // 100 Hz (10ms)

    // Start Timer
    if (timer_settime(timer_spec.it_value, 0, &timer_spec, NULL) == -1) {
        perror("timer_settime");
        close(i2c_fd);
        return 1;
    }

    // Main Loop
    while (running) {
        pause(); // Wait for signal
    }

    return 0;
}

