#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 18
#define RELAY2_GPIO 23
#define RELAY3_GPIO 24
#define RELAY4_GPIO 25

// Define the prime numbers for the intervals (seconds)
#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Structure to hold relay and interval information
typedef struct {
    int gpio;
    int interval;
    int state;
    struct timespec last_toggle_time;
} Relay;

// Global array of relay structures
Relay relays[4];

// Function prototypes
void signal_handler(int signal);
void toggle_relay(Relay *relay);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to toggle a relay
void toggle_relay(Relay *relay) {
    // Calculate the current time
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    // Calculate the time elapsed since the last toggle
    double elapsed_time = (now.tv_sec - relay->last_toggle_time.tv_sec) + (now.tv_nsec - relay->last_toggle_time.tv_nsec) / 1000000000.0;

    // Check if the elapsed time is greater than or equal to the interval
    if (elapsed_time >= relay->interval) {
        // Toggle the relay state
        relay->state = !relay->state;
        gpioWrite(relay->gpio, relay->state);

        // Update the last toggle time
        relay->last_toggle_time = now;

        // Print the current state of the relay
        printf("Relay %d (GPIO %d): State = %d\n", relay->gpio, relay->gpio, relay->state);
    }
}

// Cleanup function to turn off relays and terminate pigpio
void cleanup() {
    // Turn off all relays
    gpioWrite(RELAY1_GPIO, 0);
    gpioWrite(RELAY2_GPIO, 0);
    gpioWrite(RELAY3_GPIO, 0);
    gpioWrite(RELAY4_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Initialize relay structures
    relays[0].gpio = RELAY1_GPIO;
    relays[0].interval = INTERVAL1;
    relays[0].state = 0;
    clock_gettime(CLOCK_MONOTONIC, &relays[0].last_toggle_time);

    relays[1].gpio = RELAY2_GPIO;
    relays[1].interval = INTERVAL2;
    relays[1].state = 0;
    clock_gettime(CLOCK_MONOTONIC, &relays[1].last_toggle_time);

    relays[2].gpio = RELAY3_GPIO;
    relays[2].interval = INTERVAL3;
    relays[2].state = 0;
    clock_gettime(CLOCK_MONOTONIC, &relays[2].last_toggle_time);

    relays[3].gpio = RELAY4_GPIO;
    relays[3].interval = INTERVAL4;
    relays[3].state = 0;
    clock_gettime(CLOCK_MONOTONIC, &relays[3].last_toggle_time);

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        for (int i = 0; i < 4; i++) {
            toggle_relay(&relays[i]);
        }

        // Sleep for a short interval to avoid busy-waiting
        gpioDelay(100); // 100 milliseconds
    }

    return 0;
}

