        cleanup();
        return 1;
    }

    printf("Sound-activated relay system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (read_sound_sensor() == 1) {
            time_t now = time(NULL);
            if (difftime(now, last_relay_activation) >= config.debounce_time) {
