int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.sound_pin, PI_INPUT);
    gpioSetMode(config.relay_pin, PI_OUTPUT);
    gpioWrite(config.relay_pin, 0); // Ensure relay is initially off

    return 0;
}

