#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_PWR_MGMT_1 0x6B

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold
#define ANGULAR_VELOCITY_THRESHOLD 50.0

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_gyro_data(gyro_data_t *data);
float calculate_magnitude(gyro_data_t data);
void check_threshold(float magnitude);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting gracefully.\n");
        program_running = 0;
    }
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    uint8_t data[2];

    // Wake up the MPU-6050 (clear sleep mode bit)
    data[0] = MPU6050_PWR_MGMT_1;
    data[1] = 0x00; // Set to 0 to wake up
    if (write(i2c_fd, data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }
    delay(100); // Short delay after initialization

    return 0;
}

// Read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    uint8_t reg = MPU6050_GYRO_XOUT_H;
    uint8_t buffer[6];
    int16_t gyro_x, gyro_y, gyro_z;

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading from I2C device");
        return -1;
    }

    gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to degrees per second (assuming sensitivity of 131 LSB/deg/s)
    data->x = (float)gyro_x / 131.0;
    data->y = (float)gyro_y / 131.0;
    data->z = (float)gyro_z / 131.0;

    return 0;
}

// Calculate the magnitude of the angular velocity vector
float calculate_magnitude(gyro_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Check if the angular velocity exceeds the threshold
void check_threshold(float magnitude) {
    if (magnitude > ANGULAR_VELOCITY_THRESHOLD) {
        printf("Angular velocity threshold exceeded: %.2f degrees/second\n", magnitude);
    }
}

// Cleanup resources before exiting
void cleanup() {
    close(i2c_fd);
    printf("I2C device closed.\n");
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed.\n");
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        cleanup();
        return 1;
    }

    gyro_data_t gyro_data;
    float magnitude;

    printf("MPU-6050 data acquisition started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(gyro_data);

            // Store data in circular buffer
            gyro_buffer[buffer_index] = gyro_data;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Check threshold
            check_threshold(magnitude);
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        delay(10); // Delay for 10 milliseconds
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

