#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/time.h>
#include <pigpio.h>

// Configuration
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define MH_Z19B_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define CO2_LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define SAMPLE_INTERVAL_SEC 5
#define TIMEOUT_MS 1000
#define MAX_RETRIES 10

// Global variables
int uart_handle;
FILE *co2_log_fp = NULL;
FILE *error_log_fp = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    unsigned int co2_ppm;
    int error_flag;
} sensor_data_t;

// Function prototypes
int initialize_uart();
int send_command(const unsigned char *command, int command_len);
int read_response(unsigned char *response, int response_len);
int verify_checksum(const unsigned char *response);
sensor_data_t process_response(const unsigned char *response);
int log_data(const sensor_data_t *data);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize the UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %s\n", UART_DEVICE);
        return -1;
    }
    return 0;
}

// Function to send a command to the MH-Z19B sensor
int send_command(const unsigned char *command, int command_len) {
    int result = serWrite(uart_handle, (char *)command, command_len);
    if (result != command_len) {
        fprintf(stderr, "Error sending command: %d bytes written (expected %d)\n", result, command_len);
        return -1;
    }
    return 0;
}

// Function to read a response from the MH-Z19B sensor
int read_response(unsigned char *response, int response_len) {
    int bytes_read = 0;
    int start_time = time(NULL);
    int retries = 0;

    while (bytes_read < response_len && (time(NULL) - start_time) * 1000 < TIMEOUT_MS) {
        int chunk = serRead(uart_handle, (char *)(response + bytes_read), response_len - bytes_read);
        if (chunk > 0) {
            bytes_read += chunk;
        } else if (chunk < 0) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        } else {
            // No data received, wait a short time
            gpioDelay(1000); // 1 ms
            retries++;
            if (retries > MAX_RETRIES) {
                fprintf(stderr, "Timeout reading from UART\n");
                return -1;
            }
        }
    }

    if (bytes_read != response_len) {
        fprintf(stderr, "Incomplete response received (%d bytes, expected %d)\n", bytes_read, response_len);
        return -1;
    }

    return 0;
}

// Function to verify the checksum of the response
int verify_checksum(const unsigned char *response) {
    unsigned char checksum = 0;
    for (int i = 0; i < 8; i++) {
        checksum += response[i];
    }
    checksum = 256 - checksum;

    if (checksum != response[8]) {
        fprintf(stderr, "Checksum mismatch: calculated 0x%02X, received 0x%02X\n", checksum, response[8]);
        return -1;
    }
    return 0;
}

// Function to process the response and extract the CO2 concentration
sensor_data_t process_response(const unsigned char *response) {
    sensor_data_t data;
    data.co2_ppm = (response[2] << 8) | response[3];
    data.error_flag = 0; // Assume no error initially
    return data;
}

// Function to log the data to a file
int log_data(const sensor_data_t *data) {
    if (co2_log_fp == NULL) {
        fprintf(stderr, "CO2 log file not opened\n");
        return -1;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    long timestamp_ms = (tv.tv_sec * 1000) + (tv.tv_usec / 1000);

    fprintf(co2_log_fp, "{\"timestamp\": %ld, \"co2_ppm\": %u, \"error_flag\": %d}\n",
            timestamp_ms, data->co2_ppm, data->error_flag);
    fflush(co2_log_fp);

    printf("{\"timestamp\": %ld, \"co2_ppm\": %u, \"error_flag\": %d}\n",
           timestamp_ms, data->co2_ppm, data->error_flag);

    return 0;
}

// Function to log errors to a file
int log_error(const char *message) {
    if (error_log_fp == NULL) {
        fprintf(stderr, "Error log file not opened\n");
        return -1;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    long timestamp_ms = (tv.tv_sec * 1000) + (tv.tv_usec / 1000);

    fprintf(error_log_fp, "%ld: %s\n", timestamp_ms, message);
    fflush(error_log_fp);

    fprintf(stderr, "%ld: %s\n", timestamp_ms, message);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (co2_log_fp != NULL) {
        fclose(co2_log_fp);
    }
    if (error_log_fp != NULL) {
        fclose(error_log_fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    co2_log_fp = fopen(CO2_LOG_FILE, "a");
    if (co2_log_fp == NULL) {
