            continue;
        }

        // Verify checksum
        if (verify_checksum(response) != 0) {
            log_error("Checksum verification failed");
            data.error_flag = 1;
        } else {
            // Process response
            data = process_response(response);
        }

        // Log data
        if (log_data(&data) != 0) {
            log_error("Failed to log data");
        }

