#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// GPIO pin for alert
#define ALERT_GPIO 17

// Circular buffer size
#define BUFFER_SIZE 100

// Target heading
#define TARGET_HEADING 90.0

// Deviation threshold
#define DEVIATION_THRESHOLD 10.0

// Hard iron compensation offsets
#define HARD_IRON_X 100
#define HARD_IRON_Y -50

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_hmc5883l();
int read_raw_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
float apply_hard_iron(float x, float y);
void update_circular_buffer(float heading);
void check_deviation(float heading);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize HMC5883L
int init_hmc5883l() {
    // Configure register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Configure register B: Gain = 1
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Read raw magnetometer data
int read_raw_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate heading in degrees
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2((float)y, (float)x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Apply hard iron compensation
float apply_hard_iron(float x, float y) {
    return calculate_heading(x - HARD_IRON_X, y - HARD_IRON_Y);
}

// Update circular buffer
void update_circular_buffer(float heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check for deviation from target heading
void check_deviation(float heading) {
    float deviation = fabs(heading - TARGET_HEADING);
    if (deviation > DEVIATION_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1); // Set GPIO high
    } else {
        gpioWrite(ALERT_GPIO, 0); // Set GPIO low
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float heading;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Calculate heading
            heading = calculate_heading(raw_x, raw_y);

            // Apply hard iron compensation
            float compensated_heading = apply_hard_iron((float)raw_x, (float)raw_y);

            // Update circular buffer
            update_circular_buffer(compensated_heading);

            // Check for deviation
            check_deviation(compensated_heading);

            // Print heading (optional)
            printf("Heading: %.2f\n", compensated_heading);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0); // Set GPIO low before exiting
    gpioTerminate();

    return 0;
}

