#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define LUX_THRESHOLD_LOW 50
#define LUX_THRESHOLD_MED 150
#define LUX_THRESHOLD_HIGH 300
#define LOG_FILE "lighting_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
void control_relays(int lux_value);
void log_data(time_t timestamp, float lux_value, int red_state, int green_state, int blue_state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char buf[2];
    int lux = -1; // Initialize to an error value

    // Send start measurement command (High Resolution Mode)
    if (i2cWriteByteData(i2c_handle, 0x00, 0x10) != 0) {
        fprintf(stderr, "Error: Failed to write to I2C device.\n");
        return -1;
    }

    // Wait for measurement (at least 120ms)
    gpioDelay(120000); // 120ms

    // Read two bytes from the sensor
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read from I2C device.\n");
        return -1;
    }

    // Convert the two bytes to lux value
    lux = (buf[0] << 8) | buf[1];
    return lux;
}

// Function to control the relays based on lux value
void control_relays(int lux_value) {
    int red_state = 0, green_state = 0, blue_state = 0;

    if (lux_value < LUX_THRESHOLD_LOW) {
        gpioWrite(RED_GPIO, 1); // Turn on RED relay
        red_state = 1;
    } else {
        gpioWrite(RED_GPIO, 0); // Turn off RED relay
        red_state = 0;
    }

    if (lux_value >= LUX_THRESHOLD_LOW && lux_value <= LUX_THRESHOLD_MED) {
        gpioWrite(GREEN_GPIO, 1); // Turn on GREEN relay
        green_state = 1;
    } else {
        gpioWrite(GREEN_GPIO, 0); // Turn off GREEN relay
        green_state = 0;
    }

    if (lux_value > LUX_THRESHOLD_MED && lux_value <= LUX_THRESHOLD_HIGH) {
        gpioWrite(BLUE_GPIO, 1); // Turn on BLUE relay
        blue_state = 1;
    } else {
        gpioWrite(BLUE_GPIO, 0); // Turn off BLUE relay
        blue_state = 0;
    }

    log_data(time(NULL), (float)lux_value, red_state, green_state, blue_state);
}

// Function to log data to file
void log_data(time_t timestamp, float lux_value, int red_state, int green_state, int blue_state) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%d,%d,%d\n", timestamp_str, lux_value, red_state, green_state, blue_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

