#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM Frequency
#define PWM_FREQUENCY 1000

// Proportional Constant
#define PROPORTIONAL_CONSTANT 2.0

// Distance Threshold
#define DISTANCE_THRESHOLD 50.0

// Global flag for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, terminating gracefully...\n");
}

// Function to set motor direction
void set_motor_direction(int in1, int in2, int direction)
{
    if (direction == 1) // Forward
    {
        gpioWrite(in1, 1);
        gpioWrite(in2, 0);
    }
    else // Backward
    {
        gpioWrite(in1, 0);
        gpioWrite(in2, 1);
    }
}

// Function to set motor speed
void set_motor_speed(int in, int speed)
{
    gpioPWM(in, speed);
}

// Function to calculate PWM duty cycle based on distance
int calculate_pwm_duty(int distance)
{
    if (distance < 0 || distance > 100) {
        fprintf(stderr, "Error: Distance out of range (0-100 cm): %d\n", distance);
        return 0; // Or handle the error as appropriate
    }

    float duty_cycle = (float)distance / 100.0 * PROPORTIONAL_CONSTANT;
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    return (int)duty_cycle;
}

// Function to control motor A
void control_motor_a(int distance)
{
    int speed = calculate_pwm_duty(distance);
    set_motor_speed(MOTOR_A_IN2, speed);
    set_motor_direction(MOTOR_A_IN1, MOTOR_A_IN2, (distance < DISTANCE_THRESHOLD) ? 1 : 0);
}

// Function to control motor B
void control_motor_b(int distance)
{
    int speed = calculate_pwm_duty(distance);
    set_motor_speed(MOTOR_B_IN4, speed);
    set_motor_direction(MOTOR_B_IN3, MOTOR_B_IN4, (distance < DISTANCE_THRESHOLD) ? 1 : 0);
}

int main(int argc, char *argv[])
{
    if (argc != 3)
    {
        fprintf(stderr, "Usage: %s <distance_motor_a> <distance_motor_b>\n", argv[0]);
        return 1;
    }

    int distance_motor_a = atoi(argv[1]);
    int distance_motor_b = atoi(argv[2]);

    if (distance_motor_a < 10 || distance_motor_a > 100 || distance_motor_b < 10 || distance_motor_b > 100)
    {
        fprintf(stderr, "Error: Distance values must be between 10 and 100 cm.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR_A_IN2, 255);
    gpioSetPWMrange(MOTOR_B_IN4, 255);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        control_motor_a(distance_motor_a);
        control_motor_b(distance_motor_b);

        gpioDelay(100); // 100 ms delay
    }

    // Stop motors
    set_motor_speed(MOTOR_A_IN2, 0);
    set_motor_speed(MOTOR_B_IN4, 0);

    // Cleanup
    gpioTerminate();

    return 0;
}

