#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

// Define step sequence
const int step_sequence[4][4] = {
    {1, 0, 0, 0},
    {1, 1, 0, 0},
    {0, 1, 0, 0},
    {0, 1, 1, 0}
};

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_motor_step(int step);
void lock_door();
void unlock_door();
void button_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    if (gpioSetMode(IN1, PI_OUTPUT) < 0) { fprintf(stderr, "Failed to set IN1 mode\n"); }
    if (gpioSetMode(IN2, PI_OUTPUT) < 0) { fprintf(stderr, "Failed to set IN2 mode\n"); }
    if (gpioSetMode(IN3, PI_OUTPUT) < 0) { fprintf(stderr, "Failed to set IN3 mode\n"); }
    if (gpioSetMode(IN4, PI_OUTPUT) < 0) { fprintf(stderr, "Failed to set IN4 mode\n"); }
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0) { fprintf(stderr, "Failed to set LOCK_BUTTON mode\n"); }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) { fprintf(stderr, "Failed to set UNLOCK_BUTTON mode\n"); }

    // Enable pull-up resistors
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0) { fprintf(stderr, "Failed to set LOCK_BUTTON pull-up\n"); }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) { fprintf(stderr, "Failed to set UNLOCK_BUTTON pull-up\n"); }

    return 0; // Indicate success
}

// Function to set the motor to a specific step
void set_motor_step(int step) {
    gpioWrite(IN1, step_sequence[step][0]);
    gpioWrite(IN2, step_sequence[step][1]);
    gpioWrite(IN3, step_sequence[step][2]);
    gpioWrite(IN4, step_sequence[step][3]);
    gpioDelay(2); // 2ms delay
}

// Function to lock the door
void lock_door() {
    printf("Locking door...\n");
    for (int i = 0; i < 512; i++) {
        set_motor_step(i % 4);
    }
    printf("Door locked.\n");
}

// Function to unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    for (int i = 0; i < 512; i++) {
        set_motor_step(3 - (i % 4)); // Reverse the step sequence
    }
    printf("Door unlocked.\n");
}

// Callback function for button presses
void button_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_lock_tick = 0;
    static uint32_t last_unlock_tick = 0;

    if (gpio == LOCK_BUTTON && level == 0) {
        if (tick - last_lock_tick > 200) { // Debounce (200ms)
            lock_door();
            last_lock_tick = tick;
        }
    } else if (gpio == UNLOCK_BUTTON && level == 0) {
        if (tick - last_unlock_tick > 200) { // Debounce (200ms)
            unlock_door();
            last_unlock_tick = tick;
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Stop the motor (set all coils to LOW)
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);

    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Set up interrupt handlers for buttons
    gpioSetAlertFunc(LOCK_BUTTON, button_callback);
    gpioSetAlertFunc(UNLOCK_BUTTON, button_callback);

    printf("Door control program started. Press Ctrl+C to exit.\n");

    // Main loop (keep the program running until a signal is received)
    while (program_running) {
        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    return 0;
}

