int pwm_enable(int enable);
int pwm_set_period(int period);
int pwm_set_duty_cycle(int duty_cycle);

// I2C read function with retry and exponential backoff
int i2c_read_reg(int fd, uint8_t reg) {
    int retries = 0;
    int delay_ms = 10;
    int result;

    while (retries < 5) {
        result = wiringPiI2CReadReg8(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
            retries++;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X)\n", reg);
    return -1; // Indicate failure
}

// I2C write function with retry and exponential backoff
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int retries = 0;
    int delay_ms = 10;
    int result;

    while (retries < 5) {
        result = wiringPiI2CWriteReg8(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %s\n", reg, value, strerror(errno));
            retries++;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
