    *accel_y = (int16_t)((i2c_read_reg(fd, ACCEL_XOUT_H + 2) << 8) | i2c_read_reg(fd, ACCEL_XOUT_H + 3));
    *accel_z = (int16_t)((i2c_read_reg(fd, ACCEL_XOUT_H + 4) << 8) | i2c_read_reg(fd, ACCEL_XOUT_H + 5));
