// Define the fade duration in seconds
#define FADE_DURATION 1800

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Structure to represent a schedule entry
typedef struct {
    time_t timestamp;
    int relay_number;
    int state; // 0 for off, 1 for on
} schedule_entry_t;

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_schedule(const char *filename, schedule_entry_t *schedule, int *schedule_size);
int parse_schedule_line(const char *line, schedule_entry_t *entry);
int set_relay_state(int relay_number, int state);
int fade_relay(int relay_number, int target_state);
void signal_handler(int signal);
void log_message(const char *message);

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Initialize all relays to OFF
    gpioPWM(RELAY1_PIN, 0);
    gpioPWM(RELAY2_PIN, 0);
    gpioPWM(RELAY3_PIN, 0);
    gpioPWM(RELAY4_PIN, 0);

    return 0;
}

// Function to read the schedule from the file
int read_schedule(const char *filename, schedule_entry_t *schedule, int *schedule_size) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        log_message("Error opening schedule file");
        return 1;
    }

    char line[256];
    *schedule_size = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (parse_schedule_line(line, &schedule[*schedule_size]) == 0) {
            (*schedule_size)++;
        }
    }

    fclose(fp);
    return 0;
}

// Function to parse a schedule line
int parse_schedule_line(const char *line, schedule_entry_t *entry) {
    char *token;
    char *line_copy = strdup(line); // Duplicate the line for strtok
    if (line_copy == NULL) {
        log_message("Memory allocation error in parse_schedule_line");
        return 1;
    }

    token = strtok(line_copy, ",");
    if (token == NULL) {
        log_message("Invalid schedule line format (timestamp missing)");
        free(line_copy);
        return 1;
    }
    if (sscanf(token, "%d:%d:%d", &entry->timestamp.tm_hour, &entry->timestamp.tm_min, &entry->timestamp.tm_sec) != 3) {
        log_message("Invalid timestamp format");
        free(line_copy);
        return 1;
    }

    token = strtok(NULL, ",");
    if (token == NULL) {
        log_message("Invalid schedule line format (relay number missing)");
        free(line_copy);
        return 1;
    }
    if (sscanf(token, "%d", &entry->relay_number) != 1) {
        log_message("Invalid relay number format");
        free(line_copy);
        return 1;
    }

    token = strtok(NULL, ",");
    if (token == NULL) {
        log_message("Invalid schedule line format (state missing)");
        free(line_copy);
        return 1;
    }
    if (sscanf(token, "%d", &entry->state) != 1) {
        log_message("Invalid state format");
        free(line_copy);
        return 1;
    }

    free(line_copy);
    return 0;
}

// Function to set the state of a relay
int set_relay_state(int relay_number, int state) {
    int pin;
    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            log_message("Invalid relay number");
            return 1;
    }

    gpioPWM(pin, state ? 100 : 0); // Set duty cycle to 100% or 0%
    return 0;
}

// Function to fade the brightness of a relay
int fade_relay(int relay_number, int target_state) {
    int pin;
    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            log_message("Invalid relay number");
            return 1;
    }

    int current_state = gpioPWM(pin, 0); // Read current duty cycle
    if (current_state < 0) {
        log_message("Error reading current PWM duty cycle");
        return 1;
    }

    int steps = 100; // Number of steps for the fade
    int delay_ms = FADE_DURATION * 1000 / steps; // Delay between steps in milliseconds

    for (int i = 0; i <= steps; i++) {
        int duty_cycle = (target_state * i) / steps; // Calculate duty cycle
        gpioPWM(pin, duty_cycle);
        gpioDelay(delay_ms);
    }

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_message("Signal received, shutting down...");

    // Turn off all relays
    set_relay_state(1, 0);
    set_relay_state(2, 0);
    set_relay_state(3, 0);
    set_relay_state(4, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to log messages to a file
void log_message(const char *message) {
    if (log_file == NULL) {
        log_file = fopen("lighting.log", "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return;
        }
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    schedule_entry_t schedule[100]; // Assuming a maximum of 100 schedule entries
    int schedule_size = 0;

    // Read the schedule
    if (read_schedule(SCHEDULE_FILE, schedule, &schedule_size) != 0) {
        return 1;
    }

    // Sort the schedule by timestamp
    for (int i = 0; i < schedule_size - 1; i++) {
        for (int j = 0; j < schedule_size - i - 1; j++) {
            if (schedule[j].timestamp.tv_sec > schedule[j + 1].timestamp.tv_sec) {
                schedule_entry_t temp = schedule[j];
                schedule[j] = schedule[j + 1];
                schedule[j + 1] = temp;
            }
        }
    }

    time_t current_time;
    time(&current_time);

    // Main loop
    while (program_running) {
        time(&current_time);

        // Check for schedule changes
        for (int i = 0; i < schedule_size; i++) {
            if (current_time >= schedule[i].timestamp) {
                // Fade to the target state
                fade_relay(schedule[i].relay_number, schedule[i].state);

                // Remove the entry from the schedule
                schedule[i] = schedule[schedule_size - 1];
                schedule_size--;
                i--; // Adjust index after removing an element
            }
        }

        gpioDelay(1000); // Check every second
    }

    return 0;
}

