#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 200.0    // Maximum distance in cm
#define MIN_FREQUENCY 200     // Minimum PWM frequency in Hz
#define MAX_FREQUENCY 2000    // Maximum PWM frequency in Hz
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds
#define MIN_GAP_US 60000000   // Minimum gap between measurements in microseconds

// Global variables
static volatile int running = 1;
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(uint32_t pulse_width);
int map_distance_to_frequency(float distance);
void set_buzzer_frequency(int frequency);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1;
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 0;
    }
}

// Function to calculate distance from pulse width
float calculate_distance(uint32_t pulse_width) {
    if (pulse_width == 0) return -1.0; // Indicate error
    return ((float)pulse_width * SPEED_OF_SOUND) / 2000000.0; // Convert pulse width to distance in cm
}

// Function to map distance to PWM frequency
int map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return (int)((distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_FREQUENCY);
    }
}

// Function to set the PWM frequency of the buzzer
void set_buzzer_frequency(int frequency) {
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        fprintf(stderr, "Error: Frequency out of range (%d Hz). Clamping to min/max.\n", frequency);
        if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
        if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;
    }
    gpioSetPWMfrequency(BUZZER_PIN, frequency);
}

// Cleanup function to stop PWM and terminate pigpio
void cleanup() {
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();        // Terminate pigpio
    printf("pigpio terminated.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (optional, but recommended)
    gpioSetPWMrange(BUZZER_PIN, 1000); // Set range to 1000 for finer control

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    uint32_t last_measurement_time = 0;

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        // Calculate current time in microseconds
        uint32_t current_time = gpioTick();

        // Check if enough time has passed since the last measurement
        if (current_time - last_measurement_time >= MIN_GAP_US) {
            // Generate trigger pulse
            trigger_pulse();

            // Wait for echo pulse (with timeout)
            uint32_t start = gpioTick();
            while (!echo_received && running) {
                if (gpioTick() - start > TIMEOUT_US) {
                    fprintf(stderr, "Error: Echo pulse timeout.\n");
                    break; // Exit loop if timeout occurs
                }
                gpioDelay(1); // Small delay to prevent busy-waiting
            }

            if (!running) break; // Exit main loop if signal received

            // Calculate pulse width
            uint32_t pulse_width = end_tick - start_tick;

            // Calculate distance
            float distance = calculate_distance(pulse_width);

            if (distance > 0) {
                // Map distance to frequency
                int frequency = map_distance_to_frequency(distance);

                // Set buzzer frequency
                set_buzzer_frequency(frequency);

                // Update last measurement time
                last_measurement_time = current_time;
            } else {
                fprintf(stderr, "Error: Invalid distance reading.\n");
            }
        } else {
            gpioDelay(1); // Small delay to prevent busy-waiting
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

