    {440, 200}, {494, 200}, {523, 200}, {587, 200}, {659, 200}, {698, 200}, {784, 200}, {880, 200}
};

// Define melody length
const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Global variables
volatile int button_pressed = 0;
volatile int playing_melody = 0;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user);
void play_melody();
void stop_melody();
void cleanup(int signal);

// Button interrupt service routine (ISR)
void button_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    // Debounce the button
    if (current_tick - last_tick > DEBOUNCE_TIME * 1000) {
        if (level == 0) { // Button is pressed (active-low)
            button_pressed = 1;
        }
        last_tick = current_tick;
    }
}

// Function to play the melody
void play_melody() {
    playing_melody = 1;
    for (int i = 0; i < melody_length; i++) {
        if (!playing_melody) break; // Stop if another button press occurs

        // Generate tone
        gpioPWM(BUZZER_PIN, 128); // 50% duty cycle (128/255)
        gpioSetPWMfrequency(BUZZER_PIN, melody[i].frequency);
        gpioDelay(melody[i].duration * 1000); // Delay for duration (in microseconds)

        // Stop tone
        gpioPWM(BUZZER_PIN, 0); // Turn off PWM
        gpioDelay(50 * 1000); // Short pause between notes
    }
    playing_melody = 0;
}

// Function to stop the melody
void stop_melody() {
    playing_melody = 0;
    gpioPWM(BUZZER_PIN, 0); // Turn off PWM
}

// Signal handler for clean shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Enable internal pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set PWM range (0-255)
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(BUZZER_PIN, 440); // Initial frequency

    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Register button ISR
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR\n");
        gpioTerminate();
        return 1;
    }

    printf("Doorbell program running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (button_pressed) {
            button_pressed = 0;
            play_melody();
        }
        gpioDelay(10 * 1000); // Small delay to prevent busy-waiting
    }

    return 0;
}

