#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5
#define POLL_TIMEOUT_MS 1000

volatile sig_atomic_t terminate = 0;

// Structure to hold the sliding window of events
typedef struct {
    int window[WINDOW_SIZE];
    int head;
    int count;
} EventWindow;

// Function prototypes
int read_sensor();
void log_event(int value);
void check_earthquake_alert(EventWindow *window);
void signal_handler(int signal);
void initialize_event_window(EventWindow *window);

// Global event window
EventWindow event_window;

int main(int argc, char *argv[]) {
    int poll_timeout_ms = POLL_TIMEOUT_MS;

    // Parse command-line arguments
    if (argc > 1) {
        poll_timeout_ms = atoi(argv[1]);
        if (poll_timeout_ms <= 0) {
            fprintf(stderr, "Invalid poll timeout. Using default value: %d ms\n", POLL_TIMEOUT_MS);
            poll_timeout_ms = POLL_TIMEOUT_MS;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the event window
    initialize_event_window(&event_window);

    // Main loop
    while (!terminate) {
        int sensor_value = read_sensor();

        if (sensor_value == -1) {
            fprintf(stderr, "Error reading sensor value\n");
            continue; // Continue to the next iteration
        }

        log_event(sensor_value);

        // Update the event window
        event_window.window[event_window.head] = sensor_value;
        event_window.head = (event_window.head + 1) % WINDOW_SIZE;
        if (event_window.count < WINDOW_SIZE) {
            event_window.count++;
        }

        // Check for earthquake alert
        check_earthquake_alert(&event_window);

        // Polling with timeout
        gpioDelay(poll_timeout_ms * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    gpioTerminate();
    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to log the event to a file
void log_event(int value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s %d\n", timestamp, value);

    if (ferror(fp)) {
        fprintf(stderr, "Error writing to log file: %s\n", LOG_FILE);
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", LOG_FILE);
    }

    if (fsync(fileno(fp)) != 0) {
        fprintf(stderr, "Error syncing log file: %s\n", LOG_FILE);
    }

    fclose(fp);
}

// Function to check for earthquake alert
void check_earthquake_alert(EventWindow *window) {
    int high_count = 0;
    for (int i = 0; i < window->count; i++) {
        if (window->window[i] == 1) {
            high_count++;
        }
    }

    if (high_count >= 3) {
        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

        printf("EARTHQUAKE ALERT: %s\n", timestamp);
    }
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the event window
void initialize_event_window(EventWindow *window) {
    window->head = 0;
    window->count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        window->window[i] = 0; // Initialize all values to 0
    }
}

