#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC register addresses
#define LSM303_CTRL_REG1_M 0x20
#define LSM303_OUT_X_L_M 0x28
#define LSM303_OUT_X_H_M 0x29
#define LSM303_OUT_Y_L_M 0x2A
#define LSM303_OUT_Y_H_M 0x2B
#define LSM303_OUT_Z_L_M 0x2C
#define LSM303_OUT_Z_H_M 0x2D

// Hard-iron calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int init_i2c();
magnetometer_data_t read_magnetometer();
magnetometer_data_t calibrate_magnetometer(magnetometer_data_t raw_data);
float calculate_heading(magnetometer_data_t calibrated_data);
const char* get_compass_direction(float heading);
int log_data(magnetometer_data_t calibrated_data, float heading);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure the magnetometer (e.g., set gain and data rate)
    if (i2cWriteByteData(i2c_handle, LSM303_CTRL_REG1_M, 0x70) < 0) { // Enable all axes, 50 Hz data rate
        fprintf(stderr, "Error writing to CTRL_REG1_M\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read raw magnetometer data
magnetometer_data_t read_magnetometer() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LSM303_OUT_X_L_M | 0x80, buffer, 6) < 0) { // Read 6 bytes starting from OUT_X_L_M
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Function to calibrate magnetometer data
magnetometer_data_t calibrate_magnetometer(magnetometer_data_t raw_data) {
    magnetometer_data_t calibrated_data;
    calibrated_data.x = raw_data.x - X_OFFSET;
    calibrated_data.y = raw_data.y - Y_OFFSET;
    calibrated_data.z = raw_data.z - Z_OFFSET;
    return calibrated_data;
}

// Function to calculate heading in degrees
float calculate_heading(magnetometer_data_t calibrated_data) {
    float heading = atan2(calibrated_data.y, calibrated_data.x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Function to get compass direction based on heading
const char* get_compass_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) return "N";
    if (heading < 67.5) return "NE";
    if (heading < 112.5) return "E";
    if (heading < 157.5) return "SE";
    if (heading < 202.5) return "S";
    if (heading < 247.5) return "SW";
    if (heading < 292.5) return "W";
    if (heading < 337.5) return "NW";
    return "N"; // Default to North
}

// Function to log data to a CSV file
int log_data(magnetometer_data_t calibrated_data, float heading) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %d, %d, %d, %.2f\n", timestamp, calibrated_data.x, calibrated_data.y, calibrated_data.z, heading);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup function to close I2C and file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t raw_data = read_magnetometer();

        // Calibrate magnetometer data
        magnetometer_data_t calibrated_data = calibrate_magnetometer(raw_data);

        // Calculate heading
        float heading = calculate_heading(calibrated_data);

        // Get compass direction
        const char* direction = get_compass_direction(heading);

        // Log data
        if (log_data(calibrated_data, heading) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Print to console
        printf("Direction: %s, Heading: %.2f\n", direction, heading);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

