// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int running = 1;
static volatile unsigned long last_touch_time = 0;
static volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
int log_state(const char *state);
void signal_handler(int signal);

