int log_state(const char *state) {
    FILE *fp = fopen("relay_log.json", "a");
    if (fp == NULL) {
        perror("Error opening relay_log.json");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", timestamp, state);
    fclose(fp);
    return 0;
}

