    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    control_relay(0); // Turn relay OFF
    log_state("OFF");
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            unsigned long current_time = gpioTick();

            if ((current_time - last_touch_time) > (DEBOUNCE_TIME * 1000)) {
                relay_state = !relay_state; // Toggle relay state
                control_relay(relay_state);

                if (relay_state == 1) {
                    log_state("ON");
                } else {
                    log_state("OFF");
                }

                last_touch_time = current_time;
            }
        }

        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0;
}

