// Define GPIO pins for relays
#define RELAY1 17
#define RELAY2 23
#define RELAY3 24
#define RELAY4 25

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Define irrigation duration
#define IRRIGATION_DURATION 5

// Define relay activation delay
#define RELAY_DELAY 1

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_moisture();
void activate_relay(int relay_num, int moisture);
void log_data(int relay_num, int moisture);
void cleanup();
void signal_handler(int signal);

// Structure to hold GPIO pin numbers
typedef struct {
    int relay1;
    int relay2;
    int relay3;
    int relay4;
} RelayPins;

RelayPins pins = {RELAY1, RELAY2, RELAY3, RELAY4};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(pins.relay1, PI_OUTPUT);
    gpioSetMode(pins.relay2, PI_OUTPUT);
    gpioSetMode(pins.relay3, PI_OUTPUT);
    gpioSetMode(pins.relay4, PI_OUTPUT);

    // Set all relays to inactive (HIGH)
    gpioWrite(pins.relay1, 1);
    gpioWrite(pins.relay2, 1);
    gpioWrite(pins.relay3, 1);
    gpioWrite(pins.relay4, 1);

    return 0;
}

// Function to read simulated soil moisture value
int read_moisture() {
    return rand() % 101; // Returns a value between 0 and 100
}

// Function to activate a relay for a specified duration
void activate_relay(int relay_num, int moisture) {
    int gpio_pin;

    switch (relay_num) {
        case 1:
            gpio_pin = pins.relay1;
            break;
        case 2:
            gpio_pin = pins.relay2;
            break;
        case 3:
            gpio_pin = pins.relay3;
            break;
        case 4:
            gpio_pin = pins.relay4;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_num);
            return;
    }

    if (moisture < MOISTURE_THRESHOLD) {
        gpioWrite(gpio_pin, 0); // Activate relay (LOW)
        gpioDelay(IRRIGATION_DURATION * 1000000); // Delay for irrigation duration (microseconds)
        gpioWrite(gpio_pin, 1); // Deactivate relay (HIGH)
    }
}

// Function to log data to a file
void log_data(int relay_num, int moisture) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Relay %d, Moisture: %d\n", timestamp, relay_num, moisture);
        fflush(log_file); // Flush the buffer to ensure data is written to the file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Function to cleanup GPIO and close log file
void cleanup() {
    // Deactivate all relays
    gpioWrite(pins.relay1, 1);
    gpioWrite(pins.relay2, 1);
    gpioWrite(pins.relay3, 1);
    gpioWrite(pins.relay4, 1);

    // Release GPIO pins
    gpioSetMode(pins.relay1, PI_INPUT); // Set to input to release
    gpioSetMode(pins.relay2, PI_INPUT);
    gpioSetMode(pins.relay3, PI_INPUT);
    gpioSetMode(pins.relay4, PI_INPUT);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int moisture = read_moisture();
        printf("Moisture: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            for (int i = 1; i <= 4; i++) {
                activate_relay(i, moisture);
                log_data(i, moisture);
                gpioDelay(RELAY_DELAY * 1000000); // Delay between relays (microseconds)
            }
        }

        gpioDelay(10 * 1000000); // Delay for 10 seconds (microseconds)
    }

    return 0;
}

