#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_PIN 17
#define NOZZLE_PIN 18

// Define servo pulse widths (microseconds)
#define VALVE_OPEN_PULSE 1500
#define VALVE_CLOSE_PULSE 500
#define NOZZLE_PULSE_0 500
#define NOZZLE_PULSE_45 1000
#define NOZZLE_PULSE_90 1500
#define NOZZLE_PULSE_135 2000
#define NOZZLE_PULSE_180 2500

// Define moisture thresholds
#define MOISTURE_THRESHOLD_LOW 50
#define MOISTURE_THRESHOLD_HIGH 100

// Define watering cycle parameters
#define VALVE_OPEN_TIME 5
#define NOZZLE_SWEEP_TIME 2
#define VALVE_CLOSE_TIME 5
#define NOZZLE_HOLD_TIME 5
#define NOZZLE_SWEEP_PAUSE 5

// Define retry parameters
#define MAX_RETRIES 3
#define BACKOFF_DELAY 100 // milliseconds

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Function to set servo pulse width with retry
int set_servo_pulse(int gpio, int pulse_width) {
    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES) {
        result = gpioServo(gpio, pulse_width);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error setting servo pulse width (GPIO %d, pulse %d): %d. Retrying...\n", gpio, pulse_width, result);
            gpioDelay(BACKOFF_DELAY * 1000); // Convert ms to microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to set servo pulse width (GPIO %d, pulse %d) after %d retries.\n", gpio, pulse_width, MAX_RETRIES);
    return -1; // Failure
}

// Function to open the valve
int open_valve() {
    if (set_servo_pulse(VALVE_PIN, VALVE_OPEN_PULSE) != 0) {
        fprintf(stderr, "Error opening valve.\n");
        return -1;
    }
    gpioDelay(VALVE_OPEN_TIME * 1000000); // Convert seconds to microseconds
    return 0;
}

// Function to close the valve
int close_valve() {
    if (set_servo_pulse(VALVE_PIN, VALVE_CLOSE_PULSE) != 0) {
        fprintf(stderr, "Error closing valve.\n");
        return -1;
    }
    gpioDelay(VALVE_CLOSE_TIME * 1000000); // Convert seconds to microseconds
    return 0;
}

// Function to sweep the nozzle
int sweep_nozzle() {
    int pulse_widths[] = {NOZZLE_PULSE_0, NOZZLE_PULSE_45, NOZZLE_PULSE_90, NOZZLE_PULSE_135, NOZZLE_PULSE_180};
    int num_positions = sizeof(pulse_widths) / sizeof(pulse_widths[0]);

    for (int i = 0; i < num_positions; i++) {
        if (set_servo_pulse(NOZZLE_PIN, pulse_widths[i]) != 0) {
            fprintf(stderr, "Error setting nozzle position %d.\n", i);
            // Continue to the next position, but log the error
        }
        gpioDelay(NOZZLE_SWEEP_TIME * 1000000); // Convert seconds to microseconds
    }

    gpioDelay(NOZZLE_HOLD_TIME * 1000000); // Convert seconds to microseconds
    return 0;
}

// Function to simulate soil moisture reading
int read_soil_moisture() {
    static int moisture = 20;
    static int index = 0;

    moisture = 20 + (index * 20);
    index = (index + 1) % 5; // Cycle through the sequence
    return moisture;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(VALVE_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_PIN, PI_OUTPUT);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read soil moisture
        int moisture = read_soil_moisture();
        printf("Soil moisture: %d\n", moisture);

        // Check moisture level and perform watering cycle if needed
        if (moisture < MOISTURE_THRESHOLD_LOW) {
            printf("Moisture level low, starting watering cycle.\n");

            // Open the valve
            if (open_valve() != 0) {
                fprintf(stderr, "Failed to open valve, skipping watering cycle.\n");
                continue; // Skip the rest of the cycle
            }

            // Sweep the nozzle
            if (sweep_nozzle() != 0) {
                fprintf(stderr, "Failed to sweep nozzle, skipping watering cycle.\n");
            }

            // Close the valve
            if (close_valve() != 0) {
                fprintf(stderr, "Failed to close valve.\n");
            }

            // Wait before the next cycle
            gpioDelay(NOZZLE_SWEEP_PAUSE * 1000000); // Convert seconds to microseconds
        } else {
            printf("Moisture level sufficient, skipping watering cycle.\n");
        }

        // Wait before the next moisture reading
        gpioDelay(1000000); // 1 second
    }

    // Stop servos and cleanup
    printf("Stopping servos and cleaning up...\n");
    set_servo_pulse(VALVE_PIN, 0); // Stop valve
    set_servo_pulse(NOZZLE_PIN, 0); // Stop nozzle
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

