    int pulse_widths[] = {NOZZLE_PULSE_0, NOZZLE_PULSE_45, NOZZLE_PULSE_90, NOZZLE_PULSE_135, NOZZLE_PULSE_180};
    int num_positions = sizeof(pulse_widths) / sizeof(pulse_widths[0]);

    for (int i = 0; i < num_positions; i++) {
        if (set_servo_pulse(NOZZLE_PIN, pulse_widths[i]) != 0) {
            fprintf(stderr, "Error setting nozzle position %d.\n", i);
            // Continue to the next position, but log the error
        }
        gpioDelay(NOZZLE_SWEEP_TIME * 1000000); // Convert seconds to microseconds
    }

    gpioDelay(NOZZLE_HOLD_TIME * 1000000); // Convert seconds to microseconds
    return 0;
}

// Function to simulate soil moisture reading
int read_soil_moisture() {
    static int moisture = 20;
    static int index = 0;

    moisture = 20 + (index * 20);
    index = (index + 1) % 5; // Cycle through the sequence
    return moisture;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(VALVE_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_PIN, PI_OUTPUT);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read soil moisture
        int moisture = read_soil_moisture();
        printf("Soil moisture: %d\n", moisture);

        // Check moisture level and perform watering cycle if needed
        if (moisture < MOISTURE_THRESHOLD_LOW) {
            printf("Moisture level low, starting watering cycle.\n");

            // Open the valve
            if (open_valve() != 0) {
                fprintf(stderr, "Failed to open valve, skipping watering cycle.\n");
                continue; // Skip the rest of the cycle
            }

            // Sweep the nozzle
            if (sweep_nozzle() != 0) {
                fprintf(stderr, "Failed to sweep nozzle, skipping watering cycle.\n");
            }

            // Close the valve
            if (close_valve() != 0) {
                fprintf(stderr, "Failed to close valve.\n");
            }

            // Wait before the next cycle
            gpioDelay(NOZZLE_SWEEP_PAUSE * 1000000); // Convert seconds to microseconds
        } else {
            printf("Moisture level sufficient, skipping watering cycle.\n");
        }

        // Wait before the next moisture reading
        gpioDelay(1000000); // 1 second
    }

    // Stop servos and cleanup
    printf("Stopping servos and cleaning up...\n");
    set_servo_pulse(VALVE_PIN, 0); // Stop valve
    set_servo_pulse(NOZZLE_PIN, 0); // Stop nozzle
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

