#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_PWR_MGMT_1 0x6B

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_mpu6050();
int read_gyro_data(gyro_data_t *data);
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char buf[6];
    int16_t gyro_x, gyro_y, gyro_z;

    if (i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyro data: %s\n", strerror(errno));
        return -1;
    }

    gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert to degrees per second (assuming sensitivity of 131 LSB/deg/s)
    data->x = (float)gyro_x / 131.0;
    data->y = (float)gyro_y / 131.0;
    data->z = (float)gyro_z / 131.0;

    return 0;
}

// Log data to file
void log_data(gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gyro_data_t gyro_data;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&gyro_data) == 0) {
            log_data(gyro_data);
        } else {
            fprintf(stderr, "Error: Failed to read gyro data. Retrying...\n");
        }

        gpioDelay(100); // 10 Hz sampling rate
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

