#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000 // 50ms timeout
#define MIN_DISTANCE 2.0  // Minimum measurable distance (cm)
#define MAX_DISTANCE 400.0 // Maximum measurable distance (cm)
#define SAMPLE_INTERVAL_US 1000000 // 1 second

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width with timeout
long measure_pulse_width() {
    long start_time = 0, end_time = 0;
    int timeout_count = 0;

    // Wait for rising edge with timeout
    while (gpioRead(ECHO_PIN) == 0) {
        start_time = gpioTick();
        if (start_time - timeout_count > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1; // Timeout
        }
        timeout_count = start_time;
    }

    // Wait for falling edge with timeout
    timeout_count = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        end_time = gpioTick();
        if (end_time - timeout_count > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1; // Timeout
        }
        timeout_count = end_time;
    }

    return end_time - start_time;
}

// Function to calculate distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (pulse_width * 0.0343) / 2.0;
}

// Function to log the distance to a file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
                fprintf(log_file, "Distance out of range: %.2f cm\n", distance);
                fflush(log_file);
            }
        } else {
            fprintf(stderr, "Error: Pulse width measurement failed\n");
            fprintf(log_file, "Error: Pulse width measurement failed\n");
            fflush(log_file);
        }

        gpioDelay(SAMPLE_INTERVAL_US); // Wait for 1 second
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

