#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_RELAY 18
#define DISTANCE_THRESHOLD 50 // cm
#define POLL_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_relay(int distance);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR 0x0027
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN 0x0024
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02x\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02x\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02x\n", reg);
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (adjust based on datasheet)
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x01) != 0) return -1; // Start with short range
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR, 0x30) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN, 0x00) != 0) return -1;
    return 0;
}

// Function to read the distance from the VL53L1X sensor
int read_distance(int *distance) {
    uint8_t range_status;
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    uint8_t msb, lsb;
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &msb) != 0) {
        fprintf(stderr, "Error reading MSB of distance\n");
        return -1;
    }
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &lsb) != 0) {
        fprintf(stderr, "Error reading LSB of distance\n");
        return -1;
    }

    *distance = (lsb << 8) | msb;

    return 0;
}

// Function to control the relay based on the distance
void control_relay(int distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_RELAY, 1); // Set relay HIGH
    } else {
        gpioWrite(GPIO_RELAY, 0); // Set relay LOW
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is initially LOW

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int distance;
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            printf("Distance: %d cm\n", distance);
            control_relay(distance);
        } else {
            fprintf(stderr, "Error reading distance, attempting to re-initialize...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (init_vl53l1x() != 0) {
                    fprintf(stderr, "VL53L1X re-initialisation failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_RELAY, 0); // Set relay LOW
    gpioTerminate();

    return 0;
}

