#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the watering duration in seconds
#define WATERING_DURATION 5

// Define the cycle duration in seconds
#define CYCLE_DURATION 60

// Define the total cycle duration for all four relays (4 * 5 + 3 * 60) seconds
#define TOTAL_CYCLE_DURATION (4 * WATERING_DURATION + 3 * CYCLE_DURATION)

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void activate_relay(int pin);
void deactivate_relay(int pin);
void log_watering_cycle();
void signal_handler(int signal);

// Structure to hold GPIO pin numbers
typedef struct {
    int relay1;
    int relay2;
    int relay3;
    int relay4;
} gpio_pins_t;

// Global variable to store GPIO pins
gpio_pins_t pins = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(pins.relay1, PI_OUTPUT);
    gpioSetMode(pins.relay2, PI_OUTPUT);
    gpioSetMode(pins.relay3, PI_OUTPUT);
    gpioSetMode(pins.relay4, PI_OUTPUT);

    // Set all relays to inactive (HIGH)
    gpioWrite(pins.relay1, 1);
    gpioWrite(pins.relay2, 1);
    gpioWrite(pins.relay3, 1);
    gpioWrite(pins.relay4, 1);

    return 0;
}

// Function to activate a relay (set GPIO pin LOW)
void activate_relay(int pin) {
    gpioWrite(pin, 0);
}

// Function to deactivate a relay (set GPIO pin HIGH)
void deactivate_relay(int pin) {
    gpioWrite(pin, 1);
