#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define log file name
#define LOG_FILE "smart_lighting.log"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int set_pwm_frequency(int gpio, int frequency);
int set_pwm_range(int gpio, int range);
int set_pwm_dutycycle(int gpio, int dutycycle);
int log_event(const char *message);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Verify GPIO pin modes
    if (gpioGetMode(RELAY1_PIN) != PI_OUTPUT) {
        log_event("Failed to set GPIO17 as output");
        return 1;
    }
    if (gpioGetMode(RELAY2_PIN) != PI_OUTPUT) {
        log_event("Failed to set GPIO18 as output");
        return 1;
    }
    if (gpioGetMode(RELAY3_PIN) != PI_OUTPUT) {
        log_event("Failed to set GPIO27 as output");
        return 1;
    }
    if (gpioGetMode(RELAY4_PIN) != PI_OUTPUT) {
        log_event("Failed to set GPIO22 as output");
        return 1;
    }

    return 0;
}

// Function to set PWM frequency
int set_pwm_frequency(int gpio, int frequency) {
    if (gpioSetPWMfrequency(gpio, frequency) != frequency) {
        char message[100];
        sprintf(message, "Failed to set PWM frequency for GPIO%d to %d Hz", gpio, frequency);
        log_event(message);
        return 1;
    }
    return 0;
}

// Function to set PWM range
int set_pwm_range(int gpio, int range) {
    if (gpioSetPWMrange(gpio, range) != range) {
        char message[100];
        sprintf(message, "Failed to set PWM range for GPIO%d to %d", gpio, range);
        log_event(message);
        return 1;
    }
    return 0;
}

// Function to set PWM duty cycle
int set_pwm_dutycycle(int gpio, int dutycycle) {
    if (gpioPWM(gpio, dutycycle) != dutycycle) {
        char message[100];
        sprintf(message, "Failed to set PWM duty cycle for GPIO%d to %d", gpio, dutycycle);
        log_event(message);
        return 1;
    }
    return 0;
}

// Function to log events to a file
int log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");

    // Stop PWM signals
    gpioPWM(RELAY1_PIN, 0);
    gpioPWM(RELAY2_PIN, 0);
    gpioPWM(RELAY3_PIN, 0);
    gpioPWM(RELAY4_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    log_event("Starting smart lighting system");

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting");
        fclose(log_file);
        return 1;
    }

    // Set PWM frequency
    if (set_pwm_frequency(RELAY1_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY2_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY3_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY4_PIN, PWM_FREQUENCY) != 0) {
        log_event("Failed to set PWM frequency, exiting");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    if (set_pwm_range(RELAY1_PIN, 255) != 0 ||
        set_pwm_range(RELAY2_PIN, 255) != 0 ||
        set_pwm_range(RELAY3_PIN, 255) != 0 ||
        set_pwm_range(RELAY4_PIN, 255) != 0) {
        log_event("Failed to set PWM range, exiting");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set initial duty cycle to 0
    set_pwm_dutycycle(RELAY1_PIN, 0);
    set_pwm_dutycycle(RELAY2_PIN, 0);
    set_pwm_dutycycle(RELAY3_PIN, 0);
    set_pwm_dutycycle(RELAY4_PIN, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Sunrise effect
    for (int dutycycle = 0; dutycycle <= 255 && running; dutycycle++) {
        set_pwm_dutycycle(RELAY1_PIN, dutycycle);
        set_pwm_dutycycle(RELAY2_PIN, dutycycle);
        set_pwm_dutycycle(RELAY3_PIN, dutycycle);
        set_pwm_dutycycle(RELAY4_PIN, dutycycle);
        gpioDelay(1000); // Wait for 1 second
    }

    log_event("Sunrise effect complete");

    // Sunset effect
    for (int dutycycle = 255; dutycycle >= 0 && running; dutycycle--) {
        set_pwm_dutycycle(RELAY1_PIN, dutycycle);
        set_pwm_dutycycle(RELAY2_PIN, dutycycle);
        set_pwm_dutycycle(RELAY3_PIN, dutycycle);
        set_pwm_dutycycle(RELAY4_PIN, dutycycle);
        gpioDelay(1000); // Wait for 1 second
    }

    log_event("Sunset effect complete");

    // Clean up and exit
    signal_handler(0); // Call signal handler to close log file and terminate pigpio

    return 0;
}

