#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_PWR_MGMT_1 0x6B

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Gyroscope sensitivity scale factor (LSB/deg/s)
#define GYRO_SCALE_FACTOR 131.0

// Threshold for LED activation (deg/s)
#define THRESHOLD 250.0

// Structure to hold gyroscope data and timestamp
typedef struct {
    time_t timestamp;
    int16_t x, y, z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C file descriptor
int i2c_fd;

// Function prototypes
int init_i2c(int address);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void store_data(time_t timestamp, int16_t x, int16_t y, int16_t z);
bool check_threshold(int16_t x, int16_t y, int16_t z);
void control_led(bool on);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    if (wiringPiI2CWriteReg8(fd, MPU6050_PWR_MGMT_1, 0) == -1) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }

    return fd;
}

// Function to read gyroscope data
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int16_t x_high, x_low, y_high, y_low, z_high, z_low;

    x_high = wiringPiI2CReadReg8(fd, MPU6050_GYRO_XOUT_H);
    x_low = wiringPiI2CReadReg8(fd, MPU6050_GYRO_XOUT_H + 1);
    y_high = wiringPiI2CReadReg8(fd, MPU6050_GYRO_XOUT_H + 2);
    y_low = wiringPiI2CReadReg8(fd, MPU6050_GYRO_XOUT_H + 3);
    z_high = wiringPiI2CReadReg8(fd, MPU6050_GYRO_XOUT_H + 4);
    z_low = wiringPiI2CReadReg8(fd, MPU6050_GYRO_XOUT_H + 5);

    if (x_high == -1 || x_low == -1 || y_high == -1 || y_low == -1 || z_high == -1 || z_low == -1) {
        fprintf(stderr, "Error reading gyro data: %s\n", strerror(errno));
        return -1;
    }

    *x = (x_high << 8) | x_low;
    *y = (y_high << 8) | y_low;
    *z = (z_high << 8) | z_low;

    return 0;
}

// Function to store data in the circular buffer
void store_data(time_t timestamp, int16_t x, int16_t y, int16_t z) {
    gyro_buffer[buffer_index].timestamp = timestamp;
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check if any axis exceeds the threshold
bool check_threshold(int16_t x, int16_t y, int16_t z) {
    float x_rate = (float)x / GYRO_SCALE_FACTOR;
    float y_rate = (float)y / GYRO_SCALE_FACTOR;
    float z_rate = (float)z / GYRO_SCALE_FACTOR;

    return (fabs(x_rate) > THRESHOLD || fabs(y_rate) > THRESHOLD || fabs(z_rate) > THRESHOLD);
}

// Function to control the LED
void control_led(bool on) {
    digitalWrite(LED_PIN, on ? HIGH : LOW);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    control_led(false);
    if (i2c_fd != -1) {
        // No explicit I2C close function in wiringPi, but we can reset the pin
        pinMode(LED_PIN, INPUT); // Release the LED pin
    }
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C with retry
    int retries = 3;
    while (retries > 0) {
        i2c_fd = init_i2c(MPU6050_ADDR);
        if (i2c_fd != -1) {
            break;
        }
        fprintf(stderr, "I2C initialization failed, retrying... (%d retries left)\n", retries - 1);
        retries--;
        delay(1000); // Wait before retrying
    }

    if (i2c_fd == -1) {
