#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_BUS "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define CS_GPIO_LINE 8 // GPIO8 (BCM)
#define CS_GPIO_CHIP "gpiochip0"
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_INTERVAL_MS 10
#define RETRY_COUNT 3

// MPU-9250 Registers
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *cs_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int cs_init(void);
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void log_data(int16_t x, int16_t y, int16_t z);
void cleanup(void);
void signal_handler(int sig);
char* iso8601_timestamp(void);

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// Chip Select Initialization
int cs_init(void) {
    cs_chip = gpiod_chip_open(CS_GPIO_CHIP);
    if (!cs_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(cs_chip, CS_GPIO_LINE);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(cs_chip);
        cs_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "gyro_cs", 1) != 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(cs_chip);
        cs_chip = NULL;
        gpiod_line_release(cs_line);
        cs_line = NULL;
        return -1;
    }

    return 0;
}

// Read Gyro Data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[6];
    uint8_t rx_buf[6];
    struct spi_ioc_transfer tr;
    int retries = 0;

    // Build the transmit buffer (read command)
    tx_buf[0] = GYRO_XOUT_H | 0x80; // Read X MSB
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = GYRO_YOUT_H | 0x80; // Read Y MSB
    tx_buf[3] = 0x00; // Dummy byte
    tx_buf[4] = GYRO_ZOUT_H | 0x80; // Read Z MSB
    tx_buf[5] = 0x00; // Dummy byte

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 6;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    while (retries < RETRY_COUNT) {
        // Assert chip select
        gpiod_line_set_value(cs_line, 0);

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
            fprintf(stderr, "SPI transaction failed (attempt %d): %s\n", retries + 1, strerror(errno));
            // De-assert chip select
            gpiod_line_set_value(cs_line, 1);
            retries++;
            usleep(1000); // Wait before retrying
        } else {
            // De-assert chip select
            gpiod_line_set_value(cs_line, 1);

            // Combine MSB and LSB for each axis
            *x = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
            *y = (int16_t)((rx_buf[2] << 8) | rx_buf[3]);
            *z = (int16_t)((rx_buf[4] << 8) | rx_buf[5]);
            return 0; // Success
        }
    }

    fprintf(stderr, "Failed to read gyro data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Log Data to CSV File
void log_data(int16_t x, int16_t y, int16_t z) {
    char *timestamp = iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp.\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
    free(timestamp);
}

// Cleanup Resources
void cleanup(void) {
    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }

    if (cs_line != NULL) {
        gpiod_line_set_value(cs_line, 1); // De-assert CS
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }

    if (cs_chip != NULL) {
        gpiod_chip_close(cs_chip);
        cs_chip = NULL;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

// Signal Handler
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// ISO 8601 Timestamp
char* iso8601_timestamp(void) {
    struct timespec ts;
    struct tm tm_info;
    char *timestamp = malloc(30 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        free(timestamp);
        return NULL;
    }

    localtime_r(&ts.tv_sec, &tm_info);

    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), 30 - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    return timestamp;
}

int main(void) {
    int16_t x, y, z;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    // Initialize Chip Select
    if (cs_init() != 0) {
        fprintf(stderr, "Chip Select initialization failed.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Gyroscope data logging started. Press Ctrl+C to stop.\n");

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyro data.\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 10ms
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

