// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 3900000 // 3.9 MHz
#define LED_GPIO 17
#define BUFFER_SIZE 64
#define THRESHOLD 200.0 // deg/s
#define BLINK_DURATION 500 // ms

// MPU-6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular Buffer Structure
typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

gyro_data_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function Prototypes
int init_spi();
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
void print_buffer();
void blink_led();
void signal_handler(int signal);

// Function to initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to initialize MPU-6050
int init_mpu6050() {
    char buf[2];

    // Wake up the MPU-6050 (set sleep bit to 0)
    buf[0] = PWR_MGMT_1;
    buf[1] = 0x00;
    if (spiWrite(spi_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100); // Short delay after waking up

    // Configure gyroscope range to +/- 250 deg/s
    buf[0] = GYRO_CONFIG;
    buf[1] = 0x00; // 0x00 = +/- 250 deg/s
    if (spiWrite(spi_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[1];
    char data[6];
    int16_t raw_x, raw_y, raw_z;

    // Read X, Y, and Z axis data
    buf[0] = GYRO_XOUT_H;
    if (spiXfer(spi_handle, buf, data, 7) != 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    raw_x = (data[0] << 8) | data[1];
    raw_y = (data[2] << 8) | data[3];
    raw_z = (data[4] << 8) | data[5];

    // Convert to degrees per second (assuming +/- 250 deg/s range)
    *x = (float)raw_x / 131.0;
    *y = (float)raw_y / 131.0;
    *z = (float)raw_z / 131.0;

    return 0;
}

