    clock_gettime(CLOCK_REALTIME, &ts);

    buffer[buffer_index].timestamp = ts;
    buffer[buffer_index].x = x;
    buffer[buffer_index].y = y;
    buffer[buffer_index].z = z;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

