void print_buffer() {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        printf("%ld.%09ld,%f,%f,%f\n", buffer[index].timestamp.tv_sec, buffer[index].timestamp.tv_nsec, buffer[index].x, buffer[index].y, buffer[index].z);
    }
}

// Function to blink the LED
void blink_led() {
    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(BLINK_DURATION * 1000); // Delay for 500ms
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(BLINK_DURATION * 1000); // Delay for 500ms
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

