    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;

    printf("Monitoring gyroscope data... Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);

            if (fabs(x) > THRESHOLD || fabs(y) > THRESHOLD || fabs(z) > THRESHOLD) {
                printf("Threshold exceeded! Blinking LED.\n");
                blink_led();
            }
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        gpioDelay(10); // Small delay to avoid overwhelming the CPU
    }

    // Print the circular buffer
    print_buffer();

    // Close SPI and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
