#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

// LED GPIO pin
#define LED_PIN 21

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_mpu6050(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void calculate_roll_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *roll, float *pitch);
void control_led(float roll, float pitch);
void log_data(float roll, float pitch);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (set power management register to 0)
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050\n");
        return -1;
    }
    return 0;
}

// Read data from MPU6050
int read_mpu6050(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[14];

    if (i2cReadI2CBlockData(i2c_handle, MPU6050_ACCEL_XOUT_H, buf, 14) != 14) {
        fprintf(stderr, "Error: Could not read data from MPU6050\n");
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    *gyro_x = (int16_t)((buf[8] << 8) | buf[9]);
    *gyro_y = (int16_t)((buf[10] << 8) | buf[11]);
    *gyro_z = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

// Calculate roll and pitch angles
void calculate_roll_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *roll, float *pitch) {
    float ax = (float)accel_x;
    float ay = (float)accel_y;
    float az = (float)accel_z;

    *roll = atan2(ay, sqrt(ax * ax + az * az)) * 180 / M_PI;
    *pitch = atan2(-ax, sqrt(ay * ay + az * az)) * 180 / M_PI;
}

// Control LED based on roll and pitch angles
void control_led(float roll, float pitch) {
    if (fabs(roll) > 45.0 || fabs(pitch) > 45.0) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

// Log data to file
void log_data(float roll, float pitch) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float roll, pitch;

    // Main loop
    while (!terminate) {
        // Read data from MPU6050
        if (read_mpu6050(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate roll and pitch
            calculate_roll_pitch(accel_x, accel_y, accel_z, &roll, &pitch);

            // Control LED
            control_led(roll, pitch);

            // Log data
            log_data(roll, pitch);

            // Print roll and pitch to console
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
        } else {
            fprintf(stderr, "Error: Failed to read MPU6050 data. Retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

