    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, &reg, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return reg;
}

// I2C write register function
int i2c_write_register(int fd, int reg, int value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, int *ambient_light, int *proximity) {
