#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXRS290 Register Addresses
#define ADXRS290_REG_X_RATE 0x00
#define ADXRS290_REG_Y_RATE 0x02
#define ADXRS290_REG_TEMP 0x04
#define ADXRS290_REG_DIAG 0x06
#define ADXRS290_REG_STATUS 0x08
#define ADXRS290_REG_ID 0x0A
#define ADXRS290_REG_SENSITIVITY 0x0C
#define ADXRS290_REG_OFFSET 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE 8 // GPIO8
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data);
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data);
int read_gyro_data(int handle, int16_t *x_rate, int16_t *y_rate);
void log_data(FILE *fp, int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set read bit
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    *data = rx_buf[1];
    return 0;
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear read bit
    tx_buf[1] = data;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    return 0;
}

// Read Gyro Data Function
int read_gyro_data(int handle, int16_t *x_rate, int16_t *y_rate) {
    uint8_t x_rate_msb, x_rate_lsb, y_rate_msb, y_rate_lsb;

    if (spi_read_register(handle, ADXRS290_REG_X_RATE, &x_rate_msb) != 0) return -1;
    if (spi_read_register(handle, ADXRS290_REG_X_RATE + 1, &x_rate_lsb) != 0) return -1;
    if (spi_read_register(handle, ADXRS290_REG_Y_RATE, &y_rate_msb) != 0) return -1;
    if (spi_read_register(handle, ADXRS290_REG_Y_RATE + 1, &y_rate_lsb) != 0) return -1;

    *x_rate = (int16_t)((x_rate_msb << 8) | x_rate_lsb);
    *y_rate = (int16_t)((y_rate_msb << 8) | y_rate_lsb);

    return 0;
}

// Log Data Function
void log_data(FILE *fp, int16_t x_rate, int16_t y_rate) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    fprintf(fp, "%ld,%d,%d\n", timestamp, x_rate, y_rate);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int16_t x_rate, y_rate;
    int retries = 3;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    while (retries > 0) {
        spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
        if (spi_handle >= 0) {
            break;
        } else {
            fprintf(stderr, "SPI open failed, retrying... (%d retries left)\n", retries - 1);
            retries--;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed after multiple retries\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(fp, "timestamp,x_rate,y_rate\n");

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_gyro_data(spi_handle, &x_rate, &y_rate) == 0) {
            log_data(fp, x_rate, y_rate);
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }

        gpioDelay(10); // 10 ms delay
    }

    // Cleanup
    fclose(fp);
    spiClose(spi_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully\n");
    return 0;
}

