#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define constants
#define ALERT_DURATION 2000 // milliseconds
#define SEISMIC_EVENT_DURATION 500 // milliseconds

// Global variables
static volatile int both_high_count = 0;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
int initialize_gpio();
int open_log_file();
void sensor_callback(int gpio, int level, uint32_t tick);
void trigger_alert();
void log_event();
void signal_handler(int signal);

// Structure to hold sensor state
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorState;

SensorState current_state = {0, 0};

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    gpioWrite(ALERT_PIN, 0); // Ensure alert pin is initially LOW

    return 0;
}

// Function to open the log file
int open_log_file() {
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }
    return 0;
}

// Callback function for sensor events
void sensor_callback(int gpio, int level, uint32_t tick) {
    int sensor1_state = gpioRead(SENSOR_1_PIN);
    int sensor2_state = gpioRead(SENSOR_2_PIN);

    if (gpio == SENSOR_1_PIN) {
        current_state.sensor1_state = sensor1_state;
    } else if (gpio == SENSOR_2_PIN) {
        current_state.sensor2_state = sensor2_state;
    }

    if (current_state.sensor1_state == 1 && current_state.sensor2_state == 1) {
        both_high_count++;
    } else {
        both_high_count = 0; // Reset counter if either sensor is LOW
    }

    if (both_high_count >= (SEISMIC_EVENT_DURATION * 1000) / 1000) { // Check if both sensors are HIGH for the required duration
        trigger_alert();
        both_high_count = 0; // Reset the counter after triggering the alert
    }
}

// Function to trigger the alert
void trigger_alert() {
    gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
    gpioDelay(ALERT_DURATION); // Wait for the alert duration
