#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADXRS290_X_AXIS_REG 0x00 // Example register address for X-axis rate
#define ADXRS290_SENSITIVITY 0.03125 // deg/s/LSB
#define THRESHOLD 20.0 // deg/s
#define LED_GPIO 17
#define CIRCULAR_BUFFER_SIZE 100

// Data structure for circular buffer entries
typedef struct {
    struct timespec timestamp;
    float rate;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[CIRCULAR_BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init();
int spi_transfer(int reg_addr, char *data, int len);
float read_gyro_rate();
void add_to_circular_buffer(circular_buffer_t *buffer, struct timespec timestamp, float rate);
gyro_data_t get_from_circular_buffer(circular_buffer_t *buffer, int index);
void check_threshold(float rate);
void signal_handler(int signal);
void cleanup();
void circular_buffer_init(circular_buffer_t *buffer);

// SPI initialization function
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// SPI transfer function
int spi_transfer(int reg_addr, char *data, int len) {
    char tx_buf[1];
    char rx_buf[1];

    tx_buf[0] = (reg_addr << 1) | 0x01; // Set MSB for read

    if (spiXfer(spi_handle, tx_buf, rx_buf, 1) != 1) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    data[0] = rx_buf[0];
    return 0;
}

// Function to read gyroscope rate
float read_gyro_rate() {
    char data[1];
    if (spi_transfer(ADXRS290_X_AXIS_REG, data, 1) != 0) {
        fprintf(stderr, "Error reading gyro rate\n");
        return 0.0; // Return 0 on error
    }

    // Convert raw data to degrees per second
    int16_t raw_rate = (int16_t)data[0]; // Assuming 8-bit data, sign extended
    float rate = (float)raw_rate * ADXRS290_SENSITIVITY;
    return rate;
}

// Function to add data to the circular buffer
void add_to_circular_buffer(circular_buffer_t *buffer, struct timespec timestamp, float rate) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head].timestamp = timestamp;
    buffer->data[buffer->head].rate = rate;
    buffer->head = (buffer->head + 1) % CIRCULAR_BUFFER_SIZE;
    if (buffer->count < CIRCULAR_BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % CIRCULAR_BUFFER_SIZE;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Function to get data from the circular buffer
gyro_data_t get_from_circular_buffer(circular_buffer_t *buffer, int index) {
    gyro_data_t data;
    pthread_mutex_lock(&buffer->mutex);
    data = buffer->data[(buffer->tail + index) % CIRCULAR_BUFFER_SIZE];
    pthread_mutex_unlock(&buffer->mutex);
    return data;
}

// Function to check the threshold and control the LED
void check_threshold(float rate) {
    if (rate > THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting...\n");
    program_running = 0;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    pthread_mutex_destroy(&circular_buffer.mutex);
}

// Initialize circular buffer
void circular_buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially off

    // Initialize circular buffer
    circular_buffer_t gyro_buffer;
    circular_buffer_init(&gyro_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        float rate = read_gyro_rate();
        add_to_circular_buffer(&gyro_buffer, ts, rate);
        check_threshold(rate);

        printf("Rate: %.2f deg/s\n", rate);

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

