#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define the total duration for the sunset simulation (in seconds)
int total_duration = 0;

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void fade_lamp(int gpio, int duration_seconds);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, terminating program...\n", signal);
        program_running = 0;
        cleanup();
        exit(0);
    }
}

// Function to initialize GPIO pins and PWM
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(LAMP1_GPIO, 255);
    gpioSetPWMrange(LAMP2_GPIO, 255);
    gpioSetPWMrange(LAMP3_GPIO, 255);

    return 0; // Indicate success
}

// Function to fade a lamp from full brightness to off
void fade_lamp(int gpio, int duration_seconds) {
    int steps = 255; // Number of steps in the fade
    int delay_ms = (duration_seconds * 1000) / steps; // Delay between steps in milliseconds

    printf("Fading lamp on GPIO %d over %d seconds...\n", gpio, duration_seconds);

    for (int i = 255; i >= 0; i--) {
        gpioPWM(gpio, i);
        gpioDelay(delay_ms * 1000); // Convert milliseconds to microseconds
    }

    printf("Lamp on GPIO %d faded to off.\n", gpio);
}

// Function to clean up GPIO and terminate pigpio
void cleanup() {
    // Turn off all lamps
    gpioPWM(LAMP1_GPIO, 0);
    gpioPWM(LAMP2_GPIO, 0);
    gpioPWM(LAMP3_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main(int argc, char *argv[]) {
    // Check command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_seconds>\n", argv[0]);
        return 1;
    }

    // Parse the total duration from the command-line argument
    total_duration = atoi(argv[1]);

    // Validate the total duration
    if (total_duration < 1 || total_duration > 3600) {
        fprintf(stderr, "Error: Total duration must be between 1 and 3600 seconds.\n");
        return 1;
    }

    // Register signal handlers for graceful termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO and PWM
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sunset simulator started. Total duration: %d seconds.\n", total_duration);

    // Fade the lamps sequentially
    fade_lamp(LAMP1_GPIO, total_duration / 3);
    fade_lamp(LAMP2_GPIO, total_duration / 3);
    fade_lamp(LAMP3_GPIO, total_duration / 3);

    printf("Sunset simulation complete.\n");

    // Clean up and exit
    cleanup();

    return 0;
}

