void red_yellow_light() {
    set_traffic_light_state(0, 0, 1, 1); // LOW for red, LOW for yellow, HIGH for others
    printf("Red + Yellow light ON\n");
    gpioDelay(2000000); // 2 seconds
}

// Function to turn on the green light and turn off others
void green_light() {
    set_traffic_light_state(1, 1, 0, 1); // HIGH for red, HIGH for yellow, LOW for green, HIGH for yellow2
    printf("Green light ON\n");
    gpioDelay(10000000); // 10 seconds
}

// Function to turn on the yellow light and turn off others
void yellow_light() {
    set_traffic_light_state(1, 1, 1, 0); // HIGH for red, HIGH for yellow, HIGH for green, LOW for yellow2
    printf("Yellow light ON\n");
    gpioDelay(3000000); // 3 seconds
}

// Function to cleanup GPIO pins and terminate the pigpio library
void cleanup_gpio() {
    printf("Cleaning up GPIO and terminating pigpio...\n");
    gpioTerminate();
}

// Signal handler function to catch SIGINT and SIGTERM signals
void signal_handler(int signal) {
    printf("Caught signal %d. Terminating program...\n", signal);
    program_running = 0;
