#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define ELECTRODE_0_TOUCH_STATUS 0x00
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define TOUCH_STATUS_READ_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int initialize_gpio();
int read_touch_status(uint16_t *touch_status);
int debounce_touch_event(int *debounced_state);
int toggle_relay();
void log_message(const char *message);
void signal_handler(int signal);

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Error opening I2C bus");
        return -1;
    }
    log_message("I2C bus initialized successfully");
    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        log_message("Error setting GPIO mode");
        return -1;
    }
    gpioWrite(RELAY_GPIO, 0); // Set relay to LOW initially
    log_message("GPIO initialized successfully");
    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, ELECTRODE_0_TOUCH_STATUS, buf, 2);
    if (result != 2) {
        log_message("Error reading touch status");
        return -1;
    }
    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to debounce touch events
int debounce_touch_event(int *debounced_state) {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay for debouncing
    uint16_t touch_status;
    if (read_touch_status(&touch_status) != 0) {
        return -1; // Error reading touch status
    }
    if ((touch_status & 0x01) && !(*debounced_state)) {
        *debounced_state = 1;
        return 1; // Touch detected
    } else if (!(touch_status & 0x01) && (*debounced_state)) {
        *debounced_state = 0;
        return 0; // Touch released
    } else {
        return 0; // No change
    }
}

// Function to toggle the relay
int toggle_relay() {
    int current_state = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_state);
    char message[100];
    sprintf(message, "Relay toggled to %d", !current_state);
    log_message(message);
    return 0;
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_message("Signal received, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;
    int debounced_touch_state = 0;

    log_message("Program started");

    while (program_running) {
        if (read_touch_status(&touch_status) == 0) {
            if (debounce_touch_event(&debounced_touch_state) == 1) {
                toggle_relay();
            }
        }
        gpioDelay(TOUCH_STATUS_READ_DELAY_MS * 1000); // Delay for touch status read
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Set relay to LOW before exiting
    fclose(log_file);
    gpioTerminate();

    log_message("Program terminated");

    return 0;
}

