void activate_buzzer_led(int duration);
void log_flame_detection(int sensor1, int sensor2, int sensor3);
void signal_handler(int signal);
int setup_gpio(int gpio, int mode);
int cleanup_gpio(int gpio);

// Function to read the flame sensor
int read_flame_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to check for flame detection
int check_flame_detection(int sensor1, int sensor2, int sensor3) {
    int count = 0;
    if (sensor1 == 0) count++;
    if (sensor2 == 0) count++;
    if (sensor3 == 0) count++;

    return (count == FLAME_THRESHOLD);
}

// Function to activate buzzer and LED
void activate_buzzer_led(int duration) {
    if (gpioWrite(BUZZER, 1) < 0) {
        fprintf(stderr, "Error writing to BUZZER\n");
    }
    if (gpioWrite(LED, 1) < 0) {
        fprintf(stderr, "Error writing to LED\n");
    }
    gpioDelay(duration * 1000000); // Convert seconds to microseconds
    if (gpioWrite(BUZZER, 0) < 0) {
        fprintf(stderr, "Error writing to BUZZER\n");
    }
    if (gpioWrite(LED, 0) < 0) {
        fprintf(stderr, "Error writing to LED\n");
    }
}

// Function to log flame detection
void log_flame_detection(int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Flame Detected (S1:%d, S2:%d, S3:%d)\n", timestamp, sensor1, sensor2, sensor3);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to setup GPIO pin
int setup_gpio(int gpio, int mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error setting mode for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to cleanup GPIO pin
int cleanup_gpio(int gpio) {
    if (gpioSetMode(gpio, PI_INPUT) < 0) { // Set to input to disable output
        fprintf(stderr, "Error setting mode for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up GPIO pins
    if (setup_gpio(FLAME_SENSOR_1, PI_INPUT) < 0 ||
        setup_gpio(FLAME_SENSOR_2, PI_INPUT) < 0 ||
        setup_gpio(FLAME_SENSOR_3, PI_INPUT) < 0 ||
        setup_gpio(BUZZER, PI_OUTPUT) < 0 ||
        setup_gpio(LED, PI_OUTPUT) < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    int flame_count1 = 0;
    int flame_count2 = 0;
    int flame_count3 = 0;
    int last_state1 = 1; // Initialize to HIGH (1)
    int last_state2 = 1; // Initialize to HIGH (1)
    int last_state3 = 1; // Initialize to HIGH (1)

    // Main loop
    while (running) {
        int sensor1_value = read_flame_sensor(FLAME_SENSOR_1);
        int sensor2_value = read_flame_sensor(FLAME_SENSOR_2);
        int sensor3_value = read_flame_sensor(FLAME_SENSOR_3);

        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break;
        }

        // Debouncing
        if (sensor1_value != last_state1) {
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay in microseconds
            sensor1_value = read_flame_sensor(FLAME_SENSOR_1);
        }
        if (sensor2_value != last_state2) {
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay in microseconds
            sensor2_value = read_flame_sensor(FLAME_SENSOR_2);
        }
        if (sensor3_value != last_state3) {
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay in microseconds
            sensor3_value = read_flame_sensor(FLAME_SENSOR_3);
        }

        last_state1 = sensor1_value;
        last_state2 = sensor2_value;
        last_state3 = sensor3_value;

        // Update flame counts
        if (sensor1_value == 0) {
            flame_count1++;
        } else {
            flame_count1 = 0;
        }

        if (sensor2_value == 0) {
            flame_count2++;
        } else {
            flame_count2 = 0;
        }

        if (sensor3_value == 0) {
            flame_count3++;
        } else {
            flame_count3 = 0;
        }

        // Check for flame detection
        if (check_flame_detection(sensor1_value, sensor2_value, sensor3_value)) {
            log_flame_detection(sensor1_value, sensor2_value, sensor3_value);
            activate_buzzer_led(FLAME_DURATION);
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    cleanup_gpio(FLAME_SENSOR_1);
    cleanup_gpio(FLAME_SENSOR_2);
    cleanup_gpio(FLAME_SENSOR_3);
    cleanup_gpio(BUZZER);
    cleanup_gpio(LED);
    gpioTerminate();

    return 0;
}

