#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense interval
#define DISPENSE_INTERVAL_MS 1000

// Define dispense duration for each solenoid
#define SOLENOID_DURATION_MS (DISPENSE_INTERVAL_MS / 2)

// Define log file name
#define LOG_FILE "dispense_log.txt"

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int activate_solenoid(int pin, int duration_ms);
int deactivate_solenoid(int pin);
int log_event(int solenoid_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Shutting down gracefully...\n");
        program_running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    return 0;
}

// Activate a solenoid for a specified duration
int activate_solenoid(int pin, int duration_ms) {
    gpioWrite(pin, 1); // Activate solenoid (HIGH)
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    return 0;
}

