int log_event(int solenoid_pin, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, GPIO%d, %d\n", timestamp, solenoid_pin, duration_ms);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate solenoid 1
        if (activate_solenoid(SOLENOID_1_PIN, SOLENOID_DURATION_MS) != 0) {
            fprintf(stderr, "Error activating solenoid 1\n");
        } else {
            if (log_event(SOLENOID_1_PIN, SOLENOID_DURATION_MS) != 0) {
                fprintf(stderr, "Error logging event for solenoid 1\n");
            }
        }

        // Activate solenoid 2
        if (activate_solenoid(SOLENOID_2_PIN, SOLENOID_DURATION_MS) != 0) {
            fprintf(stderr, "Error activating solenoid 2\n");
        } else {
            if (log_event(SOLENOID_2_PIN, SOLENOID_DURATION_MS) != 0) {
                fprintf(stderr, "Error logging event for solenoid 2\n");
            }
        }

        // Deactivate both solenoids
        deactivate_solenoid(SOLENOID_1_PIN);
        deactivate_solenoid(SOLENOID_2_PIN);

        // Wait for the remaining half of the interval
        gpioDelay((DISPENSE_INTERVAL_MS - SOLENOID_DURATION_MS) * 1000); // Delay in microseconds
    }

    // Cleanup
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);
    gpioTerminate();

    printf("Pneumatic dispensing system stopped.\n");

    return 0;
}

