#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENABLE 24

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENABLE 25

// PID Constants
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Obstacle Avoidance
#define OBSTACLE_DISTANCE 20.0
#define OBSTACLE_SPEED 127

// Logging
#define LOG_FILE "balance_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void set_motor_speed(int motor_a_speed, int motor_b_speed);
void obstacle_avoidance();
void pid_control(float tilt_error, float *integral, float *previous_error, int *motor_a_speed, int *motor_b_speed);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Logging function
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Motor control function
void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    if (motor_a_speed > 255) motor_a_speed = 255;
    if (motor_a_speed < -255) motor_a_speed = -255;
    if (motor_b_speed > 255) motor_b_speed = 255;
    if (motor_b_speed < -255) motor_b_speed = -255;

    gpioPWM(MOTOR_A_ENABLE, abs(motor_a_speed));
    gpioPWM(MOTOR_B_ENABLE, abs(motor_b_speed));

    if (motor_a_speed > 0) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
    } else if (motor_a_speed < 0) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
    } else {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 0);
    }

    if (motor_b_speed > 0) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
    } else if (motor_b_speed < 0) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
    } else {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 0);
    }
}

// Obstacle avoidance function
void obstacle_avoidance() {
    printf("Obstacle detected! Avoiding...\n");
    set_motor_speed(-OBSTACLE_SPEED, -OBSTACLE_SPEED);
    gpioDelay(500000); // 500ms
    set_motor_speed(0, 0);
    printf("Obstacle avoided.\n");
}

// PID control function
void pid_control(float tilt_error, float *integral, float *previous_error, int *motor_a_speed, int *motor_b_speed) {
    float proportional = KP * tilt_error;
    *integral += KI * tilt_error;
    float derivative = KD * (tilt_error - *previous_error);

    float output = proportional + *integral + derivative;

    // Map the output to motor speeds (adjust as needed)
    *motor_a_speed = (int)output;
    *motor_b_speed = (int)output;

    *previous_error = tilt_error;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    // Enable PWM
    gpioPWM(MOTOR_A_ENABLE, 0); // Start with 0 duty cycle
    gpioPWM(MOTOR_B_ENABLE, 0);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float tilt_error, distance;
    int motor_a_speed = 0, motor_b_speed = 0;
    float integral = 0, previous_error = 0;

    // Main loop
    while (running) {
        // Simulate sensor data
        tilt_error = ((float)rand() / RAND_MAX) * 20.0 - 10.0;
        distance = ((float)rand() / RAND_MAX) * 398.0 + 2.0;

        // Obstacle avoidance
        if (distance < OBSTACLE_DISTANCE) {
            obstacle_avoidance();
            motor_a_speed = 0;
            motor_b_speed = 0;
        } else {
            // PID control
            pid_control(tilt_error, &integral, &previous_error, &motor_a_speed, &motor_b_speed);
        }

        // Set motor speeds
        set_motor_speed(motor_a_speed, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay(50000); // 50ms
    }

    // Stop motors
    set_motor_speed(0, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

