    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    // Enable PWM
    gpioPWM(MOTOR_A_ENABLE, 0); // Start with 0 duty cycle
    gpioPWM(MOTOR_B_ENABLE, 0);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float tilt_error, distance;
    int motor_a_speed = 0, motor_b_speed = 0;
    float integral = 0, previous_error = 0;

    // Main loop
    while (running) {
        // Simulate sensor data
        tilt_error = ((float)rand() / RAND_MAX) * 20.0 - 10.0;
        distance = ((float)rand() / RAND_MAX) * 398.0 + 2.0;

        // Obstacle avoidance
        if (distance < OBSTACLE_DISTANCE) {
            obstacle_avoidance();
            motor_a_speed = 0;
            motor_b_speed = 0;
        } else {
            // PID control
            pid_control(tilt_error, &integral, &previous_error, &motor_a_speed, &motor_b_speed);
        }

        // Set motor speeds
        set_motor_speed(motor_a_speed, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay(50000); // 50ms
    }

    // Stop motors
    set_motor_speed(0, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

