void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
    // Turn off all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Release GPIO resources
    gpioTerminate();
    exit(0);
}

// Function to set the PWM duty cycle for a relay
void set_relay_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Invalid duty cycle value. Must be between 0 and 100.\n");
        return;
    }

    // Calculate the PWM range (adjust as needed for your hardware)
    int pwm_range = 1000; // Example: Adjust this value based on your pigpio configuration

    // Calculate the PWM value based on the duty cycle
    int pwm_value = (int)((duty_cycle / 100.0) * pwm_range);

    // Set the PWM value for the relay
    gpioPWM(gpio_pin, pwm_value);
}

