    gpioSetPWMfrequency(RELAY1_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(RELAY2_PIN, 1000);
    gpioSetPWMfrequency(RELAY3_PIN, 1000);
    gpioSetPWMfrequency(RELAY4_PIN, 1000);

