#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define VIDEO_DURATION_S 5
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_DIR "/home/pi/logs/"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function to handle SIGINT signal (Ctrl+C)
void sigint_handler(int signal) {
    program_running = 0;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor
    return 0;
}

// Function to generate a timestamp string in ISO 8601 format
int generate_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    if (strftime(timestamp_str, timestamp_str_size, "%Y%m%d_%H%M%S", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }
    return 0;
}

// Function to capture a video using raspivid
int capture_video(const char *timestamp) {
    char filename[256];
    snprintf(filename, sizeof(filename), "%s%s.h264", VIDEO_DIR, timestamp);

    char command[512];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, VIDEO_DURATION_S * 1000);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing raspivid command\n");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid command failed with exit status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Function to log a motion event to a file
int log_motion(const char *timestamp) {
    char log_filename[256];
    snprintf(log_filename, sizeof(log_filename), "%s%s.log", LOG_DIR, timestamp);

    log_file = fopen(log_filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);
    log_file = NULL; // Reset log_file after closing

    return 0;
}

// Function to debounce the sensor input
int debounce_sensor() {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    return 0;
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (gpioRead(GPIO_PIN) == 0) { // Sensor output is LOW when obstacle is detected
            char timestamp[32];
            if (generate_timestamp(timestamp, sizeof(timestamp)) == 0) {
                printf("Motion detected at %s\n", timestamp);

                if (capture_video(timestamp) == 0) {
                    printf("Video captured successfully\n");
                } else {
                    fprintf(stderr, "Video capture failed\n");
                }

                if (log_motion(timestamp) == 0) {
                    printf("Motion logged successfully\n");
                } else {
                    fprintf(stderr, "Motion logging failed\n");
                }

                debounce_sensor(); // Debounce the sensor
            } else {
                fprintf(stderr, "Timestamp generation failed\n");
            }
        }
        gpioDelay(50 * 1000); // Check every 50ms
    }

    // Cleanup
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Program terminated.\n");
    return 0;
}

