// Define GPIO pins for the relays
#define RELAY_ZONE1 4
#define RELAY_ZONE2 17
#define RELAY_ZONE3 27
#define RELAY_ZONE4 22

// Moisture threshold
#define MOISTURE_THRESHOLD 30

// Log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
FILE *log_file = NULL;
int pigpio_initialized = 0;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
void control_relay(int zone, int moisture_level);
void log_data(int moisture_level, int relay1_state, int relay2_state, int relay3_state, int relay4_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Deactivate all relays
    gpioWrite(RELAY_ZONE1, 1);
    gpioWrite(RELAY_ZONE2, 1);
    gpioWrite(RELAY_ZONE3, 1);
    gpioWrite(RELAY_ZONE4, 1);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Terminate the pigpio library
    if (pigpio_initialized) {
        gpioTerminate();
        pigpio_initialized = 0;
    }

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }
    pigpio_initialized = 1;

    gpioSetMode(RELAY_ZONE1, PI_OUTPUT);
    gpioSetMode(RELAY_ZONE2, PI_OUTPUT);
    gpioSetMode(RELAY_ZONE3, PI_OUTPUT);
    gpioSetMode(RELAY_ZONE4, PI_OUTPUT);

    // Initialize relays to OFF (HIGH)
    gpioWrite(RELAY_ZONE1, 1);
    gpioWrite(RELAY_ZONE2, 1);
    gpioWrite(RELAY_ZONE3, 1);
    gpioWrite(RELAY_ZONE4, 1);

    return 0; // Indicate success
}

// Read moisture sensor (simulated)
int read_moisture_sensor() {
    return rand() % 101; // Returns a random integer between 0 and 100
}

// Control relay based on moisture level
void control_relay(int zone, int moisture_level) {
    int relay_state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1; // 0 for ON, 1 for OFF
    gpioWrite(zone, relay_state);
}

// Log data to file
void log_data(int moisture_level, int relay1_state, int relay2_state, int relay3_state, int relay4_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
            timestamp,
            moisture_level,
            (relay1_state == 0) ? "ON" : "OFF",
            (relay2_state == 0) ? "ON" : "OFF",
            (relay3_state == 0) ? "ON" : "OFF",
            (relay4_state == 0) ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read moisture sensor
        int moisture_level = read_moisture_sensor();

        // Control relays
        control_relay(RELAY_ZONE1, moisture_level);
        control_relay(RELAY_ZONE2, moisture_level);
        control_relay(RELAY_ZONE3, moisture_level);
        control_relay(RELAY_ZONE4, moisture_level);

        // Log data
        log_data(moisture_level, gpioRead(RELAY_ZONE1), gpioRead(RELAY_ZONE2), gpioRead(RELAY_ZONE3), gpioRead(RELAY_ZONE4));

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    return 0;
}

