#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define MAX_DISTANCE 400.0 // Maximum measurable distance in cm
#define TIMEOUT_MS 100      // Timeout for echo pulse in milliseconds
#define MAX_PULSE_WIDTH 23200 // Maximum pulse width in microseconds

// Global variables
static volatile unsigned int start_tick = 0;
static volatile unsigned int end_tick = 0;
static volatile int echo_received = 0;
static volatile int timeout_flag = 0;
static FILE *log_file = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_rising_edge_callback(int gpio, int level, unsigned int tick, void *user_data);
void echo_falling_edge_callback(int gpio, int level, unsigned int tick, void *user_data);
void *log_distance(void *arg);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for rising edge of the ECHO signal
void echo_rising_edge_callback(int gpio, int level, unsigned int tick, void *user_data) {
    (void)gpio; (void)level; (void)user_data; // unused parameters
    pthread_mutex_lock(&mutex);
    start_tick = tick;
    echo_received = 1;
    pthread_mutex_unlock(&mutex);
}

// Callback function for falling edge of the ECHO signal
void echo_falling_edge_callback(int gpio, int level, unsigned int tick, void *user_data) {
    (void)gpio; (void)level; (void)user_data; // unused parameters
    pthread_mutex_lock(&mutex);
    end_tick = tick;
    echo_received = 1;
    timeout_flag = 0; // Reset timeout flag
    pthread_mutex_unlock(&mutex);
}

// Function to log the distance to a file
void *log_distance(void *arg) {
    (void)arg; // unused parameter
    while (running) {
        gpioDelay(100); // Check every 100ms

        pthread_mutex_lock(&mutex);
        if (echo_received) {
            unsigned int pulse_width = end_tick - start_tick;
            if (pulse_width > MAX_PULSE_WIDTH) {
                fprintf(stderr, "Error: Pulse width exceeds maximum limit (%u us)\n", pulse_width);
                echo_received = 0; // Reset flag
                pthread_mutex_unlock(&mutex);
                continue;
            }

            // Calculate distance in centimeters
            float distance = (float)pulse_width * 0.0343 / 2.0;

            // Get current timestamp in nanoseconds
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            unsigned int timestamp_ns = (unsigned int)(ts.tv_sec * 1000000000 + ts.tv_nsec);

            // Log the data to the file
            fprintf(log_file, "%u,%f\n", timestamp_ns, distance);
            fflush(log_file); // Ensure data is written to disk

            echo_received = 0; // Reset flag
            end_tick = 0;       // Reset end tick
            start_tick = 0;     // Reset start tick
            pthread_mutex_unlock(&mutex);
        } else if (timeout_flag) {
            // Log timeout error
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            unsigned int timestamp_ns = (unsigned int)(ts.tv_sec * 1000000000 + ts.tv_nsec);
            fprintf(log_file, "%u,Timeout\n", timestamp_ns);
            fflush(log_file);
            echo_received = 0; // Reset flag
            timeout_flag = 0;   // Reset timeout flag
            pthread_mutex_unlock(&mutex);
        } else {
            pthread_mutex_unlock(&mutex);
        }
    }
    return NULL;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // unused parameter
    printf("\nCaught signal, exiting gracefully...\n");
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt callbacks
    gpioSetAlertFuncEx(ECHO_PIN, echo_rising_edge_callback, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, echo_falling_edge_callback, NULL);

    // Create a thread to log the distance
    pthread_t log_thread;
    if (pthread_create(&log_thread, NULL, log_distance, NULL) != 0) {
        fprintf(stderr, "Error creating log thread!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        trigger_pulse();
        timeout_flag = 1; // Set timeout flag
        gpioDelay(TIMEOUT_MS * 1000); // Wait for timeout
    }

    // Clean up
    pthread_join(log_thread, NULL);
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&mutex);

    return 0;
}

