#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define BUZZER_GPIO 17
#define FREE_FALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 1.5f
#define G_PER_LSB 0.001f // 1mg

// LIS3DH Registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_lis3dh();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void activate_buzzer();
void signal_handler(int signal);

// Structure for configuration
typedef struct {
    float free_fall_threshold;
    float impact_threshold;
} Config;

Config config = {FREE_FALL_THRESHOLD, IMPACT_THRESHOLD};

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        config.free_fall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        config.impact_threshold = atof(argv[2]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() != 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure buzzer GPIO
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    float x, y, z;
    float magnitude;
    int free_fall_detected = 0;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Detect free fall
            if (magnitude < config.free_fall_threshold && !free_fall_detected) {
                printf("Free fall detected!\n");
                free_fall_detected = 1;
            }

            // Detect impact
            if (free_fall_detected && magnitude > config.impact_threshold) {
                printf("Impact detected!\n");
                activate_buzzer();
                free_fall_detected = 0; // Reset free fall state after impact
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        gpioDelay(10); // Delay for 10ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize LIS3DH
int init_lis3dh() {
    // Enable all axes and set data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return -1;
    }

    // Set full-scale range to +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) == 6) {
            // Combine high and low bytes, convert to signed 16-bit integer
            int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
            int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
            int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

            // Convert to g units
            *x = (float)x_raw * G_PER_LSB;
            *y = (float)y_raw * G_PER_LSB;
            *z = (float)z_raw * G_PER_LSB;

            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed, retrying...\n");
            gpioDelay(1); // Small delay before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read acceleration data after multiple retries\n");
    return -1; // Failure
}

// Calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Activate buzzer for 1 second
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Turn on buzzer
    gpioDelay(1000);           // Wait for 1 second
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

