#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3DH I2C address (default)
#define LIS3DH_ADDR_DEFAULT 0x18

// LIS3DH register addresses
#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

// Global variables
int i2c_handle;
int i2c_address = LIS3DH_ADDR_DEFAULT;
float threshold = 2.0;
FILE *log_file = NULL;

// Function prototypes
int init_lis3dh(int i2c_handle, int i2c_address);
int read_acceleration(int i2c_handle, int i2c_address, float *x, float *y, float *z);
void log_acceleration(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize LIS3DH sensor
int init_lis3dh(int i2c_handle, int i2c_address) {
    // Configure CTRL_REG1: 100 Hz ODR, enable all axes
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: ±2g range, high-resolution mode
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL4, 0x08) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from LIS3DH sensor
int read_acceleration(int i2c_handle, int i2c_address, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    // Read 6 bytes of acceleration data (X_L, X_H, Y_L, Y_H, Z_L, Z_H)
    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_REG_OUT_X_L, buffer, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = 0.0; *y = 0.0; *z = 0.0;
        return -1;
    }

    // Combine high and low bytes to form 16-bit signed integers
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to g units (assuming ±2g range and 12-bit resolution)
    *x = (float)raw_x / 16384.0;
    *y = (float)raw_y / 16384.0;
    *z = (float)raw_z / 16384.0;

    return 0;
}

// Log acceleration data to file
void log_acceleration(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
    fprintf(stderr, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g\n", timestamp, x, y, z);
    system("sudo shutdown -h now");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address != 0x18 && i2c_address != 0x19) {
                    fprintf(stderr, "Error: Invalid I2C address. Must be 0x18 or 0x19.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0) {
                    fprintf(stderr, "Error: Threshold must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH sensor
    if (init_lis3dh(i2c_handle, i2c_address) < 0) {
        fprintf(stderr, "Error initializing LIS3DH sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/high_acceleration.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (1) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, i2c_address, &x, &y, &z) == 0) {
            // Check if any axis exceeds the threshold
            if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
                log_acceleration(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

