    // Convert raw values to g units (assuming ±2g range and 12-bit resolution)
    *x = (float)raw_x / 16384.0;
    *y = (float)raw_y / 16384.0;
    *z = (float)raw_z / 16384.0;

    return 0;
}

// Log acceleration data to file
void log_acceleration(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
    fprintf(stderr, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g\n", timestamp, x, y, z);
    system("sudo shutdown -h now");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address != 0x18 && i2c_address != 0x19) {
                    fprintf(stderr, "Error: Invalid I2C address. Must be 0x18 or 0x19.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0) {
                    fprintf(stderr, "Error: Threshold must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH sensor
    if (init_lis3dh(i2c_handle, i2c_address) < 0) {
        fprintf(stderr, "Error initializing LIS3DH sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/high_acceleration.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (1) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, i2c_address, &x, &y, &z) == 0) {
            // Check if any axis exceeds the threshold
            if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
                log_acceleration(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

