    printf("Motor: Forward\n");
}

void motor_left() {
    printf("Motor: Left\n");
}

void motor_right() {
    printf("Motor: Right\n");
}

void motor_stop() {
    printf("Motor: Stop\n");
}

// Define circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Initialize circular buffer
void circular_buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add data to circular buffer
void circular_buffer_add(CircularBuffer *cb, int data) {
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get data from circular buffer
int circular_buffer_get(CircularBuffer *cb, int index) {
    if (index < 0 || index >= cb->count) {
        return -1; // Invalid index
    }
    int actual_index = (cb->head - cb->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    return cb->buffer[actual_index];
}

