#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define RELAY_GPIO 17
#define MAGNETIC_FIELD_THRESHOLD 5.0f
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 5
#define POLL_INTERVAL_US 1000 // 1 ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_magnetic_field(float *magnetic_field);
void control_relay(int state);
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int si7210_address;
    int relay_gpio;
    float magnetic_field_threshold;
    int sample_interval_ms;
} Config;

Config config = {
    I2C_BUS,
    SI7210_ADDR,
    RELAY_GPIO,
    MAGNETIC_FIELD_THRESHOLD,
    SAMPLE_INTERVAL_MS
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    float magnetic_field;
    int relay_state = 0; // 0 = off, 1 = on

    // Main loop
    while (program_running) {
        // Read magnetic field
        if (read_magnetic_field(&magnetic_field) == 0) {
            // Check if magnetic field exceeds threshold
            if (magnetic_field > config.magnetic_field_threshold) {
                // Activate relay
                if (relay_state == 0) {
                    control_relay(1);
                    relay_state = 1;
                    log_event("Relay State Change", "Relay activated");
                }
            } else {
                // Deactivate relay
                if (relay_state == 1) {
                    control_relay(0);
                    relay_state = 0;
                    log_event("Relay State Change", "Relay deactivated");
                }
            }

            // Log magnetic field reading
            char timestamp[32];
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Magnetic Field: %.2f mT", magnetic_field);
            log_event("Magnetic Field Reading", log_message);
        } else {
            fprintf(stderr, "Failed to read magnetic field\n");
        }

        // Wait for the next sample
        gpioDelay(config.sample_interval_ms * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.si7210_address, 0);
    if (i2c_handle < 0) {
        log_event("I2C Error", "Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Read magnetic field from Si7210
int read_magnetic_field(float *magnetic_field) {
    char buf[2];
    int result;
    int retries = 0;

    // Read two bytes from the sensor
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Convert the two bytes to a signed 16-bit integer
            int16_t raw_value = (buf[0] << 8) | buf[1];

            // Convert the raw value to milliTesla (mT) - Example conversion, adjust as needed
            *magnetic_field = (float)raw_value * 0.1f; // Example scaling factor

            return 0; // Success
        } else {
            char error_message[64];
            snprintf(error_message, sizeof(error_message), "I2C read failed (attempt %d): %d", retries + 1, result);
            log_event("I2C Error", error_message);
            retries++;
            gpioDelay(POLL_INTERVAL_US); // Wait before retrying
        }
    }

    // Timeout after MAX_RETRIES
    log_event("I2C Error", "Timeout reading from I2C device");
    return -1; // Failure
}

// Control the relay
void control_relay(int state) {
    gpioWrite(config.relay_gpio, state);
}

// Log an event to the log file
void log_event(const char *event_type, const char *message) {
    char timestamp[32];
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s [%s] %s\n", timestamp, event_type, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    // Deactivate relay
    control_relay(0);

    // Close I2C
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

