#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define POLLING_INTERVAL_MS 100

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int crc8(const uint8_t *data, size_t len);
int read_sensor(int i2c_handle, float *flow_rate);
void control_relay(int gpio_pin, int state);
void log_flow_data(float flow1, float flow2);
void signal_handler(int signal);
int setup();
void cleanup();

// CRC-8 calculation function
int crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from a sensor
int read_sensor(int i2c_handle, float *flow_rate) {
    uint8_t buffer[3];
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buffer, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "Error: I2C read failed (bytes read: %d)\n", bytes_read);
        return -1;
    }

    // CRC check
    uint8_t crc = crc8(buffer, 2);
    if (crc != buffer[2]) {
        fprintf(stderr, "Error: CRC check failed\n");
        return -1;
    }

    // Convert raw data to flow rate (example conversion, adjust as needed)
    uint16_t raw_flow = (buffer[0] << 8) | buffer[1];
    *flow_rate = (float)raw_flow / 100.0; // Example scaling factor

    return 0;
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log flow data to a file
void log_flow_data(float flow1, float flow2) {
    FILE *fp = fopen("flow_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open flow_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fflush(fp);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup function to initialize pigpio and I2C
int setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error: Could not open I2C device for sensor 1 (handle: %d)\n", i2c_handle1);
        gpioTerminate();
        return -1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error: Could not open I2C device for sensor 2 (handle: %d)\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return -1;
    }

    // Start measurement command (example, adjust as needed)
    char start_cmd[2] = {0x36, 0x08};
    if (i2cWriteDevice(i2c_handle1, start_cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send start measurement command to sensor 1\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return -1;
    }
    if (i2cWriteDevice(i2c_handle2, start_cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send start measurement command to sensor 2\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    gpioWrite(RELAY_GPIO, 0); // De-energize relay
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup() != 0) {
        fprintf(stderr, "Setup failed, exiting\n");
        return 1;
    }

    float flow1, flow2;

    while (!terminate) {
        if (read_sensor(i2c_handle1, &flow1) == 0 && read_sensor(i2c_handle2, &flow2) == 0) {
            log_flow_data(flow1, flow2);

            if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
                control_relay(RELAY_GPIO, 1); // Energize relay
            } else {
                control_relay(RELAY_GPIO, 0); // De-energize relay
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data, skipping relay control\n");
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpio delay in microseconds
    }

    cleanup();
    fprintf(stderr, "Program terminated gracefully\n");
    return 0;
}

