#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control parameters
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 2
#define MOTOR_STOP 0

// Define rain detection parameters
#define RAIN_DETECTED 0
#define RAIN_NOT_DETECTED 1
#define RAIN_CONFIRMED 3

// Global variables
static volatile int running = 1;
static int rain_state = RAIN_NOT_DETECTED;
static int consecutive_dry_polls = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int direction);
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Ensure motor is stopped initially
    gpioWrite(MOTOR_ENA_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);

    return 0;
}

// Function to read the rain sensor
int read_rain_sensor() {
    int sensor_value = gpioRead(RAIN_SENSOR_PIN);
    if (sensor_value < 0) {
        syslog(LOG_ERR, "Failed to read rain sensor");
        return -1;
    }
    return sensor_value;
}

// Function to control the motor
int control_motor(int direction) {
    int result = 0;
    switch (direction) {
        case MOTOR_FORWARD:
            result = gpioWrite(MOTOR_ENA_PIN, 1);
            gpioWrite(MOTOR_IN1_PIN, 1);
            gpioWrite(MOTOR_IN2_PIN, 0);
            break;
        case MOTOR_REVERSE:
            result = gpioWrite(MOTOR_ENA_PIN, 1);
            gpioWrite(MOTOR_IN1_PIN, 0);
            gpioWrite(MOTOR_IN2_PIN, 1);
            break;
        case MOTOR_STOP:
            result = gpioWrite(MOTOR_ENA_PIN, 0);
            gpioWrite(MOTOR_IN1_PIN, 0);
            gpioWrite(MOTOR_IN2_PIN, 0);
            break;
        default:
            syslog(LOG_ERR, "Invalid motor direction");
            return -1;
    }

    if (result != 0) {
        syslog(LOG_ERR, "Failed to write to motor control pins");
        return -1;
    }

    return 0;
}

// Function to log events to syslog
