#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define pulse widths
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int lock_door();
int unlock_door();
void handle_button_press(int button_pin, int pulse_width);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        program_running = 0;

        // Stop the servo
        if (gpioServo(SERVO_PIN, 0) != 0) {
            fprintf(stderr, "Error stopping servo.\n");
        }

        // Call the API call() function one final time
        if (gpioServo(SERVO_PIN, 0) != 0) {
            fprintf(stderr, "Error calling call() function.\n");
        }

        // Terminate the pigpio library
        gpioTerminate();

        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0;
}

// Lock the door
int lock_door() {
    printf("Locking door...\n");
    if (gpioServo(SERVO_PIN, LOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error locking door.\n");
        return 1;
    }
    return 0;
}

// Unlock the door
int unlock_door() {
    printf("Unlocking door...\n");
    if (gpioServo(SERVO_PIN, UNLOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error unlocking door.\n");
        return 1;
    }
    return 0;
}

// Handle button press
void handle_button_press(int button_pin, int pulse_width) {
    if (gpioRead(button_pin) == 0) { // Button is pressed (low signal)
        if (lock_door() != 0) {
            fprintf(stderr, "Error locking door.\n");
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay

        while (gpioRead(button_pin) == 0) {
            gpioDelay(1000); // Wait for button release
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay

    } else if (gpioRead(button_pin) == 1) {
        if (unlock_door() != 0) {
            fprintf(stderr, "Error unlocking door.\n");
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay

        while (gpioRead(button_pin) == 1) {
            gpioDelay(1000); // Wait for button release
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        handle_button_press(LOCK_BUTTON_PIN, LOCK_PULSE_WIDTH);
        handle_button_press(UNLOCK_BUTTON_PIN, UNLOCK_PULSE_WIDTH);
        gpioDelay(10000); // Check buttons every 10ms
    }

    return 0;
}

