// Define GPIO pins
#define PIR_PIN 4
#define FLOODLIGHT_PIN 17

// Define log file name
#define LOG_FILE "security_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_floodlight(int state);
int log_event(const char *event_type, const char *timestamp, int duration);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT);

    return 0;
}

// Function to read PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Function to control floodlight
int control_floodlight(int state) {
    gpioWrite(FLOODLIGHT_PIN, state);
    return 0;
}

// Function to log events
int log_event(const char *event_type, const char *timestamp, int duration) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    if (fprintf(log_file, "%s - %s - Duration: %d seconds\n", event_type, timestamp, duration) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    control_floodlight(0); // Turn off floodlight

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate(); // Terminate pigpio
        return 1;
    }

    printf("Security system started. Press Ctrl+C to exit.\n");

    int floodlight_on = 0;
    time_t start_time = 0;

    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            if (!floodlight_on) {
                // Motion detected, turn on floodlight
                char* timestamp = get_iso8601_timestamp();
                if (log_event("Motion Detected", timestamp, 0) != 0) {
                    running = 0; // Exit if logging fails
                }
                free(timestamp);
                control_floodlight(1);
                floodlight_on = 1;
                start_time = time(NULL);
            }
        } else if (floodlight_on) {
            // Floodlight is on, check if 60 seconds have passed
            time_t current_time = time(NULL);
            if (difftime(current_time, start_time) >= 60) {
                // 60 seconds have passed, turn off floodlight
                char* timestamp = get_iso8601_timestamp();
                if (log_event("Floodlight Deactivated", timestamp, 60) != 0) {
                    running = 0; // Exit if logging fails
                }
                free(timestamp);
                control_floodlight(0);
                floodlight_on = 0;
            }
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_floodlight(0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

