#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>
#include <errno.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define BUFFER_SIZE 1024

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int socket_fd = -1;
FILE *log_file = NULL;

// Function prototypes
void log_event(const char *format, ...);
int set_servo_angle(int angle);
int read_pir_sensor();
void handle_client(int client_socket);
void signal_handler(int signal);
int setup();
void cleanup();

// Logging function
void log_event(const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Log to syslog
    syslog(LOG_USER, format, args);

    // Log to file
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

        fprintf(log_file, "%s ", buf);
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }

    va_end(args);
}

// Servo control function
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_event("Invalid servo angle: %d", angle);
        return -1;
    }

    // Calculate pulse width (1ms - 2ms for 0-180 degrees)
    int pulse_width = 1000 + (int)((float)angle / 180.0 * 1000.0);

    gpioServo(SERVO_PIN, pulse_width);
    log_event("Servo angle set to: %d, pulse width: %d", angle, pulse_width);
    return 0;
}

// PIR sensor reading function
int read_pir_sensor() {
    int pir_value = gpioRead(PIR_PIN);
    if (pir_value == PI_BAD_GPIO) {
        log_event("Error reading PIR sensor");
        return -1;
    }
    return pir_value;
}

// Client handling function
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        log_event("Received command: %s", buffer);

        if (strncmp(buffer, "PIR", 3) == 0) {
            int pir_value = read_pir_sensor();
            if (pir_value == -1) {
                send(client_socket, "PIR:ERROR\n", strlen("PIR:ERROR\n"), 0);
            } else {
                char response[10];
                snprintf(response, sizeof(response), "PIR:%d\n", pir_value);
                send(client_socket, response, strlen(response), 0);
            }
        } else if (strncmp(buffer, "angle", 5) == 0) {
            int angle;
            if (sscanf(buffer, "angle %d", &angle) == 1) {
                if (set_servo_angle(angle) == 0) {
                    send(client_socket, "OK\n", strlen("OK\n"), 0);
                } else {
                    send(client_socket, "ERROR\n", strlen("ERROR\n"), 0);
                }
            } else {
                send(client_socket, "ERROR: Invalid angle format\n", strlen("ERROR: Invalid angle format\n"), 0);
            }
        } else {
            send(client_socket, "ERROR: Invalid command\n", strlen("ERROR: Invalid command\n"), 0);
        }
    }

    if (bytes_received < 0) {
        log_event("Error receiving data: %s", strerror(errno));
    }

    close(client_socket);
    log_event("Client disconnected");
}

// Signal handler function
void signal_handler(int signal) {
    log_event("Signal received: %d. Terminating...", signal);
    terminate = 1;
}

// Setup function
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("security.log", "a");
    if (log_file == NULL) {
        log_event("Error opening log file: %s", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        log_event("Error creating socket: %s", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return -1;
    }

    // Bind socket
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(socket_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_event("Error binding socket: %s", strerror(errno));
        close(socket_fd);
        fclose(log_file);
        gpioTerminate();
        return -1;
    }

    // Listen for connections
    if (listen(socket_fd, 3) < 0) {
        log_event("Error listening on socket: %s", strerror(errno));
        close(socket_fd);
        fclose(log_file);
        gpioTerminate();
        return -1;
    }

    log_event("Server listening on port %d", PORT);
    return 0;
}

// Cleanup function
void cleanup() {
    log_event("Cleaning up resources...");

    // Close socket
    if (socket_fd != -1) {
        close(socket_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    log_event("Cleanup complete. Exiting.");
}

int main() {
    openlog("security_server", LOG_PID | LOG_CONS, LOG_USER);

    if (setup() != 0) {
        closelog();
        return 1;
    }

    struct sockaddr_in client_address;
    socklen_t client_address_len = sizeof(client_address);

    log_event("Server started");

    while (!terminate) {
        int client_socket = accept(socket_fd, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            log_event("Error accepting connection: %s", strerror(errno));
            continue; // Continue listening for connections
        }

        log_event("Connection accepted from %s:%d", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));
        handle_client(client_socket);
    }

    cleanup();
    closelog();
    return 0;
}

