    terminate = 1;
}

// Setup function
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("security.log", "a");
    if (log_file == NULL) {
        log_event("Error opening log file: %s", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        log_event("Error creating socket: %s", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return -1;
    }

    // Bind socket
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(socket_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_event("Error binding socket: %s", strerror(errno));
        close(socket_fd);
        fclose(log_file);
        gpioTerminate();
        return -1;
    }

    // Listen for connections
    if (listen(socket_fd, 3) < 0) {
        log_event("Error listening on socket: %s", strerror(errno));
        close(socket_fd);
        fclose(log_file);
        gpioTerminate();
        return -1;
    }

    log_event("Server listening on port %d", PORT);
    return 0;
}

// Cleanup function
void cleanup() {
    log_event("Cleaning up resources...");

    // Close socket
    if (socket_fd != -1) {
        close(socket_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    log_event("Cleanup complete. Exiting.");
}

int main() {
    openlog("security_server", LOG_PID | LOG_CONS, LOG_USER);

    if (setup() != 0) {
        closelog();
        return 1;
    }

    struct sockaddr_in client_address;
    socklen_t client_address_len = sizeof(client_address);

    log_event("Server started");

    while (!terminate) {
        int client_socket = accept(socket_fd, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            log_event("Error accepting connection: %s", strerror(errno));
            continue; // Continue listening for connections
        }

        log_event("Connection accepted from %s:%d", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));
        handle_client(client_socket);
    }

    cleanup();
    closelog();
    return 0;
}

