    while (!terminate) {
        retry_count = 0;
        while (retry_count < I2C_RETRY_COUNT) {
            if (read_bh1750(&lux) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)\n", retry_count + 1, I2C_RETRY_COUNT);
                gpioDelay(100); // Wait before retrying
                retry_count++;
