#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200

// Global variables
static volatile int running = 1;
static double tare_value = 0.0;
static double scale_factor = DEFAULT_SCALE;
static int duration_ms = DEFAULT_DURATION;
static double weight_threshold = DEFAULT_THRESHOLD;

// Function prototypes
int read_hx711();
double average_readings(int num_readings);
double calculate_weight(int raw_value);
void activate_solenoid();
void deactivate_solenoid();
void signal_handler(int signal);
int tare_load_cell();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    running = 0;
    deactivate_solenoid();
    gpioTerminate();
    closelog();
    exit(0);
}

// Function to read a single value from the HX711
int read_hx711() {
    int i;
    unsigned long data = 0;

    // Wait for DOUT to go low
    int timeout = 1000; // Timeout after 1 second (1000 ms)
    while (gpioRead(HX711_DOUT) == 1 && timeout > 0) {
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        syslog(LOG_ERR, "HX711 DOUT timeout");
        return -1; // Indicate error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Apply the 25th clock pulse to select channel A, gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return (int)data;
}

// Function to average multiple readings
double average_readings(int num_readings) {
    int i;
    double sum = 0.0;
    int raw_value;

    for (i = 0; i < num_readings; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            syslog(LOG_ERR, "Error reading HX711, skipping reading");
            continue; // Skip this reading
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    return sum / num_readings;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value) {
    return (double)(raw_value - tare_value) / scale_factor;
}

// Function to activate the solenoid lock
void activate_solenoid() {
    gpioWrite(SOLENOID_PIN, 1);
    gpioDelay(duration_ms);
    gpioWrite(SOLENOID_PIN, 0);
}

// Function to deactivate the solenoid lock
void deactivate_solenoid() {
    gpioWrite(SOLENOID_PIN, 0);
}

// Function to tare the load cell
int tare_load_cell() {
    int i;
    double sum = 0.0;
    int raw_value;

    syslog(LOG_INFO, "Starting tare sequence...");
    for (i = 0; i < 10; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            syslog(LOG_ERR, "Error reading HX711 during tare, skipping reading");
            continue; // Skip this reading
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    tare_value = sum / 10.0;
    syslog(LOG_INFO, "Tare value: %lf", tare_value);
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                weight_threshold = atof(optarg);
                break;
            case 's':
                scale_factor = atof(optarg);
                break;
            case 'd':
                duration_ms = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration]\n", argv[0]);
                closelog();
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Tare the load cell
    if (tare_load_cell() != 0) {
        syslog(LOG_ERR, "Tare sequence failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        double weight = calculate_weight((int)average_readings(5));
        syslog(LOG_INFO, "Weight: %lf grams", weight);

        if (weight > weight_threshold) {
            syslog(LOG_INFO, "Weight exceeds threshold, activating solenoid");
            activate_solenoid();
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup
    deactivate_solenoid();
    gpioTerminate();
    closelog();

    return 0;
}

