#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17
#define MAX_PAYLOAD_SIZE 64

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Set relay to OFF (LOW)
    return 0;
}

// Function to set the relay state
void set_relay_state(int state) {
    gpioWrite(GPIO_PIN, state);
}

// Callback function for MQTT messages
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "ON") == 0) {
            set_relay_state(1); // Relay ON
            log_message(LOG_INFO, "Relay ON");
        } else if (strcmp(payload, "OFF") == 0) {
            set_relay_state(0); // Relay OFF
            log_message(LOG_INFO, "Relay OFF");
        } else {
            log_message(LOG_ERR, "Invalid payload received");
        }
    } else {
        log_message(LOG_ERR, "Empty payload received");
    }
}

// Callback function for MQTT connection
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "MQTT connected");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_message(LOG_ERR, "MQTT connection error");
    }
}

// Callback function for MQTT disconnection
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_message(LOG_WARNING, "MQTT disconnected unexpectedly");
    } else {
        log_message(LOG_INFO, "MQTT disconnected");
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    running = 0;
    log_message(LOG_INFO, "Signal received, exiting...");
}

int main() {
    // Open syslog
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    // Initialize MQTT client
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create MQTT client");
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Connect to MQTT broker
    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    // Start MQTT loop
    while (running) {
        rc = mosquitto_loop(mosq, -1, 1); // Blocking loop with a timeout
        if (rc != MOSQ_ERR_SUCCESS) {
            log_message(LOG_WARNING, "MQTT loop error, reconnecting...");
            sleep(5);
            mosquitto_reconnect(mosq);
        }
    }

    // Clean up
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

