#define SERVO3_PULSE_WIDTH 2000
#define SERVO4_PULSE_WIDTH 500
#define SERVO5_PULSE_WIDTH 2500

// Define the duration to hold each pulse (in seconds)
#define HOLD_DURATION 3

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(SERVO1_PIN, PI_OUTPUT);
    gpioSetMode(SERVO2_PIN, PI_OUTPUT);
    gpioSetMode(SERVO3_PIN, PI_OUTPUT);
    gpioSetMode(SERVO4_PIN, PI_OUTPUT);
    gpioSetMode(SERVO5_PIN, PI_OUTPUT);

    // Set PWM frequency to 50 Hz (20 ms period)
    gpioSetPWMfrequency(SERVO1_PIN, 50);
    gpioSetPWMfrequency(SERVO2_PIN, 50);
    gpioSetPWMfrequency(SERVO3_PIN, 50);
    gpioSetPWMfrequency(SERVO4_PIN, 50);
    gpioSetPWMfrequency(SERVO5_PIN, 50);

