    gpioPWM(SERVO4_PIN, SERVO4_PULSE_WIDTH);
    gpioPWM(SERVO5_PIN, SERVO5_PULSE_WIDTH);

    // Wait for the specified duration
    gpioDelay(HOLD_DURATION * 1000000); // Convert seconds to microseconds

    // Stop PWM signals
    gpioPWM(SERVO1_PIN, 0);
    gpioPWM(SERVO2_PIN, 0);
    gpioPWM(SERVO3_PIN, 0);
    gpioPWM(SERVO4_PIN, 0);
    gpioPWM(SERVO5_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

