#define PWM_FREQUENCY 10000 // 10 kHz
#define ENCODER_TICKS_PER_REVOLUTION 64.0
#define STALL_TIMEOUT_SECONDS 2.0

// PI Controller Gains
#define Kp 10.0
#define Ki 0.1

// Global variables (protected by mutex)
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;
pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
void motor_a_forward(int duty_cycle);
void motor_b_forward(int duty_cycle);
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int ticks);
double pi_control(double error);
void log_data(double rpm_a, double rpm_b, double duty_cycle_a, double duty_cycle_b, double error_a, double integral_a, double output_a, double error_b, double integral_b, double output_b);

// Structure to hold motor data
typedef struct {
    int pwm_pin;
    int dir_pin;
    int phase_a_pin;
    int phase_b_pin;
    int current_duty_cycle;
    double current_rpm;
    double integral;
    double last_error;
} Motor;

Motor motor_a, motor_b;

// Function to set motor direction
void set_motor_direction(Motor *motor, int direction) {
    gpioWrite(motor->dir_pin, direction);
}

// Function to set motor PWM duty cycle
void set_motor_pwm(Motor *motor, int duty_cycle) {
    gpioPWM(motor->pwm_pin, duty_cycle);
    motor->current_duty_cycle = duty_cycle;
}

// Function to calculate RPM
double calculate_rpm(int ticks) {
    return (double)ticks * 60.0 / ENCODER_TICKS_PER_REVOLUTION;
}

// PI controller function
double pi_control(double error) {
    static double integral = 0.0;
    static double last_error = 0.0;

    integral += error * 0.1; // 0.1 is the sample time (100ms)

    // Anti-windup clamping
    double output = Kp * error + Ki * integral;
    if (output > 255) {
        output = 255;
        integral = last_error * (255 / Kp); // Adjust integral to prevent windup
    } else if (output < 0) {
        output = 0;
        integral = last_error * (0 / Kp); // Adjust integral to prevent windup
    }

    last_error = error;
    return output;
}

// Function to log data to a file
void log_data(double rpm_a, double rpm_b, double duty_cycle_a, double duty_cycle_b, double error_a, double integral_a, double output_a, double error_b, double integral_b, double output_b) {
    FILE *fp = fopen("motor_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, RPM_A: %.2f, RPM_B: %.2f, Duty_A: %.2f, Duty_B: %.2f, Error_A: %.2f, Integral_A: %.2f, Output_A: %.2f, Error_B: %.2f, Integral_B: %.2f, Output_B: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            rpm_a, rpm_b, duty_cycle_a, duty_cycle_b, error_a, integral_a, output_a, error_b, integral_b, output_b);

    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, stopping motors...\n", signal);
    program_running = 0;
    set_motor_pwm(&motor_a, 0);
    set_motor_pwm(&motor_b, 0);
    gpioTerminate();
    exit(0);
}

// Motor forward function
void motor_forward(Motor *motor, int duty_cycle) {
    set_motor_direction(motor, 1); // Set direction to forward
    set_motor_pwm(motor, duty_cycle);
}

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    static int last_level_a = 0;
    static int last_level_b = 0;
    static int last_tick = 0;

    int level_a = gpioRead(ENCODER_A_PHASE_A);
    int level_b = gpioRead(ENCODER_A_PHASE_B);

    if (level_a != last_level_a || level_b != last_level_b) {
        if (level_a == level_b) {
            // Clockwise
            pthread_mutex_lock(&encoder_mutex);
            encoder_a_ticks++;
            pthread_mutex_unlock(&encoder_mutex);
        } else {
            // Counter-clockwise
            pthread_mutex_lock(&encoder_mutex);
            encoder_a_ticks--;
            pthread_mutex_unlock(&encoder_mutex);
        }
        last_level_a = level_a;
        last_level_b = level_b;
    }
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    static int last_level_a = 0;
    static int last_level_b = 0;
    static int last_tick = 0;

    int level_a = gpioRead(ENCODER_B_PHASE_A);
    int level_b = gpioRead(ENCODER_B_PHASE_B);

    if (level_a != last_level_a || level_b != last_level_b) {
        if (level_a == level_b) {
            // Clockwise
            pthread_mutex_lock(&encoder_mutex);
            encoder_b_ticks++;
            pthread_mutex_unlock(&encoder_mutex);
        } else {
            // Counter-clockwise
            pthread_mutex_lock(&encoder_mutex);
            encoder_b_ticks--;
            pthread_mutex_unlock(&encoder_mutex);
        }
        last_level_a = level_a;
        last_level_b = level_b;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(ENCODER_A_PHASE_A, PI_INPUT);
    gpioSetMode(ENCODER_A_PHASE_B, PI_INPUT);
    gpioSetMode(ENCODER_B_PHASE_A, PI_INPUT);
    gpioSetMode(ENCODER_B_PHASE_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Set pull-up/down resistors (optional, adjust as needed)
    gpioSetPullUpDown(ENCODER_A_PHASE_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_A_PHASE_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_PHASE_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_PHASE_B, PI_PUD_UP);

    // Initialize motors
    motor_a.pwm_pin = MOTOR_A_PWM;
    motor_a.dir_pin = MOTOR_A_DIR;
    motor_a.phase_a_pin = ENCODER_A_PHASE_A;
    motor_a.phase_b_pin = ENCODER_A_PHASE_B;
    motor_a.current_duty_cycle = 0;
    motor_a.current_rpm = 0.0;
    motor_a.integral = 0.0;
    motor_a.last_error = 0.0;

    motor_b.pwm_pin = MOTOR_B_PWM;
    motor_b.dir_pin = MOTOR_B_DIR;
    motor_b.phase_a_pin = ENCODER_B_PHASE_A;
    motor_b.phase_b_pin = ENCODER_B_PHASE_B;
    motor_b.current_duty_cycle = 0;
    motor_b.current_rpm = 0.0;
    motor_b.integral = 0.0;
    motor_b.last_error = 0.0;

    // Set up ISRs for encoders
    if (gpioSetISRFuncEx(ENCODER_A_PHASE_A, RISING_EDGE, 0, encoder_a_isr, NULL) < 0) {
        fprintf(stderr, "Error setting up ISR for Encoder A Phase A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_PHASE_B, RISING_EDGE, 0, encoder_a_isr, NULL) < 0) {
        fprintf(stderr, "Error setting up ISR for Encoder A Phase B\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_PHASE_A, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Error setting up ISR for Encoder B Phase A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_PHASE_B, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Error setting up ISR for Encoder B Phase B\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    time_t last_stall_check = time(NULL);

    // Main control loop
    while (program_running) {
        // Read encoder ticks
        pthread_mutex_lock(&encoder_mutex);
        int ticks_a = encoder_a_ticks;
        int ticks_b = encoder_b_ticks;
        encoder_a_ticks = 0;
        encoder_b_ticks = 0;
        pthread_mutex_unlock(&encoder_mutex);

        // Calculate RPM
        double rpm_a = calculate_rpm(ticks_a);
        double rpm_b = calculate_rpm(ticks_b);

        // Calculate error
        double error_a = TARGET_RPM - rpm_a;
        double error_b = TARGET_RPM - rpm_b;

        // PI control
        double output_a = pi_control(error_a);
        double output_b = pi_control(error_b);

        // Clamp PWM duty cycle
        if (output_a > 255) output_a = 255;
        if (output_a < 0) output_a = 0;
        if (output_b > 255) output_b = 255;
        if (output_b < 0) output_b = 0;

        // Set motor speeds
        motor_forward(&motor_a, (int)output_a);
        motor_forward(&motor_b, (int)output_b);

        // Stall detection
        time_t current_time = time(NULL);
        if (current_time - last_stall_check >= STALL_TIMEOUT_SECONDS) {
            pthread_mutex_lock(&encoder_mutex);
            int current_ticks_a = encoder_a_ticks;
            int current_ticks_b = encoder_b_ticks;
            pthread_mutex_unlock(&encoder_mutex);

            if (current_ticks_a == 0 && current_ticks_b == 0) {
                fprintf(stderr, "Warning: Motor stalled!\n");
            }
            last_stall_check = current_time;
        }

        // Log data
        log_data(rpm_a, rpm_b, motor_a.current_duty_cycle, motor_b.current_duty_cycle, error_a, motor_a.integral, output_a, error_b, motor_b.integral, output_b);

        // Print RPM and duty cycle
        printf("Motor A: RPM = %.2f, Duty Cycle = %.2f, Motor B: RPM = %.2f, Duty Cycle = %.2f\n", rpm_a, motor_a.current_duty_cycle, rpm_b, motor_b.current_duty_cycle);

        // Sleep for 100ms
        gpioDelay(100000); // 100ms
    }

    // Stop motors and terminate pigpio
    set_motor_pwm(&motor_a, 0);
    set_motor_pwm(&motor_b, 0);
    gpioTerminate();

    return 0;
}

