#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 17
#define LUX_DUSK 50
#define LUX_DAWN 200
#define LUX_HYSTERESIS 10
#define POLL_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int init_gpio();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO pin for relay control
int init_gpio() {
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initialize relay to OFF state
    return 0;
}

// Read light intensity from BH1750 sensor
int read_bh1750(float *lux) {
    char config_cmd[1] = {0x10}; // Continuous high resolution mode
    char buffer[2];
    int result;

    result = i2cWriteDevice(i2c_handle, config_cmd, 1);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }

    gpioDelay(180); // Wait for measurement (at least 180ms)

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2; // Convert to Lux

    return 0;
}

// Control the relay (ON/OFF)
int control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
    return 0;
}

// Log data to file
int log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int relay_state = 0; // 0 = OFF, 1 = ON
    float lux;

    printf("Chicken Coop Light Monitoring System started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read light intensity
        if (read_bh1750(&lux) == 0) {
            // Control relay based on lux value
            if (lux < LUX_DUSK && relay_state == 0) {
                control_relay(1); // Turn ON relay
                relay_state = 1;
                log_data(lux, relay_state);
            } else if (lux > LUX_DAWN && relay_state == 1) {
                control_relay(0); // Turn OFF relay
                relay_state = 0;
                log_data(lux, relay_state);
            } else {
                log_data(lux, relay_state);
            }
        } else {
            fprintf(stderr, "Failed to read lux value. Logging error.\n");
            fprintf(log_file, "ERROR: Failed to read lux value.\n");
            fflush(log_file);
            control_relay(0); // Ensure relay is OFF in case of error
            relay_state = 0;
        }

        gpioDelay(POLL_INTERVAL * 1000); // Wait for POLL_INTERVAL seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(0); // Turn OFF relay
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

