#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
static volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
int log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        running = 0;
        control_relay(0); // Turn off the relay
        gpioTerminate(); // Release GPIO resources
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Read the touch sensor value
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Control the relay state
int control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    return 0;
}

// Log the relay state with ISO 8601 timestamp
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s Relay: %s\n", buffer, state ? "ON" : "OFF");
    return 0;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int last_touch_state = 0;
    int current_touch_state = 0;
    int stable_touch_state = 0;
    int debounce_count = 0;

    printf("Touch-toggled relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        current_touch_state = read_touch_sensor();

        if (current_touch_state != last_touch_state) {
            gpioDelay(1); // Small delay for debouncing
            current_touch_state = read_touch_sensor(); // Re-read to confirm
            if (current_touch_state == last_touch_state) {
                last_touch_state = current_touch_state;
            }
        }

        if (last_touch_state == 1) {
            debounce_count++;
            if (debounce_count >= 5) { // 50ms delay (5 * 10ms)
                stable_touch_state = 1;
                debounce_count = 0;
            }
        } else {
            debounce_count = 0;
            stable_touch_state = 0;
        }

        if (stable_touch_state == 1 && last_touch_state == 0) {
            // Touch released, toggle relay state
            relay_state = !relay_state;
            control_relay(relay_state);
            log_relay_state(relay_state);
            stable_touch_state = 0; // Reset stable state
        }

        gpioDelay(10); // Main loop delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_relay(0);
    gpioTerminate();

    return 0;
}

