#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0 // YF-S201 sensor
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIME_MS 1000
#define LOG_FILE "water_flow.log"

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm();
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold program state
typedef struct {
    int solenoid_state;
} ProgramState;

ProgramState state = {1}; // Initialize solenoid to open (HIGH)

int main() {
    if (initialize() != 0) {
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        double lpm = calculate_lpm();
        control_solenoid(lpm);
        log_data(lpm, state.solenoid_state);
        gpioDelay(1000); // Sample every 1 second
    }

    cleanup();
    return 0;
}

// Initialize pigpio and other resources
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(SOLENOID_GPIO, PI_OUTPUT);

    // Set initial solenoid state to open (HIGH)
    gpioWrite(SOLENOID_GPIO, 1);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Set up ISR for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_TIME_MS, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Interrupt service routine for pulse counting
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; (void)user_data; // unused parameters
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Calculate liters per minute
double calculate_lpm() {
    pthread_mutex_lock(&pulse_mutex);
    int current_pulse_count = pulse_count;
    pulse_count = 0; // Reset pulse count after reading
    pthread_mutex_unlock(&pulse_mutex);

    return (double)current_pulse_count / PULSES_PER_LITER * 60.0; // LPM
}

// Control solenoid valve
void control_solenoid(double lpm) {
    if (lpm > LPM_THRESHOLD_HIGH && state.solenoid_state == 1) {
        gpioWrite(SOLENOID_GPIO, 0); // Close solenoid
        state.solenoid_state = 0;
        log_data(lpm, state.solenoid_state);
    } else if (lpm < LPM_THRESHOLD_LOW && state.solenoid_state == 0) {
        gpioWrite(SOLENOID_GPIO, 1); // Open solenoid
        state.solenoid_state = 1;
        log_data(lpm, state.solenoid_state);
    }
}

// Log data to file
void log_data(double lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(SOLENOID_GPIO, 1); // Ensure solenoid is open on exit
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
}

