#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <jansson.h>
#include <errno.h>

// Configuration
#define CONFIG_FILE "config.ini"
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVO_MIN_PULSE_WIDTH 1000
#define DEFAULT_SERVO_MAX_PULSE_WIDTH 2000
#define DEFAULT_SERVO_GPIO 18
#define DEFAULT_HX711_DATA_GPIO 23
#define DEFAULT_HX711_SCK_GPIO 24
#define DEFAULT_API_ENDPOINT "http://api.example.com/dispense"
#define DEFAULT_API_TIMEOUT 5 // seconds

// Global variables
static int hx711_data_gpio = DEFAULT_HX711_DATA_GPIO;
static int hx711_sck_gpio = DEFAULT_HX711_SCK_GPIO;
static int servo_gpio = DEFAULT_SERVO_GPIO;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static int servo_min_pulse_width = DEFAULT_SERVO_MIN_PULSE_WIDTH;
static int servo_max_pulse_width = DEFAULT_SERVO_MAX_PULSE_WIDTH;
static char *api_endpoint = DEFAULT_API_ENDPOINT;
static int api_timeout = DEFAULT_API_TIMEOUT;
static int socket_fd = -1;
static int client_socket = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config();
int read_hx711();
double calibrate_weight(double raw_value, double known_weight);
int map_weight_to_pulse_width(double target_weight);
int dispense(double target_weight);
int log_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);
int setup();
void cleanup();

// HX711 read function with timeout
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(hx711_data_gpio, PI_INPUT);
    gpioSetMode(hx711_sck_gpio, PI_OUTPUT);

    // Wait for data line to go low
    int timeout_count = 0;
    while (gpioRead(hx711_data_gpio) == 1 && timeout_count < 1000) {
        gpioDelay(1); // 1 us delay
        timeout_count++;
    }

    if (timeout_count >= 1000) {
        fprintf(stderr, "Error: HX711 timeout waiting for data line to go low\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(hx711_sck_gpio, 1);
        gpioDelay(1); // 1 us delay
        data = data << 1;
        if (gpioRead(hx711_data_gpio)) {
            data++;
        }
        gpioWrite(hx711_sck_gpio, 0);
        gpioDelay(1); // 1 us delay
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(hx711_sck_gpio, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(hx711_sck_gpio, 0);
    gpioDelay(1); // 1 us delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Calibration function
double calibrate_weight(double raw_value, double known_weight) {
    return raw_value * calibration_factor;
}

// Map weight to pulse width
int map_weight_to_pulse_width(double target_weight) {
    // Assuming a linear relationship between weight and pulse width
    // Adjust these values based on your servo's characteristics
    double min_weight = 0.0; // Minimum weight to dispense
    double max_weight = 100.0; // Maximum weight to dispense

    if (target_weight < min_weight) {
        target_weight = min_weight;
    } else if (target_weight > max_weight) {
        target_weight = max_weight;
    }

    double pulse_width = servo_min_pulse_width + (target_weight / max_weight) * (servo_max_pulse_width - servo_min_pulse_width);
    return (int)pulse_width;
}

// Dispense function
int dispense(double target_weight) {
    int pulse_width = map_weight_to_pulse_width(target_weight);
    char json_payload[256];
    snprintf(json_payload, sizeof(json_payload), "{\"target_weight\": %.2f, \"pulse_width\": %d}", target_weight, pulse_width);

    // Simulate API call
    printf("Simulating API call to %s with payload: %s\n", api_endpoint, json_payload);

    // Simulate network delay
    sleep(1); // 1 second delay

    // Simulate API response
    printf("Simulating API response: Dispense successful\n");

    return 0; // Indicate success
}

// Log event function
int log_event(double target_weight, double actual_weight, const char *error_message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    json_t *root = json_object();
    json_object_set_new(root, "timestamp", json_string(timestamp));
    json_object_set_new(root, "target_weight", json_real(target_weight));
    json_object_set_new(root, "actual_weight", json_real(actual_weight));
    json_object_set_new(root, "error_message", json_string(error_message));

    char *json_string = json_dumps(root, JSON_REAL_PRECISION(2));
    if (json_string == NULL) {
        fprintf(stderr, "Error: Failed to serialize JSON\n");
        json_decref(root);
        return -1;
    }

    fprintf(log_file, "%s\n", json_string);
    fflush(log_file);

    json_decref(root);
    free(json_string);

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Setup function
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Read configuration
    if (read_config() != 0) {
        fprintf(stderr, "Error: Failed to read configuration\n");
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen("dispensing_log.json", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return -1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Close socket
    if (client_socket != -1) {
        close(client_socket);
    }
    if (socket_fd != -1) {
        close(socket_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    if (setup() != 0) {
        return 1;
    }

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        perror("Error creating socket");
        cleanup();
        return 1;
    }

    // Bind socket
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(12345);

    if (bind(socket_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Error binding socket");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(socket_fd, 3) < 0) {
        perror("Error listening on socket");
        cleanup();
        return 1;
    }

    printf("Listening on port 12345...\n");

    while (!terminate) {
        // Accept connection
        struct sockaddr_in client_address;
        int client_address_len = sizeof(client_address);
        client_socket = accept(socket_fd, (struct sockaddr *)&client_address, (socklen_t *)&client_address_len);
        if (client_socket < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        // Receive target weight
        char buffer[256];
        ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            perror("Error receiving data");
            close(client_socket);
            client_socket = -1;
            continue;
        }
        buffer[bytes_received] = '\0';
        double target_weight = strtod(buffer, NULL);
        if (errno == ERANGE) {
            fprintf(stderr, "Error: Target weight out of range\n");
            log_event(target_weight, 0.0, "Target weight out of range");
            close(client_socket);
            client_socket = -1;
            continue;
        }

        printf("Received target weight: %.2f grams\n", target_weight);

        // Dispense
        if (dispense(target_weight) != 0) {
            fprintf(stderr, "Error: Dispense failed\n");
            log_event(target_weight, 0.0, "Dispense failed");
        } else {
            // Read actual weight
            int raw_value = read_hx711();
            if (raw_value == -1) {
                fprintf(stderr, "Error: Failed to read HX711 value\n");
                log_event(target_weight, 0.0, "Failed to read HX711 value");
            } else {
                double actual_weight = calibrate_weight(raw_value, 0.0); // Calibrate with a known weight of 0
                printf("Actual weight: %.2f grams\n", actual_weight);

                // Log event
                log_event(target_weight, actual_weight, NULL);

                // Send actual weight back to client
                char response[256];
                snprintf(response, sizeof(response), "%.2f", actual_weight);
                send(client_socket, response, strlen(response), 0);
                printf("Sent actual weight: %.2f grams\n", actual_weight);
            }
        }

        // Close connection
        close(client_socket);
        client_socket = -1;
    }

    cleanup();
    return 0;
}

int read_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open config file %s, using default values\n", CONFIG_FILE);
        return 0;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') {
            continue;
        }

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            // Remove leading/trailing whitespace
            while (*key == ' ') key++;
            while (*value == ' ') value++;
            char *end = value + strlen(value) - 1;
            while (end > value && *end == ' ') end--;
            *(end + 1) = 0;

            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = strtod(value, NULL);
            } else if (strcmp(key, "servo_min_pulse_width") == 0) {
                servo_min_pulse_width = atoi(value);
            } else if (strcmp(key, "servo_max_pulse_width") == 0) {
                servo_max_pulse_width = atoi(value);
            } else if (strcmp(key, "api_endpoint") == 0) {
                api_endpoint = strdup(value); // Duplicate the string to avoid issues with const char*
            } else if (strcmp(key, "api_timeout") == 0) {
                api_timeout = atoi(value);
            } else if (strcmp(key, "hx711_data_gpio") == 0) {
                hx711_data_gpio = atoi(value);
            } else if (strcmp(key, "hx711_sck_gpio") == 0) {
                hx711_sck_gpio = atoi(value);
            } else {
                fprintf(stderr, "Warning: Unknown configuration parameter: %s\n", key);
            }
        }
    }

    fclose(fp);
    return 0;
}

