#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17

static volatile int running = 1;
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile int debounce_interval_ms = 50;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(RELAY_GPIO, 0); // Turn relay OFF
    gpioTerminate(); // Release pigpio resources
    exit(0);
}

// Function to log relay state changes with timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_interval_ms = atoi(optarg);
                if (debounce_interval_ms <= 0) {
                    fprintf(stderr, "Error: Invalid debounce interval. Using default value (50ms).\n");
                    debounce_interval_ms = 50;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d milliseconds]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Set initial relay state to OFF
    gpioWrite(RELAY_GPIO, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Relay control program started. Debounce interval: %d ms\n", debounce_interval_ms);

    int last_touch_state = gpioRead(TOUCH_SENSOR_GPIO);
    int current_touch_state;
    int touch_detected = 0;

    while (running) {
        current_touch_state = gpioRead(TOUCH_SENSOR_GPIO);

        if (current_touch_state != last_touch_state) {
            if (current_touch_state == 1 && last_touch_state == 0) {
                // Rising edge detected
                touch_detected = 1;
            }
            last_touch_state = current_touch_state;
        }

        if (touch_detected) {
            // Toggle relay state
            relay_state = !relay_state;
            gpioWrite(RELAY_GPIO, relay_state);
            log_relay_state(relay_state);
            touch_detected = 0; // Reset touch detection
            gpioDelay(debounce_interval_ms * 1000); // Debounce
        }

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY_GPIO, 0); // Turn relay OFF
    gpioTerminate(); // Release pigpio resources

    return 0;
}

