#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_GPIO 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180

static volatile int running = 1;
static struct termios original_termios;
static int pigpio_state;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Function to set the servo pulse width
int set_servo_pulse_width(int gpio, int pulse_width) {
    int result = gpioServo(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate pulse width from angle
int calculate_pulse_width(int angle) {
    return (int)(500 + (angle * (2000.0 / 180.0)));
}

// Function to clamp angle to the valid range
int clamp_angle(int angle) {
    if (angle < MIN_ANGLE) {
        return MIN_ANGLE;
    } else if (angle > MAX_ANGLE) {
        return MAX_ANGLE;
    } else {
        return angle;
    }
}

// Function to read a single character from the terminal in raw mode
int read_key() {
    struct termios new_termios;
    int c;

    // Save the original terminal settings
    tcgetattr(STDIN_FILENO, &original_termios);
    new_termios = original_termios;

    // Configure the terminal for raw input
    new_termios.c_lflag &= ~(ICANON | ECHO);
    new_termios.c_cc[VMIN] = 0;  // Read non-blocking
    new_termios.c_cc[VTIME] = 0; // No timeout

    // Apply the new terminal settings
    tcsetattr(STDIN_FILENO, TCSANOW, &new_termios);

    // Read a single character
    c = getchar();

    // Restore the original terminal settings
    tcsetattr(STDIN_FILENO, TCSANOW, &original_termios);

    return c;
}

int main() {
    int angle = 90;
    int pulse_width;
    int key;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_state = 1; // Indicate pigpio is initialized

    // Set GPIO18 as output
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_GPIO, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Servo control program. Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");

    while (running) {
        // Read key input
        key = read_key();

        // Process key input
        switch (key) {
            case '+':
                angle += 10;
                break;
            case '-':
                angle -= 10;
                break;
            case 'q':
                running = 0;
                break;
            default:
                // Ignore other keys
                break;
        }

        // Clamp the angle
        angle = clamp_angle(angle);

        // Calculate pulse width
        pulse_width = calculate_pulse_width(angle);

        // Set servo pulse width
        if (set_servo_pulse_width(SERVO_GPIO, pulse_width) != 0) {
            running = 0; // Exit on error
        }

        // Print the current angle
        printf("Angle: %d\n", angle);

        // Delay to avoid overwhelming the servo
        usleep(100000); // 100ms
    }

    // Stop PWM pulses
    gpioServo(SERVO_GPIO, 0);

    // Restore terminal settings
    tcsetattr(STDIN_FILENO, TCSANOW, &original_termios);

    // Terminate pigpio
    if (pigpio_state) {
        gpioTerminate();
    }

    printf("Program terminated.\n");
    return 0;
}

