    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Servo control program. Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");

    while (running) {
        // Read key input
        key = read_key();

        // Process key input
        switch (key) {
            case '+':
                angle += 10;
                break;
            case '-':
                angle -= 10;
                break;
            case 'q':
                running = 0;
                break;
            default:
                // Ignore other keys
                break;
        }

        // Clamp the angle
        angle = clamp_angle(angle);

        // Calculate pulse width
        pulse_width = calculate_pulse_width(angle);

        // Set servo pulse width
        if (set_servo_pulse_width(SERVO_GPIO, pulse_width) != 0) {
            running = 0; // Exit on error
        }

        // Print the current angle
        printf("Angle: %d\n", angle);

        // Delay to avoid overwhelming the servo
        usleep(100000); // 100ms
    }

    // Stop PWM pulses
    gpioServo(SERVO_GPIO, 0);

    // Restore terminal settings
    tcsetattr(STDIN_FILENO, TCSANOW, &original_termios);

    // Terminate pigpio
    if (pigpio_state) {
        gpioTerminate();
    }

    printf("Program terminated.\n");
    return 0;
}

