#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define LOG_FILE "motor_rpm.log"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, stopping...\n", signal);
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to debounce the sensor reading
int debounce_sensor() {
    int reading = read_sensor();
    gpioDelay(DEBOUNCE_MS * 1000); // Convert ms to microseconds
    return read_sensor();
}

// Function to get the current timestamp in ISO 8601 format
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

// Function to calculate RPM
double calculate_rpm(long long pulse_count, double elapsed_time) {
    return (double)pulse_count / elapsed_time * 60.0;
}

// Function to log the RPM data to a file
int log_rpm_data(double rpm) {
    char timestamp[21];
    get_iso8601_timestamp(timestamp);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to print the current RPM to stdout
void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    long long pulse_count = 0;
    struct timespec start_time, current_time;
    double elapsed_time;
    double rpm;

    // Main loop
    while (program_running) {
        // Reset pulse count and start time
        pulse_count = 0;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds

        // Get the current time
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        // Calculate elapsed time
        elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        // Calculate RPM
        rpm = calculate_rpm(pulse_count, elapsed_time);

        // Log the RPM data
        if (log_rpm_data(rpm) != 0) {
            fprintf(stderr, "Error logging RPM data\n");
        }

        // Print the RPM to stdout
        print_rpm(rpm);
    }

    // Clean up
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

