#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define POLL_INTERVAL_MS 50
#define MAX_TOUCH_DURATION_S 10

// Global variables
volatile sig_atomic_t terminate = 0;
int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int read_touch_sensor();
int control_relay(int state);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error writing to relay pin.\n");
        return -1;
    }
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    control_relay(0); // Turn off the relay
    gpioTerminate();   // Terminate pigpio
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting touch sensor pin mode.\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting relay pin mode.\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor and relay control program started.\n");

    time_t touch_start_time = 0;
    int touch_detected = 0;

    // Main loop
    while (!terminate) {
        int touch_value = read_touch_sensor();

        if (touch_value == 1) {
            if (!touch_detected) {
                touch_detected = 1;
                touch_start_time = time(NULL);
            }

            if (time(NULL) - touch_start_time >= MAX_TOUCH_DURATION_S) {
                printf("Touch duration exceeded. Turning relay OFF.\n");
                control_relay(0);
                relay_state = 0;
                touch_detected = 0; // Reset touch detection
            }
        } else {
            touch_detected = 0; // Reset touch detection
        }

        if (touch_value == 1 && !touch_detected) {
            // Rising edge detected
            relay_state = !relay_state;
            if (control_relay(relay_state) != 0) {
                fprintf(stderr, "Error controlling relay.\n");
                terminate = 1; // Exit on error
            }
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

