#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define constants
#define PWM_FREQUENCY 1000  // Hz
#define PWM_RANGE 255
#define Kp 1.0
#define FLOW_SENSOR_PULSES_PER_LITER 4500.0 // Example value, adjust based on datasheet
#define TARGET_FLOW_RATE_MIN 0.0
#define TARGET_FLOW_RATE_MAX 100.0

// Global variables
volatile int flow_count = 0;
FILE *log_file = NULL;
double target_flow_rate = 0.0;
int running = 1;

// Function prototypes
int initialize_gpio();
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_flow_rate();
int calculate_pwm_duty_cycle(double flow_rate, double target_flow_rate);
int set_valve_position(int duty_cycle);
int log_data(double flow_rate, int valve_position);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[]);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE);

    gpioWrite(VALVE_ENABLE_PIN, 1); // Enable the valve

    return 0;
}

// Interrupt service routine for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge
        flow_count++;
    }
}

// Function to calculate flow rate (L/min)
double calculate_flow_rate() {
    double flow_rate = (double)flow_count / FLOW_SENSOR_PULSES_PER_LITER * 60.0; // Convert pulses to L/min
    flow_count = 0; // Reset the count
    return flow_rate;
}

// Function to calculate PWM duty cycle using proportional control
int calculate_pwm_duty_cycle(double flow_rate, double target_flow_rate) {
    double error = target_flow_rate - flow_rate;
    double pwm_value = Kp * error;

    // Clamp the PWM value to the valid range
    if (pwm_value < 0) {
        pwm_value = 0;
    } else if (pwm_value > PWM_RANGE) {
        pwm_value = PWM_RANGE;
    }

    return (int)pwm_value;
}

// Function to set the valve position using PWM
int set_valve_position(int duty_cycle) {
    gpioPWM(VALVE_PWM_PIN, duty_cycle);
    return 0;
}

// Function to log data to a CSV file
int log_data(double flow_rate, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "-t") != 0) {
        fprintf(stderr, "Invalid argument format. Use -t <target_flow_rate>\n");
        return 1;
    }

    char *endptr;
    target_flow_rate = strtod(argv[2], &endptr);

    if (*endptr != '\0' || target_flow_rate < TARGET_FLOW_RATE_MIN || target_flow_rate > TARGET_FLOW_RATE_MAX) {
        fprintf(stderr, "Invalid target flow rate. Must be a number between %.2f and %.2f\n", TARGET_FLOW_RATE_MIN, TARGET_FLOW_RATE_MAX);
        return 1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (parse_arguments(argc, argv) != 0) {
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Flow control system started. Target flow rate: %.2f L/min\n", target_flow_rate);

    // Main loop
    while (running) {
        // Calculate flow rate
        double flow_rate = calculate_flow_rate();

        // Calculate PWM duty cycle
        int pwm_duty_cycle = calculate_pwm_duty_cycle(flow_rate, target_flow_rate);

        // Set valve position
        set_valve_position(pwm_duty_cycle);

        // Log data
        log_data(flow_rate, pwm_duty_cycle);

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Graceful shutdown
    printf("Shutting down...\n");
    set_valve_position(0); // Set valve to 0%
    gpioWrite(VALVE_ENABLE_PIN, 0); // Disable the valve
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

