    if (*endptr != '\0' || target_flow_rate < TARGET_FLOW_RATE_MIN || target_flow_rate > TARGET_FLOW_RATE_MAX) {
        fprintf(stderr, "Invalid target flow rate. Must be a number between %.2f and %.2f\n", TARGET_FLOW_RATE_MIN, TARGET_FLOW_RATE_MAX);
        return 1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (parse_arguments(argc, argv) != 0) {
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Flow control system started. Target flow rate: %.2f L/min\n", target_flow_rate);

    // Main loop
    while (running) {
        // Calculate flow rate
        double flow_rate = calculate_flow_rate();

        // Calculate PWM duty cycle
        int pwm_duty_cycle = calculate_pwm_duty_cycle(flow_rate, target_flow_rate);

        // Set valve position
        set_valve_position(pwm_duty_cycle);

        // Log data
        log_data(flow_rate, pwm_duty_cycle);

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Graceful shutdown
    printf("Shutting down...\n");
    set_valve_position(0); // Set valve to 0%
    gpioWrite(VALVE_ENABLE_PIN, 0); // Disable the valve
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

