                button_pressed = 1;
                button_debounce = 1; // Start debounce timer
                log_event("Button Pressed", "Button pressed.");
            } else {
                button_debounce = 0; // Reset debounce timer
            }
        } else {
            button_pressed = 0; // Reset button press flag
        }

        // Check for button press with valid tag
        if (button_pressed && button_debounce == 0) {
            if (read_rfid_tag(tag) == 0 && validate_tag(tag)) {
                disengage_locks();
                button_pressed = 0; // Reset button press flag
            } else {
                log_event("Button Press Without Valid Tag", "Button pressed without a valid RFID tag.");
                button_pressed = 0; // Reset button press flag
            }
        }

        gpioDelay(100); // Small delay to reduce CPU usage
    }

    return 0;
}

