#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Motor 1 GPIOs
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2 GPIOs
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1 GPIOs
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2 GPIOs
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID parameters
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Target speed (RPM)
#define TARGET_SPEED 60.0

// Sample time (ms)
#define SAMPLE_TIME 100

// PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Global variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
void motor1_forward(int speed);
void motor1_backward(int speed);
void motor1_stop();
void motor2_forward(int speed);
void motor2_backward(int speed);
void motor2_stop();
int read_encoder1();
int read_encoder2();
double calculate_rpm(int encoder_count);
double pid_control(double current_speed);
void log_data(double rpm1, double rpm2, double p, double i, double d, double output);
void *encoder1_thread(void *arg);
void *encoder2_thread(void *arg);

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d\n", signal);
    motor1_stop();
    motor2_stop();
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Motor control functions
void motor1_forward(int speed) {
    gpioWrite(MOTOR1_IN1, 1);
    gpioWrite(MOTOR1_IN2, 0);
    gpioPWM(MOTOR1_ENA, speed);
}

void motor1_backward(int speed) {
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 1);
    gpioPWM(MOTOR1_ENA, speed);
}

void motor1_stop() {
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioPWM(MOTOR1_ENA, 0);
}

void motor2_forward(int speed) {
    gpioWrite(MOTOR2_IN3, 1);
    gpioWrite(MOTOR2_IN4, 0);
    gpioPWM(MOTOR2_ENB, speed);
}

void motor2_backward(int speed) {
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 1);
    gpioPWM(MOTOR2_ENB, speed);
}

void motor2_stop() {
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
    gpioPWM(MOTOR2_ENB, 0);
}

// Encoder reading functions
int read_encoder1() {
    pthread_mutex_lock(&encoder1_mutex);
    int count = encoder1_count;
    pthread_mutex_unlock(&encoder1_mutex);
    return count;
}

int read_encoder2() {
    pthread_mutex_lock(&encoder2_mutex);
    int count = encoder2_count;
    pthread_mutex_unlock(&encoder2_mutex);
    return count;
}

// RPM calculation function
double calculate_rpm(int encoder_count) {
    // Assuming 1 pulse per revolution
    return (double)encoder_count / (double)SAMPLE_TIME * 60000.0; // Convert to RPM
}

// PID control function
double pid_control(double current_speed) {
    static double integral = 0.0;
    static double previous_error = 0.0;

    double error = TARGET_SPEED - current_speed;
    integral += error * (double)SAMPLE_TIME / 1000.0; // Integrate error over time
    double derivative = (error - previous_error) / (double)SAMPLE_TIME / 1000.0; // Differentiate error

    double output = KP * error + KI * integral + KD * derivative;

    previous_error = error;

    // Limit the output to the range 0-255
    if (output < 0) output = 0;
    if (output > 255) output = 255;

    return output;
}

// Logging function
void log_data(double rpm1, double rpm2, double p, double i, double d, double output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, rpm1, rpm2, p, i, d, output);
    fflush(log_file);
}

// Encoder thread functions
void *encoder1_thread(void *arg) {
    int last_state = 0;
    while (1) {
        int current_state = gpioRead(ENCODER1_A);
        int b_state = gpioRead(ENCODER1_B);

        if (current_state != last_state) {
            if (current_state == 1 && b_state == 0) {
                pthread_mutex_lock(&encoder1_mutex);
                encoder1_count++;
                pthread_mutex_unlock(&encoder1_mutex);
            } else if (current_state == 1 && b_state == 1) {
                pthread_mutex_lock(&encoder1_mutex);
                encoder1_count--;
                pthread_mutex_unlock(&encoder1_mutex);
            }
        }
        last_state = current_state;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    return NULL;
}

void *encoder2_thread(void *arg) {
    int last_state = 0;
    while (1) {
        int current_state = gpioRead(ENCODER2_A);
        int b_state = gpioRead(ENCODER2_B);

        if (current_state != last_state) {
            if (current_state == 1 && b_state == 0) {
                pthread_mutex_lock(&encoder2_mutex);
                encoder2_count++;
                pthread_mutex_unlock(&encoder2_mutex);
            } else if (current_state == 1 && b_state == 1) {
                pthread_mutex_lock(&encoder2_mutex);
                encoder2_count--;
                pthread_mutex_unlock(&encoder2_mutex);
            }
        }
        last_state = current_state;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    return NULL;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    // Set pull-up/down resistors (optional, adjust as needed)
    gpioSetPullUpDown(ENCODER1_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP);

    // Open log file
    log_file = fopen("motor_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Write header row
    fprintf(log_file, "Timestamp,RPM1,RPM2,P,I,D,PID_Output\n");

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create encoder threads
    pthread_t encoder1_thread_id, encoder2_thread_id;
    if (pthread_create(&encoder1_thread_id, NULL, encoder1_thread, NULL) != 0) {
        fprintf(stderr, "Error creating encoder 1 thread\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (pthread_create(&encoder2_thread_id, NULL, encoder2_thread, NULL) != 0) {
        fprintf(stderr, "Error creating encoder 2 thread\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read encoder counts
        int encoder1 = read_encoder1();
        int encoder2 = read_encoder2();

        // Calculate RPM
        double rpm1 = calculate_rpm(encoder1);
        double rpm2 = calculate_rpm(encoder2);

        // Reset encoder counts for the next sample
        pthread_mutex_lock(&encoder1_mutex);
        encoder1_count = 0;
        pthread_mutex_unlock(&encoder1_mutex);
        pthread_mutex_lock(&encoder2_mutex);
        encoder2_count = 0;
        pthread_mutex_unlock(&encoder2_mutex);

        // Calculate PID output
        double pid_output = pid_control((rpm1 + rpm2) / 2.0); // Average RPM for PID

        // Apply PID output to motors (assuming both motors should have the same speed)
        motor1_forward((int)pid_output);
        motor2_forward((int)pid_output);

        // Log data
        log_data(rpm1, rpm2, 0, 0, 0, pid_output); // Placeholder for P, I, D values

        // Delay for the sample time
        gpioDelay(SAMPLE_TIME);
    }

    // Cleanup (should not reach here under normal circumstances due to signal handling)
    pthread_join(encoder1_thread_id, NULL);
    pthread_join(encoder2_thread_id, NULL);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

