#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32

// GPIO pin for relay control
#define RELAY_PIN 17

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void control_relay(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// MPR121 initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x80) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Configure filtering parameters
    if (i2cWriteByteData(i2c_handle, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_FDLR, 0x00) < 0) return -1;

    if (i2cWriteByteData(i2c_handle, MPR121_MHDF, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NHDF, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NCLF, 0x0E) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_FDLF, 0x00) < 0) return -1;

    // Set touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x30) < 0) return -1; // Touch threshold
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x10) < 0) return -1; // Release threshold
    }

    // Enable electrodes (all 12)
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x3F) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }

    // Set operation mode to run mode
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG2, 0x24) < 0) return -1;

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
}

// Function to log relay state with timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s Relay: %s\n", timestamp, state ? "HIGH" : "LOW");
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t touch_status;
    int relay_state = 0; // 0 = LOW, 1 = HIGH

    // Main loop
    while (!terminate) {
        // Read touch status
        if (read_touch_status(&touch_status) == 0) {
            // Check if any electrode is touched
            int any_touched = (touch_status != 0);

            // Control relay based on touch status
            if (any_touched && !relay_state) {
                control_relay(1);
                relay_state = 1;
                log_relay_state(1);
            } else if (!any_touched && relay_state) {
                control_relay(0);
                relay_state = 0;
                log_relay_state(0);
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup
    control_relay(0); // Turn off relay
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

