// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define valve activation times (in milliseconds)
#define VALVE1_DURATION 500
#define VALVE2_DURATION 1000

// Define valve pause times (in seconds)
#define VALVE1_PAUSE 5
#define VALVE2_PAUSE 10

// Define the log file name
#define LOG_FILE "valve_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
void valve_on(int gpio);
void valve_off(int gpio);
void log_event(const char *event);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Function to turn a valve on (set GPIO HIGH)
void valve_on(int gpio) {
    gpioWrite(gpio, 1); // Set GPIO HIGH
}

// Function to turn a valve off (set GPIO LOW)
void valve_off(int gpio) {
    gpioWrite(gpio, 0); // Set GPIO LOW
}

// Function to log an event with an ISO 8601 timestamp
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        program_running = 0;
    }
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(VALVE1_GPIO, PI_OUTPUT);
    gpioSetMode(VALVE2_GPIO, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to cleanup GPIO and close the log file
void cleanup_gpio() {
    printf("Cleaning up GPIO and closing log file...\n");
    valve_off(VALVE1_GPIO);
    valve_off(VALVE2_GPIO);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    printf("Water distribution system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate Valve 1
        valve_on(VALVE1_GPIO);
        log_event("Valve 1 activated");
        gpioDelay(VALVE1_DURATION * 1000); // pigpioDelay takes microseconds
        valve_off(VALVE1_GPIO);
        log_event("Valve 1 deactivated");
        gpioDelay(VALVE1_PAUSE * 1000000); // pigpioDelay takes microseconds

        // Activate Valve 2
        valve_on(VALVE2_GPIO);
        log_event("Valve 2 activated");
        gpioDelay(VALVE2_DURATION * 1000); // pigpioDelay takes microseconds
        valve_off(VALVE2_GPIO);
        log_event("Valve 2 deactivated");
        gpioDelay(VALVE2_PAUSE * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Water distribution system stopped.\n");
    return 0;
}

