#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_ECR 0x5E

// GPIO pin for relay control
#define RELAY_PIN 17

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
int relay_control(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize the MPR121
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode\n");
        return -1;
    }

    // Configure touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, 40) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, 20) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Set filter and charge time
    if (i2cWriteByteData(i2c_handle, MPR121_MHDR, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set MHD_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NHDR, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set NHD_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NCLR, 0x0E) < 0) {
        fprintf(stderr, "Error: Failed to set NCL_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FDLR, 0x04) < 0) {
        fprintf(stderr, "Error: Failed to set FDL_R\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MPR121_MHDF, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set MHD_F\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NHDF, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set NHD_F\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NCLF, 0x0E) < 0) {
        fprintf(stderr, "Error: Failed to set NCL_F\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FDLF, 0x04) < 0) {
        fprintf(stderr, "Error: Failed to set FDL_F\n");
        return -1;
    }

    // Set electrode current
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to set electrode current\n");
        return -1;
    }

    // Run mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to run mode\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(uint16_t *touch_status) {
    char buf[2];

    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to control the relay
int relay_control(int state) {
    gpioWrite(RELAY_PIN, state);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;
    int relay_state = 0;

    // Main loop
    while (!terminate) {
        // Read touch status
        if (mpr121_read_touch_status(&touch_status) == 0) {
            // Check if any electrode is touched
            if (touch_status > 0) {
                // Toggle relay state
                relay_state = !relay_state;
                relay_control(relay_state);

                // Print relay toggle status
                printf("Relay toggled to state: %d\n", relay_state);
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

