// Define GPIO pins
#define PIR_PIN 17
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION 500 // milliseconds
#define RATE_LIMIT_DURATION 2000 // milliseconds
#define POLLING_INTERVAL 50 // milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static unsigned long last_motion_time = 0;
static unsigned long last_unlock_time = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void unlock_door();
void log_event(const char *event_type, const char *message);
void cleanup();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off initially

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Function to unlock the door
void unlock_door() {
    gpioWrite(RELAY_PIN, 1); // Activate relay
    log_event("unlock", "Door unlocked");
    gpioDelay(UNLOCK_DURATION);
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
}

// Function to log events to a file
void log_event(const char *event_type, const char *message) {
    if (log_file == NULL) return; // Check if log file is open

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to clean up resources
void cleanup() {
    printf("Cleaning up and exiting...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
