    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            unsigned long current_time = gpioTick();

            if (current_time - last_motion_time > RATE_LIMIT_DURATION) {
                unlock_door();
                last_unlock_time = current_time;
                last_motion_time = current_time;
            } else {
                log_event("rate_limit", "Rate limit exceeded");
            }
        }

        gpioDelay(POLLING_INTERVAL);
    }

    cleanup();
    return 0;
}

