#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Global flag for graceful shutdown
volatile sig_atomic_t shutdown_flag = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal) {
    shutdown_flag = 1;
    printf("\nCaught SIGINT, shutting down gracefully...\n");
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to generate a random haptic feedback pattern
int generate_pattern(int *motor1_duties, int *motor2_duties, int *durations) {
