#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Default calibration values
#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0

// Weight threshold in kg
#define WEIGHT_THRESHOLD 10.0

// Calibration file name
#define CALIBRATION_FILE "calibration.txt"

// Log file name
#define LOG_FILE "weight_log.txt"

// Number of readings for startup calibration
#define STARTUP_CALIBRATION_READINGS 100

// Timeout for HX711 reading in milliseconds
#define HX711_TIMEOUT 500

// Global variables
double scale = DEFAULT_SCALE;
double offset = DEFAULT_OFFSET;
FILE *log_file = NULL;
FILE *calibration_file = NULL;
int running = 1;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value);
void control_solenoid(double weight);
void log_data(double weight, int raw_value);
void load_calibration();
void save_calibration();
void startup_calibration();
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < HX711_TIMEOUT) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= HX711_TIMEOUT) {
        fprintf(stderr, "Error: HX711 timeout waiting for data line to go low.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Small delay
    }

    // Pulse the clock pin 25th time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value) {
    return ((double)raw_value - offset) / scale;
}

// Function to control the solenoid
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Engage solenoid
        printf("Solenoid engaged!\n");
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Disengage solenoid
        printf("Solenoid disengaged.\n");
    }
}

// Function to log data to file
void log_data(double weight, int raw_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Weight: %.2f kg, Raw: %d\n", timestamp, weight, raw_value);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to load calibration data from file
void load_calibration() {
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        printf("Calibration file not found. Using default values.\n");
        scale = DEFAULT_SCALE;
        offset = DEFAULT_OFFSET;
        return;
    }

    if (fscanf(calibration_file, "%lf %lf", &scale, &offset) != 2) {
        printf("Invalid calibration file format. Using default values.\n");
        scale = DEFAULT_SCALE;
        offset = DEFAULT_OFFSET;
        fclose(calibration_file);
        return;
    }

    fclose(calibration_file);
    printf("Calibration values loaded: scale=%.2f, offset=%.2f\n", scale, offset);
}

// Function to save calibration data to file
void save_calibration() {
    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error opening calibration file for writing!\n");
        return;
    }

    fprintf(calibration_file, "%lf %lf\n", scale, offset);
    fclose(calibration_file);
    printf("Calibration values saved: scale=%.2f, offset=%.2f\n", scale, offset);
}

// Function to perform startup calibration
void startup_calibration() {
    printf("Starting startup calibration...\n");
    double sum = 0.0;
    for (int i = 0; i < STARTUP_CALIBRATION_READINGS; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading HX711 during startup calibration.\n");
            return;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    offset = sum / STARTUP_CALIBRATION_READINGS;
    printf("Startup calibration complete. Offset: %.2f\n", offset);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    load_calibration();

    // Perform startup calibration
    startup_calibration();

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Weight-triggered solenoid lock control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = calculate_weight(raw_value);
            log_data(weight, raw_value);
            control_solenoid(weight);
        } else {
            fprintf(stderr, "Error reading HX711, skipping iteration.\n");
        }

        gpioDelay(500); // Read every 500 ms
    }

    // Clean up
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is disengaged
    fclose(log_file);
    gpioTerminate();

    return 0;
}

