#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define motor control parameters
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 2
#define MOTOR_STOP 0

#define MOTOR_SPEED 150 // Duty cycle (0-255)
#define MOTOR_FREQUENCY 1000 // PWM frequency (Hz)
#define MOTOR_DURATION 5 // Motor duration (seconds)

// Define rain detection parameters
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50
#define RAIN_THRESHOLD 3

// Define logging parameters
#define LOG_FILE "/var/log/window_control.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int direction);
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(MOTOR_PWM_PIN, MOTOR_FREQUENCY);
    gpioSetPWMrange(MOTOR_PWM_PIN, 255);

    return 0;
}

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int reading = gpioRead(RAIN_SENSOR_PIN);
        if (reading == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    }
    return (low_count >= RAIN_THRESHOLD) ? 1 : 0; // 1 for rain, 0 for no rain
}

// Function to control the motor
int control_motor(int direction) {
    if (direction == MOTOR_FORWARD) {
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, MOTOR_SPEED);
        syslog(LOG_INFO, "Motor started in forward direction");
    } else if (direction == MOTOR_REVERSE) {
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 1);
        gpioPWM(MOTOR_PWM_PIN, MOTOR_SPEED);
        syslog(LOG_INFO, "Motor started in reverse direction");
    } else if (direction == MOTOR_STOP) {
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, 0);
        syslog(LOG_INFO, "Motor stopped");
    } else {
        syslog(LOG_ERR, "Invalid motor direction");
        return -1;
    }
    return 0;
}

// Function to log events to syslog
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);
    syslog(LOG_INFO, "%s", log_message);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, stopping motor and cleaning up...");
    running = 0;
    control_motor(MOTOR_STOP);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    closelog();
}

int main() {
    // Open syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        // Read rain sensor
        int rain_detected = read_rain_sensor();

        if (rain_detected) {
            log_event("Rain detected, closing window");

            // Control motor to close window
            if (control_motor(MOTOR_FORWARD) != 0) {
                syslog(LOG_ERR, "Failed to control motor");
            }

            // Wait for motor duration
            gpioDelay(MOTOR_DURATION * 1000000); // Convert seconds to microseconds

            // Stop motor
            if (control_motor(MOTOR_STOP) != 0) {
                syslog(LOG_ERR, "Failed to stop motor");
            }

            log_event("Window closed");

            // Wait before next check
            gpioDelay(60 * 1000000); // 60 seconds
            gpioDelay(60 * 1000000); // 60 seconds
        } else {
            // Wait before next check
            gpioDelay(60 * 1000000); // 60 seconds
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

