#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17

// Define constants
#define LOCK_DURATION 5 // seconds
#define WEIGHT_THRESHOLD 100 // grams
#define NUM_CALIBRATION_READINGS 10

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static double calibration_factor = 1.0; // Initial calibration factor

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value);
void activate_solenoid();
void deactivate_solenoid();
void log_event(const char *message);
void signal_handler(int signal);
int calibrate_hx711();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
    deactivate_solenoid();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read data from HX711
int read_hx711() {
    int i;
    int data = 0;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for the data line to go low
    int timeout = 1000; // Timeout after 1000 attempts
    while (gpioRead(HX711_DT) == 1 && timeout > 0) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout--;
    }

    if (timeout == 0) {
        log_event("HX711 read timeout");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Pulse the clock pin 1 more time to set the gain to 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Function to activate the solenoid lock
void activate_solenoid() {
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
    log_event("Solenoid activated");
}

// Function to deactivate the solenoid lock
void deactivate_solenoid() {
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
    log_event("Solenoid deactivated");
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Function to calibrate the HX711
int calibrate_hx711() {
    double known_weight;
    int raw_value;
    double sum = 0.0;
    int i;

    printf("Place a known weight on the load cell (in grams): ");
    if (scanf("%lf", &known_weight) != 1) {
        log_event("Invalid input for known weight");
        return -1;
    }

    printf("Taking %d readings...\n", NUM_CALIBRATION_READINGS);
    for (i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            log_event("Error reading HX711 during calibration");
            return -1;
        }
        sum += raw_value;
        gpioDelay(100); // Small delay between readings
    }

    calibration_factor = sum / known_weight;
    printf("Calibration factor: %lf\n", calibration_factor);
    log_event("Calibration complete");

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("stock_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Calibrate the HX711
    if (calibrate_hx711() != 0) {
        log_event("HX711 calibration failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    log_event("Program started");

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            log_event("Error reading HX711");
        } else {
            double weight = calculate_weight(raw_value);
            char message[100];
            snprintf(message, sizeof(message), "Weight: %.2f g", weight);
            log_event(message);

            if (weight < WEIGHT_THRESHOLD) {
                activate_solenoid();
                gpioDelay(LOCK_DURATION * 1000); // Wait for lock duration
                deactivate_solenoid();
            }
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_solenoid();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

