#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0
#define SOLENOID_ACTIVATION_TIME 5 // seconds
#define TIMEOUT_DURATION 100 // milliseconds

// Global variables
static volatile int running = 1;
static double calibration_factor = 1.0; // Default calibration factor
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
double read_hx711();
double calibrate_sensor();
void control_solenoid(int activate);
void log_weight(double weight);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO pin configurations
typedef struct {
    int data_pin;
    int clock_pin;
    int solenoid_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off

    return 0;
}

// Function to read data from HX711
double read_hx711() {
    int i;
    unsigned long data = 0;

    // Wait for data line to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < TIMEOUT_DURATION) {
        gpioDelay(1); // 1 ms delay
        timeout++;
    }

    if (timeout >= TIMEOUT_DURATION) {
        fprintf(stderr, "HX711 Timeout Error\n");
        return -1.0; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // 1 us delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // 1 us delay
    }

    // Pulse the clock pin 25th time to set the HX711 for the next reading
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1 us delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return (double)data;
}

// Function to calibrate the sensor
double calibrate_sensor() {
    double known_weight;
    double raw_value;

    printf("Place a known weight on the load cell (in kg): ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Invalid input for known weight\n");
        return -1.0;
    }

    printf("Reading raw value...\n");
    raw_value = read_hx711();

    if (raw_value < 0) {
        fprintf(stderr, "Error reading raw value during calibration\n");
        return -1.0;
    }

    calibration_factor = raw_value / known_weight;
    printf("Calibration factor: %lf\n", calibration_factor);

    // Save calibration factor to file
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing\n");
        return -1.0;
    }

    if (fprintf(fp, "%lf", calibration_factor) < 0) {
        fprintf(stderr, "Error writing calibration factor to file\n");
        fclose(fp);
        return -1.0;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing calibration file\n");
        return -1.0;
    }

    return calibration_factor;
}

// Function to control the solenoid
void control_solenoid(int activate) {
    if (activate) {
        gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
        printf("Solenoid activated\n");
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
        printf("Solenoid deactivated\n");
    }
}

// Function to log weight to file
void log_weight(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return;
    }

    if (fprintf(log_file, "%s, Weight: %.2f kg\n", timestamp, weight) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }

    fflush(log_file); // Ensure data is written to disk
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    control_solenoid(0); // Ensure solenoid is off
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    double weight;
    double calibrated_weight;
    int solenoid_activated = 0;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(SECURITY_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Read calibration factor from file
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        printf("Calibration file not found. Please calibrate the sensor.\n");
        if (calibrate_sensor() < 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            cleanup();
            return 1;
        }
    } else {
        if (fscanf(fp, "%lf", &calibration_factor) != 1) {
            fprintf(stderr, "Error reading calibration factor from file. Using default.\n");
            fclose(fp);
            if (calibrate_sensor() < 0) {
                fprintf(stderr, "Calibration failed. Exiting.\n");
                cleanup();
                return 1;
            }
        } else {
            printf("Calibration factor loaded from file: %lf\n", calibration_factor);
            fclose(fp);
        }
    }

    printf("Monitoring weight...\n");

    while (running) {
        weight = read_hx711();

        if (weight < 0) {
            fprintf(stderr, "Error reading weight. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        calibrated_weight = weight * calibration_factor;

        printf("Raw: %.2f, Weight: %.2f kg\n", weight, calibrated_weight);

        if (calibrated_weight > WEIGHT_THRESHOLD && !solenoid_activated) {
            control_solenoid(1);
            log_weight(calibrated_weight);
            solenoid_activated = 1;
            gpioDelay(SOLENOID_ACTIVATION_TIME * 1000); // Wait for solenoid activation time
            control_solenoid(0);
            solenoid_activated = 0;
        }

        gpioDelay(100); // Sample every 100 ms
    }

    cleanup();
    return 0;
}

