// Define GPIO pins
#define SENSOR_PIN 16
#define RELAY_PIN 20

// Define log file name
#define LOG_FILE "relay_events.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
void control_relay(int state);
int log_event(int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-up/down resistor for sensor pin (optional, depends on sensor module)
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Read sensor value
int read_sensor() {
    int sensor_value = gpioRead(SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor value\n");
        return -1; // Indicate error
    }
    return sensor_value;
}

// Control relay state
void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
}

// Log event to file
int log_event(int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Relay: %s\n", timestamp, relay_state ? "ON" : "OFF");
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return 1;
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    int relay_state = 0; // Initial relay state (OFF)
    int last_sensor_value = 1; // Initialize to a value that ensures relay toggles on first read

    printf("Monitoring sensor... Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (sensor_value == 0 && last_sensor_value == 1) { // Obstacle detected (LOW) and last reading was clear
            relay_state = !relay_state; // Toggle relay state
            control_relay(relay_state);
            log_event(relay_state);
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
        }

        last_sensor_value = sensor_value;
        gpioDelay(50); // Delay to avoid excessive CPU usage
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(0); // Turn off relay
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

