#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "Signal received, shutting down...\n");
}

int read_config(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading from config file or file is empty\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *token = strtok(line, "=");
    if (token == NULL || strcmp(token, "duration") != 0) {
        fprintf(stderr, "Invalid config file format\n");
        return -1;
    }

    token = strtok(NULL, "=");
    if (token == NULL) {
        fprintf(stderr, "Invalid config file format\n");
        return -1;
    }

    char *endptr;
    *duration = strtol(token, &endptr, 10);

    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Invalid duration value in config file\n");
        return -1;
    }

    if (*duration < 1 || *duration > 3600) {
        fprintf(stderr, "Duration out of range (1-3600 seconds)\n");
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int duration;
    if (read_config(CONFIG_FILE, &duration) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Watering duration: %d seconds\n", duration);

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure valve is off initially

    while (!terminate) {
        if (gpioWrite(GPIO_PIN, 1) != 0) {
            fprintf(stderr, "Error setting GPIO high\n");
            break;
        }
        printf("Valve ON\n");
        sleep(duration);
        if (gpioWrite(GPIO_PIN, 0) != 0) {
            fprintf(stderr, "Error setting GPIO low\n");
            break;
        }
        printf("Valve OFF\n");
        sleep(60); // Wait 60 seconds before next cycle
    }

    // Ensure valve is off before exiting
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return 0;
}

