void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    control_motors(0, 0); // Stop motors
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

