    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        if (read_sensors(&left, &middle, &right) != 0) {
            fprintf(stderr, "Error reading sensors!\n");
            continue; // Continue to the next iteration
        }

        // Determine motor speeds based on sensor values
        if (middle == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left == 0) {
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (right == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else {
            left_speed = 0;
            right_speed = 0;
        }

        // Control motors
        control_motors(left_speed, right_speed);

        // Log data
        log_data(left, middle, right, left_speed, right_speed);

        // Delay for 10ms
        gpioDelay(10000); // 10ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_motors(0, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

