#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse widths
#define SERVO_LOCK_PULSE_WIDTH 1000
#define SERVO_UNLOCK_PULSE_WIDTH 2000

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to set servo pulse width
void set_servo_pulse_width(int pulse_width) {
    gpioServo(SERVO_PIN, pulse_width);
}

// Function to read button state with debouncing
int read_button(int button_pin) {
    int button_state = gpioRead(button_pin);
    if (button_state == 0) { // Button is pressed (active low)
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        if (gpioRead(button_pin) == 0) { // Check if still pressed after delay
            return 1; // Button is pressed
        }
    }
    return 0; // Button is not pressed
}

// Function to lock the door
void lock_door() {
    set_servo_pulse_width(SERVO_LOCK_PULSE_WIDTH);
    printf("Door locked\n");
}

// Function to unlock the door
void unlock_door() {
    set_servo_pulse_width(SERVO_UNLOCK_PULSE_WIDTH);
    printf("Door unlocked\n");
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (read_button(LOCK_BUTTON_PIN)) {
            lock_door();
            gpioDelay(500000); // Small delay to prevent multiple triggers
        } else if (read_button(UNLOCK_BUTTON_PIN)) {
            unlock_door();
            gpioDelay(500000); // Small delay to prevent multiple triggers
        }
        gpioDelay(10000); // Small delay to reduce CPU usage
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

