#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define motor activation durations (in milliseconds)
#define MOTOR1_DURATION 200
#define MOTOR2_DURATION 300

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating program...\n", signal);
    program_running = 0;
}

// Function to activate a motor for a specified duration
int activate_motor(int gpio_pin, int duration_ms) {
    if (gpio_pin < 0 || duration_ms <= 0) {
        fprintf(stderr, "Error: Invalid GPIO pin or duration.\n");
        return -1;
    }

    // Activate the motor
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to write HIGH to GPIO %d.\n", gpio_pin);
        return -1;
    }

    // Wait for the specified duration
    gpioDelay(duration_ms * 1000); // pigpioDelay takes microseconds

    // Deactivate the motor
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to write LOW to GPIO %d.\n", gpio_pin);
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Error: Failed to register signal handler");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Main loop to control the vibration motors
    while (program_running) {
        // Activate motor 1
        if (activate_motor(MOTOR1_GPIO, MOTOR1_DURATION) != 0) {
            fprintf(stderr, "Error: Failed to activate motor 1\n");
            break; // Exit the loop on error
        }

        // Activate motor 2
        if (activate_motor(MOTOR2_GPIO, MOTOR2_DURATION) != 0) {
            fprintf(stderr, "Error: Failed to activate motor 2\n");
            break; // Exit the loop on error
        }
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

