#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <zmq.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ address
#define ZMQ_ADDRESS "tcp://*:5555"

// Define message format
#define MESSAGE_FORMAT "{\"topic\": \"SOUND_ALERTS\", \"message\": \"Sound detected\"}"

// Global variables
static volatile int running = 1;
static void *context = NULL;
static void *publisher = NULL;
static void *subscriber = NULL;
static int mode = -1; // -1 means not set, 0 for sound_sensor, 1 for alarm_node

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int initialize_zmq_publisher();
int initialize_zmq_subscriber();
void cleanup();
void sound_sensor_mode();
void alarm_node_mode();

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    return 0;
}

// Initialize ZeroMQ publisher
int initialize_zmq_publisher() {
    context = zmq_ctx_new();
    if (!context) {
        perror("zmq_ctx_new failed");
        return -1;
    }

    publisher = zmq_socket(context, ZMQ_PUB);
    if (!publisher) {
        perror("zmq_socket failed");
        zmq_ctx_destroy(context);
        return -1;
    }

    int rc = zmq_bind(publisher, ZMQ_ADDRESS);
    if (rc != 0) {
        perror("zmq_bind failed");
        zmq_close(publisher);
        zmq_ctx_destroy(context);
        return -1;
    }

    printf("Publisher bound to %s\n", ZMQ_ADDRESS);
    return 0;
}

// Initialize ZeroMQ subscriber
int initialize_zmq_subscriber() {
    context = zmq_ctx_new();
    if (!context) {
        perror("zmq_ctx_new failed");
        return -1;
    }

    subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        perror("zmq_socket failed");
        zmq_ctx_destroy(context);
        return -1;
    }

    int rc = zmq_connect(subscriber, "tcp://localhost:5555");
    if (rc != 0) {
        perror("zmq_connect failed");
        zmq_close(subscriber);
        zmq_ctx_destroy(context);
        return -1;
    }

    rc = zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, "SOUND_ALERTS", strlen("SOUND_ALERTS"));
    if (rc != 0) {
        perror("zmq_setsockopt failed");
        zmq_close(subscriber);
        zmq_ctx_destroy(context);
        return -1;
    }

    printf("Subscriber connected to tcp://localhost:5555\n");
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    // GPIO cleanup
    gpioWrite(ALARM_LED_PIN, 0); // Turn off LED
    gpioTerminate();

    // ZeroMQ cleanup
    if (publisher) {
        zmq_close(publisher);
    }
    if (subscriber) {
        zmq_close(subscriber);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }

    printf("Cleanup complete.\n");
}

// Sound sensor mode
void sound_sensor_mode() {
    printf("Running in sound sensor mode...\n");

    while (running) {
        int sound_detected = gpioRead(SOUND_SENSOR_PIN) == 0; // Active low

        if (sound_detected) {
            printf("Sound detected!\n");

            // Publish alert
            void *message = zmq_msg_init_size(NULL, strlen(MESSAGE_FORMAT));
            if (!message) {
                perror("zmq_msg_init_size failed");
                running = 0; // Exit loop on error
                continue;
            }
            memcpy(zmq_msg_data(message), MESSAGE_FORMAT, strlen(MESSAGE_FORMAT));

            int rc = zmq_msg_send(message, publisher, 0);
            if (rc == -1) {
                perror("zmq_msg_send failed");
                running = 0; // Exit loop on error
            }

            zmq_msg_close(message);

            // Debounce: Wait for a short period to avoid multiple triggers
            gpioDelay(100000); // 100ms
        }

        gpioDelay(10000); // 10ms delay
    }
}

// Alarm node mode
void alarm_node_mode() {
    printf("Running in alarm node mode...\n");

    while (running) {
        zmq_msg_t message;
        zmq_msg_init(&message);

        int rc = zmq_msg_recv(&message, subscriber, 0);
        if (rc == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, continue the loop
                zmq_msg_close(&message);
                continue;
            }
            perror("zmq_msg_recv failed");
            zmq_msg_close(&message);
            running = 0; // Exit loop on error
            continue;
        }

        char *message_data = zmq_msg_data(&message);
        size_t message_size = zmq_msg_size(&message);

        // Validate message format (basic check)
        if (message_size > strlen(MESSAGE_FORMAT)) {
            fprintf(stderr, "Invalid message size: %zd\n", message_size);
            zmq_msg_close(&message);
            continue;
        }

        if (strncmp(message_data, MESSAGE_FORMAT, message_size) != 0) {
            fprintf(stderr, "Invalid message content: %s\n", message_data);
            zmq_msg_close(&message);
            continue;
        }

        printf("Received alert: %s\n", message_data);

        // Activate alarm LED
        gpioWrite(ALARM_LED_PIN, 1);
        gpioDelay(1000000); // 1 second
        gpioWrite(ALARM_LED_PIN, 0);

        zmq_msg_close(&message);
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  <mode> can be 'sound_sensor' or 'alarm_node'\n");
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        mode = 0;
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        mode = 1;
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize ZeroMQ
    if (mode == 0) {
        if (initialize_zmq_publisher() != 0) {
            cleanup();
            return 1;
        }
    } else {
        if (initialize_zmq_subscriber() != 0) {
            cleanup();
            return 1;
        }
    }

    // Run in the selected mode
    if (mode == 0) {
        sound_sensor_mode();
    } else {
        alarm_node_mode();
    }

    // Cleanup resources
    cleanup();

    return 0;
}

