#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x24
#define BH1750_ADDR_3 0x25
#define BH1750_ADDR_4 0x26
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SLEEP_MS 1000 // 1 second

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_fd;
int udp_socket;

// Function prototypes
int init_i2c(int bus);
int read_bh1750(int fd, int addr);
float convert_to_lux(unsigned int raw_value);
char* format_data(int sensor_id, float lux);
void send_udp_packet(const char* data);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Initialize I2C
int init_i2c(int bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Read data from BH1750 sensor
int read_bh1750(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    unsigned char config[1] = {CONTINUOUS_HIGH_RES_MODE};
    if (write(fd, config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(180000); // Wait for measurement (180ms)

    unsigned char buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return raw_value;
}

// Convert raw value to lux
float convert_to_lux(unsigned int raw_value) {
    return (float)raw_value / 1.2;
}

// Format data as CSV string
char* format_data(int sensor_id, float lux) {
    char* data = (char*)malloc(50 * sizeof(char)); // Allocate memory for the string
    if (data == NULL) {
        perror("Failed to allocate memory");
        return NULL;
    }
    snprintf(data, 50, "%d,%.2f", sensor_id, lux);
    return data;
}

// Send UDP packet
void send_udp_packet(const char* data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(udp_socket, data, strlen(data), 0, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP packet");
    }
}

// Cleanup resources
void cleanup() {
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    if (udp_socket > 0) {
        close(udp_socket);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating socket");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char data_buffer[200] = ""; // Buffer to hold the CSV data
        int sensor_addresses[] = {BH1750_ADDR_1, BH1750_ADDR_2, BH1750_ADDR_3, BH1750_ADDR_4};
        int num_sensors = sizeof(sensor_addresses) / sizeof(sensor_addresses[0]);

        for (int i = 0; i < num_sensors; i++) {
            int raw_value = read_bh1750(i2c_fd, sensor_addresses[i]);
            if (raw_value < 0) {
                char* nan_data = format_data(i + 1, NAN);
                strcat(data_buffer, nan_data);
                free(nan_data);
            } else {
                float lux = convert_to_lux(raw_value);
                char* sensor_data = format_data(i + 1, lux);
                strcat(data_buffer, sensor_data);
                free(sensor_data);
            }

            if (i < num_sensors - 1) {
                strcat(data_buffer, ";");
            }
        }

        send_udp_packet(data_buffer);
        usleep(SLEEP_MS * 1000); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

