#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define AWM7300V_ADDR 0x28
#define FLOW_SCALE_FACTOR 0.01
#define LOG_FILE "airflow_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write(int fd, unsigned char *data, int len);
int i2c_read(int fd, unsigned char *data, int len);
int read_sensor_data(int fd, unsigned char *data);
float convert_to_slpm(unsigned int raw_flow);
int log_data(float flow_rate);
void signal_handler(int signal);

// I2C write function
int i2c_write(int fd, unsigned char *data, int len) {
    int result = i2cWriteDevice(fd, data, len);
