#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Register Addresses
#define AS7341_ID 0x00
#define AS7341_ENABLE 0x77
#define AS7341_CFG0 0x70
#define AS7341_CFG1 0x71
#define AS7341_CFG2 0x72
#define AS7341_CFG3 0x73
#define AS7341_CFG4 0x74
#define AS7341_CFG5 0x75
#define AS7341_CFG6 0x76
#define AS7341_ATIME 0x7A
#define AS7341_AGAIN 0x7B
#define AS7341_F1DATAH 0x94
#define AS7341_F1DATAL 0x95
#define AS7341_F2DATAH 0x96
#define AS7341_F2DATAL 0x97
#define AS7341_F3DATAH 0x98
#define AS7341_F3DATAL 0x99
#define AS7341_F4DATAH 0x9A
#define AS7341_F4DATAL 0x9B
#define AS7341_F5DATAH 0x9C
#define AS7341_F5DATAL 0x9D
#define AS7341_F6DATAH 0x9E
#define AS7341_F6DATAL 0x9F
#define AS7341_F7DATAH 0xA0
#define AS7341_F7DATAL 0xA1
#define AS7341_F8DATAH 0xA2
#define AS7341_F8DATAL 0xA3
#define AS7341_CLEARDATAH 0xA6
#define AS7341_CLEARDATAL 0xA7
#define AS7341_NIRDATAH 0xAA
#define AS7341_NIRDATAL 0xAB

// AS7341 Identification Value
#define AS7341_ID_VALUE 0x15

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_spectral_data(uint16_t *data);
float calculate_lux(const uint16_t *data);
int log_data(const uint16_t *data, float lux);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the AS7341 sensor
int initialize_sensor() {
    int status;

    // Verify sensor ID
    status = i2cReadByteData(i2c_handle, AS7341_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor ID: %s\n", strerror(errno));
        return -1;
    }
    if ((status & 0xFF) != AS7341_ID_VALUE) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X (expected 0x%02X)\n", status & 0xFF, AS7341_ID_VALUE);
        return -1;
    }
    printf("AS7341 sensor ID verified: 0x%02X\n", status & 0xFF);

    // Power on the sensor
    status = i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x01); // PON bit
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register (PON): %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Wait for power-on

    // Configure the sensor
    status = i2cWriteByteData(i2c_handle, AS7341_CFG0, 0x00); // Default value
    if (status < 0) {
        fprintf(stderr, "Error writing to CFG0 register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, AS7341_CFG1, 0x00); // Default value
    if (status < 0) {
        fprintf(stderr, "Error writing to CFG1 register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, AS7341_CFG2, 0x00); // Default value
    if (status < 0) {
        fprintf(stderr, "Error writing to CFG2 register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, AS7341_CFG3, 0x00); // Default value
    if (status < 0) {
        fprintf(stderr, "Error writing to CFG3 register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, AS7341_CFG4, 0x00); // Default value
    if (status < 0) {
        fprintf(stderr, "Error writing to CFG4 register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, AS7341_CFG5, 0x00); // Default value
    if (status < 0) {
        fprintf(stderr, "Error writing to CFG5 register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, AS7341_CFG6, 0x03); // Enable all channels
    if (status < 0) {
        fprintf(stderr, "Error writing to CFG6 register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, AS7341_ATIME, 0x64); // Integration time
    if (status < 0) {
        fprintf(stderr, "Error writing to ATIME register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, AS7341_AGAIN, 0x03); // Gain
    if (status < 0) {
        fprintf(stderr, "Error writing to AGAIN register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03); // Enable spectral measurement
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register (SP_EN): %s\n", strerror(errno));
        return -1;
    }

    printf("AS7341 sensor initialized successfully.\n");
    return 0;
}

// Reads spectral data from the AS7341 sensor
int read_spectral_data(uint16_t *data) {
    int status;
    uint8_t buffer[20]; // Buffer to hold all 10 channel readings (2 bytes each)

    // Read all 10 channel data in one go
    status = i2cReadI2CBlockData(i2c_handle, AS7341_F1DATAH, (char *)buffer, 20);
    if (status < 0) {
        fprintf(stderr, "Error reading spectral data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for each channel
    data[0] = (buffer[1] << 8) | buffer[0]; // F1
    data[1] = (buffer[3] << 8) | buffer[2]; // F2
    data[2] = (buffer[5] << 8) | buffer[4]; // F3
    data[3] = (buffer[7] << 8) | buffer[6]; // F4
    data[4] = (buffer[9] << 8) | buffer[8]; // F5
    data[5] = (buffer[11] << 8) | buffer[10]; // F6
    data[6] = (buffer[13] << 8) | buffer[12]; // F7
    data[7] = (buffer[15] << 8) | buffer[14]; // F8
    data[8] = (buffer[17] << 8) | buffer[16]; // Clear
    data[9] = (buffer[19] << 8) | buffer[18]; // NIR

    return 0;
}

// Calculates a simplified lux approximation from the spectral data
float calculate_lux(const uint16_t *data) {
    // Simplified lux approximation formula (example)
    float lux = 0.1 * (data[0] + data[1] + data[2] + data[3] + data[4] + data[5] + data[6] + data[7]) +
                0.2 * (data[8] + data[9]);
    return lux;
}

// Logs the spectral data and lux value to a CSV file
int log_data(const uint16_t *data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp, data[0], data[1], data[2], data[3], data[4], data[5], data[6], data[7], data[8], data[9], lux);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    uint16_t spectral_data[10];
    float lux;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, AS7341_ADDR, 0); // Bus 1, address 0x39, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read spectral data
        if (read_spectral_data(spectral_data) == 0) {
            // Calculate lux
            lux = calculate_lux(spectral_data);

            // Log data
            if (log_data(spectral_data, lux) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading spectral data, retrying...\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Close resources before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

