        fprintf(stderr, "Error writing to ENABLE register (SP_EN): %s\n", strerror(errno));
        return -1;
    }

    printf("AS7341 sensor initialized successfully.\n");
    return 0;
}

// Reads spectral data from the AS7341 sensor
int read_spectral_data(uint16_t *data) {
    int status;
    uint8_t buffer[20]; // Buffer to hold all 10 channel readings (2 bytes each)

    // Read all 10 channel data in one go
    status = i2cReadI2CBlockData(i2c_handle, AS7341_F1DATAH, (char *)buffer, 20);
    if (status < 0) {
        fprintf(stderr, "Error reading spectral data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for each channel
    data[0] = (buffer[1] << 8) | buffer[0]; // F1
    data[1] = (buffer[3] << 8) | buffer[2]; // F2
    data[2] = (buffer[5] << 8) | buffer[4]; // F3
    data[3] = (buffer[7] << 8) | buffer[6]; // F4
    data[4] = (buffer[9] << 8) | buffer[8]; // F5
    data[5] = (buffer[11] << 8) | buffer[10]; // F6
    data[6] = (buffer[13] << 8) | buffer[12]; // F7
    data[7] = (buffer[15] << 8) | buffer[14]; // F8
    data[8] = (buffer[17] << 8) | buffer[16]; // Clear
    data[9] = (buffer[19] << 8) | buffer[18]; // NIR

    return 0;
}

// Calculates a simplified lux approximation from the spectral data
float calculate_lux(const uint16_t *data) {
    // Simplified lux approximation formula (example)
    float lux = 0.1 * (data[0] + data[1] + data[2] + data[3] + data[4] + data[5] + data[6] + data[7]) +
                0.2 * (data[8] + data[9]);
    return lux;
}

// Logs the spectral data and lux value to a CSV file
int log_data(const uint16_t *data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp, data[0], data[1], data[2], data[3], data[4], data[5], data[6], data[7], data[8], data[9], lux);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    uint16_t spectral_data[10];
    float lux;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, AS7341_ADDR, 0); // Bus 1, address 0x39, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read spectral data
        if (read_spectral_data(spectral_data) == 0) {
            // Calculate lux
            lux = calculate_lux(spectral_data);

            // Log data
            if (log_data(spectral_data, lux) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading spectral data, retrying...\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Close resources before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

