#define DEFAULT_SAMPLING_INTERVAL 1
#define DEFAULT_OUTPUT_FILENAME "seismic_data.csv"
#define DEFAULT_ERROR_LOG_FILENAME "seismic_error.log"
#define I2C_BUS 1
#define RETRY_COUNT 3
#define BACKOFF_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *data_file = NULL;
FILE *error_file = NULL;
int i2c_address = DEFAULT_I2C_ADDRESS;
int sampling_interval = DEFAULT_SAMPLING_INTERVAL;
char *output_filename = DEFAULT_OUTPUT_FILENAME;
char *error_log_filename = DEFAULT_ERROR_LOG_FILENAME;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int address);
int read_sensor_data(int handle, int16_t *x, int16_t *y, int16_t *z);
double convert_to_g(int16_t raw_value);
char* get_timestamp(char* timestamp_str, size_t timestamp_str_size);
