int log_error(FILE *fp, char *timestamp, char *message);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    double x_g;
    double y_g;
    double z_g;
} sensor_data_t;

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = strtol(optarg, NULL, 0);
                if (sampling_interval <= 0) {
                    fprintf(stderr, "Error: Sampling interval must be a positive integer.\n");
                    return 1;
                }
                break;
            case 'f':
                output_filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sampling_interval] [-f output_filename]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) != 0) {
        fprintf(stderr, "Error: I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open data file
    data_file = fopen(output_filename, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error: Could not open data file %s\n", output_filename);
        cleanup();
        return 1;
    }

    // Open error log file
    error_file = fopen(error_log_filename, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Error: Could not open error log file %s\n", error_log_filename);
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t x_raw, y_raw, z_raw;
