            // Get timestamp
            get_timestamp(timestamp, sizeof(timestamp));

            // Log data
            if (log_data(data_file, timestamp, sensor_data.x_g, sensor_data.y_g, sensor_data.z_g) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            // Log error
            get_timestamp(timestamp, sizeof(timestamp));
            log_error(error_file, timestamp, "Failed to read sensor data");
        }

        // Wait for the next sample
        sleep(sampling_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(I2C_BUS, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2cReadDevice(handle, buf, 6);
        if (result == 6) {
            *x = (int16_t)((buf[0] << 8) | buf[1]);
            *y = (int16_t)((buf[2] << 8) | buf[3]);
            *z = (int16_t)((buf[4] << 8) | buf[5]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C read failed (result = %d), retrying...\n", result);
            log_error(error_file, "Timestamp", "I2C read failed");
            gpioDelay(BACKOFF_DELAY_MS * 1000); // Convert ms to microseconds
            retries--;
        }
    }

    fprintf(stderr, "Error: I2C read failed after multiple retries\n");
    return 1; // Failure
}

// Convert raw value to g
double convert_to_g(int16_t raw_value) {
    // Assuming a sensitivity of 1g/1000 (adjust as needed)
    return (double)raw_value / 1000.0;
}

// Get timestamp
char* get_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = localtime(&timer);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%d %H:%M:%S", tm_info);
    return timestamp_str;
}

// Log data to CSV file
int log_data(FILE *fp, char *timestamp, double x_g, double y_g, double z_g) {
    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x_g, y_g, z_g) < 0) {
        fprintf(stderr, "Error: Failed to write to data file\n");
        return 1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Log error to error log file
int log_error(FILE *fp, char *timestamp, char *message) {
    if (fprintf(fp, "%s,Error: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error: Failed to write to error log file\n");
        return 1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fflush(data_file);
        fclose(data_file);
    }
    if (error_file != NULL) {
        fflush(error_file);
        fclose(error_file);
    }
    gpioTerminate();
}

