#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

int i2c_fd = -1;
int udp_socket = -1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to read data from the BH1750 sensor
int read_bh1750(unsigned char *data) {
    unsigned char config = CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(200000); // Wait for measurement (at least 180ms)

    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// Function to convert raw data to lux value
float convert_to_lux(unsigned char *data) {
    unsigned int raw_value = (data[0] << 8) | data[1];
    return (float)raw_value / 1.2;
}

// Function to send data via UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    char buffer[32];
    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);

    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP multicast");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating socket");
        close(i2c_fd);
        return 1;
    }

    // Set multicast TTL
    int ttl = TTL;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL");
        close(i2c_fd);
        close(udp_socket);
        return 1;
    }

    unsigned char data[2];
    float lux_value;

    while (1) {
        if (read_bh1750(data) == 0) {
            lux_value = convert_to_lux(data);
            if (send_udp_multicast(lux_value) != 0) {
                fprintf(stderr, "Failed to send UDP multicast.\n");
            }
        } else {
            fprintf(stderr, "Failed to read BH1750 sensor.\n");
        }

        sleep(1);
    }

    // Cleanup (should not reach here in normal execution due to signal handler)
    close(i2c_fd);
    close(udp_socket);

    return 0;
}

