#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define UART device and baud rate
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

// Function prototypes
int read_sensor(int gpio_pin);
int log_sensor_data(int left, int middle, int right);
int send_emergency_stop(int uart_fd);
void signal_handler(int signal);

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log sensor data with a timestamp
int log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: Left=%d, Middle=%d, Right=%d\n", timestamp, left, middle, right);
    return 0;
}

// Function to send an emergency stop message over UART
int send_emergency_stop(int uart_fd) {
    if (uart_fd != -1) {
        if (write(uart_fd, "EMERGENCY STOP!\n", strlen("EMERGENCY STOP!\n")) < 0) {
            perror("Error writing to UART");
        }
    } else {
        fprintf(stderr, "UART not initialized, cannot send emergency stop.\n");
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close UART port
    if (uart_fd != -1) {
        close(uart_fd);
    }

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Open UART port
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Error opening UART");
        fprintf(stderr, "UART initialization failed, continuing without UART.\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_sensor = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor = read_sensor(RIGHT_SENSOR_PIN);

        // Log sensor data
        log_sensor_data(left_sensor, middle_sensor, right_sensor);

        // Check for emergency stop condition
        if (left_sensor == 0 && middle_sensor == 0 && right_sensor == 0) {
            send_emergency_stop(uart_fd);
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    if (uart_fd != -1) {
        close(uart_fd);
    }
    gpioTerminate();

    return 0;
}

